local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["npc:falla-sagewind"] = {fx={["53e3505a"]={q="Auf wessen Seite steht Falla Weisenwind?",a="Falla Weisenwind ist eine Tauren, die kein Banner einer Fraktion trägt. In den rauen Höhen des Brachlands stationiert, hilft sie Reisenden sowohl der Horde als auch der Allianz, die die unnatürlichen Verderbnisse untersuchen, die sich von den Höhlen des Wehklagens aus ausbreiten, und unterstützt diejenigen, die daran arbeiten, das Land zu reinigen.",al={"falla weisenwind fraktion","ist falla weisenwind bei der horde","wem dient falla weisenwind"}},["709098cb"]={q="Was will Falla Weisenwind?",a="Falla Weisenwind versucht, die wachsende Verderbnis zu verstehen und zu bekämpfen, die aus den Höhlen des Wehklagens sickert. Wenn Abenteurer ihr seltsame Relikte bringen, wie etwa glühende Scherben, die von den Kreaturen im Inneren stammen, arbeitet sie daran, den Albtraum aufzudecken, der in den unterirdischen Quellen Wurzeln schlägt.",al={"falla weisenwind ziele","was will falla","falla weisenwind aufgabe"}},["26262d64"]={q="Warum ist Falla Weisenwind hier?",a="Falla Weisenwind hält Wache auf einem Bergrücken südwestlich des Wegekreuzes, von wo aus sie die blühende Oase und den nahe gelegenen Eingang zu den Höhlen des Wehklagens überblickt. Von diesem erhöhten Aussichtspunkt aus überwacht sie die Verderbnis des Landes und leitet Reisende an, die dunkle Relikte finden, die mit den gestörten Träumern in der Tiefe in Verbindung stehen.",al={"warum ist falla weisenwind im brachland","warum ist falla auf dem berg"}}}}
P.entries["npc:fallen-hero-of-the-horde"] = {n="Gefallener Held der Horde",s="Der Gefallene Held der Horde ist der verweilende Geist eines Orc-Kriegers, der an der südlichen Straße aus den Sümpfen des Elends Wache hält. Gebunden an Reue und Schande, warnt er vorbeiziehende Reisende vor den Schrecken, die sie in den Verwüsteten Landen erwarten, und sucht nach Helden, die bereit sind, seine gequälten Soldaten aus dämonischer Knechtschaft zu befreien.",h="Der Gefallene Held der Horde ist der verweilende Geist eines Orc-Kriegers, der an der südlichen Straße aus...",kw={"allistarj","gefallener held der horde","grol the destroyer","lieutenant kirith","razelikh the defiler","sevine","steine der bindung","swamp talker"},ang={["class:Warrior"]="Als gefallener Krieger von hohem Ansehen berührt seine spektrale Verbundenheit besonders kämpferische Abenteurer, die den Schmerz verstehen, zu überleben, während die eigenen Kameraden gefallen sind.",["faction:Horde"]="Der Held verkörpert die Qual eines Kriegers, dessen Ehre durch dämonische Grausamkeit geraubt wurde, und appelliert an Abenteurer der Horde, seine verlorene Truppe zu rächen und den Makel der Niederlage von ihrem Erbe zu tilgen."},sec={{t="Ein tragisches Kommando",b="Zu Lebzeiten war dieser Krieger ein gefeierter Champion, der mit einem handverlesenen Regiment von Soldaten entsandt wurde, um die Verwüsteten Lande zu erkunden und über die Präsenz der Brennenden Legion zu berichten. Seine Depesche kam nie an; der nach Norden gen Steinard geschickte Bote geriet in einen Hinterhalt und wurde vom Swamp Talker und seinen Murlocs erschlagen. Ohne Befehle oder Verstärkung gestrandet, marschierte der Kommandant mit seinen Soldaten schließlich nach Süden in die zerrütteten Einöden, um sich der wachsenden Finsternis zu stellen. Es war eine verhängnisvolle Fehleinschätzung. Von dämonischen Kräften überwältigt, wurde seine Armee zersprengt, gefangen genommen und durch die Hand des Schreckenslords Razelikh the Defiler grauenhafter Folter ausgesetzt."},{t="Der Preis des Versagens",b="Gemeinsam mit seinem Leutnant Kirith gefangen genommen, ertrug der Kommandant brutale Folter in der Schlangenschlinge, während ihre Peiniger seinen überlebenden Männern die Seelen entrissen. Nachdem er entkommen war, nur um seinen tödlichen Wunden nahe der Sumpfgrenze zu erliegen, bleibt der Geist des Helden an die Schwelle der Verwüsteten Lande gefesselt. Seine Soldaten erlitten ein noch finstereres Schicksal: Ihre seelenlosen Hüllen wurden an mystische Steine gebunden und dienten als unsterbliche Knechte, aufgeteilt zwischen Razelikh und seinen Leutnants – Archmage Allistarj, Lady Sevine und Grol the Destroyer. Bis ihre seelenbindenden Steine zerschlagen und ihre Qualen beendet sind, kann sein rastloser Geist keinen Frieden finden."}},faq={{q="Wer war der Gefallene Held zu Lebzeiten?",a="Er war ein erfahrener Orc-Krieger, der auserwählt wurde, eine Aufklärungstruppe in die Verwüsteten Lande zu führen, um die dämonische Bedrohung einzuschätzen. Er starb an schweren Wunden, nachdem er der Folter durch Razelikh the Defiler entkommen war, wodurch sein Geist an der Straße gestrandet blieb, die aus den Sümpfen des Elends führt.",al={"identität des gefallenen helden","name des gefallenen helden","wer ist der gefallene held"}},{q="Warum spukt er an der Grenze der Verwüsteten Lande?",a="Er ist an die Schande gebunden, sein Regiment verloren und seinen Auftrag verfehlt zu haben. Er weigert sich weiterzuziehen, bis mutige Abenteurer nach Süden vordringen, um die Steine der Bindung zu zerstören, die seine Soldaten in ewiger Knechtschaft der Brennenden Legion halten.",al={"warum ist er ein geist","gefallener held geist","warum ist er hier"}},{q="Was geschah mit den Befehlen, die er nach Steinard sandte?",a="Der Späher, der seinen dringenden Bericht zurück zum Außenposten Steinard tragen sollte, wurde im Sumpf von Murlocs unter der Führung des Swamp Talkers überfallen und getötet. Da der Bericht verloren ging, traf nie Verstärkung ein, was den Helden dazu veranlasste, allein in die Verwüsteten Lande vorzurücken.",al={"verlorene befehle","was geschah mit seinen befehlen","swamp talker bote"}},{q="Was geschah mit seinem Leutnant Kirith?",a="Leutnant Kirith erlitt dämonische Experimente in der Schlangenschlinge. Seine Seele wurde verzerrt und verdreht, was seine physische Gestalt in einen monströsen Teufelsjäger verwandelte, der in den Tiefen der Höhle lauert.",al={"leutnant kirith","wer ist kirith","was geschah mit kirith"}},{q="Warum sind seine Soldaten unverwundbar?",a="Razelikh und seine Leutnants trennten die Seelen der gefangenen Soldaten von ihrem Fleisch. Ohne Seele können ihre physischen Körper nicht wahrhaftig sterben. Sie können nur befreit werden, wenn ihre Körper bis kurz vor den Zerfall geschlagen werden, wodurch die seelenbindenden Steine in der Nähe kurzzeitig anfällig für die Zerstörung werden.",al={"unverwundbare soldaten","steine der bindung","diener von razelikh"}}},fp="24,325,16.645.0,20.641.1,32.284.0,51.232.0,47.259.0,40.194.1,34.293.1"}
P.entries["npc:fandral-staghelm"] = {fx={d5bab569={q="Auf wessen Seite steht Fandral Hirschhaupt?",a="Fandral ist der Erz-Druide von Darnassus und ein Anführer innerhalb des Zirkels des Cenarius, der sich für die Kaldorei und die Allianz einsetzt. Seine Loyalität ist jedoch stark nationalistisch geprägt. Anstatt sich demütig der traditionellen Vorsicht der Ältesten des Zirkels oder der Priesterschaft von Elune zu unterwerfen, handelt Fandral streng nach dem, was er als kühnes, militaristisches Interesse des Volkes der Nachtelfen wahrnimmt.",al={"fandral hirschhaupt fraktion","wem dient fandral","fandral loyalität"}},adee2909={q="Was will Fandral Hirschhaupt?",a="Fandral wünscht sich die Wiederherstellung der Macht, der Unsterblichkeit und der territorialen Vorherrschaft der Nachtelfen. Frustriert von jahrhundertelanger passiver Isolation drängte er darauf, den Weltenbaum Teldrassil als Ersatz für Nordrassil zu pflanzen. Er stellt sich eine aggressive Nation der Kaldorei vor, die bereit ist, ihre Grenzen zu erobern, kühn durch Kalimdor zu expandieren und den verlorenen Ruhm und die Kraft ihrer alten Vergangenheit zurückzugewinnen.",al={"was ist das ziel von fandral hirschhaupt","fandral ambitionen","was will erz-druide hirschhaupt"}},["6d220bca"]={q="Warum ist Fandral Hirschhaupt in Darnassus?",a="Da Malfurion Sturmgrimm im Smaragdgrünen Traum gefangen und handlungsunfähig ist, trat Fandral als Erz-Druide an seine Stelle. Er regiert die Druiden des Zirkels des Cenarius von den Höhen der Enklave des Cenarius in Darnassus aus, herrscht an der Seite der Hohepriesterin Tyrande Wisperwind und lenkt aktiv die politische und magische Zukunft von Teldrassil.",al={"warum ist fandral in darnassus","fandral hirschhaupt standort grund","warum ist fandral hier"}},["53c16312"]={q="Warum ist Fandral Hirschhaupt berühmt?",a="Lange bevor er die Pflanzung von Teldrassil leitete, diente Fandral während des Krieges der wandelnden Dünen in Silithus als brillanter Feldkommandant der Kaldorei. Sein verheerendes taktisches Kommando gegen den insektenartigen Schwarm brachte ihm bei den Qiraji den Titel Kar'sis – die Hand der Erde – ein, die seine Wut auf dem Schlachtfeld fürchteten, bis sie die tragische Hinrichtung seines Sohnes orchestrierten.",al={"fandral berühmt","warum wird fandral gefürchtet","hand der erde fandral"}}}}
P.entries["npc:farmer-furlbrow"] = {fx={d2bcffbc={q="Auf wessen Seite steht Bauer Brauenwirbel?",a="Bauer Brauenwirbel ist ein gewöhnlicher Bauer aus Westfall, der dem Königreich Sturmwind und der Allianz treu ergeben ist. Er empfindet keine Liebe für The Defias Brotherhood, die sein Land beschlagnahmt und ihn vertrieben hat. Obwohl er verbittert über den Mangel an königlichem Schutz ist, wendet er sich dennoch an mitreisende Mitglieder der Allianz und die People's Militia, um Hilfe zu erhalten.",al={"bauer brauenwirbel fraktion","wen unterstützt brauenwirbel","ist brauenwirbel bei der allianz"}},["81475819"]={q="Was will Bauer Brauenwirbel?",a="Bauer Brauenwirbel möchte nichts weiter, als seinen kaputten Wagen zu reparieren und mit seiner Frau Verna und ihrem alten Pferd Blanchy aus Westfall zu entkommen. Da ihre Kürbisfarm von Banditen der Defias überrannt wurde, ist es seine Priorität, Vorräte zu sammeln, sein verlorenes Familienerbstück zurückzuerlangen und die gesetzlose Grenze hinter sich zu lassen.",al={"was braucht brauenwirbel","bauer brauenwirbel ziel","brauenwirbel absichten"}}}}
P.entries["npc:farmer-saldean"] = {fx={b644bbfd={q="Was möchte Bauer Saldean?",a="Saldean wünscht sich nichts sehnlicher, als sein Gehöft zu beschützen, seine Ernte einzubringen und sich gemeinsam mit seiner Frau, Salma, ein Leben aufzubauen. Da Westfall von Gesetzlosigkeit geprägt ist und von Sturmwind vernachlässigt wird, ist er darauf angewiesen, dass reisende Abenteurer die durchgedrehten mechanischen Erntemaschinen beseitigen, die auf seinen Feldern ihr Unwesen treiben, und die örtliche Volksmiliz dabei unterstützen, die Sicherheit in der Region wiederherzustellen.",al={"was möchte saldean","saldeans ziel","was möchte bauer saldean"}},["4625baa0"]={q="Mit wem ist Bauer Saldean verbunden?",a="Bauer Saldean führt sein Gehöft gemeinsam mit seiner Frau, Salma Saldean, die sich um den Haushalt und das Kochen kümmert. Er arbeitet außerdem mit Gryan Starkmantel und der Volksmiliz auf der Späherkuppe zusammen und weist fähige Recken an, ihren Kampf gegen die Gesetzlosen zu unterstützen, die die Kornkammer des Königreichs bedrohen.",al={"familie bauer saldean","mit wem ist saldean verheiratet","beziehung salma saldean"}}}}
P.entries["npc:farthing"] = {fx={["1783acb6"]={q="Warum ist Bischof Heller in der Kathedrale des Lichts?",a="Heller ist in der Kathedrale des Lichts in Sturmwind stationiert, um seine klerikalen Pflichten als Bischof zu erfüllen, Besucher zu beraten, den Priesterstand zu unterstützen und bei der Leitung kirchlicher Angelegenheiten im Auftrag der hohen Geistlichkeit zu helfen.",al={"warum ist farthing hier","warum ist farthing in sturmwind","farthings aufgabe kathedrale"}}}}
P.entries["npc:feegly-the-exiled"] = {n="Feegly der Verbannte",s="Feegly der Verbannte ist ein verstoßener Zwerg, der in der Nähe der Zwergenausgrabung bei Bael Modan im südlichen Brachland lauert. Einst als einer der besten Ausgräber der Expedition gerühmt, führte seine Obsession mit einem freigelegten Relikt dazu, dass General Twinbraid ihn verjagte.",h="Feegly der Verbannte ist ein verstoßener Zwerg, der in der Nähe der Zwergenausgrabung bei Bael Modan im...",kw={"bael modan","brachland","ausgräber","ausgrabung","verbannt","feegly","träne der monde","trogg"},ang={["faction:Horde"]="Feeglys bitterer Groll gegen die Ausgräber von Bael Modan macht ihn zu einem unerwarteten Verbündeten für Wanderer der Horde, die die Zwergenexpedition im Brachland sabotieren wollen.",["race:Dwarf"]="Für Zwerge ist Feegly eine tragische und furchterregende Warnung: ein fähiger Ausgräber, dessen Obsession mit einem ausgegrabenen Relikt ihn seinen Platz unter seinesgleichen kostete."},sec={{t="Der Ruin eines Ausgräbers",b="Vor seinem Exil galt Feegly als einer der führenden Ausgräber in Bael Modan. Die Träne der Monde war die erste große Entdeckung bei der Grabung, und Feegly beanspruchte ihre Macht für sich selbst. General Twinbraid bezeichnete den Edelstein als verflucht, sperrte ihn in Burg Bael'dun weg und vertrieb Feegly. Nun brütet er einsam vor sich hin, verzweifelt darauf bedacht, genau jenen Edelstein zurückzuerlangen, der sein Verderben besiegelt: Als er ihn schließlich wieder in Händen hält, zerbricht die Träne und er verwandelt sich in einen scheußlichen, buckligen Trogg."}},faq={{q="Wer ist Feegly der Verbannte?",a="Feegly ist ein Zwerg, ein verbannter Ausgräber der Grabungsstätte Bael Modan, der ein als die Träne der Monde bekanntes Relikt begehrt.",al={"wer ist feegly","feegly geschichte","feegly der verbannte"}},{q="Warum wurde Feegly aus Bael Modan verbannt?",a="Feegly verfiel einer Obsession für die Träne der Monde, der ersten großen Entdeckung in Bael Modan. General Twinbraid bezeichnete den Edelstein als verflucht, sperrte ihn in Burg Bael'dun weg und vertrieb Feegly.",al={"warum verbannt","was hat feegly getan","feegly verbannung"}},{q="Warum ist Feegly bereit, mit Abenteurern der Horde zu sprechen?",a="Von seinen Zwergenbrüdern verraten und verstoßen, hegt Feegly keinerlei Loyalität gegenüber der Expedition der Allianz. Er ist verzweifelt genug, um Reisende der Horde um Hilfe zu bitten, damit er das von ihm begehrte Relikt wiedererlangt.",al={"warum ist feegly freundlich zur horde","feegly horde freundlich"}},{q="Was ist die Träne der Monde?",a="Die Träne der Monde ist ein Edelstein, den die Ausgräber in Bael Modan freigelegt haben – ihre erste große Entdeckung dort. Feegly behauptet, sie habe ihm Macht verliehen, doch General Twinbraid hielt sie für verflucht und schloss sie in Burg Bael'dun ein.",al={"träne der monde","feegly edelstein","feegly artefakt"}}},fx={["21513985"]={q="Wer ist Feegly der Verbannte?",a="Feegly ist ein verbannter Zwergengräber von der Ausgrabungsstätte Bael Modan im südlichen Brachland. Er hält sich außerhalb der Ausgrabungsstätte auf und ist besessen davon, ein Relikt namens The Tear of the Moons zu bergen.",al={"wer ist feegly","feeglys identität","feeglys hintergrund"}},ed9ce58e={q="Was möchte Feegly der Verbannte?",a="Feegly sucht nach The Tear of the Moons, einem Relikt, das er wegen seiner seltsamen Macht begehrt. Er rekrutiert willige Wanderer, um es aus Burg Bael'dun zu bergen, damit er es wieder in seinen Besitz bringen kann.",al={"was möchte feegly","feeglys beweggrund","warum braucht feegly die träne"}},["7eaaafaa"]={q="Warum ist Feegly der Verbannte im Brachland?",a="Feegly hält sich in den Hügeln außerhalb von Bael Modan auf, weil General Twinbraid ihn vertrieben und The Tear of the Moons weggeschlossen hat. Verzweifelt versucht er, den Edelstein zurückzugewinnen, und bleibt daher in der Nähe seiner ehemaligen Ausgrabungsstätte.",al={"warum ist feegly hier","wo bleibt feegly","warum ist feegly außerhalb von bael modan"}},["0b854105"]={q="Mit wem ist Feegly der Verbannte verbunden?",a="Feegly ist mit der Zwergenexpedition von Bael Modan verbunden, wo er früher einer ihrer wichtigsten Gräber war, bevor er verbannt wurde. Nun von seinen Verwandten entfremdet, ist er darauf angewiesen, dass vorbeiziehende Wanderer der Horde sein Gebot gegen die Ausgrabung ausführen.",al={"feeglys verbindungen","mit wem arbeitet feegly zusammen","feeglys beziehungen"}}},fp="17,252,15.460.1,25.113.0,38.184.0,51.189.0,30.214.0"}
P.entries["npc:feero-ironhand"] = {fx={["996da789"]={q="Auf wessen Seite steht Feero Eisenhand?",a="Feero Eisenhand steht fest auf der Seite der Allianz. Er ist in Maestras Posten stationiert, einem wichtigen Nachtelfen-Außenposten entlang der westlichen Grenze des Eschentals, und unterstützt Reisende und lokale Streitkräfte gegen die Bedrohungen, die über dem uralten Wald schweben.",al={"feero eisenhand fraktion","ist feero bei der allianz","seite feero eisenhand"}},bf9a9ed2={q="Was möchte Feero Eisenhand?",a="Feero zielt darauf ab, die Verteidiger von Maestras Posten zu unterstützen und den finsteren Kult des Dunklen Strangs zu vereiteln. Gemeinsam mit Delgren der Läuterer versucht er, deren verderblichen Einfluss aus dem nördlichen Kalimdor zu tilgen und die Versorgungswege zwischen dem Eschental und der Dunkelküste aufrechtzuerhalten.",al={"ziel feero eisenhand","was möchte feero","feeros beweggrund"}}}}
P.entries["npc:fel-zerul"] = {n="Fel'zerul",s="Fel'zerul ist ein Hexenmeister der Orcs, der in Steinard in den trüben Tiefen der Sümpfe des Elends stationiert ist. Auf direkten Befehl von Kriegshäuptling Thrall untersucht er die unheilvolle Präsenz, die im versunkenen Tempel von Atal'Hakkar lauert.",h="Fel'zerul ist ein Hexenmeister der Orcs, der in Steinard in den trüben Tiefen der Sümpfe des Elends...",kw={"atal'hakkar","fel'zerul","felzerul","steinard","sümpfe des elends","thrall","hexenmeister"},ang={["class:Warlock"]="Fel'zerul steht für die offizielle Beauftragung eines Hexenmeisters durch Thrall und verdeutlicht, dass Die neue Horde gelegentlich auf Ausüber der dunklen Künste zurückgreift, um obskuren, esoterischen Bedrohungen zu begegnen.",["faction:Horde"]="In Steinard stationiert, fungiert Fel'zerul als Frühwarnspäher und stellt sicher, dass die finstere Magie, die im Sumpf schwelt, den Stützpunkt der Horde in der Region nicht unvorbereitet trifft."},sec={{t="Ein wachsames Auge auf den Versunkenen Tempel",b="Während Thralls Horde die dunklen Künste im Allgemeinen mit Misstrauen betrachtet, erkennt der Kriegshäuptling an, dass das Verständnis finsterer Mächte jene erfordert, die sie studieren. Fel'zerul wurde eigens nach Steinard entsandt, um das Verderben rund um den Tränenteich und den untergetauchten Tempel von Atal'Hakkar aufzudecken. Indem er Abenteurer anweist, Artefakte zu bergen und die verbannten Atal'ai-Trolle zu untersuchen, versucht der Hexenmeister herauszufinden, welches Unheil sich unter den trüben Wassern regt, bevor es den südlichen Außenposten der Horde bedroht."}},faq={{q="Wer ist Fel'zerul?",a="Fel'zerul ist ein Hexenmeister der Orcs, der in Steinard weilt, der Festung der Horde in den Sümpfen des Elends. Er fungiert als Ermittler, der die dunklen Rituale analysiert, die sich im nahe gelegenen Tempel von Atal'Hakkar abspielen.",al={"felzerul","wer ist fel'zerul","steinard hexenmeister"}},{q="Warum schickte Thrall einen Hexenmeister nach Steinard?",a="Kriegshäuptling Thrall entsandte Fel'zerul, weil der Umgang mit uralten Flüchen und Blutritualen Fachwissen in dunklerer Zauberei erfordert. Fel'zeruls Auftrag ist es, die beunruhigenden Entwicklungen rund um den versunkenen Tempel zu überwachen und die Interessen der Horde im Sumpf zu schützen.",al={"thrall felzerul","warum ist felzerul hier","felzerul mission"}},{q="Was untersucht Fel'zerul?",a="Fel'zerul untersucht die Atal'ai-Trolle und ihre unheiligen Riten im Tempel von Atal'Hakkar am Tränenteich. Er spannt Späher und Abenteurer ein, um Artefakte zu heben und verbannte Priester aufzuspüren, die über entscheidendes Wissen verfügen könnten.",al={"felzerul quest lore","was will felzerul","tränenteich untersuchung"}}},fp="9,228,25.509.0,17.203.0,41.259.0,32.240.0"}
P.entries["npc:felgur-twocuts"] = {n="Felgur Zweischneid",s="Felgur Zweischneid ist ein barscher orkischer Späher, der am Geistwandlerposten in Desolace stationiert ist. Er koordiniert die Bemühungen der Horde gegen die regionalen Zentaurenklans.",h="Felgur Zweischneid ist ein barscher orkischer Späher, der am Geistwandlerposten in Desolace stationiert ist.",kw={"zentaurenkopfgeld","desolace","felgur zweischneid","geistwandlerposten","horde","kolkar","ork"},ang={["faction:Horde"]="Felgur fungiert als wichtige Einsatzverbindung am Geistwandlerposten und hilft der Horde, die aggressiven Zentaurenstämme in Desolace zurückzudrängen.",["race:Orc"]="Getreu dem orkischen Pragmatismus in gefährlichen Grenzgebieten schätzt Felgur Stärke, Schnelligkeit und unmittelbare Ergebnisse mehr als müßige Konversation."},sec={{t="Ein grober Außenpostenspäher",b="Felgur Zweischneid hält inmitten der trostlosen Weiten des Geistwandlerpostens im zentralen Desolace Wache und hat wenig Geduld für Höflichkeiten. Als Vorpostenspäher der Horde beurteilt er die Bedrohungen für Reisende und Siedler, die sich westwärts durch die Berge wagen, insbesondere die lokalen Kolkar-Zentauren."},{t="Krieg gegen die Zentauren",b="Felgur weist Champions der Horde an, die lokalen Zentaurenhäuptlinge auszuschalten und Kopfgelder auf die kriegerischen Stämme auszusetzen, die drohen, die Region zu überrennen. Er ist ein zentraler Kontakt für jeden, der den Stützpunkt der Horde in Desolace sichern möchte."}},faq={{q="Wer ist Felgur Zweischneid?",a="Felgur Zweischneid ist ein orkischer Späher und Questgeber, der am Geistwandlerposten stationiert ist, dem Vorposten der Horde in Desolace.",al={"wer ist felgur zweischneid","wer ist felgur"}},{q="Wo finde ich Felgur Zweischneid?",a="Er befindet sich am Geistwandlerposten, direkt nördlich der zentralen Straße, die durch Desolace führt.",al={"ort von felgur zweischneid","wo ist felgur","wo ist felgur zweischneid"}},{q="Welche Aufgaben gibt Felgur Zweischneid?",a="Felgur rekrutiert Abenteurer der Horde, um die lokalen Kolkar-Zentauren anzugreifen, Khan Dez'hepah zu jagen und Kopfgelder auf feindselige Zentauren zu sammeln.",al={"felgur quests","was will felgur"}},{q="Warum ist Felgur so schroff zu Besuchern?",a="Desolace ist ein gefährliches und unerbittliches Ödland, das von feindseligen Zentaurenklans umgeben ist. An einem isolierten Posten stationiert, hat Felgur keine Zeit für untätiges Geplänkel und konzentriert sich lieber streng auf das Überleben und seine militärische Pflicht.",al={"warum ist felgur unhöflich","fass dich kurz felgur"}}},fx={f5a09a6e={q="Auf wessen Seite steht Felgur Zweischneid?",a="Felgur ist ein stolzes Mitglied der Horde, das weit draußen an der Grenze stationiert ist, um ihre Interessen voranzubringen und ihre Lager gegen regionale Bedrohungen zu verteidigen.",al={"felgur zweischneid fraktion","ist felgur bei der horde","wem dient felgur"}},["8c623583"]={q="Was möchte Felgur Zweischneid?",a="Felgur versucht, die feindseligen Zentaurenclans einzudämmen, die die Horde in Desolace bedrohen. Er wirbt fähige Recken an, um Kopfgelder zu sammeln und sich Khan Dez'hepah entgegenzustellen.",al={"ziel felgur zweischneid","was versucht felgur zu tun","was braucht felgur"}},a5d710fc={q="Warum ist Felgur Zweischneid hier stationiert?",a="Felgur ist im Geistwandlerposten stationiert, um die örtlichen Zentaurenstämme zu beobachten und Maßnahmen gegen Bedrohungen für den Stützpunkt der Horde in Desolace zu leiten.",al={"warum ist felgur zweischneid im geistwandlerposten","felgurs zweck hier","warum ist felgur hier draußen"}}},fp="14,144,21.297.0,18.233.0,22.122.0,32.92.0,36.138.0,36.213.0"}
P.entries["npc:felix-whindlebolt"] = {n="Felix Windenbolz",s="Felix Windenbolz ist ein vertriebener Gnomenflüchtling, der in Ambossar im Coldridgetal Zuflucht sucht. In seiner Eile, vor der radioaktiven Strahlung zu fliehen, die Gnomeregan überflutete, verlor er seine persönlichen Habseligkeiten, und feindselige Frostmane-Trolle machten sich damit davon.",h="Felix Windenbolz ist ein vertriebener Gnomenflüchtling, der in Ambossar im Coldridgetal Zuflucht sucht.",kw={"ambossar","das coldridgetal","felix windenbolz","frostmane","gnomeregan","flüchtling","weißbarts lager"},ang={["race:Dwarf"]="Die einheimischen Frostmane-Trolle sind im gesamten Coldridgetal dreister geworden und greifen verletzliche Gnomenflüchtlinge an, die in der Nähe von Ambossar umherwandern.",["race:Gnome"]="Felix verkörpert die anhaltende Not Eurer vertriebenen Artgenossen, die nach der Katastrophe in Gnomeregan in die unbarmherzige Kälte von Dun Morogh getrieben wurden."},sec={{t="Ein heimatloser Reisender",b="Nach dem tragischen Fall von Gnomeregan irrten Tausende von Gnomen auf der Suche nach Sicherheit durch die eisigen Weiten von Dun Morogh. Felix Windenbolz floh in solcher Eile aus der verstrahlten Stadt, dass er all seine persönlichen Habseligkeiten und Werkzeuge verlor. Zu allem Überfluss verschleppten Frostmane-Eistrolle seine Kiste, seinen Kasten und seinen Eimer voll Bolzen in ihre Lager südwestlich von Ambossar, sodass er mittellos und gestrandet zurückblieb und auf mitfühlende Wanderer angewiesen ist, um seine gestohlene Ausrüstung zurückzuerlangen."}},faq={{q="Wer ist Felix Windenbolz?",a="Felix Windenbolz ist ein Gnomenflüchtling, der derzeit in Ambossar im Coldridgetal Unterschlupf gefunden hat. Er verlor seine Habseligkeiten bei der Flucht aus Gnomeregan, und die einheimischen Frostmane-Trolle stahlen sie.",al={"wer ist felix","felix windenbolz lore","gnom im weißbartlager"}},{q="Wohin wollte Felix fliehen?",a="Felix floh vor der Strahlung, die Gnomeregan überrollte, nachdem der Versuch der Gnome, die Troggs zu vertreiben, schrecklich schiefgegangen war. Er landete in Ambossar, dem Zwergenaußenposten im Coldridgetal, auch wenn er den Ort für einen Gnomen als denkbar ungeeignet empfindet.",al={"wohin wollte felix","felix ziel","warum ist felix im coldridgetal"}},{q="Was ist mit seinen Besitztümern geschehen?",a="In seiner Hast, aus Gnomeregan zu entkommen, verlor Felix seine Kiste, seinen Kasten und seinen Eimer voll Bolzen. Die Frostmane-Eistrolle verschleppten sie in ihre Lager südwestlich von Ambossar, sodass er ohne Vorräte gestrandet ist.",al={"wer hat felix' sachen gestohlen","felix gestohlene ausrüstung","frostmane trolle felix"}},{q="Was verkauft Felix an Abenteurer?",a="Nichts. Felix ist kein Händler: Er hat bei seiner Flucht aus Gnomeregan all seine Habseligkeiten verloren, und alles, was er in Ambossar anbieten kann, ist sein Dank an jeden, der seine Kiste, seinen Kasten und seinen Eimer voll Bolzen wiederbeschafft.",al={"felix händlerwaren","was bietet felix an","felix inventar"}}},fx={b1540142={q="Auf wessen Seite steht Felix Windenbolz?",a="Felix gehört zu den Gnomeregangnome und der Großen Allianz. Wie viele vertriebene Gnome floh er aus den verstrahlten Ruinen von Gnomeregan und findet nun Zuflucht in Ambossar im Coldridgetal, in der Hoffnung, wieder zu seinem Volk zurückkehren zu können.",al={"felix fraktion","ist felix bei der allianz","für wen arbeitet felix"}}},fp="17,232,20.489.0,25.180.0,29.244.0,33.208.0,36.183.0"}
P.entries["npc:fenrus-the-devourer"] = {n="Fenrus der Verschlinger",s="Fenrus der Verschlinger ist ein gewaltiger Worg, der durch das obere Sanktum von Burg Shadowfang streift. Von Erzmagier Arugal als persönliches Haustier und Wächter gehalten, ist die unersättliche Bestie durch unnatürliche Magie aufgedunsen. Jeder, der es wagt, in das persönliche Arbeitszimmer des Erzmagiers einzudringen, muss sich diesem wilden Schrecken und dem Meister stellen, der über ihn wacht.",h="Fenrus der Verschlinger ist ein gewaltiger Worg, der durch das obere Sanktum von Burg Shadowfang streift.",kw={"arugal","fenrus","fenrus der verschlinger","burg shadowfang","silberwald","worg"},ang={["class:Hunter"]="Verschwendet keine Zeit mit dem Versuch, Fenrus zu bezaubern. Der Geist der Bestie ist durch die dunklen Künste von Shadowfang unwiderruflich verdreht und kann nicht an die Wildnis gebunden werden.",["class:Mage"]="Fenrus dient als düstere Mahnung daran, wie tief Erzmagier Arugal gefallen ist, indem er arkane Künste nutzt, um wilde Bestien in groteske Wächter zu verwandeln.",["class:Warlock"]="Erzmagier Arugals Fähigkeit, Leerwandler zur Unterstützung seines Hundes herbeizurufen, offenbart, wie tief der einstige Magier aus Dalaran in schattenhafte, verbotene Beschwörungen eingetaucht ist."},sec={{t="Eine Bestie im Arbeitszimmer des Meisters",b="Tief in Burg Shadowfang, unmittelbar vor den Gemächern von Erzmagier Arugal, lauert der monströse Worg namens Fenrus der Verschlinger. Anders als die wolfsartigen Worgen, die die Zinnen durchstreifen, ist Fenrus ein echter Worg, der zu gigantischen Ausmaßen herangewachsen ist. Während er zwischen den Regalen, Schriftrollen und arkanen Apparaturen von Arugals privatem Arbeitszimmer umherstreift, dient die Bestie sowohl als Haustier als auch als unbarmherzige Vorhut gegen jeden Eindringling, der den Kopf des verrückten Magiers fordert."},{t="Verderbte Macht",b="Fenrus' unnatürliche Masse legt nahe, dass er den dunklen Magien ausgesetzt war, die die Burg seit dem Fall von Baron Silberlein durchdringen. Erzmagier Arugal oder seine entfesselten Worgen haben die Kreatur zweifellos durch arkane oder schattenhafte Experimente verändert und so ein heimisches Raubtier in einen unersättlichen Koloss verwandelt. Fenrus ist so wild und magisch gebunden, dass kein Jäger seinen Geist bezaubern oder zähmen kann."},{t="Arugals wachsames Auge",b="Fenrus aufzuschrecken, bedeutet für Unvorsichtige das sofortige Todesurteil. Erblickt die Bestie einen Eindringling, stößt sie ein ohrenbetäubendes Heulen aus, das durch die gesamte Festung hallt und die unmittelbare Aufmerksamkeit von Arugal selbst auf sich zieht. Anstatt sein Haustier unverteidigt zu lassen, projiziert der Erzmagier seinen finsteren Willen in die Kammer und beschwört Leerwandler herbei, die Fenrus dabei helfen sollen, die Eindringlinge zu überwältigen und zu verschlingen."}},faq={{q="Was für eine Kreatur ist Fenrus?",a="Fenrus ist ein außergewöhnlich großer Worg – ein natürliches, wolfsähnliches Raubtier, das in Lordaeron heimisch ist – und kein zweibeiniger Worgen. Seine unnatürliche Masse und bösartige Wildheit sind das direkte Ergebnis anhaltender Einwirkung der dunklen Magie, die in Burg Shadowfang gewirkt wird.",al={"ist fenrus ein worgen","fenrus kreaturtyp","fenrus wolf"}},{q="Wo ist Fenrus zu finden?",a="Fenrus streift durch das Arbeitszimmer hoch oben in Burg Shadowfang im Silberwald. Sein Bau liegt direkt auf dem Weg zu Erzmagier Arugals innerem Refugium.",al={"wo ist fenrus","fenrus standort","fenrus raum"}},{q="Können Jäger Fenrus als Begleiter zähmen?",a="Nein. Obwohl er als gewöhnliches Wildtier eingestuft ist, kann Fenrus nicht gezähmt werden. Sein Geist ist völlig gebrochen, verwildert und an Erzmagier Arugals finsteren Willen gebunden.",al={"kann ich fenrus zähmen","ist fenrus zähmbar","fenrus zähmen"}},{q="Warum beschwört Arugal Dämonen, wenn Fenrus angegriffen wird?",a="Arugal betrachtet Fenrus als sein geschätztes Haustier und als letzte Verteidigungslinie vor seinem Sanktum. Wenn Fenrus beim Eintritt in den Kampf aufbrüllt, greift Arugal direkt ein und beschwört Leerwandler in die Kammer, um jeden zu überwältigen, der seine Bestie bedroht.",al={"arugal leerwandler","warum hilft arugal fenrus","fenrus leerwandler diener"}},{q="Warum ist Fenrus so viel größer als normale Worge?",a="Fenrus' gewaltige Größe gilt als Folge der dunklen magischen Experimente von Erzmagier Arugal oder als magische Nachwirkung des Worgenbefalls, der die Burg heimsucht.",al={"warum ist fenrus riesig","fenrus größe hintergrund","riesenworg"}},{q="Was geschieht im gesamten Dungeon, wenn Fenrus angegriffen wird?",a="Tritt Fenrus in den Kampf ein, stößt er ein donnerndes Gebrüll aus, das so laut ist, dass man es überall in Burg Shadowfang hören kann, wodurch jeder auf den Kampf vor Arugals Tür aufmerksam gemacht wird.",al={"fenrus gebrüll","fenrus heulen im dungeon","lautes brüllen bsf"}}},fx={b2b015f0={q="Auf wessen Seite steht Fenrus?",a="Fenrus ist Erzmagier Arugal treu ergeben. Als persönliches Biest und Wächter des Zauberers dient er jedem verdrehten Willen, der den Meister von Burg Shadowfang antreibt, und greift jeden Eindringling an, der das obere Sanktum ohne Zögern betritt.",al={"fenrus fraktion","wem dient fenrus","fenrus loyalitäten"}},["01e73d00"]={q="Warum ist Fenrus in Burg Shadowfang?",a="Fenrus streift durch das Hauptarbeitszimmer direkt neben Arugals privaten Gemächern. Er fungiert sowohl als Haustier als auch als monströser Wachhund, der dort platziert wurde, um jeden zu zerfleischen, der versucht, in das innere Sanktum des Erzmagiers einzudringen.",al={"warum ist fenrus hier","fenrus standort zweck","warum bewacht fenrus das arbeitszimmer"}}},fp="19,322,29.436.0,15.369.0,21.397.1,32.260.0,26.167.0,33.157.0,54.234.0,47.174.0,55.191.0"}
P.entries["npc:field-marshal-snowfall"] = {n="Feldmarschall Schneefall",s="Feldmarschall Schneefall ist ein zwergischer Militäroffizier, der im Military Ward von Eisenschmiede stationiert ist, um die Kriegsanstrengungen der Allianz gegen die erstarkende Bedrohung durch die Silithiden zu koordinieren. Angesichts eines uralten Übels, das sich im südlichen Sand von Silithus regt, überwacht er die gewaltigen logistischen Maßnahmen, die zur Ausrüstung der verbündeten Armeen erforderlich sind. Snowfall erfasst gespendete Rohstoffe und belohnt jene, die den Vorbereitungen des Reiches auf den Krieg beistehen.",h="Feldmarschall Schneefall ist ein zwergischer Militäroffizier, der im Military Ward von Eisenschmiede...",kw={"ahn'qiraj","feldmarschall schneefall","eisenschmiede","military ward","abzeichen","silithus","snowfall","kriegsanstrengungen"},ang={["faction:Alliance"]="Snowfall verkörpert den geeinten industriellen und militärischen Willen der Allianz und ruft jedes Volk von Sturmwind bis Darnassus dazu auf, seine Lagerhäuser zu leeren und sich auf die bevorstehende Schlacht vorzubereiten.",["race:Dwarf"]="Im Kriegsviertel der Großen Schmiede stationiert, spricht Snowfall voller Stolz davon, die Schöpfungen der Titanen gegen eine uralte, tief sitzende Verderbnis zu verteidigen."},sec={{t="Rüstmeister der Kriegsanstrengungen von Ahn'Qiraj",b="Feldmarschall Schneefall hält im Military Ward von Eisenschmiede Wache und fungiert als zentraler Koordinator für die Mobilmachung der Allianz gegen Ahn'Qiraj. Er betrachtet den heraufziehenden Konflikt nicht bloß als Grenzplänkelei, sondern als entscheidenden Kampf gegen einen uralten Feind, der allen Schöpfungen der Titanen feindselig gegenübersteht. Snowfall überwacht atemberaubende Vorratslager – Millionen von Verbänden, Tonnen von Metallbarren, Leder, Kräutern und Rationen, die von Abenteurern gesammelt wurden –, um sicherzustellen, dass die Streitkräfte der Allianz bewaffnet, gerüstet und versorgt sind, wenn der Marsch gen Süden nach Silithus beginnt."},{t="Der Weg nach Silithus",b="Die Mobilmachung einer ganzen Fraktion erfordert die Abstimmung zwischen Schmieden, Sammlern, Köchen und Soldaten in jedem Territorium der Allianz. Snowfall überwacht jede Phase dieser gewaltigen Unternehmung, nimmt Belobigungsabzeichen entgegen und händigt Freiwilligen Nachschubanforderungen aus. Sobald die benötigten Kriegsvorräte fraktionsübergreifend vollständig gesammelt sind, werden die Vorräte verpackt und nach Süden zur Burg Cenarius geschafft, um den Großangriff gegen die insektoiden Schwärme und den Alten Gott vorzubereiten, der hinter dem Skarabäuswall lauert."}},faq={{q="Wer ist Feldmarschall Schneefall?",a="Feldmarschall Schneefall ist ein hochrangiger zwergischer Kommandant mit Sitz im Military Ward von Eisenschmiede. Er ist damit beauftragt, die umfassende Vorratssammlung der Allianz für den bevorstehenden Krieg gegen die Qiraji in Silithus zu überwachen und zu bilanzieren.",al={"snowfall rolle","wer ist snowfall","feldmarschall snowfall lore"}},{q="Warum sammelt die Allianz so viele Vorräte?",a="Eine uralte Macht jenseits der Tore von Ahn'Qiraj bedroht Kalimdor. Um einen erfolgreichen Feldzug durch die unbarmherzigen Wüsten von Silithus zu führen, muss die Allianz gewaltige Reserven an Rüstungen, Metallbarren, medizinischen Verbänden, Nahrungsmitteln und Kräutern anhäufen, bevor ihre Armeen ausrücken können.",al={"warum stoff spenden","zweck der kriegsanstrengungen","warum kriegsmaterial"}},{q="Wohin gelangen die gesammelten Materialien, sobald alles abgeschlossen ist?",a="Sobald sowohl die Allianz als auch die Horde ihre gesamten Sammelkontingente erfüllt haben, transportieren Karawanen und Nachschubschiffe die riesigen Vorräte zur Burg Cenarius in Silithus, wo die vereinten Streitkräfte ihr vorgeschobenes Aufmarschgebiet errichten.",al={"wohin kommen die vorräte","was geschieht mit den vorräten"}},{q="Wofür werden die Abzeichen für Kriegsmaterial verwendet?",a="Abzeichen werden an Unterstützer verliehen, die benötigte Waffen und Materialien für die Kriegsanstrengungen spenden. Feldmarschall Schneefall nimmt diese Abzeichen bündelweise entgegen und belohnt pflichtbewusste Bürger der Allianz für ihre Dienste mit Nachschubkisten und Ausrüstung.",al={"abzeichen abgeben","wofür sind abzeichen"}}},fx={ec7ab6f1={q="Auf wessen Seite steht Feldmarschall Schneefall?",a="Feldmarschall Schneefall ist ein loyaler Kommandant der Allianz. Stationiert im Military Ward der Eisenschmiede, beaufsichtigt er die fraktionsweite Logistik und Materialbeschaffung, die erforderlich ist, um eine gemeinsame Offensive in Kalimdor aufzustellen. Obwohl dieser Feldzug eine schwierige parallele Zusammenarbeit mit der Horde erfordert, um genügend Vorräte anzuhäufen, liegt Schneefalls Loyalität fest bei den Königreichen der Großen Allianz.",al={"feldmarschall schneefall allianz oder horde","schneefall fraktion","wem dient schneefall"}},e1b72348={q="Was will Feldmarschall Schneefall?",a="Schneefall möchte atemberaubende Mengen an Rohstoffen, Verbänden, Metallbarren, Kräutern und Nahrungsvorräten aus den gesamten Landen der Allianz anhäufen. Sein Ziel ist es sicherzustellen, dass die stehende Armee, die in der rauen Wüste von Silithus eintrifft, bei der Öffnung der Tore von Ahn'Qiraj über jede Waffe, jeden Trank und jede Ration verfügt, die nötig ist, um C'Thuns Legionen standzuhalten, ohne durch Erschöpfung zusammenzubrechen.",al={"ziel von feldmarschall schneefall","was benötigt schneefall","objektive von schneefall"}},a597c3d5={q="Warum ist Feldmarschall Schneefall in Eisenschmiede?",a="Schneefall hat sein Kommando im Military Ward von Eisenschmiede aufgeschlagen, da die Zwergenstadt im Gebirge als zentraler Knotenpunkt für Industrie und Handel der Allianz dient. Von hier aus kann er Frachtlisten verfolgen, eingehende Materialien koordinieren, die von Bürgersoldaten gesammelt wurden, und den Berg an Vorräten zusammenstellen, bevor sie über das Meer zu den Bereitstellungsgebieten in Silithus verschifft werden.",al={"warum ist schneefall in eisenschmiede","schneefall military ward","warum ist feldmarschall schneefall hier"}}},fp="22,407,37.558.0,20.505.0,30.238.0,48.269.0,49.224.0,47.239.0"}
P.entries["npc:field-marshal-stonebridge"] = {n="Feldmarschall Steinsteg",s="Feldmarschall Steinsteg ist eine hochrangige Offizierin der Allianz, die nahe dem Eingang von Sturmwind stationiert ist. Neben den Toren von Sturmwind im Tal der Helden postiert, überwacht sie gemeinsam mit General Marcus Jonathan die Verteidigung der Stadt und dient als Anlaufstelle für bedeutende kriegerische Triumphe.",h="Feldmarschall Steinsteg ist eine hochrangige Offizierin der Allianz, die nahe dem Eingang von Sturmwind...",kw={"feldmarschall","tore","der herrscher von blackrock","marcus jonathan","nefarian","steinsteg","sturmwind","das tal der helden"},ang={["class:Warrior"]="Als eine der obersten militärischen Befehlshaberinnen an den Stadttoren genießt Feldmarschall Steinsteg den Respekt der Frontsoldaten, die nach hohem kriegerischem Ansehen innerhalb der Allianz streben.",["faction:Alliance"]="Schulter an Schulter mit General Marcus Jonathan verkörpert Steinsteg die unerschütterliche Wachsamkeit des Allianz-Militärs, das Sturmwind vor Invasionen von außen beschützt."},sec={{t="Ein Bollwerk an den Toren",b="Gleich hinter dem hoch aufragenden Eingang des Tals der Helden hält Feldmarschall Steinsteg unter dem östlichen Torbogen nahe den Haupttoren Wache. Ihr hoher Rang innerhalb des Militärs der Großen Allianz stellt sie in die obersten Riegen der strategischen Führung Sturmwinds, wo sie in enger Abstimmung mit General Marcus Jonathan agiert. Von diesem markanten Aussichtspunkt aus beobachtet sie den Strom von Verteidigern, Reisenden und heimkehrenden Champions, die in die Hauptstadt ziehen, stets bereit, die Garnison zu formieren, sollten Bedrohungen den äußeren Verteidigungsring durchbrechen."},{t="Überbringerin von Trophäen",b="Über ihre zeremoniellen und defensiven Pflichten am Stadttor hinaus nimmt Feldmarschall Steinsteg entscheidende Berichte und Beutestücke aus Feldzügen gegen die größten Widersacher des Königreichs entgegen. Hochrangige Befehlshaber verlassen sich auf Offiziere wie Steinsteg, um wichtige Informationen zu überprüfen und monumentale Siege auf dem Schlachtfeld zu würdigen, darunter die Niederlage von Kriegsherren und Ungeheuern, die in den Klüften des Schwarzfels nisten."}},faq={{q="Wo befindet sich Feldmarschall Steinsteg?",a="Sie steht unter einem Torbogen im nordöstlichen Teil des Tals der Helden in Sturmwind, direkt rechts von General Marcus Jonathan, wenn Ihr durch die Stadttore eintretet.",al={"steinsteg aufenthaltsort","wo ist feldmarschall steinsteg","steinsteg finden"}},{q="Welche Rolle spielt Feldmarschall Steinsteg in Sturmwind?",a="Sie ist eine hochrangige Militäroffizierin der Allianz, die General Marcus Jonathan bei der Verteidigung von Sturmwinds Haupttor unterstützt und als Empfangsoffizierin für bemerkenswerte militärische Berichte sowie bedeutende Siegestrophäen dient, die von Champions der Allianz zurückgebracht werden.",al={"was macht steinsteg","steinsteg funktion","wer ist feldmarschall steinsteg"}},{q="Welcher Rang ist ein Feldmarschall in der Allianz?",a="Feldmarschall ist einer der höchsten Offiziersränge in der militärischen Kommandostruktur der Großen Allianz, direkt unter dem Großmarschall angesiedelt. Offiziere dieses Ranges beaufsichtigen bedeutende taktische Einsätze, Stadtverteidigungssektoren und strategische Garnisonen.",al={"allianz feldmarschall rang","welchen rang hat steinsteg"}},{q="An welchen bedeutenden Quests ist Feldmarschall Steinsteg beteiligt?",a="Sie ist die Offizierin, die den Bericht und die Trophäe für „Der Herrscher des Schwarzfels“ entgegennimmt und damit Nefarians Fall bestätigt, wenn Abenteurer der Allianz den Kopf des Drachen zu den Toren von Sturmwind schleppen.",al={"steinsteg quests","der herrscher von blackrock questabgabe"}}},fx={["63c0e4ac"]={q="Wer ist Feldmarschall Steinsteg?",a="Feldmarschall Steinsteg ist eine hochrangige menschliche Kommandantin des Militärs der Allianz, die an den Toren von Sturmwind stationiert ist. An der Seite der Führung der Stadt im Tal der Helden überwacht sie kritische Verteidigungsmaßnahmen und fungiert als eine der militärischen Autoritäten des Königreichs.",al={"wer ist steinsteg","identität von feldmarschall steinsteg","hintergrund von steinsteg"}},["05caa28c"]={q="Auf wessen Seite steht Feldmarschall Steinsteg?",a="Feldmarschall Steinsteg ist dem Königreich Sturmwind und der Großen Allianz vollkommen loyal. Sie dient direkt unter den obersten Kommandanten des Königreichs und hilft dabei, die Hauptstadt vor äußeren Bedrohungen zu schützen.",al={"fraktion von steinsteg","loyalität von steinsteg","wem dient steinsteg"}},d0356b7c={q="Warum ist Feldmarschall Steinsteg hier?",a="Sie ist im Tal der Helden stationiert, um am Haupteingang der Hauptstadt Wache zu halten, General Marcus Jonathan bei der Koordination der Streitkräfte von Sturmwind zu unterstützen und militärische Berichte mit hoher Priorität sowie Trophäen, die von Champions der Allianz mitgebracht werden, entgegenzunehmen.",al={"warum ist steinsteg in sturmwind","warum ist steinsteg an den toren","steinsteg tal der helden"}},a46f624c={q="Was will Feldmarschall Steinsteg?",a="Steinsteg strebt die vollständige Verteidigung von Sturmwind und den Sieg über die größten Widersacher des Reiches an. Sie verifiziert eifrig Beweise für bedeutende Siege, die von Abenteurern gebracht werden, um die Sicherheit des Königreichs zu gewährleisten.",al={"ziele von steinsteg","was will feldmarschall steinsteg","beweggründe von steinsteg"}},af024441={q="Mit wem ist Feldmarschall Steinsteg verbunden?",a="Sie arbeitet eng mit General Marcus Jonathan zusammen, dem Kommandanten der Stadtverteidigung von Sturmwind, und ist Teil des umfassenderen militärischen Apparats von Hochlord Bolvar Fordragon, der das Reich des jungen Königs Anduin Wrynn schützt.",al={"verbindungen von steinsteg","mit wem arbeitet steinsteg zusammen","steinsteg marcus jonathan"}}},fp="25,285,22.552.0,18.432.0,43.180.0,54.251.0,45.239.0,52.195.1"}
P.entries["npc:first-mate-fitzsimmons"] = {n="Erster Maat Fitzsimmons",s="Erster Maat Fitzsimmons ist ein zerlumpter, stinkender Seemann, der seine Tage mit Trinken vor der Tiefenwassertaverne im Hafen von Menethil verbringt. Einst Erster Maat an Bord der Wave Mistress aus der Dritten Flotte von Kul Tiras, ist er der einzig bekannte lebende Überlebende der Zerstörung der Flotte während des Zweiten Krieges. Von der Tragödie heimgesucht, sucht er nach willigen Abenteurern, die sich den rastlosen Geistern seiner ertrunkenen Kameraden stellen.",h="Erster Maat Fitzsimmons ist ein zerlumpter, stinkender Seemann, der seine Tage mit Trinken vor der...",kw={"tiefenwassertaverne","auge von paleth","erster maat fitzsimmons","fitzsimmons","kul tiras","die verlorene flotte","der hafen von menethil","die dritte flotte","wave mistress"},ang={["faction:Alliance"]="Fitzsimmons steht für ein tragisches Kapitel in der Marinegeschichte der Allianz und erinnert Helden an die verheerenden Verluste, die sie gegen die versklavte Drachenarmada der Horde erlitten haben.",["race:Human"]="Als Veteran von Kul Tiras teilt Fitzsimmons tiefe kulturelle Bande mit dem seefahrenden Menschenkönigreich, das während des Zweiten Krieges große Opfer brachte, um Lordaeron zu verteidigen."},sec={{t="Ein gebrochener Seemann",b="Erster Maat Fitzsimmons lümmelt in der feuchten Salzluft des Hafens von Menethil vor der Tiefenwassertaverne herum und ist ein Mann, den man leicht übersieht – oder angesichts seines ungewaschenen Gestanks gänzlich meidet. Für die meisten Gäste ist er nur ein weiterer gebrochener alter Seebär, der seine Erinnerungen im Alkohol ertränkt. Doch wer bereit ist, sich zu ihm zu setzen und zuzuhören, erfährt erschütternde Geschichten von einer stolzen Flotte, die durch Feuer und Klauen zu Fall gebracht wurde."},{t="Der Fall der Dritten Flotte",b="Während des Zweiten Krieges diente Fitzsimmons als Erster Maat an Bord der Wave Mistress, die Teil der zur Bekämpfung der Horde entsandten Dritten Flotte von Kul Tiras war. Vor der Küste des Sumpflands geriet die Flotte in einen Hinterhalt und wurde von versklavten roten Drachen verbrannt, die von Dragonmaw-Orcs geflogen wurden. Die Schiffe wurden zerschmettert und versenkt, sodass Fitzsimmons als einziger Mann lebend an Land kroch."},{t="Der fortwährende Fluch",b="Das Überleben des Drachenfeuers brachte Fitzsimmons keinen Frieden. Die Überreste der Schiffe, die heute als Die verlorene Flotte bekannt sind, werden von seinen ehemaligen Schiffskameraden heimgesucht, die als verfluchte Untote auferstanden und in ihren wässrigen Gräbern keine Ruhe finden. Getrieben von Schuldgefühlen und Schrecken wirbt Fitzsimmons Reisende an, um die untoten Seeleute zu erlösen und uralte Relikte zu bergen, die das Böse, das ihre Seelen bindet, endlich aufheben könnten."}},faq={{q="Wer ist Erster Maat Fitzsimmons?",a="Er ist ein alter Seemann aus Kul Tiras und ehemaliger Erster Maat der Wave Mistress. Er überlebte den katastrophalen Untergang der Dritten Flotte von Kul Tiras während des Zweiten Krieges und vertrinkt nun seine Tage vor der Tiefenwassertaverne im Hafen von Menethil.",al={"fitzsimmons lore","wer ist fitzsimmons","erster maat fitzsimmons"}},{q="Was geschah mit seinem Schiff?",a="Die Wave Mistress und der Rest der Dritten Flotte gerieten während des Zweiten Krieges in einen Hinterhalt versklavter roter Drachen, die von Angehörigen des Dragonmaw-Klans geritten wurden. Die Schiffe verbrannten und zerschellten am Riff vor der Küste des Sumpflands.",al={"was geschah mit wave mistress","dritte flotte zerstörung","warum sank sein schiff"}},{q="Wo befindet sich Die verlorene Flotte?",a="Die zerschmetterten Rümpfe der Flotte liegen vor der felsigen Küste nördlich des Hafens von Menethil im Sumpfland unter Wasser und werden nun von Murlocs und den rastlosen Geistern ertrunkener Seeleute bewacht.",al={"die verlorene flotte standort","wo liegen die versunkenen schiffe","fitzsimmons schiff standort"}},{q="Warum möchte er, dass Abenteurer gegen seine alte Mannschaft kämpfen?",a="Die ertrunkenen Seeleute der Dritten Flotte starben nicht einfach, sondern kehrten als verfluchte, gepeinigte Untote zurück. Fitzsimmons sucht mutige Reisende, um ihnen Frieden zu schenken und die Artefakte zu bergen, die ihre Seelen gefangen halten.",al={"verfluchte besatzung quest lore","warum seine besatzung töten"}},{q="Was ist das Auge von Paleth?",a="Es ist ein uraltes, mächtiges Artefakt, das an Bord der Dritten Flotte mitgeführt wurde. Seine dunkle Macht ist an den Fluch gebunden, der auf den versunkenen Seeleuten lastet, sodass seine Bergung entscheidend dafür ist, der ertrunkenen Flotte Frieden zu schenken.",al={"auge von paleth","paleth relikt"}},{q="Warum riecht Fitzsimmons so streng?",a="Nachdem er beim Untergang seiner Flotte alles verloren hatte, lebt Fitzsimmons seit Jahren in betrunkener Verwahrlosung vor der Tiefenwassertaverne, trägt meerwassergetränkte Lumpen und wäscht sich nur selten.",al={"warum riecht fitzsimmons","fitzsimmons gestank"}}},fx={c1574e2a={q="Auf wessen Seite steht Erster Maat Fitzsimmons?",a="Fitzsimmons fühlt sich durch seine früheren Loyalitäten zu Kul Tiras und The Third Fleet der Allianz verbunden. Heute dient er jedoch keiner Nation und keinem Herrn mehr. Er ist lediglich ein gebrochener Seemann, der seine Tage außerhalb der Tiefenwassertaverne im Hafen von Menethil vertrinkt und sich darauf verlässt, dass vorbeiziehende Abenteurer der Allianz die verfluchten Überreste seiner Vergangenheit beseitigen.",al={"fraktion von fitzsimmons","wem dient fitzsimmons","gehört fitzsimmons zur allianz"}},["468babc7"]={q="Warum ist Erster Maat Fitzsimmons im Hafen von Menethil?",a="Fitzsimmons landete im Hafen von Menethil, weil er der einzige Überlebende der The Third Fleet von Kul Tiras ist, die während des Zweiten Krieges von Orc-Drachenreitern entlang der Küste des Sumpflands vernichtet wurde. Geplagt vom grausamen Schicksal seiner Kameraden hat er sich auf die Stufen vor der Tiefenwassertaverne zurückgezogen, um sein Trauma in Alkohol zu ertränken.",al={"warum ist fitzsimmons hier","grund für fitzsimmons im hafen von menethil","warum ist fitzsimmons vor der taverne"}},["786aa53e"]={q="Mit wem ist Erster Maat Fitzsimmons verbunden?",a="Fitzsimmons war der erste Maat an Bord der Wave Mistress, einem Schiff von Kul Tiras, das in der The Third Fleet diente. Er bleibt eng mit seinem alten Kapitän und seinen Schiffskameraden verbunden, die nun als verfluchte Untote, gebunden durch dunkle Relikte wie The Eye of Paleth, die Schiffswracks vor der Küste heimsuchen.",al={"verbindungen von fitzsimmons","schiff von fitzsimmons","crew von fitzsimmons"}}},fp="22,397,15.367.0,27.366.0,19.390.1,30.232.0,26.212.0,32.182.0,51.206.0,26.197.0,34.173.0"}
P.entries["npc:fizzle-brassbolts"] = {fx={["4ec804ad"]={q="Was will Fizzel Kupferbolz?",a="Fizzel will nichts weiter, als die absolute technische Überlegenheit der Gnome gegenüber der Goblin-Technologie zu beweisen. Zu diesem Zweck hat er zusammen mit seinem Goblin-Rivalen Pozzik die Illusionenrennbahn mitbegründet. Er konzentriert sich voll und ganz auf die Entwicklung schnellerer Raketenautos, die Beschaffung exotischer Treibstoffzutaten wie das salzige Gift der Skorpide der schimmernden Ebene und darauf, das Goblin-Team über die Salzwüste zu schlagen.",al={"was will fizzel","ziel von fizzel kupferbolz","warum nimmt fizzel am rennen teil"}}}}
P.entries["npc:fleet-master-seahorn"] = {n="Flottenmeister Seehorn",s="Flottenmeister Seehorn ist ein erfahrener Tauren-Seefahrer, der als Marinekommandant der Blackwater Raiders in Beutebucht dient. Stationiert auf dem oberen Balkon der Salty Sailor Tavern an der Seite von Baron Revilgaz, überwacht er die maritime Verteidigung des Goblin-Hafens. Seine Hauptaufgabe besteht darin, den Hafen vor der drohenden Gefahr durch ihre geschworenen Feinde, die Blutsegelbukaniere, zu schützen.",h="Flottenmeister Seehorn ist ein erfahrener Tauren-Seefahrer, der als Marinekommandant der Blackwater Raiders...",kw={"blackwater raiders","blutsegel","beutebucht","die faldirbucht","firallon","flottenmeister seehorn","revilgaz","salty sailor tavern","seehorn","die wilden ufer"},ang={["class:Rogue"]="Schurken, die in Beutebucht operieren, finden in Seehorn das Zentrum der Küstenspionage, der verdeckte Überfälle auf die Kriegsschiffe der Blutsegel organisiert und feindliche Befehle abfängt.",["faction:Horde"]="Obwohl Seehorn ein Taure ist, gilt seine Loyalität uneingeschränkt dem Steamwheedle-Kartell und den Blackwater Raiders, und er verhält sich gegenüber Reisenden der Horde und der Allianz gleichermaßen neutral.",["race:Tauren"]="Seehorn ist einer der äußerst seltenen Tauren, welche die Ebenen im Landesinneren von Kalimdor hinter sich gelassen haben, um das offene Meer zu beherrschen und als Flottenmeister für einen neutralen Goblin-Hafen zu dienen."},sec={{t="Ein Bulle auf hoher See",b="Während Tauren in ganz Kalimdor als Ebenenbewohner bekannt sind, wählte Flottenmeister Seehorn ein völlig anderes Leben auf dem Meer. In Piratengewänder gekleidet, befehligt er die Flotte der Blackwater Raiders, den privaten Marinezweig der Operationen des Steamwheedle-Kartells im Schlingendorntal. Hoch oben auf der Salty Sailor Tavern arbeitet Seehorn Schulter an Schulter mit Baron Revilgaz und koordiniert Schifffahrtsrouten, Mannschaftseinsätze sowie die Küstenverteidigung für den gesetzlosen, aber streng verwalteten Hafen von Beutebucht."},{t="Verteidigung der Bucht",b="Seehorns größte anhaltende Sorge gilt den Blutsegelbukanieren, die befestigte Lager entlang der südlichen Wilden Ufer errichtet und Kriegsschiffe vor der Küste vor Anker gelegt haben. Als Berichte enthüllen, dass Flottenmeister Firallon und die Führung der Blutsegel einen direkten Angriff zur Plünderung von Beutebucht planen, ergreift Seehorn offensive Maßnahmen. Indem er Söldner entsendet, um feindliche Korrespondenz abzufangen und Firallon, Keelhaul sowie Stillwater an Bord ihres Flaggschiffs auszuschalten, bewahrt Seehorn den Hafen erfolgreich vor der völligen Zerstörung."},{t="Ein wachsames Auge über die Meere",b="Neben der Abwehr von Piratenüberfällen leitet Seehorn verschiedene Handels- und Bergungsunternehmungen in den Östlichen Königreichen. Er koordiniert die Bergung verlorener, versunkener Schätze vor der Küste von Arathi nahe der Faldirbucht und arbeitet mit Bergungstauchern zusammen, um Elfenrelikte zu sichern. Zudem hält er Revilgaz über lukrative Gelegenheiten in der Stadt auf dem Laufenden, wie etwa Angelwettbewerbe und den örtlichen Handel, um sicherzustellen, dass die Flotte der Blackwater Raiders stets gut finanziert bleibt und rivalisierenden Unternehmungen einen Schritt voraus ist."}},faq={{q="Wo befindet sich Flottenmeister Seehorn?",a="Er befindet sich im obersten Stockwerk und auf dem Balkon der Salty Sailor Tavern in Beutebucht, direkt neben Baron Revilgaz mit Blick auf die Docks.",al={"wo ist seehorn","seehorn aufenthaltsort","seehorn finden"}},{q="Warum dient ein Taure als Flottenmeister der Piraten?",a="Obwohl die meisten Tauren eng mit den Ebenen und spirituellen Traditionen von Mulgore verbunden bleiben, verschrieb sich Seehorn der Seefahrt und dem Leben als Marinesöldner. Sein seemännisches Können und sein gebieterisches Auftreten brachten ihm die Führung der Blackwater Raiders unter Baron Revilgaz ein.",al={"tauren pirat","warum ist seehorn ein pirat","tauren in beutebucht"}},{q="In welcher Beziehung steht Seehorn zu Baron Revilgaz?",a="Seehorn ist Baron Revilgaz' Stellvertreter und der Flottenkommandant seiner Blackwater Raiders. Während Revilgaz Politik, Handel und Finanzen leitet, überwacht Seehorn die Flotte, taktische Aufklärung und defensive Militäroperationen für Beutebucht.",al={"seehorn und revilgaz","ist seehorn revilgaz leibwächter","wer arbeitet für revilgaz"}},{q="Wer sind die Blackwater Raiders?",a="Die Blackwater Raiders sind eine private Korsarenflotte im Dienste des Steamwheedle-Kartells mit Stützpunkt in Beutebucht. Anders als gesetzlose Räuber, die wahllos plündern, fungieren sie als sanktionierte Seestreitmacht, die Goblin-Handelsinteressen schützt und die Ordnung in den südlichen Meeren aufrechterhält.",al={"blackwater raiders","welcher fraktion gehört seehorn an","beutebucht piraten"}},{q="Warum will Seehorn die Blutsegelbukaniere aufhalten?",a="Die Blutsegelbukaniere sind die bitteren Rivalen der Blackwater Raiders. Angeführt von Flottenmeister Firallon haben die Blutsegel Lager entlang der Wilden Ufer errichtet und beabsichtigen, Beutebucht selbst zu erobern. Seehorn arbeitet unentwegt daran, ihren Invasionsplänen zuvorzukommen.",al={"seehorn gegen blutsegel","blutsegel konflikt","warum gegen blutsegel kämpfen"}},{q="Hat Seehorn geschäftliche Beziehungen außerhalb des Schlingendorntals?",a="Ja. Seehorn arbeitet mit Bergungsagenten wie Doktor Draxlegauge und Shakes O'Breen zusammen, um verlorene Fracht und Elfenschätze zu bergen, die nahe der Faldirbucht vor dem Arathihochland gesunken sind, und lässt wertvolle Artefakte zu seinem Posten in Beutebucht bringen.",al={"faldirbucht seehorn","seehorn versunkener schatz","arathi quests seehorn"}}},fp="20,378,23.506.0,17.524.1,20.470.0,38.143.0,49.254.0,51.250.0,31.277.0,55.254.0,57.242.0"}
P.entries["npc:foggy-mackreel"] = {n="Dunst MacKreel",s="Dunst MacKreel ist ein unerschrockener Zwerg, der sich in misslicher Lage auf dem zerstörten unteren Mauerwerk des Thandol-Übergangs befindet. Trotz des zertrümmerten Steinwerks unter seinen Füßen und des schwindelerregenden Abgrunds darunter gilt seine einzige wirkliche Sorge der Zustellung seiner Schwarzbrand-Lieferung nach Norden nach Süderstade.",h="Dunst MacKreel ist ein unerschrockener Zwerg, der sich in misslicher Lage auf dem zerstörten unteren...",kw={"arathi","foggy","mackreel","schwarzbrand","süderstade","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Kuriere der Allianz, die zwischen Eisenschmiede und dem nördlichen Außenposten Süderstade reisen, kreuzen oft Foggys Weg und nehmen seine gestrandete Fracht an sich, um einem Mitstreiter der Allianz zu helfen.",["race:Dwarf"]="MacKreel verkörpert die sture Entschlossenheit – und die eigentümlichen Prioritäten – der Zwerge, indem er die pünktliche Lieferung starken Alkohols weit über belanglose Kleinigkeiten wie das Stranden über einem tödlichen Abgrund stellt."},sec={{t="Gestrandet auf dem Übergang",b="Auf den zerbrochenen Pfeilern unter dem zerstörten Thandol-Übergang sitzend, scheint Dunst MacKreel von seiner gefährlichen Lage völlig unbeeindruckt zu sein. Während die Sabotage der Dunkeleisenzwerge und Kriegsschäden die gewaltige Brücke zwischen dem Sumpfland und dem Arathihochland zerrüttet zurückgelassen haben, betrachtet MacKreel seinen prekären Standplatz als bloße Unannehmlichkeit. Sein Hauptgedanke gilt nicht seiner Rettung, sondern einer ungelieferten Fuhre starken Schwarzbrands, die für die Gäste von Süderstade im Vorgebirge des Hügellands bestimmt ist. Bereitwillig heuert er vorbeikommende Abenteurer an, die geschickt genug sind, seinen Sims zu erreichen, um den Kurierdienst an seiner Statt zu vollenden."}},faq={{q="Wer ist Dunst MacKreel?",a="Dunst MacKreel ist ein exzentrischer Zwergenkurier, der auf den zerstörten Steinpfeilern unter der zerbrochenen Brücke des Thandol-Übergangs festsitzt. Trotz des tiefen Abgrunds bleibt er vollkommen ruhig und konzentriert sich darauf, seinen Schwarzbrand zustellen zu lassen.",al={"dunst mackreel","wer ist foggy","mackreel nsc"}},{q="Wo finde ich Dunst MacKreel?",a="Er befindet sich auf einer Steinplattform auf halber Höhe des zerbrochenen Mittelabschnitts des Thandol-Übergangs, die durch vorsichtiges Herabspringen vom Brückenbauwerk auf der Seite des Arathihochlands erreichbar ist.",al={"wo ist dunst mackreel","dunst mackreel standort","wie man mackreel findet"}},{q="Warum ist Dunst MacKreel dort unten?",a="Foggy landete während seiner Reisen inmitten der Trümmer des Thandol-Übergangs. Doch statt nach Rettung zu suchen, gilt seine Hauptsorge der Suche nach jemandem, der bereit ist, seine Schwarzbrandladung den restlichen Weg nach Süderstade zu bringen.",al={"warum foggy gestrandet ist","wie kam mackreel dorthin","warum er auf der brücke ist"}},{q="Welche Quest bietet Dunst MacKreel an?",a="Er bietet 'MacKreels Schwarzgebranntes' an und bittet Reisende, einen Krug seines starken Gebräus zur Taverne in Süderstade jenseits des Arathihochlands zu bringen.",al={"foggy quest","mackreel schwarzbrand quest","welche quest gibt foggy"}}},fx={["28a25d1f"]={q="Auf wessen Seite steht Dunst MacKreel?",a="Dunst MacKreel ist ein der Allianz zugewandter Zwerg. Selbst als er gefährlich auf den beschädigten Ruinen von The Thandol Span festsaß, lagen seine Loyalitäten und Geschäfte bei seinem Volk und anderen Siedlungen der Allianz, mit dem Ziel, sein starkes Gebräu in den Norden in die Hände der Leute zu bringen, die Süderstade im Vorgebirge des Hügellands halten.",al={"fraktion von dunst mackreel","gehört dunst mackreel zur allianz","seite von dunst mackreel"}},c1253653={q="Was will Dunst MacKreel?",a="Dunst MacKreel möchte, dass seine spezielle Charge selbstgebrannten Schnapses sicher nach Süderstade gebracht wird. Obwohl er auf einem zertrümmerten Pfeiler unter der Brücke gefangen ist, zeigt er erstaunlich wenig Sorge um seine eigene gefährliche Lage und ist voll und ganz damit beschäftigt, sicherzustellen, dass sein Gebräu sein Ziel im Hügelland erreicht, anstatt eine sofortige Rettung zu planen.",al={"motiv von dunst mackreel","was will dunst","ziel von dunst mackreel"}}},fp="14,264,20.583.0,22.226.0,32.183.0,33.217.0,37.143.0"}
P.entries["npc:foreman-oslow"] = {fx={cf681f3e={q="Auf wessen Seite steht Großknecht Oslow?",a="Großknecht Oslow dient dem Königreich Sturmwind und der örtlichen Gemeinde Seenhain. Als Chefbaumeister und Großknecht der Stadt liegt seine Pflicht darin, die lebenswichtige Infrastruktur des Rotkammgebirges aufrechtzuerhalten und seinen Bewohnern zu helfen, trotz der unerbittlichen Angriffe durch umliegende Schwarzfelsorcs und feindselige Gnolle zu überleben.",al={"fraktion von oslow","wem dient großknecht oslow","gehört oslow zur allianz"}},["1a3f577b"]={q="Was will Großknecht Oslow?",a="Oslows Hauptziel ist es, die zerstörte The Everstill Bridge wieder aufzubauen und Seenhain mit dem Rest des Königreichs verbunden zu halten. Um dies zu erreichen, muss er verzweifelt seinen versunkenen Werkzeugkasten aus dem Der Immerruhsee bergen lassen und die Baumaterialien zurückgewinnen, die von örtlichen Gnollen in einem Hinterhalt gestohlen wurden.",al={"was will oslow","ziel von großknecht oslow","warum braucht oslow hilfe"}},["765147a2"]={q="Warum ist Großknecht Oslow in Seenhain?",a="Oslow ist am See stationiert, um öffentliche Arbeiten zu beaufsichtigen und den Wiederaufbau der The Everstill Bridge zu leiten. Die Brücke ist die Lebensader von Seenhain, doch unerbittliche feindliche Angriffe und verheerende Materialverluste lassen ihn direkt am Wasser festsitzen, wo er auf Hilfe wartet, um seine Arbeit fortzusetzen.",al={"warum ist oslow hier","zweck von oslow in seenhain","beruf von großknecht oslow"}}}}
P.entries["npc:foreman-stonebrow"] = {n="Großknecht Steinbraue",s="Großknecht Steinbraue ist ein zwergischer Vorarbeiter, der die Miners' League am Gol'bolar Steinbruch im östlichen Dun Morogh vertritt. Nachdem aggressive Troggs aus dem Fels hervorbrachen und die Ausgrabungsstätte überrannten, sah er sich gezwungen, eine Verteidigung zu organisieren und Abenteurer anzuheuern, um die Gruben zu säubern.",h="Großknecht Steinbraue ist ein zwergischer Vorarbeiter, der die Miners' League am Gol'bolar Steinbruch im...",kw={"dun morogh","großknecht steinbraue","gol bolar","steinbruch gol'bolar","miners' league","stonebrow","troggs"},ang={["profession:Mining"]="Bergleute haben ein berufliches Interesse daran, Stonebrow zu helfen, da die Rückgewinnung der reichen Stein- und Erzvorkommen des Steinbruchs für die Gildenoperationen von Khaz Modan von entscheidender Bedeutung ist.",["race:Dwarf"]="Für Zwerge ist die Trogg-Invasion am Gol'bolar Steinbruch ein direkter Schlag gegen die Steinindustrie von Eisenschmiede und eine finstere Erinnerung an die uralten Bedrohungen, die unter ihrer uralten Heimat lauern."},sec={{t="Die Krise bei Gol'Bolar",b="Großknecht Steinbraue war damit beauftragt, die Arbeiten am Gol'bolar Steinbruch zu leiten, einer wichtigen Zwergenausgrabung in den Bergen östlich von Kharanos. Als tiefe Grabungen verborgene Trogg-Höhlen freilegten, strömten unterirdische Bestien in die Gruben und vertrieben die Bergleute von ihrer Ausrüstung. Da er sich weigert, den Ort vollständig aufzugeben, verharrt Stonebrow am Rand des Steinbruchs, um jeden wehrfähigen Reisenden anzuwerben, der gewillt ist, die Troggs zurückzudrängen."}},faq={{q="Wer ist Großknecht Steinbraue?",a="Großknecht Steinbraue ist ein Zwerg der Miners' League, der die Arbeiten am Gol'bolar Steinbruch in Dun Morogh beaufsichtigt. Er koordiniert die Arbeitsabläufe und versucht, den Steinbruch zu sichern.",al={"stonebrow","wer ist stonebrow","großknecht stonebrow lore"}},{q="Warum bittet Großknecht Steinbraue um Hilfe?",a="Ausgrabungen am Gol'bolar Steinbruch brachen versehentlich in unterirdische Trogg-Höhlen ein. Troggs überrannten die unteren Terrassen, töteten Arbeiter und zwangen die überlebenden Bergleute zum Rückzug in das Lager am oberen Rand.",al={"gol bolar trogg-problem","warum hilfe benötigt wird","steinbruch-quest"}},{q="Was ist die Miners' League?",a="Die Miners' League ist eine Zwergengilde und Handelsorganisation mit Sitz in Eisenschmiede, die Bergbau-Expeditionen, Rohstoffabbau und Steinbruchbetriebe in ganz Khaz Modan überwacht.",al={"miners league","was ist die miners league"}},{q="Wo ist Großknecht Steinbraue zu finden?",a="Er ist im Lager am Rand mit Blick auf den Gol'bolar Steinbruch stationiert, das in den östlichen Hügeln von Dun Morogh direkt an der Straße nach Loch Modan liegt.",al={"stonebrow aufenthaltsort","wo ist großknecht stonebrow"}}},fx={["2635f3c5"]={q="Auf wessen Seite steht Großknecht Steinbraue?",a="Großknecht Steinbraue ist der Miners' League und dem Zwergenkönigreich Eisenschmiede loyal, was ihn fest auf die Seite der Allianz stellt. Er beaufsichtigt zivile Ausgrabungsarbeiten in Dun Morogh und sucht nach Abenteurern der Allianz, um Bedrohungen von den Bergbauaktivitäten in Eisenschmiede zu beseitigen.",al={"fraktion von steinbraue","wem dient steinbraue","gehört steinbraue zur allianz"}},c868fd05={q="Warum ist Großknecht Steinbraue im Steinbruch Gol'Bolar?",a="Großknecht Steinbraue wurde in den Steinbruch Gol'Bolar geschickt, um die Ausgrabung und Rohstoffgewinnung im Namen der Miners' League zu beaufsichtigen. Er bleibt in der Nähe der Grube stationiert, um Unterstützung zu sammeln und Anstrengungen zu koordinieren, den Ort zurückzuerobern, nachdem ein plötzlicher Trogg-Befall die Belegschaft überwältigt hat.",al={"warum ist steinbraue hier","steinbraue golbolar","was macht steinbraue hier"}}},fp="17,269,23.426.0,25.183.0,41.201.0,27.182.0,37.151.0"}
P.entries["npc:foreman-thazz-ril"] = {n="Großknecht Thazz'ril",s="Großknecht Thazz'ril ist ein Vorarbeiter der Orcs, der im Tal der Prüfungen in Durotar stationiert ist. Betraut mit der Aufgabe, die Peons im Zeitplan zu halten und die grundlegende Infrastruktur für junge Krieger instand zu halten, ist er fortwährend von faulen Arbeitern und den nahegelegenen Aktivitäten von Kultisten frustriert.",h="Großknecht Thazz'ril ist ein Vorarbeiter der Orcs, der im Tal der Prüfungen in Durotar stationiert ist.",kw={"knüppel","burning blade","durotar","großknecht","lazy peons","thazzril","das tal der prüfungen"},ang={["profession:Mining"]="Thazz'ril schätzt hochwertige Bergbauausrüstung, wie seine Verzweiflung zeigt, seine verzauberte Spitzhacke aus den finsteren Winkeln des Kovens der Brennenden Klinge wiederzuerlangen.",["race:Orc"]="Jungen Orcs, die heranwachsen, erteilt Thazz'ril eine frühe Lektion über die Gesellschaft der Horde: Stärke auf dem Schlachtfeld ist nur möglich, wenn sie durch unscheinbare, disziplinierte Arbeit gestützt wird."},sec={{t="Die Peons im Zaum halten",b="Der Aufbau einer neuen Heimat im rauen roten Fels von Durotar erfordert unaufhörliche körperliche Arbeit. Im Tal der Prüfungen beaufsichtigt Großknecht Thazz'ril die Peons, die Holz fällen und Materialien sammeln, um sowohl das Lager als auch die größeren Kriegsanstrengungen der Horde zu unterstützen. Zu Thazz'rils Bedauern neigen Peons notorisch dazu, die Arbeit zu vernachlässigen und unter der Wüstensonne Nickerchen zu machen. Um den Baufortschritt zu sichern, heuert er regelmäßig neu eingetroffene Rekruten an, um den schlummernden Arbeitern mit seinem treuen Knüppel einen kräftigen Hieb zu verpassen und ihnen durch stumpfe Überzeugungskraft Gehorsam beizubringen."},{t="Eine verlorene Spitzhacke in gefährlichen Händen",b="Zu Thazz'rils Pflichten gehört auch die Erkundung der Bodenschätze des Tals, was jedoch zu einem peinlichen Fehltritt führte. Bei der Erkundung der als Koven der Brennenden Klinge bekannten Höhle musste er vor den finsteren Kultisten fliehen, die im Inneren lauerten, und ließ dabei versehentlich seine geschätzte verzauberte Spitzhacke zurück. Zu vorsichtig, um sie inmitten der sich sammelnden Hexenmeister und ihrer dämonischen Schergen selbst zurückzuholen, verlässt er sich auf junge Hordenanwärter, die in die Tiefen vordringen und sein Werkzeug zurückbringen."}},faq={{q="Wer ist Großknecht Thazz'ril?",a="Großknecht Thazz'ril ist ein Arbeitsaufseher der Orcs im Tal der Prüfungen in Durotar. Er ist für die Verwaltung der Arbeitstrupps, das Holzfällen und die Erkundung der Region nach nützlichen Ressourcen zur Unterstützung der Siedlung der Horde verantwortlich.",al={"wer ist thazzril","thazzril tal der prüfungen","großknecht thazzril lore"}},{q="Warum gibt Thazz'ril Spielern einen Knüppel?",a="Die Peons unter seiner Aufsicht schlafen häufig unter Bäumen ein, anstatt Holz zu hacken. Thazz'ril stellt einen verzauberten Holzknüppel zur Verfügung, um ihnen etwas Disziplin einzubläuen und sie eilig zurück an die Arbeit zu schicken.",al={"warum faule peons schlagen","thazzril knüppel","lazy peons quest lore"}},{q="Warum befindet sich Thazz'rils Spitzhacke in der Höhle der Burning Blade?",a="Beim Erkunden der örtlichen Höhlen nach Mineraladern stolperte Thazz'ril in den Koven der Brennenden Klinge. Aufgeschreckt von den in den Schatten lauernden Kultisten trat er einen hastigen Rückzug an und ließ seine wertvolle verzauberte Spitzhacke zurück.",al={"thazzril spitzhacke","warum ist spitzhacke im koven","burning blade spitzhacke"}},{q="Welche Rolle spielt er in der Horde?",a="Thazz'ril ist kein Soldat an vorderster Front oder Schamane, sondern ein ziviler Aufseher. Seine Pflichten drehen sich um das logistische Rückgrat von Durotar: die Beaufsichtigung manueller Arbeit, die Instandhaltung von Baumaterialien und das Sichern der Produktivität der Peons.",al={"ist thazzril ein soldat","thazzril rang"}}},fx={["607050fc"]={q="Auf wessen Seite steht Großknecht Thazz'ril?",a="Thazz'ril ist Thralls Horde gegenüber loyal. Stationiert im Das Tal der Prüfungen beaufsichtigt er die grundlegende Arbeit und Rohstoffbeschaffung, die dabei hilft, Durotar aufzubauen und die Trainingsgelände für ankommende Rekruten der Orcs und Trolle zu erhalten.",al={"loyalität von großknecht thazz'ril","thazz'ril horde","fraktion von thazz'ril"}},f77b2dd2={q="Was will Großknecht Thazz'ril?",a="Großknecht Thazz'ril will in erster Linie, dass seine Arbeiter auch wirklich arbeiten. Genervt von faulen Peons, die im Tal herumlungern, rekrutiert er junge Abenteurer, um sie aufzuwecken. Er möchte außerdem seine geschätzte verzauberte Spitzhacke zurückerhalten, die er unglücklicherweise in der Nähe des Zirkels der Burning Blade zurückgelassen hat.",al={"thazzrils ziele","was braucht thazzril","thazzrils motivationsgrund"}},ee1167cb={q="Warum ist Großknecht Thazz'ril hier?",a="Er wurde dem Tal der Prüfungen zugewiesen, um die Arbeit der Peons zu leiten und die örtlichen Bergbau- und Holzfällerarbeiten zu verwalten. Die Instandhaltung der Siedlung und der stetige Fluss an Rohstoffen sind entscheidend für die Vorbereitung junger Krieger, bevor sie sich in die weitläufigeren Ländereien von Durotar wagen.",al={"warum ist thazzril im tal der prüfungen","grund für thazzrils standort"}}},fp="17,260,25.562.0,30.481.0,25.215.0,44.213.0,54.214.0,30.220.0"}
P.entries["npc:foreman-thistlenettle"] = {n="Großknecht Distelklette",s="Großknecht Distelklette war einst ein zwergischer Vorarbeiter, der sowohl die Miners' League als auch die Explorers' League in den Tiefen von Westfall vertrat. Nachdem ein katastrophaler Einsturz seine Mannschaft in den unterirdischen Tunneln der Todesminen gefangen hatte, kam er an der Seite seiner Arbeiter um und erhob sich erneut als untoter Ghul. Er streift nun durch die finsteren, eingestürzten Gänge, für jedermann unkenntlich, bis auf das Gildenabzeichen, das er noch immer bei sich trägt.",h="Großknecht Distelklette war einst ein zwergischer Vorarbeiter, der sowohl die Miners' League als auch die...",kw={"abzeichen","einsturz","die todesminen","großknecht","ghul","miners' league","thistlenettle","wilder"},ang={["profession:Mining"]="Thistlenettles Schicksal ist eine düstere Mahnung an alle Bergleute bezüglich der allgegenwärtigen Gefahr von Tunneleinstürzen und feindseligen unterirdischen Tiefen.",["race:Dwarf"]="Der tragische Verlust eines Großknechts der Explorers' League und einer gesamten zwergischen Mannschaft verdeutlicht die schwelenden Gefahren, die unter den Königreichen der Menschen lauern."},sec={{t="Tragödie in den Todesminen",b="Bevor die Bruderschaft der Defias die vollständige Kontrolle über die Todesminen übernahm, drangen rechtmäßige Bergbauexpeditionen tief in deren reiche Adern vor. Großknecht Distelklette beaufsichtigte ein solches Unterfangen im Auftrag der Miners' League und der Explorers' League. Tief in den Tunneln unter Mondbruch schlug das Unglück zu, als ein gewaltiger Einsturz seine Gruppe von der Oberfläche abschnitt. Die eingeschlossenen Bergleute starben in der Dunkelheit, doch ihre Ruhe währte nicht lange; ein unheilvoller, nekrotischer Makel erweckte Thistlenettle und seine Mannschaft als unersättliche Ghule wieder zum Leben, damit sie die schattigen Passagen durchstreifen."},{t="Die Trauer eines Bruders",b="Zurück in Sturmwind verbrachte sein Bruder Wilder Distelklette rastlose Monate damit, über das Schicksal der vermissten Bergbaugruppe zu grübeln. Da kein Wort aus den besetzten Tunneln nach außen drang, kamen schließlich Gerüchte auf, dass der gefallene Vorarbeiter noch immer unter den Toten wandelte. Abenteurer, die den Außenbereich der Todesminen wagen, werden darum gebeten, den untoten Großknecht ausfindig zu machen, seine Qualen zu beenden und sein Abzeichen zu bergen, um seinen trauernden Angehörigen Gewissheit zu verschaffen."}},faq={{q="Wer war Großknecht Distelklette, bevor er starb?",a="Er war ein zwergischer Großknecht, der sowohl mit der Miners' League als auch mit der Explorers' League in Verbindung stand. Er führte eine Mannschaft von Bergleuten in die Todesminen, bevor diese von Gesetzlosen vollständig befestigt wurden, um die unterirdischen Adern abzubauen und zu vermessen.",al={"thistlenettle lore","wer ist großknecht thistlenettle","thistlenettle hintergrund"}},{q="Warum ist Großknecht Distelklette ein untoter Ghul?",a="Ein katastrophaler Einsturz verschüttete die Tunnel um Thistlenettle und seine Bergbaugruppe und tötete sie. Dunkle unterirdische Energien oder verweilende Nekromantie innerhalb der labyrinthischen Minen belebten ihre Überreste in der Folgezeit wieder und machten aus den Zwergen rastlose Ghule.",al={"warum ist er ein ghul","wie starb thistlenettle","thistlenettle untoter"}},{q="Wo befindet sich Großknecht Distelklette?",a="Er spukt in einem eingestürzten Sackgassentunnel im äußeren Labyrinth der Todesminen, der vor dem Portal zur eigentlichen Instanz liegt, umgeben von seinen wiederbelebten ehemaligen Bergleuten.",al={"wo findet man thistlenettle","thistlenettle aufenthaltsort","standort großknecht todesminen"}},{q="Wer sucht nach Großknecht Distelklette?",a="Sein Bruder Wilder Distelklette, der im Zwergendistrikt von Sturmwind verweilt. Wilder sucht nach einem Beweis für das Schicksal seines Bruders und bittet Reisende darum, Distelklettes Abzeichen zurückzubringen.",al={"wer will thistlenettles tod","wilders bruder","thistlenettle questgeber"}}},fx={["81248170"]={q="Auf wessen Seite steht Großknecht Distelklette?",a="Großknecht Distelklette gehört keiner Fraktion oder Sache mehr an. Als gehirnloser, gefräßiger Ghul greift er zusammen mit seiner wiederbelebten Mannschaft jeden an, der töricht genug ist, sich in ihren eingestürzten Winkel der Todesminen zu wagen, egal ob Defias, Allianz oder umherstreifende Schatzsucher.",al={"thistlenettles fraktion","ist großknecht distelklette feindselig","wem dient distelklette"}},a595eadc={q="Was will Großknecht Distelklette?",a="Welche zwergischen Ambitionen er zu Lebzeiten auch besaß, sie starben mit dem Einsturz. Im Untod hat Großknecht Distelklette keine großen Pläne oder Intrigen – nur den blinden, rastlosen Hunger, den alle Ghule teilen, während er im dunklen Geröll nach allem Lebendigen sucht, das sich nähert.",al={"was will distelklette","distelklettes beweggrund","distelklettes ziel"}},["194368c4"]={q="Warum ist Großknecht Distelklette hier in den Todesminen?",a="Er wagte sich ursprünglich tief in die Todesminen, um eine Expedition im Auftrag der Bergbau-Liga und der Forscherliga zu beaufsichtigen. Als die Katastrophe eintrat und ein unterirdischer Einsturz seine Mannschaft unter sich begrub, waren sie unter dem Gestein gefangen und konnten niemals entkommen, selbst nach ihrem Tod nicht.",al={"warum ist distelklette in den todesminen","wie kam distelklette hierher","warum ist großknecht distelklette hier"}}},fp="21,416,24.530.0,17.419.1,45.237.0,45.261.0,39.181.0,41.186.0"}
P.entries["npc:frahun-shadewhisper"] = {n="Frahun Schattenflüsterer",s="Frahun Schattenflüsterer ist ein Nachtelf-Schurkenlehrer, der in Aldrassil im Laubschattental stationiert ist. Er bringt neu eingeweihten Nachtelfenspähern und -schurken die grundlegenden Techniken der Heimlichkeit, Beweglichkeit und verdeckten Angriffe bei. Er teilt seinen Nachnamen mit Erion Schattenflüsterer, einem weiteren Ausbilder seines Handwerks in Darnassus.",h="Frahun Schattenflüsterer ist ein Nachtelf-Schurkenlehrer, der in Aldrassil im Laubschattental stationiert ist.",kw={"aldrassil","verschlüsseltes siegelzeichen","erion","frahun","schurkenlehrer","shadewhisper","laubschattental","teldrassil"},ang={["class:Rogue"]="Frahun Schattenflüsterer dient als allererster Klassenlehrer für Nachtelfenschurken und vermittelt ihnen die erste Einführung in Heimlichkeit, Hinterhaltstaktiken und Waffenbeherrschung.",["race:NightElf"]="Frahun veranschaulicht, wie Nachtelfen ihre natürliche nächtliche Verbundenheit und Flüchtigkeit in tödliche, praktische Kampffertigkeiten umwandeln, um Teldrassil zu beschützen."},sec={{t="Ein Mentor in den Schatten",b="In der sicheren Zuflucht von Aldrassil im Herzen von Teldrassil unterweist Frahun Schattenflüsterer aufstrebende Schurken in den stillen Künsten der Verborgenheit und Klingenführung. Während die Gesellschaft der Nachtelfen oft Priester, Schildwachen und Druiden ehrt, bleibt das spezialisierte Handwerk der Späher und Infiltratoren unerlässlich, um das Geäst des Weltenbaums zu schützen. Frahun heißt Rekruten willkommen, die mit einem Verschlüsselten Siegelzeichen eintreffen, beurteilt ihr Potenzial und leitet ihre anfängliche Ausbildung an."}},faq={{q="Wer ist Frahun Schattenflüsterer?",a="Frahun Schattenflüsterer ist ein Nachtelf-Schurkenlehrer, der in Aldrassil auf Teldrassil stationiert ist. Er lehrt angehende Schurken die Grundlagen der Heimlichkeit, des Präzisionskampfes und verdeckter Taktiken.",al={"frahun lore","wer ist frahun","frahun schattenflüsterer rolle"}},{q="Wo ist Frahun Schattenflüsterer zu finden?",a="Er befindet sich in Aldrassil, der zentralen Festung des Startgebiets Laubschattental auf Teldrassil.",al={"frahun standort","wo ist frahun","frahun schattenflüsterer finden"}},{q="Ist Frahun mit Erion Schattenflüsterer verwandt?",a="Aufgrund ihres gemeinsamen Nachnamens und ihrer beiderseitigen Hingabe zur Ausbildung von Schurken auf Teldrassil wird weithin angenommen, dass Frahun mit Erion Schattenflüsterer verwandt ist, der Schurken in Darnassus ausbildet.",al={"erion schattenflüsterer bruder","frahun erion verwandt","shadewhisper familie"}},{q="Welche Rolle spielen die Verschlüsselten Siegelzeichen bei ihm?",a="Angehende Nachtelfenschurken beginnen ihre Reise, indem sie Verschlüsselte Siegelzeichen direkt zu Frahun bringen, was sie als Kandidaten ausweist, die für die formelle Unterweisung im Handwerk des Schurken bereit sind.",al={"verschlüsselte siegelzeichen abgabe","frahun siegelzeichen","schurken startquest"}}},fx={a27f02ba={q="Auf wessen Seite steht Frahun Schattenflüsterer?",a="Frahun steht fest an der Seite von Darnassus und der Allianz. Stationiert inmitten der uralten Äste von Aldrassil im Laubschattental, dient er seinen Mit-Kaldorei, indem er sicherstellt, dass diejenigen mit einem Talent für Heimlichkeit und List ihre Fähigkeiten verfeinern können, um die Ländereien der Nachtelfen zu schützen.",al={"frahuns fraktion","frahuns loyalität","gehört frahun zur allianz"}},["025c0171"]={q="Was will Frahun Schattenflüsterer?",a="Frahun möchte aufstrebende Nachtelf-Schurken in der Kunst der Schatten, des Schlösserknackens und des verstohlenen Kampfes unterrichten. Er stellt sicher, dass neue Späher und Agenten ihre Disziplin gründlich beherrschen, bevor sie sich über die geschützten Grenzen des Laubschattentals hinaus in das weitere Teldrassil wagen.",al={"frahuns beweggrund","frahuns ziel","was tut frahun"}},["72dec556"]={q="Warum ist Frahun Schattenflüsterer hier in Aldrassil?",a="Frahun ist in Aldrassil stationiert, um neu erwachte oder unerfahrene Nachtelfen anzuleiten, die den Pfad des Schurken beschreiten. Im sicheren Hafen des Laubschattentals bietet er grundlegende Ausbildung, um sicherzustellen, dass junge Praktizierende nicht den Gefahren erliegen, die im Wald lauern.",al={"warum ist frahun in aldrassil","warum ist frahun im laubschattental","zweck von frahuns standort"}}},fp="19,308,23.468.0,27.178.0,39.100.0,40.173.0,49.172.0"}
P.entries["npc:furen-longbeard"] = {fx={["269e0799"]={q="Auf wessen Seite steht Furen Langbart?",a="Furen Langbart ist ein treues Mitglied der Allianz und geht seinem Handwerk im geschäftigen Zwergendistrikt in Sturmwind nach. Er arbeitet eng mit Verwandten aus Eisenschmiede, anderen Schmieden und dem Stormpike-Clan zusammen und widmet sein Können der Ausrüstung der Verteidiger der Allianz.",al={"furen langbarts fraktion","gehört furen langbart zur allianz","wem dient furen langbart"}},d8add91c={q="Was will Furen Langbart?",a="Furen sucht nach seltenen Materialien und fähigen Verbündeten, um außergewöhnliche Rüstungen herzustellen, insbesondere für vielversprechende Krieger, die robuste Ausrüstung wie feuergehärtete Kettenrüstung suchen. Er arbeitet auch daran, wichtige militärische Aufträge zu erfüllen, einschließlich spezialisierter Bestellungen für die Stormpikegarde.",al={"was will furen","furen langbarts beweggrund","furen langbarts ziele"}},["316ead5d"]={q="Warum ist Furen Langbart in Sturmwind?",a="Furen arbeitet vom Zwergendistrikt in Sturmwind aus und dient als lebenswichtiges Bindeglied zwischen zwergischem Handwerk und den militärischen Bedürfnissen der Hauptstadt der Menschen. Hier, in der Nähe der großen Schmieden der Stadt, kann er mit Lehrlingen, Meisterschmieden und gnomischen Ingenieuren zusammenarbeiten, während er Frontverteidiger mit schwerer Rüstung versorgt.",al={"warum ist furen langbart hier","warum ist furen in sturmwind","hintergrund zu furen langbarts standort"}}}}
P.entries["npc:furl-scornbrow"] = {n="Furl Hohnbraue",s="Furl Hohnbraue ist ein alternder Orc-Späher, der im Wachturm nordwestlich von Klingenhügel stationiert ist. Da er aufgrund seines fortgeschrittenen Alters nicht mehr an vorderster Front kämpfen kann, hält er über den roten Schluchten von Durotar Wache und fertigt robuste Taschen für junge Reisende, die ins Land aufbrechen.",h="Furl Hohnbraue ist ein alternder Orc-Späher, der im Wachturm nordwestlich von Klingenhügel stationiert ist.",kw={"akzeptiert euer schicksal","durotar","furl hohnbraue","späher","orc","klingenhügel","wachturm"},ang={["faction:Horde"]="Stationiert entlang der Bergrücken außerhalb von Klingenhügel, verkörpert Furl die Wachsamkeit, die nötig ist, um Durotars junge Siedlungen vor anhaltenden Bedrohungen zu schützen.",["race:Orc"]="Furl verkörpert den Glauben der Orcs, dass ein ehrenhaftes Leben bedeutet, einen anderen Weg zu finden, um dem Clan und der Horde zu dienen, selbst wenn das Alter einen Krieger seiner kriegerischen Stärke beraubt."},sec={{t="Wächter des Kamms",b="Hoch oben im hölzernen Wachturm direkt nordwestlich von Klingenhügel hält Furl Hohnbraue eine ruhige Wacht über die zentralen Ebenen von Durotar. In den angespannten frühen Tagen nach der Gründung von Orgrimmar waren Posten wie Furl unerlässlich, um Signalhörner gegen feindselige Borstennacken, Zentauren und Eindringlinge aus Kul Tiras ertönen zu lassen. Da sich Durotar stabilisiert hat und Klingenhügel über festere Grenzen verfügt, sind Notfälle seltener geworden, was Furl viele ruhige Stunden auf seinem Posten beschert."},{t="Ein nützliches Paar Hände",b="Furl gibt freimütig zu, dass seine alten Knochen und schwindenden Kräfte ihn im Kampf unbrauchbar machen, doch ein Orc gibt seine Bestimmung nicht so leicht auf. Anstatt untätig herumzusitzen, macht er sich nützlich, indem er Segeltuchsäcke und Taschen für neue Rekruten herstellt, die ihre Vorräte tragen müssen. Im Austausch gegen groben Faden und praktische Materialien rüstet er unerfahrene Abenteurer aus, die ausziehen, um ihren Wert für die Horde zu beweisen."}},faq={{q="Wer ist Furl Hohnbraue?",a="Furl Hohnbraue ist ein älterer Orc-Wächter, der im Aussichtsturm auf den Klippen nordwestlich von Klingenhügel stationiert ist. Da er aufgrund seines Alters nicht mehr als Krieger an vorderster Front dienen kann, hält er am Horizont nach Gefahren Ausschau und fertigt Taschen für junge Reisende.",al={"wer ist furl","furl hohnbraue lore","furl in klingenhügel"}},{q="Welche Rolle spielt Furl in Durotar?",a="Er besetzt den Signalhornturm und hält Ausschau nach Angreifern, die sich Klingenhügel nähern. Da Durotar unter der Kontrolle der Horde immer sicherer geworden ist, schlägt er weit seltener Alarm und nutzt seine freie Zeit, um ankommenden Rekruten bei der Organisation ihrer Ausrüstung zu helfen.",al={"was macht furl","furls bestimmung"}},{q="Warum bittet Furl Reisende um Materialien?",a="Furl glaubt daran, dass jedes Mitglied der Horde seinen Beitrag leisten muss, ungeachtet der Umstände. Da er nicht mehr kämpfen kann, näht er praktische Reisetaschen, um neueren Kriegern zu helfen, und verlangt dafür lediglich grundlegende Materialien wie groben Faden, um die Arbeit fertigzustellen.",al={"akzeptiert euer schicksal quest lore","warum furl faden will"}}},fx={["1ce1cc0b"]={q="Auf wessen Seite steht Furl Hohnbraue?",a="Furl steht fest an der Seite der Horde. Hoch über Klingenhügel positioniert, hält er Wache über Durotar, um das junge Orc-Reich vor potenziellen Eindringlingen zu schützen, und unterstützt Reisende, die dem Kriegshäuptling dienen.",al={"furl hohnbraues fraktion","gehört furl hohnbraue zur horde","ist furl bei der horde"}}},fp="14,282,21.468.0,22.410.0,22.248.0,31.249.0,42.251.0"}
P.entries["npc:gaerolas-talvethren"] = {n="Gaerolas Talvethren",s="Gaerolas Talvethren ist eine Schildwache der Nachtelfen, die über die Ruinen von Sternenhauch in Teldrassil wacht. Als Beschützer der Schlafenden Druiden ernannt, sucht er Unterstützung beim Kampf gegen die aggressiven Furbolgs und die dunkle Verderbnis, die das Geäst heimsucht.",h="Gaerolas Talvethren ist eine Schildwache der Nachtelfen, die über die Ruinen von Sternenhauch in Teldrassil...",kw={"ein beunruhigender wind","gaerolas talvethren","die verderbnis der knarzklauen","starbreeze","teldrassil","die schlafenden"},ang={["class:Druid"]="Gaerolas' Pflicht als Wächter der schlafenden Druiden macht die Unterstützung seiner Bestrebungen zu einer persönlichen Angelegenheit zum Schutz von Mitstreitern des Zirkels des Cenarius.",["race:NightElf"]="Für junge Nachtelfen, die Dolanaar verlassen, bietet die Unterstützung von Gaerolas einen ernüchternden Einblick darin, wie tief die Verderbnis bereits in Teldrassils heiliges Geäst eingedrungen ist."},sec={{t="Wächter der Schlafenden",b="Inmitten der unruhigen Siedlung Sternenhauch trägt Gaerolas Talvethren die feierliche Pflicht, die Schlafenden Druiden zu beschützen, die im Einklang mit dem Smaragdgrünen Traum ruhen. Seine Wachsamkeit wird immer mühsamer, da unnatürliche Verderbnis durch den Wald kriecht und das Gleichgewicht von Teldrassil stört."},{t="Die Bedrohung der Gnarlpine",b="Gaerolas weist Reisende an, den Stamm der Gnarlpine-Furbolgs zurückzudrängen, deren Verstand dem Wahnsinn und der Wildheit anheimgefallen ist. Indem er das Verderben untersucht, das von ihren Schamanen ausgeht, und die Wurzeln ihrer Pein ergründet, hofft er, die verbliebene Unversehrtheit des östlichen Teldrassil zu bewahren."}},faq={{q="Wer ist Gaerolas Talvethren?",a="Er ist ein Verteidiger der Nachtelfen, der in Sternenhauch stationiert ist, um die schlafenden Druiden zu beschützen und der seltsamen Verderbnis nachzugehen, die dieses Gebiet heimsucht.",al={"gaerolas","wer ist gaerolas","gaerolas rolle"}},{q="Wo finde Ich Gaerolas Talvethren?",a="Er befindet sich in Sternenhauch, im östlichen Geäst von Teldrassil, östlich von Dolanaar.",al={"gaerolas aufenthaltsort","wo ist gaerolas talvethren","gaerolas finden"}},{q="Wer sind „die Schlafenden“, die Gaerolas beschützt?",a="Die Schlafenden bezieht sich auf die Nachtelfendruiden, die sich in Grabhügeln und Zufluchten in einen langen Schlaf begaben, um den Smaragdgrünen Traum zu durchwandern, wodurch ihre physischen Körper ungeschützt vor weltlicher Gefahr blieben.",al={"die schlafenden","wer sind die schlafenden","schlafende druiden"}},{q="Welche Bedrohungen beunruhigen Gaerolas?",a="Er ist zutiefst besorgt über die Verderbnis, die die einheimische Tierwelt befällt, und die plötzliche, von Wahnsinn erfüllte Feindseligkeit des Stammes der Gnarlpine-Furbolgs.",al={"starbreeze bedrohungen","gaerolas quests","gnarlpine probleme"}}},fx={["52ffd6bd"]={q="Auf wessen Seite steht Gaerolas Talvethren?",a="Gaerolas steht fest an der Seite der Nachtelfen von Darnassus und der Allianz. Als geschworener Wächter der schlummernden Druiden, die in Sternenhauch ruhen, liegt seine Loyalität beim Zirkel des Cenarius, seinem Volk und der Verteidigung von Teldrassil.",al={"gaerolas fraktion","wem dient gaerolas","gaerolas loyalität"}},["436c9e7a"]={q="Was will Gaerolas Talvethren?",a="Gaerolas möchte die schlummernden Druiden vor den korrumpierenden Kräften schützen, die in Sternenhauch eindringen. Er bittet Euch um Hilfe bei der Untersuchung der beunruhigenden Fäulnis, die sich in der Gegend ausbreitet, und bei der Ausrottung der Aggression der korrumpierten Gnarlpine-Furbolgs.",al={"gaerolas ziel","was versucht gaerolas","gaerolas zweck"}},["9c3b08f8"]={q="Warum ist Gaerolas Talvethren hier?",a="Gaerolas bleibt in Sternenhauch stationiert, da er der designierte Beschützer der Schlafenden ist. Während die Druiden im Smaragdgrünen Traum kommunizieren, sind sie physischen Gefahren völlig schutzlos ausgeliefert, weshalb Gaerolas Wache gegen jegliche äußere Bedrohung hält.",al={"warum ist gaerolas in sternenhauch","grund für gaerolas anwesenheit","warum ist gaerolas talvethren hier"}}},fp="19,256,24.310.0,20.292.0,27.169.0,37.91.0,46.185.0,41.136.0"}
P.entries["npc:gakin-the-darkbinder"] = {n="Gakin der Dunkelbinder",s="Gakin der Dunkelbinder ist ein Hexenmeistermeister, der im Verborgenen tief unter der Taverne „Zum Geschlachteten Lamm“ im Magierviertel von Sturmwind operiert. Er unterweist aufstrebende Praktizierende der Allianz in den dunklen Künsten und prüft ihre Entschlossenheit, bevor er Rituale einleitet, um jenseitige Dämonen zu beschwören und an ihren Dienst zu binden.",h="Gakin der Dunkelbinder ist ein Hexenmeistermeister, der im Verborgenen tief unter der Taverne „Zum...",kw={"dunkelbinder","gakin","das magierviertel","slaughtered lamb","sukkubus","surena caledon","leerwandler","hexenmeister"},ang={["class:Warlock"]="Gakin ist ein lebenswichtiger Mentor für Menschen- und Gnomen-Hexenmeister, der entscheidende Klassenquests anbietet, um die Rituale für Leerwandler und Sukkuben in den Krypten von Sturmwind zu meistern.",["faction:Alliance"]="Gakins Zirkel, der heimlich unter der Hauptstadt operiert, verdeutlicht die pragmatischen, schattendurchtränkten Kompromisse, die im Herzen der Allianz eingegangen werden."},sec={{t="Ein geheimer Versammlungsort",b="Während Sturmwinds Magier offen in ihren hoch aufragenden Heiligtümern praktizieren, müssen die Anwender von Schatten und Teufelsmagie dort verweilen, wo neugierige Blicke sie nicht erreichen können. Verborgen unter der Schankstube von „Zum Geschlachteten Lamm“ liegt ein feuchter, kryptaartiger Keller, der mit Beschwörungskreisen und düsteren Folianten ausgestattet ist. Gakin dient als Anker dieses verborgenen Konklaves und stellt sicher, dass junge Hexenmeister Disziplin und Zurückhaltung lernen, bevor sie Schrecken entfesseln, die sie nicht kontrollieren können."},{t="Meister der Dämonen",b="Gakins Fachwissen liegt in der Dämonologie und in Bindungsritualen. Initianden, die seine Aufmerksamkeit erlangen, werden durch das gesamte Königreich geschickt, um seltene Relikte und Zutaten zu beschaffen – von gestohlenen Blutsteintalismanen bis hin zu verderbtem Holz aus den dunklen Wäldern. Sobald die Reagenzien versammelt sind, beaufsichtigt Gakin die Rituale im Beschwörungskreis der Krypta und zwingt die Novizen dazu, Leerwandler und Sukkuben in Willensprüfungen auf Leben und Tod zu unterwerfen."},{t="Verrat und lose Fäden",b="Nicht alle Schüler Gakins bleiben gehorsam. Eine ehemalige Schülerin, Surena Caledon, machte sich mit einem wertvollen Blutsteinhalsreif davon und floh in die Wildnis. Ein solcher interner Verrat droht den Zirkel der Hexenmeister vor den Stadtwachen zu enttarnen, was Gakin dazu veranlasst, treue Anhänger auszusenden, um verlorene Artefakte wiederzubeschaffen und lose Fäden zum Schweigen zu bringen, bevor die Behörden Verdacht schöpfen."}},faq={{q="Wo kann ich Gakin den Dunkelbinder finden?",a="Gakin befindet sich tief unter der Taverne „Zum Geschlachteten Lamm“ im Magierviertel von Sturmwind. Geht in die Taverne hinein, sucht die Rampe nach unten im hinteren Bereich und steigt durch die Steintunnel hinab, bis Ihr den Beschwörungskreis in der untersten Krypta erreicht.",al={"wo ist gakin","gakin aufenthaltsort","zum geschlachteten lamm keller"}},{q="Was tut Gakin der Dunkelbinder?",a="Er dient als prominenter Questgeber und Mentor für Hexenmeister-Charaktere der Allianz. Er prüft Novizen, indem er sie auf Prüfungen quer durch Azeroth schickt und ihnen beibringt, wie man Dämonen wie den Leerwandler und die Sukkubus beschwört und bindet.",al={"was macht gakin","gakin rolle","gakin quests"}},{q="Warum werden Hexenmeister unter „Zum Geschlachteten Lamm“ geduldet?",a="Dämonische Magie ist in Sturmwind verboten und stößt auf tiefes Misstrauen. Die Praktizierenden unter „Zum Geschlachteten Lamm“ agieren in strenger Geheimhaltung und werden nur als gefährlicher, verdeckter Vorposten geduldet – verborgen vor den Wachen und Bürgern der Stadt.",al={"warum hexenmeister erlaubt sind","sind hexenmeister in sturmwind legal","zum geschlachteten lamm lore"}},{q="Wer ist Surena Caledon?",a="Surena Caledon war eine ehemalige Schülerin von Gakin, die ihm einen mächtigen Blutsteinhalsreif stahl. Ihr Verrat stellt eine Gefahr für ihren verborgenen Orden dar, weshalb Gakin Hexenmeister damit beauftragt, sie aufzuspüren.",al={"surena caledon","gakin schüler","wer bestahl gakin"}},{q="Welche Dämonen hilft Gakin zu beschwören?",a="Gakin überwacht die Bindungsrituale für Leerwandler und Sukkuben und leitet Hexenmeister an, die Kreaturen in den unterirdischen Kreis zu rufen und sie zu unterwerfen.",al={"gakin dämonen","gakin leerwandler","gakin sukkubus"}},{q="Wer ist Strahad und warum erwähnt Gakin ihn?",a="Strahad Farsan ist ein erfahrener Hexenmeister, der in den Hügeln von Ratschet auf Kalimdor weilt. Sobald ein Schüler Gakins grundlegende Bindungsrituale gemeistert hat, schickt Gakin ihn über das Meer, um seine finstere Ausbildung bei Strahad fortzusetzen.",al={"strahad","die suche nach strahad","wohin schickt mich gakin als nächstes"}}},fx={["5c1d997e"]={q="Wer ist Gakin der Dunkelbinder?",a="Gakin der Dunkelbinder ist ein mächtiger menschlicher Hexenmeister, der sich tief in den Krypten unterhalb von The Slaughtered Lamb im Das Magierviertel von Sturmwind verbirgt. Fernab der neugierigen Blicke der Stadtwache und der Kirin Tor leitet er junge Praktizierende der Teufelsmagie an und weist sie in die gefährlichen Riten ein, die erforderlich sind, um jenseitige Dämonen ihrem Willen zu unterwerfen.",al={"wer ist gakin","identität gakin","gakin hintergrundgeschichte"}},a5302178={q="Auf wessen Seite steht Gakin der Dunkelbinder?",a="Gakin arbeitet in loser Verbindung im Dienste der Allianz und bildet menschliche und gnomische Praktizierende darin aus, dämonische Kräfte für ihr eigenes Überleben als Waffe einzusetzen. Doch wie bei den meisten Meistern der dunklen Künste bleibt seine endgültige Loyalität verborgen, gehüllt in Schatten, Geheimnisse und das Streben nach verbotenem Wissen, fernab der Kontrolle der Herrscher von Sturmwind.",al={"ist gakin bei der allianz","loyalität gakin","wem dient gakin"}},["503bf85b"]={q="Was will Gakin der Dunkelbinder?",a="Gakin möchte seine Meisterschaft über die Teufelsmagie erweitern und sicherstellen, dass aufstrebende Hexenmeister die Entschlossenheit besitzen, größere Dämonen zu binden, anstatt von ihnen verschlungen zu werden. Er arbeitet zudem im Stillen daran, gestohlene Machtartefakte wiederzuerlangen, wie etwa einen geraubten Blutsteinhalsreif, der von seinem abtrünnigen ehemaligen Schüler gestohlen wurde.",al={"was will gakin","gakin ziele","gakin motive"}}},fp="20,297,24.429.0,16.411.0,24.365.1,38.247.0,34.223.0,52.230.0,22.201.0,36.153.0,46.232.0"}
P.entries["npc:galgar"] = {n="Galgar",s="Galgar ist ein Orc-Koch, der im Tal der Prüfungen in Durotar stationiert ist. Er bereitet Vorräte für junge Rekruten zu, die ihre ersten Schritte im Dienst der Horde machen. Um Neulingen die Grundlagen der Nahrungssuche in der rauen Wüste beizubringen, beauftragt er sie damit, wilde Kaktusäpfel für sein Spezialgericht zu sammeln.",h="Galgar ist ein Orc-Koch, der im Tal der Prüfungen in Durotar stationiert ist.",kw={"kaktusapfel surprise","kaktusäpfel","koch","durotar","galgar","horde rekrut","das tal der prüfungen"},ang={["profession:Cooking"]="Galgar verkörpert die praktische, rustikale Küche der Horde, die Durotars karge natürliche Ressourcen nutzt, um Rekruten satt und kampfbereit zu halten.",["race:Orc"]="Für junge Orcs, die ihre ersten Schritte im Tal der Prüfungen machen, ist eine Besorgung für Galgar ein vertrauter Übergangsritus, bevor sie sich gefährlicheren Bedrohungen in der Wildnis stellen."},sec={{t="Ein Koch im Tal",b="In der Nähe der Feuerstelle beim Höhlenbau im Tal der Prüfungen versorgt Galgar junge Orcs und Trolle, die ihre ersten Übergangsriten durchlaufen, mit Nahrung. Durotar ist ein trockenes, unbarmherziges rotes Ödland, in dem jeder Bissen Nahrung der Landschaft abgerungen werden muss. Indem er unerfahrene Krieger damit beauftragt, reife Kaktusfrüchte zu sammeln, stellt Galgar ihre Aufmerksamkeit und Zähigkeit auf die Probe und hält gleichzeitig seine Küche gefüllt."},{t="Kaktusapfel Surprise",b="Galgars Spezialrezept ist als Kaktusapfel Surprise bekannt. Obwohl er offen zugibt, dass die Suche nach stacheligen Wüstenfrüchten eine bewusst einfache Aufgabe ist, die neuen Rekruten den Einstieg in das Leben als Abenteurer erleichtern soll, bleibt das Endprodukt eine unverzichtbare Ration für hungrige Auszubildende. Selbst der abgehärtetste Krieger der Horde muss irgendwo anfangen, und unter Galgars wachsamen Augen beginnt diese Reise mit der Nahrungssuche in der Wüste."}},faq={{q="Wo kann ich Galgar finden?",a="Galgar befindet sich im Tal der Prüfungen, dem Startgebiet für Orcs und Trolle im südwestlichen Durotar. Er steht nahe dem zentralen Lagerfeuer und dem Kochbereich vor dem Höhlenbau.",al={"galgar aufenthaltsort","wo ist galgar","galgar koordinaten"}},{q="Worum bittet Galgar Abenteurer?",a="Er bittet neue Abenteurer darum, reife Kaktusäpfel von den wilden Kakteen zu sammeln, die im Tal der Prüfungen verstreut sind, damit er seine Kaktusapfel Surprise zubereiten kann.",al={"galgar quest","was will galgar"}},{q="Warum schickt Galgar neue Rekruten los, um Früchte zu pflücken?",a="Galgar gibt zu, dass die Aufgabe bewusst einfach gehalten ist. Sie dient frischgebackenen Kämpfern als leichte Einstiegsaufgabe, um sich im Tal zurechtzufinden und Selbstversorgung in der rauen Wildnis von Durotar zu üben.",al={"warum kaktusäpfel","galgar prüfung"}},{q="Was ist Kaktusapfel Surprise?",a="Es ist Galgars Spezialrezept, hergestellt aus frischen Kaktusäpfeln, die aus der einheimischen Wüstenflora Durotars gesammelt wurden, um neue Rekruten zu stärken.",al={"was ist kaktusapfel surprise","galgar essen"}}},fx={["115dfff8"]={q="Wer ist Galgar?",a="Galgar ist ein Orc-Koch, der im Tal der Prüfungen in Durotar stationiert ist. Anstatt Krieger im brutalen Kampf auszubilden, unterstützt er die Siedlung durch die Zubereitung herzhafter Proviante, vor allem seiner wohlbekannten Kaktusapfel Surprise.",al={"wer ist galgar","galgar hintergrund","wer galgar"}},["7f3ad096"]={q="Auf wessen Seite steht Galgar?",a="Galgar ist der Horde von Thrall treu ergeben. Er dient im Tal der Prüfungen und kümmert sich direkt um die jungen Orcs und Trolle, die ihre ersten Schritte im Dienste Durotars machen.",al={"galgars fraktion","gehört galgar zur horde","galgars loyalität"}},d4d57a6c={q="Was will Galgar?",a="Galgar will frische Zutaten – hauptsächlich die reifen Kaktusäpfel, die im gesamten trockenen Tal wachsen –, damit er Portionen seiner Kaktusapfel Surprise zubereiten kann, um die jungen Rekruten satt und energiegeladen zu halten.",al={"was braucht galgar","galgars ziel","galgar möchte"}},["50f967f0"]={q="Warum ist Galgar hier im Tal der Prüfungen?",a="Galgar ist im Tal der Prüfungen stationiert, um die Küche des Lagers zu unterstützen. Während Ausbilder die Anwärter in der Kunst des Krieges unterrichten, stellt Galgar sicher, dass das Gelände mit Nahrung versorgt bleibt, und führt Neuankömmlinge in grundlegende Feldarbeit ein.",al={"warum ist galgar hier","grund für galgars anwesenheit im tal der prüfungen","warum ist galgar in durotar"}},["2e1d8215"]={q="Warum ist Galgar berühmt?",a="Galgar ist im gesamten Tal der Prüfungen für sein berühmtes Rezept, Kaktusapfel Surprise, bekannt. Fast jeder junge Rekrut, der durch The Den zieht, probiert seine Kochkünste, während er erste kleine Aufgaben für ihn erledigt.",al={"ist galgar berühmt","wofür ist galgar bekannt","galgars bekanntheit"}}},fp="6,294,20.415.0,21.418.0,24.177.0,39.157.0,48.211.0,30.139.0"}
P.entries["npc:gan-rul-bloodeye"] = {n="Gan'rul Blutauge",s="Gan'rul Blutauge ist ein hochrangiger Hexenmeisterausbilder der Orcs, der tief in der dunklen Kaverne von der Kluft der Schatten in Orgrimmar residiert. Vor den wachsamen Augen der Stadt über ihm verborgen, führt er Hexenmeister der Horde in dunklere dämonische Riten ein. Unter seiner Anleitung lernen die Initianden, jenseitige Wesen wie Leerwandler und Sukkubi ihrem Willen zu unterwerfen.",h="Gan'rul Blutauge ist ein hochrangiger Hexenmeisterausbilder der Orcs, der tief in der dunklen Kaverne von der...",kw={"bloodeye","die kluft der schatten","gan'rul","orgrimmar","sukkubus","ausbilder","leerwandler","hexenmeister"},ang={["class:Warlock"]="Für Hexenmeister, die nach verbotenem Wissen suchen, ist Gan'rul ein wichtiger Mentor in Kalimdor, der das Wissen und die Prüfungen bereitstellt, die erforderlich sind, um Leerwandler und Sukkubi zu binden.",["faction:Horde"]="Gan'rul verkörpert die prekäre Stellung der Teufelsmagie in Thralls Horde – sie wird für militärische Stärke genutzt, ist aber in die unterirdischen Winkel der Hauptstadt verbannt."},sec={{t="Ein Meister in den Schatten",b="Während Kriegshäuptling Thrall die Anwesenheit von Hexenmeistern in der neuen Horde toleriert, sind ihre dunklen Künste im offenen Sonnenlicht von Durotar nicht willkommen. Gan'rul Blutauge hat sein Zuhause in der Kluft der Schatten, einem unterirdischen Zufluchtsort unter Orgrimmar, wo Schattenweber, Schurken und Teufelswirker ungestört studieren können. Von diesem unterirdischen Stützpunkt aus fungiert Gan'rul als primärer Lehrmeister für aufstrebende Praktizierende der Teufelsmagie."},{t="Die Bindung des Nether",b="Gan'ruls Hauptaufgabe ist die Überwachung der gefährlichen Beschwörungsrituale, die von ehrgeizigen Hexenmeistern verlangt werden. Praktizierende, die größere Dämonen – wie den widerstandsfähigen Leerwandler oder den verführerischen Sukkubus – binden wollen, müssen Gan'rul konsultieren, um sich Ritualkomponenten zu sichern und die präzisen Beschwörungsformeln zu erlernen, die nötig sind, um die beschworenen Kreaturen zu beherrschen, bevor sie ihren Meister verzehren."}},faq={{q="Wer ist Gan'rul Blutauge?",a="Gan'rul Blutauge ist ein Hexenmeisterausbilder der Orcs, der in Orgrimmar stationiert ist. Er betreut Hexenmeister-Novizen und Fortgeschrittene der Horde und lehrt sie, wie man Dämonen aus dem Wirbelnden Nether beschwört und bindet.",al={"gan'rul blutauge","wer ist ganrul","rolle von ganrul bloodeye"}},{q="Wo kann ich Gan'rul Blutauge finden?",a="Er befindet sich in der Kluft der Schatten, dem unterirdischen Höhlensystem, das unter Orgrimmar verborgen liegt. Er steht dort zusammen mit anderen dunklen Praktizierenden, abseits der Hauptverkehrswege der Stadt.",al={"standort von ganrul","wo ist gan'rul blutauge","wo ist der ausbilder in die kluft der schatten"}},{q="Warum sind Hexenmeister in der Kluft der Schatten verborgen?",a="Kriegshäuptling Thrall und die schamanistische Gesellschaft der neuen Horde misstrauen der Teufelsmagie und der dämonischen Verderbnis aufgrund der vergangenen Versklavung der Orcs zutiefst. Hexenmeister sind innerhalb der Horde lediglich aufgrund ihres Nutzens geduldet, doch ihre Praxis ist in die Schatten verbannt, um zivile Unruhen zu vermeiden.",al={"warum in höhlen","warum werden hexenmeister versteckt","hintergrundwissen zu die kluft der schatten"}},{q="Welche Dämonen hilft Gan'rul zu beschwören?",a="Gan'rul leitet Hexenmeister durch die Rituale, die erforderlich sind, um sowohl den Leerwandler als auch den Sukkubus zu beschwören und zu unterwerfen. Das Abschließen seiner Aufgaben beweist, dass der Beschwörer über die notwendige Willenskraft verfügt, um diese Unholde zu kontrollieren.",al={"dämonen die ganrul lehrt","dämonenquests von ganrul","ausbilder für leerwandler und sukkubus"}},{q="Hat Gan'rul bekannte Verwandte?",a="Er teilt sich einen Nachnamen mit Halga Bloodeye, wenngleich ihre genaue Verwandtschaftsbeziehung nicht offiziell dokumentiert ist.",al={"verwandte von gan'rul","verwandter halga bloodeye"}},{q="Wer ist Strahad, den Gan'rul erwähnt?",a="Strahad Farsan ist ein versierter Hexenmeister, der im Brachland in der Nähe der Hügel bei Ratschet lebt. Gan'rul schickt vielversprechende Schüler schließlich zu Strahad für fortgeschrittenere Unterweisungen und größere Herausforderungen.",al={"die suche nach strahad","wer ist strahad","strahad quest"}}},fx={["11e29292"]={q="Auf wessen Seite steht Gan'rul Blutauge?",a="Gan'rul Blutauge dient der Horde und bildet Praktizierende der dunklen Magie unter Thralls Hauptstadt aus. Obwohl Hexenmeister von der schamanistischen Führung mit tiefem Misstrauen betrachtet werden, stellt Gan'rul seine arkanen Künste in den Dienst des Überlebens und der Stärke der Horde und unterweist jene, die bereit sind, Teufelsenergien zu ihrer Verteidigung zu nutzen.",al={"fraktion von gan'rul blutauge","loyalität von gan'rul","wem dient gan'rul"}},["67b7b1ae"]={q="Was will Gan'rul Blutauge?",a="Gan'rul will die Reihen fähiger Hexenmeister der Horde erweitern, indem er Initianden prüft und sie in der Beherrschung des Wirbelnden Nether unterweist. Er fordert Disziplin und okkulten Fokus und leitet Lehrlinge dazu an, gefährliche dämonische Entitäten wie Leerwandler und Sukkubi zu binden, damit die dunkle Magie als gehorsame Waffe dient und keine alles verzehrende Bedrohung darstellt.",al={"ziele von gan'rul","was will gan'rul","zweck von gan'rul"}}},fp="16,344,23.407.0,18.364.0,24.187.0,34.188.0,47.285.0,37.219.0,35.100.0,38.198.0"}
P.entries["npc:gann-stonespire"] = {n="Gann Steinkeil",s="Gann Steinkeil ist ein gekränkter Taurennomade, der auf den Straßen des Südlichen Brachlands nahe Bael Modan umherzieht. Von den Ausgräbern der Zwerge aus den angestammten Jagdgründen seines Stammes vertrieben, sinnt er auf Vergeltung gegen die vordringende Ausgrabungsstätte.",h="Gann Steinkeil ist ein gekränkter Taurennomade, der auf den Straßen des Südlichen Brachlands nahe Bael Modan...",kw={"bael modan","bael'dun","gann steinkeil","prospector khazgorm","südliches brachland","stonespire"},ang={["faction:Horde"]="Gann beizustehen bietet der Horde eine wichtige taktische Gelegenheit, den Expansionsdrang der im Südlichen Brachland verschanzten Allianz einzudämmen.",["race:Tauren"]="Ganns Not steht sinnbildlich für den größeren Kampf der nomadischen Tauren, deren angestammte Weiten und heilige Erde wiederholt von fremden Allianz-Expeditionen geschändet werden."},sec={{t="Vertrieben aus Bael Modan",b="Bevor die Zwergenexpedition aus Eisenschmiede eintraf, um die Festung Bael Modan zu errichten, diente das umliegende Land als angestammtes Territorium und Jagdgebiet für den Stamm von Gann Steinkeil. Die Zwergenbergarbeiter vertrieben die einheimischen Tauren mit Spitzhacken, Schusswaffen und schwerem Gerät von ihrem Boden und wiesen friedliche Annäherungsversuche zurück. Nun lagert Gann an der staubigen Straße des Südlichen Brachlands und weigert sich, sein Erbe kampflos aufzugeben, während er Reisende dazu bewegt, gegen die Ausgräber zurückzuschlagen."},{t="Rückforderung und Sabotage",b="In der Erkenntnis, dass friedliche Diplomatie völlig gescheitert ist, weist Gann Agenten der Horde an, den Zwergen die Kontrolle über die Ausgrabungsstätte zu entreißen. Seine Vergeltung zielt auf die Schlüsselfiguren der Expeditionsführung ab, insbesondere Prospector Khazgorm, bevor er zwergisches Sprengpulver und Munition zu einem Sprengsatz umfunktioniert. Indem er die Vorrichtung direkt unter der Zwergenflugmaschine zündet, will Gann deren technologischen Vorteil zunichtemachen und die Ehre seines vertriebenen Volkes wiederherstellen."}},faq={{q="Wer ist Gann Steinkeil?",a="Gann Steinkeil ist ein Taurenkrieger, dessen Stamm einst die Ländereien bewohnte, die heute von der Zwergenfestung Bael Modan besetzt sind. Nachdem er vertrieben wurde, als die Zwerge ihre Ausgrabungsstätte errichteten, wartet er nun am Straßenrand im Südlichen Brachland und sucht nach Rache sowie der Rückforderung der Heimat seines Volkes.",al={"wer ist gann","gann steinkeil lore","tauren vor bael modan"}},{q="Warum kämpft Gann gegen die Zwerge von Bael Modan?",a="Die Zwergenexpedition von Bael'dun traf im Südlichen Brachland ein und vertrieb die ansässigen Tauren gewaltsam aus ihren angestammten Jagdgründen, um ihre Ausgrabungsfestung zu errichten. Nachdem die Zwerge alle diplomatischen Bemühungen abgelehnt hatten, beschloss Gann, ihr Vorhaben mit Gewalt zu zerschlagen.",al={"warum hasst gann zwerge","warum bael modan angreifen","gann bael modan konflikt"}},{q="Was ist Ganns Plan gegen die Ausgrabung?",a="Gann fordert zunächst den Tod zwergischer Aufseher, darunter Prospector Khazgorm, um Ausgrabungsaufzeichnungen an sich zu bringen. Mithilfe gestohlener Zwergenmunition und Sprengvorräten veranlasst er anschließend den Bau einer Bombe, um die Flugmaschine der Expedition zu zerstören und deren technologische Vormachtstellung zu brechen.",al={"ganns racheplan","was macht gann","bael modan bombe"}},{q="Wo schlägt Gann Steinkeil sein Lager auf?",a="Er zieht auf der Straße knapp westlich von Bael Modan im Südlichen Brachland umher, direkt vor den Grenzen der Ausgrabungsstätte.",al={"wo ist gann","gann steinkeil standort"}}},fx={["60933082"]={q="Auf wessen Seite steht Gann Steinkeil?",a="Gann steht auf der Seite der Horde und seiner taurenischer Mitbrüder. Er bittet Horde-Champions, die das Südliche Brachland durchqueren, um Hilfe, um gegen die Bael'dun-Zwerge zurückzuschlagen, die in die heiligen Stätten seines Volkes eindringen.",al={"gehört gann steinkeil zur horde","fraktion von gann steinkeil","für wen kämpft gann"}},["59c620b8"]={q="Mit wem ist Gann Steinkeil verbunden?",a="Gann gehört einem Taurenstamm an, dessen angestammte Heimat die Ländereien umfasste, die nun von Bael Modan besetzt sind. Er handelt im Namen seines vertriebenen Volkes, das durch den Beginn der zwergischen Ausgrabungen vertrieben wurde.",al={"stamm von gann steinkeil","wer sind ganns leute","clan von gann steinkeil"}}},fp="15,239,25.485.0,24.466.1,23.308.0,47.289.0,43.297.1,41.134.0"}
P.entries["npc:gar-thok"] = {fx={["61b8b646"]={q="Auf wessen Seite steht Gar'Thok?",a="Gar'Thok ist der Horde und Kriegshäuptling Thrall voll und ganz loyal. Er ist in Durotar unter dem Kommando von Nazgrel stationiert und arbeitet unermüdlich daran, die entstehende Heimat der Orcs zu verteidigen und sicherzustellen, dass neu eingetroffene Krieger bereit sind, die Grenzen der Horde zu schützen.",al={"fraktion von gar'thok","gehört gar'thok zur horde","wem dient gar'thok"}},["7b499593"]={q="Was will Gar'Thok?",a="Gar'Thok will Durotar fest gegen alle Bedrohungen gesichert sehen. Nachdem er mit ansehen musste, wie sein Außenposten von Invasoren aus Kul Tiras niedergemetzelt wurde, sinnt er auf Rache an den verbliebenen menschlichen Seeleuten an der Küste und fordert die Unterdrückung der eindringenden Stacheleber, die die Siedlung bedrängen.",al={"ziel von gar'thok","was will gar'thok","motive von gar'thok"}},["007248aa"]={q="Warum ist Gar'Thok hier?",a="Nach der Verwüstung seines Küstenaußenpostens durch Streitkräfte aus Kul Tiras bezog Gar'Thok einen Posten in Klingenhügel. Von dieser zentralen Siedlung aus organisiert er die Verteidigung von Durotar und leitet angehende Horde-Champions gegen feindliche Übergriffe.",al={"warum ist gar'thok in klingenhügel","warum ist gar'thok hier","aufgabe von gar'thok in klingenhügel"}}}}
P.entries["npc:gart-mistrunner"] = {n="Gart Nebelläufer",s="Gart Nebelläufer ist der ansässige Druidenlehrer in Camp Narache auf der Hochwolkenebene. Er heißt Tauren-Neulinge willkommen, die von der Erdenmutter gerufen wurden, und leitet sie durch ihre ersten Riten der Naturmagie.",h="Gart Nebelläufer ist der ansässige Druidenlehrer in Camp Narache auf der Hochwolkenebene.",kw={"camp narache","druidenlehrer","gart nebelläufer","mistrunner","mulgore","die hochwolkenebene","taurendruide"},ang={["class:Druid"]="Für Taurendruiden ist Gart Nebelläufer der allererste Lehrmeister, der ihren Bund mit der Wildnis und die Gaben der Erdenmutter prägt.",["race:Tauren"]="Gart verkörpert das Wiederaufleben der uralten druidischen Traditionen der Shu'halo und gibt das Wissen der Ahnen an die Jugend von Camp Narache weiter."},sec={{t="Mentor der Hochwolkenebene",b="Gart Nebelläufer wacht über Camp Narache und verkörpert den uralten druidischen Pfad, der unter den Shu'halo neu entfacht wurde. Neue Taurendruiden werden bei ihren ersten Schritten auf der Hochwolkenebene direkt zu Gart geschickt, oft mit einer Tiefgrünen Notiz, die sie seiner Obhut anvertraut. Durch seine geduldige Führung lernen junge Praktizierende, mit der natürlichen Welt in Einklang zu treten, und schöpfen aus den wiederherstellenden Kräften der Natur und dem Mondglanz von Mu'sha, um ihre Verbündeten zu heilen und Bedrohungen des Landes niederzustrecken."}},faq={{q="Wer ist Gart Nebelläufer?",a="Gart Nebelläufer ist ein Tauren-Druidenlehrer in Camp Narache auf der Hochwolkenebene in Mulgore. Er unterweist angehende Taurendruiden in ihren ersten Zaubern und Riten.",al={"wer ist gart","gart nebelläufer hintergrundgeschichte","gart nebelläufer"}},{q="Welche Zauber lehrt er neu erwachten Druiden?",a="Gart führt Anfänger an grundlegende Naturfähigkeiten heran und lehrt frühe Heilzauber wie Heilende Berührung sowie offensive Naturmagie wie Mondfeuer.",al={"was lehrt gart","gart nebelläufer ausbildung","druidenzauber camp narache"}},{q="Was ist seine Verbindung zum Mistrunner-Clan?",a="Mistrunner ist schlicht Garts Familienname. Es gibt keine Überlieferungen, die einen Mistrunner-Stamm beschreiben oder mehr über seine Verwandtschaft verraten; er ist lediglich als Druidenlehrer von Camp Narache bekannt.",al={"mistrunner clan","wer sind die mistrunner"}}},fx={fd7992e7={q="Auf wessen Seite steht Gart Nebelläufer?",a="Gart Nebelläufer ist den Taurenstämmen ergeben und steht auf der Seite der Horde. Stationiert im Herzen der Hochwolkenebene in Camp Narache, arbeitet er in seiner angestammten Heimat daran, die Traditionen der Tauren zu bewahren, und fördert junge Praktizierende, die die Gaben der Natur nutzen, um das Land zu schützen und ihrem Volk zu dienen.",al={"fraktion von gart nebelläufer","wem dient gart","gart nebelläufer horde"}},["4b2be6b9"]={q="Warum ist Gart Nebelläufer hier?",a="Gart lebt in Camp Narache, um angehende Tauren zu unterweisen, die den Ruf der Wildnis hören. Als Druidenausbilder auf der Hochwolkenebene führt er neu erwachte Initianden in die Lehren der Natur ein und leitet ihre frühe spirituelle und kämpferische Entwicklung, bevor sie sich in die weiteren Ebenen von Mulgore hinauswagen.",al={"warum ist gart in camp narache","zweck von gart nebelläufer","was macht gart nebelläufer hier"}},["8def0ffd"]={q="Was will Gart Nebelläufer?",a="Gart will die Harmonie zwischen den Tauren und der Erdenmutter fördern, indem er neue Druiden im natürlichen Gleichgewicht ausbildet. Er möchte, dass junge Initianden frühe Riten wie verjüngende Heilung und Gleichgewichtszauber meistern, um sie darauf vorzubereiten, das Land zu heilen und ihren Stamm gegen eindringende Bedrohungen zu verteidigen.",al={"ziele von gart nebelläufer","was will gart","motive von gart nebelläufer"}}},fp="15,206,28.505.0,23.168.0,48.150.0,46.160.0"}
P.entries["npc:gath-ilzogg"] = {n="Gath'Ilzogg",s="Gath'Ilzogg ist der furchterregende Kriegsfürst der Schwarzfelsorks, der die Invasionsstreitmacht anführt, die Burg Steinwacht im Rotkammgebirge besetzt hält. Unter seiner brutalen Führung eroberten die Orks die Festung und starteten verheerende Überfälle auf die Stadt Seenhain, was ihm ein dringendes Kopfgeld des verzweifelten Magistrats der Stadt einbrachte.",h="Gath'Ilzogg ist der furchterregende Kriegsfürst der Schwarzfelsorks, der die Invasionsstreitmacht anführt...",kw={"schwarzfels","gath'ilzogg","gathilzogg","seenhain","morganth","singe","solomon","steinwacht","burg steinwacht"},ang={["faction:Alliance"]="Gath'Ilzogg zur Strecke zu bringen bricht das Rückgrat der Schwarzfelsoffensive, die Seenhain bedroht, und folgt dem verzweifelten Ruf von Magistrat Solomon.",["race:Orc"]="Gath'Ilzogg verkörpert die alten, kriegerischen Pfade des Schwarzfelsklans unter der Dunklen Horde, völlig getrennt von Thralls neuer Horde in Kalimdor."},sec={{t="Die Geißel von Steinwacht",b="Gath'Ilzogg marschierte auf Befehl, das Rotkammgebirge für den Schwarzfelsklan zu sichern, aus der Brennenden Steppe nach Norden. Unterstützt von der finsteren Hexerei des abtrünnigen menschlichen Hexenmeisters Morganth überwältigte Gath'Ilzoggs Kriegsschar die Verteidiger von Burg Steinwacht und sicherte sich die Anhöhe, die die gesamte Region überblickt. Aus dieser verschanzten Redoute leitet er aggressive Angriffe in die Täler und hinab zur Brücke von Seenhain, wodurch die menschliche Siedlung zusehends eingeschnürt wird. Er kämpft selten allein und hält elitäre Schwarzfelswachen sowie einen bösartigen schwarzen Drachenwelpen namens Singe stets an seiner Seite."},{t="Ein brüchiger Halt",b="Trotz seiner Eroberung von Steinwacht brachte Gath'Ilzoggs Sieg neue Komplikationen mit sich. Morganth wandte sich rasch gegen seine einstigen orkischen Verbündeten und stellte eine Armee von Schattenfellgnollen unter Leutnant Fangore auf, die gleichermaßen Jagd auf Schwarzfelspatrouillen und menschliche Reisende macht. Gleichzeitig setzte Magistrat Solomon ein offenes Kopfgeld auf den Kopf des Kriegsfürsten aus und bat alle Söldner oder Abenteurer der Allianz inständig darum, die Zinnen von Burg Steinwacht zu erklimmen und Gath'Ilzoggs Schrecken zu beenden, bevor die Stadt gänzlich fällt."}},faq={{q="Wer ist Gath'Ilzogg?",a="Gath'Ilzogg ist ein Kriegsfürst der Orks, der dem Schwarzfelsklan angehört. Er führt die Vorhut an, die in das Rotkammgebirge einfiel und Burg Steinwacht erfolgreich der Allianz entriss.",al={"gath'ilzogg geschichte","wer ist gathilzogg","schwarzfels boss rotkammgebirge"}},{q="Wo ist Gath'Ilzogg zu finden?",a="Er hat sich ganz oben auf Burg Steinwacht verschanzt, die in den östlichen Klippen des Rotkammgebirges liegt.",al={"gath'ilzogg aufenthaltsort","wo ist gathilzogg","gathilzogg finden"}},{q="Warum hat Gath'Ilzogg einen Drachenwelpen?",a="Gath'Ilzogg wird von einem schwarzen Drachenwelpen namens Singe begleitet, von dem weithin angenommen wird, dass er ein Geschenk von Lord Victor Nefarius war, um den Kriegsfürsten für die erfolgreiche Einnahme von Burg Steinwacht zu belohnen.",al={"warum welpe bei gathilzogg","singe drache","schwarzer drachenwelpe gathilzogg"}},{q="Warum ist ein Kopfgeld auf ihn ausgesetzt?",a="Magistrat Solomon von Seenhain setzte ein hochdotiertes Kopfgeld auf Gath'Ilzoggs Kopf aus, weil die ständigen Überfälle des Kriegsfürsten und die Besetzung von Steinwacht Seenhain unmittelbar mit der völligen Zerstörung bedrohen.",al={"gesucht gath'ilzogg","wer will gathilzogg tot sehen","magistrat solomon kopfgeld"}},{q="Was geschah zwischen Gath'Ilzogg und Morganth?",a="Der menschliche Hexenmeister Morganth half Gath'Ilzogg anfangs mit dunkler Magie bei der Eroberung von Steinwacht. Doch sobald die Festung gefallen war, verriet Morganth die Orks und stellte eine Armee von Schattenfellgnollen auf, um sowohl die Menschheit als auch den Schwarzfelsklan anzugreifen.",al={"morganth gathilzogg allianz","warum greifen gnolle orks an","morganth verrat"}}},fx={["9f2c44f6"]={q="Auf wessen Seite steht Gath'Ilzogg?",a="Gath'Ilzogg ist ein Kriegsfürst des Schwarzfelsklans, loyal zur Dunklen Horde, die im Schwarzfels verwurzelt ist. Er und seine Streitkräfte führen aktiv Krieg gegen das Königreich Sturmwind und zeigen äußerste Feindseligkeit gegenüber der Allianz und jedem, der ihr erobertes Gebiet betritt.",al={"fraktion von gath'ilzogg","wem dient gath'ilzogg","gehört gath'ilzogg zum schwarzfelsclan"}},["56c8e0ec"]={q="Was will Gath'Ilzogg?",a="Von seiner Festung in Burg Steinwacht aus plant Gath'Ilzogg die Zerstörung von Seenhain und die vollständige Eroberung des Rotkammgebirges. Er leitet Überfälle auf menschliche Siedlungen und arbeitet daran, die Herrschaft des Schwarzfelsklans über die umliegenden Ländereien auszuweiten.",al={"was ist gath'ilzoggs ziel","plan von gath'ilzogg","warum greift gath'ilzogg an"}},d3a450f6={q="Warum ist Gath'Ilzogg hier?",a="Gath'Ilzogg führte den Angriff an, der die Verteidiger der Allianz in Burg Steinwacht überwältigte. Nachdem er die Festung eingenommen hat, nutzt er sie nun als befestigte Operationsbasis, um tiefer in das Rotkammgebirge vorzustoßen und Überfälle auf Seenhain zu organisieren.",al={"warum ist gath'ilzogg im rotkammgebirge","warum ist gath'ilzogg in burg steinwacht","gath'ilzogg burg steinwacht"}},d6829113={q="Mit wem ist Gath'Ilzogg verbunden?",a="Über das Kommando über die örtlichen Schwarzfels-Orcs hinaus ging Gath'Ilzogg einst ein tückisches Bündnis mit dem abtrünnigen menschlichen Hexenmeister Morganth ein, um Burg Steinwacht einzunehmen. Er befehligt außerdem den Welpen Seng, eine Kreatur, die ihm wahrscheinlich von Lord Victor Nefarius als Belohnung für seinen Sieg überlassen wurde.",al={"verbündete von gath'ilzogg","wer arbeitet mit gath'ilzogg zusammen","verbindungen von gath'ilzogg"}},b07f2498={q="Warum wird Gath'Ilzogg gefürchtet?",a="Gath'Ilzogg bewies seine Gefährlichkeit, indem er den Fall von Burg Steinwacht erfolgreich orchestrierte und die örtliche Garnison der Allianz zerschmetterte. Magistrat Solomon betrachtet ihn als die größte militärische Bedrohung für das Überleben von Seenhain, was ein hohes Kopfgeld auf den Kriegsfürsten ausgesetzt hat.",al={"warum ist gath'ilzogg gefährlich","ist gath'ilzogg bekannt","ruf von gath'ilzogg"}}},fp="11,321,25.571.0,14.490.1,19.167.0,31.108.0,41.182.0,34.205.0,47.241.0"}
P.entries["npc:gaxim-rustfizzle"] = {n="Gaxim Rostknirsch",s="Gaxim Rostknirsch ist ein ehrgeiziger Gnomengelehrter und Tüftler, der in einem kleinen Lager der Allianz am Weberpass im Steinkrallengebirge stationiert ist. Als Vertreter der Erleuchteten Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften möchte er skeptischen Nachtelfen beweisen, dass fortschrittliche Handwerkskunst und Alchemie ihr Waldreich bewahren können. Seine wissenschaftliche Neugier wird nur von einer erbitterten Fehde gegen die zerstörerischen Machenschaften der Venture Company übertroffen.",h="Gaxim Rostknirsch ist ein ehrgeiziger Gnomengelehrter und Tüftler, der in einem kleinen Lager der Allianz am...",kw={"versammlung","gaxim","gnom","kaela","rustfizzle","steinkrallengebirge","venture company","weberpass","scherwindklippe"},ang={["faction:Alliance"]="Am gefährlichen Weberpass gelegen, übernimmt Gaxim wichtige Aufklärungs-, Spionage- und Sabotagemissionen, um die aggressiven industriellen Vorstöße im Steinkrallengebirge einzudämmen.",["profession:Engineering"]="Gaxim setzt ingenieurwissenschaftliche Prinzipien im Feld um, indem er verdeckte Operationen und taktische Geräte entwirft, die speziell darauf ausgelegt sind, die primitive Maschinerie der Venture Company zu stören.",["race:Gnome"]="Gaxim verkörpert den akademischen Stolz der Gnome von seiner besten Seite und beweist den alten Kulturen Kalimdors, dass Zahnräder und Reagenzien einen Wald ebenso gut retten können wie Naturmagie.",["race:NightElf"]="Auch wenn Traditionalisten über seine surrenden Apparaturen und blubbernden Phiolen spotten mögen, ist Gaxim ein treuer Verbündeter, der die Grenzen von Eschental und dem Steinkrallengebirge aktiv vor der Goblinindustrie verteidigt."},sec={{t="Ein wissenschaftlicher Gesandter",b="Während Nachtelfen traditionell auf uraltes Druidentum und Naturmagie vertrauen, kam Gaxim Rostknirsch in die zerklüfteten Pässe des Steinkrallengebirges, um eine grundlegend andere Perspektive aufzuzeigen. Als Vertreter der Erleuchteten Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften glaubt er aufrichtig daran, dass berechnete Mechanismen und chemische Lösungen die Wildnis von Kalimdor genauso effektiv verteidigen und wiederherstellen können wie Gebete zu Elune. An der Seite der Schildwache Kaela Schattenspeer am Weberpass rastend, arbeitet er unermüdlich daran, seine hochgewachsenen, zurückgezogen lebenden Verbündeten von den ökologischen Vorzügen der Ingenieurskunst zu überzeugen."},{t="Sabotage an den Sägen",b="Einen Großteil seiner Energie wendet Gaxim gegen die Venture Company auf, deren Kahlschlag und industrielle Gier die nahe gelegene Scherwindklippe entweihen. In der Überzeugung, dass plumpe Goblinmaschinerie weder Respekt noch Gnade verdient, koordiniert Gaxim verdeckte Operationen und volatile chemische Sabotageakte gegen deren Abholzungsaktivitäten. Das Lahmlegen ihrer Schredder und der Diebstahl ihrer Baupläne ist für ihn nicht bloß taktische Kriegsführung – es ist ein praktischer Beweis dafür, dass überlegener Gnomengeist stets über rücksichtslose Ausbeutung durch Konzerne triumphiert."}},faq={{q="Wer ist Gaxim Rostknirsch?",a="Gaxim Rostknirsch ist ein Gnomengelehrter und Erfinder, der an einem Ausguck der Allianz am Weberpass im Steinkrallengebirge stationiert ist. Er dient als Gesandter der Erleuchteten Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften.",al={"wer ist gaxim","gaxim rostknirsch lore","gnom im steinkrallengebirge"}},{q="Was ist die Erleuchtete Versammlung der Arkanologie-, Alchemie- und Ingenieurswissenschaften?",a="Es ist eine akademische und wissenschaftliche Gesellschaft von Gnomen, die sich der Verschmelzung der Disziplinen Arkanmagie, alchemistische Gemische und Maschinenbau verschrieben hat. Gaxim vertritt ihre Ideale in der Ferne Kalimdors.",al={"erleuchtete versammlung","gaxim fraktion","gaxim gruppe"}},{q="Warum arbeitet Gaxim mit den Nachtelfen zusammen?",a="Gaxim möchte den Nachtelfen beweisen, dass gnomische Wissenschaft und Alchemie natürliche Wälder aktiv schützen und heilen können, und bietet so neben dem traditionellen Druidentum eine moderne Antwort der Allianz auf den Waldschutz.",al={"warum ist gaxim hier","gaxim nachtelfen","gaxim aufgabe"}},{q="Warum hasst Gaxim die Venture Company?",a="Die Venture Company betreibt an der Scherwindklippe mit plumpen Maschinen und giftiger Verschmutzung rücksichtslosen Kahlschlag. Gaxim verachtet ihre skrupellose Ausbeutung und genießt es, flüchtige Chemikalien und Sabotage gegen ihre Unternehmungen einzusetzen.",al={"gaxim venture co","gaxim gegen venture company","warum venture co bekämpfen"}},{q="Wer lagert mit Gaxim am Weberpass?",a="Er teilt sich seinen kleinen Außenposten mit Kaela Schattenspeer, einer Nachtelfenschildwache, die über die Pfade zur Scherwindklippe wacht.",al={"gaxim begleiter","wer ist bei gaxim","gaxim und kaela"}},{q="Wo ist Gaxim Rostknirsch zu finden?",a="Er befindet sich in einem bescheidenen Lager der Allianz am Weberpass, direkt südwestlich der industriellen Holzfällergruben der Scherwindklippe im Steinkrallengebirge.",al={"gaxim aufenthaltsort","wo ist gaxim","gaxim rostknirsch karte"}}},fx={d5f6878f={q="Auf wessen Seite steht Gaxim Rostknirsch?",a="Gaxim ist der Allianz loyal und arbeitet direkt an der Seite der Nachtelfen im Steinkrallengebirge. Als Vertreter der Erleuchteten Versammlung für Arkanologie, Alchemie und Ingenieurswissenschaften fungiert er als Gesandter gnomischer Erfindungsgabe und will skeptischen Kaldorei-Verbündeten beweisen, dass die Kombination von arkanem Wissen, chemischen Mischungen und mechanischer Handwerkskunst die Natur bewahren statt zerstören kann.",al={"fraktion von gaxim rostknirsch","gehört gaxim zur allianz","für wen arbeitet gaxim"}}},fp="16,465,21.595.0,19.523.0,24.238.0,81.204.0,42.216.0,40.225.0,43.126.0,36.158.0"}
P.entries["npc:gazin-tenorm"] = {n="Gazin Tenorm",s="Gazin Tenorm ist ein Zwerg, der nahe dem Altar in der Kathedrale des Lichts in Sturmwind stationiert ist. Zusammen mit seinem Kameraden Henze Faulk unternahm er eine gefährliche Spähmission, um Beweise für die Aktivitäten der Bruderschaft der Defias für die Berater des Königs zu sammeln.",h="Gazin Tenorm ist ein Zwerg, der nahe dem Altar in der Kathedrale des Lichts in Sturmwind stationiert ist.",kw={"kathedrale des lichts","defias","duthorian rall","gazin tenorm","henze faulk","paladin","tome of divinity"},ang={["class:Paladin"]="Initianden, die die Pfade des Mitgefühls und der Erlösung erlernen, treffen Gazin in der Kathedrale des Lichts, um seinem gefallenen Waffenbruder Henze Faulk zu helfen.",["race:Dwarf"]="Gazin repräsentiert die beständige Solidarität zwischen Eisenschmiede und Sturmwind und dient als zwergischer Champion, der bereit ist, sich im Namen der Berater des Königreichs den Wegelagerern von Elwynn zu stellen."},sec={{t="Ein Späher in der Kathedrale",b="Während Gazin Tenorm seine Tage in den friedlichen Hallen der Kathedrale des Lichts verbringt, sind seine Gedanken immer noch draußen in der Wildnis des Waldes von Elwynn. Gazin und sein enger Freund Henze Faulk brachen zu einer dringenden Mission in die Wälder auf: Sie sollten stichhaltige Beweise für die Bewegungen der Bruderschaft der Defias sammeln, um diese dem königlichen Hof zu präsentieren. Die Expedition lief schief, als sie von Kräften der Defias überfallen wurden. Gazin konnte mit knapper Not in die Sicherheit von Sturmwind entkommen, aber Henze blieb in tödlicher Gefahr zurück, was Gazin dazu veranlasste, einen standhaften Helden des Lichts zu suchen, der seinem Gefährten zu Hilfe eilt."}},faq={{q="Wo finde ich Gazin Tenorm?",a="Gazin Tenorm befindet sich in der Kathedrale des Lichts in Sturmwind, wo er nahe dem hinteren Altar bei hochrangigen Klerikern und Paladin-Mentoren steht.",al={"gazin standort","wo ist gazin tenorm","wo ist gazin"}},{q="Was ist Gazin Tenorm im Wald von Elwynn zugestoßen?",a="Während er mit seinem Gefährten Henze Faulk die Bruderschaft der Defias untersuchte, geriet Gazin in einen Hinterhalt der Gesetzlosen. Er schaffte es, sich freizukämpfen und zurück nach Sturmwind zu fliehen, doch durch die Ereignisse blieb sein Freund draußen im Wald zurück.",al={"gazins geschichte","was passierte mit gazin","warum ist gazin verletzt"}},{q="Warum untersuchte Gazin die Bruderschaft der Defias?",a="Gazin und Henze Faulk begaben sich in den Wald von Elwynn, um unwiderlegbare Beweise für die illegalen Aktivitäten der Bruderschaft der Defias zu sammeln, mit der Absicht, diese stichhaltigen Beweise direkt den Beratern des Königs in Sturmwind vorzulegen.",al={"warum defias untersuchen","gazins mission","gazin henze defias"}},{q="Welche Verbindung hat Gazin zu den Prüfungen der Paladine?",a="Duthorian Rall verweist angehende menschliche Paladine, die das Tome of Divinity anstreben, an Gazin. Gazin bietet dann die Mittel und Anweisungen zur Rettung seines gefallenen Partners Henze Faulk an, was den Mut und die Barmherzigkeit des Initianden auf die Probe stellt.",al={"gazin tome of divinity","paladin-quest gazin","henze faulk quest"}}},fx={["2ec8b348"]={q="Mit wem ist Gazin Tenorm verbunden?",a="Gazin arbeitet eng mit seinem Kollegen, dem Ermittler Henze Faulk, zusammen. Er teilt außerdem ein starkes Vertrauensverhältnis mit Duthorian Rall, der vielversprechende junge Paladine zur Unterstützung zu Gazin schickt, damit sie gemeinsam ihre Pflicht erfüllen können, das Reich zu schützen.",al={"gazin tenorm verbündete","gazin verbindungen","mit wem arbeitet gazin zusammen"}},d8d56684={q="Wer ist Gazin Tenorm?",a="Gazin Tenorm ist ein zwergischer Ermittler, der derzeit Zuflucht in der Kathedrale des Lichts in Sturmwind sucht. In Abstimmung mit königlichen Kontakten suchten er und sein Partner nach Beweisen, um die wachsende Bedrohung durch die Defias zu bestätigen, die sich direkt vor den Toren der Hauptstadt regt.",al={"wer ist gazin","wer ist gazin tenorm","identität von gazin tenorm"}},e9ee1d11={q="Auf wessen Seite steht Gazin Tenorm?",a="Gazin ist der Allianz und dem Königreich Sturmwind vollkommen loyal. Er arbeitet an der Seite der Priesterschaft und der Paladine der Kathedrale des Lichts und bemüht sich, für den Hof des Königs stichhaltige Informationen über die subversive Tätigkeit der Rebellen im Wald von Elwynn zu sammeln.",al={"fraktion von gazin tenorm","gehört gazin zur allianz","wem dient gazin"}},["22d0c57e"]={q="Was will Gazin Tenorm?",a="Nachdem er einen Hinterhalt von Defias-Schlägern nur knapp überlebt hat, will Gazin verzweifelt, dass sein Begleiter Henze Faulk aus dem Wald von Elwynn gerettet wird. Darüber hinaus will er die Machenschaften der The Defias Brotherhood den Beratern des Königs offenlegen, bevor ihr Aufstand weiter an Boden gewinnt.",al={"was will gazin","ziel von gazin tenorm","wonach sucht gazin"}},["6cef862e"]={q="Warum ist Gazin Tenorm in der Kathedrale des Lichts?",a="Nach einer gewaltsamen Konfrontation mit den Defias, die ihn erschüttert und zur Flucht gezwungen hatte, suchte Gazin die heilige Zuflucht der Kathedrale des Lichts auf. Hier, nahe dem Altar, erholt er sich unter dem wachsamen Schutz von Duthorian Rall und der Silbernen Hand.",al={"warum ist gazin in der kathedrale","warum ist gazin tenorm hier","gazin kathedrale des lichts"}}},fp="12,235,24.580.0,30.154.0,47.242.0,51.213.0,45.212.0"}
P.entries["npc:gazrog"] = {fx={fdfa6042={q="Was will Gazrog?",a="Gazrog möchte für die Horde wichtige Vorräte sichern und im Brachland für Ordnung sorgen. Er beauftragt Abenteurer damit, die von einheimischen Raptoren gestohlene Silberlieferung zurückzuholen, und sucht zudem nach Informationen über das Schicksal seines vermissten Kameraden Dogran.",al={"was will gazrog","was braucht gazrog","gazrog ziele"}},d6aec43d={q="Warum ist Gazrog hier am Wegekreuz?",a="Gazrog ist am strategischen Außenposten des Wegekreuzes stationiert und überwacht dort Operationen, die für den Stützpunkt der Horde im zentralen Kalimdor von entscheidender Bedeutung sind. Er ist hier, um lokale Bedrohungen abzuwehren, die Karawanen angreifen, vermisste Späher der Horde aufzuspüren und gestohlene Ressourcen zurückzuholen, die für die Verteidigung des Außenpostens unerlässlich sind.",al={"warum ist gazrog hier","zweck von gazrog am wegekreuz","warum ist gazrog im brachland"}}}}
P.entries["npc:gelbin-mekkatorque"] = {fx={db25d752={q="Auf wessen Seite steht Gelbin Mekkadrill?",a="Gelbin Mekkadrill steht fest an der Seite der Allianz. Als Anführer der Gnome pflegt er eine unzerbrechliche Bindung zu König Magni Bronzebart und den Zwergen von Eisenschmiede, die ihre Tore öffneten, um seinem vertriebenen Volk Zuflucht zu gewähren. Mekkadrill hat die gnomische Technik, seinen Erfindergeist und militärische Ressourcen zugesagt, um ihre Verbündeten der Allianz in ganz Azeroth zu unterstützen.",al={"mekkadrill fraktion","gelbin allianz","wem dient mekkadrill"}},["0e3721be"]={q="Was will Gelbin Mekkadrill?",a="Mekkadrills einziges Ziel ist die Rückeroberung von Gnomeregan. Der Verlust seiner Heimat und der tragische Tod zahlloser Gnome lasten schwer auf ihm und treiben ihn dazu an, einen Weg zu finden, die Troggs und die Strahlung, die ihre Hallen vergiftet, zu beseitigen. Von der Tüftlerstadt aus leitet er Aufklärungsarbeiten und organisiert Einsatzgruppen, um die Grundlage für die Rückeroberung der Stadt zu schaffen.",al={"mekkadrill ziel","was versucht gelbin zu tun","gelbins plan"}},["39ae11c6"]={q="Mit wem ist Gelbin Mekkadrill verbunden?",a="Mekkadrill arbeitet eng mit König Magni Bronzebart zusammen, seinem großzügigen Gastgeber in Eisenschmiede, und koordiniert sich mit der Führung der Allianz in Sturmwind. Auf persönlicher Ebene verfolgt ihn der Verlust von Gnomeregan und der tausenden Gnome, die starben, nachdem er auf den Rat eines vertrauten Beraters hin die Entlüftung der radioaktiven Stoffe angeordnet hatte.",al={"mekkadrill verbündete","gelbin beziehungen","mit wem arbeitet mekkadrill zusammen"}}}}
P.entries["npc:gelkak-gyromast"] = {n="Gelkak Gyromast",s="Gelkak Gyromast ist ein Gnom, der wie ein Piratenkapitän spricht und an der nebligen Küstenlinie von Nebelrand an der nördlichen Dunkelküste gestrandet ist. Sein Schiff wurde vor der Küste von Dreschadon versenkt, und er möchte seinen mechanischen Ersten Maat, den Threshwackonator 4100, wieder funktionstüchtig machen.",h="Gelkak Gyromast ist ein Gnom, der wie ein Piratenkapitän spricht und an der nebligen Küstenlinie von...",kw={"dunkelküste","gelkak gyromast","gnomerfinder","mathystra","nebelrand","threshwackonator 4100"},ang={["profession:Engineering"]="Gelkaks Notlage ist die klassische Geschichte eines Gnoms fern der Heimat, der seine Hoffnungen auf Rache an ein so eindrucksvolles Gerät wie den Threshwackonator 4100 knüpft.",["race:Gnome"]="Einen Gnomkollegen am Rande von Kalimdor gestrandet zu sehen, führt einem deutlich vor Augen, wie weit weg von zu Hause die Abenteuer einen Gnom tragen können."},sec={{t="Gestrandet am Nebelrand",b="An der einsamen Nordküste von Dunkelküste, direkt westlich der uralten Ruinen von Mathystra, bietet Gelkak Gyromast einen sonderbaren Anblick an den düsteren Ufern der Nachtelfen. Wie ein alter Seebär redend, verlor der selbsternannte Kapitän sein Schiff dicht vor der Küste an die Dreschadon. Als er an den nebligen Strand gespült wurde, zerbrach der Schlüssel zu seinem mechanischen Ersten Maat, dem Threshwackonator 4100, an den Felsen, und seine Teile wurden von den Kriechern, Waldschreitern und Murlocs fortgeschleppt, die das Wrack durchstöberten."},{t="Die Fehlfunktion des Threshwackonators",b="Sobald Abenteurer den Schlüssel geborgen haben, schickt Gyromast sie los, um seinen Ersten Maat einzuschalten und zu ihm zurückzuführen, begierig darauf, ihn auf die Murlocs und Bestien der Küste loszulassen. Der Threshwackonator 4100 folgt gehorsam, nur um in dem Moment eine Fehlfunktion zu erleiden und feindselig zu werden, als er seinen Kapitän erreicht, sodass den Abenteurern nichts anderes übrig bleibt, als ihn zu zerstören."}},faq={{q="Wer ist Gelkak Gyromast?",a="Gelkak Gyromast ist ein exzentrischer Gnom, der wie ein Piratenkapitän spricht und am nördlichen Strand von Dunkelküste namens Nebelrand gestrandet ist, direkt westlich der Ruinen von Mathystra.",al={"gelkak","wer ist gelkak","gyromast"}},{q="Warum ist Gelkak in Dunkelküste gestrandet?",a="Sein Schiff wurde dicht vor der Küste von Dreschadon versenkt, und er wurde mit dem zerbrochenen Schlüssel zu seinem mechanischen Ersten Maat an die einsame Nordküste gespült.",al={"warum ist gelkak hier","gelkak dunkelküste"}},{q="Was ist der Threshwackonator 4100?",a="Der Threshwackonator 4100 ist Gelkaks mechanische Schöpfung und sein selbsternannter Erster Maat. Er möchte ihn wieder funktionstüchtig machen, damit er an den Murlocs und Bestien der Küste Rache nehmen kann.",al={"threshwackonator","gelkak maschine","roboter"}},{q="Welche Hilfe benötigt Gelkak von Reisenden?",a="Gelkak bittet fähige Abenteurer darum, die drei Teile seines zerbrochenen Schlüssels von den Kriechern, Waldschreitern und Murlocs der Küste zu bergen, ihn anschließend zu benutzen, um den Threshwackonator 4100 zu starten, und diesen zu ihm zurückzuführen.",al={"gelkak quests","gyromast quests"}}},fx={["77810e79"]={q="Auf wessen Seite steht Gelkak Gyromast?",a="Gelkak ist ein Gnom, der zur Allianz gehört, obwohl er hier an den einsamen Stränden der Dunkelküste streng auf eigene Faust handelt. Er ist weit abseits jeder größeren Siedlung gestrandet und heißt jeden freundlichen Reisenden der Allianz willkommen, der bereit ist, ihm bei seinen mechanischen Missgeschicken zu helfen.",al={"gelkak gyromast fraktion","gehört gelkak zur allianz","wem dient gelkak"}}},fp="15,271,23.509.0,32.325.1,23.173.0,36.145.0,34.186.0,42.209.0"}
P.entries["npc:general-marcus-jonathan"] = {n="General Marcus Jonathan",s="General Marcus Jonathan ist der Oberkommandant der Verteidigung von Sturmwind und direkt am Tor im Tal der Helden stationiert. Als Veteran des Zweiten Krieges beaufsichtigt er die Garnison, die die Hauptstadt schützt, und verwaltet militärische Anfragen aus den Grenzsiedlungen des Königreichs.",h="General Marcus Jonathan ist der Oberkommandant der Verteidigung von Sturmwind und direkt am Tor im Tal der...",kw={"general jonathan","seenhain","magistrat solomon","marcus jonathan","reginald windsor","armee von sturmwind","verteidigung von sturmwind","das tal der helden"},ang={["class:Warrior"]="Als Oberbefehlshaber der Tore von Sturmwind und Veteran des Zweiten Krieges repräsentiert Jonathan den Gipfel der regulären militärischen Pflicht innerhalb der Infanterieränge des Königreichs.",["faction:Alliance"]="Marcus Jonathan verkörpert den militärischen Stolz Sturmwinds am Tor der Hauptstadt."},sec={{t="Kommandant der Tore",b="Auf seinem Ross im Tal der Helden sitzend, bildet General Marcus Jonathan die erste Verteidigungslinie und ist der ranghöchste Militäroffizier, der die Stadttore überwacht. Er kämpfte im Zweiten Krieg an der Seite berühmter Soldaten wie Reginald Windsor unter dem Kommando von General Turalyon. In dieser Zeit wachsender Spannungen muss Jonathan die unmittelbare Sicherheit der Hauptstadt mit den immer verzweifelteren Hilferufen aus Grenzstädten wie Seenhain in Einklang bringen."},{t="Ein angespanntes Kommando",b="Während Städte wie Seenhain um Soldaten aus Sturmwind bitten, um Schwarzfelsorcs und Gnolle abzuwehren, versichert Jonathan den lokalen Magistraten sein Engagement für Hilfe, vertraut jedoch privat an, dass der Hof distanziert geworden ist und die Regentschaft des jungen Königs sich seltsam verhält."}},faq={{q="Wo kann ich General Marcus Jonathan finden?",a="Er ist hoch zu Ross direkt innerhalb der Haupttore von Sturmwind stationiert und überblickt die Eingangsbrücke im Tal der Helden.",al={"standort marcus jonathan","wo ist general jonathan","kommandant des tores von sturmwind"}},{q="Was ist die militärische Geschichte von Marcus Jonathan?",a="Marcus Jonathan ist ein Veteran, der während des Zweiten Krieges unter General Turalyon diente. Er kämpfte an der Seite von Kameraden wie Reginald Windsor, bevor er schließlich zum Oberkommandanten der Verteidigung von Sturmwind aufstieg.",al={"vergangenheit von marcus jonathan","hintergrundgeschichte marcus jonathan","hat marcus im zweiten krieg gekämpft"}}},fx={d649e9ed={q="Wer ist General Marcus Jonathan?",a="General Marcus Jonathan ist der Oberkommandierende der Verteidigung von Sturmwind. Als erfahrener Veteran, der während des Zweiten Krieges unter General Turalyon diente, beaufsichtigt er nun die Streitkräfte, die die Hauptstadt und die umliegenden Gebiete schützen.",al={"wer ist marcus jonathan","identität von marcus jonathan","wer ist general jonathan"}},["59fdae30"]={q="Auf wessen Seite steht General Marcus Jonathan?",a="Er ist dem Königreich Sturmwind und der Großen Allianz voll und ganz ergeben. Er nimmt seine Pflicht, das Reich zu verteidigen und seine Bürger zu schützen, mit absolutem Ernst und ist der Krone sowie der hohen Führung von Sturmwind direkt unterstellt.",al={"loyalität von marcus jonathan","wem dient marcus jonathan","fraktion von marcus jonathan"}},["5549e5c1"]={q="Was will General Marcus Jonathan?",a="Jonathan möchte Sturmwind schützen und sicherstellen, dass die abgelegenen Siedlungen wie Seenhain die militärische Unterstützung erhalten, die sie dringend benötigen. Da jedoch König Varian Wrynn vermisst wird und sich der königliche Hof seltsam verhält, ist seine Fähigkeit, Truppen nach Belieben zu mobilisieren, stark eingeschränkt.",al={"ziel von marcus jonathan","was braucht marcus jonathan","beweggründe von marcus jonathan"}},b8230eb1={q="Warum ist General Marcus Jonathan für das Rotkammgebirge relevant?",a="Magistrat Solomon von Seenhain richtet Bitten um militärische Hilfe direkt an General Jonathan, da er weiß, dass dessen Wort in Sturmwind ein erhebliches Gewicht hat. Als Befehlshaber der Armee ist Jonathan der Beamte, der die Befugnis hat, die Krone um Verstärkung zur Verteidigung des Rotkammgebirges zu bitten.",al={"warum ist marcus jonathan im rotkammgebirge relevant","marcus jonathan seenhain","warum nachricht an marcus jonathan senden"}},ab66a8e6={q="Mit wem ist General Marcus Jonathan verbunden?",a="Er verbindet eine lange Geschichte mit Marschall Reginald Windsor, da er während des Zweiten Krieges unter General Turalyon an seiner Seite gekämpft hat. In Sturmwind koordiniert er sich regelmäßig mit der Krone und antwortet auf dringende Appelle von regionalen Anführern wie Magistrat Solomon.",al={"verbindungen von marcus jonathan","wer kennt marcus jonathan","verbündete von marcus jonathan"}}},fp="23,272,22.465.0,18.256.1,41.132.0,43.215.0"}
P.entries["npc:gerard-tiller"] = {n="Gerard Tiller",s="Gerard Tiller ist ein durstiger menschlicher Landarbeiter, der vor der Scheune auf den Weinbergen der Maclures im Wald von Elwynn arbeitet. Während er die Weinberge unter der warmen Sonne pflegt, ist er stets begierig darauf, jedem Reisenden, der einen Schlauch erfrischendes Quellwasser erübrigen kann, einen knackigen, glänzenden roten Apfel einzutauschen.",h="Gerard Tiller ist ein durstiger menschlicher Landarbeiter, der vor der Scheune auf den Weinbergen der...",kw={"wald von elwynn","gerard tiller","etwas zu trinken für gerard","weinberge der maclures","erfrischendes quellwasser","glänzender roter apfel"},ang={["profession:Cooking"]="Gerards Bereitschaft, frische Äpfel gegen einfaches Quellwasser einzutauschen, macht ihn zu einer praktischen Obstquelle für wandernde Köche, die nach einfachen Zutaten suchen."},sec={{t="Ein durstiger Landarbeiter",b="Gerard Tiller verbringt seine Tage damit, auf den Feldern zu schuften und das Gelände vor der Scheune auf den Weinbergen der Maclures zu bestellen. Südlich von Goldhain gelegen, bringt der Weinberg einige der bekanntesten Trauben von Elwynn hervor, doch die Aufrechterhaltung der Ernte ist harte Arbeit. Tiller ist von seinen Pflichten ständig ausgedörrt, weshalb er gern mit vorbeikommenden Abenteurern tauscht. Wenn ihm jemand einen frischen Schlauch kühles Quellwasser anbietet, erwidert er diesen Gefallen mit Freuden durch frische, glänzende rote Äpfel, die direkt von den hiesigen Obstgärten geerntet wurden."}},faq={{q="Wer ist Gerard Tiller?",a="Gerard Tiller ist ein menschlicher Landarbeiter, der vor der Scheune auf den Weinbergen der Maclures im südlichen Wald von Elwynn steht.",al={"gerard tiller identität","wer ist gerard","tiller elwynn"}},{q="Wo kann ich Gerard Tiller finden?",a="Er steht direkt vor der großen Holzscheune auf den Weinbergen der Maclures, südlich von Goldhain und östlich vom Hof der Steinfelds.",al={"gerard tiller aufenthaltsort","wo ist gerard","gerard elwynn finden"}},{q="Was tauscht Gerard Tiller?",a="Gerard tauscht einen Glänzenden roten Apfel gegen einen Schlauch Erfrischendes Quellwasser für jeden Reisenden ein, der seinen Durst löscht.",al={"gerard apfeltour tausch","gerard tiller wasser","was will gerard"}},{q="Mischt sich Gerard in die Fehde zwischen den Maclures und Steinfelds ein?",a="Nein. Obwohl er auf den Weinbergen der Maclures arbeitet, konzentriert sich Gerard lieber auf seine Pflichten und darauf, seinen Durst zu stillen, anstatt sich in die Familienrivalität zwischen den Maclures und Steinfelds einzumischen.",al={"gerard tiller fehde","maclure fehde gerard"}}},fx={["467277ed"]={q="Was will Gerard Tiller?",a="Die Arbeit unter der heißen Sonne in den Weinbergen der Maclures ist durstig machend, und Gerard will kaum mehr als einen einfachen Schlauch mit Erfrischendem Quellwasser, um seinen Durst zu stillen. Wenn Ihr ihm ein Getränk bringt, tauscht er gerne einen knackigen, Glänzenden roten Apfel aus dem Obstgarten dagegen ein.",al={"was braucht gerard tiller","handel mit gerard tiller","was will gerard"}},["9aadf23d"]={q="Warum ist Gerard Tiller hier?",a="Gerard Tiller verdient seinen Lebensunterhalt als Arbeiter, der das Gelände vor der Scheune in den Weinbergen der Maclures pflegt. Während die umliegenden Lande von Elwynn von Unruhen bedroht sind, konzentriert sich Gerard weiterhin auf die tägliche Farmarbeit und die Pflege der Ernte.",al={"warum ist gerard tiller in den weinbergen","grund für gerard tillers aufenthaltsort","was macht gerard tiller"}},["9f9d4e60"]={q="Mit wem ist Gerard Tiller verbunden?",a="Gerard ist mit der Familie Maclure verbunden und arbeitet auf ihren Weinbergen südlich von Sturmwind. Obwohl er direkt auf ihrem Land neben ihren Scheunen arbeitet, kümmert er sich um seine eigenen Angelegenheiten und meidet die erbitterte Fehde, die zwischen den Maclures und ihren benachbarten Rivalen, den Steinfelds, tobt.",al={"verbindungen von gerard tiller","für wen arbeitet gerard tiller","verbündete von gerard tiller"}}},fp="13,272,18.515.0,21.112.0,31.131.0,30.118.0,60.175.0"}
P.entries["npc:gerrig-bonegrip"] = {n="Gerrig Knochengriff",s="Gerrig Knochengriff ist ein unscheinbarer Zwergenladner, der in den schattigen Gängen von Eisenschmiedes Forlorn Cavern untergebracht ist. Hinter dem Tresen von Bonegrip's Runes and Dooms kauft und verkauft er im Stillen esoterische Texte über dunkle Rituale und vergessene uralte Mächte.",h="Gerrig Knochengriff ist ein unscheinbarer Zwergenladner, der in den schattigen Gängen von Eisenschmiedes...",kw={"tiefschwarze grotte","knochengriff","forlorn cavern","gerrig","eisenschmiede","manuskript von lorgalis","runes and dooms"},ang={["class:Warlock"]="Für Hexenmeister, die die schattigen Ecken der Forlorn Cavern aufsuchen, bietet Knochengriffs Sammlung esoterischer Rituale und dunkler Folianten eine willkommene Quelle gefährlichen Wissens.",["race:Dwarf"]="Für zwergische Besucher wirft Knochengriffs Handel mit verbotenem Wissen einen beunruhigenden Schatten auf das Gelehrtenleben Eisenschmiedes."},sec={{t="Bonegrip's Runes and Dooms",b="Gerrig Knochengriff, der in den schmuddeligen Winkeln der Forlorn Cavern tätig ist, erscheint den meisten Bürgern lediglich als exzentrischer Verkäufer bizarren Relikten und verbotenen Wissens. Sein bescheidener Laden erfüllt jedoch einen weitaus dunkleren Zweck. Knochengriff ist ein aktives Mitglied des nihilistischen Schattenhammerkults und nutzt seine Ladenfront, um gefährliche Manuskripte und obskure Texte über die Alten Götter direkt vor den Augen des Senats von Eisenschmiede und des High Seat zu sammeln."},{t="Sammeln verbotenen Wissens",b="Gerrig wirbt aktiv ahnungslose Abenteurer der Allianz an, um uralte Artefakte wie das Manuskript von Lorgalis zu bergen, das tief in der Tiefschwarzen Grotte verloren ging. Sobald diese Relikte in seinen Händen sind, transkribiert und verbreitet er das profane Wissen direkt an seine Kultbrüder in ganz Azeroth. Über subtile Verbindungen zu zwielichtigen Verbündeten wie Skuerto und Gestalten, die mit uralten, ursprünglichen Wesenheiten wie Myzrael zu tun haben, arbeitet Knochengriff unermüdlich daran, die apokalyptischen Pläne des Kults voranzutreiben."}},faq={{q="Wer ist Gerrig Knochengriff?",a="Gerrig Knochengriff ist ein Zwerg, der Bonegrip's Runes and Dooms in Eisenschmiedes Forlorn Cavern betreibt. Er handelt mit exzentrischen Kuriositäten und obskuren Texten über uralte Rituale.",al={"wer ist knochengriff","gerrig knochengriff lore","knochengriff eisenschmiede"}},{q="Was macht er mit dem Manuskript von Lorgalis?",a="Er sucht das Manuskript von Lorgalis aus der Tiefschwarzen Grotte für seine Sammlung seltener Texte. Weitere Nachforschungen können mehr über seine Verwendung dessen enthüllen.",al={"warum will knochengriff das manuskript von lorgalis","knowledge in the deeps abgabe","verwendung des manuskripts von lorgalis"}},{q="Wie geht Gerrig in Eisenschmiede vor?",a="Gerrig hält sich als exzentrischer Gelehrter und Händler in der Forlorn Cavern bedeckt, wo er obskure Texte kauft und verkauft.",al={"weiß eisenschmiede dass knochengriff ein kultist ist","warum wird knochengriff in eisenschmiede geduldet"}},{q="Was ist seine Verbindung zu Myzrael?",a="Gerrig ist ein alter Gefährte des Zwergs Skuerto, der das versiegelte Erdelementar Myzrael im Arathihochland untersucht. Durch diese Verbindungen hilft Gerrig dabei, Aufgaben zu koordinieren, die an uralte Binde-Rituale und ursprüngliche Mächte geknüpft sind.",al={"gerrig knochengriff und myzrael","skuerto und gerrig"}}},fp="15,264,26.449.1,30.487.1,23.172.2,45.149.1,37.129.2,34.238.0"}
P.entries["npc:gershala-nightwhisper"] = {n="Gershala Nachtraunen",s="Gershala Nachtraunen ist ein Forscher der Nachtelfen, der in der Küstensiedlung Auberdine an der Dunkelküste lebt. Angetrieben von tiefer Sorge über den Weg der Hochelfen von Quel'Thalas untersucht er Proben verfluchter aquatischer und dämonischer Kreaturen, um zu verstehen, wie magische Verderbnis Geist und Körper verzerrt.",h="Gershala Nachtraunen ist ein Forscher der Nachtelfen, der in der Küstensiedlung Auberdine an der Dunkelküste...",kw={"auberdine","blackfathom","verderbnis","dunkelküste","gershala","naga","nightwhisper","satyr"},ang={["faction:Alliance"]="Gershala dient als wichtiger Förderer, der Allianzexpeditionen in die Gefahren der Tiefschwarzen Grotte entsendet und dafür sorgt, dass ihre Vorstöße wertvolles arkanes Wissen einbringen.",["race:NightElf"]="Für Nachtelfen sind Gershalas düstere Nachforschungen eine ergreifende Mahnung an die uralte Zerschlagung und den schrecklichen Preis magischer Sucht, die einst ihre eigenen Brüder und Schwestern in Schrecken verwandelte."},sec={{t="Studium der Verwandlung",b="Friedlich in Auberdine stationiert, blickt Gershala Nachtraunen über die unmittelbaren Sorgen an der Küste der Dunkelküste hinaus auf eine größere, schleichende Gefahr. Bestürzt darüber, wie die verbliebenen Hochelfen gefährliche arkane Praktiken annehmen und sich Blutelfen nennen, versucht Gershala den biologischen und spirituellen Niedergang zu begreifen, der ungezügelter Magie folgt. Um diese Geheimnisse zu lüften, schickt er erfahrene Abenteurer der Allianz in die überfluteten Hallen der Tiefschwarzen Grotte, um verdorbene Hirnstämme von den dort hausenden Naga und Satyren zu erbeuten."},{t="Ein Gegenmittel zum Untergang",b="Gershalas düstere Konzentration auf die Hirnstämme von Naga und Satyren rührt von ihrer gemeinsamen Abstammung her: Beide Völker waren einst Nachtelfen, bevor sie Königin Azshara und dämonischen Pakten erlagen. Indem er die physischen Spuren seziert, die Jahrtausende dämonischer und abyssischer Energien auf ihren Nervensystemen hinterlassen haben, hofft er, Warnzeichen oder Schutzmaßnahmen aufzudecken, die andere elfische Verwandte vor einem ähnlichen Abstieg in monströse Missbildungen bewahren könnten."}},faq={{q="Wo ist Gershala Nachtraunen zu finden?",a="Gershala Nachtraunen befindet sich in Auberdine, der wichtigsten Hafenstadt der Allianz an der Küste der Dunkelküste.",al={"gershala standort","wo ist gershala","gershala nachtraunen finden"}},{q="Warum möchte Gershala Hirnstämme von Naga und Satyren?",a="Gershala untersucht verdorbene Hirnstämme, um zu erforschen, wie tiefgreifende magische und dämonische Verwandlung die Anatomie ehemaliger Nachtelfen verändert. Sowohl Naga als auch Satyrn waren einst Elfen, und er versucht, die physischen Mechanismen hinter ihrer Verderbnis zu verstehen.",al={"warum hirnstämme","erforschung der verderbnis lore","was erforscht gershala"}},{q="Was hofft Gershala mit seinen Nachforschungen zu erreichen?",a="Gershala hofft, dass seine Forschungen entscheidende Erkenntnisse liefern, um zu verhindern, dass die Blutelfen durch ihre gefährliche Abhängigkeit von Teufelsmagie und ungezügelter arkaner Macht dem Bösen und monströsen Missbildungen anheimfallen.",al={"gershala ziel","warum blutelfen helfen","gershala forschungszweck"}},{q="Wo befinden sich die Proben, die Gershala benötigt?",a="Er schickt Abenteurer in die Tiefschwarze Grotte, eine uralte, überflutete Tempelruine an der Küste von Eschental, die von Naga und Satyren heimgesucht wird.",al={"wo sind die hirnstämme","blackfathom-tiefe hirnstämme","gershala gegenstände finden"}}},fx={["087b63f5"]={q="Auf wessen Seite steht Gershala Nachtraunen?",a="Gershala ist mit den Nachtelfen von Darnassus verbündet und dient Mitgliedern der Allianz als freundlicher Gelehrter. Seine Forschungen finden in Auberdine statt, wo er daran arbeitet, Kalimdor und die sterblichen Völker im Allgemeinen vor den schleichenden Bedrohungen durch dämonische und magische Verderbnis zu schützen.",al={"gershala fraktion","ist gershala allianz","gershala zugehörigkeit"}},aee12c2d={q="Warum ist Gershala Nachtraunen hier?",a="Gershala hat sein Zuhause in Auberdine, da die Dunkelküste direkt an Orte grenzt, die tief von uraltem Übel befallen sind, wie zum Beispiel die Tiefschwarze Grotte. Von diesem Zufluchtsort an der Küste aus kann er Reisende und Abenteurer rekrutieren, die sich nach Süden wagen, um verderbte Exemplare für seine laufenden Forschungen zu sammeln.",al={"warum ist gershala in auberdine","gershala zweck dunkelküste"}},["19945428"]={q="Wer ist Gershala Nachtraunen?",a="Gershala Nachtraunen ist ein Nachtelfengelehrter, der in der Küstensiedlung Auberdine in der Dunkelküste lebt. Angetrieben von wissenschaftlicher Neugier und Sorge um die weitere Welt widmet er sich dem Verständnis magischer und biologischer Verderbnis. Er studiert die veränderte Anatomie von Kreaturen, die durch dunkle Mächte verzerrt wurden, in der Hoffnung, dass sorgfältige Studien ähnliche Untergänge bei anderen Völkern verhindern können.",al={"wer ist gershala","gershala nachtraunen hintergrundwissen","gershala hintergrund"}}},fp="21,311,23.550.0,19.411.0,37.111.0,50.251.0,56.201.0,47.138.0"}
P.entries["npc:gilnid"] = {n="Gilnid",s="Gilnid, bekannt als der Schmelzer, ist der meisterhafte Ingenieur der Goblins, der die Schmieden in den Tiefen der Todesminen betreibt. Er beaufsichtigt das Schmelzen von Roherz zu veredeltem Metall und Munition für Edwin van Cleefs verborgenes gepanzertes Schlachtschiff. Ohne seine feurigen Operationen würde der Bruderschaft der Defias die schwere Artillerie fehlen, die für einen Angriff auf Sturmwind erforderlich ist.",h="Gilnid, bekannt als der Schmelzer, ist der meisterhafte Ingenieur der Goblins, der die Schmieden in den...",kw={"kanonen","die todesminen","defias","schmiede","gießerei","gilnid","goblin","schlachtschiff","schmelzer","vancleef"},ang={["faction:Alliance"]="Das Ausschalten von Gilnid legt die Waffenfertigung der Defias lahm und verhindert, dass VanCleefs Kriegsschiff vollständig bewaffnet werden kann, bevor es den Hafen von Sturmwind bedrohen kann.",["profession:Engineering"]="Gilnids Gießerei ist ein Paradebeispiel für die Schwerindustrie der Goblins, in der unter extremen Bedingungen standardisierte Schiffskanonen, Munition und Strukturpanzerungen hergestellt werden.",["profession:Mining"]="Die gewaltigen Hochöfen und Schmelztiegel in Gilnids Werkstatt zeigen, wie die Bruderschaft der Defias die unberührten Bodenschätze von Westfall in raffiniertes Eisen und Rüstungsgüter verwandelt."},sec={{t="Meister der Gießerei",b="Tief in den Todesminen verlässt sich die Bruderschaft der Defias auf industrielles Fachwissen, um Kriegswaffen zu schmieden. Gilnid dient als VanCleefs oberster Schmelzer und befehligt eine kleine Armee aus Goblin-Arbeitern, Tüftlern und Schmieden in der zentralen Gießerei. Er überragt die meisten seiner Artgenossen und treibt seine Mannschaft unerbittlich durch Rauch und Schlacke, bellt Befehle und verweigert Pausen, um sicherzustellen, dass Roheisenerz zu schweren Panzerplatten und tödlicher Munition verarbeitet wird."},{t="Bewaffnung des Schlachtschiffs",b="Die Schmelzhütte ist von entscheidender Bedeutung für die ehrgeizigen Pläne der Bruderschaft. Gilnid ist direkt für das Schmieden der schweren Kanonen und der Munition verantwortlich, die für das gewaltige eiserne Kriegsschiff bestimmt sind, das in der unterirdischen Bucht jenseits seiner Werkstatt vor Anker liegt. Bis seine Gießerei jedes Geschütz, jedes Rohr und jede Kugel produziert hat, bleibt das Schiff der Defias unvollendet für seinen geplanten Angriff auf Sturmwind."}},faq={{q="Wer ist Gilnid?",a="Gilnid ist ein Goblin-Ingenieur und der oberste Schmelzer von Edwin van Cleef in den Todesminen. Er beaufsichtigt die Schmieden der Bruderschaft und leitet die industriellen Bemühungen, Kanonen und Munition für ihre Kriegsmaschinerie zu gießen.",al={"gilnid todesminen","wer ist gilnid","der schmelzer"}},{q="Warum befindet sich Gilnid in den Todesminen?",a="Die Bruderschaft der Defias heuerte Goblin-Söldneringenieure an, um ihr verborgenes Kriegsschiff zu bauen und auszurüsten. Gilnid wurde mit der Leitung der Schmelzhütte betraut, wo abgebautes Eisenerz in veredelte Teile, Panzerungen und Artillerie verwandelt wird.",al={"warum ist ein goblin in den todesminen","gilnid defias lore","was macht gilnid"}},{q="Woran arbeitet Gilnid?",a="Gilnid ist für die Herstellung der massiven Kanonen, Schiffsteile und Kugeln verantwortlich, die zur Bewaffnung des Kriegsschiffs benötigt werden, das in den Docks tiefer im Inneren der Minen versteckt ist.",al={"gilnid kanone","was baut gilnid","todesminen schmiede zweck"}},{q="Warum muss Gilnid besiegt werden?",a="Gilnid kontrolliert die industrielle Gießerei, die den Weg zur Bucht versperrt. Die schweren Panzertüren, die tiefer zum Schiff der Defias führen, bleiben versiegelt, bis der Schmelzraum gesichert ist.",al={"warum gilnid töten","tür nach gilnid"}},{q="Arbeitet Gilnid direkt für Edwin van Cleef?",a="Ja. Er ist kein Mitglied der ursprünglichen Steinmetzgilde, sondern ein angeheuerter Goblin-Spezialist, der direkt unter VanCleef dient, um die schwere Metallurgie und Waffenproduktion zu leiten.",al={"vancleef und gilnid","ist gilnid anführer der defias"}},{q="Warum sind so viele Goblins um ihn herum?",a="Gilnid leitet eine spezialisierte Goblin-Ingenieurmannschaft in der Gießerei. Sie betreiben die Hochöfen, gießen flüssiges Eisen und montieren Artillerie unter seiner strengen, unerbittlichen Aufsicht.",al={"gilnid goblins","todesminen schmiedemannschaft"}}},fx={["1c6d7566"]={q="Auf wessen Seite steht Gilnid?",a="Gilnid steht fest auf der Seite der Bruderschaft der Defias. Während Goblins normalerweise für ihre unabhängigen Söldnerverträge und ihre Neutralität bekannt sind, hat Gilnid seine beachtlichen metallurgischen Talente der rebellischen Sache von Edwin van Cleef gewidmet und dient als leitender Aufseher tief im unterirdischen Stützpunkt der Bruderschaft.",al={"gilnid fraktion","gilnid bruderschaft der defias","für wen kämpft gilnid"}},["88f08ccf"]={q="Was will Gilnid?",a="Gilnid möchte nichts lieber, als das Juggernaut der Defias vollständig ausgerüstet und einsatzbereit zu sehen. Als leitender Schmelzer ist sein oberstes Ziel sicherzustellen, dass jede Kanone, jedes Gehäuse und jede Ladung schwerer Munition perfekt geschmiedet wird, und er treibt seine Goblin-Arbeiter unbarmherzig ohne Pause an, bis das gewaltige Kriegsschiff bereit zum Auslaufen ist.",al={"gilnid ziel","was versucht gilnid zu tun","gilnid motivation"}}},fp="6,339,21.433.0,21.374.1,14.208.0,31.218.0,26.155.0,28.179.0,45.177.0,41.182.0"}
P.entries["npc:gilshalan-windwalker"] = {n="Gilshalan Windspäher",s="Gilshalan Windspäher ist ein Nachtelfenforscher, der am Fuße des großen Baumes Aldrassil in Laubschattental weilt. Besorgt über das plötzliche Verderben, das in Teldrassil Wurzeln schlägt, studiert er die einheimische Tierwelt, um die unnatürliche Aggression zu verstehen, welche die Äste heimsucht. Seine Nachforschungen über die Waldweberspinnen liefern frühe Hinweise auf die Fäulnis, die den Weltenbaum befällt.",h="Gilshalan Windspäher ist ein Nachtelfenforscher, der am Fuße des großen Baumes Aldrassil in Laubschattental...",kw={"aldrassil","gilshalan","laubschattental","spinne","tenaron","gift","waldweber","windwalker"},ang={["class:Druid"]="Seine Forschung unterstützt direkt die Versuche des Zirkels des Cenarius, das ökologische Ungleichgewicht zu ergründen, das in den Ästen von Laubschattental schwelt.",["race:NightElf"]="Gilshalan verkörpert die frühen Bemühungen Eures Volkes, zu begreifen, warum der neu gewachsene Weltenbaum bereits von Fäulnis geplagte, gewalttätige Bestien hervorbringt."},sec={{t="Ein Gelehrter an den Wurzeln",b="Ruhig auf den Steinstufen sitzend, die nach Aldrassil hinaufführen, blickt Gilshalan Windspäher mit wachsendem Unbehagen auf das friedliche Blätterdach von Laubschattental. Teldrassil wurde gepflanzt, um den Nachtelfen ihre verlorene Zuflucht und die Harmonie mit der Natur zurückzugeben, doch traten fast augenblicklich Anzeichen eines tiefen spirituellen Unbehagens zutage. Gilshalan widmet sich der Erforschung dessen, wie sich dieses Verderben in den örtlichen Bestien manifestiert, beginnend bei den giftigen Spinnentieren, die in der Nähe ihre Netze weben."},{t="Die Waldweberbedrohung",b="Gilshalans Hauptaugenmerk liegt auf den Waldweberspinnen, die im Norden in der Schattenweberhöhle lauern. Diese Kreaturen, einst ein ausgewogener Teil des Waldökosystems, sind unnatürlich feindselig und verdorben geworden. Indem er junge Novizen aussendet, um Giftbeutel und unversehrte Spinneneier zu sammeln, arbeitet Gilshalan daran, die veränderte Wirksamkeit des Gifts zu analysieren und festzustellen, ob das Verderben über Generationen weitergegeben wird oder sich von außen über den Boden von Teldrassil ausbreitet."},{t="Nachricht an den Erzdruiden",b="Mit dem Gift und einem Ei in den Händen glaubt Gilshalan, dass das Gift der Spinnen Eigenschaften aufweisen wird, die mit dem jüngsten Wachstum des neuen Weltenbaums verknüpft sind. Er veranlasst, dass die Exemplare nach Darnassus geschickt werden, wo er seine Studien fortsetzen wird. Zudem lässt er vielversprechenden Beschützern ausrichten, dass Tenaron Sturmgewalt im obersten Gemach von Aldrassil, wo die Führung der Druiden über den jungen Weltenbaum wacht, nach ihnen verlangt hat."}},faq={{q="Wer ist Gilshalan Windspäher?",a="Gilshalan Windspäher ist ein Nachtelfengelehrter, der am Fuße von Aldrassil in Laubschattental sitzt. Er untersucht das mysteriöse Verderben, das sich in die Tierwelt von Teldrassil einschleicht.",al={"gilshalan","wer ist gilshalan","windwalker nachtelf"}},{q="Warum möchte Gilshalan Waldwebergift?",a="Gilshalan versucht, die chemischen und spirituellen Eigenschaften des Gifts zu erforschen, um zu verstehen, warum die Spinnen des Waldes so aggressiv und mutiert geworden sind.",al={"warum waldwebergift","waldwebergift quest","spinnengift gilshalan"}},{q="Was macht er mit dem Waldweberei?",a="Er möchte lebende Exemplare studieren, doch eine ausgewachsene Riesenspinne einzufangen ist zu gefährlich. Ein ungebrütetes Ei lässt sich weitaus leichter transportieren, daher lässt er es zusammen mit dem Gift nach Darnassus senden, wo die Schlüpflinge eingesperrt und studiert werden können.",al={"waldweberei quest","warum spinneneier","waldweberei"}},{q="Wohin schickt Gilshalan Abenteurer als Nächstes?",a="Nachdem das Ei abgeliefert wurde, teilt er Abenteurern mit, dass Tenaron Sturmgewalt nach ihnen verlangt hat, und schickt sie hinauf in die oberste Kammer auf der Spitze von Aldrassil.",al={"tenaron ruft","wen aufsuchen nach gilshalan","nach waldweberei"}},{q="Wo befindet sich Gilshalan Windspäher?",a="Er sitzt auf dem Steinpfad am nördlichen Fuß von Aldrassil, direkt vor dem hohlen Eingang des zentralen Baumes in Laubschattental.",al={"gilshalan standort","wo ist windwalker","gilshalan finden"}},{q="Warum ist die Tierwelt in Teldrassil aggressiv?",a="Eine unbekannte Fäulnis hat begonnen, durch die Wurzeln und den Boden von Teldrassil zu sickern, was den Geist und das Wesen seiner Kreaturen verdirbt und Gelehrte wie Gilshalan beunruhigt.",al={"warum sind spinnen wütend","teldrassil verderbnis","verdorbene bestien laubschattental"}}},fx={["4b23360a"]={q="Auf wessen Seite steht Gilshalan Windspäher?",a="Gilshalan steht fest an der Seite seiner Mitstreiter, der Nachtelfen und der Allianz. Er ist an den Wurzeln von Aldrassil innerhalb des Laubschattentals stationiert und hilft jungen Abenteurern dabei, die seltsamen, verderbenden Kräfte zu verstehen und zu bekämpfen, die die lokale Tierwelt von Teldrassil befallen.",al={"gilshalan fraktion","wem dient gilshalan","gilshalan windspäher allianz"}},["61ec761c"]={q="Warum ist Gilshalan Windspäher hier?",a="Er sitzt an der Basis von Aldrassil, um die aufkommende Verderbnis im Laubschattental zu überwachen. Durch die Untersuchung von Giftproben und ungeöffneten Eiern der aufgewühlten Webwaldspinnen versucht Gilshalan herauszufinden, was die natürliche Harmonie des großen Weltenbaums vergiftet.",al={"warum ist gilshalan im laubschattental","gilshalan windspäher aldrassil zweck"}},ba2e5485={q="An wen ist Gilshalan Windspäher gebunden?",a="Gilshalan berichtet an Tenaron Sturmgewalt, einen der älteren Druiden, die hoch oben in den Ästen von Aldrassil stationiert sind. Sobald seine ersten Untersuchungen zu den Webwaldspinnen abgeschlossen sind, verweist er vielversprechende Rekruten an Tenaron, um weiterhin bei der Verteidigung von Teldrassil zu helfen.",al={"an wen berichtet gilshalan","gilshalan tenaron","gilshalan verbindungen"}}},fp="20,370,22.466.0,18.458.0,21.429.1,28.174.0,38.153.0,37.236.0,43.151.0,38.131.0,45.187.0"}
P.entries["npc:gilthares-firebough"] = {fx={["4d14e07a"]={q="Auf wessen Seite steht Gilthares Feuerzweig?",a="Gilthares steht weder auf der Seite der Horde noch auf der der Allianz. Er ist ein unabhängiger Seemann, der den Freibeutern von Thalo'dan angehört, einer Gruppe von Freibeutern, die auf den Handelsrouten zwischen Ratschet und Beutebucht operiert. Obwohl er keine besondere Liebe für die Horde hegt, haben ihn seine gewaltsame Gefangennahme und harte Versklavung durch Theramore-Eiferer offen feindselig gegenüber den Allianzstreitkräften gemacht, die die Feste Northwatch besetzt halten.",al={"gilthares feuerzweig fraktion","ist gilthares horde oder allianz","gilthares zugehörigkeit"}},["84aa2a4b"]={q="Was will Gilthares Feuerzweig?",a="Gilthares will nichts weiter, als aus seinem Käfig in der Feste Northwatch auszubrechen und den Eiferern zu entkommen, die ihn gefangen genommen haben. Nachdem er die gewaltsame Zerstörung seines Schnapstransports überlebt hat und nun in einem Küstenturm eingesperrt ist, ist er verzweifelt auf der Suche nach jemandem, der in der Lage ist, ihm einen Weg durch die Garnison freizukämpfen, damit er ihrer Gefangenschaft entfliehen kann.",al={"gilthares feuerzweig ziel","was will gilthares","gilthares feuerzweig zielsetzung"}}}}
P.entries["npc:glorin-steelbrow"] = {n="Glorin Stahlbraue",s="Glorin Stahlbraue ist ein zwergischer Agent, den man beim Trinken in der Tiefenwassertaverne im Hafen von Menethil antrifft. Als Vertrauter von Bischof Heller aus Sturmwinds Kathedrale des Lichts hilft er Abenteurern, Die Dritte Flotte zu untersuchen und heilige Relikte sowie Materialien zu bergen, die an der Küste des Sumpflands verstreut liegen. Seine Bemühungen verbinden die heimgesuchte Wildnis des Dämmerwalds direkt mit den versunkenen Schiffswracks des Nordens.",h="Glorin Stahlbraue ist ein zwergischer Agent, den man beim Trinken in der Tiefenwassertaverne im Hafen von...",kw={"bischof heller","tiefenwassertaverne","die verlorene flotte","dämmerwald","auge von paleth","glorin stahlbraue","lichtgeschmiedetes eisen","der hafen von menethil","sumpfland"},ang={["class:Paladin"]="Paladine, die Hellers Befehlen folgen, werden Glorin als unverzichtbar erachten, um lichtgeschmiedetes Eisen zu bergen – ein heiliges Metall, das für das Schmieden von durch das Heilige Licht gesegneten Waffen unerlässlich ist.",["faction:Alliance"]="Glorin spielt eine Schlüsselrolle bei der Bergung wichtiger militärischer Allianzrelikte und geweihter Materialien, die bei den maritimen Katastrophen im Sumpfland verloren gingen.",["race:Dwarf"]="Glorin verkörpert zwergische Tatkraft und Solidarität, indem er vom maritimen Knotenpunkt im Hafen von Menethil aus Verbündete in ganz Khaz Modan und den südlichen Menschenkönigreichen unterstützt."},sec={{t="Eine Verbindung im Hafen",b="Während Bischof Heller den Menschen im Dämmerwald von Sturmwinds Kathedrale des Lichts aus gegen die schleichenden Schrecken beisteht, unterhält er weit im Norden im Hafen von Menethil Verbindungen. In der geschäftigen Tiefenwassertaverne stationiert, fungiert Glorin Stahlbraue als Hellers Augen und Ohren an der Küste. Er bietet Reisenden, die auf der Suche nach heiligen Metallen und vergessenen Relikten nach Norden geschickt werden, Hilfe und Führung und schlägt so eine entscheidende Brücke zwischen den Nöten des südlichen Waldes und den versunkenen Trümmern des Sumpflands."},{t="Die verlorene Flotte und verlorene Relikte",b="Steelbrow ist mit der Tragödie der Dritten Flotte bestens vertraut, deren Schiffe an der Küste des Sumpflands zerschmettert und in die Tiefe gerissen wurden. Er leitet Abenteurer an, die heimgesuchten Wracks nach verlorenen Barren aus lichtgeschmiedetem Eisen und dem mächtigen, verfluchten Artefakt abzusuchen, das als das Auge von Paleth bekannt ist. Glorin weiß, dass die Bergung solch heiliger Rüstgüter unerlässlich ist, um Waffen zu schmieden, die den finsteren Mächten Einhalt gebieten können, welche die Allianz bedrohen."}},faq={{q="Wer ist Glorin Stahlbraue?",a="Glorin Stahlbraue ist ein Zwerg, der in der Tiefenwassertaverne im Hafen von Menethil stationiert ist. Er arbeitet mit Bischof Heller aus Sturmwind zusammen und unterstützt Abenteurer, die nach Norden reisen, um versunkene Fracht und Relikte vor der Küste des Sumpflands zu bergen.",al={"wer ist glorin","glorin stahlbraue lore","was macht glorin"}},{q="Wo finde ich Glorin Stahlbraue?",a="Glorin befindet sich im Erdgeschoss der Tiefenwassertaverne im Hafen von Menethil an der Westküste des Sumpflands.",al={"glorin aufenthaltsort","wo ist glorin stahlbraue","glorin deepwater taverne"}},{q="Warum hat ein Zwerg im Hafen von Menethil mit dem Dämmerwald zu tun?",a="Bischof Heller aus Sturmwinds Kathedrale des Lichts sucht nach mächtigen heiligen Relikten und geweihten Metallen, um die Dunkelheit zu bekämpfen, die den Dämmerwald bedroht. Er entsendet vertrauenswürdige Abgesandte zu Glorin Stahlbraue, der die Küste des Sumpflands kennt und Bergungstrupps zu den versunkenen Überresten der Dritten Flotte leiten kann.",al={"warum dämmerwald quest im sumpfland","verbindung zu farthing","warum ins sumpfland geschickt"}},{q="Was ist die Dritte Flotte, von der Glorin spricht?",a="Die Dritte Flotte war eine Marineexpedition der Allianz, die vor der Küste des Sumpflands in eine Katastrophe geriet. Ihre zerschellten Rümpfe liegen nun auf dem Meeresgrund, heimgesucht von ertrunkenen Seeleuten, und verbergen wertvolle Fracht wie lichtgeschmiedetes Eisen und uralte Artefakte.",al={"was ist die verlorene flotte","dritte flotte sumpfland","die verlorene flotte quest"}},{q="Was ist das Auge von Paleth?",a="Das Auge von Paleth ist ein uraltes religiöses Relikt, das an Bord der versunkenen Flotte transportiert wurde. Sobald es mit Glorins Führung vom Meeresgrund geborgen wurde, muss es von der Priesterschaft gereinigt werden, da das Schiffswrack von finsterer Verderbnis umgeben ist.",al={"auge von paleth","paleth relikt","was ist das auge von paleth"}},{q="Wofür wird lichtgeschmiedetes Eisen verwendet?",a="Lichtgeschmiedetes Eisen ist ein seltenes, geweihtes Metall, aus dem gesegnete Waffen geschmiedet werden, die mächtige Untote und dämonische Streitkräfte niederstrecken können. Glorin hilft dabei, verlorene Barren aus den Schiffswracks zu bergen, um die Verteidiger des Dämmerwalds zu unterstützen.",al={"lichtgeschmiedetes eisen","verlorene barren","gesegnete waffe"}}},fx={["65727266"]={q="Auf wessen Seite steht Glorin Stahlbraue?",a="Glorin steht fest auf der Seite der Allianz und der Kirche des Heiligen Lichts. Er ist im Hafen von Menethil stationiert und arbeitet in Abstimmung mit Anführern wie Bischof Heller von Sturmwind, um von vertrauenswürdigen Abenteurern der Allianz Unterstützung bei der Bergung verlorener, geweihter Relikte und Materialien zu erhalten, die entlang der tückischen Küsten verloren gingen.",al={"glorin stahlbraue fraktion","wem dient glorin stahlbraue","glorin stahlbraue allianz"}},cbae8fd4={q="Was will Glorin Stahlbraue?",a="Glorin möchte verlorene heilige Fracht bergen, die vom Meer beansprucht wurde, insbesondere Lieferungen, die von der versunkenen Dritten Flotte transportiert wurden. Seine Bemühungen konzentrieren sich darauf, Abenteurer anzuheuern, um seltene Lightforge Iron-Barren und heilige Relikte wie The Eye of Paleth zu bergen, um sicherzustellen, dass sie gereinigt und der Kirche zurückgegeben werden.",al={"was braucht glorin stahlbraue","glorin stahlbraue ziel","wonach sucht glorin stahlbraue"}},["72c86ba2"]={q="An wen ist Glorin Stahlbraue gebunden?",a="Glorin ist ein Mitarbeiter von Bischof Heller aus der Kathedrale des Lichts in Sturmwind. Er koordiniert sich direkt mit der Geistlichkeit von Sturmwind, um verlorene heilige Relikte zu sichern, und fungiert als deren Verbindungsperson im Hafen des Sumpflands, um Lieferungen zu bergen, die für die Bemühungen der Kirche bestimmt oder von diesen verloren gegangen sind.",al={"glorin stahlbraue verbindungen","wen kennt glorin stahlbraue","glorin stahlbraue bischof farthing"}}},fp="16,405,19.496.0,32.444.1,24.239.0,34.128.0,57.294.0,48.240.0,26.243.0,33.221.0"}
P.entries["npc:gnoarn"] = {n="Gnoarn",s="Gnoarn ist ein im Exil lebender Gnom, der sich in Tüftlerstadt in der Zwergen-Bergstadt Eisenschmiede aufhält. Nach dem verheerenden Fall von Gnomeregan vertrieben, unterstützt er sein verstreutes Volk, indem er Abenteurer aussendet, um befreundeten gnomischen Ingenieuren und Überlebenden zu helfen.",h="Gnoarn ist ein im Exil lebender Gnom, der sich in Tüftlerstadt in der Zwergen-Bergstadt Eisenschmiede aufhält.",kw={"bingles","gnoarn","gnomfro","gnomeregan","eisenschmiede","shoni die schtille","tüftlerstadt"},ang={["faction:Alliance"]="Helden der Allianz, die durch Eisenschmiede reisen, können mit Gnoarn sprechen, um Hinweise auf wichtige gnomische Ingenieurbestrebungen in Dun Morogh, Loch Modan und Sturmwind zu erhalten.",["race:Gnome"]="Für andere Gnome verkörpert Gnoarn die Widerstandskraft der Flüchtlingsgemeinschaft in Tüftlerstadt und sorgt dafür, dass vertriebene Ingenieure in den Östlichen Königreichen miteinander in Verbindung bleiben."},sec={{t="Ein vertriebener Bürger von Gnomeregan",b="Wie der Großteil seiner Brüder war Gnoarn gezwungen, aus den Tiefen von Gnomeregan zu fliehen, als Troggs einfielen und katastrophale Strahlung die große unterirdische Metropole unbewohnbar machte. In Tüftlerstadt in Eisenschmiede fand er unter der Gastfreundschaft der Bronzebeard-Zwerge Zuflucht und verbringt nun seine Tage damit, den Überblick über andere Überlebende zu behalten. Er fungiert als informeller Koordinator unter den Flüchtlingen und weist fähige Reisende auf Gnome in der Ferne hin, die dringend Hilfe benötigen, wie etwa den gestrandeten Piloten Bingles Blastenheimer in Loch Modan oder die ehrgeizige Ingenieurin Shoni die Schtille in Sturmwind."}},faq={{q="Wer ist Gnoarn?",a="Gnoarn ist ein gnomischer Überlebender, der unter der Flüchtlingsbevölkerung in Tüftlerstadt lebt, dem Gnomviertel von Eisenschmiede. Er schickt Reisende aus, um befreundeten verbannten Gnomen zu helfen, die in den Gebieten der Allianz an verschiedenen Projekten arbeiten.",al={"wer ist dieser gnom","gnoarn lore","gnoarn nsc"}},{q="Wo ist Gnoarn zu finden?",a="Er ist in Tüftlerstadt im nordöstlichen Teil von Eisenschmiede zu finden, umgeben von surrenden Maschinen, Zahnrädern und Werkbänken seiner im Exil lebenden Verwandten.",al={"gnoarn aufenthaltsort","wo ist gnoarn","gnoarn finden"}},{q="Welche Aufgaben vergibt Gnoarn?",a="Gnoarn weist Abenteurer an, anderen verstreuten Gnomen beizustehen. Insbesondere schickt er Abenteurer nach Loch Modan, um nach dem vermissten Piloten Bingles Blastenheimer zu sehen, und entsendet Reisende nach Sturmwind, um mit der Erfinderin Shoni die Schtille über ihre Gyrobohrmatische Exkavation zu sprechen.",al={"gnoarn quests","was will gnoarn"}},{q="Was ist mit Gnoarns Haaren geschehen?",a="Vor dem Fall von Gnomeregan war Gnoarn dafür bekannt, eine exzentrische „Gnomfro“-Frisur zu tragen. Tragischerweise verlor er seine markante Haarpracht nach dem katastrophalen Niederschlag und der Entlüftung radioaktiver Gase, die seine Heimatstadt verwüsteten.",al={"gnoarn gnomfro","gnoarn haare"}}},fx={["38923b37"]={q="Auf wessen Seite steht Gnoarn?",a="Gnoarn ist seinen Mitgnomen aus Gnomeregan und der Großen Allianz treu ergeben. Er lebt unter der vertriebenen Gnombevölkerung in der Tüftlerstadt und arbeitet daran, seine Gemeinschaft organisiert und in Verbindung mit ihren Verbündeten in Eisenschmiede zu halten.",al={"gnoarn fraktion","ist gnoarn allianz","wem dient gnoarn"}},ce7102b3={q="Warum ist Gnoarn in Eisenschmiede?",a="Wie Tausende anderer Gnome wurde Gnoarn nach dem Fall von Gnomeregan aus seiner Heimat vertrieben. Als Troggs das unterirdische technologische Wunderwerk überrannten und giftige Strahlung die Gänge verseuchte, flohen die Überlebenden nach oben, um Zuflucht bei ihren Zwergenvettern in Eisenschmiede zu suchen, wo sie sich in der Tüftlerstadt ein neues Zuhause schufen.",al={"warum ist gnoarn hier","warum kam gnoarn nach eisenschmiede","was brachte gnoarn nach eisenschmiede"}},["82a3a1ba"]={q="Was will Gnoarn?",a="Gnoarn sorgt sich um die Sicherheit und den Verbleib seiner vertriebenen Verwandten. In der Unordnung nach der Evakuierung von Gnomeregan sucht er nach vermissten Kameraden wie Bingles und leitet fähige Abenteurer an, bedeutenden Erfindern und Spezialisten wie Shoni die Schtille zu helfen.",al={"was versucht gnoarn zu tun","gnoarn ziele","was braucht gnoarn"}},efead32c={q="An wen ist Gnoarn gebunden?",a="Gnoarn unterhält enge Beziehungen zu anderen Überlebenden aus Gnomeregan in Eisenschmiede, insbesondere durch seine Verbindung zu der bekannten Erfinderin Shoni die Schtille und seine Koordinierungsbemühungen, um geflüchtete Kameraden wie Bingles Blastenheimer ausfindig zu machen.",al={"gnoarn verbündete","wen kennt gnoarn","gnoarn verbindungen"}}},fp="6,259,33.597.0,14.214.0,26.161.0,32.286.0,31.230.0"}
P.entries["npc:godrick-farsan"] = {n="Godrick Farsan",s="Godrick Farsan ist ein untoter Hexenmeisterassistent in Unterstadt, der an der Seite von Carendin Halgar im Magieviertel dient. Obwohl er vollkommen blind ist, sagt er, dass er auf andere Weise sehe.",h="Godrick Farsan ist ein untoter Hexenmeisterassistent in Unterstadt, der an der Seite von Carendin Halgar im...",kw={"carendin halgar","godrick farsan","hearts of the pure","strahad farsan","succubus","unterstadt","hexenmeister"},ang={["class:Warlock"]="Hexenmeister der Verlassenen, die die Kunst erlernen wollen, einen Succubus zu beschwören, müssen Godrick konsultieren, um die notwendigen Lockmittel vorzubereiten und die verschlingende Natur dämonischer Diener zu verstehen.",["race:Undead"]="Godrick verkörpert die Philosophie der Hexenmeister der Verlassenen, indem er den körperlichen Verfall und die Blindheit annimmt, während er eine dunkle magische Wahrnehmung schärft, um sterbliche Schwächen zu ersetzen."},sec={{t="Augen im Dunkeln",b="Inmitten der Beschwörungskreise des Magieviertels unterstützt Godrick Farsan Meister Carendin Halgar dabei, angehende Hexenmeister der Verlassenen anzuleiten. Obwohl ihm das physische Augenlicht fehlt, sagt Godrick, dass er dennoch auf andere Weise sehen könne, ohne die Mittel dazu zu erklären. Er prüft Praktizierende, die mächtigere dämonische Wesenheiten binden wollen, und schickt sie los, um Reine Herzen und Essenzen zu sammeln, die für komplizierte Beschwörungsrituale benötigt werden."}},faq={{q="Wer ist Godrick Farsan?",a="Godrick Farsan ist ein Hexenmeister der Verlassenen, der im Magieviertel von Unterstadt stationiert ist. Er dient als Assistent von Meister Carendin Halgar und hilft bei der Ausbildung und den Ritualen angehender Hexenmeister.",al={"godrick farsan","wer ist godrick"}},{q="Wie kann Godrick sehen, wenn er blind ist?",a="Godrick sagt, dass er trotz seiner Blindheit auf andere Weise sehe. Die genauen Mittel werden nicht erklärt.",al={"ist godrick blind","wie sieht godrick"}},{q="Ist Godrick mit Strahad Farsan verwandt?",a="Sie teilen denselben Nachnamen, aber eine familiäre Verbindung ist nicht bestätigt.",al={"beziehung zu strahad farsan","strahad farsan bruder","sind godrick und strahad verwandt"}},{q="Welche Rolle spielt er bei der Ausbildung von Hexenmeistern?",a="Godrick hilft bei der Beaufsichtigung der Bindungsriten für Hexenmeister und leitet sie insbesondere durch Aufgaben wie die Beschaffung Reiner Herzen an, um einen Succubus anzulocken und zu binden.",al={"godrick hexenmeisterquests","quest hearts of the pure"}}},fx={["5d2f41c4"]={q="Auf wessen Seite steht Godrick Farsan?",a="Godrick ist den Verlassenen und der Dunklen Fürstin treu ergeben und lebt tief in der Unterstadt. Er dient an der Seite von Carendin Halgar, unterstützt Praktizierende der dunklen Künste und leitet Hexenmeister der Horde an, die dämonische Mächte meistern wollen.",al={"godrick farsan zugehörigkeit","wem dient godrick","godrick farsan fraktion"}},f8f4201c={q="Warum ist Godrick Farsan hier?",a="Ihr findet Godrick in den schattigen Quartieren der Unterstadt, wo er als ergebener Assistent von Carendin Halgar fungiert. Er bleibt hier stationiert, um Prüfungen für angehende Hexenmeister zu beaufsichtigen und ihnen dabei zu helfen, mächtige dämonische Wesen wie die Sukkubus zu binden.",al={"warum ist godrick in der unterstadt","godrick farsan zweck unterstadt","was macht godrick farsan hier"}},["57b226ed"]={q="Was will Godrick Farsan?",a="Godrick möchte die dunklen Studien der Hexenmeister der Unterstadt voranbringen. Durch zermürbende Prüfungen, die rituelle Komponenten wie die Hearts of the Pure und der Unschuldigen beinhalten, testet er Eure Entschlossenheit und Eure Fähigkeit, gefährliche Dämonen des Wirbelnden Nether zu befehligen.",al={"godrick farsan ziel","was will godrick","godrick farsan motive"}}},fp="14,198,16.410.0,22.199.0,35.104.0,37.60.0,43.152.0"}
P.entries["npc:golnir-bouldertoe"] = {n="Golnir Geröllzeh",s="Golnir Geröllzeh ist ein zwergischer Bergbauhändler, der neben der geschäftigen Großen Schmiede in Eisenschmiede stationiert ist. Er stellt grundlegende Vorräte für Bergleute und Prospektoren bereit und kümmert sich um Depeschen für örtliche Kuriere und Reisende.",h="Golnir Geröllzeh ist ein zwergischer Bergbauhändler, der neben der geschäftigen Großen Schmiede in...",kw={"bouldertoe","kohle","flussmittel","golnir","die große schmiede","eisenschmiede","bergbauzulieferer"},ang={["profession:Mining"]="Bergleute, die die Große Schmiede besuchen, verlassen sich auf Golnir, wenn es um wichtige Werkzeuge für ihr Handwerk geht, einschließlich Ersatzhacken und Flussmitteln, die zum Schmelzen von Roherz zu veredelten Barren benötigt werden.",["race:Dwarf"]="Für Zwerge, die von ihren ersten Reisen aus Coldridge oder Kharanos zurückkehren, dient Golnir als früher Kontaktpunkt in der Hauptstadt und heißt Reisende direkt neben dem feurigen Herzen des Berges willkommen."},sec={{t="Händler der Großen Schmiede",b="Inmitten der dröhnenden Hitze der Großen Schmiede von Eisenschmiede rüstet Golnir Geröllzeh Prospektoren und Handwerker mit dem Notwendigen für ihr Gewerbe aus. Von robusten Bergbauhacken bis hin zu Flussmitteln und Kohle befeuern seine Waren die unermüdlichen Schmelzöfen und Schmieden, die die zwergische Hauptstadt prägen. Als Verwandter von Geofram Bouldertoe ist Golnir ein zuverlässiger Ansprechpartner für Arbeiter, die in der Stadt ankommen; oft weist er neue Arbeitskräfte ein oder nimmt Versorgungsdepeschen entgegen, die von nahegelegenen Außenposten herbeigeschafft werden."}},faq={{q="Wo finde ich Golnir Geröllzeh?",a="Golnir Geröllzeh befindet sich in der Großen Schmiede in Eisenschmiede und steht dort zusammen mit anderen Handelsleuten in der Nähe der zentralen Schmelz- und Schmiedebereiche.",al={"golnir standort","wo ist golnir","golnir geröllzeh eisenschmiede"}},{q="Welche Waren verkauft Golnir?",a="Er fungiert als Bergbauzulieferer und verkauft wichtige Handelsausrüstung wie Bergbauhacken, Kohle und Flussmittel, um Prospektoren beim Graben und Veredeln von Roherz zu unterstützen.",al={"golnir händlerwaren","was verkauft golnir","golnir inventar"}},{q="Ist Golnir Geröllzeh an Quests beteiligt?",a="Ja. Kurierquests, die umliegende zwergische Siedlungen mit der Hauptstadt verbinden, wie zum Beispiel Botengänge, die Gryth Thurden und eintreffende Flüge von Außenposten wie Thelsamar betreffen, weisen Reisende an, Nachrichten direkt Golnir zu überbringen.",al={"golnir quests","flug nach eisenschmiede golnir"}},{q="Ist Golnir mit jemand anderem in Dun Morogh verwandt?",a="Golnir teilt seinen Clannamen mit Geofram Bouldertoe, dem Bergbaulehrer, der neben ihm in der Großen Schmiede von Eisenschmiede arbeitet.",al={"bouldertoe familie","geofram bouldertoe verwandter"}}},fx={["5f6dd933"]={q="Wer ist Golnir Geröllzeh?",a="Golnir Geröllzeh ist ein Zwergenhändler, der als Bergbauausstatter innerhalb der Großen Schmiede von Eisenschmiede arbeitet. Er versorgt die Prospektoren und Schmiede, die am geschmolzenen Herzen der Stadt arbeiten, mit wichtigen Vorräten, Spitzhacken und Schmelzbedarf.",al={"wer ist golnir","golnir geröllzeh hintergrundgeschichte","golnir identität"}},b602f757={q="Auf wessen Seite steht Golnir Geröllzeh?",a="Golnir ist ein loyaler Untertan von Eisenschmiede und des Clans Bronzebart und steht fest an der Seite der Großen Allianz. Er betreibt seinen Handel im geschäftigen Zentrum des Königreichs und dient sowohl seinen Zwergenbrüdern als auch reisenden Besuchern der Allianz.",al={"golnir fraktion","golnir loyalität","golnir seite"}},["7131f874"]={q="Warum ist Golnir Geröllzeh hier?",a="Golnir bleibt in der Nähe der Großen Schmiede, wo die Hitze nie erlischt und ständig Erz geschmolzen wird. Da Bergleute und Schmiede aus ganz Dun Morogh und darüber hinaus ihre Funde direkt zur zentralen Esse von Eisenschmiede bringen, hält Golnir seinen Laden in der Nähe, um sie mit der notwendigen Ausrüstung zu versorgen.",al={"warum ist golnir in eisenschmiede","golnir rolle große schmiede","warum ist golnir hier"}}},fp="17,218,27.473.0,35.154.0,28.154.0,44.236.0,47.125.0"}
P.entries["npc:gorbold-steelhand"] = {n="Gorbold Stahlhand",s="Gorbold Stahlhand ist ein Zwergenhändler, der in Auberdine an der nebligen Küste der Dunkelküste stationiert ist. Weit entfernt von den verschneiten Hallen von Khaz Modan versorgt er Reisende, Handwerker und einheimische Nachtelfen mit allgemeinen Waren und Handwerkswaren.",h="Gorbold Stahlhand ist ein Zwergenhändler, der in Auberdine an der nebligen Küste der Dunkelküste stationiert...",kw={"auberdine","dunkelküste","deep ocean vast sea","gorbold","eisenschmiede","händler","steelhand","warenhändler"},ang={["faction:Alliance"]="Gorbold veranschaulicht die praktische Zusammenarbeit zwischen den östlichen Völkern der Allianz und den Nachtelfen und sorgt dafür, dass der Handel über das große Meer hinweg floriert.",["race:Dwarf"]="Ein vertrautes Gesicht aus Eisenschmiede wie Gorbold in der nebligen, nächtlichen Umgebung der Dunkelküste zu erblicken, bietet reisenden Zwergen eine willkommene Erinnerung an die Heimat."},sec={{t="Ein Zwergenhändler in Kalimdor",b="Während der Großteil der nördlichen Weiten Kalimdors von den zurückgezogen lebenden Nachtelfen bewohnt wird, sind Außenposten der Allianz wie Auberdine auf Händler von jenseits des großen Meeres angewiesen, um den Handel aufrechtzuerhalten. Gorbold Stahlhand repräsentiert die weitreichende Präsenz des Handels aus Eisenschmiede in dieser Region. Seite an Seite mit den Kaldorei verkauft er Handwerkswaren, Reagenzien, Herstellungsbedarf und Werkzeuge an Abenteurer, die sich auf Erkundungen der tückischen Küsten und Wälder der Dunkelküste vorbereiten."},{t="Maritime Unternehmungen",b="Neben dem Verkauf alltäglicher Waren behält Gorbold auch die gefährlichen Küstengewässer vor Auberdine aufmerksam im Auge. Die von Riffen durchzogenen Gewässer der Dunkelküste sind berüchtigt dafür, Schiffe der Allianz zu verschlingen, und Händler wie Gorbold haben ein direktes Interesse an den unter den Wellen verlorenen Frachten. Reisende, die bereit sind, in die Tiefen des Ozeans hinabzutauchen, stoßen bei ihm oft auf Interesse an Bergungsgut und verschollenen Logbüchern aus versunkenen Wracks."}},faq={{q="Wer ist Gorbold Stahlhand?",a="Gorbold Stahlhand ist ein Zwerg und Händler für allgemeinen Handwerksbedarf, der im Küstenhafen Auberdine an der Dunkelküste ansässig ist.",al={"gorbold","wer ist gorbold stahlhand","zwerg in auberdine"}},{q="Was verkauft Gorbold Stahlhand?",a="Er führt allgemeinen Handwerksbedarf, Handwerkszutaten, Sammelwerkzeuge sowie Reagenzien wie Phiolen und Fäden, die von durch Auberdine reisenden Handwerkern benötigt werden.",al={"was verkauft gorbold","gorbold handwerkswaren","gorbold händlerliste"}},{q="Warum lebt ein Zwerg aus Eisenschmiede an der Dunkelküste?",a="Auberdine dient als zentraler Umschlagplatz der Allianz, der Kalimdor mit den Östlichen Königreichen verbindet. Zwerge reisen häufig hierher, um Handel zu treiben, Erkundungen durchzuführen und verbündete Operationen der Nachtelfen zu unterstützen.",al={"warum ist hier ein zwerg","warum ist gorbold an der dunkelküste","eisenschmiede in auberdine"}},{q="Bietet Gorbold Quests an?",a="Ja, in der Quest 'Tiefer Ozean, weites Meer' schickt er Abenteurer zu versunkenen Schiffswracks vor der Küste der Dunkelküste, um verlorene Schiffsladung zu bergen.",al={"gorbold quest","deep ocean vast sea questgeber"}}},fx={["59afaf53"]={q="Auf wessen Seite steht Gorbold Stahlhand?",a="Gorbold Stahlhand ist fest mit der Allianz verbündet. Als Zwerg aus Eisenschmiede, der im Nachtelfen-Zufluchtsort Auberdine Geschäfte macht, unterhält er freundschaftliche Beziehungen zu den dortigen Kaldorei und heißt Reisende, die der Allianz treu sind und die Dunkelküste durchqueren, willkommen.",al={"gorbold stahlhand fraktion","ist gorbold stahlhand allianz","gorbold loyalität"}}},fp="17,242,28.454.0,17.401.0,25.106.0,33.157.0,46.193.0,30.141.0"}
P.entries["npc:gordon-wendham"] = {n="Gordon Wendheim",s="Gordon Wendheim ist ein Waffenschmied und Händler der Verlassenen, der im geschäftigen Handwerksviertel von Unterstadt tätig ist. Er rüstet neu eingetroffene Champions und örtliche Verteidiger der Dunklen Fürstin mit verlässlichem Stahl, Klingen und stumpfen Waffen aus. Neben dem Feilbieten einfacher Rüstgüter dient er häufig als lokaler Ansprechpartner für Kuriere, die von der Oberfläche eintreffen.",h="Gordon Wendheim ist ein Waffenschmied und Händler der Verlassenen, der im geschäftigen Handwerksviertel von...",kw={"verlassene","gordon wendheim","michael garrett","handwerksviertel","unterstadt","waffenhändler"},ang={["class:Warrior"]="Gordon bietet verlässliche Grundklingen und Hiebwaffen für Frontkämpfer, die ihre Waffenfertigkeiten in der Hauptstadt ausbauen möchten.",["race:Undead"]="Für frisch befreite Verlassene, die Todesend verlassen, stellen Händler wie Gordon Wendheim im Handwerksviertel das praktische Rückgrat der Kriegsanstrengungen ihres noch jungen Volkes dar."},sec={{t="Rüstungsgüter des Handwerksviertel",b="Inmitten des feuchten Mauerwerks und der chemischen Kanäle im Handwerksviertel von Unterstadt versorgt Gordon Wendheim jene mit grundlegenden Waffen, die für die Verlassenen zu den Waffen greifen. Von einfachen Dolchen und Handäxten bis hin zu robusten Breitschwertern und Streitkolben richtet sich sein Sortiment an angehende Kämpfer, die verlässliches Eisen benötigen, bevor sie sich in die umkämpften Weiten von Lordaeron wagen."},{t="Ziel eines Kuriers",b="Über seinen Warenhandel hinaus ist Wendham in das rege Logistiknetzwerk der Hauptstadt eingebunden. Reisende, die von Flugmeistern und Kurieren auf Botengänge geschickt werden – wie etwa jene in Verbindung mit den Fledermausführern über den Ruinen –, werden oft direkt zu seinem Stand gewiesen. Seine zentrale Lage im Handwerksviertel macht ihn zu einer leicht erreichbaren und vertrauten Anlaufstelle für die Koordination grundlegender Vorräte und Depeschen in der gesamten unterirdischen Stadt."}},faq={{q="Wer ist Gordon Wendheim?",a="Gordon Wendheim ist ein untoter Händler, der im Handwerksviertel von Unterstadt stationiert ist. Er verkauft standardmäßige Kriegswaffen und dient als Ansprechpartner für Kuriere, die in der Hauptstadt eintreffen.",al={"gordon wendheim lore","wer ist wendham","unterstadt gordon"}},{q="Wo befindet sich Gordon Wendheim?",a="Ihr findet ihn an seinem Waffenstand im Handwerksviertel, dem Handelsring in den unterirdischen Hallen von Unterstadt.",al={"gordon wendheim aufenthaltsort","wo ist gordon unterstadt","handwerksviertel waffenhändler"}},{q="Was verkauft er?",a="Er bietet eine breite Palette grundlegender Standardwaffen an, darunter Schwerter, Dolche, Streitkolben, Stäbe, Äxte und verschiedene Wurfwaffen, die für aufstrebende Abenteurer geeignet sind.",al={"wendhams waren","was verkauft gordon","gordon wendheim waffen"}},{q="Welche Quests schließen ihn ein?",a="Er ist in einführende Lieferungen eingebunden, die die Fledermaushorste an der Oberfläche mit dem Inneren von Unterstadt verbinden, darunter Lieferungen zwischen ihm und dem Fledermausführer Michael Garrett.",al={"gordon wendheim quests","flug nach unterstadt","michael garrett quest"}}},fx={["84654bd5"]={q="Auf wessen Seite steht Gordon Wendheim?",a="Gordon Wendheim ist treu ergeben gegenüber Fürstin Sylvanas Windläufer und den Verlassenen und steht im Einklang mit der größeren Horde. Von seinem Laden in der Unterstadt aus unterstützt er seine untoten Verwandten, indem er Reisende und Soldaten ausstattet, die ihr zurückerobertes Königreich unter den Ruinen von Lordaeron verteidigen.",al={"fraktion gordon wendheim","wem dient gordon wendheim","ist gordon wendheim horde"}},d70aab3f={q="Warum ist Gordon Wendheim in der Unterstadt?",a="Gordon Wendheim geht seinem Handwerk als Waffenschmied im belebten Handwerksviertel der Unterstadt nach. Umgeben von den unterirdischen Hallen der Hauptstadt der Verlassenen steht er bereit, um jedem, der sich in die feindseligen Lande darüber begeben will, Klingen, Äxte und Streitkolben zu liefern.",al={"warum ist gordon wendheim hier","zweck gordon wendheim unterstadt","was führt gordon wendheim hierher"}}},fp="14,351,30.365.0,23.429.0,22.181.0,32.140.0,18.166.0,24.173.0"}
P.entries["npc:gornek"] = {fx={a3ac85eb={q="Auf wessen Seite steht Gornek?",a="Gornek ist Thralls Neuer Horde gegenüber loyal. Er ist in Durotar stationiert und dient als Aufseher im Tal der Prüfungen, wo er sicherstellt, dass jeder neu erwachte Orc und jeder Troll-Rekrut die Disziplin, Stärke und Überlebensmentalität annimmt, die notwendig sind, um ihre junge Nation zu verteidigen.",al={"gornek fraktion","wem dient gornek","gornek horde oder allianz"}},e623e91b={q="Was will Gornek?",a="Gornek möchte, dass Ihr Euch der Horde als würdig erweist. Durotar ist ein raues Land, das vor Raubtieren und feindlichen Infiltratoren wimmelt, und er weigert sich, Ressourcen an undisziplinierte Rekruten zu verschwenden. Er beauftragt junge Krieger damit, gefährliche Bestien zu jagen und lokale Bedrohungen auszuschalten, um sie zu fähigen Kämpfern zu formen.",al={"gornek ziel","was braucht gornek","gornek quest motive"}},a6376a9f={q="Warum ist Gornek im Tal der Prüfungen?",a="Das Tal der Prüfungen ist das ausgewiesene Übungsgelände für das neueste Blut der Horde. Gornek ist hier stationiert, um Neuankömmlinge anzuleiten, ihre ersten Fähigkeiten zu bewerten und sie mit den Ausbildern und Prüfungen bekannt zu machen, die sie auf die Herausforderungen von Durotar und darüber hinaus vorbereiten werden.",al={"warum ist gornek hier","gornek rolle tal der prüfungen","warum ist gornek in durotar"}}}}
P.entries["npc:gramma-stonefield"] = {n="Oma Steinfeld",s="Oma Steinfeld, deren Vorname Mildred lautet, ist die betagte Matriarchin der Steinfeld-Familie, die auf ihrem Bauernhof im Wald von Elwynn lebt. Im Gegensatz zu ihrer streitsüchtigen Verwandtschaft ist sie der bitteren, generationenlangen Fehde mit den benachbarten Maclures überdrüssig geworden. Im Stillen hinter dem Rücken ihrer Familie tut sie alles in ihrer Macht Stehende, um ihrem Enkel Tommy Joe bei seiner verbotenen Romanze mit Maybell Maclure zu helfen.",h="Oma Steinfeld, deren Vorname Mildred lautet, ist die betagte Matriarchin der Steinfeld-Familie, die auf ihrem...",kw={"elwynn","oma steinfeld","maclure","maybell","mildred","hof der steinfelds","tommy joe","william pestle"},ang={["faction:Alliance"]="Oma Steinfeld ist eine sanfte Erinnerung daran, dass selbst im Kernland der Allianz lokale Konflikte oft eher leise Diplomatie und schlichtes Mitgefühl als blanken Stahl erfordern."},sec={{t="Eine heimliche Friedensstifterin",b="Als ältestes lebendes Mitglied der Steinfeld-Sippe hat Mildred Steinfeld jahrzehntelange kleinliche Streitigkeiten zwischen ihrem Hof und den Maclures auf der anderen Straßenseite miterlebt. Anstatt das böse Blut noch weiter anzufachen, betrachtet sie die anhaltende Rivalität als sinnlos und zerstörerisch. Als sich ihr Enkel Tommy Joe Steinfeld in Maybell Maclure verliebt, entscheidet sich Oma für Mitgefühl statt Sippentreue. Gestützt auf eine alte Freundschaft mit William Pestle in Goldhain schmiedet sie im Stillen Pläne, um den unglücklich Liebenden heimliche Treffen zu ermöglichen und so die sture Feindseligkeit zu untergraben, die die beiden Höfe trennt."}},faq={{q="Wer ist Oma Steinfeld?",a="Oma Steinfeld, mit Vornamen Mildred, ist die betagte Matriarchin der Steinfeld-Familie, die auf ihrem Bauernhof im zentralen Wald von Elwynn lebt. Sie ist die Großmutter von Tommy Joe Steinfeld.",al={"wer ist oma","mildred stonefield","stonefield oma"}},{q="Was hält sie von der Fehde mit den Maclures?",a="Mildred hat kein Interesse daran, die Fehde aufrechtzuerhalten. Anders als die meisten Mitglieder beider Familien hält sie den Groll für töricht und schädlich und wünscht sich Harmonie zwischen den Höfen statt endloser Zankereien.",al={"stonefield maclure fehde","hasst sie die maclures"}},{q="Warum hilft sie Tommy Joe und Maybell?",a="Sie liebt ihren Enkel Tommy Joe und möchte, dass er glücklich ist. Da sie die Familienfehde ablehnt, unterstützt sie tatkräftig seine verbotene Romanze mit Maybell Maclure, indem sie ihren alten Freund William Pestle bittet, eine Lösung für das Paar zu brauen.",al={"warum tommy joe helfen","oma liebestrank","verliebten helfen"}},{q="In welcher Beziehung steht William Pestle zu ihr?",a="William Pestle, der im Gasthaus \"Zur Höhle des Löwen\" in Goldhain lebende Alchemist, ist ein alter und vertrauter Freund von Oma Steinfeld. Sie wendet sich über vertrauenswürdige Boten an ihn, um feinsinnige Mittelchen und Hilfen für Tommy Joe zubereiten zu lassen.",al={"william pestle verbindung","william pestle oma"}}},fx={d471da09={q="Warum ist Oma Steinfeld hier?",a="Diese Hütte ist ihr Zuhause, in dem sie ihr Leben lang gelebt hat. Als Matriarchin und ältestes lebendes Mitglied des Clans Steinfeld wohnt Mildred direkt hier auf dem Hof der Steinfelds im Wald von Elwynn und wacht still über ihre Verwandten, während sie versucht, ihre kleinen Rivalitäten davon abzuhalten, junge Leben zu zerstören.",al={"warum ist oma steinfeld auf dem hof","hof der stonefields oma standort","warum ist mildred steinfeld hier"}}},fp="17,404,19.576.0,25.178.0,51.211.0,41.239.0,29.226.0"}
P.entries["npc:grand-mason-marblesten"] = {n="Großsteinmetz Marmorstein",s="Großsteinmetz Marmorstein ist ein hochangesehener Zwergensteinmetz, der im belebten Platzviertel von Eisenschmiede stationiert ist. Zutiefst dem königlichen Erbe von Khaz Modan verpflichtet, wurde er von König Magni Bronzebart damit beauftragt, eine Gedenkstätte für Sully Balloo zu errichten – einen Zwergensoldaten, der bei der Tragödie am Thandol-Übergang fiel. Abenteurer begegnen ihm oft, wenn sie bei der Beschaffung der für dieses feierliche Denkmal benötigten Materialien behilflich sind.",h="Großsteinmetz Marmorstein ist ein hochangesehener Zwergensteinmetz, der im belebten Platzviertel von...",kw={"ehrerbietung von einem könig","bronzebeard","platzviertel","großsteinmetz","eisenschmiede","magni","marblesten","steinmetz","sully balloo"},ang={["faction:Alliance"]="Das Opfer von Sully Balloo zu ehren, erinnert die Allianz an jeden Soldaten, den sie in ihren Kriegen verloren hat.",["profession:Mining"]="Bergleute, die intensiv mit dem Gestein von Dun Morogh und darüber hinaus vertraut sind, werden Marblestens anspruchsvolle Maßstäbe an die Rohstoffqualität zu schätzen wissen.",["race:Dwarf"]="Für Zwerge ist die Steinkunst ein Erbe der Ahnen; Marblesten zu helfen, erweist sowohl dem Handwerk von Khaz Modan als auch dem Andenken an den gefallenen Soldaten Sully Balloo die Ehre."},sec={{t="Meister des Steins",b="Die Zwergensteinmetzkunst ist nicht bloß ein Handwerk; sie ist eine beständige Kunstform, die die Seele von Eisenschmiede prägt. Großsteinmetz Marmorstein gehört zu den herausragendsten Meißelmeistern der Stadt und repräsentiert die jahrhundertealte Tradition, Hallen, Säulen und gewaltige Bildnisse direkt aus dem lebendigen Fels zu hauen. Vom Platzviertel aus leitet er städtische Bauvorhaben und Denkmäler, die die Geschichte der Bronzebeard verewigen."},{t="Ehrerbietung von einem König",b="Marblestens ergreifendste Aufgabe ist ein Mahnmal, das König Magni für Sully Balloo in Auftrag gab – einen Soldaten, der bei der Tragödie am Thandol-Übergang starb –, als Ehrung für dessen trauernde Witwe. Da er ein wahrhaft beständiges Werk schaffen will, besteht der Großsteinmetz auf einem der edelsten Steine überhaupt: Alteracgranit von Darrow Hill in Hillsbrad."}},faq={{q="Wer ist Großsteinmetz Marmorstein?",a="Großsteinmetz Marmorstein ist ein erfahrener Zwergensteinmetz im Platzviertel von Eisenschmiede. Ihm sind städtische und königliche Bildhauerprojekte anvertraut, allen voran eine Gedenkstätte für den gefallenen Soldaten Sully Balloo im Auftrag von König Magni Bronzebart.",al={"wer ist marblesten","marblestens rolle","großsteinmetz nsc"}},{q="Wo kann ich Großsteinmetz Marmorstein finden?",a="Er hält sich im Platzviertel von Eisenschmiede auf, umgeben von Steinblöcken und architektonischen Arbeiten, unweit der geschäftigen Läden und Banken der Stadt.",al={"marblesten standort","wo ist marblesten","eisenschmiede marblesten"}},{q="An welchem Denkmal arbeitet Marblesten?",a="Er errichtet eine Gedenkstätte für Sully Balloo, einen Zwergensoldaten, der bei der Tragödie am Thandol-Übergang starb. König Magni Bronzebart gab sie als Würdigung für Balloo und seine trauernde Witwe in Auftrag.",al={"was baut er","quest ehrerbietung von einem könig","marblestenteinstatue"}},{q="Warum benötigt Marblesten Abenteurer, um Materialien zu beschaffen?",a="Marblesten möchte ein wahrhaft monumentales und dauerhaftes Werk schaffen, weshalb er nur mit einem der edelsten Steine arbeiten will. Er schickt Reisende nach Darrow Hill in Hillsbrad, um Alteracgranit zu sammeln.",al={"marblesten quests","warum steine nötig","materialien für denkmal"}},{q="Was bedeutet der Titel „Großsteinmetz“ in der Zwergengesellschaft?",a="Unter Zwergen wird die Steinbearbeitung neben der Schmiedekunst gleichermaßen verehrt. Ein „Großsteinmetz“ ist ein meisterhafter Vollender der Steinkunst, dem bedeutende staatliche Vorhaben, königliche Architekturentwürfe und zeremonielle Denkmäler anvertraut werden.",al={"was ist ein großsteinmetz","zwergensteinmetz rang"}},{q="Ist Marblesten ein Beamter der Allianz oder ein privater Auftragnehmer?",a="Marblesten agiert direkt innerhalb von Eisenschmiede und dient dem Königreich Eisenschmiede sowie der Allianz, wobei er eng mit dem Hof von König Magni Bronzebart bei königlichen Aufträgen zusammenarbeitet.",al={"für wen arbeitet marblesten","marblestens fraktion"}}},fx={a77cb24b={q="Auf wessen Seite steht Großsteinmetz Marmorstein?",a="Marmorstein ist Eisenschmiede und der Allianz gegenüber absolut loyal. Er ist direkt im Herzen des Stadtviertels der Commons stationiert, dient König Magni Bronzebart und dem Zwergenkönigreich und widmet sein Handwerk und seine Steinmetzkunst der Ehrung des Zwergenerbes und des Throns.",al={"marmorstein fraktion","wem dient marmorstein","marmorstein allianz"}},["1dc5a337"]={q="Was will Großsteinmetz Marmorstein?",a="Marmorstein beaufsichtigt ein königliches Denkmal und benötigt feine Materialien, um es fertigzustellen. Durch seine Arbeit an 'A King's Tribute' sucht er nach fähigen Abenteurern, die ihm helfen, die wesentlichen Ressourcen für das von König Magni in Auftrag gegebene Denkmal für den gefallenen Soldaten Sully Balloo zu beschaffen.",al={"was will marmorstein","marmorstein ziel","warum braucht marmorstein hilfe"}},["98aae54f"]={q="Warum ist Großsteinmetz Marmorstein in den Commons?",a="Marmorstein hat seine Werkstatt in den geschäftigen Commons von Eisenschmiede eingerichtet, um die Steinmetzarbeiten der großen Bergfestung zu überwachen und die Bauarbeiten für den Thron zu organisieren. Der offene Platz ermöglicht es ihm, Projekte zu koordinieren und Reisende, die durch die Stadt kommen, zu rekrutieren.",al={"warum ist marmorstein in eisenschmiede","warum ist marmorstein hier","marmorstein commons eisenschmiede"}}},fp="22,395,19.426.0,16.312.0,30.247.0,40.154.0,39.182.0,57.184.0,58.210.0,59.176.0"}
P.entries["npc:granis-swiftaxe"] = {n="Granis Flinkaxt",s="Granis Flinkaxt ist ein Kriegerlehrer der Zwerge, der in der Brauerei Donnerbräu in Kharanos stationiert ist. Bekannt für sein schroffes Auftreten und seinen harten Trainingsplan, unterweist er angehende Kämpfer der Allianz, die aus der Eisklamm kommen, bevor er erfahrene Krieger in die Stadt Eisenschmiede schickt.",h="Granis Flinkaxt ist ein Kriegerlehrer der Zwerge, der in der Brauerei Donnerbräu in Kharanos stationiert ist.",kw={"dun morogh","granis flinkaxt","kharanos","muren stormpike","brauerei donnerbräu","kriegerlehrer"},ang={["class:Warrior"]="Für Kämpfer der Zwerge und Gnome, die das Coldridgetal verlassen, bietet Granis wichtige grundlegende Kampfausbildung direkt neben einem frischen Krug in der Brauerei.",["race:Dwarf"]="Granis verkörpert den robusten und sturen Geist der Fußsoldaten von Eisenschmiede und verbindet kriegerische Disziplin mit den Annehmlichkeiten des einheimischen Bieres."},sec={{t="Ein schroffer Mentor in Kharanos",b="Granis Flinkaxt wärmt sich zwischen den Fässern der Brauerei Donnerbräu auf und dient als primärer Kampfausbilder für junge Krieger, die Dun Morogh durchqueren. Er besitzt den unbeugsamen Stolz, der typisch für Zwergenkämpfer ist, und zeigt offene Belustigung sowie Verachtung gegenüber Nicht-Kriegern, die versuchen, Gehör bei ihm zu finden. Sobald ein Schüler ausreichendes Kampfgeschick beweist, schickt Granis ihn den Bergpfad hinauf, um Meisterausbilder Muren Stormpike im Military Ward von Eisenschmiede aufzusuchen."}},faq={{q="Wer ist Granis Flinkaxt?",a="Granis Flinkaxt ist ein Kriegerlehrer der Zwerge, der sich im Erdgeschoss der Brauerei Donnerbräu in Kharanos befindet. Er lehrt junge Zwergen- und Gnomkrieger, die Abenteuer in Dun Morogh erleben, frühe Kampftechniken.",al={"granis flinkaxt","wer ist granis","kriegerlehrer in kharanos"}},{q="Warum verspottet Granis meinen Charakter?",a="Granis hat keine Geduld für jene, die nicht den Pfad des Kriegers beschreiten. Wenn ein Abenteurer einer anderen Klasse mit ihm spricht, spottet er über die Vorstellung, dass dieser auch nur einen einzigen Tag unter seinem harten Trainingsplan überleben könnte.",al={"granis unhöfliches zitat","warum lacht granis über mich","granis text für nicht-krieger"}},{q="Wohin schickt Granis aufstrebende Krieger?",a="Sobald ein Krieger genug Erfahrung in Dun Morogh gesammelt hat, weist Granis ihn an, Muren Stormpike aufzusuchen, einen ranghohen Kriegerlehrer im Military Ward von Eisenschmiede.",al={"muren stormpike quest","granis questreihe","zu wem schickt granis einen"}},{q="Ist Granis mit anderen Flinkäxten in Khaz Modan verwandt?",a="Er teilt den Nachnamen Flinkaxt mit anderen Zwergen, doch eine familiäre Beziehung ist nicht bestätigt.",al={"familie flinkaxt","granis flinkaxt verwandte"}}},fx={b8e95117={q="Auf wessen Seite steht Granis Flinkaxt?",a="Granis steht fest an der Seite der Zwerge von Eisenschmiede und der breiteren Allianz. Er ist in Kharanos stationiert und widmet seine militärische Expertise dem Training der nächsten Generation von Verteidigern gegen die Troggs, Frosttrolle und andere Bedrohungen in der Umgebung von Dun Morogh.",al={"granis flinkaxt fraktion","für wen kämpft granis","granis allianz"}},["760b1803"]={q="Warum ist Granis Flinkaxt in Kharanos?",a="Granis ist in der Brauerei Donnerbräu in Kharanos stationiert, um angehende Krieger der Allianz auszubilden, die von der Eisklamm aufbrechen. Dun Morogh steht unter wachsendem Druck durch einheimische Troggs und Wendigos, was seine rigorosen Kampfübungen für die lokale Verteidigung unerlässlich macht.",al={"warum ist granis hier","granis flinkaxt standort grund","was brachte granis nach kharanos"}},cf3183bb={q="Was will Granis Flinkaxt?",a="Granis will nichts Geringeres als abgehärtete, disziplinierte Krieger, die in der Lage sind, die Linie für Khaz Modan zu halten. Er hat wenig Geduld für Schwache oder Unausgebildete und fordert unerbittliches Engagement von Rekruten, bevor er vielversprechende Veteranen an Meister wie Muren Stormpike in Eisenschmiede weiterleitet.",al={"granis flinkaxt ziele","was will granis","granis zweck"}}},fp="15,285,26.485.0,23.216.0,34.218.0,42.170.0,51.91.0"}
P.entries["npc:great-father-winter"] = {n="Altvater Winter",s="Altvater Winter ist ein älterer Orc, der von der Handelsgesellschaft Kokelwälder angestellt wurde, um in Orgrimmar als die legendäre Festtagsgestalt aufzutreten. Während des Winterhauchfests hat er seinen Platz nahe Grommash Hold im Tal der Stärke bezogen, wo er sich die Wünsche der Kinder anhört, während ihm der kommerzielle Feiertagstrubel zusehends zusetzt. Im Austausch für Festtagsgeschenke und saisonale Aufgaben bittet er Vorbeigehende regelmäßig um Lebkuchen und Eiskalte Milch.",h="Altvater Winter ist ein älterer Orc, der von der Handelsgesellschaft Kokelwälder angestellt wurde, um in...",kw={"lebkuchen","altvater winter","orgrimmar","kokelwälder","tal der stärke","winterhauch"},ang={["faction:Horde"]="Er dient als wichtigste saisonale Identifikationsfigur für die Horde in Orgrimmar und bietet im Namen von Kokelwälder Festtagsgeschenke und Aufgaben an.",["profession:Cooking"]="Köche können nach festlichen Rezepten Lebkuchen backen und diese zusammen mit Milch direkt zu Altvater Winter bringen, um seine Lebensgeister zu wecken.",["race:Orc"]="Obwohl Orcs den Wechsel der Jahreszeiten und die Elemente verehren, stellt der Anblick eines der Ihren als kostümiertes Maskottchen, das Händlerrabatte anpreist, die Geduld von Traditionalisten auf die Probe."},sec={{t="Ein gemieteter Mythos",b="Während alte Überlieferungen von Altvater Winter als einem majestätischen Elementargeist sprechen, der durch das Land zieht und Schnee sowie den Wandel der Jahreszeiten bringt, ist die Gestalt im Tal der Stärke weitaus weltlicher. Er ist ein orcischer Darsteller auf der Gehaltsliste von Kokelwälder, der eigens angeheuert wurde, um den Handel anzukurbeln, Waren der Gesellschaft zu bewerben und die Jugend der Horde zu unterhalten. Kritiker murren, dass dieses kommerzielle Maskottchen echte saisonale Traditionen entwerte, doch kaum jemand kann die festliche Betriebsamkeit leugnen, die er in die Straßen der Stadt bringt."},{t="Schichtarbeit im Tal der Stärke",b="Direkt vor Grommash Hold unter den Zweigen geschmückter Nadelbäume erträgt dieser Vertreter eine zermürbende Schicht, in der Kinder auf seinen Schoß klettern, um ihre Geschenkwünsche vorzubringen. Zwischen eingeworfenen Werbesprüchen für Rabatte von Kokelwälder und halbherzigen Feiertagsgrüßen lässt seine Ausdauer spürbar nach. Er gibt unumwunden zu, eine Flasche hochprozentiger Festtagsstimmung in seinem Rucksack versteckt zu haben, um den Lärm zu ertränken, sobald seine Schicht endet, und ist stark darauf angewiesen, dass durchreisende Abenteurer ihm stärkende Leckereien bringen."}},faq={{q="Ist dies der echte Altvater Winter?",a="Nein. Er ist ein gewöhnlicher Orc, der von Kokelwälder angeheuert wurde, um sich zu verkleiden, die legendäre Winterhauch-Gestalt darzustellen und in Orgrimmar Festtagsangebote zu verteilen.",al={"ist er echt","wer ist altvater winter","ist er ein schauspieler"}},{q="Wo finde ich Altvater Winter in Orgrimmar?",a="Er befindet sich im Tal der Stärke, direkt vor dem Eingang zu Grommash Hold neben dem Winterhauchbaum und den Festtagsständen.",al={"altvater winter standort","wo ist altvater winter","wo findet man den winter-orc"}},{q="Was tut er während des Winterhauchfests?",a="Er unterhält Festtagsbesucher, hört sich die Geschenkwünsche der Kinder an, vergibt Werbeaufgaben für Kokelwälder und überreicht festliche Geschenke unter dem Baum, sobald der Höhepunkt der Feiertage erreicht ist.",al={"was macht er","altvater winter aufgabe","winterhauch quests"}},{q="Warum verlangt er Lebkuchen und Milch?",a="Laute Menschenmengen und ein Kind nach dem anderen auf seinem Schoß zu ertragen, laugt ihn völlig aus. Er bittet Abenteurer darum, ihm frische Lebkuchen und Milch zu bringen, um bei Kräften durch die Schicht zu kommen.",al={"leckereien für altvater winter","warum milch und kekse","lebkuchen quest"}},{q="Wie steht er zu seiner Arbeit?",a="Er empfindet die Rolle als mühselig und kräftezehrend. Er meckert offen über ungeduldige Kinder, leiert Unternehmensparolen herunter und zählt ungeduldig die Minuten, bis er einen Schluck aus der Flasche nehmen kann, die er in seiner Tasche versteckt hat.",al={"mag er seinen job","altvater winter zitate","ist er betrunken"}},{q="Gibt es aufseiten der Allianz eine entsprechende Gestalt?",a="Ja. Die Allianz hat Altvater Winter, einen älteren Zwerg im Dienst von Kokelwälder, der nahe dem Festtagsbaum im The Commons von Eisenschmiede sitzt.",al={"allianz altvater","eisenschmiede weihnachtsmann","allianz gegenstück"}}},fx={["1d43ce2e"]={q="Auf wessen Seite steht Altvater Winter?",a="Dieser Altvater Winter ist ein Orc, der ausschließlich innerhalb von Orgrimmar für die Horde arbeitet, obwohl sein eigentlicher Arbeitgeber Smokywood Pastures ist. Das Goblin-Unternehmen heuerte ihn an, um festliche Stimmung – und festliche Konsumausgaben – ins Tal der Stärke zu bringen. Während er das festliche rote Gewand der Legende trägt, gilt seine wahre Loyalität seinem Gehaltsscheck und dem Überstehen seiner zermürbenden Schicht.",al={"ist altvater winter horde","altvater winter fraktion","für wen arbeitet altvater winter"}},["796ea74c"]={q="Warum ist Altvater Winter hier?",a="Er ist vor Grommash Hold stationiert, weil Smokywood Pastures ihn engagierte, um ihre Feierlichkeiten zum Winterhauchfest in der Hauptstadt der Horde zu verankern. Die kaufmännischen Goblins setzten ihn ein, um die Jugend der Stadt zu unterhalten, sich ihre Geschenkwünsche anzuhören und eifrige Familien zu Feiertagswaren und festlichen Leckereien zu lenken.",al={"warum ist altvater winter in orgrimmar","was brachte altvater winter hierher","grund warum altvater winter hier ist"}},f14772a5={q="Mit wem ist Altvater Winter verbunden?",a="Er ist direkt bei Smokywood Pastures angestellt, dem unternehmerischen Goblin-Betrieb, der für die Vermarktung des Winterhauchfests im ganzen Reich verantwortlich ist. Sie liefern sein festliches Kostüm, legen seine Werbesprüche fest und organisieren die Geschenke und Leckereien, die er rund um Grommash Hold verteilt.",al={"wer hat altvater winter angeheuert","altvater winter verbindungen","smokywood pastures altvater winter"}},["826ac72e"]={q="Warum ist Altvater Winter berühmt?",a="Er beansprucht den Namen und die Gestalt von Altvater Winter, einer alten übernatürlichen Figur, die in ganz Azeroth gefeiert wird, weil sie den Wechsel der Jahreszeiten ankündigt. Während Gelehrte argumentieren, dass dieser kostümierte Orc lediglich ein kommerzielles Maskottchen ist, strömen Kinder und festliche Feiernde immer noch zu ihm als dem lebendigen Gesicht der Freude des Winterhauchfests.",al={"warum kennen leute altvater winter","ist altvater winter legendär","altvater winter ruf"}}},fp="19,438,12.510.0,36.525.0,36.154.0,50.145.0,48.183.0,46.205.0,30.223.0,44.149.0"}
P.entries["npc:greatfather-winter"] = {n="Altvater Winter",s="Altvater Winter ist die legendäre Personifizierung der Wintersaison und die zentrale Gestalt des Winterhauchfests. Während uralte Legenden ihn als mythisches Wesen verehren, das Azeroth mit Schnee bedeckt, damit das Land ruhen und sich erneuern kann, kennen moderne Stadtbewohner ihn vor allem durch das kommerzielle Spektakel, das von den Goblins der Kokelwälder bereitgestellt wird.",h="Altvater Winter ist die legendäre Personifizierung der Wintersaison und die zentrale Gestalt des...",kw={"dun morogh","lebkuchen","altvater winter","eisenschmiede","orgrimmar","kokelwälder","winterhauchfest"},ang={["profession:Cooking"]="Das Fest verlässt sich auf geschickte Köche, um Lebkuchen und andere festliche Leckereien für die Kokelwälder und Altvater Winter selbst zuzubereiten.",["race:Dwarf"]="Zwerge sehen den Altvater als einen Aspekt der Titanen, die die Welt formten, und betrachten die verschneiten Gipfel von Dun Morogh als lebendiges Zeugnis seiner Berührung."},sec={{t="Mythos und Erneuerung",b="Uralten Überlieferungen zufolge ist Altvater Winter ein ätherischer Wanderer, der spät im Jahr die Welt durchstreift und seinen wogenden Schneemantel über das Land breitet, damit die Natur schlummern und wiedergeboren werden kann. Zwerge betrachten ihn als eine Verkörperung oder einen Herold der Titanen und verweisen auf die verschneiten Felsen von Dun Morogh als lebenden Beweis seiner Gunst. Andere Traditionen, wie jene der Tauren, respektieren seine Rolle beim Wandel der Jahreszeiten, schreiben die Kälte und die Stürme jedoch dem elementaren Wirken von Sonne und Mond zu, die der Erdenmutter Zeit zur Ruhe schenken. Wohin die Legende auch gelangte, lernten die Gemeinschaften, zusammenzukommen und gemeinsam gegen die Kälte zu schmausen, um das Versprechen wiederkehrenden Lebens zu feiern."},{t="Die Kokelwälder und städtische Feierlichkeiten",b="In großen Siedlungen wie Eisenschmiede und Orgrimmar wurde der uralte Geist von den geschäftstüchtigen Goblins der Kokelwälder von Grund auf umgestaltet. Das Handelskartell machte die Darstellung von Altvater Winter als fröhlichem, rot gekleidetem Greis mit weißem Bart populär, der auf einem fliegenden Schlitten fährt und festliche Leckereien sowie Spielzeug verteilt. Die Kokelwälder heuern lokale Schauspieler an – einen Zwerg in Eisenschmiede und einen Ork in Orgrimmar –, um die Wunschzettel der Kinder anzuhören, Gaben von Milch und Lebkuchen entgegenzunehmen und unter aufwendig geschmückten Bäumen saisonale Waren anzupreisen."}},faq={{q="Ist der Altvater Winter in Eisenschmiede der echte Geist?",a="Nein, der Altvater Winter, der am Festtagsbaum in Eisenschmiede sitzt, ist ein Schauspieler, der von der Goblin-Handelsgesellschaft Kokelwälder engagiert wurde. Die Gesellschaft inszeniert diese Auftritte, um Kinder zu erfreuen und saisonale Süßwaren zu verkaufen, wenngleich echte Legenden von einem tatsächlichen ätherischen Wesen berichten, das im Winter die Welt durchstreift.",al={"ist altvater winter echt","wer ist der typ in eisenschmiede","ist er ein schauspieler"}},{q="Warum verehren die Zwerge Altvater Winter?",a="Zwerge bringen Altvater Winter mit ihren Schöpfern, den Titanen, in Verbindung. Sie betrachten die Schneedecke, die er über das Land wirft, als Segen und sehen ihre dauerhaft eisige Heimat Dun Morogh als besten Beweis seiner Gunst an.",al={"zwerge winterhauchfest","zwergischer altvater winter","eisenschmiede altvater winter"}},{q="Was macht Altvater Winter mit den Keksen und der Milch, die man ihm bringt?",a="Nach den von den Kokelwäldern verbreiteten Festtagsbräuchen nascht Altvater Winter für sein Leben gern festliche Lebkuchen und eiskalte Milch, während er Wunschzettel durchgeht und Festtagsstimmung verbreitet.",al={"leckereien für altvater winter","warum milch und kekse","lebkuchen quest"}},{q="Wie betrachtet die Horde Altvater Winter?",a="Die Horde nimmt an den Festlichkeiten größtenteils durch die städtischen Aktionen der Kokelwälder in Orgrimmar teil, wo der Altvater als Ork dargestellt wird. Kulturell erkennen die Tauren den Winter als lebenswichtige Zeit des Schlummers und der elementaren Erneuerung für die Erdenmutter an; sie respektieren die Rolle des Altvaters im Kreislauf der Jahreszeiten, meiden jedoch eine buchstäbliche Titanenverehrung.",al={"horde altvater winter","orgrimmar altvater winter","tauren winterhauchfest"}}},fx={["66677a0e"]={q="Auf wessen Seite steht Altvater Winter?",a="Er gehört keiner Fraktion an. Der Legende nach ist Altvater Winter eine uralte, übernatürliche Naturgewalt, die der ganzen Welt saisonale Erneuerung und Reichtum schenkt, ungeachtet der Loyalität der Sterblichen. Die Gestalt, die Ihr in Eisenschmiede sitzen seht, wird von der Goblin-Handelsgesellschaft Raucherdampf gesponsert, die einen streng neutralen, gewinnorientierten Betrieb führt. Tatsächlich heuert Raucherdampf einen Orc an, der in Orgrimmar sitzt und gleichzeitig die Feiertagsstimmung unter der Horde verbreitet.",al={"altvater winter allianz oder horde","gehört altvater winter zur allianz","fraktion altvater winter"}},a8f1de98={q="Was will Altvater Winter?",a="Der uralte Geist des Mythos möchte die Welt nur in Winter hüllen, um dem Land die nötige Zeit für Ruhe, Wiedergeburt und letztendliche Erneuerung zu geben, während er denjenigen, die ihn willkommen heißen, Reichtum gewährt. Der sterbliche Nachahmer, den Ihr in Eisenschmiede trefft, ist jedoch bei Raucherdampf angestellt. Ihr Ziel ist rein festlich und kommerziell: Freude zu bringen, Leckereien an brave Kinder zu verteilen und den Verkauf ihrer Feiertagswaren und Spielzeuge anzukurbeln.",al={"beweggründe altvater winter","was will altvater winter","warum verteilt altvater winter geschenke"}},daa32740={q="Warum ist Altvater Winter in Eisenschmiede?",a="Raucherdampf hat ihn neben dem Altvater-Winter-Baum stationiert, um ihre saisonalen Feierlichkeiten zu verankern. Während der Wochen vor dem Fest trifft sich die fröhliche Gestalt mit Bürgern und Kindern, um ihre Feiertagswünsche zu hören, Briefe zu sammeln und gemeinsam mit seinen Goblin-Helfern guten Willen zu verbreiten – all das, während er Raucherdampf dabei hilft, ihre saisonalen Waren zu bewerben.",al={"warum ist altvater winter in eisenschmiede","warum ist altvater winter hier","standort altvater winter eisenschmiede"}},["8b922b4d"]={q="Mit wem ist Altvater Winter verbunden?",a="Die zwergische Tradition verbindet den uralten Geist eng mit den Titanen und glaubt, dass er ihre formende Kraft über die Jahreszeiten von Azeroth verkörpert. In der täglichen Praxis arbeitet der festliche Altvater, den man in der Stadt sieht, mit Raucherdampf zusammen, umgeben von ihren winzigen Kleinen Helfern und festlichen Schneemännern.",al={"mit wem wird altvater winter in verbindung gebracht","verbindungen altvater winter","wer arbeitet mit altvater winter"}}},fp="18,362,16.674.0,39.571.0,55.303.0,41.228.0,73.202.0,43.359.0"}
P.entries["npc:greatmother-hawkwind"] = {fx={f701fe56={q="Auf wessen Seite steht Großmutter Falkenwind?",a="Großmutter Falkenwind widmet sich ihrem Volk, den Tauren der Horde. Als älteste Matriarchin von Camp Narache liegt ihre Loyalität ganz bei ihrem Stamm, ihrer Familie und den jungen Kriegern, die ausziehen, um den Ahnen und der Erdenmutter zu dienen.",al={"fraktion großmutter falkenwind","wem dient großmutter falkenwind","loyalität großmutter falkenwind"}},["8d52ad78"]={q="Was will Großmutter Falkenwind?",a="Trotz ihres hohen Alters besteht Großmutter Falkenwind darauf, ihren Teil zur Versorgung von Camp Narache beizutragen. Sie kümmert sich um die Bedürfnisse der Siedlung, erledigt einfache häusliche Pflichten wie das Heranschaffen von frischem Wasser aus dem Dorfbrunnen und bittet junge Tauren, bei diesen bescheidenen alltäglichen Aufgaben eine Helfende Hand zu reichen.",al={"was braucht großmutter falkenwind","ziel großmutter falkenwind","warum mit großmutter falkenwind sprechen"}},["2db356dc"]={q="Warum ist Großmutter Falkenwind hier?",a="Großmutter Falkenwind lebt als Dorfälteste und Mutter von Häuptling Falkenwind in Camp Narache. Ihr findet sie am zentralen Wasserbrunnen der Siedlung, wo sie fleißig arbeitet, um ihren Stamm zu unterstützen und über die jungen Jäger und Schamanen wacht, die ihre Reise auf der Hochwolkenebene beginnen.",al={"warum ist großmutter falkenwind in camp narache","standort großmutter falkenwind grund","warum ist sie am brunnen"}}}}
P.entries["npc:grelin-whitebeard"] = {fx={bc052fbe={q="Wer ist Grelin Weißbart?",a="Grelin Weißbart ist ein Ermittler, der im Auftrag des Senats von Eisenschmiede und König Magni Bronzebart in Das Coldridgetal geschickt wurde. Er ist damit beauftragt, die aggressiven Bewegungen der Frostmähneneistrolle zu beurteilen, und unterhält ein abgelegenes Lager im verschneiten Tal, wobei er sich auf frische Rekruten der Gebirgswache verlässt, um die Trolle zurückzudrängen, während die zwergische Hauptarmee anderswo beschäftigt ist.",al={"wer ist grelin","lore grelin weißbart","wer ist weißbart"}},d217c46a={q="Auf wessen Seite steht Grelin Weißbart?",a="Grelin ist dem Königreich Eisenschmiede und der Großen Allianz vollkommen loyal. Er berichtet direkt an den Senat von Eisenschmiede und führt Depeschen bei sich, die von König Magni selbst unterzeichnet wurden, und arbeitet unermüdlich daran, die zwergischen Lande gegen äußere Bedrohungen zu sichern.",al={"fraktion grelin weißbart","für wen arbeitet grelin","ist grelin allianz"}},["6d2fc414"]={q="Was will Grelin Weißbart?",a="Grelin möchte eine schnelle Lösung für das Problem mit den Frostmähneneistrollen im südlichen Coldridgetal. Da die zwergische Wache durch die Bekämpfung von Trogg-Einfällen gebunden ist, benötigt er fähige Abenteurer, die die aggressiven Trolle ausdünnen, sein gestohlenes Tagebuch vom Trollanführer Grik'nir zurückholen und seinen fertigen Aufklärungsbericht an seinen Bruder in Kharanos übermitteln.",al={"was versucht grelin zu tun","ziel grelin weißbart","was benötigt grelin"}}}}
P.entries["npc:greta-mosshoof"] = {n="Greta Mooshuf",s="Greta Mooshuf ist eine Taurendruidin, die mit dem Smaragdkreis im Smaragdrefugium im südlichen Teufelswald verbündet ist. Seite an Seite mit Nachtelfen und anderen Hütern der Natur untersucht sie das üble Verderben, das durch den uralten Wald kriecht, und schickt Späher in die Festung des Schattenrats in Jaedenar.",h="Greta Mooshuf ist eine Taurendruidin, die mit dem Smaragdkreis im Smaragdrefugium im südlichen Teufelswald...",kw={"verderbtes wasser","smaragdkreis","das smaragdrefugium","teufelswald","greta mooshuf","islen wasserdeuter","jaedenar"},ang={["class:Druid"]="Für Druiden, die daran arbeiten, die Narben der Brennenden Legion zu tilgen, verkörpert Greta Mooshuf den Geist der Zusammenarbeit des Zirkels des Cenarius, der fraktionelle Bindungen beiseiteschiebt, um die Wildnis von Kalimdor wiederherzustellen.",["race:Tauren"]="Greta zeigt die Hingabe der Tauren an die Heilung der Wunden der Erdenmutter – selbst weit im Norden in Landen, die einst allein von den Nachtelfen bewacht wurden."},sec={{t="Hüterin des Waldes",b="Im Smaragdrefugium an der südlichen Grenze des Teufelswalds stationiert, arbeitet Greta Mooshuf an der Seite des Smaragdkreises, um die um sich greifende Verderbnis zu bekämpfen, die die uralten Wälder verzehrt. Anstatt die verheerten Lande dem dämonischen Verderben zu überlassen, das im Gefolge des Dritten Krieges zurückblieb, koordiniert sie die Bemühungen, die sich ausbreitende Fäulnis zu verstehen und zurückzudrängen. Ihre Untersuchungen konzentrieren sich auf die vergifteten Gewässer des Teufelswalds und die üblen Kultisten, die sich in Jaedenar eingenistet haben."},{t="Gegen den Schattenrat zuschlagen",b="Greta Mooshuf ist maßgeblich daran beteiligt, die Machenschaften des Schattenrats aufzudecken, der aus den Tiefen von Jaedenar operiert. Da sie erkennt, dass die verderbten Quellen und üblen Schutzsiegel in der Schlucht die Krankheit, die das Land erstickt, direkt nähren, gewinnt sie Reisende dafür, Proben der verunreinigten Gewässer zu nehmen, den Beistand von Schamanen wie Islen Wasserdeuter an der fernen Küste zu suchen und die rituellen Kohlenbecken zu zerstören, die die dämonische Kabale vor Eindringlingen schützen."}},faq={{q="Wer ist Greta Mooshuf?",a="Greta Mooshuf ist ein Tauren-Mitglied des Smaragdkreises, das im Smaragdrefugium im Teufelswald stationiert ist. Sie hilft Reisenden und Druiden dabei, die dämonische Plage, die den Wald vergiftet, zu untersuchen und rückgängig zu machen.",al={"greta mooshuf lore","wer ist greta mooshuf","greta teufelswald"}},{q="Zu welcher Fraktion gehört Greta Mooshuf?",a="Greta Mooshuf ist ein Mitglied des Smaragdkreises, einer neutralen Organisation, die sich der Heilung der Natur widmet. Als solche bietet sie sowohl Abenteurern der Allianz als auch der Horde Führung und Quests an.",al={"ist greta mooshuf horde oder allianz","greta mooshuf ruf","greta fraktion"}},{q="Warum schickt Greta Abenteurer nach Jaedenar?",a="Jaedenar ist die Festung des Schattenrats im Teufelswald, der dafür verantwortlich ist, dämonische Galle in die Gewässer des Landes zu pumpen und Schutzsiegel aufrechtzuerhalten, die Dämonen Unterschlupf gewähren. Greta leitet Angriffe gegen Jaedenar, um deren Rituale zu zerschlagen und die verseuchten Quellen zu reinigen.",al={"warum jaedenar quest","greta mooshuf jaedenar","kräfte von jaedenar grund"}},{q="Welche Verbindung besteht zwischen Greta Mooshuf und Islen Wasserdeuter?",a="Greta ist mit Islen Wasserdeuter befreundet, einer weisen Schamanin, die an der Küste des Brachlands lebt. Als Greta verderbte Wasserproben aus dem Teufelswald entdeckt, weist sie Abenteurer an, Islens spirituelle Meisterschaft zu erbitten, um die Flüssigkeit zu läutern, damit sie die vergifteten Quellen reinigen kann.",al={"greta und islen","islen wasserdeuter verbindung"}}},fp="14,297,22.465.0,30.441.1,22.202.0,43.181.0,47.265.0,55.268.0"}
P.entries["npc:grif-wildheart"] = {fx={["5a030de6"]={q="Auf wessen Seite steht Grif Wildherz?",a="Grif Wildherz ist fest loyal gegenüber Eisenschmiede und der Großen Allianz. Er dient seinem Volk, indem er junge zwergische Jäger in Kharanos ausbildet und sicherstellt, dass sie die Disziplin und die Überlebensfähigkeiten besitzen, die nötig sind, um das Bergkönigreich und seine Gebiete zu schützen.",al={"fraktion grif wildherz","ist grif allianz","loyalität grif wildherz"}},a3b5e7f5={q="Was will Grif Wildherz?",a="Grif widmet sich der Weitergabe des Handwerks der Wildnis. Er möchte, dass aufstrebende Jäger das Zähmen von Wildtieren und das Überleben in der Wildnis meistern, und schickt Novizen in den Schnee von Dun Morogh, damit sie Respekt, Geduld und den Aufbau lebenslanger Bindungen mit den Kreaturen der zerklüfteten Berge lernen.",al={"ziel grif wildherz","was will grif","motiv grif wildherz"}},["20183458"]={q="Warum ist Grif Wildherz in Kharanos?",a="Grif ist in Kharanos stationiert, um frische Rekruten auszubilden, die aus dem Coldridgetal herabsteigen. Als zentraler Knotenpunkt in Dun Morogh ist Kharanos der ideale Prüfstand für junge Jäger, die bereit sind, ihren Verstand gegen die Eber, Leoparden und Bären des Berges zu testen.",al={"warum ist grif hier","warum ist grif in dun morogh","warum ist grif in kharanos"}}}}
P.entries["npc:grimbooze-thunderbrew"] = {fx={["21ebedd0"]={q="Wer ist Schnapsbart Donnerbräu?",a="Schnapsbart ist ein schrulliger, fröhlicher Zwergenbrauer aus dem berühmten Donnerbräu-Clan von Dun Morogh. Bekannt für seine legendäre Liebe zum Bier und seine Neigung, in Rätseln und Versen zu sprechen, verließ er das Zuhause seiner Familie in Kharanos, um in den Hügeln von Westfall sein eigenes Bier zu brauen.",al={"wer ist schnapsbart","schnapsbart donnerbräu","über schnapsbart"}},["182004c2"]={q="Auf wessen Seite steht Schnapsbart Donnerbräu?",a="Schnapsbart ist, wie der Rest des Donnerbräu-Clans, Eisenschmiede und der Allianz treu ergeben. Seine wahre Leidenschaft gilt jedoch eher dem Brauen und guten Getränken als der Politik oder dem Fraktionskrieg, was ihn zu einem freundlichen Gesicht für jeden macht, der ein gutes Bier zu schätzen weiß.",al={"fraktion schnapsbart","ist schnapsbart allianz","seite schnapsbart"}},["9bf66a40"]={q="Was will Schnapsbart Donnerbräu?",a="Schnapsbart ist immer auf der Suche danach, seine Spezialbiere zu brauen und sie mit Mitreisenden zu teilen. Im Austausch für Zutaten oder ein wenig Hilfe bietet er Euch nur allzu gerne Proben des starken Donnerbräu-Lagers an, um Eure Stimmung hochzuhalten.",al={"was will schnapsbart","ziel schnapsbart","warum braucht schnapsbart hopfen"}},d50f3d5e={q="Warum ist Schnapsbart Donnerbräu in Westfall?",a="Schnapsbart hat die kalten Gipfel von Dun Morogh hinter sich gelassen und ist in Die Dolchhügel gezogen, wo er nun seine Tage damit verbringt, weit weg von der familiären Brennerei in Kharanos zu brauen und in Versen zu philosophieren.",al={"warum ist schnapsbart in westfall","schnapsbart westfall grund","was macht schnapsbart in westfall"}}}}
P.entries["npc:grish-longrunner"] = {n="Grish Fernläufer",s="Grish Fernläufer ist ein Späher und Bote der Tauren, der in der Nähe des Großen Aufzugs stationiert ist – dem lebenswichtigen mechanischen Übergang, der das Südliche Brachland mit den Canyons von Tausend Nadeln verbindet. Im Dienste der Horde an dieser belebten Grenze behält er Reisende im Auge und koordiniert militärische Bewegungen entlang der Front.",h="Grish Fernläufer ist ein Späher und Bote der Tauren, der in der Nähe des Großen Aufzugs stationiert ist – dem...",kw={"brachland","hinzurufen der reserve","der große aufzug","grish","longrunner","tauren","tausend nadeln"},ang={["faction:Horde"]="Für Kuriere und Krieger der Horde, die nach Süden in Richtung Tausend Nadeln reisen oder nach Norden ins Brachland zurückkehren, dient Grish als wichtiger Ausguck und Kontaktpunkt am Aufzug.",["race:Tauren"]="Mit dem stolzen Namen Longrunner verkörpert Grish die Ausdauer und Wachsamkeit der Shu'halo, während sie lebenswichtige Pfade durch ihre angestammten Heimatländer sichern."},sec={{t="Wächter am Aufzug",b="Direkt neben den hoch aufragenden Maschinen des Großen Aufzugs hält Grish Fernläufer Wache an einem der heikelsten Grenzübergänge Zentral-Kalimdors. Der Plattformaufzug ist eine Lebensader, die das karge Südliche Brachland mit den windgepeitschten Hochebenen von Tausend Nadeln darunter verbindet. Zwischen umherstreifenden Stacheleber-Rudeln und konkurrierenden Bedrohungen im Umland ist das Reisen entlang dieser vertikalen Grenze gefährlich. Daher sind Späher wie Grish unerlässlich, um die Horde auf dem Laufenden zu halten und Verstärkung dorthin zu rufen, wo sie dringend gebraucht wird."}},faq={{q="Wer ist Grish Fernläufer?",a="Grish Fernläufer ist ein mit der Horde verbündeter Taurenspäher, der am Rand des Großen Aufzugs stationiert ist, welcher vom Brachland hinab nach Tausend Nadeln führt.",al={"wer ist grish","grish fernläufer identität","was macht grish"}},{q="Wo finde ich Grish Fernläufer?",a="Er befindet sich in den südlichen Weiten des Brachlands, direkt am mechanischen Eingang des Großen Aufzugs, der hinunter nach Tausend Nadeln führt.",al={"grish fernläufer standort","wo ist grish","grish finden"}},{q="Welche Rolle spielt er in diesem Gebiet?",a="Grish dient als Ansprechpartner für Boten und Reisende der Horde und hilft vor allem dabei, örtliche Verstärkungen durch Aufträge wie „Hinzurufen der Reserve“ zu sammeln und zu leiten.",al={"grish zweck","grish quests","hinzurufen der reserve grish"}}},fx={["0053ed11"]={q="Auf wessen Seite steht Grish Fernläufer?",a="Grish ist ein stolzes Mitglied der Taurenstämme und loyal zur Horde. Er operiert an den Grenzen zum Brachland und dem Abstieg nach Tausend Nadeln und dient als Kontaktperson für Reisende der Horde, die die gefährlichen Passagen zwischen den Regionen navigieren.",al={"fraktion grish fernläufer","ist grish horde","loyalität grish fernläufer"}}},fp="16,329,19.537.0,24.164.0,34.140.0,35.180.0"}
P.entries["npc:grub"] = {n="Grub",s="Grub ist ein geschäftstüchtiger Ork, der in einer Hütte am Wegesrand östlich des Wegekreuzes im Brachland lebt. Zusammen mit einem Koch und einem Bäcker betreibt er ein bescheidenes Grenzgasthaus und ist berühmt – oder vielleicht berüchtigt – dafür, Reisenden den kulinarischen Nutzen des einheimischen Ungeziefers näherzubringen.",h="Grub ist ein geschäftstüchtiger Ork, der in einer Hütte am Wegesrand östlich des Wegekreuzes im Brachland...",kw={"brachland","das wegekreuz","grubenratteneintopf","duhng","grub","tarban hearthgrain"},ang={["faction:Horde"]="Direkt vor den Toren des Wegekreuzes gelegen, bietet Grubs Küche am Wegesrand herzhafte Stärkung und eine Lektion in Einfallsreichtum für Reisende der Horde, die in den rauen Ebenen überleben wollen.",["profession:Cooking"]="Grub ist eine unverzichtbare Anlaufstelle für angehende Grenzköche und bereit, das Rezept für Grubenratteneintopf mit jedem zu teilen, der mutig genug ist, die Zutaten zu sammeln."},sec={{t="Appetit an der Grenze",b="Eingebettet an den Felsen östlich des Wegekreuzes wacht Grub über eine rustikale Behausung, die er mit Duhng, seinem Koch, und Tarban Hearthgrain, einem Bäcker, teilt. Während das Leben in den Ebenen einen robusten Magen erfordert, treibt Grub die Selbstversorgung an der Grenze auf die Spitze. Anstatt die reichlich vorhandenen Grubenratten des Brachlands verkommen zu lassen, hat er sie zu einer Hauptzutat gemacht und bietet vorbeiziehenden Wanderern an, ihnen beizubringen, wie man die unterirdischen Nager zu einem herzhaften, wenn auch wenig glamourösen Eintopf verkocht."}},faq={{q="Wer ist Grub?",a="Grub ist ein Ork, der in einer Hütte östlich des Wegekreuzes im Brachland wohnt. Er betreibt zusammen mit seinem Koch Duhng und einem Bäcker namens Tarban Hearthgrain ein kleines Etablissement und verköstigt Reisende, die durch das staubige Grenzland ziehen.",al={"grub","wer ist grub","ork östlich von das wegekreuz"}},{q="Wo finde ich Grub?",a="Grub ist östlich des Wegekreuzes am Fuße der Berge im Brachland zu finden, gelegen in einer kleinen Behausung abseits des Hauptweges.",al={"grub aufenthaltsort","wo ist grub","grubs hütte"}},{q="Wobei benötigt Grub Hilfe?",a="Grub beauftragt Reisende damit, Grubenratten aus dem Brachland zu sammeln, die für die Zubereitung seines unverkennbaren Grubenratteneintopfs verwendet werden. Im Gegenzug teilt er das Rezept mit Köchen, die bereit sind, es zuzubereiten.",al={"grub quest","grubenratteneintopf quest"}}},fx={["1dd1f89b"]={q="Auf wessen Seite steht Grub?",a="Grub ist ein Orc, der mit der Horde verbündet ist und friedlich direkt außerhalb vom Das Wegekreuz im Brachland arbeitet. Er heißt Reisende der Horde in seinem kleinen Gehöft willkommen und treibt Geschäfte mit anderen Köchen, Bäckern und vorbeiziehenden Abenteurern, ohne sich in militärische Konflikte verstricken zu lassen.",al={"fraktion grub","ist grub horde","grub allianz oder horde"}},bef281f8={q="Warum ist Grub hier?",a="Grub hat östlich vom Das Wegekreuz am Fuße der Berge eine kleine häusliche Siedlung errichtet. Anstatt an der Front zu dienen, betreibt er eine kulinarische Wohnstätte zusammen mit seinem Koch Duhng und dem Bäcker Tarban Hearthgrain, wo sie lokale Grenzspeisen beschaffen und zubereiten.",al={"warum ist grub im brachland","grub hütte wegkreuz","was macht grub hier"}},c7807b4d={q="Mit wem ist Grub verbunden?",a="Grub teilt seine Hütte am Wegesrand mit Duhng, der für das Kochen zuständig ist, und Tarban Hearthgrain, der sich um das Backen kümmert. Zusammen führt diese ungewöhnliche Ansammlung von Gefährten ihre kleine Feuerstelle in den rauen Ebenen des Brachlands.",al={"mit wem arbeitet grub","grub gefährten","grub kontakte"}}},fp="4,263,19.477.0,12.229.0,22.144.0,30.181.0"}
P.entries["npc:grull-hawkwind"] = {n="Grull Falkenwind",s="Grull Falkenwind ist ein junger Krieger der Tauren, der im Camp Narache auf der Hochwolkenebene in Mulgore stationiert ist. Als Sohn von Häuptling Falkenwind hilft er dabei, unerfahrene Tauren anzuleiten, die ihre allerersten Schritte in die Welt wagen. Er führt junge Jäger und Krieger durch ihre ersten Prüfungen, um ihre Entschlossenheit auf die Probe zu stellen und ihre Vorfahren zu ehren.",h="Grull Falkenwind ist ein junger Krieger der Tauren, der im Camp Narache auf der Hochwolkenebene in Mulgore...",kw={"camp narache","häuptling falkenwind","grull falkenwind","mulgore","die hochwolkenebene","ritus der kraft","tauren"},ang={["class:Hunter"]="Grull versorgt angehende Jäger mit grundlegenden ersten Aufgaben und stellt ihre Geduld sowie ihr Können im Kampf gegen die Fauna von Mulgore auf die Probe.",["race:Tauren"]="Für junge Tauren, die die Hochwolkenebene betreten, ist Grull Falkenwind oft der allererste Krieger, der ihren Mut auf die Probe stellt und sie in die Traditionen der Shu'halo einführt."},sec={{t="Der Sohn eines Häuptlings",b="Stolz an der Seite der Krieger und Ältesten von Camp Narache stehend, trägt Grull Falkenwind sowohl die stolze Abstammung von Häuptling Falkenwind als auch die Verantwortung, die Jugend des Stammes vorzubereiten. Er dient den Neuankömmlingen auf der Hochwolkenebene als erster Mentor und beurteilt deren Bereitschaft, den Shu'halo zu dienen. Indem er Prüfungen auferlegt, die Ausdauer, Fährtenlesen und das Überleben gegen einheimische Bestien wie Ebenenschreiter und Berggorillas testen, stellt Grull sicher, dass junge Tauren begreifen, dass Gleichgewicht und Respekt vor der Natur das Fundament des Lebens in Mulgore bilden."}},faq={{q="Wer ist Grull Falkenwind?",a="Grull Falkenwind ist ein Questgeber der Tauren, der im Camp Narache auf der Hochwolkenebene weilt. Er ist der Sohn von Häuptling Falkenwind, dem Anführer der Siedlung, und fungiert als einer der wichtigsten Mentoren für junge Tauren, die ihre Reise beginnen.",al={"grull falkenwind rolle","wer ist grull","grull falkenwind lore"}},{q="Welche Rolle spielt Grull Falkenwind für junge Abenteurer?",a="Grull beurteilt die Grundausbildung unerfahrener Tauren, nimmt einführende Schriftstücke von den Stammesältesten entgegen und betraut die Jugend mit ihren ersten Prüfungen der Jagd und des Überlebens in den umliegenden Ebenen.",al={"grull quests","was macht grull","grull falkenwind zweck"}},{q="Ist Grull mit der Führung des Lagers verwandt?",a="Ja, Grull ist der Sohn von Häuptling Falkenwind, dem Häuptling von Camp Narache. Er wahrt die Traditionen seines Vaters und hilft dabei, die Verteidiger des Lagers vorzubereiten.",al={"häuptling hawkwinds sohn","grull falkenwind familie","ist grull mit dem häuptling verwandt"}}},fx={["36d17655"]={q="Auf wessen Seite steht Grull Falkenwind?",a="Grull Falkenwind steht stolz an der Seite der Taurenstämme und der Horde. Er lebt im Camp Narache und dient seinem Volk unter der Führung seines Vaters und des Hochhäuptlings Cairne Bluthuf, wobei er sich der Aufgabe widmet, jungen Tauren dabei zu helfen, zu fähigen Verteidigern ihrer angestammten Heimat in Mulgore heranzuwachsen.",al={"grull falkenwind fraktion","wem dient grull","grull falkenwind loyalität"}},["56962b2d"]={q="Was will Grull Falkenwind?",a="Grull möchte sehen, wie junge Tauren ihre Stärke und ihre Hingabe zum Stamm beweisen. Er prüft die ankommenden Jugendlichen, um sicherzustellen, dass sie über die nötige Standhaftigkeit, Disziplin und die Jagdfähigkeiten verfügen, um in der Wildnis zu überleben und das Camp Narache vor Bedrohungen aus der Nähe zu schützen.",al={"was will grull","grull falkenwind ziele","warum gibt grull quests"}},["379dd378"]={q="Warum ist Grull Falkenwind hier im Camp Narache?",a="Camp Narache ist der angestammte Prüfungsort für die Jugend, die auf der Hochwolkenebene erwachsen wird, und wird von Grulls Vater, Häuptling Falkenwind, geleitet. Grull bleibt hier, um neue Initianden bei ihren ersten Riten zu unterstützen und die Führung seiner Familie über das Lager zu stützen.",al={"warum ist grull hier","grull rolle im camp narache","warum ist grull auf der hochwolkenebene"}}},fp="14,320,17.542.0,22.230.0,57.194.0,42.146.0"}
P.entries["npc:grunt-dogran"] = {fx={["3efd280a"]={q="Wer ist Grunzer Dogran?",a="Grunzer Dogran ist ein Orc-Soldat der Horde. Nachdem er befördert wurde, war er im Wegekreuz stationiert, bevor er zum Camp Taurajo versetzt wurde. Während er ein Kontingent von Grunzer in das Südliche Brachland führte, um den Stachelebern entgegenzutreten, wurde er im Kampf schwer verwundet und von den borstigen Bestien gefangen genommen, die ihn nun gefesselt in ihrem Lager bei Agama'gor festhalten.",al={"wer ist dogran","identität von grunzer dogran","dogran hintergrund"}}}}
P.entries["npc:grunt-logmar"] = {n="Grunzer Logmar",s="Grunzer Logmar ist ein Orc-Krieger der Horde, der im südlichen Brachland in Camp Taurajo stationiert ist. Pflichtbewusst und wachsam behält er die Bedrohungen rund um das Lager im Auge und koordiniert die Bemühungen, vermisste Späher der Horde in der Region ausfindig zu machen und ihnen zu helfen.",h="Grunzer Logmar ist ein Orc-Krieger der Horde, der im südlichen Brachland in Camp Taurajo stationiert ist.",kw={"camp taurajo","dogran","grunzer logmar","ken'ziglas trunk","orc-grunzer","taurajo","brachland"},ang={["faction:Horde"]="Logmar verkörpert die militärische Präsenz an vorderster Front zur Unterstützung der Tauren im Brachland und verlässt sich auf die Helden der Horde, um sich um gefallene und gefangene Späher zu kümmern.",["race:Orc"]="Als weit von Orgrimmar entfernter Orc-Grunzer verdeutlicht Logmar die Entschlossenheit der Horde, Seite an Seite mit ihren Verbündeten, den Tauren, zu stehen."},sec={{t="Dienst in Camp Taurajo",b="Unter den Tauren in Camp Taurajo stationiert, dient Grunzer Logmar als wachsamer Orc-Wächter an der Grenze des südlichen Brachlands. Die Siedlung liegt nahe an feindseligen Gebieten der Borstennacken und den Gebirgspässen, die ins Steinkrallengebirge und nach Mulgore führen, was ständige Wachsamkeit erfordert. Logmar koordiniert Spähberichte und wendet sich an fähige Reisende der Horde, wenn seine Kameraden von einheimischen Feinden überfallen oder gefangen genommen werden."}},faq={{q="Wer ist Grunzer Logmar?",a="Grunzer Logmar ist ein Orc-Soldat, der in Camp Taurajo im südlichen Brachland stationiert ist. Er dient der Horde, indem er die Siedlung sichert und Rettungs- sowie Aufklärungsaufgaben überwacht.",al={"grunzer logmar","wer ist logmar","logmar brachland"}},{q="Wo ist Grunzer Logmar zu finden?",a="Er befindet sich in Camp Taurajo, einem Außenposten in den südlichen Ebenen des Brachlands an der Straße, die zum großen Aufzug und nach Tausend Nadeln führt.",al={"wo ist logmar","logmar standort","grunzer logmar finden"}},{q="Welche Angelegenheiten beaufsichtigt Logmar?",a="Logmar kümmert sich um die Sicherheit vermisster Horde-Späher. Vor allem beauftragt er Reisende damit, das Verschwinden und die Gefangennahme seines Kameraden Grunzer Dogran zu untersuchen und lebenswichtige Vorräte wie Ken'ziglas Trunk zu beschaffen.",al={"logmar quests","was will logmar","dogran rettung"}}},fx={ce116068={q="Auf wessen Seite steht Grunzer Logmar?",a="Grunzer Logmar ist ein loyaler Soldat der Horde. Er ist bei den Siedlungen der Tauren stationiert und dient dem Kriegshäuptling, indem er die südlichen Grenzen bewacht und die Operationen der Horde in den Ebenen unterstützt.",al={"ist logmar horde","grunzer logmar fraktion","grunzer logmar seite"}},["1f3f5c49"]={q="Warum ist Grunzer Logmar hier?",a="Logmar ist als Vorpostenwache stationiert, um die Verteidigung zu stärken und die militärische Kommunikation aufrechtzuerhalten. Die umliegende Wildnis stellt eine ständige Bedrohung durch feindliche Wildtiere, Zentaurenplünderer und nahe gelegene Stacheleber dar, was standhafte Soldaten erfordert, um Reisende zu schützen und das Südliche Brachland zu sichern.",al={"warum ist grunzer logmar hier","warum ist logmar in taurajo","logmar posten"}},e7dd0701={q="Was will Grunzer Logmar?",a="Logmar sucht Hilfe bei der Bewältigung dringender militärischer Notlagen in der Region, insbesondere bei der Rettung und Bergung gefangener Kameraden wie Dogran sowie bei der Beschaffung von stärkenden Tränken, die benötigt werden, um seine Mitstreiter im Feld zu versorgen.",al={"was will logmar","grunzer logmar ziel","was braucht grunzer logmar"}}},fp="12,235,20.419.0,20.174.0,32.155.0,33.201.0"}
P.entries["npc:grunth"] = {n="Grunth",s="Grunth ist ein energiegeladenes junges Orc-Waisenkind, das in der Obhut des Waisenhauses von Orgrimmar in der Gasse lebt. Während der Kinderwoche begleitet er eifrig Champions der Horde auf großen Reisen durch Kalimdor und die Östlichen Königreiche, um zu lernen, was es bedeutet, ein Held zu sein.",h="Grunth ist ein energiegeladenes junges Orc-Waisenkind, das in der Obhut des Waisenhauses von Orgrimmar in der...",kw={"kinderwoche","grunth","orc-waisenkind","orgrimmar","waisenmatrone schlachterbe","waisenpfeife","die gasse"},ang={["faction:Horde"]="Die Betreuung von Grunth während der Kinderwoche erinnert die Champions der Horde daran, was ihre Fraktion zu schützen versucht: eine heranwachsende Generation, die in Freiheit statt in dämonischer Knechtschaft geboren wurde.",["race:Orc"]="Grunth verkörpert die Jugend von Durotar, die aufwächst und Stammesere und Überleben kennt, anstatt die finstere Lethargie der Internierungslager."},sec={{t="Ein neugieriges Kind der Horde",b="Grunth lebt in der Gasse von Orgrimmar unter den wachsamen Augen von Waisenmatrone Schlachterbe und repräsentiert die nächste Generation der neu gegründeten Horde. Wie viele junge Grünhäute, die in Durotars rauen roten Einöden aufgewachsen sind, blickt er mit staunenden Augen und einem unerschöpflichen Strom von Fragen zu gerüsteten Abenteurern auf – er fragt sich, ob gerüstete Krieger wirklich furchterregend sind, warum Blitze auf dem Wasser nicht jeden Fisch töten und ob er jemals jemanden gegen einen echten Drachen kämpfen sehen wird."},{t="Reisen während der Kinderwoche",b="Wenn die Festzeit beginnt, blasen Abenteurer eine Pfeife des orcischen Waisenkindes, um Grunth herbeizurufen und ihn auf eine ausgedehnte Reise durch die Welt mitzunehmen. Seine Wunschliste erstreckt sich über das gesamte Gebiet der Horde: eine Audienz bei Oberhäuptling Cairne Bluthuf in Mulgore ersuchen, sich in den zerstörten Thronsaal von Lordaeron wagen und die rauen Grenzländer besuchen, in denen sein Volk für seine Zukunft kämpft."}},faq={{q="Wer ist Grunth?",a="Grunth ist ein Orc-Kind, das im Waisenhaus von Orgrimmar in der Gasse lebt. Er wird von Waisenmatrone Schlachterbe umsorgt und träumt davon, ein legendärer Held der Horde zu werden.",al={"grunth nsc","orc-waisenkind","orgrimmar waisenkind"}},{q="Wo ist Grunth zu finden?",a="Er hält sich mit den anderen Waisenkindern in der Gasse in Orgrimmar auf, doch während der Kinderwoche kann ein Abenteurer ihn überall mit einer Pfeife des orcischen Waisenkindes herbeirufen, die man von Waisenmatrone Schlachterbe erhält.",al={"grunth aufenthaltsort","wo ist grunth","grunth finden"}},{q="Welche Orte möchte Grunth besuchen?",a="Grunth sehnt sich danach, die größten Ikonen der Horde zu sehen. Zu seinen Bitten gehört es, Oberhäuptling Cairne Bluthuf in Donnerfels zu besuchen, die Docks von Ratschet zu besichtigen und den weiten Weg zum zerstörten Thronsaal von Lordaeron zu reisen.",al={"grunth quests","was will das waisenkind","grunth reise"}},{q="Welche Art von Persönlichkeit hat Grunth?",a="Grunth ist laut, neugierig und äußerst fantasievoll. Er stellt den Abenteurern, die ihn begleiten, ständig absurde Rätsel und kindliche Fragen, wie etwa, was „Zug Zug“ eigentlich bedeutet, ob eine flügellose Fliege eine Gehe heißt, und erwähnt beiläufig, dass er sich einen Stein in die Nase gesteckt hat.",al={"grunth zitate","grunth dialoge","was sagt grunth"}}},fx={ec5570c7={q="Auf wessen Seite steht Grunth?",a="Grunth gehört ganz zur Horde. Aufgewachsen in Orgrimmar unter der Obhut von Waisenmatrone Schlachterbe, blickt er zu den Champions der Horde auf und träumt davon, mächtige Taten mitzuerleben, wie etwa einen Helden dabei zu beobachten, wie er gegen einen wilden Drachen kämpft.",al={"grunth horde oder allianz","ist grunth horde","grunth fraktion"}},["06889c57"]={q="Warum ist Grunth in Orgrimmar?",a="Grunth ist ein orcisches Waisenkind, das unter der Obhut des Waisenhauses von Orgrimmar im Tal der Ehre lebt. Während der Kinderwoche darf er die Welt an der Seite eines erfahrenen Abenteurers der Horde erkunden, der seine eifrigen Fragen beantwortet und ihm die weitere Welt zeigt.",al={"warum ist grunth hier","warum ist grunth in orgrimmar","grund für grunths standort"}},["0a265be0"]={q="Mit wem ist Grunth verbunden?",a="Grunth wird von Waisenmatrone Schlachterbe im Waisenhaus in Orgrimmar betreut. Sie kümmert sich um den jungen Orc und vertraut ihn Abenteurern der Horde an, die bereit sind, ihn als Mentor zu begleiten und ihn auf Reisen durch Kalimdor und darüber hinaus mitzunehmen.",al={"wer kümmert sich um grunth","grunth verbindungen","grunth waisenmatrone"}}},fp="6,260,28.483.0,24.393.0,14.169.0,26.194.0,38.226.0,42.291.0"}
P.entries["npc:gryan-stoutmantle"] = {fx={["7558c158"]={q="Auf wessen Seite steht Gryan Starkmantel?",a="Gryan ist der Allianz, dem Königreich Sturmwind und vor allem dem einfachen Volk von Westfall gegenüber loyal. Während der königliche Hof von Sturmwind die Not der Provinz ignoriert, hat Gryan die Dinge selbst in die Hand genommen und führt die People's Militia an. Er bleibt ein treuer Ritter, der dafür kämpft, das Reich für seine rechtmäßigen Bürger zurückzugewinnen.",al={"gryan starkmantel fraktion","wem dient gryan","welcher fraktion gehört gryan an"}},c0a0d15a={q="Was will Gryan Starkmantel?",a="Gryan versucht, die The Defias Brotherhood auszurotten und Frieden, Recht und Ordnung in Westfall wiederherzustellen. Er will die überrannten Farmen der Provinz zurückgewinnen, die Banditen und Diebe, die ehrliche Siedler terrorisieren, vertreiben und die Sicherheit der Farmer gewährleisten, die von der Krone im Stich gelassen wurden.",al={"gryan starkmantel ziel","was will gryan","gryan motivation"}},d2149791={q="Warum ist Gryan Starkmantel in Westfall?",a="Westfall ist Gryans Heimat. Als ihn während des Dritten Krieges in Lordaeron die Nachricht erreichte, dass kriminelle Wegelagerer seinen Heimatboden überrannten und Farmer von ihrem Land vertrieben, kehrte er in den Süden zurück, um die Provinz zu verteidigen. Stationiert auf der Späherkuppe, führt er die People's Militia vom Herzen des umkämpften Gebiets aus an.",al={"warum ist gryan in westfall","warum kam gryan nach westfall","warum ist gryan auf der späherkuppe"}},["9073fb6b"]={q="Mit wem ist Gryan Starkmantel verbunden?",a="Gryan unterhält Verbindungen zu Mathias Shaw, dem Leiter des Geheimdienstes von Sturmwind SI:7, der ihn mit wichtigen Aufklärungsergebnissen bezüglich der Defias versorgt. Er ist auch mit Wiley der Schwarze im Rotkammgebirge verbunden, einem alten Bekannten, dessen Leben er einst rettete, und koordiniert sich mit lokalen Verteidigern in den benachbarten Ländern.",al={"gryan starkmantel verbündete","mit wem arbeitet gryan","gryan verbindungen"}}}}
P.entries["npc:guard-berton"] = {n="Wache Berton",s="Wache Berton ist ein menschlicher Stadtwächter, der vor dem Gasthaus von Seenhain im Rotkammgebirge stationiert ist. Frustriert über die bürokratischen Verzögerungen des Rechtssystems von Sturmwind sucht er nach rascher Gerechtigkeit gegen Targorr den Schrecklichen, einen inhaftierten Orc-Anführer.",h="Wache Berton ist ein menschlicher Stadtwächter, der vor dem Gasthaus von Seenhain im Rotkammgebirge...",kw={"berton","wache berton","seenhain","rotkammgebirge","targorr","targorr der schreckliche","das verlies","wie du mir so ich dir"},ang={["faction:Alliance"]="Berton verkörpert die wachsende Frustration in den ländlichen Siedlungen der Allianz, wo die örtlichen Verteidiger mit ansehen müssen, wie die zentrale Bürokratie von Sturmwind die Justiz verzögert, während Grenzdörfer ums Überleben kämpfen."},sec={{t="Ein Wächter auf der Suche nach Gerechtigkeit",b="Während das Rotkammgebirge unter der Bedrohung der Invasion der Schwarzfelsorcs einknickt, verharrt Wache Berton auf seinem Posten vor dem Gasthaus von Seenhain. Obwohl die örtliche Verteidigung an ihre Grenzen stößt, gilt Bertons Aufmerksamkeit einem gefangenen Feind: Targorr dem Schrecklichen. Targorr wurde gefangen genommen und tief im Verlies von Sturmwind eingesperrt, verurteilt zum Tode für seine Verbrechen gegen das Königreich. Doch da Sturmwinds Hinrichtung auf unbestimmte Zeit aufgeschoben wurde, weigert sich Berton, den brutalen Räuber in einer Zelle verweilen zu lassen, während Seenhain blutet. Er nimmt die Dinge selbst in die Hand und heuert willige Abenteurer an, um die königlichen Verzögerungen zu umgehen und den Orc direkt hinzurichten."}},faq={{q="Wer ist Wache Berton?",a="Wache Berton ist eine Wache der Allianz, die vor dem Gasthaus von Seenhain im Rotkammgebirge stationiert ist. Er ist vor allem dafür bekannt, Abenteurer anzuheuern, um an einem berüchtigten gefangenen Orc Gerechtigkeit zu üben.",al={"berton seenhain","wer ist berton"}},{q="Warum will Wache Berton, dass Targorr der Schreckliche getötet wird?",a="Targorr der Schreckliche wurde für seine Verbrechen zur Hinrichtung verurteilt, doch die Führung von Sturmwind setzte das Urteil aus. Frustriert über diese Verzögerung, während das Rotkammgebirge weiterhin belagert wird, arrangiert Berton Targorrs Beseitigung im Verlies.",al={"warum targorr töten","targorr hinrichtung","lore zur quest wie du mir so ich dir"}},{q="Wo wird Targorr der Schreckliche gefangen gehalten?",a="Targorr wird im Verlies festgehalten, dem Hochsicherheitskerker im Kanalviertel von Sturmwind.",al={"targorr aufenthaltsort","wo ist targorr"}},{q="Wo ist Wache Berton zu finden?",a="Er hält direkt vor dem Eingang zum Gasthaus von Seenhain Wache und überblickt das Stadtzentrum von Seenhain im Rotkammgebirge.",al={"wo ist berton","berton aufenthaltsort"}}},fx={["352370f6"]={q="Auf wessen Seite steht Wache Berton?",a="Wache Berton ist ein loyaler Verteidiger des Königreichs Sturmwind und der Allianz. Er ist im Rotkammgebirge stationiert und hat die Aufgabe, die bedrängte Stadt Seenhain und ihre Bewohner vor den Gefahren der umliegenden Wildnis zu schützen, einschließlich der plündernden Schwarzfelsorcs.",al={"berton fraktion","wem dient wache berton","ist berton allianz"}},bd53caa6={q="Mit wem ist Wache Berton verbunden?",a="Berton dient in der Stadtwache von Rotkammgebirge, die in Seenhain stationiert ist, und steht neben seinen Mitstreitern vor dem örtlichen Gasthaus. Über seine örtliche Garnison hinaus binden ihn seine Beschwerden direkt an Targorr der Schreckliche, einen berüchtigten Gefangenen, der in der Stormwind Stockade festgehalten wird.",al={"wache berton verbindungen","berton stadtwache","mit wem arbeitet berton"}}},fp="12,240,23.633.0,20.196.0,52.246.0,32.119.0,32.117.0"}
P.entries["npc:guard-howe"] = {n="Wache Howe",s="Wache Howe ist ein Stadtwächter, der nahe dem südlichen Fuß der Brücke von Seenhain im Rotkammgebirge stationiert ist. Getrieben von einer persönlichen Fehde gegen die Schwarzfelsorcs, die in das Tal vordringen, setzt er Kopfgelder für jeden Abenteurer aus, der bereit ist, die Eindringlinge niederzustrecken.",h="Wache Howe ist ein Stadtwächter, der nahe dem südlichen Fuß der Brücke von Seenhain im Rotkammgebirge...",kw={"kopfgeld auf den schwarzfelsklan","blackrock-orcs","wache howe","howe","seenhain","rotkammgebirge"},ang={["faction:Alliance"]="Seenhain erhält wenig direkte Hilfe aus Sturmwind, sodass Frontwächter wie Howe auf durchreisende Champions der Allianz angewiesen sind, um die Schwarzfelsorcs daran zu hindern, die Stadt zu überrennen."},sec={{t="Ein Groll auf der Brücke",b="Wache Howe ist direkt südlich der großen Steinbrücke über den Immerruhsee postiert und hält Wache über das Herz von Seenhain. Wie viele in der belagerten Stadt sieht er in den vordringenden Schwarzfelsorcs eine existenzielle Bedrohung für das Rotkammgebirge. Howe hegt ein bitteres Verlangen nach Rache an dem Clan und rekrutiert aktiv vorbeiziehende Söldner für die Jagd auf Orcs in den östlichen Hügeln, wobei er als Gegenleistung für greifbare Beweise ihrer Niederlage Bezahlung anbietet."}},faq={{q="Wer ist Wache Howe?",a="Wache Howe ist ein menschlicher Stadtwächter, der direkt südlich der Brücke in Seenhain im Rotkammgebirge stationiert ist. Er hilft beim Schutz der Siedlung und leitet fähige Kämpfer an, gegen die einfallenden Schwarzfelsorcs zurückzuschlagen.",al={"wache howe","howe seenhain","wer ist howe"}},{q="Warum will Wache Howe den Tod der Schwarzfelsorcs?",a="Howe hegt eine persönliche Fehde gegen den Schwarzfelsklan, der tief in das Rotkammgebirge vorgedrungen ist und Seenhain unter unerbittlichen Druck setzt. Er sinnt auf Rache und bietet Kopfgelder für jeden, der ihre Reihen lichtet.",al={"warum kopfgeld auf die blackrocks","howe orcs","warum hasst howe orcs"}},{q="Ist Wache Howe mit jemand anderem in der Region verwandt?",a="Er teilt einen Nachnamen mit Soloman Howe, was darauf hindeutet, dass sie verwandt sein könnten, auch wenn er seinen Fokus strikt auf seine Pflichten bei der Bewachung der Stadt und der Bekämpfung der Orcs richtet.",al={"howe verwandte","soloman howe verwandtschaft"}}},fx={["59b92c48"]={q="Auf wessen Seite steht Wache Howe?",a="Wache Howe dient dem Königreich Sturmwind und steht an der Seite der Stadtwache von Seenhain. Er ist an der Front von Rotkammgebirge stationiert und kämpft dafür, die lokale menschliche Bevölkerung gegen die unerbittlichen Einfälle zu verteidigen, die ihre Grenzen bedrohen.",al={"wache howe fraktion","ist wache howe allianz","wem dient wache howe"}},d5289960={q="Warum ist Wache Howe hier?",a="Wache Howe ist südlich der Brücke von Seenhain stationiert, um den Umfang der Stadt zu bewachen. Das Rotkammgebirge wird von Gnollen und eindringenden Schwarzfelsorcs belagert, was die Brücke zu einem wichtigen Übergang und einem wesentlichen Engpass macht, der vor plötzlichen Angriffen geschützt werden muss.",al={"warum ist wache howe in seenhain","wache howe posten","warum wache howe brücke"}}},fp="10,269,22.433.0,18.224.0,47.229.0,51.156.0"}
P.entries["npc:guard-thomas"] = {n="Wache Thomas",s="Wache Thomas ist ein pflichtbewusster Soldat der Armee von Sturmwind, der an der Brücke westlich des Holzfällerlagers des Osttals stationiert ist. Isoliert an der östlichen Grenze des Walds von Elwynn überwacht er die Verteidigung der einheimischen Siedler gegen räuberische Wildtiere und vordringende Murlocs.",h="Wache Thomas ist ein pflichtbewusster Soldat der Armee von Sturmwind, der an der Brücke westlich des...",kw={"osttal","holzfällerlager des osttals","wald von elwynn","wache thomas","verlorene wachen","murloc","armee von sturmwind","thomas"},ang={["class:Warrior"]="Für junge Krieger der Allianz verkörpert Thomas Disziplin an vorderster Front und die unglamouröse Realität der regionalen Grenzverteidigung.",["faction:Alliance"]="Wache Thomas verkörpert den überdehnten Zustand der Armee von Sturmwind, da er mit minimaler Unterstützung durch die Krone einen lebenswichtigen Außenposten an der Grenze hält."},sec={{t="An der Ostgrenze",b="Während ein Großteil der Aufmerksamkeit des Reiches nach innen auf die Hauptstadt oder nach Westen in Richtung Westfall gerichtet ist, hält Wache Thomas einen der ruhigsten und zugleich heikelsten Posten im Wald von Elwynn. Positioniert an der Steinbrücke, die den Fluss zum Holzfällerlager des Osttals überquert, fungiert Thomas als schützende Linie zwischen den einfachen Waldarbeitern und den aggressiven Kreaturen, die durch die Wälder streifen. Da das Militär von Sturmwind stark überdehnt ist, müssen sich Wachen wie Thomas stark auf durchreisende Abenteurer verlassen, um die Ordnung aufrechtzuerhalten und Nachrichten an das Zentralkommando zu übermitteln."},{t="Grenzschwierigkeiten",b="Die östlichen Ausläufer von Elwynn stehen unter ständigem Druck. Aggressive Bären und Pirscher lauern an der Baumgrenze und bedrohen Holzfäller sowie Reisende, während seltsame Murloc-Stämme Lager entlang der Wasserwege errichtet haben. Thomas verfolgt die Bewegungen dieser aquatischen Räuber und setzt Kopfgelder aus, um ihre Zahl zu dezimieren. Schlimmer noch: Spähpatrouillen entlang des Flusses verschwinden gelegentlich spurlos, sodass Thomas versuchen muss, das Schicksal seiner Wachkameraden inmitten der wachsenden regionalen Instabilität aufzuklären."}},faq={{q="Wo finde ich Wache Thomas?",a="Wache Thomas ist auf der Steinbrücke postiert, die den Fluss direkt westlich des Holzfällerlagers des Osttals entlang der östlichen Straße im Wald von Elwynn überspannt.",al={"wache thomas standort","wo ist thomas","wache thomas brücke"}},{q="Was ist die Aufgabe von Wache Thomas im Wald von Elwynn?",a="Er ist ein Soldat der Armee von Sturmwind, der mit dem Schutz der östlichen Grenze von Elwynn beauftragt ist. Zu seinen Aufgaben gehören die Sicherung der Handelsbrücke, die Verteidigung der nahegelegenen Arbeiter vor wilden Raubtieren und die Überwachung feindseliger Murloc-Übergriffe entlang der Flussufer.",al={"was macht thomas","wache thomas aufgabe","thomas osttal"}},{q="Warum bittet Wache Thomas um Hilfe bezüglich verschwundener Wachen?",a="Routinepatrouillen, die in die Flussbecken entsandt wurden, haben sich nicht zurückgemeldet. Ohne ausreichende Verstärkung, um seinen Posten unbesetzt zu lassen, rekrutiert Thomas durchreisende Abenteurer, um die Wasserwege abzusuchen und herauszufinden, was mit seinen vermissten Kameraden geschehen ist.",al={"vermisste wachen elwynn","wache thomas verschwundene späher","was geschah mit den wachen"}},{q="Warum sind Murlocs ein Problem für Wache Thomas?",a="Murloc-Stämme dringen zunehmend in die Flusssysteme des östlichen Elwynn vor. Ihre wachsende Präsenz bedroht sowohl die örtlichen Holzfällarbeiten als auch die Überlandversorgungswege, was Thomas dazu veranlasst hat, Kopfgelder auf ihre Flossen auszusetzen, um die Wasserwege freizuhalten.",al={"murlocs osttal","warum murlocs töten","wache thomas murloc kopfgeld"}},{q="Wem untersteht Wache Thomas?",a="Thomas dient in der Armee von Sturmwind und untersteht über die militärische Hierarchie dem regionalen Kommando in Goldhain und der Hauptstadt. Während sich die Lage an den Grenzen verschlechtert, stimmen sich seine Berichte auch mit der Grenzführung wie Gryan Starkmantel in Westfall ab.",al={"thomas vorgesetzter","befehlskette armee von sturmwind","für wen arbeitet thomas"}},{q="Wohin schickt Wache Thomas die Abenteurer, sobald ihre Arbeit in Elwynn erledigt ist?",a="Sobald die unmittelbaren Bedrohungen rund um das Osttal und den östlichen Fluss gebannt sind, stellt Thomas Berichte zur Verfügung, die erfahrene Reisende nach Westfall leiten, um Gryan Starkmantel und der kämpfenden Volksmiliz beizustehen.",al={"nach wache thomas","wohin nach dem osttal","bericht für westfall"}}},fx={["2ef4fdb3"]={q="Wer ist Wache Thomas?",a="Wache Thomas ist ein Offizier der Armee von Sturmwind, der an der östlichen Grenze vom Wald von Elwynn stationiert ist. Während die Streitkräfte von Sturmwind im gesamten Königreich dünn gesät sind, hält Thomas die Stellung nahe dem Holzfällerlager des Osttals und schützt Reisende und Arbeiter entlang der Brücke vor Gnollen und eindringenden Murlocs.",al={"wer ist thomas","identität von wache thomas","wer ist wache thomas"}},["26bccfb6"]={q="Auf wessen Seite steht Wache Thomas?",a="Thomas dient dem Königreich Sturmwind und der Allianz. Als loyaler Soldat der Armee von Sturmwind handelt er unter der Autorität des Throns und arbeitet direkt daran, die Grenzen des Reiches für dessen Bürger und Arbeiter zu sichern.",al={"fraktion von wache thomas","wem dient wache thomas","wache thomas allianz"}},["8313e011"]={q="Was will Wache Thomas?",a="Thomas benötigt fähige Hände, um den östlichen Rand von Elwynn zu schützen. Zwischen aggressiven Flussmurlocs und feindseligen Gnollen, die die Holzfäller des Osttals bedrohen, möchte er die umliegende Wildnis gesichert wissen, das Schicksal vermisster Patrouillen aufklären und regelmäßige Informationen an das Oberkommando in Sturmwind und Westfall senden.",al={"was will thomas","ziele von wache thomas","was braucht wache thomas"}},c7700b23={q="Warum ist Wache Thomas hier?",a="Thomas ist an der östlichen Brücke stationiert, um den Hauptübergang zum Holzfällerlager des Osttals und die dahinter liegenden Grenzgebiete zu bewachen. Da das Osttal für die Holzversorgung Sturmwinds lebenswichtig ist und lokale Bestien aus den Flüssen und Hügeln vordringen, ist eine militärische Präsenz notwendig, um den Weg offen zu halten.",al={"warum ist wache thomas an der brücke","warum ist thomas hier","standortgrund von wache thomas"}}},fp="12,261,21.542.0,17.495.1,30.142.0,45.258.0,53.251.0,43.251.0,32.275.0,75.208.0"}
P.entries["npc:gubber-blump"] = {n="Gubber Blump",s="Gubber Blump ist ein Zwergenfischer und -lehrer, der an den Ufern von Auberdine an der Dunkelküste stationiert ist. Im Sand zwischen den Docks und dem Flugmeister gelegen, ist er ein begeisterter Liebhaber des Angelhandwerks und von Meeresfrüchten, insbesondere von frischem Krabbenfleisch.",h="Gubber Blump ist ein Zwergenfischer und -lehrer, der an den Ufern von Auberdine an der Dunkelküste...",kw={"auberdine","blump","dunkelküste","angeln","graun blump","gubber","riffkriecher","glänzender schatz"},ang={["profession:Cooking"]="Gubber begeistert sich leidenschaftlich für Küstenkost, insbesondere für frisches Fleisch von Riffkriechern, was ihn zu einem Gleichgesinnten für Köche macht, die Zutaten aus den Gewässern der Dunkelküste suchen.",["race:Dwarf"]="Einen Zwerg zu sehen, der sich glücklich an einer nebligen Küste von Kalimdor anstatt in Khaz Modan niedergelassen hat, ist ein ungewöhnlicher Anblick, doch seine unverblümten Neckereien über die Verwandtschaft beweisen, dass er seine Wurzeln in Eisenschmiede nicht verloren hat."},sec={{t="Der Angler von Auberdine",b="Während die meisten Zwerge Trost unter Stein oder neben einer tosenden Schmiede finden, bevorzugt Gubber Blump die neblige Küste der Dunkelküste. Am Strand von Auberdine zwischen dem Flugmeister und dem Fähranleger stationiert, lehrt Gubber die Kunst des Angelns und verkauft grundlegende Angelausrüstung an vorbeikommende Reisende. Er hegt eine tiefe kulinarische Vorliebe für Krabbenfleisch, verlässt sich jedoch häufig auf Abenteurer, die ihm dabei helfen, seinen Fang an der gefährlichen Küste zu sichern sowie sentimentales Angelgerät seiner Familie zurückzuholen."},{t="Familienbande und Gefälligkeiten am Meer",b="Gubber ist dafür bekannt, offenherzige Geschichten über seine Familie zu erzählen, insbesondere über seine Kusine Graun Blump, von der er behauptet, dass sie sowohl einen Bart als auch einen ungewöhnlichen Geruch besitzt. Reisende, die ihm bei seinen Besorgungen an der Küste zur Hand gehen – sei es beim Einholen von Kriecherbeinen oder beim Bergen seiner Familienangel –, erhalten von Gubber oft einen aufmerksamen handgeschriebenen Dankesbrief, meist begleitet von einem glänzenden Angelköder, um ihre zukünftigen Auswürfe zu fördern."}},faq={{q="Wer ist Gubber Blump?",a="Gubber Blump ist ein zwergischer Angellehrer und Händler am Strand von Auberdine, direkt zwischen den Docks des Dorfes und dem Hippogryphenmeister gelegen.",al={"wer ist gubber blump","gubber blump nsc","wo ist gubber blump"}},{q="Was lehrt oder verkauft Gubber Blump?",a="Er bildet Neulinge im Angelberuf aus und führt grundlegende Ausrüstung für angehende Angler, darunter einfache Angeln und Glänzende Schätze.",al={"was verkauft gubber","gubber blump lehrer","dunkelküste angellehrer"}},{q="Welche Aufgaben vergibt Gubber Blump?",a="Gubber bittet Reisende, seine verlorene Familienangel wiederzubeschaffen und feines Krabbenfleisch von der Küste zu sammeln, etwa in den Quests 'Die Familie und die Angelrute' und 'Meeresfrüchte'.",al={"gubber blump quests","meeresfrüchte","die familie und die angelrute"}},{q="Wer ist Graun Blump?",a="Graun Blump ist Gubbers Zwergenkusine. Gubber bemerkt freimütig, dass sie einen beachtlichen Bart zur Schau trägt und einen ziemlich ungewöhnlichen Geruch hat.",al={"graun blump","gubber blump kusine"}}},fx={["0ab58c9b"]={q="Auf wessen Seite steht Gubber Blump?",a="Gubber Blump ist ein Zwerg der Allianz, der friedlich an der Seite der Nachtelfen von Auberdine stationiert ist. Obwohl er sich größtenteils um seine eigenen Angelegenheiten kümmert und auf sein Handwerk konzentriert, heißt er Reisende der Allianz willkommen, um mit ihnen zu handeln, zu trainieren und den Fang von der Küste zu teilen.",al={"ist gubber blump allianz","fraktion von gubber blump","wem dient gubber blump"}},["09bb4e46"]={q="Was will Gubber Blump?",a="Gubber ist leidenschaftlicher Angler und liebt kulinarische Köstlichkeiten; er hat eine besondere Vorliebe für frisches Krabbenfleisch aus den örtlichen Gewässern. Vor allem möchte er die Schätze des Meeres genießen, das verlorene Angelgerät seiner Familie wiederfinden und anderen Anglern die Feinheiten des Berufs beibringen.",al={"was ist gubber blumps ziel","was braucht gubber blump","beweggründe von gubber blump"}},["77301056"]={q="Warum ist Gubber Blump in Dunkelküste?",a="Gubber hat sein Zuhause an der Küste von Auberdine aufgeschlagen, eingebettet zwischen den Docks und dem Flugmeister. Die neblige Küste bietet reichhaltige Angelgründe und einen stetigen Fang an Riffkrabben, was sie zu einem idealen Posten für einen zwergischen Angler macht, der in Frieden fischen möchte.",al={"warum ist gubber blump hier","warum ist ein zwerg in dunkelküste","warum ist gubber in auberdine"}}},fp="12,256,23.502.0,28.409.0,20.153.0,37.142.0,38.178.0,19.127.0"}
P.entries["npc:gunther-arcanus"] = {n="Gunther Arkanus",s="Gunther Arkanus ist ein außergewöhnlich mächtiger Nekromant, der auf einer abgelegenen Insel im Blendwassersee haust. Im Dritten Krieg erschlagen und in den Untod erhoben, gelang es ihm, den geistigen Griff des Lichkönigs gänzlich aus eigener Kraft zu brechen. Lange Zeit glaubte er, der einzige Untote mit freiem Willen zu sein, und verteidigte seinen Zufluchtsort gegen alle Außenstehenden, bis die Verlassenen ihn entdeckten.",h="Gunther Arkanus ist ein außergewöhnlich mächtiger Nekromant, der auf einer abgelegenen Insel im...",kw={"arcanus","bethor","blendwassersee","dalaran","gunther","iceshard","kirin tor","lich","nekromant","thule","tirisfal"},ang={["class:Mage"]="In Dalaran ausgebildet, repräsentiert Gunther jene Magier der Kirin Tor, die sich vor der Invasion Lordaerons durch die Geißel heimlich mit verbotenen nekromantischen Zaubern beschäftigten.",["class:Warlock"]="Gunthers befehlshabende Beherrschung der dunklen Künste und der Reanimation zeigt, wie weit verbotene Studien außerhalb der wachsamen Augen der Führung von Dalaran gedeihen konnten.",["race:Undead"]="Gunthers Selbstbefreiung macht ihn zu einer Anomalie unter den Verlassenen und beweist, dass intensive arkane Ausbildung und eiserner Wille allein mitunter ausreichten, um die geistige Beherrschung des Lichkönigs zu zerschlagen."},sec={{t="Ein Schüler Dalarans",b="Vor dem Fall von Lordaeron war Gunther ein vielversprechender Lehrling der Kirin Tor in Dalaran. Gemeinsam mit seinen engen Freunden Bethor Eismacht und Thule Rabenklaue studierte er die arkanen Künste und vertiefte sich heimlich in die Nekromantie, ungeachtet der strengen Verbote der Kirin Tor bezüglich dunkler Magie. Zum Gedenken an ihre Bruderschaft band das Trio einst ihre Lehrlingszauberstäbe zu einem einzigen Erbstück zusammen."},{t="Sprengen der Fesseln",b="Als die Geißel während des Dritten Krieges über den Norden fegte, erlag Gunther der Seuche des Untods und wurde in die Knechtschaft erhoben. Anders als die meisten, die auf eine Schwächung der Macht des Lichkönigs angewiesen waren oder darauf, dass Fürstin Sylvanas ihre Ketten brach, erlaubten Gunthers rohe arkane Meisterschaft und seine schiere Willenskraft es ihm, die geistige Beherrschung des Lichkönigs vollkommen allein abzuschütteln. Überzeugt davon, dass jeder andere wandelnde Leichnam ein geistloser Knecht der Geißel geblieben war, zog er sich auf eine Insel in Tirisfal zurück, umgab sich mit schlurfenden Wächtern und brach jeden Kontakt zu den Lebenden wie auch den Toten ab."},{t="Der abtrünnige Lich",b="Auf der Suche nach mächtigen Verbündeten gegen die Geißel sandten die Verlassenen Abgesandte aus, um das Zauberbuch des geheimnisvollen Nekromanten zu beschaffen. Bei der Untersuchung des arkanen Wälzers in Unterstadt erkannte Bethor Eismacht die unverwechselbare Handschrift seines lang verschollenen Weggefährten. Durch das Verzaubern des zurückgebrachten Grimoires und die Forderung nach der Vernichtung örtlicher Geißelkommandanten erkannte Gunther schließlich, dass er mit seiner Freiheit nicht allein war. Überzeugt davon, dass Sylvanas' Fraktion eine echte Rebellion gegen die Geißel darstellt, schloss er einen Pakt mit seinem ehemaligen Mitschüler, um den Verlassenen beizustehen."}},faq={{q="Wer ist Gunther Arkanus?",a="Er ist ein ehemaliger Magier der Kirin Tor aus Dalaran, der während des Dritten Krieges umkam. In den Untod erhoben, befreite er sich aus eigener Kraft von der Beherrschung des Lichkönigs und zog sich auf eine Insel im Blendwassersee in Tirisfal zurück.",al={"wer ist gunther","gunther lore","gunther arkanus geschichte"}},{q="Warum sieht Gunther wie ein gewöhnlicher Verlassener aus und nicht wie ein skelettartiger Lich?",a="Während traditionelle Liche ihren Geist in ein Phylakterium transferieren und monströse, schwebende Skelettgestalten annehmen, erlangte Gunther seinen lichähnlichen nekromantischen Status, ohne seinen ursprünglichen wiederbelebten Leichnam aufzugeben, wodurch seine physische, sterbliche Erscheinung erhalten blieb.",al={"warum sieht gunther menschlich aus","gunther kein skelett","warum ist gunther ein lich"}},{q="Warum lebte Gunther allein auf einer Insel?",a="Nachdem er die mentale Kontrolle des Lichkönigs gebrochen hatte, glaubte Gunther, er sei der einzige existierende Untote mit freiem Willen. In der Annahme, alle anderen wandelnden Toten seien noch immer geistlose Sklaven der Geißel, isolierte er sich und befahl seinen Dienern, jeden niederzustrecken, der sich näherte.",al={"warum ist gunther allein","gunther insel isolation","warum versteckt sich gunther"}},{q="Woher kennt Gunther Bethor Eismacht?",a="Sie waren Mitschüler und enge Freunde in Dalaran, die gemeinsam unter den Kirin Tor lernten, zusammen mit einem dritten Magier namens Thule Rabenklaue. Die drei Freunde flochten sogar ihre Lehrlingszauberstäbe als Symbol ihres Bundes zusammen.",al={"bethor und gunther","woher kennt gunther bethor","bethor eismacht geschichte"}},{q="Schließt sich Gunther den Verlassenen an?",a="Ja. Sobald Abenteurer sein verzaubertes Zauberbuch zurückbringen und die lokale Geißelagentin Lillith Nefara hinrichten, um ihre Unabhängigkeit vom Lichkönig zu beweisen, schwört Gunther Bethor und der Sache der Verlassenen seine Gefolgschaft.",al={"schließt sich gunther der horde an","gunther fraktion","ist gunther ein verlassener"}},{q="Wer ist Lillith Nefara?",a="Lillith Nefara ist eine Agentin der Geißel, die in Tirisfal stationiert ist. Gunther verlangt ihren Tod als Beweis dafür, dass der Abenteurer wahrhaftig einem Feind des Lichkönigs dient und nicht der Geißel selbst.",al={"lillith nefara","nefara","gunther ziel"}}},fx={["3744b38d"]={q="Was will Gunther Arkanus?",a="Vor allem schätzt Gunther seine Unabhängigkeit vom Lichkönig. Nachdem er sich durch schiere Willenskraft befreit hatte, verbrachte er Jahre in Isolation und bewachte sich vor dem, was er für Sklaven der Geißel hielt. Er begehrt Einsamkeit vor der Geißel und sucht nach Beweisen, bevor er jemandem vertraut, der behauptet, seine Freiheit zu teilen, und möchte die Gewissheit haben, dass Ihr der Herrschaft des Lichkönigs wirklich entgegensteht.",al={"was will gunther","ziel von gunther arkanus","motivation von gunther arkanus"}},["2466094b"]={q="Warum ist Gunther Arkanus berühmt oder gefürchtet?",a="Selbst als sterblicher Magier von Dalaran meisterte Gunther die verbotene Kunst der Nekromantie. Im Untod erreichte er den seltenen Status eines Lichs, während er seine ursprüngliche sterbliche Form behielt. Am beängstigendsten ist jedoch, dass er die psychische Kontrolle des Lichkönigs ganz aus eigener Kraft zerschlug und nun untote Diener unter seinem absoluten Willen befehligt.",al={"ist gunther arkanus mächtig","warum ist gunther arkanus gefürchtet","ruf von gunther arkanus"}}},fp="15,371,20.392.0,21.596.0,17.549.1,23.229.0,73.258.0,42.272.0,38.213.0,31.216.1,22.198.1"}
P.entries["npc:gurda-ragescar"] = {n="Gurda Zornnarbe",s="Gurda Zornnarbe war eine Orcin, die an einem kleinen Außenposten der Horde südwestlich vom Splitterholzposten in Eschental stationiert war. An der Seite von Feran Strongwind fiel sie bei der Verteidigung ihres Lagers gegen örtliche Gefahren im schattigen Wald.",h="Gurda Zornnarbe war eine Orcin, die an einem kleinen Außenposten der Horde südwestlich vom Splitterholzposten...",kw={"eschental","feran strongwind","gurda","orc","ragescar","splintertree","die verlorenen seiten"},ang={["faction:Horde"]="Das gefallene Lager dient als düstere Mahnung an den hohen Preis, den die Horde zahlt, um in den heiligen Wäldern von Eschental Fuß zu fassen."},sec={{t="Ein zerschlagener Außenposten",b="Direkt südwestlich der befestigten Mauern des Splitterholzpostens unterhielt Gurda Zornnarbe ein bescheidenes Lager der Horde unter dem dichten Blätterdach von Eschental. Tief in einem Gebiet, das von nachtelfischen Verteidigern und wilden Tieren umkämpft wird, ist das Halten solch isolierter Stellungen ein gefährliches Unterfangen. Gurda wurde zusammen mit Feran Strongwind und ihrer Abteilung von Wachen letztlich an ihrem Posten überrannt und getötet, sodass vorüberziehenden Verbündeten nur die Überreste ihres letzten Gefechts blieben."},{t="Die gefallenen Späher",b="Reisende, die nahe des Pfades unterwegs sind, stoßen womöglich auf den tragischen Schauplatz von Gurdas Niederlage. Selbst im Tod bieten die Besitztümer und Aufgaben ihres Lagers Hinweise auf die Unternehmungen der Horde in den Wäldern, darunter vermisste Dokumente und durch den Hinterhalt vereitelte Befehle."}},faq={{q="Wer ist Gurda Zornnarbe?",a="Gurda Zornnarbe ist eine Orc-Späherin und Questgeberin an einem kleinen Lager direkt südwestlich vom Splitterholzposten in Eschental, die zusammen mit ihren Gefährten am Außenposten ein gewaltsames Ende fand.",al={"wer ist gurda","gurda zornnarbe lore"}},{q="Wo ist Gurda Zornnarbe zu finden?",a="Ihr Leichnam liegt in einem überrannten Lager südwestlich vom Splitterholzposten, abseits des Weges, der durch das zentrale Eschental führt.",al={"gurda standort","wo ist gurda zornnarbe"}},{q="Wer wurde an ihrer Seite getötet?",a="Sie kam an der Seite von Feran Strongwind und ihrem Gefolge aus Wachen während eines Angriffs auf ihr kleines Lager ums Leben.",al={"wer starb mit gurda","feran strongwind"}},{q="Welche Quest steht mit Gurda Zornnarbe in Verbindung?",a="Gurda ist mit der Quest Die verlorenen Seiten verknüpft, bei der es um die Wiederbeschaffung verstreuter Dokumente in der Wildnis von Eschental geht.",al={"gurda quests","die verlorenen seiten"}}},fx={["28561f13"]={q="Welcher Fraktion gehört Gurda Zornnarbe an?",a="Gurda Zornnarbe war der Horde gegenüber loyal. Stationiert in einem kleinen Außenposten südwestlich vom Splitterholzposten, repräsentierte sie zusammen mit ihren Gefährten die befestigte Präsenz der Horde tief innerhalb der umstrittenen Grenzen vom Eschental.",al={"fraktion von gurda zornnarbe","ist gurda horde oder allianz","für wen kämpft gurda"}},e9ae8f07={q="Warum war Gurda Zornnarbe südwestlich vom Splitterholzposten stationiert?",a="Gurda Zornnarbe unterhielt zusammen mit Feran Strongwind und einem Kontingent von Wachen ein vorgeschobenes Lager der Horde südwestlich vom Splitterholzposten. Ihr Posten befand sich an den umstrittenen Waldwegen und diente dazu, die Operationen der Horde zu unterstützen und verlorene Güter in den feindseligen Wäldern vom Eschental zurückzuholen.",al={"warum ist gurda zornnarbe hier","zweck von gurdas lager","warum war gurda im eschental"}}},fp="14,208,15.473.0,17.266.0,22.179.0,34.115.0,29.108.0,35.117.0"}
P.entries["npc:gwennyth-bly-leggonde"] = {n="Gwennyth Bly'Leggonde",s="Gwennyth Bly'Leggonde ist eine Nachtelfe, die in der Hafenstadt Auberdine an der Küste lebt. An der nebelverhangenen Küste der Dunkelküste stationiert, beobachtet sie die Gezeiten und schickt Reisende aus, um die seltsamen Überreste zu untersuchen, die an Land gespült werden. Ihre Sorge gilt den geheimnisvollen Meereskreaturen und riesigen Schildkröten, deren Kadaver begonnen haben, die nördlichen Strände zu übersäen.",h="Gwennyth Bly'Leggonde ist eine Nachtelfe, die in der Hafenstadt Auberdine an der Küste lebt.",kw={"auberdine","gestrandete meereskreatur","gestrandete meeresschildkröte","blyleggonde","dunkelküste","gwennyth","kaldorei","verhülltes meer","an land gespült"},ang={["class:Druid"]="Druiden, die sich der Bewahrung der natürlichen Harmonie Kalimdors verschrieben haben, sehen in Gwennyths Berichten über gestrandetes Meeresleben einen alarmierenden Hinweis auf Störungen im Küstenökosystem.",["faction:Alliance"]="Auberdine dient als primärer Küstenhafen der Allianz im nördlichen Kalimdor; seine Wasserwege und Strände vor verborgenen Bedrohungen zu schützen, ist für alle verbündeten Völker, die das Gebiet bereisen, von entscheidender Bedeutung.",["race:NightElf"]="Für die Kaldorei ist der unnatürliche Tod großer Meeresbestien vor den Ufern der Dunkelküste ein beunruhigendes Zeichen eines Ungleichgewichts in ihren angestammten Ländern, was Gwennyths Wache am Strand besonders dringlich macht."},sec={{t="Wächterin des treibenden Sandes",b="Gwennyth Bly'Leggonde hat ihr Zuhause in Auberdine, der geschäftigen Küstenzuflucht an der Dunkelküste. Während sich viele in der Stadt mit dem Wald oder der Schifffahrt über das Verhüllte Meer befassen, richtet Gwennyth ihren Blick fest auf die Küstenlinie. Die Gezeiten haben in letzter Zeit eine düstere Wendung genommen und spülen die Überreste kolossalen Meereslebens an die Brandung. Um zu verstehen, was in den Gewässern vor der Küste geschieht, verlässt sie sich auf hilfsbereite Abenteurer, die den Sand absuchen, Skelettproben bergen und Antworten zurückbringen."},{t="Die gestrandeten Riesen",b="Die Strände nördlich und südlich von Auberdine verzeichnen einen besorgniserregenden Zustrom gestrandeter Meereskreaturen und uralter Meeresschildkröten. Anstatt deren Tod unbemerkt verstreichen zu lassen, beauftragt Gwennyth Reisende damit, diese gefallenen Titanen zu untersuchen. Indem sie die Knochen studiert und herausfindet, was diese Bestien an Land trieb oder ihnen das Leben nahm, hofft sie, die verborgenen Gefahren aufzudecken, die vor den Küsten des nördlichen Kalimdor lauern."}},faq={{q="Wer ist Gwennyth Bly'Leggonde?",a="Sie ist eine Nachtelfen-Bewohnerin von Auberdine an der Dunkelküste, die die jüngsten ökologischen Störungen entlang der Küstenlinie erforscht. Sie bittet Reisende darum, den Strand zu untersuchen und seltsames Angespültes aus dem Meer zu begutachten.",al={"wer ist gwennyth","gwennyth auberdine","gwennyth lore"}},{q="Wo kann ich Gwennyth Bly'Leggonde finden?",a="Ihr könnt sie in der Küstensiedlung Auberdine finden, nahe dem Strand und den Docks an der nebelverhangenen Küste der Dunkelküste gelegen.",al={"wo ist gwennyth","gwennyth standort","gwennyth finden"}},{q="Warum interessiert sie sich für gestrandete Kreaturen?",a="Das plötzliche Sterben und Stranden gewaltiger Meeresschildkröten sowie mysteriöser Meeresungeheuer weist auf ein Ungleichgewicht oder ein ungesehenes Raubtier in den Gewässern vor der Dunkelküste hin. Gwennyth versucht, die Ursache zu ergründen, indem sie die entlang der Küste geborgenen Überreste untersucht.",al={"warum gestrandete schildkröten","warum will sie knochen","quest an land gespült"}},{q="Welche Quests bietet Gwennyth an?",a="Sie schickt Abenteurer auf die Quest 'An Land gespült' und dient als Abgabepunkt für verschiedene Entdeckungen im Zusammenhang mit den gestrandeten Meereskreaturen und gestrandeten Meeresschildkröten, die entlang der Küstenlinie der Dunkelküste gefunden werden.",al={"gwennyth quests","was gibt sie"}},{q="Gehört sie zum Zirkel des Cenarius oder zu den Schildwachen?",a="Weder noch. Sie ist eine Mondpriesterin im Dienste der Schwesternschaft von Elune in Auberdine und keine Druidin des Zirkels oder Schildwachen-Kommandantin, teilt jedoch die tiefe Besorgnis ihres Volkes über den Zustand und das Gleichgewicht der natürlichen Umwelt der Dunkelküste.",al={"gwennyth fraktion","ist gwennyth ein druide"}},{q="Was bedeutet ihr Name?",a="Obwohl er zum rhythmischen Namensstil der Kaldorei passt, ist ihr ungewöhnlicher Nachname 'Bly'Leggonde' ein Anagramm von 'Leggy Blonde' – ein verspieltes Detail der Schöpfer der Spielwelt.",al={"bly leggonde bedeutung","gwennyth name easter egg"}}},fx={["9c9d3ff5"]={q="Warum ist Gwennyth Bly'Leggonde in Dunkelküste?",a="Gwennyth hat ihr Zuhause im Küstenhafen Auberdine und hält Wache über die nebelverhangenen Strände von Dunkelküste. Beunruhigt von der unnatürlichen Fäulnis, die an die Küste gespült wird, überwacht sie das Ufer auf gestrandete Meerestiere und rekrutiert vorbeiziehende Reisende, um gestrandete Meeresbewohner und Schildkröten zu untersuchen, die unter der seltsamen Verderbnis leiden, die die Gewässer befällt.",al={"warum ist gwennyth hier","warum ist gwennyth bly'leggonde in auberdine","warum ist gwennyth in dunkelküste"}}},fp="21,348,29.489.0,19.409.0,29.212.0,39.134.0,43.248.0,32.196.0,52.234.0,24.167.0"}
P.entries["npc:hagar-lightninghoof"] = {fx={d173f224={q="Auf wessen Seite steht Hagar Blitzhuf?",a="Hagar Blitzhuf ist der Horde und seinen Tauren-Gefährten treu ergeben. Stationiert auf den hoch aufragenden Spitzen vom Freiwindposten, vertraut er seine Aufgaben nur Champions der Horde an, die beweisen, dass sie es wagen, die gefährlichen Schluchten darunter zu durchqueren.",al={"fraktion von hagar blitzhuf","ist hagar horde"}},c809f2c7={q="Warum ist Hagar Blitzhuf hier am Freiwindposten?",a="Hagar reiste nach Tausend Nadeln, nachdem er Gerüchte über ein seltsames, fremdartiges Ei gehört hatte, das in den Nestern der Windschlangen gesichtet wurde. Fasziniert von dem seltsamen Fund, schlug er sein Lager am Freiwindposten auf, um jemanden zu finden, der mutig genug ist, es an den Schlangenwachen vorbei zu bergen.",al={"warum ist hagar hier","warum kam hagar nach tausend nadeln"}},a74332ba={q="Mit wem ist Hagar Blitzhuf verbunden?",a="Hagar arbeitet mit den Tauren-Verteidigern vom Freiwindposten zusammen und berät sich eng mit Motega Feuermähne. Wenn seine Untersuchungen Angelegenheiten offenbaren, die tief in alten Tauren-Legenden und heiligen Omen verwurzelt sind, wendet er sich an Motega, um Rat zu suchen.",al={"verbindungen von hagar","mit wem arbeitet hagar zusammen"}}}}
P.entries["npc:halaan-hawk-eye"] = {n="Halaan Hawk-Eye",s="Halaan Hawk-Eye ist ein Ausguck der Skyborne, der auf der Spitze des Wachturms von Thendal auf der Insel Zephras stationiert ist. Da ihm sowohl das magische Gespür als auch die mystische Himmelssicht seiner Artgenossen fehlen, verlässt er sich stattdessen auf seine scharfe weltliche Sehkraft, um die umliegende Insel zu überwachen. Von seinem Hochsitz aus behält er die fernen Ankerpylone im Auge und warnt Besucher vor deren schwindender arkaner Stabilität.",h="Halaan Hawk-Eye ist ein Ausguck der Skyborne, der auf der Spitze des Wachturms von Thendal auf der Insel...",kw={"ankerpylon","halaan","hawk-eye","skyborne","himmelssicht","thendal","insel zephras"},ang={["race:Skyborne"]="Halaan repräsentiert jene unter den Skyborne, denen die natürliche Affinität zur Manipulation von Leylinien oder die Himmelssicht fehlt, und die ihrer Gemeinschaft stattdessen durch unerschütterliche Wachsamkeit und kriegerische Pflichterfüllung dienen."},sec={{t="Ein Wächter ohne Magie",b="Hoch über Thendal dient Halaan Hawk-Eye seinem Volk ohne die Gaben, die vielen Skyborne gemein sind. Er kann weder die arkane Macht nutzen, die durch die Leylinien unter der Insel Zephras fließt, noch kann er durch die mystische Himmelssicht zwischen die Welten blicken. Stattdessen verlässt sich Halaan vollkommen auf seine scharfen natürlichen Sinne. Von seinem Aussichtspunkt auf dem Wachturm aus sucht er den Horizont ab, um die Ankerpylone der Insel zu beobachten, und macht auf deren zunehmend unberechenbare und unbeständige arkane Energien aufmerksam."}},faq={{q="Wer ist Halaan Hawk-Eye?",a="Halaan Hawk-Eye ist ein Wachposten der Skyborne, der auf dem Wachturm über Thendal auf der Insel Zephras stationiert ist. Er beobachtet das umliegende Land und warnt Abenteurer vor der unberechenbaren Magie, von der die Ankerpylone der Insel befallen sind.",al={"halaan hawkeye","wer ist halaan","thendal wachturm nsc"}},{q="Was unterscheidet Halaan von anderen Skyborne?",a="Im Gegensatz zu vielen seiner Artgenossen besitzt Halaan weder die mystische Himmelssicht, die den Schleier zwischen den Welten durchdringt, noch die angeborene Fähigkeit, die unterirdischen Leylinien der Insel Zephras zu nutzen. Er verlässt sich stattdessen auf seine scharfe physische Sehkraft und natürliche Beobachtungsgabe.",al={"halaan fähigkeiten","kann halaan magie wirken","halaan himmelssicht"}},{q="Warum macht sich Halaan Sorgen um die Ankerpylone?",a="Halaan wacht über die fernen Ankerpylone und hat bemerkt, dass ihr magischer Ausstoß sprunghaft und unbeständig geworden ist, was eine unbekannte Gefahr für die Stabilität der Insel Zephras darstellt.",al={"was stimmt mit den pylonen nicht","anker von zephras problem"}},{q="Wo kann ich Halaan Hawk-Eye finden?",a="Er befindet sich auf der Spitze des hölzernen Wachturms in Thendal auf der Insel Zephras und blickt über den Horizont.",al={"wo ist halaan","halaan aufenthaltsort"}}},fx={d6a0f6c4={q="Auf wessen Seite steht Halaan Hawk-Eye?",a="Halaan ist einer der Himmelsgeborenen und steht auf der Insel Zephras an der Seite seiner Sippe. Da ihm die angeborene Leylinien-Zauberei und die überirdische Fernsicht seiner Artgenossen fehlen, dient er seinem Volk dennoch treu, indem er über Thendal wacht und Reisende vor der schleichenden Instabilität warnt, die ihre Heimat bedroht.",al={"fraktion von halaan","seite von halaan hawk-eye","wem dient halaan"}},e8313a77={q="Warum ist Halaan Hawk-Eye am Wachturm stationiert?",a="Halaan hält oben auf dem Turm von Thendal Wache, weil er nicht auf die örtlichen Leylinien zurückgreifen oder magische Fernsicht wie andere Himmelsgeborene nutzen kann. Stattdessen nutzt er seine scharfe natürliche Sehkraft, um die Insel Zephras zu überblicken und die fernen Ankerpylone zu überwachen, während deren magische Stabilität zu schwanken beginnt.",al={"warum ist halaan hawk-eye hier","warum ist halaan am wachturm","standortgrund von halaan"}}},fp="15,358,24.509.0,23.227.0,48.260.0,46.185.0,33.117.0"}
P.entries["npc:hana-zua"] = {n="Hana'zua",s="Hana'zua ist ein Späher der Dunkelspeertrolle, der im Tal der Prüfungen stationiert ist und den giftigen Bestien zum Opfer fiel, die auf den Schluchtenkämmen lauern. Geschwächt und verwundet durch den monströsen Skorpiden Sarkoth liegt er da und wartet auf die Hilfe junger Initianden der Horde, die ihren Mut beweisen wollen.",h="Hana'zua ist ein Späher der Dunkelspeertrolle, der im Tal der Prüfungen stationiert ist und den giftigen...",kw={"dunkelspeere","durotar","hana'zua","hanazua","sarkoth","skorpid","das tal der prüfungen"},ang={["faction:Horde"]="Hana'zuas Überleben und seine Vergeltung dienen als eine der ersten Prüfungen der Loyalität und Kampfbereitschaft für angehende Champions der Horde.",["race:Troll"]="Für Initianden der Dunkelspeere, die ihre Reise in Durotar gerade erst beginnen, unterstreicht das Auffinden eines verwundeten Volksgenossen die tödliche Natur der hiesigen Tierwelt und die Notwendigkeit, ihre neugewonnenen Verbündeten zu beschützen."},sec={{t="Ein dem Gift erlegener Späher",b="Als er die trockenen Anhöhen über dem Tal der Prüfungen durchquerte, stieß Hana'zua auf Sarkoth, einen außergewöhnlich bösartigen und giftigen Skorpiden, der die Klippen heimsucht. Von der Bestie überwältigt und gestochen, überlebte der Troll die Begegnung nur knapp. Unfähig, sich zu bewegen oder aus eigener Kraft ins Lager zurückzukehren, siecht er im Staub dahin und hofft darauf, dass vorbeikommende Rekruten die Kreatur zur Strecke bringen und Nachricht über seine Notlage zum Höhlenbau überbringen."}},faq={{q="Wer ist Hana'zua?",a="Hana'zua ist ein Dunkelspeertroll, der verletzt im Tal der Prüfungen in Durotar aufgefunden wird. Er geriet in einen Hinterhalt und wurde vergiftet, als er Bestien auf den Kämmen aufspürte.",al={"hanazua","wer ist hanazua","verletzter troll tal der prüfungen"}},{q="Was ist mit Hana'zua geschehen?",a="Er wurde von Sarkoth niedergestreckt, einem großen und tödlichen Skorpiden, der auf den Felsen über dem Übungsgelände lauert. Dessen wirksames Gift setzte ihn außer Gefecht, sodass er nicht mehr an einen sicheren Ort zurückkehren konnte.",al={"warum ist hanazua verletzt","wer hat hanazua vergiftet","hanazua verletzung"}},{q="Worum bittet er Reisende?",a="Hana'zua bittet fähige Abenteurer darum, seine Verwundung zu rächen, indem sie Sarkoth erschlagen, die Klaue der Bestie als Beweis sammeln und den Ausbildern im Höhlenbau von seinem Zustand berichten.",al={"hanazua quest","was will hanazua"}}},fx={eb2d80d7={q="Auf wessen Seite steht Hana'zua?",a="Hana'zua ist der Horde und seinen Dunkelspeertrollen treu ergeben. Wie andere junge Orcs und Trolle, die durch das Tal der Prüfungen kommen, wagte er sich in die Proving Grounds, um seine Stärke und seine Bereitschaft zu demonstrieren, Thralls neuer Nation zu dienen.",al={"fraktion von hanazua","wem dient hanazua","ist hanazua horde"}}},fp="8,277,23.422.0,16.145.0,26.178.0,33.182.0"}
P.entries["npc:hands-springsprocket"] = {n="Hands Federspross",s="Hands Federspross ist ein geschäftiger Gnom, der am Eingang der Eisklamm in Dun Morogh stationiert ist. Er koordiniert Lieferungen zwischen den abgelegenen Übungsgeländen des Coldridgetals und dem Ort Kharanos, auch wenn die jüngsten Überfälle der Troggs seine Bemühungen schwer beeinträchtigt haben.",h="Hands Federspross ist ein geschäftiger Gnom, der am Eingang der Eisklamm in Dun Morogh stationiert ist.",kw={"coldridgepass","das coldridgetal","dun morogh","hands federspross","kharanos","springsprocket","vorräte für tannok"},ang={["faction:Alliance"]="Hands sorgt dafür, dass die lebenswichtigen internen Nachschublinien zwischen den zwergischen Rekruten im Coldridgetal und den Siedlungen tiefer in Dun Morogh aufrechterhalten werden.",["race:Gnome"]="Für gnomische Flüchtlinge, die aus Gnomeregan vertrieben wurden, verkörpert Hands die stille Entschlossenheit der Gnome, sich an der Seite ihrer zwergischen Verbündeten in den lokalen Handel und die Logistik von Dun Morogh einzubringen."},sec={{t="Ein Engpass im Pass",b="Am Eingang der Eisklamm gelegen, sieht Hands Federspross seine regelmäßigen Nachschublieferungen völlig zum Erliegen gebracht. Normalerweise liefert er Vorräte an die Brauerei Donnerbräu und das Gasthaus in Kharanos, doch feindselige Felsbackentroggs haben den unterirdischen Tunnel überrannt, der aus dem Tal hinausführt. Da Handel und Fußverkehr durch die Bestien lahmgelegt wurden, ist Hands darauf angewiesen, dass fähige Reisende wichtige Kisten durch den gefährlichen Gebirgskorridor tragen."}},faq={{q="Wer ist Hands Federspross?",a="Er ist ein der Allianz angehörender Gnom, der im Coldridgetal direkt vor dem Eingang zur Eisklamm stationiert und dafür zuständig ist, Vorräte in die tiefer gelegenen Gebiete von Dun Morogh zu befördern.",al={"wer ist hands federspross","hands federspross lore","wer ist dieser gnom"}},{q="Warum braucht er Hilfe beim Transport von Vorräten?",a="Der Pass, der das Coldridgetal mit dem Rest von Dun Morogh verbindet, wird von bösartigen Felsbackentroggs heimgesucht, was Routinetransporte ohne bewaffnete Eskorte oder fähige Abenteurer zu gefährlich macht.",al={"warum braucht hands hilfe","coldridgepass vorräte","warum stecken die vorräte fest"}},{q="Wohin sollen seine Vorräte geliefert werden?",a="Er organisiert regelmäßige Lieferungen nach Kharanos, darunter Waren für Tannok Frosthammer und die örtlichen Gastwirte, die auf regelmäßigen Nachschub von jenseits der schneebedeckten Gipfel angewiesen sind.",al={"wohin gehen die vorräte","hands versorgungsroute","wer bekommt die kiste"}}},fx={d7333ab8={q="Auf wessen Seite steht Hands Federspross?",a="Hands ist ein loyales Mitglied der Allianz und ein Freund des Zwergenvolkes von Dun Morogh. Wie viele Gnome, die durch die Tragödie in Gnomeregan vertrieben wurden, arbeitet er eng mit seinen Verbündeten aus Eisenschmiede zusammen, kümmert sich um Logistik und Lieferungen, um lokale Gemeinschaften wie Kharanos zu unterstützen.",al={"fraktion von hands federspross","ist hands federspross allianz"}},["8576a218"]={q="Was will Hands Federspross?",a="Hands möchte, dass seine Lieferungen sicher durch die Eisklamm zu Tannok Frosthammer in der Brauerei Donnerbräu in Kharanos gebracht werden. Der jüngste Ansturm feindseliger Felskiefertrogge im gesamten Tunnel hat seine Lieferungen völlig zum Erliegen gebracht, weshalb er verzweifelt einen Abenteurer sucht, der bereit ist, die Kiste durch die Gefahr zu tragen.",al={"was will hands","ziel von hands federspross"}},d21580a2={q="Mit wem ist Hands Federspross verbunden?",a="Hands treibt regelmäßig Geschäfte mit Tannok Frosthammer, dem Gastwirt der Brauerei Donnerbräu in Kharanos. Wann immer im Tiefland Vorräte benötigt werden, koordiniert Hands die Lieferungen durch die Passstraße und verlässt sich auf Reisende, um die Lücke zu schließen, wenn die Straße gefährlich wird.",al={"mit wem arbeitet hands zusammen","verbindungen von hands federspross"}}},fp="20,279,24.453.0,28.176.0,38.192.0,32.175.0"}
P.entries["npc:hansel-heavyhands"] = {n="Hansel Bleihand",s="Hansel Bleihand ist ein ungewöhnlich massiger Dunkeleisenzwerg, der bei der Thoriumbruderschaft auf der Thoriumspitze in der Sengenden Schlucht stationiert ist. Von den Aufsehern des Außenpostens mit gefährlicher Feldarbeit betraut, delegiert er gefährliche Aufträge mit einer bunten Reihe kleinlicher körperlicher Beschwerden stets an vorbeikommende Abenteurer. Seine gewaltige Statur sticht unter seinen Artgenossen hervor, auch wenn seine Begeisterung für die Feldarbeit nicht seiner Größe entspricht.",h="Hansel Bleihand ist ein ungewöhnlich massiger Dunkeleisenzwerg, der bei der Thoriumbruderschaft auf der...",kw={"der kessel","dunkeleisenzwerg","hansel bleihand","incendosaurier","lavaspinne","sengende schlucht","thoriumbruderschaft","thoriumspitze"},ang={["faction:Alliance"]="Obwohl die Allianz gewöhnlich mit den Loyalisten der Dunkeleisenzwerge aneinandergerät, heißt die Thoriumbruderschaft jeden mit starken Armen willkommen, was Hansel zu einer praktischen Quelle für lokale Kopfgelder macht.",["faction:Horde"]="Reisende der Horde werden durch Hansels bloße Masse an einen Orc oder Tauren erinnert, doch sein Widerwille gegenüber ehrenhaftem Kampf dürfte sicherlich für Verwunderung sorgen.",["race:Dwarf"]="Bronzebeard- und Wildhammerzwerge mögen über Hansels kolossalen Körperbau staunen – oder spotten – und sich fragen, wie ein Dunkeleisenzwerg zu solch gewaltigen Ausmaßen heranwachsen konnte, während er seine Tage damit verbringt, echter Arbeit aus dem Weg zu gehen."},sec={{t="Ein Riese unter Zwergen",b="Selbst für die breitschultrigen Maßstäbe des Dunkeleisen-Clans ist Hansel Bleihand eine Ausnahmeerscheinung. Er überragt seine Brüder mit einem massiven Körperbau, der in Breite und Höhe fast an einen Orc heranreicht, und seine schiere physische Präsenz lässt auf einen Krieger schließen, der für das Gemetzel an vorderster Front geschaffen ist. Doch trotz seines imposanten Körpers und seines ehrfurchtgebietenden Namens scheint Hansel an unnötiger körperlicher Anstrengung gänzlich uninteressiert zu sein und zieht die relative Sicherheit des Lagers der Thoriumbruderschaft hoch über der Vulkanasche vor."},{t="Meister der Ausreden",b="Taskmaster Scrange und Master Smith Burninate weisen Hansel häufig die unliebsame Pflicht zu, die feurigen Bestien zu dezimieren, die in den Schlackegruben darunter lauern. Wird er angewiesen, die räuberischen Incendosaurier zu beseitigen, die durch den Kessel kriechen, weigert sich Hansel unter Verweis auf schmerzende Füße. Wenn ihm befohlen wird, die Greater Lava Spiders auszurotten, die das sengende Ödland heimsuchen, behauptet er, der verfluchte Vulkankamm leide unter einem 'eisigen Klima', das ihm eine elende Erkältung eingebracht habe. Folglich findet jeder Söldner, der bereit ist, den Magmaströmen zu trotzen, in Hansel jemanden mit einem offenen Auftrag."}},faq={{q="Wer ist Hansel Bleihand?",a="Hansel Bleihand ist ein Dunkeleisenzwerg, der der Thoriumbruderschaft angehört. Er ist auf der Thoriumspitze in der Sengenden Schlucht stationiert und für seine verblüffend enorme Körpergröße sowie sein unheimliches Geschick bekannt, gefährlicher Feldarbeit aus dem Weg zu gehen.",al={"wer ist hansel","hansel bleihand lore","hansel zwerg"}},{q="Warum ist Hansel so viel größer als andere Zwerge?",a="Für seine Masse gibt es keine eindeutige Erklärung. Hansel ist schlicht ein abnormal gigantischer Dunkeleisenzwerg mit breiten Schultern, kräftigen Gliedmaßen und einer Gesamtstatur, die fast an die eines Orcs heranreicht.",al={"warum ist hansel so groß","riesiger zwerg sengende schlucht","orcgroßer zwerg"}},{q="Welche Aufgaben überträgt Hansel Abenteurern?",a="Hansel heuert vorbeikommende Reisende an, um die Aufgaben seiner Vorgesetzten zu erledigen. Konkret bezahlt er Söldner dafür, Greater Lava Spiders in der gesamten Sengenden Schlucht zu vernichten und Incendosaurier tief im Kessel zu jagen.",al={"hansel bleihand quests","welche quests gibt hansel"}},{q="Warum erledigt Hansel seine Pflichten nicht selbst?",a="Hansel erfindet Ausreden, wann immer Gefahr droht. Er schiebt schmerzende Füße vor, um nicht in den Kessel hinabzusteigen und gegen Incendosaurier zu kämpfen, und klagt darüber, dass die glühend heiße Sengende Schlucht kalt genug sei, um ihm eine Erkältung zu verpassen, wenn er Lavaspinnen jagen soll.",al={"warum kämpft hansel nicht","hansel ausreden"}},{q="Ist Hansel dem Dunkeleisenkaiser treu ergeben?",a="Hansel gehört der Thoriumbruderschaft an, einer abtrünnigen Fraktion von Dunkeleisenzwergen, die sich von Imperator Dagran Thaurissan und Ragnaros losgesagt hat. Er verhält sich gegenüber Reisenden von Allianz und Horde, die die Thoriumspitze besuchen, neutral.",al={"ist hansel schattenschmiede treu","ist hansel ein feind"}},{q="Wo ist Hansel Bleihand zu finden?",a="Er befindet sich auf der Thoriumspitze, dem felsigen Außenposten auf dem nördlichen Kamm mit Blick auf die Sengende Schlucht.",al={"hansel standort","wo ist hansel"}}},fp="17,420,21.485.0,17.557.0,25.235.0,48.192.0,43.232.0,37.254.0,41.227.0,37.110.0"}
P.entries["npc:harb-clawhoof"] = {n="Harb Klauenhuf",s="Harb Klauenhuf ist ein Tauren-Reittierzüchter, der direkt außerhalb des Dorfes der Bluthufe in Mulgore stationiert ist. Er kümmert sich um die robusten Kodos des Stammes und bietet sie würdigen Tauren-Reitern und vertrauenswürdigen Champions von Donnerfels an.",h="Harb Klauenhuf ist ein Tauren-Reittierzüchter, der direkt außerhalb des Dorfes der Bluthufe in Mulgore...",kw={"bloodhoof","harb klauenhuf","kodotrainer","kodohändler","reittierhändler","kodo in mulgore","reittiere in donnerfels"},ang={["faction:Horde"]="Für Orcs, Trolle und Verlassene ist der Erhalt eines Kodos von Harb das ultimative Zeichen von Ehre und Freundschaft, das von den Ältesten von Donnerfels anerkannt wird.",["race:Tauren"]="Harb Klauenhuf stellt das klassische Reittier Eurer Herkunft bereit und bietet sowohl praktische Transportmöglichkeiten durch Mulgore als auch ein Symbol Eurer nomadischen Traditionen."},sec={{t="Züchter der Großen Kodos",b="In der Nähe der Gehege des Dorfes der Bluthufe verbringt Harb Klauenhuf seine Tage damit, die riesigen Kodobestien zu pflegen, die das Rückgrat der taurischen Fortbewegung und Arbeit bilden. Diese robusten Tiere sind darauf ausgelegt, enorme Lasten über weite Strecken zu tragen, und sind für das Leben in der Steppe unerlässlich. Harb stellt sicher, dass jedes Tier gut versorgt und diszipliniert ist und nur an Reiter abgegeben wird, die den Respekt des Volkes der Tauren genießen."},{t="Reittiere der Steppe",b="Während Tauren das Vertrauen, das zum Reiten von Harbs Kodos erforderlich ist, natürlicherweise erlangen, müssen sich Außenstehende einer strengeren Prüfung unterziehen. Aufgrund ihrer enormen Größe und ihres Temperaments lassen sich Kodos nicht so leicht von jemandem lenken, der nicht mit ihrem Wesen vertraut ist. Nicht-Tauren-Verbündete, die auf einem von Harbs geschätzten Reittieren davonreiten möchten, müssen zuerst ihre Loyalität beweisen und einen ehrfürchtigen Ruf bei Donnerfels erlangen."}},faq={{q="Wo finde ich Harb Klauenhuf?",a="Harb Klauenhuf ist neben dem Kodogehege am Rande des Dorfes der Bluthufe im zentralen Mulgore stationiert, südlich von Donnerfels.",al={"standort von harb klauenhuf","wo ist harb klauenhuf","standort kodohändler"}},{q="Was verkauft Harb Klauenhuf?",a="Harb verkauft verschiedene Arten von Kodo-Reittieren, darunter normale braune und graue Kodos sowie schwer gepanzerte Große Kodos für erfahrene Reiter.",al={"was verkauft harb","harb reittiere","waren des kodohändlers"}},{q="Können Nicht-Tauren Kodos bei Harb kaufen?",a="Ja, aber nur, wenn sie einen ehrfürchtigen Ruf bei Donnerfels erlangt haben. Tauren können sie direkt erwerben, aber andere Völker der Horde müssen sich erst vor dem Stamm beweisen, bevor Harb ihnen einen Kodo anvertraut.",al={"können orcs kodos kaufen","können trolle auf kodos reiten","voraussetzung ruf für kodo"}},{q="Warum sind Kodos so wichtig für die Tauren?",a="Kodos sind kraftvolle, widerstandsfähige Kreaturen, die perfekt für die nomadische Lebensweise und die offenen Steppen im zentralen Kalimdor geeignet sind. Sie dienen als zuverlässige Lasttiere, Kriegsreittiere und für den Warentransport in der rauen Landschaft.",al={"kodo-lore der tauren","warum kodos"}}},fx={["2e2e2604"]={q="Wer ist Harb Klauenhuf?",a="Harb Klauenhuf ist ein Tauren-Kodo-Züchter und Reittierhändler, der im Dorf der Bluthufe stationiert ist. Da er bei seinem Volk dafür respektiert wird, die mächtigen Bestien von Mulgore aufzuziehen und zu pflegen, stellt er sicher, dass fähige Recken standhafte Reittiere haben, die für die Strapazen von Reisen und Schlachten in ganz Kalimdor geeignet sind.",al={"wer ist harb","hintergrund von harb klauenhuf","wer ist harb klauenhuf"}},ceacb5fa={q="Auf wessen Seite steht Harb Klauenhuf?",a="Harb ist Donnerfels und der Horde gegenüber loyal ergeben. Während er seinen Tauren-Gefährten gerne Reittiere zur Verfügung stellt, müssen Außenseiter anderer Völker der Horde ihre Hingabe beweisen und sich hohes Ansehen in Donnerfels verdienen, bevor er ihnen einen seiner geschätzten Kodos anvertraut.",al={"fraktion von harb klauenhuf","ist harb klauenhuf bei der horde","loyalität von harb klauenhuf"}},["0020906d"]={q="Was will Harb Klauenhuf?",a="Harb möchte starke, zuverlässige Kodos züchten und sie nur Reitern anvertrauen, die sie wirklich respektieren. Für die Tauren ist der Kodo nicht nur ein Lasttier, sondern das Rückgrat ihrer Zivilisation, und Harb arbeitet daran, diese heilige Partnerschaft zu bewahren.",al={"was will harb","ziel von harb klauenhuf","zweck von harb klauenhuf"}},efcee9d4={q="Warum ist Harb Klauenhuf im Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist ein zentraler Treffpunkt für junge Tauren und Reisende, die von Camp Narache aus in die weiteren Ebenen von Mulgore ziehen. Harb unterhält hier seine Ställe, wo es ausreichend offene Weideflächen gibt, um starke Kodoherden für die Verteidigung und den Wohlstand der Stämme aufzuziehen.",al={"warum ist harb in bloodhoof","warum ist harb hier","harb im dorf bloodhoof"}}},fp="13,208,25.403.0,20.360.0,31.139.0,29.141.0,35.205.0,41.221.0"}
P.entries["npc:harken-windtotem"] = {n="Harken Windtotem",s="Harken Windtotem ist ein Jäger der Tauren, der im Dorf der Bluthufe in Mulgore lebt. Den Traditionen seines Volkes verschrieben, beauftragt er junge Jäger und Reisende damit, ihre Fähigkeiten im Spurenlesen und Nahrungssammeln in den goldenen Ebenen unter Beweis zu stellen.",h="Harken Windtotem ist ein Jäger der Tauren, der im Dorf der Bluthufe in Mulgore lebt.",kw={"bloodhoof","harken windtotem","mulgore","sturzfliegerjagd","tauren","windtotem"},ang={["class:Hunter"]="Für Wildnisfährtenleser, die durch das Dorf der Bluthufe ziehen, bietet Harkens Aufgabe, fliegende Sturzflieger zu erlegen, eine grundlegende frühe Prüfung der Treffsicherheit und des Sammelns von Beute.",["race:Tauren"]="Harken Windtotem verkörpert die uralte Jagdphilosophie der Tauren: Disziplin und Selbstständigkeit in den Ebenen zu beweisen und zugleich die Bestien der Erdenmutter zu ehren."},sec={{t="Jäger des Dorfes der Bluthufe",b="Nahe dem Herzen des Dorfes der Bluthufe gelegen, dient Harken Windtotem als Ausbilder und Führer für jene, die die Jagdtraditionen der Tauren erlernen. Das Leben in den Ebenen von Mulgore verlangt Respekt vor der Natur sowie das praktische Geschick, den eigenen Stamm zu ernähren. Harken prüft junge Abenteurer, indem er sie ausschickt, die einheimischen Sturzflieger zu jagen, die über den Mesas kreisen, und deren Federn zu sammeln, um die Geduld, Treffsicherheit und Fähigkeit des Jägers zur restlosen Verwertung zu beurteilen."}},faq={{q="Wer ist Harken Windtotem?",a="Harken ist ein Jäger der Tauren, der im Dorf der Bluthufe im Zentrum von Mulgore lebt. Er leitet Reisende und angehende Abenteurer beim Erlernen der grundlegenden Traditionen des Spurenlesens und der Jagd der Tauren an.",al={"harken windtotem lore","wer ist harken"}},{q="Wo ist Harken Windtotem zu finden?",a="Harken hält sich im Dorf der Bluthufe auf, einer Siedlung südlich von Donnerfels im Zentrum von Mulgore.",al={"harken aufenthaltsort","wo ist harken windtotem"}},{q="Welche Aufgaben überträgt Harken den Abenteurern?",a="Er bietet die Aufgabe Sturzfliegerjagd an, bei der er die Jäger bittet, in das Grasland von Mulgore aufzubrechen, um wilde Sturzflieger zu erlegen und deren kräftige Schwungfedern zu beschaffen.",al={"harken windtotem quests","quest sturzfliegerjagd"}},{q="Ist Harken mit Bovan Windtotem verwandt?",a="Sie teilen den Klannamen Windtotem, was auf eine Verwandtschaft innerhalb des Stammes oder der Familie hindeutet, auch wenn Harken sich weiterhin auf die lokalen Jagden des Dorfes in Mulgore konzentriert.",al={"ist harken mit bovan verwandt","verwandtschaft mit bovan windtotem"}}},fx={b6c1a716={q="Auf wessen Seite steht Harken Windtotem?",a="Harken Windtotem steht loyal zu den Tauren-Stämmen und der Horde. Er ist im Dorf der Bluthufe ansässig und konzentriert sich ganz darauf, die lokale Siedlung zu unterstützen und junge Jäger anzuleiten, während diese daran arbeiten, ihr Volk in Mulgore zu ernähren.",al={"fraktion von harken windtotem","wem dient harken","ist harken bei der horde"}},fffafcb2={q="Was will Harken Windtotem?",a="Harken sucht nach fähigen Jägern, die die lokale Population der Swoops ausdünnen und ihre Federn sammeln. Die Ebenen von Mulgore erfordern Eigenständigkeit, und indem er Jungspunde auf die Probe stellt, hilft er dabei, nützliche Materialien zu beschaffen und gleichzeitig die Fähigkeiten junger Reisender zu schulen.",al={"was will harken","ziel von harken windtotem","warum gibt harken quests"}},["4b75134c"]={q="Warum ist Harken Windtotem im Dorf der Bluthufe?",a="Als Mitglied des Windtotem-Stammes, das im Dorf der Bluthufe lebt, beaufsichtigt Harken die Jagdbemühungen in den zentralen Ebenen. Er bleibt im Dorf, um vorbeiziehende Jäger anzuleiten und sicherzustellen, dass die Tierwelt im Gleichgewicht bleibt und die Siedlung über die nötigen Ressourcen verfügt.",al={"warum ist harken hier","zweck von harken windtotem","warum ist harken in bloodhoof"}}},fp="16,233,21.468.0,24.194.0,36.106.0,43.155.0,37.150.0"}
P.entries["npc:harlan-bagley"] = {n="Harlan Bagley",s="Harlan Bagley ist ein menschlicher Rüstungsschmied und Händler, der aus der Lionheart Armory im belebten Handelsdistrikt von Sturmwind heraus tätig ist. Er führt seinen Laden an der Nordseite des Distriktzentrums und versorgt Bürger sowie durchreisende Abenteurer mit Waffen und Ausrüstung.",h="Harlan Bagley ist ein menschlicher Rüstungsschmied und Händler, der aus der Lionheart Armory im belebten...",kw={"rüstungsschmied","harlan bagley","lionheart armory","händler","sturmwind","der handelsdistrikt"},ang={["faction:Alliance"]="Händler wie Harlan Bagley versorgen die wichtigste Hauptstadt der Allianz mit Ausrüstung und Waren, während die regulären Versorgungslinien in den umliegenden Gebieten bedroht sind."},sec={{t="Die Lionheart Armory",b="An der Nordseite des Handelsdistrikts gelegen, dient die Lionheart Armory als beständige geschäftliche Anlaufstelle im Herzen von Sturmwind. Hinter seinem Tresen verwaltet Harlan Bagley das Inventar und handelt mit Defensivausrüstung, wobei er auf ankommenden Handel und regionale Kuriere angewiesen ist, um seine Regale gefüllt zu halten, während die Hauptstadt mit fernen Grenzkonflikten und Versorgungsengpässen zu kämpfen hat."}},faq={{q="Wer ist Harlan Bagley?",a="Harlan Bagley ist ein menschlicher Ladenbesitzer und Händler, der die Lionheart Armory leitet, ein Ausrüstungsgeschäft im Handelsdistrikt von Sturmwind.",al={"wer ist harlan","harlan bagley lore","lionheart armory händler"}},{q="Wo kann ich Harlan Bagley finden?",a="Er befindet sich in der Lionheart Armory an der Nordseite des zentralen Platzes im Handelsdistrikt von Sturmwind.",al={"harlan bagley aufenthaltsort","wo ist harlan","lionheart armory standort"}},{q="Welche Rolle spielt er im Handel von Sturmwind?",a="Als lokaler Händler in der Hauptstadt des Königreichs versorgt Bagley andere mit Rüstungen sowie Ausrüstung und heuert gelegentlich Abenteurer an, um Lieferaufträge zu erledigen und Nachschublieferungen zu sichern, die für das Offenhalten seiner Rüstkammer unerlässlich sind.",al={"was verkauft harlan","harlan bagley geschäft"}}},fx={["13bd1b18"]={q="Auf wessen Seite steht Harlan Bagley?",a="Harlan Bagley ist ein gewöhnlicher Bürger und Handelskaufmann der Allianz, der dem Königreich Sturmwind treu ergeben ist. Er betreibt seine Geschäfte offen im Handelsdistrikt und bedient die Abenteurer, Wachen und Verteidiger, die durch die Hauptstadt ziehen.",al={"fraktion von harlan bagley","ist harlan bagley bei der allianz"}},d342d373={q="Was will Harlan Bagley?",a="Der Betrieb der Rüstkammer Löwenherz erfordert einen zuverlässigen Fluss an Rohmaterialien und handwerklichem Geschick. Harlan konzentriert sich darauf, seine Rüstkammer voll bestückt und bereit für Kunden zu halten, wobei er häufig Hilfe von Reisenden sucht, um Waren zu sichern und seine Regale aufzufüllen.",al={"was will harlan","beweggrund von harlan bagley","warum braucht harlan nachschub"}},["0eb71712"]={q="Warum ist Harlan Bagley hier?",a="Harlan betreibt die Rüstkammer Löwenherz, die sich auf der Nordseite des belebten Handelsdistrikts von Sturmwind befindet. Er bleibt hier, um den starken Zustrom an Käufern, Schmieden und Soldaten zu versorgen, die sich für Reisen durch Azeroth ausrüsten.",al={"warum ist harlan bagley in sturmwind","warum ist harlan im handelsdistrikt"}}},fp="13,269,20.388.0,21.147.0,31.120.0,47.199.0"}
P.entries["npc:harlo-barnaby"] = {n="Harlo Barnabas",s="Harlo Barnabas ist ein verwundeter Zwergenflüchtling, der sich im Hafen von Menethil aufhält. Nachdem er dem Gemetzel bei der Einnahme von Dun Modr durch den Dunkeleisenzwerge-Clan nur knapp entkommen war, warnt er nun Reisende vor der Tragödie, die sich in den nördlichen Sümpfen abgespielt hat.",h="Harlo Barnabas ist ein verwundeter Zwergenflüchtling, der sich im Hafen von Menethil aufhält.",kw={"dunkeleisenzwerge","dun modr","harlo barnabas","der hafen von menethil","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Der Fall von Dun Modr bedroht die wichtige Landbrücke zwischen den Marschen und Arathi, wodurch Harlos Warnungen für die Streitkräfte der Allianz von entscheidender Bedeutung sind.",["race:Dwarf"]="Harlo steht als lebendige Erinnerung an den anhaltenden und blutigen Clankrieg gegen die tückischen Dunkeleisenzwerge, die versuchen, Khaz Modan vom Norden abzuschneiden."},sec={{t="Flucht aus Dun Modr",b="Harlo Barnabas lebte in Dun Modr, bis die nördliche Festung einem plötzlichen, grausamen Angriff der Dunkeleisenzwerge zum Opfer fiel. Im Chaos des Hinterhalts floh Harlo nach Süden in Sicherheit, wurde jedoch von einer verirrten Axt mitten im Rücken getroffen. Durch den Schlag bewusstlos geschlagen, überlebte er die Reise durch das Sumpfland wie durch ein Wunder und erwachte bandagiert im Hafen von Menethil. Obwohl er am Leben ist, hindern ihn seine Wunden und die Erinnerungen an das Massaker an einer Rückkehr, weshalb er Abenteurer der Allianz dazu drängt, die rauchenden Ruinen seiner einstigen Heimat zu untersuchen."}},faq={{q="Wer ist Harlo Barnabas?",a="Harlo Barnabas ist ein Zwerg aus Eisenschmiede, der im Hafen von Menethil lebt und den brutalen Angriff der Dunkeleisenzwerge auf den Außenposten Dun Modr überlebt hat.",al={"harlo barnabas","wer ist harlo","hafen von menethil zwerg"}},{q="Wie gelangte Harlo Barnabas in den Hafen von Menethil?",a="Auf der Flucht vor der Invasion von Dun Modr wurde er von einer geworfenen Axt im Rücken getroffen. Während seines Rückzugs verlor er das Bewusstsein und erwachte in Sicherheit im Hafen von Menethil in der Obhut örtlicher Heiler.",al={"wie kam harlo hierher","harlo barnabas rückenverletzung"}},{q="Was geschah mit Dun Modr?",a="Dun Modr wurde von feindseligen Dunkeleisenzwergen überrannt und verwüstet, die vom Thandol-Übergang nach Süden vordrangen, die örtlichen Zwergenverteidiger auslöschten und Überlebende in das Sumpfland trieben.",al={"fall von dun modr","was geschah in dun modr"}}},fx={["2ef93137"]={q="Auf wessen Seite steht Harlo Barnabas?",a="Harlo Barnabas ist loyal gegenüber Eisenschmiede und der Allianz. Als Überlebender des katastrophalen Angriffs auf den nördlichen Außenposten von Dun Modr steht er an der Seite seiner Zwergenbrüder der Bronzebart-Klans und sucht nach mutigen Abenteurern der Allianz, die ihm helfen, mit den Dunkeleisenzwergen fertig zu werden, die den nördlichen Pass überrannt haben.",al={"fraktion von harlo barnabas","wem dient harlo barnabas","ist harlo barnabas bei der allianz"}},["4a6adfe0"]={q="Was will Harlo Barnabas?",a="Da er immer noch seine Wunden pflegt, möchte Harlo, dass Ihr Nachrichten und Unterstützung bezüglich des Falls von Dun Modr überbringt. Er entkam knapp mit dem Leben, als die Dunkeleisenzwerge die nördliche Festung durchbrachen, und er sucht nach fähigen Kämpfern, um den Verrätern Vergeltung zu üben und das Verlorene zurückzuerobern.",al={"beweggrund von harlo barnabas","was sollst du für harlo tun","ziel von harlo barnabas quest"}}},fp="13,226,20.526.0,21.131.0,48.192.0,26.181.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="Hegnar Schlingerschuss",s="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der an der verschneiten Straße stationiert ist, die von der Eisklamm in Richtung Kharanos führt. Er betreibt einen gut besuchten Schießstand und rüstet einheimische Jäger sowie Bergsteiger mit Schusswaffen und Munition aus.",h="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der an der verschneiten Straße stationiert ist, die...",kw={"munition","coldridgepass","dun morogh","büchsenmacher","hegnar schlingerschuss","kharanos","schießstand"},ang={["class:Hunter"]="Für Schützen, die aus dem Coldridgetal in die weiteren verschneiten Gipfel von Dun Morogh aufbrechen, stellt Hegnar lebenswichtige Schrotkugeln, Munitionsbeutel und Ersatzschusswaffen bereit.",["race:Dwarf"]="Zwerge sind stolz auf ihre Handwerkskunst und Treffsicherheit, was Hegnars Schießplatz am Wegesrand zu einem natürlichen Sammelpunkt für Reisende macht, die ihren Abzugsfinger erproben wollen."},sec={{t="Ein Büchsenmacher an der Straße",b="In einem kleinen Lager zwischen der Eisklamm und Kharanos versorgt Hegnar Schlingerschuss zwergische Scharfschützen, Reisende und die örtliche Miliz. Sein Lager verfügt über einen beliebten Schießstand, an dem die Bergvölker ihre Treffsicherheit gegen die wilden Bestien schulen, die Dun Morogh durchstreifen. Die Versorgung so vieler eifriger Schützen führt dazu, dass Hegnar seine Munitionsvorräte in rasantem Tempo verbraucht, wodurch er ständig auf frische Munitionslieferungen seines Lieferanten, des Zwergeningenieurs Loslor Rudge, angewiesen ist."}},faq={{q="Wer ist Hegnar Schlingerschuss?",a="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der einen Schießstand im Freien und ein Lager am Hauptweg zwischen der Eisklamm und Kharanos betreibt.",al={"wer ist hegnar","hegnar schlingerschuss nsc","büchsenmacher in dun morogh"}},{q="Woher bezieht Hegnar seine Munition?",a="Hegnar verlässt sich auf Loslor Rudge, einen zwergischen Ingenieurslieferanten an einem anderen Ort in Dun Morogh, der die Munition herstellt und liefert, die für den Betrieb seines Schießstands benötigt wird.",al={"hegnars lieferant","wer beliefert rumbleshot","munition für rumbleshot quest"}},{q="Was tut Hegnar für die Zwerge vor Ort?",a="Er rüstet örtliche Jäger und Milizangehörige mit Schusswaffen und Schrot aus und bietet gleichzeitig Scharfschützen, die durch Dun Morogh reisen, einen Übungsplatz.",al={"warum ist hegnar hier","hegnars schießstand","rumbleshot rolle"}}},fx={f158c8ab={q="Auf wessen Seite steht Hegnar Schlingerschuss?",a="Hegnar ist fest loyal gegenüber Eisenschmiede und der Allianz. Er ist entlang der Bergstraße stationiert und rüstet die örtliche Miliz, Verteidiger und Jäger von Dun Morogh mit zuverlässigen Schusswaffen aus, um die verschneiten Pässe des Königreichs vor eindringenden Bedrohungen zu schützen.",al={"fraktion von hegnar schlingerschuss","ist hegnar bei der allianz","wem dient hegnar"}},["932ff4bf"]={q="Was will Hegnar Schlingerschuss?",a="Hegnar benötigt einen stetigen Nachschub an Munition, um seine Werkstatt und seinen Übungsplatz am Laufen zu halten. Da lokale Scharfschützen und Milizionäre ständig in seinem Lager trainieren und sich eindecken, schwinden seine Vorräte schnell, was regelmäßige Lieferungen von seinem Ingenieurspartner Loslor Rudge erfordert.",al={"was braucht hegnar","ziel von hegnar schlingerschuss","hegnar quest"}},["3c40a283"]={q="Warum ist Hegnar Schlingerschuss hier an der Straße?",a="Er hat sein Lager und seinen Schießstand entlang der viel befahrenen Straße zwischen Eisklamm und Kharanos aufgeschlagen. Dieser ideale Standort ermöglicht es ihm, sowohl frische Rekruten, die aus dem Tal kommen, als auch Patrouillen, die die zentralen Schneefelder von Dun Morogh verteidigen, auszustatten.",al={"warum ist hegnar hier draußen","standort von hegnars lager","warum hat hegnar ein lager aufgeschlagen"}}},fp="17,225,22.470.0,25.142.0,37.168.0,42.144.0"}
P.entries["npc:henze-faulk"] = {n="Henze Faulk",s="Henze Faulk ist ein zwergischer Abenteurer, der dem Tode nahe auf dem Steinkreis außerhalb von Heldenwache im Wald von Elwynn liegt. Er wurde von der Bruderschaft der Defias niedergestreckt, als er seinen Gefährten beschützte, und dient als entscheidende Prüfung für angehende Paladine, die den Umgang mit der Gabe der Wiederbelebung erlernen.",h="Henze Faulk ist ein zwergischer Abenteurer, der dem Tode nahe auf dem Steinkreis außerhalb von Heldenwache im...",kw={"defias","wald von elwynn","gazin tenorm","henze faulk","heldenwache","wiederbelebung","symbol des lebens","foliant der offenbarung"},ang={["class:Paladin"]="Henze Faulk verkörpert Eure erste wahre Prüfung göttlicher Barmherzigkeit. Ihn mit einem Symbol des Lebens von der Schwelle des Todes zurückzuholen, lehrt einen Paladin, dass das Licht nicht bloß eine Waffe für den Kampf ist, sondern eine feierliche Macht, um dem Tod zu trotzen.",["race:Dwarf"]="Einen zwergischen Volksgenossen in den Ländern der Menschen niedergestreckt zu sehen, ist eine ernüchternde Mahnung daran, dass Defias-Gesetzlose für Reisende aller Völker eine tödliche Bedrohung darstellen, nicht nur für die Einheimischen von Sturmwind."},sec={{t="Ein Opfer bei Heldenwache",b="Nahe dem uralten Steinkreis östlich von Sturmwind liegt Heldenwache, ein Ort, der oft von Defias-Banditen heimgesucht wird, die die Wälder von Elwynn durchstreifen. Henze Faulk und sein Freund Gazin Tenorm gerieten hier in einen Hinterhalt von Defias-Marodeuren. Henze begab sich selbst in Gefahr, um Gazins Überleben zu sichern, und erlag den Klingen der Banditen. Während sein Gefährte überlebte, um Hilfe aus der Kathedrale des Lichts herbeizurufen, verharrt Henzes Körper an der Schwelle zwischen Leben und Tod und wartet auf das göttliche Eingreifen eines Paladins, der ein Symbol des Lebens bei sich trägt."}},faq={{q="Wer ist Henze Faulk?",a="Henze Faulk ist ein Zwerg aus Eisenschmiede, der tödlich verwundet am Steinkreis nahe Heldenwache im Wald von Elwynn liegt. Er geriet in einen Hinterhalt und wurde von Defias-Banditen niedergestreckt, während er seinen Freund Gazin Tenorm rettete.",al={"henze faulk","zwerg bei heldenwache","sterbender zwerg elwynn"}},{q="Warum liegt Henze Faulk am Boden?",a="Henze geriet auf Reisen mit Gazin Tenorm in einen Hinterhalt der Bruderschaft der Defias. Er fing die Hauptlast des Angriffs ab, damit Gazin entkommen konnte, wodurch er tödlich verwundet zurückblieb und auf die Wiederbelebung durch einen Geweihten des Heiligen Lichts wartet.",al={"warum liegt henze im sterben","ist henze tot","henze faulk tot"}},{q="Welche Verbindung hat Henze zu Paladinen?",a="Henze ist die zentrale Gestalt bei einem Übergangsritus für junge Paladine, die sich den Prüfungen des Folianten der Offenbarung stellen. Paladin-Geweihten wird ein Symbol des Lebens anvertraut und sie werden nach Elwynn entsandt, um Henze vom Tode zurückzuholen, womit sie ihre Meisterschaft über den heiligsten Segen der Erlösung des Lichts beweisen.",al={"henze paladinquest","foliant der offenbarung zwerg"}},{q="Wer ist Gazin Tenorm?",a="Gazin Tenorm ist der Gefährte von Henze Faulk. Als die beiden von Defias-Gesetzlosen in die Enge getrieben wurden, beschützte Henze Gazin, wodurch dieser überleben und Hilfe bei der Kirche des Heiligen Lichts suchen konnte.",al={"wer ist gazin","gazin tenorm freund"}}},fx={["162be787"]={q="Auf wessen Seite steht Henze Faulk?",a="Henze Faulk ist fest mit der Allianz und dem Heiligen Licht verbündet. Als loyaler Freund und Zwergengefährte von Gazin Tenorm fiel er, während er tapfer seinen Freund vor den rücksichtslosen Gesetzlosen der Defias-Bruderschaft im Wald von Elwynn verteidigte.",al={"fraktion von henze faulk","ist henze bei der allianz","loyalität von henze faulk"}},["47ed07eb"]={q="Was will Henze Faulk?",a="Nachdem er einem bösartigen Hinterhalt der Defias-Bruderschaft zum Opfer gefallen ist, ist Henze Faulks unmittelbares Bedürfnis das Wunder des Lichts, um sein Leben zu retten. Abgesehen vom Überleben war seine selbstlose Absicht lediglich, seinen Begleiter Gazin Tenorm vor Schaden zu bewahren.",al={"was will henze","ziel von henze faulk","aufgabe von henze faulk"}}},fp="11,281,28.507.0,19.206.0,39.223.0,39.292.0,20.184.0"}
P.entries["npc:heralath-fallowbrook"] = {n="Heralath Bachquell",s="Heralath Bachquell ist ein sterbender Nachtelfendruide, der tief im Kral der Klingenhauer gefangen gehalten wird. Ausgesandt, um das dornige Verderben rund um die Überreste des Urahnen Agamaggan zu untersuchen, wurde er vom Stamm der Razorfen gefangen genommen und misshandelt. Mit seinen letzten Atemzügen versucht er, die Nachricht von seinem Schicksal und einen geliebten Anhänger zurück zu seiner Frau nach Darnassus zu senden.",h="Heralath Bachquell ist ein sterbender Nachtelfendruide, der tief im Kral der Klingenhauer gefangen gehalten...",kw={"agamaggan","fallowbrook","henrig lonebrow","heralath","die sterblichkeit schwindet","borstennacken","kral der klingenhauer","treshala"},ang={["class:Druid"]="Einen Druidengefährten zu sehen, der an den wilden Dornen des Krals der Klingenhauer zerbrach, ist eine deutliche Erinnerung an das wilde, unnachgiebige Verderben, das sich ungehindert im südlichen Brachland ausbreitet.",["race:NightElf"]="Heralaths Anhänger zurück nach Darnassus zu bringen, ehrt einen gefallenen Bruder, der sein Leben bei dem Versuch gab, die verwundeten Länder von Kalimdor zu verstehen und zu heilen."},sec={{t="Eine tragische Mission",b="Von seinem Volk entsandt, um den uralten Ebergott Agamaggan und das wuchernde Gestrüpp zu untersuchen, das das südliche Brachland erstickt, suchte Heralath Bachquell nach der Wurzel des Verderbens im Kral der Klingenhauer. Anstatt Antworten zu finden, wurde der Nachtelf von den Borstennacken gefangen genommen. Eingesperrt in einem elenden Pferch und unerbittlich geschlagen, erlag Heralath seinen schweren Wunden und einem rasenden Fieber. Bevor er gänzlich das Bewusstsein verlor, teilte er sein Wissen mit einem Mitgefangenen, dem Zwerg Henrig Lonebrow, und drängte ihn, den Außenposten der Schildwachen in Thalanaar vor der Aggression zu warnen, die von der Borstennackenvettel Charlga Klingenflanke geschürt wird."},{t="Ein letzter Wunsch",b="Obwohl Lonebrow die Flucht gelang, war Heralath viel zu schwach, um zu fliehen. An der Schwelle des Todes in den verschlungenen Pferchen des Krals klammert sich der Druide nur lange genug an das Bewusstsein, um vorbeikommende Abenteurer anzuflehen. Er bittet nicht um Rettung, sondern darum, den Anhänger seiner Frau Treshala von seinen Peinigern wiederzubeschaffen und zurück nach Darnassus zu bringen, damit sie von seinem Schicksal erfährt und weiß, dass er bis zum Ende an sie gedacht hat."}},faq={{q="Wer ist Heralath Bachquell?",a="Heralath Bachquell ist ein Nachtelfendruide, der im Kral der Klingenhauer gefangen gehalten wird. Er reiste ins Brachland, um das Verderben der Dornen und das Erbe des gefallenen Ebergottes Agamaggan zu erforschen, wurde jedoch von den Borstennacken gefangen genommen und tödlich gefoltert.",al={"wer ist heralath","heralath bachquell","nachtelf im kral von razorfen"}},{q="Was geschah mit Heralath im Kral der Klingenhauer?",a="Nachdem er von den Borstennacken der Razorfen gefangen genommen worden war, wurde Heralath geschlagen und in einer Hütte eingesperrt. Durch die unerbittlichen Misshandlungen und Krankheit versagte sein Körper, sodass er dem Tode nahe war, als Retter ihn erreichen konnten.",al={"warum liegt heralath im sterben","was geschah mit heralath bachquell"}},{q="Worum bittet Heralath Reisende?",a="Im Wissen, dass er nicht überleben wird, fleht Heralath Abenteurer an, den Anhänger seiner Frau von den Borstennacken wiederzubeschaffen und ihn ihr mit der tragischen Nachricht von seinem Tod nach Darnassus zu bringen.",al={"heralath quest","die sterblichkeit schwindet quest"}},{q="Wer war Henrig Lonebrow für Heralath?",a="Henrig Lonebrow war ein zwergischer Gefangener, der im selben Pferch wie Heralath festgehalten wurde. Bevor Henrig die Flucht gelang, teilte Heralath lebenswichtige Informationen über Agamaggan mit ihm und bat darum, den Außenposten Thalanaar über die Umtriebe von Charlga Klingenflanke in Kenntnis zu setzen.",al={"henrig lonebrow heralath","zwerg gefangener kral von razorfen"}}},fx={["4cf4e465"]={q="Auf wessen Seite steht Heralath Bachquell?",a="Heralath ist ein Nachtelf, der Darnassus und der Allianz treu ergeben ist. Als Druide seines Volkes wagte er sich in ihrem Namen tief in das Südliche Brachland, um die seltsame Verderbnis zu verstehen, die unter den Stachelebern Wurzeln schlug, und um Kalimdor vor der Dunkelheit zu schützen, die im Kral rührt.",al={"fraktion von heralath bachquell","ist heralath bei der allianz","loyalität von heralath"}},["6e64ea11"]={q="Warum ist Heralath Bachquell im Kral der Klingenhauer?",a="Er reiste hierher, um beharrlichen Gerüchten über den gefallenen Urtum Agamaggan nachzugehen und die Ursache der Fäulnis aufzudecken, die den Kral der Klingenhauer korrumpiert. Unglücklicherweise endete seine Expedition in einer Katastrophe, als die wilden Stacheleber des Krals der Klingenhauer ihn gefangen nahmen, ihn brutaler Gefangenschaft unterwarfen und ihm tödliche Wunden zufügten.",al={"warum ist heralath hier","heralaths zweck im kral","warum kam heralath zum kral der klingenhauer"}}},fp="20,351,16.596.0,12.413.1,28.252.0,48.213.0,39.174.0,36.262.0"}
P.entries["npc:herod"] = {n="Herod",s="Herod ist ein berühmter Champion und Berserker des Scharlachroten Kreuzzugs, der die Waffenkammer im Scharlachroten Kloster befehligt. Bekannt für sein wildes kriegerisches Können und seinen unerschütterlichen Eifer, bildet er Rekruten im brutalen Nahkampf aus, der für ihren heiligen Krieg erforderlich ist. Sein Tod wird sowohl von Abtrünnigen der Allianz als auch von den Herrschern der Horde in Unterstadt angestrebt, um den militärischen Kern des Kreuzzugs zu schwächen.",h="Herod ist ein berühmter Champion und Berserker des Scharlachroten Kreuzzugs, der die Waffenkammer im...",kw={"waffenkammer","berserker","herod","raleigh der fromme","ravager","scharlachroter kreuzzug","das scharlachrote kloster","varimathras"},ang={["class:Warrior"]="Herod ist ein Paradebeispiel für einen rasenden Krieger, dessen wilde Wirbelwindschläge und rücksichtslose Aggression ihn zu einem gefürchteten kriegerischen Vorbild unter den Rekruten des Scharlachroten Kreuzzugs machen.",["faction:Alliance"]="Helden der Allianz, die dem Ruf von Raleigh dem Frommen folgen, können aus erster Hand miterleben, wie die einst edlen Verteidiger von Lordaeron unter Anführern wie Herod in einen wahnhaften, fanatischen Blutrausch verfallen sind.",["faction:Horde"]="Für die Horde und insbesondere für die Verlassenen erfüllt die Ausschaltung von Herod unmittelbar die Befehle von Varimathras, die Führung zu zerschlagen, die die Grenzen von Tirisfal bedroht."},sec={{t="Der Champion der Waffenkammer",b="In den befestigten Hallen der Waffenkammer des Scharlachroten Klosters steht Herod als Verkörperung der kriegerischen Aggression des Kreuzzugs. Im Gegensatz zu den Zauberwirkern und Paladinen, die in der Kathedrale heilige Magie kanalisieren, verlässt sich Herod auf rohe, blutrünstige körperliche Kraft. Gehüllt in Kettenrüstung und mit einer gewaltigen Zweihandaxt bewaffnet, bildet er persönlich Kohorten von Scharlachroten Auszubildenden aus und pflanzt ihnen die glühende Ergebenheit ein, jeden zu vernichten, der nicht mit ihrer fanatischen Sache verbündet ist."},{t="Ein Ziel hoher Priorität",b="Da Herod die Rüstungsgüter und die militärische Ausbildung der Frontkrieger des Kreuzzugs überwacht, ist sein Untergang für jeden unerlässlich, der den Orden zerschlagen will. Raleigh der Fromme, ein ehemaliger Kreuzfahrer in Süderstade, der von dem Wahnsinn des Ordens desillusioniert ist, fordert Herods Tod, um deren militärische Führung zu brechen. Auf der anderen Seite von Lordaeron trachtet der Schreckenslord Varimathras in Unterstadt gleichermaßen nach seiner Hinrichtung, um eine gefährliche Bastion der Menschen an der Grenze zum Territorium der Verlassenen zu beseitigen."}},faq={{q="Wer ist Herod?",a="Herod ist ein elitärer Krieger der Menschen und Kommandant der Waffenkammer im Scharlachroten Kloster. Er dient als einer der vier Hauptanführer des Klosters und ist für die Ausrüstung und den Drill der fanatischen Nahkämpfer des Kreuzzugs verantwortlich.",al={"herod lore","wer ist herod","herod scharlachrotes kloster"}},{q="Wo befindet sich Herod?",a="Herod befindet sich im Herzen des Flügels der Waffenkammer im Scharlachroten Kloster, das im nordöstlichen Tirisfal liegt. Er erwartet Herausforderer in einem zentralen Trainingsring, der von Zuschauertribünen umgeben ist.",al={"wo ist herod","herod aufenthaltsort","herod finden"}},{q="Warum will die Horde Herod tot sehen?",a="Der Schreckenslord Varimathras, der im Namen der Verlassenen in Unterstadt handelt, fordert die Vernichtung der wichtigsten Kommandanten des Klosters – einschließlich Herod –, um die verbliebene Bedrohung durch den Kreuzzug direkt vor den Toren der Hauptstadt der Verlassenen zu beseitigen.",al={"varimathras herod quest","warum horde herod tötet","ins scharlachrote kloster"}},{q="Warum will die Allianz Herod tot sehen?",a="Raleigh der Fromme, ein ehemaliges Mitglied des Scharlachroten Kreuzzugs im Vorgebirge des Hügellands, erkennt, dass der Orden in fanatischen Eifer verfallen ist. Er bittet Champions der Allianz, Herod zu beseitigen, um dem Kreuzzug seine brutale Kriegerführung zu nehmen.",al={"im namen des lichts","raleigh der fromme herod","warum allianz herod tötet"}},{q="Was geschieht, wenn Herod besiegt wird?",a="Nach Herods Niederlage strömt eine Meute junger Scharlachroter Auszubildender aus den umliegenden Baracken in den Ring, um ihren Meister zu rächen, was die tiefe Ergebenheit verdeutlicht, die er in seinen Schülern weckte.",al={"scharlachrote auszubildende","herod ansturm der auszubildenden","herod todesevent"}},{q="Was für ein Kämpfer ist Herod?",a="Herod ist eher ein Berserker und Krieger als ein traditioneller heiliger Paladin. Er setzt bösartige Sturmangriffe und weitreichende Wirbelwindschläge ein, um Feinde zu zermalmen, und verlässt sich auf puren physischen Rausch anstelle von Zaubern des Heiligen Lichts.",al={"herod kampfstil","ist herod ein paladin"}}},fx={["3c3e6bcb"]={q="Auf wessen Seite steht Herod?",a="Herod ist ein hochrangiger Kommandant der Scharlachroten Kreuzzug und einer der vier Hauptanführer, die im Scharlachroten Kloster stationiert sind. Er ist fanatisch loyal gegenüber der fanatischen Mission des Kreuzzugs und richtet dessen militärische Ausbildung und Waffenkammer gegen jeden, den der Kreuzzug als unrein oder feindselig erachtet.",al={"fraktion von herod","wem dient herod","auf welcher seite steht herod"}},["78320a40"]={q="Was will Herod?",a="Herod widmet sich der Ausbildung der nächsten Generation von Kriegern des Scharlachroten Kreuzzugs, um deren Feinde auszurotten. Er überwacht die Waffenkammer, drillt Rekruten, damit sie seinem eigenen unerbittlichen kriegerischen Eifer nacheifern, und versucht, jeden zu vernichten, der töricht genug ist, das heilige Gelände des Klosters zu betreten.",al={"herods ziel","herods zweck","was versucht herod zu tun"}},["60fea3ae"]={q="Warum ist Herod hier?",a="Herod befehligt den Flügel der Waffenkammer im Scharlachroten Kloster. Als Champion und Ausbilder der Rekruten des Kreuzzugs überwacht er dessen Arsenal und prüft persönlich jeden, der es wagt, das Kernland des Kreuzzugs herauszufordern.",al={"warum ist herod in der waffenkammer","warum ist herod im scharlachroten kloster","rolle von herod in der waffenkammer"}},f73350c1={q="Mit wem ist Herod verbunden?",a="Herod steht an der Seite der inneren Führung des Scharlachroten Klosters, zu der Hochinquisitorin Weißsträhne, Scharlachroter Kommandant Mograine und Hundemeister Loksey gehören. Gemeinsam regieren sie die Bastion des Kreuzzugs im Tirisfal.",al={"wer führt herod","verbündete von herod","mit wem arbeitet herod zusammen"}},["9c060a47"]={q="Warum ist Herod berühmt oder gefürchtet?",a="Bekannt als der Scharlachrote Champion, ist Herod für seinen wilden Berserker-Kampfstil berühmt. Er schwingt eine massive Streitaxt und ist berüchtigt dafür, sich in einen verheerenden, unaufhaltsamen Wirbel aus Stahl zu drehen, der alle nahen Feinde in Stücke reißt.",al={"warum wird herod gefürchtet","herods ruf","was macht herod gefährlich"}}},fp="5,373,26.452.0,22.488.0,13.228.0,23.200.0,35.239.0,38.254.0,36.201.1,30.210.0"}
P.entries["npc:high-executor-darthalia"] = {n="Hochexekutorin Darthalia",s="Hochexekutorin Darthalia ist eine hochrangige militärische Befehlshaberin der Verlassenen, die in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Unter der direkten Autorität von Fürstin Sylvanas Windläufer und Varimathras leitet sie die Operationen der Verlassenen gegen die Menschenfeste Süderstade und die örtlichen Banditen des Syndikats. Ihre Führung ist entscheidend für die Sicherung der südlichen Flanke der Horde in Lordaeron.",h="Hochexekutorin Darthalia ist eine hochrangige militärische Befehlshaberin der Verlassenen, die in Tarrens...",kw={"darthalia","hochexekutor","hillsbrad","vorgebirge des hügellands","süderstade","sylvanas","syndikat","tarrens mühle","varimathras"},ang={["faction:Alliance"]="Für die Menschen von Süderstade und ihre Verbündeten ist Darthalia die unbarmherzige Planerin hinter den unerbittlichen Angriffen, die ihren letzten Stützpunkt in Lordaeron bedrohen.",["faction:Horde"]="Abenteurer der Horde erstatten Darthalia Bericht, um der Aggression der Allianz Einhalt zu gebieten und die umkämpfte Grenzregion im Vorgebirge des Hügellands zu halten.",["race:Undead"]="Für die Verlassenen verkörpert Darthalia den eisernen Willen von Unterstadt und stellt sicher, dass Lordaeron fest in den Händen der Untoten mit freiem Willen bleibt."},sec={{t="Kommandantin von Tarrens Mühle",b="Von Tarrens Mühle aus dient Hochexekutorin Darthalia als operative Kommandantin für die Streitkräfte der Verlassenen im gesamten Vorgebirge des Hügellands. Ihr vorrangiges strategisches Anliegen ist es, die Ausbreitung des menschlichen Widerstands aufzuhalten, die Streitkräfte der Allianz in Süderstade in Schach zu halten und die gesetzlosen Schurken des Syndikats zur Strecke zu bringen, die das Umland heimsuchen. Jeder Offensivvorstoß in das südliche Hillsbrad unterliegt direkt ihrem Befehl."},{t="Der Krieg um Hillsbrad",b="Auf direkte Befehle der Führung von Unterstadt – der Bansheekönigin und ihres Schreckenslord-Leutnants Varimathras – überwacht Darthalia den unerbittlichen Zermürbungskrieg in Hillsbrad. Sie koordiniert Späheinsätze, gezielte Angriffe gegen die Führung der Menschen sowie Kopfgelder auf gefährliche Gesetzlose, die die Herrschaft der Verlassenen über das nördliche Lordaeron bedrohen."}},faq={{q="Wer ist Hochexekutorin Darthalia?",a="Hochexekutorin Darthalia ist eine militärische Anführerin der Verlassenen, die im Vorgebirge des Hügellands stationiert ist. Sie ist dafür verantwortlich, die militärischen Anstrengungen der Horde und der Verlassenen gegen die Menschenstadt Süderstade zu leiten und feindliche regionale Bedrohungen zu beseitigen.",al={"wer ist darthalia","darthalia identität","exekutorin darthalia"}},{q="Wo ist Darthalia zu finden?",a="Sie befehligt die Streitkräfte der Verlassenen von Tarrens Mühle aus, organisiert Truppen und koordiniert Vorstöße in der gesamten zentralen Region von Lordaeron.",al={"darthalia aufenthaltsort","wo ist darthalia","exekutorin darthalia karte"}},{q="Wem untersteht Darthalia?",a="Darthalia operiert innerhalb der direkten Militärhierarchie von Unterstadt und untersteht Fürstin Sylvanas Windläufer sowie dem Schreckenslord Varimathras, während diese die Verteidigung und Ausdehnung des Territoriums der Verlassenen koordinieren.",al={"darthalia vorgesetzter","darthalia fraktion","wer befehligt darthalia"}},{q="Welche Aufgaben überträgt Darthalia Abenteurern?",a="Darthalia beauftragt die Champions der Horde damit, direkte Angriffe gegen menschliche Siedlungen durchzuführen, gefährliche Gesetzlose hinzurichten und Mitglieder des Syndikats zu jagen, die im Vorgebirge des Hügellands ihr Unwesen treiben.",al={"darthalia quests","quests von darthalia","was will darthalia"}},{q="Warum kämpft Darthalia gegen die Menschen von Süderstade?",a="Süderstade stellt den primären militärischen Stützpunkt der Allianz in Lordaeron dar. Darthalias Mission besteht darin, die menschliche Präsenz zu unterdrücken, Tarrens Mühle zu schützen und zu verhindern, dass die Allianz nach Norden in Richtung Unterstadt vorstößt.",al={"warum süderstade angreifen","krieg um süderstade","hillsbrad konflikt"}},{q="Welchen Rang hat Darthalia im Militär der Verlassenen inne?",a="Als Hochexekutorin bekleidet Darthalia einen der höchsten Ränge der Feldkommandoebene innerhalb der Militärhierarchie der Verlassenen, was ihr das operative Kommando über die regionalen Streitkräfte, Außenposten und die Kriegsstrategie in der Zone verleiht.",al={"rang hochexekutor","darthalia titel"}}},fx={c2c985e7={q="Auf wessen Seite steht Hochexekutorin Darthalia?",a="Hochexekutorin Darthalia dient den Verlassenen und der Horde. Sie fungiert als hochrangige militärische Kommandantin unter dem Befehl von Fürstin Sylvanas Windläufer und Varimathras und leitet die Operationen der Horde im Vorgebirge des Hügellands, um die Region gegen Übergriffe der Allianz zu sichern.",al={"fraktion von darthalia","für wen kämpft darthalia","ist darthalia horde"}},["77f4a495"]={q="Was will Hochexekutorin Darthalia?",a="Darthalia will die Ausbreitung der Menschheit aufhalten und den Einfluss der Allianz im gesamten Vorgebirge des Hügellands ausrotten. Sie koordiniert Angriffe gegen nahegelegene menschliche Festungen wie Süderstade und eliminiert rivalisierende Bedrohungen wie das Syndikat, um eine unangefochtene Kontrolle der Verlassenen über das Gebiet zu gewährleisten.",al={"darthalias ziele","was versucht darthalia zu tun","darthalias zweck"}},f4963853={q="Warum ist Hochexekutorin Darthalia hier?",a="Sie ist in Tarrens Mühle stationiert, um den Feldzug der Verlassenen im Vorgebirge des Hügellands zu beaufsichtigen. Von diesem zentralen Vorposten aus organisiert sie Kriegsanstrengungen gegen die feindseligen menschlichen Siedlungen im Süden und sichert die südlichen Zugänge nach Tirisfal und zur Unterstadt.",al={"warum ist darthalia in tarrens mühle","darthalia hügelland warum","grund warum darthalia hier ist"}}},fp="23,385,24.440.0,21.364.0,31.235.0,29.129.0,29.208.0,46.198.0,51.216.0,50.207.0"}
P.entries["npc:high-executor-derrington"] = {n="Hochexekutor Derrington",s="Hochexekutor Derrington befehligt die Vorhut der Verlassenen, die am Bollwerk an der östlichen Grenze von Tirisfal stationiert ist. Als pragmatischer Militäroffizier leitet er die vorderste Verteidigungslinie der Horde gegen die Bedrohungen durch die Geißel und den Scharlachroten Kreuzzug, die von den Westlichen Pestländern ausgehen. Von dieser befestigten Barrikade aus entsendet er erfahrene Champions zu umkämpften Ruinen wie Andorhal und Scholomance.",h="Hochexekutor Derrington befehligt die Vorhut der Verlassenen, die am Bollwerk an der östlichen Grenze von...",kw={"andorhal","das bollwerk","derrington","verlassene","hochexekutor derrington","geißel","tirisfal","westliche pestländer"},ang={["class:Warrior"]="Derrington verkörpert die düstere, praktische Härte eines Frontsoldaten, der kriegerische Kompetenz und greifbare Ergebnisse auf dem Schlachtfeld über höfische Ränkespiele stellt.",["faction:Horde"]="Für Reisende der Horde, die in Tirisfal ankommen, ist Derrington der wichtigste militärische Befehlshaber, der Truppen in die gefährlichen Konflikte der Westlichen Pestländer lenkt.",["race:Undead"]="Derrington stellt das kriegerische Rückgrat des Militärs der Verlassenen dar und konzentriert sich ganz darauf, ihr zurückerobertes Land vor der Rückeroberung durch die Geißel und dem scharlachroten Fanatismus zu bewahren."},sec={{t="Kommandant an der Schwelle",b="Direkt vor den befestigten Barrikaden des Bollwerks stehend dient Hochexekutor Derrington als Torwächter zwischen der gespenstischen Sicherheit von Tirisfal und den verrottenden Schrecken der Westlichen Pestländer. Derrington hat wenig Geduld für politische Ränkespiele in Unterstadt und betrachtet die Front als Schmelztiegel des nackten Überlebens. Soldaten und Söldnern der Horde, die ihren Mut auf die Probe stellen wollen, erteilt Derrington direkte militärische Befehle und schickt Späher sowie Angriffstrupps tief in verseuchtes Gebiet, um feindliche Vorstöße abzuwehren, bevor sie Tirisfal erreichen."},{t="Ein Zweifrontenkrieg",b="Derringtons Verteidigungsposition wird von mehreren Seiten bedrängt. Im Osten lauert die Geißel, die sich in der zerstörten Stadt Andorhal verschanzt hat und sich über verseuchende Kessel über das Land ausbreitet. Gleichzeitig fechten die fanatischen Eiferer des Scharlachroten Kreuzzugs nördliche Befestigungen an und liefern sich unerbittliche Scharmützel mit Patrouillen der Verlassenen. Derrington koordiniert gezielte Gegenangriffe, Sabotageakte gegen die scharlachroten Stellungen und die systematische Zerstörung von Kesselfeldern der Geißel, um die Ostgrenze zu sichern."}},faq={{q="Wer ist Hochexekutor Derrington?",a="Hochexekutor Derrington ist der ranghöchste Kommandant der Verlassenen am Bollwerk, dem militärischen Außenposten, der Tirisfal von den Westlichen Pestländern trennt. Er koordiniert den strategischen Vorstoß der Horde nach Osten gegen die Geißel und den Scharlachroten Kreuzzug.",al={"derrington","wer ist derrington","hochexekutor derrington geschichte"}},{q="Wo befindet sich Derrington?",a="Er ist am Bollwerk stationiert, dem befestigten Engpass am äußersten östlichen Rand von Tirisfal an der Straße, die in die Westlichen Pestländer führt.",al={"wo ist derrington","derrington aufenthaltsort","hochexekutor derrington finden"}},{q="Was ist Derringtons Ziel am Bollwerk?",a="Derringtons Ziel ist es, das Überleben der Verlassenen zu sichern, indem er einen starken Verteidigungsgürtel gegen die Geißel aufrechterhält und Angriffe nach Osten in die Westlichen Pestländer führt. Er beauftragt Abenteurer damit, Andorhal auszukundschaften, Pestkessel zu deaktivieren und Operationen des Scharlachroten Kreuzzugs zu neutralisieren.",al={"was will derrington","das bollwerk zweck","derrington aufgabe"}},{q="Interessiert sich Derrington für die Politik in Unterstadt?",a="Nein. Derrington hegt offene Verachtung für höfische Ränkeschmiede und Politiker und betont, dass an der Frontlinie, wo man täglich um das Überleben kämpfen muss, kein Platz für solchen Luxus ist.",al={"derrington persönlichkeit","ist derrington politisch"}},{q="Gegen welche Hauptbedrohungen entsendet Derrington Soldaten?",a="Derrington zielt vor allem auf die Geißel ab, welche die Ruinen von Andorhal besetzt hält, auf die finsteren Nekromanten in Scholomance sowie auf nahegelegene Garnisonen des Scharlachroten Kreuzzugs, die die östlichen Nachschubwege der Horde gefährden.",al={"derrington quests","was bekämpft derrington"}},{q="Warum ist Das Bollwerk so schwer befestigt?",a="Das Bollwerk dient als wichtigster Engpass zwischen der relativen Sicherheit von Tirisfal und den aktiven Kampfzonen der Pestländer. Derringtons Truppen halten den Pass, um zu verhindern, dass gewaltige Schwärme der Geißel oder Vorstöße des Scharlachroten Kreuzzugs direkt auf Unterstadt zuströmen.",al={"warum gibt es das bollwerk","das bollwerk geschichte"}}},fx={["895ac470"]={q="Auf wessen Seite steht Hochexekutor Derrington?",a="Hochexekutor Derrington steht fest an der Seite der Verlassenen und der Horde. Als hochrangiger militärischer Kommandant unter der Dunklen Fürstin widmet er sich der Verteidigung ihres Reiches und der Sicherung ihres Platzes in Lordaeron gegen alle, die ihre Ausrottung wünschen.",al={"fraktion von derrington","wem dient derrington","ist derrington horde"}},e8355a95={q="Warum ist Hochexekutor Derrington am Bollwerk stationiert?",a="Derrington befehligt die Frontverteidigung von Tirisfal. Stationiert an der Grenze zwischen Tirisfal und den Westlichen Pestländern, überwacht er die Befestigung, die Einfälle der Geißel aufhält und den Vormarsch der Verlassenen nach Osten in das Herz der verpesteten Länder vorbereitet.",al={"warum ist derrington hier","derrington am bollwerk","warum ist derrington an der grenze"}}},fp="24,400,26.575.0,19.517.0,32.252.0,28.161.0,46.293.0,46.176.0,57.199.0,40.282.0"}
P.entries["npc:high-executor-hadrec"] = {n="Hochexekutor Hadrec",s="Hochexekutor Hadrec ist der militärische Kommandant der Garnison der Verlassenen, die im Grabmal im Silberwald stationiert ist. Von dieser zentralen Gruft aus überwacht er die Verteidigung gegen regionale Bedrohungen wie die Gnolle des Rot Hide-Klans und untersucht das Verschwinden von Spähern in der gesamten Zone. Er fungiert als leitender Offizier, der die Operationen der Horde im gesamten Silberwald lenkt.",h="Hochexekutor Hadrec ist der militärische Kommandant der Garnison der Verlassenen, die im Grabmal im...",kw={"todespirscher","insel fenris","hadrec","hochexekutor","rot hide","das grabmal","shadowfang","silberwald"},ang={["class:Rogue"]="Hadrec verlässt sich bei der Informationsbeschaffung stark auf die Todespirscher und setzt häufig heimliche Agenten ein, um vermisste Kameraden zu bergen sowie feindliches Ichor und Dokumente zu beschaffen.",["faction:Horde"]="Verbündete der Verlassenen, die aus Kalimdor eintreffen, machen bei Hadrec Meldung, um bei der Stabilisierung des Silberwalds zu helfen, und erfahren aus erster Hand, wie unsicher die Stellung der Horde im nördlichen Lordaeron nach wie vor ist.",["race:Undead"]="Für Verlassene, die aus Todesend nach Süden reisen, verkörpert Hadrec die Stimme des Oberkommandos von Unterstadt, die neugeborene Untote zu organisierten Verteidigern von Lordaeron formt."},sec={{t="Kommandant im Grabmal",b="Inmitten der Düsternis des Grabmals stationiert, leitet Hochexekutor Hadrec die militärischen Operationen der Verlassenen im gesamten Silberwald. Während Tirisfal von den Streitkräften der Dunklen Fürstin fest gesichert ist, bleibt der Silberwald voller Gefahren, umgeben von feindseligen Magiern aus Dalaran, wilden Worgen und eindringenden Gnollen. Hadrec trägt die düstere Verantwortung, das Territorium der Verlassenen zu festigen und alles auszulöschen, was die Autorität von Unterstadt südlich der Hauptstadt anfechtet."},{t="Die Rot Hide-Geißel",b="Ein Großteil von Hadrecs unmittelbarer Sorge gilt den Rot Hide-Gnollen und der Insel Fenris. Diese von der Untoten-Seuche verdorbenen Bestien haben das Todesfeld und die Ufer des Lordameresees heimgesucht und stellen eine unberechenbare und grausame Bedrohung für die Patrouillen der Verlassenen dar. Hadrec entsendet Agenten, um die verfallenen Fähren und verrottenden Gehöfte nach Hinweisen abzusuchen, festzustellen, was die Bestien stärkt, und einen direkten Angriff auf ihre Inselfestung vorzubereiten."},{t="Ein wachsames Auge auf Shadowfang",b="Neben der Gnollplage beobachtet Hadrec aufmerksam die Berichte der Todespirscher, dem verschwiegenen Spionagezweig der Verlassenen. Wenn verdeckte Ermittler in der Nähe der unheimlichen Türme von Burg Shadowfang verschwinden, beauftragt Hadrec Abenteurer damit, ihr Schicksal aufzuklären, um sicherzustellen, dass die Dunkle Fürstin über den finsteren Erzmagier Arugal und seine verfluchten Worgen informiert bleibt."}},faq={{q="Wer ist Hochexekutor Hadrec?",a="Hadrec ist ein militärischer Offizier der Verlassenen im Rang eines Hochexekutors. Er befehligt die im Grabmal stationierte Garnison, was ihn zur obersten Autorität der Verlassenen für die Operationen im Silberwald macht.",al={"hadrec lore","wer ist hadrec","kommandant des grabmals"}},{q="Wo ist Hochexekutor Hadrec zu finden?",a="Er befindet sich im Grabmal, der Siedlung der Verlassenen im zentralen Silberwald an der nördlich-südlichen Hauptstraße.",al={"hadrec aufenthaltsort","wo ist hadrec","hadrec finden"}},{q="Gegen welche Bedrohungen führt Hadrec die Spieler?",a="Hadrec führt Soldaten und Abenteurer gegen die Rot Hide-Gnolle, die das Todesfeld und die Insel Fenris heimsuchen. Er überwacht außerdem Einsätze, um vermisste Spione der Todespirscher aufzuspüren und herauszufinden, was sich im Inneren von Burg Shadowfang abspielt.",al={"hadrec quests","was macht hadrec","silberwald missionen"}},{q="Was tut ein Hochexekutor in der militärischen Struktur der Verlassenen?",a="Ein Hochexekutor ist ein hochrangiger Feldkommandant im Militär der Verlassenen, der mit der vollständigen strategischen Aufsicht über einen gesamten regionalen Außenposten oder eine Frontlinie unter der Autorität von Fürstin Sylvanas Windläufer betraut ist.",al={"hochexekutor der verlassenen","rang hochexekutor","hadrec rang"}},{q="Warum interessiert sich Hadrec für die Insel Fenris?",a="Die Insel Fenris ist zum Hauptbau der Rot Hide-Gnolle geworden. Um den Lordameresee und die umliegenden Wasserwege für die Nachschublinien der Verlassenen zu sichern, koordiniert Hadrec die Aufklärung und einen anschließenden Angriff, um die Führung der Gnolle zu zerschlagen.",al={"insel fenris hadrec","warum insel fenris angreifen","rot hide fenris"}},{q="Welche Verbindung hat Hadrec zu Burg Shadowfang?",a="Hadrec stimmt sich mit den Todespirschern ab, dem Spionageorden der Verlassenen. Wenn Späher, die in Richtung Burg Shadowfang geschickt wurden, keine Rückmeldung mehr geben, beauftragt Hadrec vertrauenswürdige Agenten damit, die Burg zu untersuchen und herauszufinden, was ihnen zugestoßen ist.",al={"burg shadowfang hadrec","hadrec arugal","todespirscher in burg schattenfang"}}},fx={["82ec3fb8"]={q="Auf wessen Seite steht Hochexekutor Hadrec?",a="Hochexekutor Hadrec dient den Verlassenen und der Dunklen Fürstin, Königin Sylvanas Windläufer, als Teil der Horde. Von seinem Posten im Grabmal aus befehligt er die militärischen Operationen der Verlassenen im Silberwald und handelt direkt im Interesse der Unterstadt.",al={"fraktion von hadrec","wem dient hadrec","hadrec horde"}},["3524c842"]={q="Was will Hochexekutor Hadrec?",a="Hadrec strebt danach, den Silberwald für die Verlassenen zu sichern und die südliche Flanke der Unterstadt zu schützen. Er koordiniert Bemühungen, um Informationen über feindliche Bewegungen zu sammeln, die Geißel der Rotfell-Gnolle, die die Region heimsucht, auszurotten und rivalisierende Bedrohungen zu eliminieren, die im gesamten Wald von der Insel Fenris bis zu den Außenbezirken von Burg Shadowfang lauern.",al={"was ist das ziel von hadrec","hadrecs motive","hadrecs ziele im silberwald"}},ed357496={q="Warum ist Hochexekutor Hadrec hier im Grabmal?",a="Hadrec ist im Grabmal stationiert, weil es als die zentrale militärische und operative Festung der Verlassenen im Silberwald dient. Als Hochexekutor überwacht er regionale Operationen, koordiniert Feldberichte der Deathstalkers und entsendet Champions, um aufkommende Bedrohungen zu neutralisieren und die Herrschaft der Verlassenen über das Gebiet zu gewährleisten.",al={"warum ist hadrec am grabmal","hadrecs standort silberwald","warum ist hadrec im silberwald"}},["4117c6ac"]={q="Mit wem ist Hochexekutor Hadrec verbunden?",a="Hadrec arbeitet eng mit der verdeckten Nachrichtendienst-Abteilung der Verlassenen zusammen, den Deathstalkers, empfängt Feldberichte und entsendet Verstärkung, um versteckte Gefahren aufzudecken. Er arbeitet auch mit lokalen Spezialisten wie Apotheker Renferrel zusammen, um regionale Bedrohungen wie die Rotfell-Gnolle zu untersuchen.",al={"verbündete von hadrec","hadrecs verbindungen","mit wem arbeitet hadrec zusammen"}}},fp="20,377,26.464.0,20.432.0,17.369.1,28.201.0,40.130.0,48.229.0,60.208.0,40.233.0,47.226.0"}
P.entries["npc:high-inquisitor-fairbanks"] = {fx={["14cc9219"]={q="Auf wessen Seite steht Hochinquisitor Schönufer jetzt?",a="Schönufer gehört keiner Fraktion mehr an. Obwohl er einst ein verehrter Priester der Silbernen Hand und der engste Vertraute von Hochlord Alexandros Mograine war, haben sein Mord und seine anschließende Wiedererhebung als Untoter ihm seinen Verstand und seine früheren Loyalitäten geraubt. Verzehrt von der Pest des Untodes und von denselben Eiferern weggesperrt, die er einst leitete, ist er völlig feindselig gegenüber jedem Lebenden, der sein verstecktes Grab betritt, und schlägt in gedankenloser Qual und Wahnsinn um sich.",al={"fraktion von schönufer","ist schönufer feindselig","schönufers seite"}}}}
P.entries["npc:high-priest-rohan"] = {n="Hohepriester Rohan",s="Hohepriester Rohan ist der herausragende Anführer der Kirche des Heiligen Lichts in Eisenschmiede, der in der Hall of Mysteries seine Bahnen zieht. Er überwacht die spirituelle Entwicklung angehender Priester in der gesamten Allianz und steht jenen bei, die nach Meisterschaft über das Heilige Licht streben. Durch seine Führung und heilige Relikte pflegt er spirituelle Bande zwischen dem Bergkönigreich, Sturmwind und fernen Verbündeten.",h="Hohepriester Rohan ist der herausragende Anführer der Kirche des Heiligen Lichts in Eisenschmiede, der in der...",kw={"kirche des heiligen lichts","weihrauchschwenker","grayson shadowbreaker","hall of mysteries","hohepriester rohan","eisenschmiede","mystic ward","priesterlehrer","rohan"},ang={["class:Paladin"]="Heilige Ritter, die von Lord Grayson Schattenbruch entsandt wurden, müssen Rohan aufsuchen, um seinen berühmten Weihrauchschwenker im Austausch gegen Hilfe für die Bedürftigen von Eisenschmiede zu erhalten.",["class:Priest"]="Hohepriester Rohan bietet grundlegende Führung und frühe Fähigkeiten-Ausbildung, bevor er Euch schließlich an renommierte Mentoren in Sturmwind oder Darnassus verweist, um einzigartige volksspezifische Andachten freizuschalten.",["faction:Alliance"]="Durch seine enge Zusammenarbeit mit der Kathedrale des Lichts, dem Tempel des Mondes und dem Zirkel des Cenarius hält Rohan die Geistlichkeit von Eisenschmiede eng mit der restlichen Allianz verwoben.",["race:Dwarf"]="Rohan verkörpert die zwergische Hingabe an das Heilige Licht und zeigt, dass das standhafte Volk von Khaz Modan neben seinem Titanenerbe auch eine tiefe spirituelle Überzeugung besitzt."},sec={{t="Hirte der Hall of Mysteries",b="Während er über die stillen Steinplatten der Hall of Mysteries im Mystic Ward schreitet, agiert Hohepriester Rohan als ranghöchster Vertreter der Kirche des Heiligen Lichts in Eisenschmiede. Obwohl die Zwerge historisch die Titanen verehrten, haben zwergische Priester die Tugenden des Lichts – Weisheit, Mitgefühl und Gerechtigkeit – tief verinnerlicht. Rohan dient jungen Akolythen als geduldiger Lehrer, der ihnen die Disziplin beibringt, die nötig ist, um heilige Magie zu kanalisieren und ihren Geist gegen Verzweiflung zu stählen."},{t="Brücken in der Allianz",b="Rohan weiß, dass spirituelle Erkenntnis in der Allianz viele Formen annimmt. Sobald die Priester unter seiner Vormundschaft die Grundlagen beherrschen, schickt er sie hinaus – er sendet menschliche und zwergische Schüler zu Hohepriesterin Laurena in Sturmwind oder entsendet Nachtelfen-Jünger zu Priesterin Alathea in den Tempel des Mondes in Darnassus, um schwer fassbare Mysterien wie Elunes Anmut zu meistern. Über die Hauptstädte hinaus drängt er Gläubige dazu, überall dort Hilfe zu leisten, wo Not herrscht, und schickt sogar Heiler in die Ferne, um den Druiden des Zirkels des Cenarius im entlegenen Azshara beizustehen."},{t="Der Weihrauchschwenker",b="Zusätzlich zu seinen Lehren verwahrt Rohan heilige Relikte, die für die Priesterschaft und die Paladin-Bruderschaften der gesamten Allianz unverzichtbar sind. Zu seinen Besitztümern gehört ein gesegneter Weihrauchschwenker, erprobt durch jahrelange Läuterung verruchter Geister. Wenn der Orden der Silbernen Hand und Lord Grayson Schattenbruch das Gefäß benötigen, um die heilige Berufung ihrer Ritter zu festigen, überlässt Rohan es ihnen bereitwillig – und bittet im Gegenzug lediglich um wohltätige Gaben, um Eisenschmiedes schwindende Nahrungsvorräte für die Bedürftigen der Stadt aufzustocken."}},faq={{q="Wo finde ich Hohepriester Rohan?",a="Hohepriester Rohan befindet sich in der Hall of Mysteries, die im Mystic Ward im nördlichen Teil von Eisenschmiede liegt. Er geht zwischen der heiligen Bibliothek und dem Altar auf und ab.",al={"rohan aufenthaltsort","wo ist der priesterlehrer in eisenschmiede","rohan karte","hall of mysteries priesterlehrer"}},{q="Welche Rolle hat Rohan in Eisenschmiede inne?",a="Er ist der ranghöchste Priesterlehrer in Eisenschmiede und der führende zwergische Vertreter der Kirche des Heiligen Lichts in Khaz Modan. Er bildet neue Priester aus, spendet spirituellen Rat und leitet Gläubige zu weiterführenden Studien in ganz Azeroth an.",al={"wer ist rohan","was tut rohan","rohan lore"}},{q="Warum schickt Rohan Priester nach Darnassus oder Sturmwind?",a="Rohan glaubt, dass spirituelles Wachstum das Lernen aus unterschiedlichen Traditionen erfordert. Er schickt menschliche und zwergische Initianden zur Kathedrale des Lichts in Sturmwind, um spezialisierte Gebete wie Verzweifeltes Gebet zu erlernen, und leitet Nachtelfen zurück in Darnassus' Tempel des Mondes, damit sie sich auf Elunes Anmut einstimmen können.",al={"rohan klassenquests","verzweifeltes gebet rohan","tempel des mondes quest"}},{q="Warum suchen Paladine Rohan auf?",a="Paladine, die von Lord Grayson Schattenbruch entsandt wurden, besuchen Rohan, um seinen gesegneten Weihrauchschwenker zu erhalten. Rohan überlässt das Relikt, um dem Orden der Silbernen Hand bei der Vollendung ihrer Riten zu helfen, und bittet im Gegenzug um eine bescheidene Spende an Vorräten, um die Bedürftigen von Eisenschmiede zu ernähren.",al={"paladinquest rohan","weihrauchschwenker","schwerpunkt auf opferbereitschaft"}},{q="Warum schickt Rohan Priester nach Azshara?",a="Geleitet von den Grundsätzen des Lichts bezüglich Nächstenliebe und Hilfsbereitschaft entsendet Rohan Heiler, um den Nachtelfen-Druiden des Zirkels des Cenarius beizustehen, die in den wilden, rauen Ländern von Azshara wirken.",al={"cenarushilfe rohan","rohan zirkel des cenarius"}},{q="Bildet Rohan nur Zwerge aus?",a="Rohan leitet jeden Anhänger der Allianz an, der den Pfad des Priestertums beschreitet, darunter Zwerge, Menschen und Nachtelfen. Er bietet frühe Unterweisung, bevor er sie an Mentoren weiterleitet, die auf ihre spezifischen Traditionen abgestimmt sind.",al={"können menschen bei rohan trainieren","wen bildet rohan aus"}}},fx={["077c3151"]={q="Wer ist Hohepriester Rohan?",a="Hohepriester Rohan ist das ranghöchste Mitglied der Kirche des Heiligen Lichts, das in Eisenschmiede residiert. Ein ehrwürdiger und frommer Zwerg, der als geistiger Hauptmentor für Priester innerhalb des Bergkönigreichs dient und Novizen in den Wegen der Hingabe, der Heilung und des heiligen Zorns unterweist.",al={"wer ist rohan","hohepriester rohan","hintergrund von rohan"}},["940e11c6"]={q="Auf wessen Seite steht Hohepriester Rohan?",a="Rohan steht fest an der Seite des Königreichs Eisenschmiede, der Großen Allianz und der Kirche des Heiligen Lichts. Er arbeitet eng mit dem menschlichen Klerus in Sturmwind, den Nachtelfen von Darnassus zusammen und sendet sogar Hilfe an neutrale Gruppen wie den Zirkel des Cenarius, wenn Leben gerettet werden müssen.",al={"rohans fraktion","ist rohan allianz","rohans loyalität"}},["90c6beb0"]={q="Was will Hohepriester Rohan?",a="Rohan widmet sich der Verbreitung der Tugenden des Heiligen Lichts und der Versorgung der Bedürftigen. Er versucht, Weisheit und Widerstandsfähigkeit bei jungen Priestern zu kultivieren, sich um die verarmten Bewohner von Eisenschmiede zu kümmern und überall dort Hilfe zu leisten, wo Leid unschuldige Leben in ganz Azeroth bedroht.",al={"was will rohan","rohans ziele","rohans motivationen"}},["88d280c0"]={q="Warum ist Hohepriester Rohan hier in der Hall of Mysteries?",a="Die Hall of Mysteries dient Eisenschmiede als Zufluchtsort für göttliche Studien und arkane Kontemplation. Rohan durchschreitet ihre heiligen Hallen, um das spirituelle Wohlbefinden der Stadt zu überwachen, sich um besuchte Bittsteller zu kümmern und angehende Priester persönlich zu unterweisen, bevor er sie in die weite Welt aussendet.",al={"warum ist rohan in eisenschmiede","warum ist rohan hier","rohan hall of mysteries"}}},fp="17,395,33.472.0,27.561.0,19.496.0,35.189.0,40.249.0,54.304.0,31.267.0,39.182.0,30.217.0"}
P.entries["npc:high-priestess-laurena"] = {fx={f0ff80a5={q="Auf wessen Seite steht Hohepriesterin Laurena?",a="Sie ist voll und ganz der Kirche des Heiligen Lichts und der Allianz ergeben. Stationiert in der Kathedrale des Lichts in Sturmwind, arbeitet sie daran, die Gläubigen des Königreichs zu betreuen, neue Priester auszubilden und die überlebenden Völker zu unterstützen, die vor der Verwüstung in ganz Azeroth Zuflucht gesucht haben.",al={"laurena loyalität","welcher fraktion gehört laurena an","wem dient laurena"}}}}
P.entries["npc:hogger"] = {n="Hogger",s="Hogger ist der bösartige Häuptling der Flusstatzen-Gnolle, die im südwestlichen Wald von Elwynn ihr Unwesen treiben. Er überragt seine Artgenossen bei Weitem, ist bemerkenswert aggressiv und berüchtigt dafür, einheimische Bauernhöfe zu überfallen und ahnungslose Reisende abzuschlachten. Seine gewalttätigen Streifzüge haben ihm ein offizielles Kopfgeld der Marschälle von Sturmwind eingebracht.",h="Hogger ist der bösartige Häuptling der Flusstatzen-Gnolle, die im südwestlichen Wald von Elwynn ihr Unwesen...",kw={"kopfgeld","defias","dughan","elwynn","gnoll","goldhain","hogger","flusstatzen"},ang={["faction:Alliance"]="Hoggers Überfälle zeigen, wie überlastet die Armee von Sturmwind ist, was die Marschälle dazu zwingt, sich auf umherziehende Abenteurer zu verlassen, um die Ordnung nahe der Hauptstadt aufrechtzuerhalten.",["race:Human"]="Für junge Verteidiger von Sturmwind ist die Konfrontation mit Hogger eine frühe Feuertaufe und eine direkte Antwort auf die Bedrohungen, die das Kernland von Elwynn destabilisieren."},sec={{t="Der Schrecken der Flusstatzen",b="Hogger lauert auf dem Hogger Hill im südwestlichen Wald von Elwynn und befehligt das dortige Rudel der Flusstatzen mit unübertroffener Grausamkeit. In den Jahren nach dem Dritten Krieg wurden die Raubzüge der Gnolle auf die örtlichen Gehöfte immer dreister und koordinierter. Hinter diesem Anstieg der Gewalt verbirgt sich ein beunruhigendes Bündnis: Die Flusstatzen haben begonnen, mit der Bruderschaft der Defias zu konspirieren, und tauschen rohe Wildheit gegen Waffen, taktische Führung und magische Unterstützung ein. Um die Grenzen von Elwynn zu sichern und die Handelswege vor weiterem Blutvergießen zu schützen, hat Marschall Dughan ein großzügiges Kopfgeld auf Hoggers Kopf ausgesetzt."}},faq={{q="Wer ist Hogger?",a="Hogger ist ein riesiger, außergewöhnlich gefährlicher Gnoll, der das Rudel der Flusstatzen im südwestlichen Wald von Elwynn anführt. Er ist bekannt für seine Überfälle auf nahegelegene Gehöfte und wird von den Behörden von Sturmwind wegen seiner brutalen Angriffe auf menschliche Siedlungen tot gesucht.",al={"hogger lore","wer ist hogger","anführer der flusstatzen"}},{q="Warum ist ein Kopfgeld auf Hogger ausgesetzt?",a="Marschall Dughan und die Wache von Sturmwind haben ein offizielles Kopfgeld auf Hogger ausgesetzt, da seine Überfälle auf ländliche Höfe und Reisende eskaliert sind. Jeder, der kühn genug ist, seinem Treiben ein Ende zu setzen, muss seine gewaltige Klaue als Beweis für die Tat nach Goldhain zurückbringen.",al={"gesucht hogger","warum hogger töten","hogger kopfgeld"}},{q="Arbeiten die Flusstatzen-Gnolle mit der Bruderschaft der Defias zusammen?",a="Ja. Die Bruderschaft der Defias konspiriert mit dem Rudel der Flusstatzen und versorgt die brutalen Gnolle mit besseren Waffen, taktischer Führung und mystischer Unterstützung, um Sturmwinds Kontrolle über die Region weiter zu schwächen.",al={"hogger defias","gnolle defias verbindung","flusstatzen defias"}},{q="Wo schlägt Hogger sein Lager auf?",a="Hogger haust auf dem Hogger Hill in den südwestlichen Ausläufern des Walds von Elwynn, umgeben von seinen treuen Flusstatzen-Rudelgefährten nahe der Grenze zu Westfall.",al={"hogger aufenthaltsort","wo ist hogger","hogger hill"}}},fx={cd1f1084={q="Auf wessen Seite steht Hogger?",a="Hogger führt die Riverpaw-Gnolle des südlichen Waldes von Elwynn an, aber sein Rudel handelt nicht allein. Sie verschwören sich mit The Defias Brotherhood und tauschen Chaos in den Wäldern gegen Waffen, taktische Führung und arkane Unterstützung. Während Gnolle hauptsächlich für Beute und Territorium kämpfen, stellt Hoggers Bündnis mit den Defias sein Rudel direkt gegen das Königreich Sturmwind und dessen Bevölkerung.",al={"hoggers seite","für wen arbeitet hogger","mit wem ist hogger verbündet"}},["3ddc17ac"]={q="Warum ist Hogger im Wald von Elwynn?",a="Hogger hat seine Festung auf einem Hügel im südwestlichen Wald von Elwynn errichtet, um die aggressive Expansion seines Rudels zu beaufsichtigen. Von diesem Lager aus überfallen die Riverpaw-Gnolle nahegelegene menschliche Farmen und Siedlungen und nutzen die überlasteten Verteidigungsanlagen des Königreichs aus, während sie sich unter dem Einfluss und der Unterstützung von The Defias Brotherhood koordinieren.",al={"warum ist hogger hier","grund für hogger im wald von elwynn","warum kam hogger hierher"}},d88533c5={q="Warum ist Hogger so gefürchtet?",a="Hogger ist im gesamten Wald von Elwynn für seine bösartige Stärke und seine gerissene Führung gefürchtet. Im Gegensatz zu gewöhnlichen umherstreifenden Gnollen ist er ein außergewöhnlich furchterregender Häuptling, der einsame Reisende und unerfahrene Abenteurer leicht überwältigt. Seine Überfälle auf lokale Gehöfte haben sich als so zerstörerisch erwiesen, dass die Marschälle von Sturmwind ihn als vorrangige Bedrohung für das Reich betrachten.",al={"warum ist hogger berühmt","warum ist hogger gefürchtet","warum ist hogger berüchtigt"}}},fp="6,312,22.569.0,14.234.0,32.237.0,60.218.0,32.149.0"}
P.entries["npc:holt-thunderhorn"] = {n="Holt Donnerhorn",s="Holt Donnerhorn ist ein Tauren-Jägerlehrer, der auf der Anhöhe der Jäger in der hochgelegenen Stadt Donnerfels stationiert ist. Er unterweist Anfänger und erfahrene Fährtenleser in ihrer Kunst, bietet grundlegende kriegerische Anleitungen und weist heranreifende Scharfschützen auf spezialisierte Prüfungen in Mulgore und darüber hinaus hin.",h="Holt Donnerhorn ist ein Tauren-Jägerlehrer, der auf der Anhöhe der Jäger in der hochgelegenen Stadt...",kw={"holt donnerhorn","die anhöhe der jäger","jägerlehrer","mulgore","donnerfels"},ang={["class:Hunter"]="Holt Donnerhorn dient als zentraler Mentor in Donnerfels und bietet Waffentechniken, Training im Fährtenlesen sowie Empfehlungen zur Tierzähhmung an.",["race:Tauren"]="Auf der Anhöhe der Jäger stationiert, verkörpert Holt die traditionelle Jagdkultur der Tauren, die die nomadischen Stämme lange bevor sie ein dauerhaftes Zuhause auf den Klippen errichteten, ernährte und beschützte."},sec={{t="Meister der Anhöhe",b="Auf der Anhöhe der Jäger hoch über den weiten Ebenen von Mulgore gelegen, dient Holt Donnerhorn der Horde als erfahrener Ausbilder in Fernkampf, Fährtenlesen und Überlebenskunst. Wie viele Älteste seines Handwerks führt er junge Tauren auf ihrem Weg vom umherziehenden Jäger hin zu disziplinierten Verteidigern ihrer neuen Hauptstadt."}},faq={{q="Wo kann Holt Donnerhorn gefunden werden?",a="Holt Donnerhorn steht auf der Anhöhe der Jäger, dem südöstlichen Hochplateau innerhalb der Taurenhauptstadt Donnerfels in Mulgore.",al={"holt donnerhorn standort","wo ist holt","jägerlehrer donnerfels"}},{q="Was lehrt Holt Donnerhorn?",a="Er ist ein Jägerlehrer, der Spielern grundlegende Treffsicherheit, Wildnisüberleben und Techniken zur Tierzähhmung beibringt sowie Neulinge an spezialisierte Tierherrschaftsprüfungen verweist.",al={"was lehrt holt","holt donnerhorn lehrer","welche fähigkeiten holt"}},{q="Welche Rolle spielen Jäger in Donnerfels?",a="Jäger bilden das traditionelle Rückgrat der Taurengesellschaft. Sie sorgen für Nahrung, patrouillieren an den territorialen Grenzen gegen Zentauren-Überfallkommandos und ehren die Erdenmutter durch ausgewogenes, ehrfürchtiges Fährtenlesen.",al={"zweck der anhöhe der jäger","tauren jäger lore"}}},fx={c3f17fe5={q="Wer ist Holt Donnerhorn?",a="Holt Donnerhorn ist ein angesehener Tauren-Jägerausbilder, der in Donnerfels auf Die Anhöhe der Jäger stationiert ist. Er widmet sich der Weitergabe der Wildniskünste der Shu'halo und unterweist junge Jäger in Treffsicherheit, Überlebenskunst und dem uralten Band zwischen Jäger und Tier.",al={"wer ist holt","holt donnerhorn lore","wer ist holt donnerhorn"}},d59405da={q="Auf wessen Seite steht Holt Donnerhorn?",a="Holt dient den Taurenstämmen von Donnerfels und der größeren Horde unter der Führung von Cairne Bluthuf. Er unterstützt jeden Jäger, der der Horde gegenüber loyal ist und danach strebt, seine Instinkte zu schärfen und die Ebenen zu ehren.",al={"holt donnerhorn fraktion","wem dient holt","ist holt bei der horde"}},["03eb281d"]={q="Warum ist Holt Donnerhorn hier?",a="Holt bleibt auf Die Anhöhe der Jäger, um neue Generationen von Spurenlesern, Schützen und Tierbändigern anzuleiten. Da die Tauren nun in Mulgore angesiedelt sind, sind geschickte Jäger unerlässlich, um die Stadt zu versorgen und die Plateaus vor feindseligen Wildtieren und Eindringlingen zu schützen.",al={"warum ist holt in donnerfels","was macht holt hier","holt donnerhorn zweck"}}},fp="16,288,18.313.0,36.128.0,33.187.0,43.209.0"}
P.entries["npc:houndmaster-loksey"] = {fx={["92e01b8b"]={q="Wer ist Hundemeister Loksey?",a="Hundemeister Loksey ist ein menschlicher Hauptmann und einer der vier Kommandanten, die sich im Das Scharlachrote Kloster aufhalten. Bekannt für seine brutale Disziplin, dient er als Zwingermeister, der für die Zucht, Konditionierung und das Hetzen der bösartigen Hunde des Kreuzzugs auf Eindringlinge und vermutete Träger der Untoten-Fäule verantwortlich ist.",al={"wer ist loksey","hundemeister loksey identität","wer ist hundemeister loksey"}},["6cbd929d"]={q="Auf wessen Seite steht Hundemeister Loksey?",a="Loksey ist dem The Scarlet Crusade unerschütterlich ergeben und dient als Frontkommandant in deren Klosterfestung. Er teilt den fanatischen Hass des Kreuzzugs auf die Untoten und jeden außerhalb ihres Zelotenordens und betrachtet jeden, der in ihre Hallen eindringt, als Eindringling, der nur dazu taugt, seinen Zwinger zu füttern.",al={"loksey fraktion","hundemeister loksey allianz","wem dient loksey"}},["1361b0af"]={q="Was will Hundemeister Loksey?",a="Loksey strebt danach, das Das Scharlachrote Kloster zu verteidigen, indem er rücksichtslose Jagdrudel ausbildet, die in der Lage sind, jeden Feind Glied für Glied zu zerreißen. Er möchte jede Spur der Untoten tilgen und das Territorium des Kreuzzugs vor Außenstehenden schützen, wobei er seine Bestien einsetzt, um Eindringlinge ohne Zögern oder Gnade zu jagen.",al={"lokseys ziel","was versucht loksey zu erreichen","hundemeister loksey beweggrund"}},["58572016"]={q="Warum ist Hundemeister Loksey hier?",a="Loksey ist im Library-Flügel des Klosters stationiert, um die Zwinger des Kreuzzugs zu beaufsichtigen. Als Hundemeister muss er sicherstellen, dass die Hunde scharf, aggressiv konditioniert und jederzeit bereit sind, losgelassen zu werden, um das Gelände zu patrouillieren und Eindringlinge abzuschlachten.",al={"warum ist loksey im kloster","warum ist hundemeister loksey hier","loksey zweck"}},["264719ea"]={q="Warum ist Hundemeister Loksey berühmt oder gefürchtet?",a="Loksey ist für sein Rudel abgerichteter Hunde gefürchtet, Bestien, die dafür bekannt sind, Opfer innerhalb von Minuten zu überwältigen und in Stücke zu reißen. Jeder, der sich in das Kloster wagt, fürchtet die Begegnung mit seinem Zwinger, da er weiß, dass Lokseys bösartiges Kommando seine Tiere in unerbittliche Maschinen des Gemetzels verwandelt.",al={"warum ist loksey gefürchtet","lokseys ruf","warum ist hundemeister loksey gefährlich"}}}}
P.entries["npc:huldar"] = {n="Huldar",s="Huldar ist ein Zwergenfuhrmann, der an der südlichen Straße von Loch Modan nahe dem Seeufer stationiert ist. Mit dem Transport von wichtigem Sprengpulver zur Ausgrabungsstätte im Süden beauftragt, sieht sich seine Lieferkarawane unerbittlichen Angriffen durch lokale Bedrohungen und Dunkeleisensaboteure ausgesetzt.",h="Huldar ist ein Zwergenfuhrmann, der an der südlichen Straße von Loch Modan nahe dem Seeufer stationiert ist.",kw={"sprengpulver","karawane","dunkeleisen","ausgrabung","huldar","loch modan","wagen"},ang={["profession:Engineering"]="Jeder Ingenieur kennt den Wert – und die Flüchtigkeit – von rohem Sprengpulver, das ungeschützt in gestrandeten Holzfässern lagert.",["race:Dwarf"]="Huldar zu helfen unterstützt direkt die Ausgrabungsstätte der Explorer's League und stellt sicher, dass Eure Verwandten das nötige Pulver haben, um uralte Geheimnisse der Titanen ans Licht zu bringen."},sec={{t="Ein Sprengstofftransport in Gefahr",b="Der Transport von Sprengstoff durch Loch Modan ist keine einfache Handelsroute. Huldar wurde damit beauftragt, Wagenladungen voller Bergbausprengpulver nach Süden zur Ausgrabungsstätte zu fahren, wo Zwergenarchäologen und Prospektoren dringend Nachschub benötigen. Allerdings sind die Straßen durch die Wildnis zunehmend gefährlicher geworden. Da einheimische Wildtiere, Troggs und Dunkeleiseninfiltratoren in der Nähe der südlichen Biegung des Sees lauern, sitzt Huldar bei seinem beschädigten Wagen fest und ist auf umherreisende Wanderer angewiesen, um die verbliebenen Pulverfässer zu sichern und dafür zu sorgen, dass die Lieferung die Grabungsstätte erreicht."}},faq={{q="Wer ist Huldar?",a="Huldar ist ein Zwergenfuhrmann, der an seinem Wagen am Südufer des Sees in Loch Modan festsitzt. Er hatte den Auftrag, Sprengpulver zur nahegelegenen Ausgrabungsstätte zu transportieren, bevor sein Versorgungszug in Schwierigkeiten geriet.",al={"wer ist huldar","huldar loch modan","wagen zwerg"}},{q="Was befindet sich in Huldars Wagen?",a="Sein Wagen transportiert Fässer voller Sprengpulver. Die Sprengstoffe werden von Zwergenprospektoren und Archäologen, die an der Ausgrabungsstätte im Süden arbeiten, dringend benötigt.",al={"was transportiert huldar","huldar wagenladung","was sind die fässer"}},{q="Warum sitzt Huldar auf der Straße fest?",a="Die Straßen durch das südliche Loch Modan sind aufgrund feindseliger Bestien, Troggs und Dunkeleisenzwergsaboteuren gefährlich geworden. Huldars Lieferung geriet in einen Hinterhalt, was ihn dazu zwang anzuhalten und Hilfe zu suchen, um die verbliebenen Vorräte zu sichern und abzuliefern.",al={"warum sitzt huldar fest","huldar hinterhalt"}},{q="Warum interessiert sich die Dunkeleisenzwerge für seine Fracht?",a="Der Dunkeleisenklan versucht aktiv, die Präsenz und die historischen Forschungen von Eisenschmiede in ganz Loch Modan zu untergraben. Das Abschneiden der Sprengpulverversorgung stoppt die Ausgrabungsarbeiten und entzieht zwergischen Operationen defensive und industrielle Ressourcen.",al={"dunkeleisen sprengpulver","warum dunkeleisen huldar angreifen"}}},fx={ff7033f4={q="Auf wessen Seite steht Huldar?",a="Huldar ist loyal gegenüber Eisenschmiede und der Allianz. Er arbeitet direkt im Dienst der Zwergenprospektoren und Bergleute, die in Loch Modan tätig sind, transportiert lebenswichtige Munition durch das Gebiet und behauptet sich dabei gegen den feindseligen Dunkeleisen-Clan, der in die Region eindringt.",al={"ist huldar bei der allianz","wem dient huldar","huldar fraktion"}},["9f03f8e3"]={q="Was will Huldar?",a="Huldar möchte seine Lieferung von Sprengpulver sicher zur Ausgrabungsstätte der Zwerge bringen. Dunkeleisenzwerge haben seinen Karawanenzug entlang der südlichen Straße des Lochs überfallen, was ihn dazu zwingt, standhafte Reisende zu suchen, die die Fracht beschützen und die Saboteure zurückschlagen.",al={"was versucht huldar zu erreichen","huldar ziel","was braucht huldar"}},["577cb64e"]={q="Mit wem ist Huldar verbunden?",a="Huldar ist mit den Zwergenausgräbern verbunden, die in Loch Modan stationiert sind. Sein Team hat die Aufgabe, lebenswichtige Vorräte und Sprengpulver direkt zu ihren Ausgrabungsstätten zu transportieren und sicherzustellen, dass ihre Operationen trotz der wachsenden Bedrohung durch Dunkeleisen-Überfälle fortgesetzt werden können.",al={"für wen arbeitet huldar","huldar verbindungen","wen beliefert huldar"}}},fp="6,268,21.566.0,14.208.0,26.167.0,32.232.0,50.234.0"}
P.entries["npc:illiyana"] = {n="Illiyana",s="Illiyana ist eine uralte Dryade, die im südwestlichen Eschental stationiert ist und sich dem Schutz des Waldlands vor uralter Verderbnis widmet. Sie streift nahe dem Schrein von Aessina umher und versammelt Streiter der Allianz, um die bösartigen Satyrn zurückzudrängen, die die uralten Haine heimsuchen. Ihre Wachsamkeit steht für das dauerhafte Bündnis zwischen den Töchtern des Cenarius und der Wildnis der Nachtelfen.",h="Illiyana ist eine uralte Dryade, die im südwestlichen Eschental stationiert ist und sich dem Schutz des...",kw={"eschental","zweig des cenarius","cenarius","dryade","illiyana","satyr","der schrein von aessina"},ang={["class:Druid"]="Druiden schätzen Dryaden als Verkörperungen der Wildnis hoch ein, und Illiyana bei der Bewahrung der geheiligten Lichtungen zu helfen, entspricht direkt der Pflicht des Cenarius, das Land zu heilen.",["faction:Alliance"]="Illiyana stellt eine wichtige Verbündete des Waldlands im südwestlichen Eschental dar und bietet den Streitkräften der Allianz, die die Wildnis gegen das vordringende Unheil sichern, Zuflucht und Führung.",["race:NightElf"]="Für die Kaldorei sind Dryaden wie Illiyana heilige Verwandte des Cenarius – verehrte Beschützerinnen, deren Ruf zu den Waffen gegen dämonische Satyrn ohne Zögern gefolgt wird."},sec={{t="Tochter des Waldes",b="Wie alle Dryaden ist Illiyana eine der Töchter des Halbgottes Cenarius. Friedfertig und doch grimmig darauf bedacht, die wilden Länder zu beschützen, durchstreift sie die Wälder des südwestlichen Eschentals. Während sich finstere Mächte regen und die Waldlande unter schleichender Verderbnis leiden, wacht Illiyana über heilige Relikte sowie Haine und dient als Hüterin der ursprünglichen Unantastbarkeit der Natur."},{t="Die Bedrohung durch die Satyrn",b="Illiyanas Hauptanliegen in der Region ist die anhaltende Plage der Satyrn. Diese verzerrten, dämonischen Kreaturen trachten unablässig danach, die Lichtungen zu verderben und ihre Dryadenschwestern zu gefährden. Illiyana verpflichtet regelmäßig vorbeiziehende Reisende, um diese abscheulichen Missgeburten niederzustrecken und verlorene Artefakte, darunter die Zweig des Cenarius, zu bergen, damit die Wälder vor dämonischer Befleckung geschützt bleiben."}},faq={{q="Wer ist Illiyana?",a="Illiyana ist eine Dryade, die das südwestliche Eschental nahe dem Schrein von Aessina durchstreift. Als Tochter des Cenarius widmet sie ihr Dasein dem Wachen über das wilde Land und dem Schutz ihrer Schwestern vor dämonischen Kräften.",al={"wer ist diese dryade","illiyana eschental","was ist illiyana"}},{q="Warum läuft Illiyana weiter, während ich mit ihr spreche?",a="Illiyana behält eine aktive Patrouillenroute durch das Waldland bei. Anders als stationäre Questgeber setzt sie ihr wachsames Schreiten durch den Hain selbst dann fort, wenn sie Gespräche mit Reisenden führt.",al={"illiyana bewegt sich","warum geht sie weg","illiyana quest laufen"}},{q="Welche Aufgaben bietet Illiyana an?",a="Sie ruft Abenteurer dazu auf, bösartige Satyrn zu jagen, die die Region bedrohen, und heilige Relikte wie die Zweig des Cenarius zu bergen, um ihre Mitschwestern unter den Dryaden zu schützen.",al={"illiyana quests","forest song quests"}},{q="Wo befindet sich Illiyana?",a="Sie patrouilliert nahe dem Schrein von Aessina im südwestlichen Eschental und hält entlang der Pfade und nahegelegenen Haine Wache.",al={"illiyana standort","wo man illiyana findet","forest song dryade standort"}},{q="Warum sind die Dryaden durch die Satyrn in Gefahr?",a="Satyrn sind uralte Nachtelfen, die durch dämonische Verderbnis entstellt wurden und Freude daran finden, die Natur zu schänden und die Kinder des Cenarius zu unterjochen. Dryaden verkörpern die reine, unberührte Schönheit des Waldes, was sie zu vorrangigen Zielen für die Bosheit der Satyrn macht.",al={"warum hassen satyrn dryaden","dryaden und satyrn lore"}},{q="Hilft Illiyana der Horde?",a="Nein. Illiyana ist mit den Nachtelfen und der weiteren Allianz verbündet. Mitglieder der Horde, die sich in ihre Lichtung wagen, werden sie und ihre Verbündeten als feindselig vorfinden.",al={"ist illiyana der horde feindlich gesinnt","kann horde mit illiyana sprechen"}}},fx={f493742a={q="Was will Illiyana?",a="Illiyana widmet sich dem Schutz des Eschental und ihrer Mit-Dryaden vor dem korrumpierenden Einfluss der Satyrn. Sie sucht nach tapferen Champions der Allianz, um die bösen Satyrn in der Nähe zu jagen, die heiligen Haine zu verteidigen und dabei zu helfen, The Branch of Cenarius zurückzugewinnen, um den Wald zu reinigen.",al={"illiyana ziel","was will illiyana","illiyana zweck"}},["925d87c3"]={q="Warum ist Illiyana am Schrein von Aessina?",a="Illiyana wacht über den Schrein von Aessina im südwestlichen Eschental, einem Zufluchtsort, der den Waldgeistern und den Töchtern des Cenarius am Herzen liegt. Von diesem heiligen Boden aus überwacht sie die um sich greifende Verderbnis der Satyrn und koordiniert Verteidigungsmaßnahmen mit Nachtelfen und Verbündeten der Allianz.",al={"warum ist illiyana hier","illiyana schrein von aessina","warum ist illiyana im eschental"}},abbc4abe={q="Mit wem ist Illiyana verbunden?",a="Als Dryade ist Illiyana eine der Töchter des Halbgottes Cenarius und teilt eine tiefe spirituelle und familiäre Verwandtschaft mit ihren Dryadenschwestern, wie Shael'dryn, und den Hütern des Hains. Sie teilt auch starke Bande mit den Nachtelfen, die Aessina und Cenarius verehren.",al={"illiyana verbindungen","illiyana cenarius","mit wem ist illiyana verwandt"}}},fp="8,384,22.345.0,23.388.0,16.218.0,51.198.0,31.163.0,26.114.0,41.230.0,29.146.0"}
P.entries["npc:ilthalaine"] = {n="Ilthalaine",s="Ilthalaine ist ein Wächter der Nachtelfen, der über die heilige Lichtung des Laubschattentals auf Teldrassil wacht. Er dient als erster Begrüßer und Mentor für junge Nachtelfen, die ihre allerersten Schritte in die Welt wagen. Wachsam und mit der Wildnis verbunden, leitet er unerfahrene Abenteurer an, das empfindliche Gleichgewicht der Natur in den Ästen des Weltenbaums zu wahren.",h="Ilthalaine ist ein Wächter der Nachtelfen, der über die heilige Lichtung des Laubschattentals auf Teldrassil...",kw={"aldrassil","das gleichgewicht der natur","ilthalaine","kaldorei","questgeber","laubschattental","siegel","teldrassil"},ang={["class:Druid"]="Für angehende Druiden bieten Ilthalaines Lehren über Bestandsregulierung und natürliches Gleichgewicht ihre allerersten praktischen Lektionen in Cenarion-Prinzipien.",["faction:Alliance"]="Er verkörpert die ruhige, beständige Wachsamkeit der Kaldorei und heißt neue Streiter im Dienst von Darnassus und der weiteren Allianz willkommen.",["race:NightElf"]="Ilthalaine ist der erste Mentor, dem jeder junge Nachtelf begegnet, und vermittelt grundlegende Weisheiten über die Bewahrung und das heilige Gleichgewicht ihrer neu gefundenen Heimat auf Teldrassil."},sec={{t="Wächter des Tals",b="Direkt vor dem Herzen des Laubschattentals positioniert, ist Ilthalaine oft das erste Gesicht, das ein angehender Nachtelf zu Beginn seiner Reise sieht. Er beobachtet die Waldpfade und bemerkt die feinen Veränderungen im Wald, die gewöhnlichen Augen verborgen bleiben. Seine Pflicht ist es, zurückkehrende Verwandte willkommen zu heißen und sicherzustellen, dass neu erwachte Verteidiger in den Traditionen ihres Volkes verwurzelt sind, bereit, sich den Pflichten zu stellen, die mit der Pflege von Teldrassil einhergehen."},{t="Das Gleichgewicht der Natur",b="Starke Frühlingsregenfälle haben dazu geführt, dass die Populationen der Nachtsäbler und Disteleber im Laubschattental über das hinaus gewachsen sind, was die Lichtung ernähren kann. Ilthalaine bittet junge Verteidiger, ihre Zahl zu verringern, damit die anderen Kreaturen des Waldes gedeihen können und das Gleichgewicht der Natur bewahrt wird."},{t="Ein Wegweiser zur Disziplin",b="Über die Erprobung des kriegerischen Könnens eines Abenteurers gegen die einheimische Tierwelt hinaus weist Ilthalaine junge Elfen ihren gewählten Berufungen zu. Indem er jedem Reisenden ein Klassensiegel anvertraut, weist er ihnen den direkten Weg zu ihren Mentoren im Sanktum von Aldrassil – ganz gleich, ob sie dem Pfad des Kriegers, Druiden, Schurken, Priesters oder Jägers folgen. Durch ihn erfährt jeder Novize, wo sein Dienst für die Kaldorei beginnt."}},faq={{q="Wer ist Ilthalaine?",a="Ilthalaine ist ein Aufseher der Kaldorei im Laubschattental, der geschützten Anfangslaube von Teldrassil. Er dient als erster Questgeber für neu erstellte Nachtelfenabenteurer und führt sie in ihre Pflichten sowie den Zustand des Waldes ein.",al={"ilthalaine lore","wer ist dieser nachtelf","laubschattental questgeber"}},{q="Welche Rolle spielt Ilthalaine im Laubschattental?",a="Er wacht über die Tierwelt im Laubschattental und sorgt dafür, dass neue Nachtelfen die Bedeutung des Gleichgewichts der Natur verstehen. Er schickt junge Initianden auf einfache Jagden und weist ihnen den Weg zu ihren jeweiligen Klassenlehrern im großen Baum Aldrassil.",al={"was macht ilthalaine","warum ist er hier","ilthalaine zweck"}},{q="Warum möchte Ilthalaine, dass die jungen Nachtsäbler und Eber dezimiert werden?",a="Starke Frühlingsregenfälle haben die Populationen der Nachtsäbler und Disteleber über das Maß hinaus anwachsen lassen, das das Laubschattental ernähren kann. Ilthalaine bittet um eine Dezimierung, um das Gleichgewicht der Natur zu bewahren.",al={"das gleichgewicht der natur quest","warum nachtsäbler töten","warum eber töten"}},{q="Was sind die Siegel, die er verteilt?",a="Ilthalaine gibt Novizen klassenspezifische beschriftete Siegel und weist sie an, ihre Ausbilder – wie etwa Priesterinnen, Druiden, Krieger und Schurken – aufzusuchen, die in den Wurzeln von Aldrassil Schutz finden.",al={"geätztes siegelzeichen","einfaches siegelzeichen","tiefgrünes siegelzeichen","verschlüsseltes siegelzeichen","geheiligtes siegelzeichen"}},{q="Wo ist Ilthalaine zu finden?",a="Er steht direkt auf dem zentralen Pfad des Laubschattentals, südlich des gewaltigen hohlen Astes von Aldrassil auf Teldrassil.",al={"ilthalaine standort","wo ist ilthalaine","ilthalaine koordinaten"}},{q="Ist Ilthalaine mit den Druiden oder den Sentinels verbunden?",a="Ilthalaine fungiert als allgemeiner Pfleger und Vertreter der Kaldorei im Laubschattental. Obwohl er tief mit der Natur und dem druidischen Ethos der Harmonie verbunden ist, arbeitet er im Auftrag der gesamten Führung von Darnassus, um Novizen aller Disziplinen anzuleiten.",al={"ist er ein druide","welche fraktion ist ilthalaine"}}},fx={e95b9493={q="Warum ist Ilthalaine im Laubschattental?",a="Ilthalaine hält im Laubschattental Wache, um neue Nachtelfen-Verteidiger zu begrüßen und das empfindliche Gleichgewicht von Teldrassils heiliger Baumschule zu bewahren. Während die lokale Tierwelt unruhig wird und Anzeichen von Verderbnis in die Zweige sickern, bleibt er in der Nähe von Aldrassil stationiert, um Neuankömmlinge anzuleiten und erste Bemühungen zur Heilung und zum Schutz des Großen Baums zu steuern.",al={"warum ist ilthalaine hier","ilthalaine laubschattental zweck","warum ist ilthalaine in teldrassil"}}},fp="10,368,20.455.0,21.274.0,21.405.0,18.238.0,40.249.0,64.170.0,33.199.0,30.117.0,58.239.0"}
P.entries["npc:innkeeper-allison"] = {n="Gastwirtin Allison",s="Gastwirtin Allison leitet die Gilded Rose, eines der belebtesten und zentralsten Gasthäuser in Sturmwind. Im Herzen des Handelsdistrikts direkt zwischen der Bank und dem Auktionshaus gelegen, versorgt sie erschöpfte Reisende und einheimische Händler mit Ruhesteinbindungen, erfrischenden Getränken und einer Unterkunft.",h="Gastwirtin Allison leitet die Gilded Rose, eines der belebtesten und zentralsten Gasthäuser in Sturmwind.",kw={"allison","gilded rose","ruhestein","gastwirtin allison","sturmwind","der handelsdistrikt"},ang={["faction:Alliance"]="Als Inhaberin des am leichtesten erreichbaren Gasthauses im Handelszentrum von Sturmwind ist Allison eines der vertrautesten Gesichter für Champions der Allianz, die von Kampagnen an vorderster Front zurückkehren, um sich auszuruhen und ihre Beute auf die Bank zu bringen."},sec={{t="Gastfreundschaft im Handelsdistrikt",b="Genau zwischen dem geschäftigen Auktionshaus und den Tresorgewölben der Stadt gelegen, dient die Gilded Rose als Epizentrum für in Sturmwind eintreffende Abenteurer. Gastwirtin Allison steht hinter dem Haupttresen im Erdgeschoss und sorgt inmitten eines stetigen Stroms von Hausierern, Söldnern und gastierenden Diplomaten für Ordnung. Neben Unterkünften und Ruhesteindiensten nimmt sie regelmäßig an lokalen Feiertagsfeierlichkeiten teil und koordiniert kleine Besorgungen für reisende Helden, die in der Hauptstadt Erholung suchen."}},faq={{q="Wo kann ich Gastwirtin Allison finden?",a="Gastwirtin Allison steht hinter dem Tresen im Erdgeschoss der Gilded Rose. Das Gasthaus befindet sich direkt im Handelsdistrikt von Sturmwind, zwischen der Zentralbank und dem Auktionshaus.",al={"allison standort","wo ist gastwirtin allison","gilded rose gastwirt"}},{q="Welche Dienste bietet Gastwirtin Allison an?",a="Sie bietet die typischen Dienste einer Gastwirtin: Spieler können ihren Ruhestein an die Gilded Rose binden, Speisen und Getränke zur Erholung kaufen und im Rahmen stadtweiter saisonaler Events und Feiertage mit ihr interagieren.",al={"was macht allison","allison dienste","kann man hier ruhestein binden"}},{q="Bietet Gastwirtin Allison Quests an?",a="Ja, Allison nimmt das ganze Jahr über an verschiedenen saisonalen Feierlichkeiten wie Feiertagsevents teil und kann gelegentlich in städtische Botengänge für Reisende verwickelt sein, die Hilfe im Reich suchen.",al={"allison quests","gastwirtin allison quest"}}},fx={["681a398f"]={q="Wer ist Gastwirtin Allison?",a="Allison ist die Inhaberin und Gastwirtin der \"Gilded Rose\", einem der bekanntesten Ruheplätze in Sturmwind. Sie arbeitet direkt im Herzen des geschäftigen Handelsdistrikts und heißt erschöpfte Abenteurer, Händler und Reisende willkommen, die inmitten der überfüllten Hauptstadt nach Ruhe und Komfort suchen.",al={"wer ist allison","gastwirtin allison hintergrundwissen","wer ist gastwirtin allison"}},["4fce5435"]={q="Auf wessen Seite steht Gastwirtin Allison?",a="Allison ist eine treue Untertanin des Königreichs Sturmwind und der Allianz ergeben. Ihr Gasthaus dient als sicherer Hafen und Heimatbasis für Champions der Allianz und Bürger, die durch die Stadt reisen.",al={"gastwirtin allison fraktion","ist allison allianz","wem dient gastwirtin allison"}},["3063ebee"]={q="Warum ist Gastwirtin Allison hier?",a="Allison leitet die \"Gilded Rose\", die direkt zwischen Stürmwinds belebter Bank und dem Auktionshaus liegt. Sie bleibt an ihrem Posten im Erdgeschoss, um Zimmer anzubieten, Ruhesteine zu binden und sich um den endlosen Strom von Reisenden zu kümmern, die im Distrikt Handel treiben und Geschäfte abwickeln.",al={"warum ist gastwirtin allison im handelsdistrikt","gastwirtin allison zweck hier","warum ist allison hier"}},["735a1673"]={q="Was will Gastwirtin Allison?",a="Allison will nichts weiter, als ein erfolgreiches, gastfreundliches Etablissement zu führen und den reibungslosen Betrieb der \"Gilded Rose\" sicherzustellen. Neben der Betreuung ihrer täglichen Gäste nimmt sie gerne an städtischen Festivitäten und saisonalen Feierlichkeiten in der ganzen Hauptstadt teil.",al={"gastwirtin allison beweggründe","was will allison","was sind die ziele von gastwirtin allison"}}},fp="17,295,33.512.0,35.204.0,43.210.0,40.201.0"}
P.entries["npc:innkeeper-firebrew"] = {n="Gastwirt Feuerbräu",s="Gastwirt Feuerbräu leitet die Stonefire Tavern im belebten Handelsdistrikt von Eisenschmiede. Als freundlicher Gastgeber für müde Bergsteiger wie auch für hochrangige Besucher serviert er herzhafte Zwergenspezialitäten und sorgt dafür, dass Reisende unter dem Berg ausgeruht bleiben.",h="Gastwirt Feuerbräu leitet die Stonefire Tavern im belebten Handelsdistrikt von Eisenschmiede.",kw={"handelsdistrikt","zwerg","firebrew","ruhestein","gastwirt","eisenschmiede","stonefire tavern"},ang={["faction:Alliance"]="Als primärer Gastwirt in der Nähe der Vordertore bietet Firebrew fremden Reisenden der Allianz einen zentralen, sicheren Zufluchtsort zum Ausruhen, wenn sie die Hauptstadt von König Magni Bronzebart besuchen.",["race:Dwarf"]="Für Zwerge, die von Patrouillen durch Khaz Modan zurückkehren, bietet Firebrews Taverne die behagliche Wärme von zu Hause und einen verlässlichen Krug Zwergenstout."},sec={{t="Hüter der Stonefire",b="Die Einrichtung von Gastwirt Feuerbräu befindet sich im zentralen Ring des Handelsdistrikts und ist oft der erste Zufluchtsort, den Reisende finden, wenn sie durch die Tore von Eisenschmiede eintreten. Hinter einem Tresen, der mit Bierkrügen, Stout-Schläuchen und gebratenen Fleischstücken beladen ist, bietet Firebrew Abenteurern Gastfreundschaft, die auf dem Weg zu den schneebedeckten Pässen von Dun Morogh oder tiefer in das Bergkönigreich sind. Seine Taverne bleibt ein lebhafter Knotenpunkt, an dem Bergleute, Schützen und Abgesandte zusammenkommen, um den zugigen Tunneln zu entfliehen und am Kamin Geschichten auszutauschen."}},faq={{q="Wo finde ich Gastwirt Feuerbräu?",a="Gastwirt Feuerbräu befindet sich in der Stonefire Tavern, die am südlichen Rand des Handelsdistrikts in Eisenschmiede liegt.",al={"standort firebrew","wo ist gastwirt firebrew","tavernenwirt eisenschmiede"}},{q="Welche Waren verkauft Firebrew?",a="Er bietet die üblichen Vorräte eines Gastwirts an, wobei er sich auf deftige Zwergenrationen spezialisiert hat. Reisende können Getränke erwerben, die von lokalem Dwarven Stout und Met bis hin zu importierten Weinen reichen, sowie Fleisch und herzhafte Mahlzeiten, die für lange Reisen geeignet sind.",al={"was verkauft firebrew","getränke bei firebrew","essen in der stonefire tavern"}},{q="Gehört Firebrew zu einer Zwergenbrauerfamilie?",a="Er trägt den Nachnamen Firebrew, aber seine familiären Beziehungen sind nicht bestätigt.",al={"familie firebrew","mit wem ist firebrew verwandt"}},{q="Welche Dienste bietet er Reisenden an?",a="Als Tavernenwirt ermöglicht Firebrew Reisenden der Allianz, ihren Ruhestein an die Stonefire Tavern zu binden, und bietet ein warmes Bett, um sich unter dem Berg auszuruhen und zu erholen.",al={"kann ich hier meinen ruhestein binden","ruhestein gasthaus eisenschmiede"}}},fx={["9fc434fc"]={q="Wer ist Gastwirt Feuerbräu?",a="Gastwirt Feuerbräu ist der zwergische Inhaber der Stonefire Tavern, die sich in den belebten Gemeinen von Eisenschmiede befindet. Als gastfreundliche Figur innerhalb der Bergstadt hütet er das Feuer, schenkt Bier aus und bietet Einheimischen sowie müden Reisenden gleichermaßen Nahrung und Unterkunft.",al={"wer ist feuerbräu","gastwirt feuerbräu","gastwirt der stonefire tavern"}},["3dd110f9"]={q="Auf wessen Seite steht Gastwirt Feuerbräu?",a="Feuerbräu ist dem Königreich Eisenschmiede gegenüber loyal und steht fest auf der Seite der Allianz. Er hält sein Gasthaus für alle verbündeten Abenteurer offen, die Zuflucht vor den kalten Winden von Dun Morogh suchen oder sich nach langen Reisen durch Azeroth ausruhen möchten.",al={"feuerbräu fraktion","feuerbräu allianz","ist feuerbräu allianz"}},e30bdb86={q="Was will Gastwirt Feuerbräu?",a="Feuerbräu konzentriert sich darauf, ein lebhaftes und gastfreundliches Gasthaus zu führen. Er möchte den Herd der Stonefire Tavern zum Brennen bringen, die Krüge der Gäste mit starkem zwergischem Bier füllen und sicherstellen, dass Besucher der großen Schmiedestadt einen warmen Ort zum Ausruhen und Binden ihrer Ruhesteine haben.",al={"was will feuerbräu","feuerbräu beweggründe","feuerbräu ziele"}},b21a7171={q="Warum ist Gastwirt Feuerbräu hier?",a="Feuerbräu leitet die Stonefire Tavern in den Gemeinen, was ihn zum zentralen Gastgeber für Reisende macht, die in das Herz von Eisenschmiede kommen. Er bleibt direkt am Herd, um Unterkunft anzubieten, Vorräte und Getränke zu verkaufen und einen einladenden Ankerpunkt für Abenteurer zu bieten, die in der Hauptstadt eintreffen.",al={"warum ist feuerbräu in eisenschmiede","warum ist feuerbräu in der stonefire tavern"}}},fp="18,235,23.540.0,36.117.0,38.230.0,47.78.0,43.178.0"}
P.entries["npc:innkeeper-grosk"] = {n="Gastwirt Grosk",s="Gastwirt Grosk leitet das Gasthaus in Klingenhügel und versorgt müde Reisende im zentralen Durotar mit Speis, Trank und einem Ort zum Ausruhen. An der belebten Straße zwischen dem Tal der Prüfungen und Orgrimmar gelegen, dient seine Gaststätte als wichtigster Rastplatz für junge Abenteurer der Horde, die in die weite Welt aufbrechen.",h="Gastwirt Grosk leitet das Gasthaus in Klingenhügel und versorgt müde Reisende im zentralen Durotar mit Speis...",kw={"durotar","grosk","gastwirt","gastwirt grosk","orgrimmar","peon's burden","klingenhügel"},ang={["faction:Horde"]="Für frischgebackene Orcs, Trolle und zu Besuch weilende Tauren, die aus dem Tal der Prüfungen oder von Sen'jin nach Norden reisen, markiert Grosks Gasthaus die erste richtige Siedlung und den ersten Heimatort auf dem Weg nach Orgrimmar."},sec={{t="Gastfreundschaft in den roten Einöden",b="Klingenhügel dient als lebenswichtige Kreuzungssiedlung, die die südlichen Übungsplätze von Durotar mit den hohen Mauern von Orgrimmar verbindet. Im Zentrum dieser Raststation steht Gastwirt Grosk, ein Orc, dessen Aufgabe es ist, Kriegern, Spähern und Kumpeln gleichermaßen Zuflucht zu gewähren. Sein Gasthaus bietet Erholung von der unbarmherzigen Wüstenhitze und ist für jeden Reisenden, der unter sein stabiles Gebälk tritt, mit einfachen Vorräten, herzhaftem Fleisch und kühlem Wasser ausgestattet."},{t="Die Erholung eines Kumpels",b="Neben der Bewirtung durchreisender Abenteurer unterstützt Grosk die lokalen Arbeitskräfte, die Durotar am Laufen halten. In der Quest 'A Peon's Burden' bittet der ängstliche Kumpel Ukor, der Nahrungsmittel den weiten Weg bis in das Tal der Prüfungen geschleppt hat, nur um festzustellen, dass sie nicht gebraucht werden, Reisende darum, die Last zurück zu Grosks Gasthaus in Klingenhügel zu tragen."}},faq={{q="Wo befindet sich Gastwirt Grosk?",a="Gastwirt Grosk steht im Gasthaus von Klingenhügel, genau im Zentrum von Durotar an der Hauptstraße, die nach Norden in Richtung Orgrimmar führt.",al={"gastwirt grosk standort","wo ist grosk","klingenhügel gastwirt"}},{q="Welche Dienste bietet Gastwirt Grosk an?",a="Grosk fungiert als Gastwirt, bei dem Abenteurer der Horde ihren Ruhestein an Klingenhügel binden können. Er verkauft zudem einfache Nahrungsmittel, Wasser und Fleisch, um Gesundheit und Mana zwischen den Reisen wieder aufzufüllen.",al={"was macht grosk","grosk händler","kann ich ruhestein an klingenhügel binden"}},{q="Bietet Gastwirt Grosk Quests an?",a="Er ist an der Quest 'A Peon's Burden' beteiligt und nimmt die Ladung Nahrung entgegen, vor deren Rücktransport nach Klingenhügel der Kumpel Ukor aus Furcht vor den Bestien Durotars zu große Angst hatte.",al={"gastwirt grosk quests","a peons burden abgabe"}}},fx={["490d29ee"]={q="Wer ist Gastwirt Grosk?",a="Gastwirt Grosk ist der Orc, der die Taverne in Klingenhügel betreibt. Da Reisende, Grunzer und wandernde Abenteurer auf ihrem Weg von oder nach Orgrimmar durch Durotar ziehen, bietet Grosk ihnen Unterkunft, Proviant und einen Herd, um ihre müden Knochen auszuruhen.",al={"wer ist grosk","gastwirt grosk","wer ist gastwirt grosk"}},["10a7c15b"]={q="Auf wessen Seite steht Gastwirt Grosk?",a="Grosk ist ein standhaftes Mitglied der Horde und heißt Orcs, Trolle, Tauren und Verlassene in seinem Etablissement willkommen. Er stellt sicher, dass diejenigen, die für das neue Reich von Kriegshäuptling Thrall kämpfen, einen verlässlichen Stützpunkt für Ruhe und Nachschub in Durotar haben.",al={"ist grosk horde","gastwirt grosk zugehörigkeit","gastwirt grosk fraktion"}},["29305f72"]={q="Was will Gastwirt Grosk?",a="Grosk will, dass seine Gaststätte reibungslos läuft, während er Reisende auf den trockenen Ebenen von Durotar versorgt. Er handelt mit herzhaftem Essen und Trinken, bindet wandernde Abenteurer an seinen Ruhestein und kümmert sich gelegentlich um die Bedürfnisse der Arbeiter und Wachen der Stadt.",al={"was will grosk","grosk motiv","gastwirt grosk ziele"}},["7fe37467"]={q="Warum ist Gastwirt Grosk in Klingenhügel?",a="Klingenhügel dient als wichtigster Knotenpunkt und Garnisonsstadt zwischen dem Tal der Prüfungen, Sen'jin und der Hauptstadt Orgrimmar. Grosk errichtete seine Taverne hier, um am pulsierenden Herzen des Grenzerlebens in Durotar lebensnotwendige Unterkunft und Vorräte bereitzustellen.",al={"warum ist grosk hier","warum klingenhügel gastwirt","grosk klingenhügel rolle"}}},fp="15,319,29.423.0,16.302.0,33.147.0,43.180.0,38.168.0"}
P.entries["npc:innkeeper-gryshka"] = {n="Gastwirtin Gryshka",s="Gastwirtin Gryshka ist eine orcische Gastgeberin, die das Gasthaus Broken Tusk im Tal der Stärke von Orgrimmar leitet. Als erste Anlaufstelle für Reisende, die durch die Stadttore eintreffen, bietet sie anreisenden Abenteurern der Horde Ruhesteinbindungen, Speisen und Getränke an. Sie pflegt enge Beziehungen zu Jägern und Spähern in Durotar und dem Brachland, um ihre Taverne stets mit erlesenen Fleischstücken zu versorgen.",h="Gastwirtin Gryshka ist eine orcische Gastgeberin, die das Gasthaus Broken Tusk im Tal der Stärke von...",kw={"broken tusk","doras","gryshka","ruhestein","gastwirt","orgrimmar","tal der stärke","zargh"},ang={["faction:Horde"]="Für jeden Reisenden der Horde, der in Durotar eintrifft, ist Gryshkas Gasthaus im Tal der Stärke oft der wichtigste Knotenpunkt, um den Ruhestein zu binden und Vorräte aufzustocken, bevor die Reise tiefer nach Kalimdor führt.",["profession:Cooking"]="Köche werden Gryshkas anspruchsvollen Gaumen zu schätzen wissen, da sie keine Mühen scheut, erstklassige Fleischstücke von Jägern zu beschaffen, die bis ins Brachland hinaus stationiert sind."},sec={{t="Der Herd des Tal der Stärke",b="Hinter dem Tresen des Broken Tusk führt Gryshka eines der meistbesuchten Gasthäuser der Horde. Direkt hinter den Haupttoren von Orgrimmar im Tal der Stärke gelegen, dient ihre Schänke als erste Raststätte für Krieger, Boten und frisch eingetroffene Champions, die unter Thralls Banner Schutz suchen."},{t="Eine Vorliebe für frisches Fleisch",b="Eine belebte Taverne in einem trockenen Canyon zu führen, erfordert verlässliche Nachschubwege. Gryshka pflegt eine wohlbekannte Vorliebe für frisches Fleisch und verlässt sich auf vertrauenswürdige Jäger in den Gebieten der Horde, um ihre Küche zu beliefern. Gefährten wie Zargh im Wegekreuz und Grimtak in Durotar schicken regelmäßig ihre feinsten Wildfleischstücke an das Broken Tusk, um ihren anspruchsvollen kulinarischen Maßstäben gerecht zu werden."}},faq={{q="Wer ist Gastwirtin Gryshka?",a="Gastwirtin Gryshka ist die orcische Gastwirtin, die die Taverne Broken Tusk im Tal der Stärke von Orgrimmar führt. Sie heißt Reisende der Horde willkommen, legt Ruhesteinbindungen fest und verkauft Speisen und Getränke an ermattete Abenteurer.",al={"wer ist gryshka","gryshka orgrimmar","gastwirt broken tusk"}},{q="Wo ist Gastwirtin Gryshka zu finden?",a="Sie befindet sich in der Taverne Broken Tusk im Tal der Stärke, dem ersten großen Viertel, das Ihr nach dem Durchqueren der südlichen Haupttore von Orgrimmar betretet.",al={"wo ist gryshka","broken tusk gasthaus standort","tal der stärke gastwirt"}},{q="Woher bezieht Gryshka ihre Fleischvorräte?",a="Gryshka verlässt sich auf Freunde und Späher in den Ländern der Horde, um ihre Vorratskammer zu füllen, darunter Zargh, der im Wegekreuz im Brachland stationiert ist, sowie Grimtak in Durotar, die ihr erlesene Fleischstücke von Wildtieren schicken.",al={"gryshka lebensmittelquellen","wer beliefert das broken tusk","zargh fleischlieferung"}},{q="Welche Dienste bietet Gryshka an?",a="Gryshka kann Euren Ruhestein an das Broken Tusk binden, sodass Ihr Euch direkt nach Orgrimmar teleportieren könnt. Außerdem verkauft sie verschiedene Speisen, Brote und Getränke zur Wiederherstellung von Gesundheit und Mana.",al={"kann ich hier meinen ruhestein binden","broken tusk ruhestein","gryshka händlerwaren"}},{q="Hat Gryshka eine Verbindung zum Windreiterhorst?",a="Reisende, die mit Flugaufträgen aus dem Brachland entsandt werden, überbringen Gryshka oft direkt Pakete, bevor sie zu Doras weitergeleitet werden, dem Windreitermeister, der hoch oben auf der Hochebene über der Stadt weilt.",al={"doras quest","windreitermeister broken tusk","flug nach orgrimmar gasthaus"}},{q="Was für eine Persönlichkeit hat Gryshka?",a="Gryshka ist eine pragmatische, herzhafte orcische Gastgeberin, die gutes Fleisch, offene Worte und eine wohlgeordnete, gut gefüllte Taverne für den steten Strom an Hordekriegern schätzt, die durch die Hauptstadt ziehen.",al={"ist gryshka freundlich","wie ist gryshka so"}}},fx={ad24947b={q="Auf wessen Seite steht Gastwirtin Gryshka?",a="Gryshka ist eine treue Tochter der Horde. Sie arbeitet im Tal der Stärke in Orgrimmar und versorgt direkt die Krieger, Jäger und Reisenden, die Kriegshäuptling Thrall dienen, und stellt sicher, dass sie unter dem Banner der Horde Rast und herzhafte Stärkung finden.",al={"gryshka fraktion","wem dient gryshka","ist gryshka horde"}},f36e4eb0={q="Was will Gastwirtin Gryshka?",a="Vor allem anderen will Gryshka, dass der „Zum gespaltenen Hauer“ gut versorgt und lebhaft bleibt. Sie besitzt einen legendären Appetit auf Qualitätsfleisch und verlässt sich ständig auf Freunde in ganz Durotar und dem Brachland, damit diese frische, erstklassige Stücke liefern, um sie selbst und ihre hungrige Kundschaft zufrieden zu stellen.",al={"was will gryshka","gryshka ziele","wonach sucht gryshka"}},edbe4e1f={q="Warum ist Gastwirtin Gryshka hier?",a="Gryshka leitet den „Zum gespaltenen Hauer“, die geschäftige Taverne im Herzen des Tals der Stärke in Orgrimmar. Sie bleibt hier, um Reisenden, die durch die Hauptstadt ziehen oder aus der rauen Wildnis zurückkehren, Gastfreundschaft, Essen, starkes Getränk und Unterkunft zu bieten.",al={"warum ist gryshka in orgrimmar","warum ist gryshka beim gespaltenen hauer","gryshka zweck"}}},fp="17,404,32.337.0,22.381.0,25.213.0,37.166.0,41.195.0,35.172.0,57.190.0,43.196.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="Gastwirt Keldamyr",s="Gastwirt Keldamyr kümmert sich um den Herd und die Unterkünfte des zentralen Gasthauses in Dolanaar auf Teldrassil. Er bietet Speis, Trank und eine Ruhestatt für junge Nachtelfen, die sich von Laubschattental aus in die weiteren Äste des Weltenbaums wagen.",h="Gastwirt Keldamyr kümmert sich um den Herd und die Unterkünfte des zentralen Gasthauses in Dolanaar auf...",kw={"dolanaar","ruhestein","gasthaus","gastwirt","keldamyr","nachtelf","teldrassil"},ang={["race:NightElf"]="Für Nachtelfen, die gerade erst aus den Ausbildungsstätten von Laubschattental aufbrechen, ist Keldamyrs Gasthaus gewöhnlich das allererste zweite Zuhause, an das sie ihre Ruhesteine binden."},sec={{t="Herd von Dolanaar",b="Dolanaar ist das erste Dorf, das Neuankömmlinge erreichen, nachdem sie die geschützte Lichtung von Aldrassil verlassen haben. Gastwirt Keldamyr pflegt diese zentrale Zuflucht der Gemeinschaft und versorgt Reisende unter dem Blätterdach von Teldrassil mit Brot, Quellwasser und weichen Betten. Wanderer, Schildwachen und junge Novizen auf dem Weg nach Darnassus halten regelmäßig an seinem Tresen inne, um zu Kräften zu kommen, ihre Ruhesteine zu binden und Rationen für die Reise durch das Geäst aufzustocken."},{t="Lieferungen ins Dorf",b="Der Betrieb eines Gasthauses hoch oben in den Zweigen erfordert stetige Nachschubwege von nahegelegenen Siedlungen und Händlern. Einheimische Boten werden oft direkt an Keldamyrs Tresen verwiesen, um Waren abzugeben, wodurch er unmittelbar in den täglichen Handel und die Logistik eingebunden ist, die das Leben in Dolanaar aufrechterhalten."}},faq={{q="Wo finde ich Gastwirt Keldamyr?",a="Keldamyr befindet sich im Hauptgebäude des Gasthauses im Herzen von Dolanaar, der ersten größeren Siedlung südlich von Laubschattental auf den Ästen von Teldrassil.",al={"keldamyr aufenthaltsort","wo ist keldamyr","dolanaar gastwirt aufenthaltsort"}},{q="Welche Dienste bietet Gastwirt Keldamyr an?",a="Er dient als örtlicher Gastwirt, was bedeutet, dass Ihr Euren Ruhestein an seinen Herd binden, grundlegenden Proviant wie Wasser, Milch, Saft und Brot kaufen oder Euch unter seinem Dach erholt ausloggen könnt.",al={"keldamyr waren","was verkauft keldamyr","dolanaar gasthaus essen"}},{q="An welchen Quests ist Gastwirt Keldamyr beteiligt?",a="Er ist der Empfänger des lokalen Kurierauftrags „Lieferung für Dolanaar“ und nimmt Pakete entgegen, die für den Erhalt und die Versorgung des Gasthauses der Siedlung bestimmt sind.",al={"keldamyr quests","dolanaar-lieferung abgeben"}}},fx={cc228f0e={q="Wer ist Gastwirt Keldamyr?",a="Gastwirt Keldamyr ist ein Nachtelf-Gastgeber, der das Gasthaus in Dolanaar leitet. Während Reisende zwischen den schattigen Lichtungen des Laubschattentals und den weitläufigeren Bereichen von Teldrassil unterwegs sind, bietet Keldamyr eine ruhige Feuerstelle, erfrischende Getränke und Vorräte für müde Abenteurer, die sich durch die großen Äste wagen.",al={"wer ist keldamyr","gastwirt keldamyr hintergrund"}},["1430db47"]={q="Auf wessen Seite steht Gastwirt Keldamyr?",a="Gastwirt Keldamyr ist Darnassus und der Allianz gegenüber loyal. Er dient der Nachtelfengemeinschaft von Dolanaar und öffnet seine Türen für seine elfischen Gefährten sowie besuchende Verbündete der Allianz, die unter dem Blätterdach von Teldrassil Ruhe suchen.",al={"keldamyr fraktion","ist keldamyr allianz"}},ff7bce47={q="Was möchte Gastwirt Keldamyr?",a="Keldamyr möchte das Gasthaus von Dolanaar gut ausgestattet und einladend halten. Er kümmert sich um eingehende Vorräte, koordiniert lokale Lieferungen und stellt sicher, dass jeder vorbeikommende Reisende Nahrung, Wasser und einen sicheren Ort hat, an dem er seinen Ruhestein binden kann, bevor er sich in die Wildnis begibt.",al={"keldamyrs ziele","was möchte keldamyr"}},dbe1a8c8={q="Warum ist Gastwirt Keldamyr hier in Dolanaar?",a="Dolanaar ist das wichtigste Wegekreuz und die Siedlung für junge Nachtelfen, die ihr Training im Laubschattental abschließen. Keldamyr unterhält das Gasthaus des Dorfes direkt an der Straße, um an diesem entscheidenden Knotenpunkt auf Teldrassil Unterkunft und Verpflegung zu bieten.",al={"warum ist keldamyr hier","keldamyr dolanaar"}}},fp="18,232,18.432.0,15.310.0,36.150.0,44.187.0,39.141.0"}
P.entries["npc:innkeeper-norman"] = {n="Gastwirt Norman",s="Gastwirt Norman hütet den Herd im Hauptgasthaus im Handwerksviertel von Unterstadt. Als ruhiger, pflichtbewusster Verlassener bietet er Reisenden der Horde Rast, das Festlegen von Hearthstones sowie Verpflegung, die auf die unterschiedlichen Geschmäcker von Lebenden und Toten abgestimmt ist.",h="Gastwirt Norman hütet den Herd im Hauptgasthaus im Handwerksviertel von Unterstadt.",kw={"bates","hallow's end","hearthstone","gastwirt","norman","handwerksviertel","unterstadt"},ang={["faction:Horde"]="Für lebende Verbündete der Horde, die Unterstadt besuchen, ist Normans Gasthaus einer der wenigen Orte, die inmitten einer ansonsten unwirtlichen unterirdischen Festung einen sicheren Platz zum Ausruhen und Erholen bieten.",["race:Undead"]="Norman bietet anderen Verlassenen im Herzen des Handwerksviertel einen zentralen Sammelpunkt, um zwischen ihren Aufträgen für die Dark Lady die müden Knochen auszuruhen."},sec={{t="Gastfreundschaft in den Abwasserkanälen",b="Im belebten Handwerksviertel unter den Ruinen der Capital City von Lordaeron gelegen, bietet Gastwirt Norman Abgesandten, Söldnern und Abenteurern auf der Durchreise durch die Festung der Verlassenen eine Bleibe. Trotz der feuchten Kälte und der alchemistischen Ausdünstungen von Unterstadt bleibt Normans Gasthaus ein geschäftiger Knotenpunkt für Reisende, die ihren Hearthstone binden, Neuigkeiten aus ganz Azeroth austauschen oder sich auf Expeditionen in die Plaguelands vorbereiten möchten."},{t="Festliche Eigenheiten",b="Während Norman für gewöhnlich seinen Pflichten nachgeht, Vorräte verkauft und Zimmer verwaltet, bringt die jährliche Ankunft von Hallow's End eine eigenwilligere Seite zum Vorschein. Während der Feiertage nimmt Norman am festlichen Treiben teil und verlangt von abenteuerlustigen Gästen, die festliche Leckereien wie Pfefferminzbonbons aus Unterstadt ergattern wollen, sonderbare Darbietungen – etwa wie ein Huhn zu gackern."}},faq={{q="Wo finde ich Gastwirt Norman?",a="Gastwirt Norman befindet sich im Hauptgasthaus im Handwerksviertel von Unterstadt, gelegen am südlichen Bogen des inneren Rings.",al={"norman standort","unterstadt gastwirt standort","wo ist norman"}},{q="Welche Dienste bietet Gastwirt Norman an?",a="Er dient als einer der primären Gastwirte für Unterstadt. Spieler können ihren Hearthstone an sein Gasthaus binden, Speisen und Getränke für Lebende und Untote kaufen oder sich sicher ausloggen, um sich auszuruhen.",al={"norman dienste","unterstadt hearthstone"}},{q="Warum verlangt Norman von Gästen, wie ein Huhn zu gackern?",a="Während des Festes Hallow's End beteiligt sich Norman an den traditionellen Festtagsstreichen. Abenteurer, die besondere Feiertags-Minzbonbons ergattern möchten, müssen ihren Stolz herunterschlucken und wie ein Huhn gackern, um sich seine Gunst zu verdienen.",al={"huhn gackern minzbonbons","norman huhn quest"}},{q="Ist Norman mit Innkeeper Bates verwandt?",a="Obwohl sie einander weder im Leben noch im Untod direkt erwähnen, ist keine Verwandtschaft zwischen ihnen bekannt. Ihre Namen zusammen sind eine augenzwinkernde Anspielung der Schöpfer der Welt auf den Gastwirt Norman Bates aus dem Film Psycho.",al={"norman bates verbindung","innkeeper bates norman"}}},fx={["543a0ebc"]={q="Wer ist Gastwirt Norman?",a="Gastwirt Norman ist ein Gastwirt der Verlassenen, der die geschäftige Taverne im Handwerksviertel der Unterstadt betreut. Während viele Untote die Annehmlichkeiten ihres sterblichen Lebens aufgegeben haben, versorgt Norman müde Reisende, Soldaten und Gesandte, die ihren Weg durch die unterirdische Festung von Lady Sylvanas finden, mit Speis, Trank und einem Ort zum Ausruhen.",al={"wer ist norman","hintergrundgeschichte gastwirt norman","norman unterstadt"}},bc99de77={q="Auf wessen Seite steht Gastwirt Norman?",a="Norman ist den Verlassenen und der Dunklen Fürstin treu und dient damit auch der gesamten Horde. Er befindet sich im Herzen des Handwerksviertels und öffnet seine Türen für besuchende Orcs, Trolle und Tauren. Er bietet ihnen unter den Ruinen von Lordaeron Unterschlupf, während er seinen untoten Artgenossen gegenüber zutiefst ergeben bleibt.",al={"fraktion norman","loyalität norman","gehört norman zur horde"}},["58ea57aa"]={q="Warum ist Gastwirt Norman hier?",a="Norman leitet die Haupteinkehr der Unterstadt und ist direkt im Handwerksviertel stationiert, wo sich Handel, Reisen und Politik kreuzen. Selbst im untoten Zustand benötigen Besucher und Bürger einen Treffpunkt, um Gerüchte auszutauschen, Ruhesteine zu binden und sich mit Vorräten einzudecken, und Norman sorgt dafür, dass die Taverne inmitten der Düsternis reibungslos läuft.",al={"warum ist norman in der unterstadt","norman handwerksviertel","was macht norman hier"}}},fp="16,256,25.440.0,22.353.0,34.140.0,44.201.0,52.197.0,37.216.0"}
P.entries["npc:innkeeper-pala"] = {n="Gastwirtin Pala",s="Gastwirtin Pala leitet die Cat and the Schamane, die geschäftige Taverne auf der unteren Ebene von Donnerfels. Sie bietet reisenden Abenteurern eine Ruhesteinbindung, kalte Getränke und einen Ort zum Ausruhen zwischen Reisen durch Mulgore und darüber hinaus.",h="Gastwirtin Pala leitet die Cat and the Schamane, die geschäftige Taverne auf der unteren Ebene von Donnerfels.",kw={"cat and the schamane","ruhestein","gastwirt","gastwirtin pala","mulgore","pala","donnerfels"},ang={["faction:Horde"]="Orcs, Trolle und Verlassene, die Mulgore besuchen, finden in Palas Gasthaus eine angenehme Operationsbasis direkt an den Aufzügen.",["race:Tauren"]="Für Tauren, die von den Grenzen Kalimdors heimkehren, bietet Pala ein vertrautes, einladendes Gesicht unter den hoch aufragenden Totems der zentralen Mesas."},sec={{t="Gastfreundschaft auf der unteren Anhöhe",b="Auf der unteren Anhöhe der weitläufigen Mesas von Donnerfels hütet Gastwirtin Pala den Herd in der Cat and the Schamane. Die Taverne dient als einer der zentralen Treffpunkte für Reisende, die von den zentralen Aufzügen steigen oder aus den weiten Ebenen von Mulgore ankommen. Pala wacht beständig über ihren Schankraum und sorgt dafür, dass müde Krieger, wandernde Druiden und reisende Verbündete der Horde eine verlässliche Zuflucht, ein warmes Getränk und ein vertrautes zweites Zuhause finden."}},faq={{q="Wo kann ich Gastwirtin Pala finden?",a="Pala befindet sich in der Taverne Cat and the Schamane, die auf der unteren Anhöhe von Donnerfels nahe den Hauptaufzügen der Stadt liegt.",al={"pala aufenthaltsort","wo ist pala","gastwirtin pala karte"}},{q="Welche Dienste bietet sie Reisenden an?",a="Wie andere Gastwirte in ganz Kalimdor kann Pala Euren Ruhestein an die Cat and the Schamane binden, sodass Ihr sofort dorthin zurückkehren könnt. Zudem verkauft sie einfache Speisen und Getränke zur Wiederherstellung von Gesundheit und Mana.",al={"pala dienste","kann ich ruhestein donnerfels binden","was verkauft pala"}},{q="Wie heißt ihre Taverne?",a="Ihre Taverne heißt Cat and the Schamane – eine Gaststätte, die dem stetigen Strom von Horde-Reisenden dient, die die untere Ebene der Stadt passieren.",al={"cat and the schamane","donnerfels unteres gasthaus name","pala gasthaus name"}}},fx={["18c94984"]={q="Wer ist Gastwirtin Pala?",a="Gastwirtin Pala ist eine Tauren-Gastgeberin, die sich im „Zur Katze und zum Schamanen“ auf der unteren Ebene von Donnerfels um Reisende und müde Wanderer kümmert. Sie pflegt den Herd, kehrt die Böden und bietet Essen, Trinken und einen erholsamen Ort für diejenigen, die die hohen Mesas der Tauren-Hauptstadt besuchen.",al={"wer ist pala","gastwirtin pala","wer ist gastwirtin pala"}},["3afadd2e"]={q="Auf wessen Seite steht Gastwirtin Pala?",a="Gastwirtin Pala ist den Taurenstämmen und der Horde unter Oberhäuptling Cairne Bluthuf treu. Da sie einladend im Herzen von Donnerfels steht, versorgt sie gerne Tauren, Orcs, Trolle und die besuchenden Verlassenen, die Gastfreundschaft in der Stadt suchen.",al={"gastwirtin pala fraktion","gastwirtin pala zugehörigkeit","ist pala horde"}},["0c2271e0"]={q="Was will Gastwirtin Pala?",a="Pala will nicht viel mehr, als dass „Zur Katze und zum Schamanen“ reibungslos läuft. Ihr Fokus liegt darauf, herzliche Gastfreundschaft anzubieten, Proviant zu servieren und einen sauberen, friedlichen Zufluchtsort bereitzustellen, an dem müde Reisende ihre Geister binden und sich zwischen beschwerlichen Reisen durch Kalimdor ausruhen können.",al={"was will pala","pala ziel","gastwirtin pala zweck"}},["1c871847"]={q="Warum ist Gastwirtin Pala hier?",a="Die weitläufigen Ebenen von Donnerfels sehen einen stetigen Verkehr von Jägern, Schamanen und Gesandten durch Mulgore. Gastwirtin Pala bleibt auf der unteren Ebene stationiert, um die Taverne zu führen und sicherzustellen, dass ankommende Abenteurer und Händler immer einen einladenden Herd und Proviant in der Nähe haben.",al={"warum ist pala hier","warum ist pala in donnerfels","gastwirtin pala rolle"}}},fp="14,243,29.485.0,32.134.0,44.192.0,31.146.0"}
P.entries["npc:interrogator-vishas"] = {n="Befrager Vishas",s="Befrager James Vishas ist der Foltermeister des Scharlachroten Kreuzzugs und tief im Friedhofsflügel vom Scharlachroten Kloster stationiert. Berüchtigt für seine schrille Stimme und schiere Grausamkeit, findet er ein verdrehtes Vergnügen daran, Gefangene zu brechen und die Grenzen sterblichen Fleisches auszutesten. Nur wenige, die seine Folterkammern betreten, verlassen sie jemals mit intaktem Verstand oder Körper.",h="Befrager James Vishas ist der Foltermeister des Scharlachroten Kreuzzugs und tief im Friedhofsflügel vom...",kw={"friedhof","befrager vishas","james vishas","der lordameresee","nancy vishas","das scharlachrote kloster","folter","vorrel sengutz"},ang={["class:Priest"]="Zu sehen, wie Vishas Eifer heraufbeschwört, um entsetzliche Verstümmelung zu heiligen, bietet eine erschreckende Demonstration dessen, wie ein heiliger Zweck in verdrehten Wahnsinn umschlagen kann.",["faction:Alliance"]="Helden der Allianz, die Vishas' Werk entdecken, erkennen schnell, dass der Scharlachrote Kreuzzug nicht länger zwischen Monstern der Geißel und unschuldigen lebenden Reisenden unterscheidet.",["race:Undead"]="Für die Verlassenen verkörpert Vishas die heuchlerische Bosheit der lebenden Eiferer, die gefangene Untote aus reiner Gehässigkeit foltern, während sie behaupten, dem Heiligen Licht zu dienen."},sec={{t="Das Skalpell des Großinquisitors",b="In den dunklen Krypten und Grabstätten vom Scharlachroten Kloster kümmert sich Befrager Vishas um die gefangenen Feinde des Kreuzzugs. Während die Eiferer draußen in glänzender Rüstung unter den Bannern der Reinheit marschieren, repräsentiert Vishas die düstere Realität hinter ihrem Kreuzzug: ungezügelter Sadismus, getarnt als religiöser, rechtschaffener Zorn. Er betrachtet das Verhör nicht bloß als eine Pflicht zur Informationsbeschaffung, sondern als eine geschätzte Handwerkskunst, wobei er in der Qual der gefangenen Verlassenen, gefangenen Geißel-Kreaturen und jeglicher lebender Reisender schwelgt, die das Unglück haben, als Ketzer gebrandmarkt zu werden."},{t="Ein Leben in stiller Häuslichkeit",b="Hinter den blutigen Schürzen und den Schreien der Folterkammer führt Vishas ein bizarr häusliches Doppelleben. Außerhalb der Klostermauern lebt seine Familie – einschließlich seiner Frau Nancy Vishas und seines älteren Verwandten Opa Vishas – friedlich in einem abgelegenen Häuschen an den östlichen Ufern vom Lordameresee im Alteracgebirge. Vishas trägt sogar grausige Andenken seiner Opfer zurück in sein Privatleben; so hat er einem gefangenen Verlassenen namens Vorrel Sengutz seinen geschätzten Ehering abgenommen, um ihn Nancy als Geschenk zu überreichen."}},faq={{q="Wo kann Befrager Vishas gefunden werden?",a="Befrager Vishas befindet sich tief im Friedhofsflügel vom Scharlachroten Kloster, in Tirisfal. Er beaufsichtigt eine düstere Folterkammer, die mit Eisenkäfigen und blutverschmierten Streckbänken ausgekleidet ist.",al={"standort von vishas","wo ist befrager vishas","raum von vishas"}},{q="Warum foltert Vishas seine Gefangenen?",a="Während der Scharlachrote Kreuzzug die Quälerei von Gefangenen damit rechtfertigt, die Verderbnis der Geißel auszumerzen und Informationen zu erlangen, erfreut sich Vishas persönlich an dem Schmerz, den er verursacht. Er ist ungemein stolz auf seine Grausamkeit und betrachtet Folter als seine künstlerische Handwerkskunst.",al={"warum foltert vishas leute","motivation von vishas"}},{q="Wer ist Vorrel Sengutz?",a="Vorrel Sengutz ist ein Gefangener, der im Friedhof des Klosters von Vishas inhaftiert und brutal gefoltert wird. Vishas unterzog Vorrel wochenlanger Qual und stahl seinen Ehering, mit der Absicht, ihn seiner Frau zu schenken.",al={"gefangener vorrel sengutz","wer ist der gefangene im käfig"}},{q="Wo lebt die Familie von Vishas?",a="Seine Familie lebt weit weg vom Kloster, in einem unscheinbaren Häuschen am östlichen Ufer vom Lordameresee im Alteracgebirge. Seine Frau Nancy und Opa Vishas wohnen dort in aller Stille, scheinbar losgelöst von seinen Gräueltaten.",al={"standort nancy vishas","opa vishas","haus von vishas familie"}},{q="Wen hält Vishas gefangen?",a="Der Scharlachrote Kreuzzug betrachtet die Untoten als Feinde. Unter Vishas' Gefangenen befindet sich der Verlassene Vorrel Sengutz, den er seit Wochen foltert.",al={"gefangene von vishas","wen foltert vishas","vishas gefangener vorrel"}},{q="Wie ist Vishas' Stimme und Gebaren?",a="Vishas ist bei jenen, die ihm gegenüberstehen, für seine schneidende, hohe Stimme, sein gackerndes Lachen und seine verstörende Begeisterung berüchtigt, wann immer sich eine Gelegenheit bietet, einem unwilligen Opfer Geheimnisse zu entlocken.",al={"stimme von vishas","persönlichkeit von vishas"}}},fx={["518fe48c"]={q="Wer ist Befrager Vishas?",a="James Vishas ist der Hauptbefrager des Scharlachroten Kreuzzugs und in den Tiefen des Friedhofs vom Scharlachroten Kloster stationiert. Fanatisch und berüchtigt für seine Grausamkeit, ist er sehr stolz darauf, Gefangene zu brechen, die vor ihn gebracht werden. Bewaffnet mit Folterinstrumenten und einem geistesgestörten Eifer, entlockt er jedem, der das Unglück hat, in seine Hände zu fallen, Geständnisse und peinigt ihn gleichermaßen.",al={"wer ist vishas","befrager vishas hintergrund","wer ist james vishas"}},cadee917={q="Auf wessen Seite steht Befrager Vishas?",a="Vishas ist dem Scharlachroten Kreuzzug voll und ganz ergeben. Er dient ihrem fanatischen Kreuzzug, indem er verdächtige Agenten der Geißel, gefangene Verlassene und jeden anderen foltert, der als beschmutzt oder feindselig gegenüber der fanatischen Reinheit des Ordens angesehen wird.",al={"vishas fraktion","für wen arbeitet vishas","vishas scharlachroter kreuzzug"}},e1510cf6={q="Warum ist Befrager Vishas hier?",a="Vishas ist in den Folterkammern des Friedhofs vom Scharlachroten Kloster stationiert, um Gefangene zu verhören, die in ganz Tirisfal gefangen genommen wurden. Er verbringt seine Tage und Nächte damit, Informationen zu erpressen, sadistischen Drängen freien Lauf zu lassen und die Geister von Gefangenen wie Vorrel Sengutz im Namen des Kreuzzugs zu brechen.",al={"warum ist vishas auf dem friedhof","vishas kloster rolle","was macht vishas hier"}}},fp="19,348,30.526.0,27.533.1,39.184.0,38.249.0,22.210.0,31.236.0,30.139.0,40.206.0"}
P.entries["npc:iverron"] = {fx={["7be6aac6"]={q="Auf wessen Seite steht Iverron?",a="Iverron ist ein gewöhnlicher Nachtelf, der seinem Volk und der Allianz treu ist. Er lebt friedlich in den geschützten Zweigen von Laubschattental auf Teldrassil und verlässt sich auf die Hilfe von Mit-Kaldorei wie seiner engen Freundin Dirania Silberschein, die sich um ihn kümmert, wenn ihm ein Missgeschick widerfährt.",al={"iverron fraktion","ist iverron allianz","wem dient iverron"}},["9c5ce7fc"]={q="Was will Iverron?",a="Im Moment will Iverron einfach nur überleben. Er wurde bei einem Ausflug durch Laubschattental von tödlichem Spinnengift niedergestreckt, ist handlungsunfähig und braucht dringend ein starkes Gegengift, bevor das Gift sein Leben fordert.",al={"iverron ziel","was braucht iverron","iverron motiv"}},b06694b4={q="Warum ist Iverron in Laubschattental?",a="Iverron wohnt in Laubschattental, dem geschützten Starttal von Teldrassil. Er wagte sich in die umliegenden Wälder, nur um dort den aggressiven Webholzspinnen in die Quere zu kommen. Vom Gift überwältigt, brach er zusammen und liegt nun niedergeschlagen auf dem Waldboden.",al={"warum ist iverron hier","iverron laubschattental grund","was ist mit iverron passiert"}}}}
P.entries["npc:jahan-hawkwing"] = {fx={f61d6720={q="Warum ist Jahan Falkenschwinge im Wegekreuz?",a="Jahan Falkenschwinge verdient seinen Lebensunterhalt als Händler für Leder- und Kettenrüstung im Wegekreuz. Da der Außenposten jeden Tag zahllose Kundschafter, Jäger und Reisende sieht, die durch das Brachland ziehen, versorgt sie sein Handwerk mit robuster Ausrüstung, die nötig ist, um in der rauen Wildnis zu überleben.",al={"warum ist jahan falkenschwinge hier","standort von jahan falkenschwinge","jahan falkenschwinge wegekreuz"}}}}
P.entries["npc:james-halloran"] = {n="James Halloran",s="James Halloran ist ein menschlicher Gerber, der im Sumpfland arbeitet, um die östlichen Königreiche mit feinen Häuten zu versorgen. Er lebt im Hafen von Menethil und verdient seinen Lebensunterhalt mit der Ernte der zähen, wertvollen Häute der heimischen Krokilisken der Region. Er ist auf durchreisende Abenteurer und nahe Handelswege angewiesen, um Rohmaterialien zu sammeln und seine fertigen Lederwaren zum Markt zu transportieren.",h="James Halloran ist ein menschlicher Gerber, der im Sumpfland arbeitet, um die östlichen Königreiche mit...",kw={"krokilisken","halloran","james halloran","lederverarbeitung","der hafen von menethil","gerber","sumpfland"},ang={["class:Hunter"]="Jäger, die durch die durchnässten Sümpfe navigieren, werden Gemeinsamkeiten mit Halloran finden, dessen Lebensunterhalt davon abhängt, die aggressiven Reptilienräuber des Sumpflands aufzuspüren und zu ernten.",["faction:Alliance"]="Hallorans Handel trägt dazu bei, die kommerzielle Präsenz der Allianz im rauen Sumpfland aufrechtzuerhalten, indem er Städte im ganzen Königreich mit wertvollem, handgefertigtem Leder versorgt."},sec={{t="Ein Gerber im Sumpf",b="Von seinem Zuhause im Hafen von Menethil aus verdient James Halloran seinen Lebensunterhalt mit dem Sumpfgebiet direkt vor der Stadt. Als unternehmungslustiger Gerber erkannte Halloran, dass die gefährlichen Moore eine lukrative Ware bieten: Krokiliskenhäute. Die Verarbeitung der rauen Haut von Sumpfreptilien zu hochwertigem Leder erfordert seltenes Handwerk, und Hallorans fertige Waren werden über lokale Handelswege an Käufer in ganz Azeroth verschifft."},{t="Häute, Lehrlinge und täglicher Handel",b="Die Arbeit so nah am Sumpf ist mit ständiger Gefahr verbunden. Halloran kann nicht einfach jedes Biest selbst jagen, während er sich um Gerbfässer und Handelslogistik kümmert. Er heuert häufig abgehärtete Reisende an, um die gröberen Arbeiten wie das Häuten junger Sumpfbestien und die Abwicklung der routinemäßigen Lieferungen zwischen seinem Arbeitsplatz und den umliegenden Siedlungen zu erledigen, damit sein geschäftiges Lederhandwerk stets ausreichend versorgt bleibt."}},faq={{q="Wer ist James Halloran?",a="James Halloran ist ein menschlicher Gerber, der im Hafen von Menethil im Sumpfland ansässig ist. Er ist darauf spezialisiert, die heimischen Krokilisken der Region zu jagen und zu häuten und ihre zähen Häute zu Lederwaren zu gerben, die in die ganze Welt exportiert werden.",al={"james halloran","halloran","wer ist halloran","gerber sumpfland"}},{q="Wo verkauft James Halloran sein Leder?",a="Halloran verarbeitet rohe Krokiliskenhäute zu feinem Leder und verschifft es in ganz Azeroth. Er ist stark auf den Seehandel angewiesen, der durch den Hafen von Menethil führt, um seine Waren über die Meere zu vertreiben.",al={"halloran lederhandel","wohin gehen krokiliskenhäute","halloran geschäft"}},{q="Warum benötigt Halloran Abenteurer, um Häute junger Krokilisken zu sammeln?",a="Das Gerben von Leder ist eine zeitaufwendige und arbeitsintensive Arbeit. Halloran beschäftigt reisende Abenteurer, um die lokalen Sumpfkrokilisken zu dezimieren und ihre Häute abzuziehen, damit er einen stetigen Vorrat an Rohmaterial hat, ohne seine Werkstatt verlassen zu müssen.",al={"warum junge krokilisken töten","quest häute junger krokilisken","krokiliskenhäute halloran"}},{q="Was verbindet Halloran mit dem Hafen von Menethil?",a="Der Hafen von Menethil dient als wichtigster Handels- und Versorgungsknotenpunkt der Region. Halloran verlässt sich auf den Hafen und seine Schifffahrtsrouten, um seine gegerbten Häute auf entfernte Märkte zu exportieren und sein Gerberhandwerk lebensfähig zu halten.",al={"halloran menethil","halloran hafenverbindung","wohnt halloran in menethil"}},{q="Wo ist James Halloran zu finden?",a="Halloran lebt und arbeitet im Hafen von Menethil, dem geschäftigen Hafen an der Westküste des Sumpflands, mit den Krokilisken-Sümpfen direkt vor der Stadt.",al={"halloran standort","wo ist james halloran","halloran finden"}},{q="Hat Halloran einen Lehrling?",a="Ja. Halloran schickte seinen Lehrling, den er wie einen Sohn betrachtet, in die Sümpfe, um riesige Krokilisken zu häuten, aber der junge Mann wurde zerfleischt und verlor ein Bein. Während sich der Lehrling erholt, verlässt sich Halloran auf abgehärtete Reisende, um die Häute zu sammeln, von denen sein Handwerk abhängt.",al={"halloran lehrling","aufgaben lehrling halloran","wer arbeitet für halloran"}}},fx={["21c95e2f"]={q="Auf wessen Seite steht James Halloran?",a="James Halloran ist mit der Allianz verbündet. Als menschlicher Handwerker, der im Sumpfland arbeitet, unterhält er Verbindungen zur Hafenstadt Hafen von Menethil, um seine Waren in den Gebieten der Allianz bereitzustellen.",al={"ist halloran allianz","fraktion von james halloran","wem dient halloran"}},b76d5522={q="Warum ist James Halloran hier im Sumpfland?",a="Halloran verdient seinen Lebensunterhalt als Gerber und Fallensteller. Die Sümpfe und Wasserwege des Sumpflands wimmeln nur so vor Krokolisken, was ihm einen stetigen Vorrat an Häuten liefert, die er gerbt und weit und breit exportiert.",al={"warum ist halloran im sumpfland","zweck von james halloran","warum ist halloran hier"}}},fp="14,354,23.426.0,35.394.0,22.229.0,43.205.0,68.243.0,49.210.0,34.143.0,33.260.0"}
P.entries["npc:jannok-breezesong"] = {n="Jannok Windsang",s="Jannok Windsang ist ein Nachtelfenschurkenlehrer, der im Dorf Dolanaar auf Teldrassil stationiert ist. Er unterweist junge Kaldoreischurken, die sich in das Geäst des Weltenbaums hinauswagen, in Heimlichkeit, List und Klingenkunst.",h="Jannok Windsang ist ein Nachtelfenschurkenlehrer, der im Dorf Dolanaar auf Teldrassil stationiert ist.",kw={"breezesong","dolanaar","erion schattenflüsterer","jannok","nachtelf","schurkenlehrer","teldrassil"},ang={["class:Rogue"]="Für junge Nachtelfenschurken, die auf Teldrassil anfangen, ist Jannok Euer entscheidender Mentor in Dolanaar, bevor Ihr Euch in die Hauptstadt begebt.",["race:NightElf"]="Während die Kultur der Kaldorei oft die Schildwachen und das Druidentum hervorhebt, bereiten Ausbilder wie Jannok jene vor, die Heimlichkeit, Gifte und Dolche bevorzugen."},sec={{t="Ein Wegweiser in den Schatten",b="Unter den Ästen von Dolanaar anzutreffen, dient Jannok Windsang als primärer Ausbilder für angehende Nachtelfenschurken. Anders als die förmlichen Schildwachen oder die zurückgezogenen Druiden von Teldrassil leitet Jannok jene an, die lautlos am Rande der Gesellschaft agieren. Er lehrt sie, durch die Schatten zu schleichen, aus dem Hinterhalt zuzuschlagen und ungesehen im Geäst zu überleben. Sobald ein Schurke die ersten Lektionen in Dolanaar hinter sich gelassen hat, schickt Jannok ihn weiter zu erfahreneren Meistern in der Hauptstadt Darnassus."}},faq={{q="Wer ist Jannok Windsang?",a="Jannok Windsang ist ein Nachtelfenschurkenlehrer mit Wohnsitz in Dolanaar auf Teldrassil. Er bringt jungen Kaldorei grundlegende Schurkenfähigkeiten und -techniken bei.",al={"wer ist jannok","jannok windsang rolle","schurkenlehrer dolanaar"}},{q="Wohin schickt Jannok aufstrebende Schurken?",a="Sobald ein Schurke seine frühe Ausbildung in Dolanaar abgeschlossen hat, weist Jannok ihn an, nach Darnassus zu reisen, um bei Erion Schattenflüsterer, einem höherrangigen Schurkenlehrer in der Enklave des Cenarius der Stadt, weiteren Unterricht zu nehmen.",al={"jannok quest","erion schattenflüsterer quest","dolanaar schurke nächster schritt"}},{q="Wo finde ich Jannok in Dolanaar?",a="Jannok befindet sich in Dolanaar, der zentralen Siedlung von Teldrassil außerhalb von Laubschattental, platziert bei den Ausbilderpavillons des Ortes.",al={"jannok aufenthaltsort","wo ist jannok","jannok windsang finden"}}},fx={f606b9db={q="Auf wessen Seite steht Jannok Windsang?",a="Jannok dient Darnassus und der Allianz. Als Ausbilder für Nachtelf-Schurken, der im Dorf Dolanaar stationiert ist, gilt seine Loyalität der Nation der Kaldorei und der Verteidigung von Teldrassil.",al={"fraktion von jannok windsang","wem dient jannok","loyalität von jannok"}},b07dd258={q="Warum ist Jannok Windsang hier?",a="Jannok ist in Dolanaar stationiert, um angehende Nachtelf-Schurken auszubilden, die aus dem Laubschattental kommen. Er bietet Training in Verstohlenheit und List an und schickt vielversprechende Kundschafter schließlich an Mentoren wie Erion Shadewhisper in Darnassus weiter.",al={"warum ist jannok in dolanaar","zweck von jannok windsang","warum ist jannok hier"}}},fp="17,230,22.506.0,25.156.0,40.221.0,36.137.0"}
P.entries["npc:jasper-fel"] = {n="Jasper Teufel",s="Jasper Teufel ist ein diskreter Händler, der vom Hauptquartier des SI:7 in Sturmwinds Altstadt aus operiert. Er versorgt Agenten mit Dolchen und verschiedenen Phiolen, behält Besucher scharf im Auge und ermahnt sie, ihre Zungen zu hüten. Sein stiller Handel unterstützt den verdeckten Arm des Königreichs hinter verschlossenen Türen.",h="Jasper Teufel ist ein diskreter Händler, der vom Hauptquartier des SI:7 in Sturmwinds Altstadt aus operiert.",kw={"dolche","jasper teufel","morbent teufel","die altstadt","schurkenbedarf","der si:7","sturmwind","phiolen"},ang={["class:Rogue"]="Jasper Teufel bietet die unverzichtbaren Phiolen und Ersatzklingen, die von verdeckten Agenten bei der Ausübung ihres Handwerks in Sturmwind benötigt werden.",["faction:Alliance"]="Aus dem Hauptquartier des SI:7 stellt Fel sicher, dass die Agenten, die das Königreich aus den Schatten heraus verteidigen, stets zuverlässigen Nachschub haben."},sec={{t="Vorräte für die Schatten",b="Versteckt in der Kaserne des SI:7 in der Altstadt bedient Jasper Teufel eine ganz bestimmte Klientel. Anstatt Standardwaffen an die Stadtwache zu verkaufen, bietet er unverzichtbare Werkzeuge des Spionagehandwerks: einfache Dolche und die empfindlichen Phiolen, die zum Brauen und Auftragen von Giften benötigt werden. Fel arbeitet unter der strengen Disziplin von Mathias Shaws Geheimdienstabteilung und ermahnt jeden, der sich ihm nähert, kurz angebunden, auf seine Worte zu achten. In einer Festung, die der Spionage und der lautlosen Tödlichkeit gewidmet ist, kann leichtsinniges Geplauder schnell zu einem frühen Ende führen."}},faq={{q="Wo kann ich Jasper Teufel finden?",a="Jasper Teufel ist im Hauptquartier des SI:7 im östlichen Teil von der Altstadt in Sturmwind stationiert.",al={"jasper teufel standort","wo ist jasper teufel","jasper teufel sturmwind"}},{q="Was verkauft Jasper Teufel?",a="Er liefert einfache Dolche und leere Phiolen verschiedener Güteklassen, was ihn zu einer nützlichen Anlaufstelle für Agenten macht, die sich mit Giftkomponenten eindecken möchten.",al={"jasper teufel händler","was verkauft fel","jasper teufel waren"}},{q="Ist Jasper Teufel mit Morbent Teufel verwandt?",a="Sie teilen denselben Nachnamen, was zu Spekulationen über eine familiäre Verbindung zu dem Nekromanten Morbent Teufel im Dämmerwald geführt hat, wenngleich Jasper selbst zu persönlichen Angelegenheiten schweigt.",al={"jasper teufel morbent teufel","ist jasper teufel mit morbent verwandt","familie fel dämmerwald"}},{q="Warum warnt Jasper Teufel Besucher davor, leise zu sprechen?",a="Er arbeitet direkt im SI:7, dem Herzen von Sturmwinds Spionageapparat. Unbedachte Worte gelten in einer Organisation voller Attentäter und Spione als gefährlich, und Fel stellt sicher, dass Besucher dem Hauptquartier mit der gebotenen Vorsicht begegnen.",al={"warum leise sprechen","jasper teufel warnung","falsches wort kehle durchgeschnitten"}}},fx={["4d6e97a5"]={q="Wer ist Jasper Teufel?",a="Jasper Teufel ist ein diskreter menschlicher Händler, der von Sturmwind aus operiert. Eingebettet in die geheimen Grenzen der Altstadt und in engem Kontakt mit Agenten des SI:7, stellt er verdeckte Vorräte, Phiolen und einfache Waffen für Schurken und geheime Agenten bereit, die sich durch die zwielichtige Unterwelt der Stadt bewegen.",al={"geschichte von jasper teufel","wer ist jasper teufel","identität von jasper teufel"}},["0dbc34cf"]={q="Auf wessen Seite steht Jasper Teufel?",a="Jasper Teufel ist loyal gegenüber Sturmwind und der Allianz und arbeitet in enger Abstimmung mit dem verdeckten Geheimdienstnetzwerk des SI:7. Während seine zwielichtige Persönlichkeit und seine gefährlichen Warnungen auf ein abtrünniges Element hindeuten könnten, unterstützt sein Handel direkt Agenten, die aus der Altstadt heraus den Interessen des Königreichs dienen.",al={"jasper teufel allianz","wem dient jasper teufel","fraktion von jasper teufel"}},["50a88541"]={q="Warum ist Jasper Teufel hier?",a="Jasper Teufel ist im Gebiet des SI:7 in der Altstadt stationiert und dient als unauffälliger Lieferant für Agenten, die Tools of the Trade benötigen. Ob er nun leere Phiolen für das Brauen von Giften oder einfache Klingen für stille Arbeit bereitstellt, er steht bereit, um verdeckte Aktivitäten abseits neugieriger Blicke zu unterstützen.",al={"warum ist jasper teufel in der altstadt","zweck von jasper teufel","warum ist jasper teufel hier"}}},fp="10,297,24.536.0,28.115.0,26.134.0,37.178.0,49.240.0"}
P.entries["npc:je-neu-sancrea"] = {n="Je'neu Sancrea",s="Je'neu Sancrea ist ein Dunkelspeertroll und ein Mitglied des Irdenen Rings, der am Außenposten von Zoram'gar an der Küste von Eschental stationiert ist. Da er finstere Erschütterungen tief unter dem Ufer spürt, leitet er Abenteurer der Horde an, die Verderbnis zu untersuchen, die den uralten, versunkenen Tempel der Tiefschwarzen Grotte heimsucht.",h="Je'neu Sancrea ist ein Dunkelspeertroll und ein Mitglied des Irdenen Rings, der am Außenposten von Zoram'gar...",kw={"aku'mai","tiefschwarze grotte","der irdene ring","je'neu sancrea","jeneu","schattenhammer","der zoramstrand","außenposten von zoram'gar"},ang={["class:Shaman"]="Als prominentes Mitglied der Dunkelspeer im Irdenen Ring verkörpert Je'neu die schamanische Pflicht, verderbte Elementare ins Gleichgewicht zu bringen und die Gewässer Kalimdors wiederherzustellen.",["faction:Horde"]="Je'neu dient als wichtigster Questknotenpunkt und geschichtlicher Führer der Horde für den Vorstoß in die Tiefschwarze Grotte von Eschental aus.",["race:Troll"]="Je'neu zeigt, wie die Dunkelspeertrolle an der Seite ihrer Verbündeten unter den Tauren und Orcs die spirituellen Pfade des Irdenen Rings angenommen haben."},sec={{t="Ein Schamane am Strand",b="Während sich der Großteil des Irdenen Rings auf die elementare Harmonie in ganz Kalimdor konzentriert, wacht Je'neu Sancrea über den abgelegenen und gefährlichen Zoramstrand. Vom Außenposten von Zoram'gar aus beobachtet er die finsteren Erschütterungen und unnatürlichen Gezeiten, die sich nahe dem verfallenen Tempel der Tiefschwarzen Grotte regen. Obwohl er an die schamanischen Pflichten seines Zirkels gebunden ist, arbeitet er aufgrund seiner tiefen Loyalität zum Stamm der Dunkelspeer und Thralls Horde ausschließlich mit Streitern der Horde zusammen."},{t="Schatten der Tiefe",b="Je'neu versucht, die wahre Ursache hinter der schleichenden Verderbnis an der Küste aufzudecken. Mithilfe kühner Abenteurer sammelt er besudelte Saphirkerne, untersucht die abscheulichen Überreste von Wasserelementaren wie Baron Aquanis und entlarvt den heimtückischen Einfluss des Schattenhammerkults. Die finsteren Rituale, die sich unter den Wellen abspielen, bedrohen nicht nur das Gleichgewicht der lokalen Elemente, sondern künden auch von der düsteren Rückkehr jener Mächte, die den Alten Göttern die Treue geschworen haben."}},faq={{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Schamane der Dunkelspeertrolle, der dem Irdenen Ring angehört. Er ist am Außenposten von Zoram'gar an der Küste von Eschental stationiert, wo er die wachsende Verderbnis überwacht, die aus der Tiefschwarzen Grotte dringt.",al={"wer ist jeneu","jeneu sancrea lore","was ist jeneu"}},{q="Warum interagiert Je'neu nur mit Abenteurern der Horde, wenn er dem Irdenen Ring angehört?",a="Obwohl der Irdene Ring als Organisation eher das elementare Gleichgewicht anstrebt als den Krieg der Fraktionen, sind Je'neus persönliche Bande fest im Stamm der Dunkelspeer und der Horde verwurzelt. Da er sich in einem militärischen Vorposten der Horde an vorderster Front in Eschental aufhält, heißt er Reisende der Allianz nicht willkommen.",al={"warum nur horde","kann allianz mit jeneu sprechen","ist jeneu neutral"}},{q="Was untersucht Je'neu in der Tiefschwarzen Grotte?",a="Je'neu untersucht die unnatürlichen Unruhigen Elemente und die dunkle Magie, die aus der Tiefschwarzen Grotte aufsteigen. Er beauftragt Streiter damit, verderbte Wasserkerne zu beschaffen, Kultisten des Schattenhammers zu töten und Gerüchte zu überprüfen, wonach eine uralte Hydra namens Aku'mai bösartigen Meistern tief unter dem Meer dient.",al={"jeneu questziele","was will jeneu","warum spieler in die bfd schicken"}},{q="Wo befindet sich Je'neu Sancrea?",a="Je'neu befindet sich am Außenposten von Zoram'gar, einer befestigten Siedlung der Horde an der äußersten Nordwestküste von Eschental, direkt am Zoramstrand, kurz südlich der Tiefschwarzen Grotte.",al={"wo ist jeneu","jeneu sancrea standort","jeneu finden"}},{q="Was ist der Irdene Ring?",a="Der Irdene Ring ist ein uralter Zirkel von Schamanen, der sich dem Verstehen und Besänftigen der Elementargeister der Welt widmet und immer dann einschreitet, wenn dunkle Mächte oder chaotische Wesenheiten die natürliche elementare Harmonie stören.",al={"der irdene ring lore","was ist der irdene ring","schamanenorganisation"}},{q="Welche Gefahr geht vom Schattenhammer in den Tiefen aus?",a="Der Kult des Schattenhammers hat die Tiefschwarze Grotte infiltriert, um die Bestie Aku'mai zu verehren und Rituale abzuhalten, die den Alten Göttern geweiht sind. Je'neu beauftragt Abenteurer der Horde damit, ihre Anführer niederzustrecken, um ihr finsteres Werk aufzuhalten.",al={"schattenhammer bfd","schattenhammerkult eschental","wer sind die kultisten in bfd"}}},fx={["1670a3c0"]={q="Warum ist Je'neu Sancrea hier?",a="Je'neu hat sich am Außenposten von Zoram'gar entlang der Küste des Eschentals stationiert, um die finstere Verderbnis zu beobachten, die sich in den nahen Ruinen der Tiefschwarzen Grotte regt. Der Irdene Ring spürte üble Störungen im natürlichen Gleichgewicht der Gewässer, was ihn an diese Grenze zog, um die sich versammelnden Kultisten zu überwachen und erfahrene Champions der Horde anzuwerben, um die Tiefen zu durchkämmen.",al={"warum ist jeneu im eschental","warum ist jeneu sancrea in zoramgar","was führt jeneu sancrea hierher"}}},fp="14,300,22.452.0,19.449.1,22.215.0,71.296.0,50.299.0,32.174.0,25.212.0,57.225.0"}
P.entries["npc:jen-shan"] = {n="Jen'shan",s="Jen'shan ist eine Dschungeltrollin der Dunkelspeer und eine Jägerlehrerin, die im Tal der Prüfungen in Durotar stationiert ist. Sie leitet angehende Schützen der Orcs und Trolle an, während diese ihre ersten Schritte in die Wildnis der Horde wagen. Junge Jäger werden zu ihr geschickt, um die Grundlagen des Fährtenlesens, des Fernkampfs und des Überlebens zu erlernen.",h="Jen'shan ist eine Dschungeltrollin der Dunkelspeer und eine Jägerlehrerin, die im Tal der Prüfungen in...",kw={"dunkelspeer","durotar","geätztes pergament","geätzte schrifttafel","jägerlehrer","jen'shan","jenshan","troll","das tal der prüfungen"},ang={["class:Hunter"]="Für junge Jäger der Orcs und Trolle ist Jen'shan die allererste Lehrmeisterin, der Ihr begegnet. Sie lehrt grundlegende Fernkampftechniken, bevor Ihr Euch über die roten Schluchten des Höhlenbaus hinauswagt.",["race:Troll"]="Jen'shan verkörpert das berühmte Können des Dunkelspeerstammes im Fährtenlesen und Kundschaften und stellt sicher, dass junge Trolle ihre angestammten Jagdtraditionen in ihrer neuen Heimat auf dem Festland bewahren."},sec={{t="Lehrmeisterin des roten Sandes",b="Inmitten der verwitterten Lager des Tals der Prüfungen dient Jen'shan als wichtigste Jägerlehrmeisterin für neue Rekruten, die ihren Wert für die Horde beweisen wollen. Junge Orcs und Trolle der Dunkelspeer treffen gleichermaßen ein, während sie beschriftete Tafeln und Pergamente umklammern, die sie geradewegs zu ihr führen. Mit scharfen Augen, die durch Jahre in der ungezähmten Wildnis geschärft wurden, vermittelt sie grundlegende Techniken des Bogenschießens, der Treffsicherheit und des Überlebens in der Wildnis, um sicherzustellen, dass kein Neuling den Skorpionen und Ebern zum Opfer fällt, die den Grund der Schlucht durchstreifen."}},faq={{q="Wer ist Jen'shan?",a="Jen'shan ist eine Dschungeltrollin der Dunkelspeer und Jägerlehrerin, die sich im Tal der Prüfungen in Durotar befindet. Sie unterweist neue Jäger der Horde in grundlegender Wildniskunde, Fährtenlesen und Fernkampfwaffen.",al={"jenshan geschichte","wer ist jenshan","jägerlehrer tal der prüfungen"}},{q="Welche Quests drehen sich um Jen'shan?",a="Neue Jäger werden über einführende Ausbildungsquests zu ihr geschickt. Junge Orcjäger werden angewiesen, bei ihr eine Geätzte Schrifttafel abzugeben, während junge Trolljäger sie mit einem Geätzten Pergament aufsuchen.",al={"jenshan quests","geätzte schrifttafel jenshan","geätztes pergament jenshan"}},{q="Warum bildet ein Troll Jäger auf einem orcischen Prüfungsfeld aus?",a="Das Tal der Prüfungen dient sowohl orcischen Rekruten als auch den vertriebenen Dunkelspeertrollen, die sich Durotar teilen, als gemeinsame Ausbildungsstätte. Als meisterhafte Kundschafter und Pirschjäger spielen Trolle wie Jen'shan eine entscheidende Rolle dabei, neue Krieger und Jäger beider Völker auf den Dienst für die Horde vorzubereiten.",al={"warum ist ein troll im tal der prüfungen","troll-lehrer in durotar"}}},fx={["9968b478"]={q="Auf wessen Seite steht Jen'shan?",a="Jen'shan ist der Horde und ihrem Volk, dem Stamm der Dunkelspeere, loyal. Sie ist im Tal der Prüfungen stationiert und dient an der Seite der Orcs, um sicherzustellen, dass neue Rekruten, egal ob Troll oder Orc, angemessen auf die raue Realität des Überlebens in Durotar und den Kampf für den Kriegshäuptling vorbereitet sind.",al={"fraktion von jenshan","ist jenshan horde","loyalität von jenshan"}},f50adc74={q="Was möchte Jen'shan?",a="Jen'shan versucht, angehenden Jägern Treffsicherheit, Überlebenskunst und die wilden Instinkte beizubringen, die sie zum Durchhalten brauchen. Sie möchte, dass vielversprechende junge Kundschafter ihr Handwerk schnell verfeinern, damit sie mit den wilden Bestien, die durch die roten Einöden streifen, fertig werden und die junge Horde vor ihren Feinden schützen können.",al={"motiv von jenshan","ziel von jenshan","was braucht jenshan"}},ece1555d={q="Mit wem ist Jen'shan verbunden?",a="Jen'shan gehört zu den Dunkelspeertrollen, die von Sen'jins Sohn Vol'jin angeführt werden. Da sich die Dunkelspeere Durotar mit Thralls Orcs teilen, arbeitet sie eng mit den Ausbildern des Tals der Prüfungen zusammen, um frische Rekruten beider Völker in die Reihen der Horde zu führen.",al={"verbindungen von jenshan","jenshan darkspear verbindungen","wem dient jenshan"}}},fp="8,301,23.520.0,16.198.0,29.199.0,57.280.0"}
P.entries["npc:jennea-cannon"] = {fx={b57d5dda={q="Auf welcher Seite steht Jennea Haubitz?",a="Jennea dient dem Königreich Sturmwind und der Allianz. Sie ist im Magiersanktum stationiert und arbeitet dort gemeinsam mit dem Zirkel der Zauberer von Sturmwind daran, die magischen Verteidigungsanlagen der Stadt zu stärken und junge, dem Reich treue Magier auszubilden.",al={"jennea haubitz fraktion","wem dient jennea haubitz","jennea haubitz zugehörigkeit"}},d154dff8={q="Was möchte Jennea Haubitz?",a="Jennea widmet sich der Anleitung und Vorbereitung angehender Zauberwirker. Sie möchte sicherstellen, dass Neulinge die gefährliche, unbeständige Natur der arkanen Magie verstehen, und warnt Reisende davor, dass rohe Magie Ungeübte verbrennen kann, während sie vielversprechende Schüler auf wichtige Studien im gesamten Reich hinweist.",al={"jennea haubitz ziel","was möchte jennea","jennea haubitz zweck"}},d5352518={q="Warum ist Jennea Haubitz hier?",a="Sie residiert im Magiersanktum im Magierviertel von Sturmwind, um als Mentorin für Magier der Allianz zu fungieren. Von diesem Turm aus überwacht sie die erste arkane Ausbildung, untersucht Störungen in der Nähe und verweist Praktizierende an höhere Autoritäten wie High Sorcerer Andromath oder Tutoren im Ausland.",al={"warum ist jennea haubitz in sturmwind","jennea haubitz magiersanktum","warum ist jennea im magierviertel"}}}}
P.entries["npc:jergosh-the-invoker"] = {n="Jergosh der Herbeirufer",s="Jergosh der Herbeirufer ist ein verräterischer Orc-Hexenmeister, der sich tief im Flammenschlund unter Orgrimmar verbirgt. Als hochrangiger Anführer unter den Kultisten der Searing Blade praktiziert er dämonische Künste direkt vor den Augen des Kriegshäuptlings und verschwört sich gegen die Horde.",h="Jergosh der Herbeirufer ist ein verräterischer Orc-Hexenmeister, der sich tief im Flammenschlund unter...",kw={"herbeirufer","jergosh","orgrimmar","der flammenschlund","searing blade","schattenrat","hexenmeister"},ang={["class:Warlock"]="Für Hexenmeister ist Jergosh ein mächtiger Anwender der dämonischen Künste, dessen Pläne die Horde bedrohen.",["faction:Horde"]="Eine Zelle des Schattenrats zu haben, die unter dem Thronsaal des Häuptlings floriert, ist eine unerträgliche Sicherheitsbedrohung, welche die Horde sich nicht leisten kann zu ignorieren.",["race:Orc"]="Jergosh verkörpert das verweilende Gift der alten Horde – die Verlockung von Dämonenblut und Zauberei, die Thrall aus der orcischen Kultur zu tilgen bestrebt ist."},sec={{t="Ein Kult unter der Stadt",b="Während Thrall unermüdlich daran arbeitet, die Orcs auf einen Pfad der Ehre und des Schamanismus zu führen, wies Jergosh diese Ideale zugunsten roher dämonischer Macht zurück. Indem er sich im unterirdischen Labyrinth des Flammenschlunds unter Orgrimmar verbarg, scharte er Anhänger in der Searing Blade um sich, einer heimtückischen Sekte, die mit den Überresten des Schattenrats verbündet ist. In den Schatten direkt unter der Hauptstadt der Horde agierend, arbeitet Jergosh daran, alles zunichtezumachen, wofür The New Horde steht."},{t="Dämonische Ambitionen",b="Jergoshs Anwesenheit in der Kluft ist keineswegs zielloses Umherwandern. Seine dunklen Rituale und gefährlichen Pläne wurden schließlich dreist genug, um die direkte Aufmerksamkeit von Thrall persönlich auf sich zu ziehen. Jergosh stellt eine existenzielle Infektion innerhalb von Durotar dar und erinnert die Horde an die dunklen Pakte, für deren Hinterlassung sie so verzweifelt gekämpft hat."}},faq={{q="Wer ist Jergosh der Herbeirufer?",a="Jergosh der Herbeirufer ist ein mächtiger Orc-Hexenmeister und ein Anführer der Kultisten der Searing Blade, die im Flammenschlund operieren. Anstatt Thralls ehrenhaftem Weg zu folgen, entschied er sich dafür, sich dämonischer Zauberei hinzugeben.",al={"wer ist jergosh","jergosh lore","jergosh flammenschlund"}},{q="Warum versteckt sich Jergosh im Flammenschlund?",a="Der Flammenschlund bietet der Searing Blade ein abgeschiedenes Netzwerk feuriger Höhlen direkt unter Orgrimmar. Von dort aus können Jergosh und seine Kultisten verbotene dunkle Magie praktizieren und sich unentdeckt gegen die Horde verschwören.",al={"warum ist jergosh unter orgrimmar","jergosh aufenthaltsort lore"}},{q="Welcher Fraktion gehört Jergosh an?",a="Jergosh ist ein Anführer innerhalb der Searing Blade, eines Kults, der mit dem Schattenrat in Verbindung steht und sich dem Dienen dämonischer Interessen wie der Brennenden Legion verschrieben hat.",al={"jergosh fraktion","ist jergosh schattenrat","anführer der searing blade"}},{q="Weiß Thrall, dass Jergosh sich unter Orgrimmar befindet?",a="Ja. Jergoshs Pläne wurden gefährlich genug, dass Gerüchte Thrall erreichten, was den Kriegshäuptling dazu veranlasste, vertrauenswürdige Abenteurer in den Flammenschlund zu entsenden, um die Bedrohung durch die Kultisten zu beseitigen.",al={"thrall jergosh","weiß thrall vom flammenschlund"}},{q="Warum praktiziert Jergosh Teufelsmagie anstelle von Schamanismus?",a="Jergosh kehrte dem spirituellen Wiederaufleben seines Volkes bereitwillig den Rücken und lehnte schamanische Harmonie ab, um der berauschenden Macht nachzujagen, die von der Brennenden Legion und den dunklen Künsten versprochen wurde.",al={"warum hexenmeister","jergosh teufelsmagie"}}},fx={["3ff8bf73"]={q="Was möchte Jergosh der Herbeirufer?",a="Jergosh zielt darauf ab, die Horde aus ihrer eigenen Hauptstadt heraus zu untergraben. Er lehnt Thralls erneuerte schamanistische Ideale ab und versucht, dunkle dämonische Praktiken wiederzubeleben und die niederträchtigen Ambitionen des Schattenrats voranzutreiben. Er lauert im Abgrund und heckt subversive Pläne aus, die gefährlich genug sind, um die Stabilität von Orgrimmar selbst zu bedrohen.",al={"ziel von jergosh","was möchte jergosh","motiv von jergosh"}},["752417a2"]={q="Mit wem ist Jergosh der Herbeirufer verbunden?",a="Jergosh ist ein führender Anführer unter den Kultisten der Klinge des Brennenden Messers, einem unterirdischen Zirkel, der direkt unter Orgrimmar operiert. Der Kult ist insgeheim ein Arm des größeren Schattenrats, was Jergosh direkt an das schattenhafte Netzwerk von Hexenmeistern und Dämonenanbetern bindet, die versuchen, das orcische Volk zurück in die Verderbnis zu ziehen.",al={"verbündete von jergosh","für wen arbeitet jergosh","jergosh schattenrat"}},baae249b={q="Warum wird Jergosh der Herbeirufer gefürchtet?",a="Jergosh wird gefürchtet, weil er verbotene Teufelsmagie direkt unter den Füßen der Führung der Horde einsetzt. Seine dunklen Rituale, dämonischen Beschwörungen und seine radikale Ablehnung des Weges der neuen Horde stellen eine existenzielle interne Bedrohung dar, die die direkte Aufmerksamkeit und Besorgnis von Kriegshäuptling Thrall selbst auf sich zieht.",al={"warum wird jergosh gefürchtet","ist jergosh gefährlich","ruf von jergosh"}}},fp="19,250,23.465.0,17.321.1,27.205.0,40.224.0,36.147.0,46.171.0,57.184.0"}
P.entries["npc:jern-hornhelm"] = {fx={["1cf890d8"]={q="Warum ist Jern Hornhelm in Thelsamar?",a="Jern Hornhelm ist in Thelsamar stationiert, um die Logistik für lokale archäologische Ausgrabungen in ganz Loch Modan zu verwalten. Er arbeitet zur Unterstützung der Forscherliga und koordiniert kritische Vorräte, Berichte und Sprengstoffe zwischen Eisenschmiede und abgelegenen Grabungsstätten wie Ironband's Excavation, um sicherzustellen, dass die Operationen der Liga finanziert und ausgerüstet bleiben.",al={"warum ist jern hornhelm hier","zweck von jern hornhelm in loch modan","warum ist jern in thelsamar"}}}}
P.entries["npc:jitters"] = {n="Bibbers",s="Bibbers ist ein zitternder, zurückgezogen lebender Mensch, der sich in den Ruinen von Rabenflucht im westlichen Dämmerwald versteckt hält. Verzehrt von ständiger Paranoia und Angst überlebt er allein am gefährlichen westlichen Rand des Dämmerwaldes. Dabei ist er auf die Hilfe vorbeikommender Abenteurer angewiesen, während er die näher rückenden Schatten beobachtet.",h="Bibbers ist ein zitternder, zurückgezogen lebender Mensch, der sich in den Ruinen von Rabenflucht im...",kw={"amtmann daltry","dark riders","dämmerwald","jitters","rabenflucht","rolands verdammnis","die sense von elune","sven yorgen","worgen"},ang={["class:Rogue"]="Bibbers besitzt schnelle Instinkte, um Gefahren zu vermeiden, aber sie haben ihn nicht vor dem Terror und der Isolation im Dämmerwald bewahrt.",["faction:Alliance"]="Bibbers steht für das menschliche Gesicht der Tragödie im Dämmerwald; er lebt in Angst, während die Nachtwache darum kämpft, die Bewohner zu schützen."},sec={{t="Ein heimgesuchter Einsiedler",b="Bibbers zittert inmitten der baufälligen Häuser von Rabenflucht und lebt in ständiger Angst vor den Raubtieren, die die westlichen Pfade des Dämmerwaldes durchstreifen. Er ist auf vorbeikommende Abenteurer angewiesen, die ihm einfache Nahrung geben, da er verzweifelt Hunger leidet, während er die näher rückenden Schatten ängstlich im Auge behält. Seine nervösen Manierismen und sein unheimlicher Reflex, plötzlicher Gefahr auszuweichen, brachten ihm vor langer Zeit seinen Spitznamen ein, doch seine hektische Paranoia ist das Ergebnis seiner Begegnungen mit schrecklichen Monstern."},{t="Das Erwachen bei Rolands Verdammnis",b="Bibbers gehörte ursprünglich zur Bruderschaft der Defias, als diese in den Dämmerwald vordrang. Während er in der Mine namens Rolands Verdammnis grub, entdeckte er Die Sense von Elune, die aus dem Gestein ragte. Das Artefakt entfesselte wilde, blutrünstige Worgen im Wald. Bibbers sah voller Entsetzen zu, wie seine Kameraden zerfetzt wurden, und entkam dem Massaker nur mit knapper Not."},{t="Flucht und der Bauernhof",b="Auf der Flucht aus der Mine zog sich Bibbers nach Dunkelhain zurück, kaufte ein leeres Buch bei Amtmann Daltry und hielt den Albtraum fieberhaft fest, während er sich in der Scarlet Raven Tavern versteckte. In Panik suchte er Zuflucht in einer Scheune auf Yorgens Bauernhof. Dort musste er mitansehen, wie schwarz gewandete Dark Riders Sven Yorgens Familie auf der Suche nach der Sense abschlachteten. Aus Angst, beschuldigt oder gefunden zu werden, vergrub Bibbers die Seiten seines Tagebuchs in der Erde und floh nach Rabenflucht, verfolgt von lähmenden Schuldgefühlen und unaufhörlicher Furcht."}},faq={{q="Wer ist Bibbers?",a="Bibbers ist ein verängstigter Mensch, der in den Ruinen von Rabenflucht lebt. Er ist hungrig, isoliert und wird von seinen Erlebnissen im Dämmerwald heimgesucht.",al={"wer ist dieser typ","jitters hintergrundgeschichte","jitters hintergrund"}},{q="Warum wird er Bibbers genannt?",a="Sein Spitzname stammt von seinem vorsichtigen Wesen, insbesondere von seiner instinktiven Angewohnheit, vor Schlägen zurückzuzucken und plötzlichen Gefahren auszuweichen. Seine lange Isolation und die schiere Angst im Dämmerwald haben seine Nervosität nur noch verschlimmert.",al={"warum jitters","woher kommt sein name","jitters namensherkunft"}},{q="Welche Gefahr stellen die Worgen im Dämmerwald dar?",a="Worgen durchstreifen die Wälder und Straßen des Dämmerwaldes und bedrohen Reisende sowie isolierte Siedlungen.",al={"worgenbedrohung dämmerwald","bestien bei jitters","worgengefahr dämmerwald"}},{q="Was ist mit Sven Yorgens Familie passiert?",a="Sven Yorgens Familie wurde auf ihrem Bauernhof ermordet, was ihn dazu veranlasste, herauszufinden, wer dafür verantwortlich war.",al={"sven bauernhof massaker","wer tötete svens familie","yorgens bauernhof morde"}},{q="Wie kann Bibbers Sven Yorgens Untersuchung helfen?",a="Bibbers' Tagebuch hält seine Erlebnisse im Dämmerwald fest und könnte Sven dabei helfen, zu untersuchen, was seiner Familie zugestoßen ist.",al={"jitters und svens untersuchung","wie kann jitters sven helfen","jitters bericht über dämmerwald"}},{q="Was ist Bibbers' Tagebuch?",a="Sein Tagebuch zeichnet seine Erlebnisse im Dämmerwald auf und ist Teil der Untersuchungen rund um Rabenflucht und Sven Yorgens Familie.",al={"jitters tagebuch","jitters vollständiges tagebuch","daltry buch"}}},fx={["9934be9b"]={q="Auf wessen Seite steht Bibbers?",a="Bibbers ist ein verängstigter, hungriger Überlebender, der sich in Raven Hill versteckt und dessen beunruhigende Erfahrungen ihn isoliert und tief erschüttert haben.",al={"fraktion von bibbers","ist bibbers böse","für wen arbeitet bibbers","loyalität von bibbers"}},["3395ed32"]={q="Was möchte Bibbers?",a="Bibbers möchte Essen und Sicherheit. Sein Hunger bringt ihn in Kontakt mit Abenteurern, die die Probleme um Raven Hill untersuchen.",al={"was braucht bibbers","motiv von bibbers","warum schickt bibbers einen"}},af0d9be3={q="Warum ist Bibbers hier in Raven Hill?",a="Raven Hill bietet Bibbers ein Versteck zwischen den verlassenen Gebäuden des Dämmerwalds, obwohl es ihm wenig Trost oder Schutz bietet.",al={"warum ist bibbers in raven hill","wie kam bibbers hierher","warum versteckt sich bibbers hier"}},b49992e9={q="Mit wem ist Bibbers verbunden?",a="Seine Geschichte überschneidet sich mit Sven Yorgens Ermittlungen und den Berichten, die in seinem Tagebuch bewahrt werden.",al={"verbindungen von bibbers","mit wem ist bibbers verbunden","bibbers defias"}}},fp="7,282,16.468.0,30.388.1,24.493.1,15.132.1,25.244.0,43.88.1,38.108.1,49.111.1,25.132.1"}
P.entries["npc:jocaste"] = {n="Jocaste",s="Jocaste ist eine Nachtelfen-Jägerlehrerin, die in der grünen Enklave des Cenarius in Darnassus weilt. An der Seite des Zirkels des Cenarius unterweist sie junge Scharfschützen und Bestienmeister der Nachtelfen, die aus der Wildnis von Teldrassil eintreffen.",h="Jocaste ist eine Nachtelfen-Jägerlehrerin, die in der grünen Enklave des Cenarius in Darnassus weilt.",kw={"die enklave des cenarius","darnassus","jägerlehrer","jocaste","nachtelfenjäger","teldrassil"},ang={["class:Hunter"]="Für Jäger der Nachtelfen, die zum ersten Mal Darnassus betreten, ist Jocaste eine wichtige Lehrerin, die Eure Kampftechniken verfeinert und dabei hilft, das Band zu Euren tierischen Begleitern zu festigen.",["race:NightElf"]="Verwurzelt in der Enklave des Cenarius spiegelt Jocaste den tiefen Einklang zwischen den Wanderern der Nachtelfen, den wilden Tieren von Teldrassil und den Lehren des Zirkels des Cenarius wider."},sec={{t="Eine Mentorin in der Enklave",b="Inmitten der friedvollen Haine der Enklave des Cenarius in Darnassus dient Jocaste als Ausbilderin für Jäger der Nachtelfen. Wenn angehende Fährtenleser ihre erste Ausbildung in Laubschattental abschließen und in die Hauptstadt aufbrechen, leitet Jocaste ihren Wandel zu erfahrenen Überlebenskünstlern an. Sie lehrt die Kunst der Treffsicherheit, das Überleben in der Wildnis sowie die heilige Verbindung zwischen einem Jäger und den wilden Tieren von Kalimdor."}},faq={{q="Wer ist Jocaste?",a="Jocaste ist eine Jägerlehrerin der Nachtelfen in der Enklave des Cenarius in der Hauptstadt Darnassus, die Ausübenden der Jagd Unterricht und Führung bietet.",al={"jocaste lore","wer ist jocaste","jocaste darnassus"}},{q="Wo kann ich Jocaste finden?",a="Sie ist zwischen den Bäumen und Pavillons der Enklave des Cenarius im nordwestlichen Bezirk von Darnassus auf den Ästen von Teldrassil zu finden.",al={"jocaste aufenthaltsort","wo ist jocaste","jocaste standort"}},{q="Welche Rolle spielt sie für junge Jäger?",a="Jäger, die nach Darnassus geschickt werden, suchen sie auf, um ihre Disziplin durch Aufgaben wie „Der Weg des Jägers“ voranzubringen und zu lernen, wie man wilde Bestien richtig zähmt und meistert.",al={"jocaste quests","der weg des jägers jocaste","die ausbildung des tiers"}},{q="Gehört Jocaste zum Zirkel des Cenarius?",a="Ja. Obwohl sie Jäger und keine Druiden ausbildet, wirkt sie in der Enklave des Cenarius und heißt reisende Jäger ausdrücklich in der Gegenwart des Zirkels des Cenarius willkommen.",al={"gehört jocaste zum zirkel des cenarius","jocaste fraktion"}}},fx={["42c501de"]={q="Auf wessen Seite steht Jocaste?",a="Jocaste steht fest an der Seite von Darnassus, der Nachtelfen und der Allianz im Allgemeinen. Stationiert bei dem Zirkel des Cenarius in ihrer Enklave, teilt sie deren Hingabe, die Natur zu schützen und diejenigen zu leiten, die im Einklang mit der Wildnis leben.",al={"fraktion von jocaste","wem dient jocaste","loyalität von jocaste"}},["05567dfb"]={q="Was will Jocaste?",a="Jocaste widmet sich der Weitergabe der Traditionen der Jagd. Sie möchte angehende Jäger in Darnassus fördern und sicherstellen, dass sie die Disziplin, das Treffsicherheitsvermögen und die spirituelle Bindung erlernen, die erforderlich sind, um Bestien im Dienste der Natur und ihres Volkes zu zähmen und zu befehligen.",al={"motiv von jocaste","was ist das ziel von jocaste","zweck von jocaste"}},["1febd3fe"]={q="Warum ist Jocaste hier in Darnassus?",a="Jocaste residiert in der Enklave des Cenarius, um Jägern, die die Hauptstadt besuchen, ihre Weisheit und Ausbildung anzubieten. Inmitten der uralten Bäume von Teldrassil bietet sie sowohl angehenden Kundschaftern als auch erfahrenen Wildnispirschern wichtige Unterweisungen.",al={"warum ist jocaste in darnassus","warum ist jocaste in der enklave des cenarius"}}},fp="7,230,23.420.0,15.171.0,25.139.0,42.163.0,47.171.0"}
P.entries["npc:john-j-keeshan"] = {n="John J. Keeshan",s="Korporal John J. Keeshan ist ein menschlicher Soldat der Armee von Sturmwind, der im Rotkammgebirge gegen die Schwarzfelsorcs kämpfte. Nachdem er während der Kämpfe um Steinwacht gefangen genommen wurde, wurde er als Kriegsgefangener tief in Renders Fels verschleppt.",h="Korporal John J.",kw={"john j keeshan","keeshan","missing in action","renders fels","steinwacht"},ang={["class:Warrior"]="Für Krieger ist Keeshan ein düsteres Zeugnis der Gefahren an der Front des Rotkammgebirges, wo selbst abgehärtete Soldaten vom Schwarzfelsklan überwältigt und verschleppt werden können.",["faction:Alliance"]="Keeshan repräsentiert den hohen menschlichen Preis des Krieges der Allianz gegen die Schwarzfelsorcs im Rotkammgebirge: ein Soldat, der gefangen genommen wurde, während er für Sturmwind die Stellung hielt."},sec={{t="Ein Soldat des Rotkammgebirges",b="John J. Keeshan ist ein Korporal im Dienste Sturmwinds, der im Rotkammgebirge stationiert war, als die Schwarzfelsorcs auf Seenhain und dessen Verteidiger vorrückten. Als die Kämpfe um Burg Steinwacht aufflammten, war Keeshan inmitten des Geschehens und hielt zusammen mit den anderen Soldaten die Stellung für das Königreich."},{t="Gefangenschaft in Renders Fels",b="Als der Schwarzfelsklan aus der Brennenden Steppe nach Norden in das Rotkammgebirge vordrang, stand Keeshan unter den Verteidigern, die um Burg Steinwacht kämpften. Von dem Angriff der Orcs überwältigt, wurde er lebend gefangen genommen, anstatt auf dem Schlachtfeld getötet zu werden. Die Invasoren des Schwarzfels verschleppten ihn als Gefangenen in die Tiefen von Renders Fels, wo der Veteran hinter feindlichen Linien eingesperrt blieb, bis Rettungstrupps der Allianz sich einen Weg bahnen konnten, um ihn zu befreien."}},faq={{q="Wer ist John J. Keeshan?",a="John J. Keeshan ist ein Korporal der Armee von Sturmwind, der im Rotkammgebirge gegen die Schwarzfelsorcs kämpfte. Während der Schlacht um Burg Steinwacht wurde er gefangen genommen und nach Renders Fels verschleppt.",al={"keeshan lore","wer ist keeshan","corporal keeshan"}},{q="Warum ist Keeshan in Renders Fels gefangen?",a="Während der Schlacht gegen den Schwarzfelsklan um Burg Steinwacht wurde Keeshan überwältigt, von den Orcs lebend gefangen genommen und zurück zu ihrem Lager in den Höhlen von Renders Fels geschleppt.",al={"warum ist keeshan gefangen","gefangener in renders fels","wie wurde keeshan gefangen genommen"}}},fp="15,241,21.304.0,26.444.1,23.198.0,43.192.0"}
P.entries["npc:jonathan-carevin"] = {n="Jonathan Treuwein",s="Jonathan Treuwein ist ein entschlossener menschlicher Jäger, der in Dunkelhain lebt und sich der Auslöschung der Dunkelheit verschrieben hat, die den Dämmerwald heimsucht. Im Gegensatz zur defensiven Nachtwache jagen er und seine Familie aktiv die Untoten, Worgen und jegliche ketzerischen Bedrohungen, die unter dem finsteren Blätterdach lauern.",h="Jonathan Treuwein ist ein entschlossener menschlicher Jäger, der in Dunkelhain lebt und sich der Auslöschung...",kw={"calor","familie carevin","dunkelhain","dämmerwald","jonathan treuwein","die nachtwache","untote","worgen"},ang={["class:Hunter"]="Jäger finden Gemeinsamkeiten mit Carevins proaktivem Aufspüren und methodischem Ausdünnen der nächtlichen Raubtiere des Dämmerwalds.",["class:Paladin"]="Carevins Eifer und die Anrufung des Lichts gegen dämonische und untote Verderbnis stehen in tiefem Einklang mit den heiligen Gelübden eines Paladins.",["faction:Alliance"]="Für Champions der Allianz, die versuchen, den Dämmerwald zu stabilisieren, führt Jonathan Treuwein gezielte Schläge gegen die übernatürlichen Bedrohungen, die durch die Vernachlässigung seitens Sturmwinds unkontrolliert blieben."},sec={{t="Der Kreuzzug der Carevins",b="Während Dunkelhain sich auf die Nachtwache verlässt, um die Straßen zu bewachen und die Ortschaft zu schützen, glaubt Jonathan Treuwein, dass eine bloße Verteidigungslinie unzureichend ist. Zusammen mit seiner Familie und Verbündeten wie Calor geht Jonathan in die Offensive. Er nimmt gezielt die unheiligen Unholde ins Visier, die den Dämmerwald durchstreifen, und führt einen persönlichen Kreuzzug, um alle Dämonen, Untoten und Ketzer im Lichte der Gnade aus der Region zu tilgen."},{t="Der Schatten der Worgen",b="Jonathans Wachsamkeit beschränkt sich nicht nur auf schlurfende Skelette und Ghule. Er achtet auch genau auf die wilden, wolfsähnlichen Bestien, die als Worgen bekannt sind und die Tiefen des Waldes durchstreifen. Da er weiß, welche Gefahr sie für eine ohnehin belagerte Siedlung darstellen, koordiniert Jonathan Untersuchungen über ihre mysteriöse Anwesenheit, um herauszufinden, woher diese gottlosen Raubtiere stammen, und ihrem nächtlichen Treiben ein Ende zu setzen."}},faq={{q="Wer ist Jonathan Treuwein?",a="Jonathan Treuwein ist ein grimmiger Jäger, der in Dunkelhain im Dämmerwald lebt. Er führt die Familie Carevin in einem aktiven Kampf gegen die abscheulichen Monster an, die den Wald heimsuchen.",al={"wer ist carevin","jonathan treuwein lore","carevin dunkelhain"}},{q="Wie unterscheidet er sich von der Nachtwache?",a="Während sich die Nachtwache in erster Linie darauf konzentriert, die Grenzen von Dunkelhain zu bewachen und die Straßen passierbar zu halten, spüren Jonathan und seine Anhänger die Untoten und andere Abscheulichkeiten aktiv auf und jagen sie, um sie an ihrem Ursprung auszumerzen.",al={"ist er bei der nachtwache","carevin vs nachtwache"}},{q="Welche Bedrohungen bekämpft er?",a="Jonathan jagt aktiv die Untoten, unersättliche Worgenrudel, Dämonen und jeden, der solchen unheiligen Abscheulichkeiten Unterschlupf oder Hilfe gewährt.",al={"was jagt carevin","carevin ziele"}},{q="Gehört Jonathan zum Scharlachroten Kreuzzug?",a="Seine harte Rhetorik, seine inbrünstige Hingabe an das Licht und sein strikter Null-Toleranz-Ansatz gegenüber Verderbnis spiegeln die Überzeugungen der Scharlachroten wider, doch offiziell operiert er unabhängig an der Seite seiner Familie in Dunkelhain.",al={"carevin scharlachroter kreuzzug","ist carevin scharlachrot"}},{q="Wer unterstützt Jonathan bei seiner Mission?",a="Neben seiner engsten Familie erhält Jonathan direkte Unterstützung von sympathisierenden Kämpfern wie Calor, der ihm hilft, monströse Übergriffe im gesamten Wald nachzuverfolgen.",al={"carevin verbündete","wer hilft carevin"}},{q="Was ist seine Verbindung zu den Worgen?",a="Jonathan betrachtet die Worgen als eine unnatürliche Bedrohung, die die Bevölkerung des Dämmerwalds terrorisiert, und beauftragt Reisende damit, die Ursache für ihr plötzliches Auftauchen in der Wildnis aufzudecken.",al={"carevin worgen","warum hasst carevin worgen"}}},fx={["8aa9d9d7"]={q="Was will Jonathan Treuwein?",a="Jonathan Treuwein strebt nichts Geringeres an als die vollständige Ausrottung des Bösen, der Häresie und der Untoten, die den Dämmerwald plagen. Im Gegensatz zur örtlichen Nachtwache, die sich darauf konzentriert, Dunkelhain hinter Verteidigungslinien sicher zu halten, glaubt Jonathan daran, in die Offensive zu gehen. Er möchte aktiv dämonische und untote Streitkräfte jagen und die Region unter der rechtschaffenen Macht des Lichts von Verderbnis reinigen.",al={"ziele von jonathan treuwein","was ist das ziel von treuwein","mission von treuwein"}},["24497d50"]={q="Warum ist Jonathan Treuwein in Dunkelhain?",a="Dunkelhain ist die Frontlinie eines schattendurchfluteten Landes, das von Ghulen, Skeleten und dunkleren Schrecken überrannt wird. Jonathan Treuwein und seine Familie haben es sich zur persönlichen Aufgabe gemacht, hier standzuhalten, Angriffe gegen die Untoten zu koordinieren und jeden fähigen Abenteurer zu versammeln, der bereit ist, gegen die Schrecken, die unter den verdunkelten Ästen des Dämmerwaldes lauern, zu den Waffen zu greifen.",al={"warum ist treuwein in dunkelhain","warum ist jonathan treuwein hier","grund für treuweins präsenz im dämmerwald"}}},fp="16,277,19.410.0,24.412.1,24.160.0,40.231.0,27.137.0,48.203.0,36.171.0,37.170.0"}
P.entries["npc:jordan-stilwell"] = {n="Jordan Stillbrunn",s="Jordan Stillbrunn ist ein geschickter menschlicher Waffenschmied, der vor den verschneiten Toren von Eisenschmiede in Dun Morogh stationiert ist. Obwohl er ursprünglich dazu bestimmt war, ein Paladin des Heiligen Lichts zu werden, folgte er dem Handwerk seines Vaters und wurde zu einem Kunstschmied, dessen Werk Paladinen der gesamten Allianz dient. Am bekanntesten ist er für das Schmieden von Verigans Faust zu Ehren seines alten Freundes Bosch Verigan.",h="Jordan Stillbrunn ist ein geschickter menschlicher Waffenschmied, der vor den verschneiten Toren von...",kw={"bailor steinhand","bosch verigan","daphne stillbrunn","dun morogh","eisenschmiede","jordan stillbrunn","burg shadowfang","foliant der ehre","verigans faust"},ang={["class:Paladin"]="Jordan Stillbrunn ist eine zentrale Gestalt in den frühen Prüfungen eines Paladins, den er damit beauftragt, ganz Azeroth nach seltenen Bestandteilen abzusuchen, um dessen charakteristischen Kriegshammer, Verigans Faust, zu schmieden.",["faction:Alliance"]="Nachdem er den Schrecken von Arugals Worgen im Silberwald entkommen war, fand Jordan Zuflucht bei den Zwergen von Dun Morogh und stellt sein Handwerk nun direkt in den Dienst der Streiter der Allianz.",["profession:Blacksmithing"]="Ausgebildet von dem Zwerg Bailor Steinhand und ausgerüstet mit einem verzauberten Hammer, den er von seinem Vater erbte, verkörpert Jordan den Gipfel der sterblichen heiligen Schmiedekunst."},sec={{t="Eine Berufung am Amboss",b="Obwohl von Jordan Stillbrunn erwartet wurde, die heiligen Gelübde abzulegen und ein Paladin der Kirche des Heiligen Lichts zu werden, wählte er letztlich den Weg der Schmiede. Er trat in die Fußstapfen seines Vaters und ergriff dessen verzauberten Schmiedehammer. Jordan verfeinerte sein Handwerk unter der Anleitung des Zwergenschmieds Bailor Steinhand. Obwohl er das Gewand eines gesalbten heiligen Kriegers ablegte, bleibt Jordan dem Licht tief verbunden und widmet seine außergewöhnliche Handwerkskunst der Ausrüstung von Streitern, die in seinem Namen kämpfen."},{t="Die Flucht aus dem Silberwald",b="Lange bevor er seine Werkstatt in der schneidenden Kälte von Dun Morogh einrichtete, diente Jordan als Schmied auf der Feste von Baron Silberlein im Silberwald. Als Erzmagier Arugal die wilden Worgen auf die Festung losließ und sie in die verfluchte Bastion namens Burg Shadowfang verwandelte, gelang Jordan die Flucht vor dem Blutvergießen. Gezwungen, seine Schmiede und seine frühere Heimat aufzugeben, fand er schließlich Zuflucht bei den Zwergen von Dun Morogh."},{t="Das Schmieden von Verigans Faust",b="Jordan betreibt seine Schmiede im Freien nahe den Toren von Eisenschmiede und zieht die frische Alpenluft der erstickenden Hitze der Großen Schmiede im Inneren des Berges vor. Wenn die Kirche des Heiligen Lichts würdige Paladine zu ihm entsendet, beauftragt Jordan sie damit, seltene Materialien aus der ganzen Welt zu beschaffen, um einen legendären zweihändigen Kriegshammer zu fertigen. Benannt als Verigans Faust zu Ehren seines alten Freundes Bosch Verigan, steht die Waffe als Zeugnis für das unvergängliche Band zwischen tiefem Glauben und meisterhaftem Stahl."}},faq={{q="Wer ist Jordan Stillbrunn?",a="Jordan Stillbrunn ist ein menschlicher Meisterschmied, der vor den Toren von Eisenschmiede in Dun Morogh arbeitet. Er fertigt heilige Rüstungen und Waffen für Paladine der Kirche des Heiligen Lichts an, vor allem den legendären Kriegshammer Verigans Faust.",al={"wer ist jordan stillbrunn","jordan stillbrunn geschichte","wer ist der schmied vor eisenschmiede"}},{q="Warum arbeitet Jordan Stillbrunn draußen im Schnee statt im Inneren von Eisenschmiede?",a="Laut Duthorian Rall in Sturmwind zieht Jordan die kühle, klare Bergluft von Dun Morogh dem stickigen Inneren der Großen Schmiede in Eisenschmiede vor.",al={"warum ist jordan vor eisenschmiede","warum arbeit in dun morogh","warum steht er im schnee"}},{q="Welche Verbindung hat Jordan Stillbrunn zu Burg Shadowfang?",a="Jordan war einst Rüstungsschmied und Grobschmied auf dem Anwesen von Baron Silberlein im Silberwald. Es gelang ihm, vor oder während des verheerenden Aufstands aus der Burg zu fliehen, als Erzmagier Arugal und seine wilden Worgen die Besatzung niedermachten und die Festung einnahmen.",al={"jordan stillbrunn burg shadowfang","jordan stillbrunn silberwald","lebte er in pyrewood"}},{q="Was ist Verigans Faust?",a="Verigans Faust ist ein mächtiger zweihändiger heiliger Hammer, der von Jordan Stillbrunn für Allianz-Paladine geschmiedet wird. Er ist zu Ehren von Jordans altem Freund Bosch Verigan benannt.",al={"verigans faust","verigan hammer","wer ist verigan"}},{q="Wer bildete Jordan Stillbrunn im Schmieden aus?",a="Jordan erbte sein Handwerk und einen verzauberten Schmiedehammer von seinem Vater und verfeinerte seine Fertigkeiten anschließend unter der Unterweisung des Zwergenschmieds Bailor Steinhand.",al={"wer bildete jordan stillbrunn aus","jordan stillbrunn lehrer","wo lernte er schmieden"}},{q="Wer ist die Frau von Jordan Stillbrunn?",a="Jordan ist mit Daphne Stillbrunn verheiratet. Gemeinsam hat das Paar der Kirche des Heiligen Lichts über die Jahre hinweg immens beigestanden, und beide werden als zutiefst fromme Diener des Glaubens verehrt.",al={"jordan stillbrunn ehefrau","daphne stillbrunn ehemann","daphne stillbrunn"}}},fx={["49deb919"]={q="Auf wessen Seite steht Jordan Stillbrunn?",a="Jordan ist der Allianz und der Kirche des Heiligen Lichts treu ergeben. Obwohl er unter den Zwergen in Dun Morogh lebt und sein Handwerk außerhalb von Eisenschmiede ausübt, bleibt er eng mit den Paladinen von Sturmwind verbunden und widmet sein Handwerk der Bewaffnung der Gläubigen gegen die Dunkelheit, die das Reich bedroht.",al={"fraktion von jordan stillbrunn","ist jordan stillbrunn allianz","loyalität von jordan stillbrunn"}}},fp="15,358,22.527.0,22.418.0,22.491.1,23.230.0,78.181.0,56.266.0,23.160.0,45.178.0,30.192.0"}
P.entries["npc:jorgen"] = {fx={["536f8488"]={q="Wer ist Jorgen?",a="Jorgen ist eine zwielichtige Gestalt, die sich ruhig unten am Wasser im Tal der Helden aufhält, gleich hinter den großen Vordertoren von Sturmwind. Anstatt in irgendeiner offiziellen zivilen Funktion zu dienen, agiert er am Rande der Angelegenheiten der Hauptstadt und besitzt tiefe Verbindungen und eine nicht enthüllte Vergangenheit, die eng mit Meister Elling Trias und Bischof DeLavey verknüpft ist.",al={"wer ist jorgen","jorgen in sturmwind","identität von jorgen"}},["846a3fb1"]={q="Warum ist Jorgen hier?",a="Jorgen hält sich am Rande des Tals der Helden auf, um als diskreter Kontaktpunkt innerhalb von Sturmwind zu fungieren. Direkt in der Nähe der Stadttore und fernab von neugierigen Blicken positioniert, bleibt er verfügbar, um vertrauenswürdigen Kontakten wie Elling Trias zu helfen, wann immer heikle, verdeckte Nachforschungen diskret gehandhabt werden müssen.",al={"warum ist jorgen hier","grund für jorgens standort","warum ist jorgen in sturmwind"}}}}
P.entries["npc:josef-gregorian"] = {n="Josef Gregorian",s="Josef Gregorian ist ein Schneidereilehrer der Verlassenen, der im Magieviertel von Unterstadt arbeitet. Er leitet ehrgeizige Schneider der Horde an, die verzauberte Stoffe weben wollen, teilt sein Fachwissen mit ihnen und weist ihnen den Weg zu spezialisierten Gewändern.",h="Josef Gregorian ist ein Schneidereilehrer der Verlassenen, der im Magieviertel von Unterstadt arbeitet.",kw={"materialsammlung","josef gregorian","magieviertel","roben des zauberfeuers","schneidereilehrer","unterstadt"},ang={["profession:Tailoring"]="Für Tuchmacher der Horde ist Josef Gregorian eine erstklassige Anlaufstelle in Lordaeron; er unterrichtet Schneider und fertigt Roben für junge Magier, die ihm die nötigen Materialien bringen.",["race:Undead"]="Gregorian beweist, dass die feine Kunst der menschlichen Schneiderei trotz Tod und Untod den Fall von Lordaeron überstanden hat, um nun der neuen Gesellschaft der Verlassenen zu dienen."},sec={{t="Weber des Magieviertels",b="Inmitten der trüben alchemistischen Laternen und feuchten Gewölbe des Magieviertels pflegt Josef Gregorian das feine Handwerk der Schneiderei für die Verlassenen und ihre Verbündeten der Horde. Auch wenn das Leben im unterirdischen Königreich kalt geworden ist, bleibt die Stoffverarbeitung für Hexenmeister, Magier und Priester, die rohe Energien durch gewebte Fasern leiten, unverzichtbar. Gregorian dient in der Hauptstadt als verlässlicher Ausbilder, stets bereit, grundlegende Schnittmuster zu lehren und die ersten Roben junger Magier zu nähen, die ihm die passenden Materialien bringen."}},faq={{q="Wo kann ich Josef Gregorian finden?",a="Josef Gregorian befindet sich im Magieviertel von Unterstadt, wo er inmitten der Zauberwirker und Gelehrten der Stadt das Schneiderhandwerk ausübt und lehrt.",al={"josef gregorian aufenthaltsort","wo ist gregorian","unterstadt schneidereilehrer"}},{q="Welche Rolle spielt Josef Gregorian in Unterstadt?",a="Er ist ein Schneidereilehrer, der Handwerkern der Horde Schneiderrezepte und Techniken beibringt. Zudem näht er die ersten Roben junger Magier, die von Anastasia Hirschbrunn zu ihm geschickt werden.",al={"was macht josef gregorian","josef gregorian lehrer","unterstadt schneiderei"}},{q="Welche Quests bietet Josef Gregorian an?",a="Gregorian nimmt an einer Questreihe für Magier teil: Anastasia Hirschbrunn schickt junge Magier mit Leinenstoff und in Silberwald erbeuteten Dalaran-Manasteinen zu ihm (Materialsammlung), woraufhin er ihnen Roben des geringen Zauberfeuers näht (Roben des Zauberfeuers).",al={"josef gregorian quests","roben quests unterstadt"}}},fx={d179720d={q="Wer ist Josef Gregorian?",a="Josef Gregorian ist ein untoter Handwerker, der als Schneiderlehrer im Magieviertel der Unterstadt dient. Wie viele Handwerker der Verlassenen hat er die feinen Fertigkeiten seines früheren Lebens bewahrt und setzt sein Wissen über Fäden, Stoffe und verzauberte Gewänder für das Volk von Königin Sylvanas und deren Verbündete der Horde ein.",al={"wer ist josef gregorian","hintergrund von josef gregorian","wer ist der schneider josef gregorian"}},["057f78ac"]={q="Auf wessen Seite steht Josef Gregorian?",a="Er ist den Verlassenen und der Horde loyal. Tief in der Unterstadt stationiert, bietet er sein Wissen über Schneiderei, Schnittmuster und handwerkliche Weisheit ausschließlich denjenigen an, die im Dienste der Dunklen Fürstin und der Horde stehen.",al={"fraktion von josef gregorian","ist josef gregorian horde","wem dient josef gregorian"}},["3b87a245"]={q="Warum ist Josef Gregorian in der Unterstadt?",a="Josef bleibt in der Unterstadt, um das Schneiderhandwerk auszuüben und andere darin zu unterrichten. Sein Workshop inmitten der Zauberwirker und Gelehrten des Magieviertels ermöglicht es ihm, Roben, verzauberte Gewänder und Stoffrüstungen für Abenteurer zu weben, die sich in die Pestländer und darüber hinaus wagen.",al={"warum ist josef gregorian hier","was brachte josef gregorian in die unterstadt","warum ist josef im magieviertel"}}},fp="15,238,27.506.0,33.148.0,54.169.0,39.241.0"}
P.entries["npc:kaal-soulreaper"] = {fx={["17865f78"]={q="Auf wessen Seite steht Kaal Seelentod?",a="Kaal Seelentod steht fest an der Seite der Horde. Obwohl er ein Orc ist, der neben den Verlassenen in der Unterstadt lebt, bildet er Hexenmeister aus, die der Sache der Horde die Treue schwören. Er unterhält direkte Verbindungen zu anderen Praktizierenden der Horde in ganz Kalimdor und den Östlichen Königreichen, einschließlich Hexenmeistern im Brachland und Ratschet, und stellt sicher, dass diejenigen, die dunkle Künste ausüben, ihre Teufelsmacht weiterhin darauf ausrichten, ihren Verbündeten zu helfen.",al={"fraktion von kaal seelentod","wem dient kaal seelentod","ist kaal seelentod horde"}},["78b7a2d4"]={q="Was will Kaal Seelentod?",a="Kaal versucht, angehende Hexenmeister auf dem gefährlichen Pfad der dämonischen Meisterschaft zu leiten. Anstatt unerfahrene Praktizierende den verderbenden Mächten des Wirbelnden Nether erliegen zu lassen, stellt er sicher, dass sie die notwendigen Riten erlernen, um Dämonen wie das Teufelsross zu beschwören und zu binden, und verweist vielversprechende Schüler an erfahrene Meister wie Menara Leerbringer, um ihr Handwerk zu vertiefen.",al={"motiv von kaal seelentod","ziel von kaal seelentod","was tut kaal seelentod"}}}}
P.entries["npc:kadrak"] = {fx={e1636f20={q="Auf wessen Seite steht Kadrak?",a="Kadrak ist ein loyaler Krieger der Horde. Stationiert an der zerklüfteten Grenze zwischen dem Brachland und den umkämpften Wäldern des Eschentals, dient er unter dem Banner des Kriegshäuptlings, bestrebt, die Interessen der Orcs zu sichern und Außenposten der Horde gegen Einfälle der Nachtelfen zu verteidigen.",al={"fraktion von kadrak","ist kadrak horde","wem dient kadrak"}},["4dfee007"]={q="Was will Kadrak?",a="Kadrak zielt darauf ab, die nördliche Grenze des Brachlands zu halten und die Präsenz der Horde tiefer in das Eschental voranzutreiben. Angesichts heftigen Widerstands der Nachtelfen sucht er nach fähigen Champions der Horde, um Berichte zu überbringen, bedrängte Kundschafter abzulösen und wichtige Versorgungslinien über den Mor'shan-Schutzwall zu schützen.",al={"was ist das ziel von kadrak","motiv von kadrak","was benötigt kadrak"}},["86a4d862"]={q="Warum ist Kadrak hier am Mor'shan-Schutzwall?",a="Kadrak hält Wache am Mor'shan-Schutzwall, weil er der entscheidende Engpass ist, der das Brachland vor den feindseligen Wäldern des Eschentals schützt. Während die Feindseligkeiten mit den Nachtelfen aufflammen, koordiniert er die Verteidigung, überwacht feindliche Aktivitäten und weist Kundschafter an, die Außenposten der Kriegshymnenklans im Norden zu verstärken.",al={"warum ist kadrak am schutzwall","grund für kadraks standort","warum ist kadrak hier stationiert"}}}}
P.entries["npc:kaela-shadowspear"] = {fx={bb8cec73={q="Warum ist Kaela Schattenspeer hier?",a="Kaela ist südwestlich der Scherwindklippe als Wachposten-Späherin stationiert. Von diesem Außenposten aus überwacht sie Störungen im gesamten Steinkrallengebirge, insbesondere das Schicksal der verderbten lokalen Geister und die Not der nahegelegenen Uralten.",al={"warum ist kaela schattenspeer im steinkrallengebirge","mission von kaela schattenspeer","warum ist kaela hier"}},e879ebe3={q="Auf wessen Seite steht Kaela Schattenspeer?",a="Kaela steht fest an der Seite der Nachtelfen und der Allianz. Stationiert im Steinkrallengebirge, dient sie Darnassus und dem Kommando der Sentinel, wobei sie sich eng mit anderen Kundschaftern der Allianz abstimmt, um das Land gegen eindringende Gegner zu verteidigen.",al={"fraktion von kaela schattenspeer","ist kaela allianz","loyalität von kaela schattenspeer"}}}}
P.entries["npc:kali-remik"] = {n="Kali Remik",s="Kali Remik ist eine Jägerin der Dunkelspeertrolle, die ihre Zeit damit verbringt, Reisenden im Kerngebiet der Horde mit Rat und Tat zur Seite zu stehen. Da sie mit den Methoden der Fährtenleserei und des Überlebens in Durotar bestens vertraut ist, verweist sie junge Jäger an Thotar in Klingenhügel, damit diese dort die Zähmung von Wildtieren erlernen.",h="Kali Remik ist eine Jägerin der Dunkelspeertrolle, die ihre Zeit damit verbringt, Reisenden im Kerngebiet der...",kw={"dunkelspeer","durotar","kali remik","sen'jin","der weg des jägers","fährtenleser","tal der geister"},ang={["class:Hunter"]="Für junge Orc- und Trollschützen fungiert Kali als Sprungbrett; sie erkennt, wenn Eure Fähigkeiten über die Übungen im Dorf hinausgehen und schickt Euch weiter zu Thotar nach Klingenhügel.",["race:Troll"]="Als Mitglied des Dunkelspeerstamms hält Kali Wache über ihr Volk, während dieses sein Leben entlang der Küste von Durotar wieder aufbaut und sich im Tal der Geister von Orgrimmar niederlässt."},sec={{t="Ein Leitfaden für die Jagd",b="Kali Remik ist eine erfahrene Dschungeltroll-Späherin, die mit den trockenen Einöden von Durotar und den geschäftigen Zentren der Horde bestens vertraut ist. In Küstensiedlungen wie Sen'jin wacht sie über junge Späher, die ihre ersten Schritte außerhalb vom Tal der Prüfungen unternehmen. Wenn sie erkennt, dass ein Neuling den örtlichen Trainingsgeländen entwachsen ist, greift sie ein und weist vielversprechende Schützen den Weg zu Thotar in Klingenhügel, damit diese dort ihre Ausbildung zum Tierherrscher beginnen können, um so sicherzustellen, dass die Reihen der Grenzschützer der Horde scharf und diszipliniert bleiben."}},faq={{q="Wer ist Kali Remik?",a="Kali Remik ist eine Späherin der Dunkelspeertrolle und eine Questgeberin. Sie hilft dabei, junge Abenteurer der Horde anzuleiten, insbesondere Jäger, die bereit sind, ihre Ausbildung über die örtlichen Außenposten hinaus fortzusetzen.",al={"kali remik hintergrundgeschichte","wer ist kali remik","kali remik npc"}},{q="Wo kann man Kali Remik finden?",a="Sie kann dabei angetroffen werden, wie sie ihrem Volk in Durotar beisteht, vor allem in der Umgebung von Sen'jin.",al={"wo ist kali remik","kali remik standort","kali remik finden"}},{q="Welche Anleitung bietet sie Jägern?",a="Durch 'Der Pfad des Jägers' weist Kali junge Orc- und Trolljäger, die ihre grundlegenden Fähigkeiten unter Beweis gestellt haben, an, nach Klingenhügel zu reisen, wo Thotar sie auf den Pfad bringt, ein eigenes Wildtier als Begleiter zu zähmen.",al={"quest der pfad des jägers","kali remik jägerquest","was lehrt kali"}}},fx={f072d80b={q="Auf welcher Seite steht Kali Remik?",a="Kali Remik ist dem Stamm der Dunkelspeere treu ergeben und steht fest zur Horde von Thrall. Sie unterstützt ihr Volk und dessen Verbündete, indem sie junge Kundschafter der Wildnis und Schützen anleitet, damit diese eine angemessene Ausbildung erhalten und ihrem neuen Zuhause dienen können.",al={"fraktion von kali remik","wem dient kali remik","kali remik horde"}},bd47d9e0={q="Warum ist Kali Remik im Sen'jin?",a="Kali Remik bleibt im Sen'jin, um über die aufstrebenden Verteidiger des Stammes der Dunkelspeere zu wachen. In diesen Küstengewässern hilft sie dabei, vielversprechende junge Jäger unter den Orcs und Trollen zu identifizieren, die den Ort passieren, und verweist sie an die Ausbilder, die ihre Überlebensfertigkeiten verfeinern können.",al={"warum ist kali remik hier","rolle von kali remik im sen'jin","was brachte kali remik hierher"}},a3912784={q="Was will Kali Remik?",a="Kali Remik möchte, dass Durotar von fähigen Kundschaftern und Stalkern geschützt wird. Sie sucht nach angehenden Jägern, um sicherzustellen, dass sie nicht unvorbereitet umherirren, und weist ihnen den richtigen Weg zu den Ausbildern, die ihnen die Wege der Wildnis lehren können.",al={"was will kali remik","motivation von kali remik","was ist das ziel von kali remik"}},["528bbb7d"]={q="Wem ist Kali Remik verbunden?",a="Sie ist eng mit den Dunkelspeertrollen im Sen'jin verbunden und arbeitet eng mit den Jägerausbildern in Durotar zusammen. Ihre Pflichten verknüpfen sie mit dem breiteren Überlebensnetzwerk der Horde, wodurch sichergestellt wird, dass neue Rekruten Kontakt zu etablierten Mentoren in ihrem gesamten Gebiet aufnehmen.",al={"wem ist kali remik verbunden","verbindungen von kali remik","verbündete von kali remik"}}},fp="10,259,20.489.0,18.173.0,30.78.0,40.206.0"}
P.entries["npc:kaltunk"] = {n="Kaltunk",s="Kaltunk ist ein Orc-Aufseher, der im Herzen vom Tal der Prüfungen in Durotar stationiert ist. Er dient als allererste Anlaufstelle für junge Orcs, die ihre ersten Schritte in die Welt wagen. Es ist seine Pflicht, diese aufstrebenden Champions willkommen zu heißen und sie zu ihren anfänglichen Aufgaben im Dienst der Horde zu leiten.",h="Kaltunk ist ein Orc-Aufseher, der im Herzen vom Tal der Prüfungen in Durotar stationiert ist.",kw={"durotar","gornek","kaltunk","orc-startgebiet","das tal der prüfungen","your place in the world"},ang={["faction:Horde"]="Kaltunk hilft dabei, die praktische Disziplin aufrechtzuerhalten, die nötig ist, um die Ordnung auf dem rauen Übungsgelände von Durotar zu wahren.",["race:Orc"]="Für jeden Orc, der hinaus nach Kalimdor zieht, sind Kaltunks barsche Anweisungen die ersten Worte, die er hört, während er beginnt, sich seine Ehre zu verdienen."},sec={{t="Der erste Schritt",b="Unter der sengenden Sonne vom Tal der Prüfungen wacht Kaltunk über die neu eingetroffenen Hoffnungsträger, die sich der Horde als würdig erweisen wollen. Während andere Ausbilder und Älteste zermürbende Prüfungen und Jagdriten zuweisen, sorgt Kaltunk dafür, dass kein Rekrut ziellos durch den roten Staub irrt. Er erteilt unmissverständliche Befehle und weist Neulinge direkt an Gornek und auf den Pfad der Disziplin."},{t="Hüter des Tals",b="Das Tal der Prüfungen ist kein einfaches Übungsgelände; es wurde eigens ausgewählt, um die Stärke und Widerstandskraft jedes Jugendlichen zu schmieden, der seine Schluchtböden betritt. Kaltunk verkörpert diese raue Zweckmäßigkeit. Er hält keine großen Reden und verhätschelt niemanden, sondern erwartet von jedem Orc, dass er rasch seinen Platz in der Welt findet und seinen Teil für den Kriegshäuptling beiträgt."}},faq={{q="Wer ist Kaltunk?",a="Kaltunk ist ein Orc-Aufseher, der im Tal der Prüfungen stationiert ist. Er ist die allererste Person, der neu erwachte Orc-Abenteurer begegnen, und hat die Aufgabe, sie an ihre Mentoren zu verweisen und ihre Ausbildung in Gang zu setzen.",al={"kaltunk rolle","wer ist dieser orc","kaltunk nsc"}},{q="Was tut Kaltunk für neue Abenteurer?",a="Er gibt neuen Rekruten ihre erste Aufgabe und schickt sie los, um mit Gornek an einem anderen Ort im Tal zu sprechen, damit ihr eigentliches Training beginnen kann.",al={"kaltunk quest","was will kaltunk","erste quest tal der prüfungen"}},{q="Wo kann ich Kaltunk finden?",a="Er steht direkt beim zentralen Ausbildungszelt und dem Lagerfeuer im Tal der Prüfungen, dem abgelegenen Startgebiet im südlichen Durotar.",al={"kaltunk aufenthaltsort","kaltunk finden","wo ist kaltunk"}},{q="Warum ist er im Tal der Prüfungen stationiert?",a="Er fungiert als empfangender Aufseher, um sicherzustellen, dass eintreffende Orc-Rekruten organisiert und unverzüglich auf ihren Pfad im Dienst für Thralls Horde geleitet werden.",al={"warum ist kaltunk hier","kaltunk zweck"}}},fx={["7b0fd1f8"]={q="Auf wessen Seite steht Kaltunk?",a="Kaltunk dient der Horde und steht fest unter dem Befehl von Kriegshäuptling Thrall. Er ist im Tal der Prüfungen stationiert, speziell um neue Orc-Rekruten willkommen zu heißen und ihre ersten Schritte in den Dienst für die neue Nation Durotar zu lenken.",al={"kaltunk fraktion","wem dient kaltunk","ist kaltunk horde"}},["5cbb3fad"]={q="Was will Kaltunk?",a="Kaltunk will, dass Ihr Euch vor der Horde beweist. Er stellt sicher, dass untätige Neuankömmlinge nicht herumlungern, und weist Euch umgehend an Gornek und die Aufseher im Tal der Prüfungen weiter, damit Eure Ausbildung und Euer Dienst für Durotar ohne Verzögerung beginnen können.",al={"was braucht kaltunk","kaltunk ziel","kaltunk motiv"}}},fp="7,304,14.402.0,20.339.0,15.207.0,41.135.0,25.139.0,44.142.0"}
P.entries["npc:kam-deepfury"] = {n="Kam Tiefenzorn",s="Kam Tiefenzorn ist ein berüchtigter Saboteur der Dunkeleisenzwerge, der in den Tiefen des Verlieses von Sturmwind eingekerkert ist. Anders als die Mehrheit der Insassen des Gefängnisses hegt er keinerlei Loyalität gegenüber der Bruderschaft der Defias; er wurde gefangen genommen, weil er weit im Norden eine verheerende Explosion am Thandol-Übergang inszeniert hatte.",h="Kam Tiefenzorn ist ein berüchtigter Saboteur der Dunkeleisenzwerge, der in den Tiefen des Verlieses von...",kw={"dunkeleisenzwerge","deepfury","dun modr","garmason","kam tiefenzorn","longbraid","das verlies","sturmwind","thandol-übergang"},ang={["faction:Alliance"]="Während die meisten Blicke in Sturmwind auf den Defias-Aufstand gerichtet sind, ist Deepfury eine Mahnung an die umfassendere Bedrohung durch die Dunkeleisenzwerge, welche die nördlichen Grenzen der Allianz heimsucht.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede ist Kam Tiefenzorn ein verhasster Feind, dessen Sabotage den Thandol-Übergang zerstörte und die Sippe von Langzopf dem Grimmigen ermordete. Diesen Verlust zu rächen, ist eine Frage der persönlichen Ehre."},sec={{t="Ein Saboteur fern der Heimat",b="Während das Verlies überwiegend mit unzufriedenen Steinmetzen und Defias-Rebellen gefüllt ist, sticht Kam Tiefenzorn heraus. Als gerissener und gewalttätiger Dunkeleisenzwerg wurde Deepfury gefasst und nach Sturmwind gebracht, nachdem er eine Operation geleitet hatte, die lebenswichtige nördliche Infrastruktur lahmlegte. Er sitzt tief in den Zellen des Gefängnisses ein, isoliert von seiner Sippe unter dem Schwarzfels, doch der Allianz gegenüber ebenso feindselig gesinnt wie jeder rebellische Aufrührer, der die Korridore mit ihm teilt."},{t="Die Sabotage am Thandol-Übergang",b="Die in Dun Modr nahe der nördlichen Grenze des Sumpflands stationierten Aufklärer der Allianz identifizierten Deepfury als den Haupturheber der Explosion, die den Thandol-Übergang zerriss. Die Detonation zerstörte eine der gewaltigen Steinbrücken, die das Sumpfland mit dem Arathihochland verbinden. Neben der Zerstörung einer für Eisenschmiede und die Allianz entscheidenden Handels- und Militärroute forderte der Sabotageakt das Leben eines Verwandten des Zwergenkommandanten Langzopf der Grimmige."},{t="Eine offene Rechnung",b="Der Aufständische der Dunkeleisenzwerge konnte der Vergeltung nicht lange entgehen, wenngleich die Inhaftierung in Sturmwind ihm vorübergehenden Schutz vor den Verwandten seiner Opfer bot. Zurück im Sumpfland haben Motley Garmason und der trauernde Langzopf der Grimmige Söldner gesucht, die bereit sind, das von Aufständen erschütterte Gefängnis zu infiltrieren und Deepfurys Kopf abzutrennen, um eine blutige Fehde beizulegen, die hunderte Meilen weiter nördlich ihren Anfang nahm."}},faq={{q="Wer ist Kam Tiefenzorn?",a="Kam Tiefenzorn ist ein gefangener Elite-Dunkeleisenzwerg, der im Verlies von Sturmwind eingesperrt ist. Er ist dafür bekannt, die Sabotage am Thandol-Übergang im Norden angezettelt zu haben, und hat keinerlei Verbindungen zu den neben ihm inhaftierten Defias-Rebellen.",al={"wer ist deepfury","kam tiefenzorn lore","wer ist der zwerg im verlies"}},{q="Warum sitzt ein Dunkeleisenzwerg im Verlies von Sturmwind ein?",a="Deepfury wurde gefasst, nachdem er einen Angriff koordiniert hatte, der eine der Brücken am Thandol-Übergang sprengte, zwergische Verteidiger tötete und einen lebenswichtigen Landweg zwischen dem Sumpfland und Arathi abschnitt. Er wurde in das Hochsicherheitsgefängnis von Sturmwind überstellt, um seiner Strafe harrte.",al={"warum ist er im verlies","was hat kam tiefenzorn getan","warum ist er eingesperrt"}},{q="Gehört Kam Tiefenzorn zur Bruderschaft der Defias?",a="Nein. Obwohl er während ihres Aufstands im Verlies an der Seite der Bruderschaft der Defias gefangen gehalten wird, gehört Deepfury zum feindseligen Dunkeleisen-Klan. Er handelt gänzlich nach den aggressiven Plänen seines eigenen Klans gegen die Allianz und Eisenschmiede.",al={"gehört er zu den defias","kam tiefenzorn defias","arbeitet deepfury mit vancleef zusammen"}},{q="Wer will Kam Tiefenzorn tot sehen?",a="Motley Garmason und die in Dun Modr stationierten Zwergentruppen aus Eisenschmiede wollen seinen Tod. Langzopf der Grimmige verlor bei Deepfurys Sprengung des Thandol-Übergangs einen Verwandten, weshalb sie Abenteurer in Sturmwind dazu aufriefen, seinen Kopf zu fordern.",al={"wer vergibt die quest für deepfury","wer will deepfury tot sehen"}},{q="Wo hat Kam Tiefenzorn sein Verbrechen begangen?",a="Deepfury organisierte die Sabotage am Thandol-Übergang, dem kolossalen Brückenkomplex, der das Sumpfland weit nördlich von Sturmwind mit dem Arathihochland verbindet.",al={"wo wurde die brücke gesprengt","deepfury brückensprengung","angriff auf thandol-übergang"}},{q="Wo ist Kam Tiefenzorn im Verlies zu finden?",a="Kam Tiefenzorn wird in den Zellenblöcken des Verlieses von Sturmwind gefangen gehalten, welches sich unter dem Kanalviertel von Sturmwind befindet.",al={"wo ist deepfury im verlies","kam tiefenzorn standort"}}},fx={["1bde1b20"]={q="Mit wem ist Kam Tiefenzorn verbündet?",a="Kam Tiefenzorn gehört dem feindseligen Clan der Dunkeleisenzwerge an. Obwohl er zusammen mit rebellischen Taschendieben und Sträflingen in der Stormwind Stockade festgehalten wird, hat er keine Verbindungen zur The Defias Brotherhood. Seine Loyalität gilt ausschließlich seinem eigenen zwielichtigen Clan, der weit nördlich seiner Heimat operiert, um tief in das von der Allianz kontrollierte Gebiet einzudringen.",al={"verbindungen von kam tiefenzorn","für wen arbeitet kam tiefenzorn","kam tiefenzorn fraktion"}},["45416a5d"]={q="Warum ist Kam Tiefenzorn berüchtigt?",a="Kam Tiefenzorn erlangte seine düstere Berühmtheit, indem er die katastrophale Explosion anführte, die eine der massiven Steinbrücken über The Thandol Span zertrümmerte. Die gewaltsame Sabotage gefährdete nicht nur eine entscheidende Verbindung zwischen dem Sumpfland und dem Arathihochland, sondern forderte auch das Leben eines Zwergenverwandten von Langzopf der Grimmigen.",al={"ruf von kam tiefenzorn","warum wird kam tiefenzorn gefürchtet","was hat kam tiefenzorn getan"}}},fp="12,301,24.459.0,25.447.0,17.404.1,20.226.0,58.266.0,47.242.0,28.238.0,40.154.0,52.125.0"}
P.entries["npc:kanati-greycloud"] = {fx={["35c73e38"]={q="Auf wessen Seite steht Kanati Grauwolke?",a="Kanati Grauwolke ist ein Tauren-Jäger, der der Horde loyal gegenübersteht. Er heißt Reisende der Horde willkommen, die Weißgipfelposten besuchen, und verlässt sich darauf, dass sie ihm helfen, sein Lager vor feindlichen Bedrohungen in der Schlucht zu verteidigen.",al={"kanati fraktion","ist kanati horde","kanati allianz oder horde"}},cf857b32={q="Was will Kanati Grauwolke?",a="Kanati möchte einfach nur sein Jagdlager in Frieden aufrechterhalten und sicherstellen, dass seine Gefährten überleben. Da die örtlichen Galak-Zentauren darauf aus sind, alle Eindringlinge zu vertreiben oder abzuschlachten, ist seine Hauptsorge die Verteidigung gegen ihre Attentatsversuche.",al={"was braucht kanati","kanati grauwolke ziele","warum kanati helfen"}},["10a1bee5"]={q="Warum ist Kanati Grauwolke hier?",a="Kanati errichtete zusammen mit seinen Gefährten ein Jagdlager bei Weißgipfelposten, um in Tausend Nadeln auf die Jagd zu gehen. Leider brachte ihn der Aufbau des Lagers in der Schlucht genau in das Gebiet, das von den feindseligen Galak-Zentauren umkämpft wird.",al={"warum ist kanati bei weißgipfelposten","was macht kanati hier","zweck von kanati grauwolke"}}}}
P.entries["npc:kaplak"] = {n="Kaplak",s="Kaplak ist ein Orc-Schurkenlehrer, der in Klingenhügel im zentralen Durotar stationiert ist. Er unterweist junge Orcs und Trolle in den Künsten der Täuschung, der Heimlichkeit und der Klingenführung, um sie auf ihren Dienst für die Horde vorzubereiten, bevor er sie nach Orgrimmar weiterschickt.",h="Kaplak ist ein Orc-Schurkenlehrer, der in Klingenhügel im zentralen Durotar stationiert ist.",kw={"durotar","kaplak","orc","orgrimmar","klingenhügel","schurkenlehrer","verstohlenheit","therzok"},ang={["class:Rogue"]="Für junge Orc- und Trollschurken, die das Tal der Prüfungen verlassen, bietet Kaplak eine frühe fachliche Ausbildung und führt sie an die verdeckten Netzwerke heran, die in Orgrimmar operieren.",["faction:Horde"]="Kaplak sorgt im Verborgenen dafür, dass die Horde über fähige Späher, Spione und Attentäter verfügt, die Durotar schützen und jenseits der regulären Frontlinien agieren können."},sec={{t="Ein Mentor in den Schatten",b="Verborgen in der Siedlung Klingenhügel dient Kaplak als grundlegender Ausbilder für angehende Schurken der Horde, die aus dem Tal der Prüfungen kommen. Wo die traditionelle Kultur der Orcs den offenen Kampf und brüllende Sturmangriffe verherrlicht, lehrt Kaplak die kühleren, leiseren Disziplinen, die fürs Überleben notwendig sind: ungesehenes Schleichen, das Knacken von Schlössern und tödliche Schläge aus dem Hinterhalt. Sobald seine Schüler seiner Unterweisung in den staubigen roten Schluchten von Durotar entwachsen sind, schickt er sie nach Norden in die Hauptstadt Orgrimmar, um ihr Handwerk bei erfahrenen Agenten der Gilde zu vertiefen."}},faq={{q="Wer ist Kaplak?",a="Kaplak ist ein Orc-Schurkenlehrer, der in Klingenhügel in Durotar stationiert ist. Er bildet unerfahrene Orc- und Trollschurken aus, die das Tal der Prüfungen verlassen haben, bringt ihnen frühe Schurkenfähigkeiten bei und verweist sie an höherrangige Lehrer in Orgrimmar weiter.",al={"wer ist kaplak","kaplak lore","kaplak klingenhügel"}},{q="Wo ist Kaplak zu finden?",a="Kaplak befindet sich in Klingenhügel, der zentralen Siedlung von Durotar, wo er sich für gewöhnlich in oder nahe der örtlichen Kaserne an der Seite anderer Klassenlehrer aufhält.",al={"wo ist kaplak","kaplak aufenthaltsort","kaplak finden"}},{q="Welche Quests bietet Kaplak an?",a="Kaplak unterstützt Schurkenabenteurer bei ihren Fortschritten und weist ihnen den Weg zu fortgeschrittenen Ausbildern sowie Aufgaben, wie etwa dem Auftrag, Therzok in Orgrimmar aufzusuchen.",al={"kaplak quests","quests von kaplak"}}},fx={c5a92913={q="Auf wessen Seite steht Kaplak?",a="Kaplak ist loyal zur Horde und dient den Orcs von Durotar. In Klingenhügel stationiert, leitet er die jungen Stalker und Späher von Thralls Reich an und schult ihre Fähigkeiten, damit sie orcisches Land vor Zentaurenüberfällen, Infiltratoren aus Kul Tiras und anderen Bedrohungen für die wachsende Nation verteidigen können.",al={"kaplak fraktion","kaplak allianz oder horde","wem dient kaplak"}},d6e62700={q="Warum ist Kaplak in Klingenhügel?",a="Kaplak ist in Klingenhügel stationiert, um junge Orcs und Trolle auszubilden, die die subtilen Künste der Heimlichkeit, des Vergiftens und des Hinterhalts praktizieren. Wenn Rekruten aus dem Tal der Prüfungen aufbrechen, schärft er ihre Schurkenfertigkeiten, bevor er fähige Späher in die Hauptstadt Orgrimmar weiterleitet.",al={"warum ist kaplak hier","zweck von kaplak in durotar","was macht kaplak in klingenhügel"}},["044206c1"]={q="Was will Kaplak?",a="Kaplak möchte die Reihen der Schurken der Horde stärken. Er sucht bei den neu angekommenen Rekruten nach List, Disziplin und schnellen Klingen und weist vielversprechende Späher an erfahrenere Mentoren wie Therzok in Orgrimmar weiter, sobald ihre grundlegende Ausbildung abgeschlossen ist.",al={"kaplak motive","kaplak ziele","was braucht kaplak"}}},fp="6,241,23.544.0,14.236.0,26.156.0,30.161.0"}
P.entries["npc:karang-amakkar"] = {n="Karang Amakkar",s="Karang Amakkar ist ein Orc-Späher, der am Außenposten von Zoram'gar entlang der felsigen Küste des Eschentals stationiert ist. Er operiert am Rande des Gebiets der Horde und konzentriert sich darauf, die gewalttätigen Furbolgstämme einzudämmen, die die Nachschubwege und Grenzen des Außenpostens bedrohen. Abenteurer, die durch den Außenposten reisen, verlassen sich auf seine örtlichen Informationen, um die gefährlichen Spannungen des Waldes zu meistern.",h="Karang Amakkar ist ein Orc-Späher, der am Außenposten von Zoram'gar entlang der felsigen Küste des Eschentals...",kw={"eschental","foulweald","furbolg","karang amakkar","der zoramstrand","außenposten von zoram'gar"},ang={["faction:Horde"]="Karang Amakkar leistet Reisenden der Horde, die sich in die westlichen Gebiete des Eschentals wagen, lebenswichtige Hilfe und bietet Arbeit an, um die feindseligen Kreaturen rund um den Außenposten von Zoram'gar zurückzudrängen.",["race:Orc"]="An einem abgelegenen Außenposten weit weg von Durotar stationiert, verkörpert Karang die entschlossene Härte von Orc-Wachen, die gefährliche Grenzgebiete halten."},sec={{t="An der Küste des Eschentals",b="Am Außenposten von Zoram'gar am Zoramstrand gelegen, dient Karang Amakkar der Horde an einem ihrer verwundbarsten Grenzaußenposten. Das Lager ist ständigem Druck von der See, den Nachtelfen und wilden Bestien im Landesinneren ausgesetzt. Karang behält die feindseligen einheimischen Populationen, die die Straße nach Osten umgeben, genau im Auge, um sicherzustellen, dass Kuriere und Spähtrupps der Horde nicht von territorialen indigenen Stämmen aus dem Hinterhalt angegriffen werden."},{t="Umgang mit den Furbolgs",b="Karang konzentriert einen Großteil seiner Aufmerksamkeit auf die Furbolg-Populationen, die in den uralten Wäldern beheimatet sind, insbesondere auf den Stamm der Foulweald. Da Verderbnis und ursprüngliche Feindseligkeit diese Bärenmenschen in Raserei versetzen, beauftragt Karang fähige Krieger damit, ihren Anführer auszuschalten und ihre Höhlen zu säubern, bevor die Stämme organisierte Angriffe gegen Zoram'gar starten können."}},faq={{q="Wer ist Karang Amakkar?",a="Karang Amakkar ist ein Orc-Questgeber, der am Außenposten von Zoram'gar an der Küste des Eschentals stationiert ist. Er arbeitet im Auftrag der Horde, um regionale Bedrohungen zu bewältigen, insbesondere feindselige Furbolgclans.",al={"karang","wer ist karang","karang amakkar lore"}},{q="Wo finde ich Karang Amakkar?",a="Er befindet sich am Außenposten von Zoram'gar, an der nordwestlichen Küste des Eschentals entlang des Zoramstrands.",al={"karang standort","wo ist karang amakkar","karang amakkar fundort"}},{q="Welche Aufgaben bietet Karang Amakkar an?",a="Karang beauftragt Abenteurer der Horde damit, sich den aggressiven Furbolgstämmen in der Nähe entgegenzustellen, und leitet einen Angriff gegen den King of the Foulweald.",al={"karang quests","karang aufgaben","was will karang"}},{q="Warum ist Karang wegen der Furbolgs besorgt?",a="Die Furbolgs im Eschental sind zunehmend wilder und verdorbener geworden. Sie greifen Reisende an und drohen, den Außenposten von Zoram'gar vom Rest der Festungen der Horde in der Region abzuschneiden.",al={"warum furbolgs töten","furbolg bedrohung eschental","foulweald bedrohung"}},{q="Ist Karang Amakkar mit Initiate Amakkar verwandt?",a="Obwohl sie einen Clannamen oder Familiennamen teilen, bleibt eine genaue familiäre Beziehung zwischen Karang und Initiate Amakkar unbestätigt.",al={"amakkar familie","initiate amakkar verwandtschaft","karang familie"}},{q="Kämpft Karang direkt gegen die Nachtelfen?",a="Karangs Pflichten in Zoram'gar konzentrieren sich in erster Linie auf die territoriale Verteidigung und den Umgang mit wilden Bedrohungen wie den Foulweald-Furbolgs, während er offenere militärische Manöver gegen die Nachtelfen anderen Befehlshabern der Horde überlässt.",al={"karang vs nachtelfen","karang allianz"}}},fx={b0298d21={q="Auf wessen Seite steht Karang Amakkar?",a="Karang Amakkar ist loyal zur Horde und dient ihren Interessen direkt in den dichten Wäldern von Eschental. Er operiert zusammen mit anderen Orcs vom Außenposten von Zoram'gar an der Küste aus und konzentriert seine Bemühungen darauf, Außenposten der Horde zu schützen und regionale Bedrohungen wie feindselige Furbolgs zu unterwerfen.",al={"karang amakkar fraktion","ist karang horde","karang loyalität"}},["481f1d87"]={q="Was will Karang Amakkar?",a="Karang möchte die gefährlichen einheimischen Stämme von Eschental niederschlagen, die den Stützpunkt der Horde bedrohen. Er sucht aktiv nach fähigen Abenteurern, um aggressive Furbolgstämme, insbesondere den Stamm der Rostpfoten und ihren König, zu bekämpfen, bevor sie nahegelegene Lager überrennen können.",al={"karang amakkar ziel","was will karang","karang motiv"}},["7b1509e6"]={q="Warum ist Karang Amakkar hier in Eschental?",a="Karang ist in Eschental stationiert, um die Expansion und Verteidigung der Horde in einem äußerst feindseligen Gebiet zu unterstützen. Vom Außenposten von Zoram'gar aus überwacht er die Wildnis und leitet Krieger dazu an, feindselige Bestienstämme zu neutralisieren, die die Präsenz der Horde entlang der Zoram-Strand bedrohen.",al={"warum ist karang hier","zweck von karang amakkar im eschental","warum ist karang in zoram'gar"}}},fp="14,367,25.418.0,25.342.0,22.190.0,32.102.0,37.135.0,41.190.0,46.136.0,43.210.0"}
P.entries["npc:kargal-battlescar"] = {n="Kargal Schlachtnarbe",s="Kargal Schlachtnarbe ist ein erfahrener Orc-Krieger, der an der Fernwacht an der östlichen Grenze des Brachlands stationiert ist. Mit der Bewachung des Übergangs von Durotar betraut, mustert er eintreffende Rekruten und schickt fähige Kämpfer tiefer in das Territorium, um die Verteidigung der Horde zu verstärken.",h="Kargal Schlachtnarbe ist ein erfahrener Orc-Krieger, der an der Fernwacht an der östlichen Grenze des...",kw={"brachland","battlescar","rekrut","das wegekreuz","durotar","fernwacht","kargal"},ang={["class:Warrior"]="Als kampferprobter Veteran, der die Narben unzähliger Gefechte trägt, verkörpert Kargal die unverwüstliche Widerstandskraft, die von den Frontkämpfern der Horde in ungezähmten Grenzlanden erwartet wird.",["faction:Horde"]="Für frische Horde-Abenteurer, die Durotar verlassen, dient Kargal Schlachtnarbe als Einführung in die größeren militärischen Konflikte von Kalimdor, indem er Rekruten für die im Brachland schwelenden Auseinandersetzungen aufstellt."},sec={{t="Wächter der Grenze",b="Kargal Schlachtnarbe hält an der Fernwacht Wache und überblickt den strategischen Übergang, der die rauen roten Ebenen von Durotar von der weiten Savanne des Brachlands trennt. Wenn Reisende und frischgebackene Abenteurer die Brücke über den Südstrom überqueren, sorgt Kargal dafür, dass sie begreifen, dass die friedlichen Tage des Trainings im Tal der Prüfungen vorbei sind. Das Brachland ist ein umkämpftes und gefährliches Gebiet, heimgesucht von aggressiver Tierwelt, Raubzügen der Zentauren und Stämmen der Borstennacken. Kargal mustert die Vorbeiziehenden, zieht willige Rekruten für den Dienst der Horde ein und schickt sie weiter zum Wegekreuz, um den örtlichen Befehlshabern bei der Sicherung der Grenze beizustehen."}},faq={{q="Wer ist Kargal Schlachtnarbe?",a="Kargal Schlachtnarbe ist ein Orc-Krieger und Außenposten-Kommandant, der an der Fernwacht stationiert ist, gelegen an der östlichen Straße, die von Durotar ins Brachland führt.",al={"kargal schlachtnarbe","kargal","wer ist kargal"}},{q="Was ist der Zweck der Fernwacht?",a="Die Fernwacht dient als Frühwarnstation und vorderste Verteidigungslinie für das Brachland gegen Bedrohungen, die nahe der Grenze zu Durotar und entlang des Südstroms auftreten.",al={"zweck farwatch-posten","warum farwatch-posten","was ist dieser außenposten"}},{q="Wohin schickt Kargal neue Rekruten?",a="Kargal rekrutiert Reisende, die den Außenposten passieren, und schickt sie westwärts entlang der Hauptstraße zum Wegekreuz, dem zentralen militärischen Knotenpunkt des Brachlands.",al={"kargal questziel","wohin nach kargal","wohin schickt kargal euch"}}},fx={["81d05e56"]={q="Auf wessen Seite steht Kargal Schlachtnarbe?",a="Kargal Schlachtnarbe steht fest auf der Seite der Horde. Er bewacht die östliche Grenze des Brachlands, wo Durotar auf die offenen Ebenen trifft, und stellt sicher, dass ankommende Rekruten und Reisende sicher unter dem Banner des Kriegshäuptlings die Grenze passieren.",al={"kargal schlachtnarbe fraktion","ist kargal horde"}},ffbc81ca={q="Was will Kargal Schlachtnarbe?",a="Kargal möchte, dass fähige Krieger die Grenze sichern und die wachsende Siedlung am Das Wegekreuz unterstützen. Er leitet frische Wehrpflichtige, die aus Durotar ankommen, an, um die Verteidigung des Brachlands gegen die Bedrohungen entlang der Ebenen zu verstärken.",al={"kargal schlachtnarbe ziel","was will kargal"}},e589e5e9={q="Warum ist Kargal Schlachtnarbe hier stationiert?",a="Kargal beaufsichtigt die Fernwacht, den befestigten Eingang, der Durotar und das Brachland über den Der Südstrom verbindet. Er ist hier stationiert, um neue Wehrpflichtige zu empfangen, die nach Westen reisen, und sie dorthin zu leiten, wo die Horde sie am dringendsten benötigt.",al={"warum ist kargal bei der fernwacht","kargal schlachtnarbe standortzweck"}}},fp="17,276,22.656.0,25.157.0,42.171.0,36.161.0"}
P.entries["npc:karos-razok"] = {n="Karos Razok",s="Karos Razok ist der Fledermausführer der Verlassenen, der im Grabmal im Silberwald stationiert ist. Er beaufsichtigt den Nistplatz der untoten Flieger, die diesen umkämpften Grenzaußenposten direkt mit Unterstadt und anderen Festungen der Horde verbinden.",h="Karos Razok ist der Fledermausführer der Verlassenen, der im Grabmal im Silberwald stationiert ist.",kw={"fledermausführer","flugmeister","karos razok","das grabmal","silberwald","unterstadt"},ang={["faction:Horde"]="Für Reisende der Horde, die nach Süden in Richtung des Vorgebirges des Hügellands vorstoßen, ist Razoks Fledermausnistplatz ein unverzichtbarer Wegpunkt am westlichen Rand von Lordaeron.",["race:Undead"]="Karos Razok stellt Eure Lebensader zurück nach Unterstadt dar und stellt sicher, dass die Einsätze an der Front im Silberwald fest an Fürstin Sylvanas' Hauptstadt angebunden bleiben."},sec={{t="Hüter der Schwingen des Grabmals",b="Auf der Holzplattform über den Grüften des Grabmals versorgt Karos Razok die skelettartigen Fledermäuse, die für die Kommunikation der Verlassenen unerlässlich sind. Da der Silberwald von Worgen der Mondrast, abtrünnigen Magiern aus Dalaran und den menschlichen Überresten von Mühlenbern heimgesucht wird, ist das Reisen über Land entlang der nördlichen Straße tückisch. Razok stellt sicher, dass Boten, frische Rekruten und lebenswichtige Vorräte das verfluchte Blätterdach überfliegen können, wodurch die Frontlinie direkt mit der Hauptstadt in Tirisfal verbunden bleibt."}},faq={{q="Wer ist Karos Razok?",a="Karos Razok ist der Flugmeister der Verlassenen, der im Grabmal im Silberwald stationiert ist. Er betreut den Nistplatz ausgebildeter vampirischer Fledermäuse, die von Abenteurern und Boten der Horde für Reisen durch Lordaeron genutzt werden.",al={"karos razok rolle","wer ist der flugmeister im grabmal","fledermausführer grabmal"}},{q="Wohin kann Karos Razok Reisende schicken?",a="Razok verbindet Das Grabmal direkt mit Unterstadt in Tirisfal sowie mit Tarrens Mühle im Vorgebirge des Hügellands und ermöglicht so eine schnelle Durchquerung des nördlichen Lordaeron.",al={"flugrouten grabmal","wohin fliegt die fledermaus vom grabmal","flugwege vom grabmal"}},{q="Welche Kreaturen betreut Karos?",a="Er kümmert sich um große, skelettartige Flugfledermäuse. Diese untoten Bestien sind zähe, unermüdliche Flieger, die an die verseuchten Himmel von Lordaeron angepasst sind und von den Verlassenen wegen ihrer Stille und Ausdauer geschätzt werden.",al={"welche reittiere hat razok","flugtiere der verlassenen","was sind die flugtiere am grabmal"}},{q="Warum ist ein Flugmeister im Grabmal wichtig?",a="Die Straßen des Silberwalds sind von feindlichen Kräften verstopft, vom Worgenfluch von Pyrewood bis hin zu menschlichen Zauberern in Mühlenbern. Razok stellt eine Rettungsleine aus der Luft dar, die es den Verlassenen ermöglicht, diesen Vorposten zu versorgen, ohne auf der Hauptstraße Hinterhalten zum Opfer zu fallen.",al={"warum fledermausmeister am grabmal gebraucht wird","reisebedeutung grabmal"}}},fx={db08745b={q="Auf wessen Seite steht Karos Razok?",a="Karos Razok dient den Verlassenen und der Horde. Er ist im Silberwald stationiert und schwört seine Treue Fürstin Sylvanas Windläufer und der Unterstadt, wobei er Kuriere, Späher und Abenteurer der Verlassenen unterstützt, die durch die Region reisen.",al={"karos razok fraktion","wem dient karos razok","karos razok horde"}},["6a9fc34a"]={q="Was will Karos Razok?",a="Karos möchte einfach nur die Flugrouten offen halten und den Lufttransport für die Verlassenen reibungslos gestalten. Die Verwaltung des Flugpunkts am Das Grabmal stellt sicher, dass Vorräte, Nachrichten und Verstärkungen zuverlässig zwischen dem Silberwald und anderen Bastionen der Horde fließen können.",al={"karos razok ziel","was macht karos razok","karos razok motive"}}},fp="11,227,31.485.0,19.205.0,37.171.0,33.190.0,50.245.0"}
P.entries["npc:katie-hunter"] = {n="Katie Hunter",s="Katie Hunter ist eine Pferdezüchterin, die in den Stallungen im Holzfällerlager des Osttals im östlichen Wald von Elwynn stationiert ist. Sie stellt Bürgern von Sturmwind und vertrauenswürdigen Streitern der Allianz ausgebildete Reitpferde und Rösser zur Verfügung. An der Seite von Randal Weidmann sorgt sie dafür, dass Reisende und Soldaten über verlässliche Reittiere verfügen, um die Straßen des Königreichs zu bereisen.",h="Katie Hunter ist eine Pferdezüchterin, die in den Stallungen im Holzfällerlager des Osttals im östlichen Wald...",kw={"osttal","wald von elwynn","pferdehändlerin","katie hunter","holzfällerlager","reittiere","stallungen","sturmwind"},ang={["faction:Alliance"]="Verbündete Völker, die sich hohes Ansehen und Respekt am Hof von Sturmwind verdienen, können das Privileg erlangen, Katies geschätzte Rösser in die Schlacht zu reiten.",["race:Human"]="Für menschliche Reisende stellen Katies Stallungen einen ganz natürlichen Übergangsritus dar, da sie klassische Pferde aus Sturmwind anbieten, sobald Ihr die Grundlagen der Reitkunst gemeistert habt."},sec={{t="Stallungen des Osttals",b="Versteckt in den ruhigen, bewaldeten Lichtungen des Holzfällerlagers des Osttals verwaltet Katie Hunter den primären Pferdebestand des Königreichs für angehende Reiter im Wald von Elwynn. Während die Holzfäller Holz für den Wiederaufbau von Sturmwind schlagen, kümmert sich Katie um die Stallungen und züchtet eine Vielzahl verlässlicher Rassen, darunter Schecken, Stuten und schnelle Rösser. Ihr Bestand verkörpert die klassische Reitertradition des Königreichs und bietet treue Gefährten, die den gefährlichen Straßen im Süden Azeroths trotzen können."}},faq={{q="Wer ist Katie Hunter?",a="Katie Hunter ist die Pferdezüchterin und Reittierhändlerin des Königreichs Sturmwind und befindet sich an den Stallungen des Holzfällerlagers des Osttals im Wald von Elwynn.",al={"katie hunter elwynn","wer ist katie hunter","katie hunter pferdehändlerin"}},{q="Wo finde ich Katie Hunter?",a="Sie befindet sich im nördlichen Teil des Holzfällerlagers des Osttals und kümmert sich im östlichen Wald von Elwynn um die Koppel und die Stallungen in der Nähe des Reitlehrers Randal Weidmann.",al={"katie hunter aufenthaltsort","wo ist katie hunter","katie hunter finden"}},{q="Können Nicht-Menschen Pferde bei ihr kaufen?",a="Ja, allerdings nur, wenn sie einen ehrfürchtigen Ruf beim Königreich Sturmwind erlangt haben. Menschliche Abenteurer können ihre Pferde ohne besonderen Ruf erwerben.",al={"zwerg pferd kaufen","nachtelf pferdereittier","sturmwind ruf reittier"}},{q="Welche Pferde verkauft sie?",a="Katie bietet Standard-Reitpferde an – darunter gescheckte, braune und fuchsfarbene Varianten – sowie schnelle, gepanzerte Rösser wie das Schnelle Palomino, den Schnellen Braunen und das Schnelle weiße Ross.",al={"welche reittiere verkauft katie","katie hunter pferdearten"}}},fx={d7735dfa={q="Auf wessen Seite steht Katie Hunter?",a="Katie Hunter ist eine loyale Untertanin des Königreichs Sturmwind und Mitglied der Allianz. Sie arbeitet vom Holzfällerlager des Osttals aus und versorgt direkt die Bürger Sturmwinds, indem sie verlässliche Reittiere an Reisende und Champions bereitstellt, die ihre Treue gegenüber der Krone bewiesen haben.",al={"katie hunter fraktion","gehört katie hunter zur allianz","wem dient katie hunter"}},d5257f59={q="Was möchte Katie Hunter?",a="Katie Hunter konzentriert sich auf die Pflege und den Verkauf der berühmten Pferde aus dem Osttal. Sie möchte fähige Reittiere an verlässliche Abenteurer liefern und sicherstellen, dass nur vertrauenswürdige Verbündete Sturmwinds ihren geschätzten Bestand erwerben, um ihre Reisen durch das Königreich zu unterstützen.",al={"was möchte katie hunter","zweck von katie hunter","ziel von katie hunter"}},["5cab52df"]={q="Warum ist Katie Hunter hier im Holzfällerlager des Osttals?",a="Katie Hunter hat ihr Zuhause im Holzfällerlager des Osttals im östlichen Wald von Elwynn, um die Ställe des Lagers zu betreiben. In Zusammenarbeit mit Randal Weidmann verwaltet sie die Zucht und Pflege der Reitpferde fernab vom Trubel der Stadt Sturmwind und nutzt dafür die offene Weide des Lagers.",al={"warum ist katie hunter im osttal","warum ist katie hunter hier","was macht katie hunter in elwynn"}},["85933b18"]={q="Mit wem ist Katie Hunter verbunden?",a="Katie Hunter arbeitet eng mit Randal Weidmann zusammen, der ebenfalls die Ställe im Holzfällerlager des Osttals beaufsichtigt. Gemeinsam verwalten sie den Pferdehandel des Lagers und dienen als Hauptquelle für Pferde für die Verbündeten Sturmwinds.",al={"verbindungen von katie hunter","mit wem ist katie hunter verwandt","katie hunter und randal weidmann"}}},fp="12,339,19.503.0,20.150.0,30.159.0,35.158.0,26.191.0"}
P.entries["npc:katrana-prestor"] = {n="Lady Katrana Prestor",s="Lady Katrana Prestor ist eine Adlige aus Sturmwind und eine der einflussreichsten Stimmen bei Hofe. Da König Varian verschollen ist, steht sie dem Knabenkönig Anduin und Hochlord Bolvar Fordragon in Burg Sturmwind als vertraute Beraterin zur Seite.",h="Lady Katrana Prestor ist eine Adlige aus Sturmwind und eine der einflussreichsten Stimmen bei Hofe.",kw={"katrana","prestor","katrana prestor","lady prestor","beraterin","burg sturmwind","hof"},sec={{t="Stimme des Hofes",b="Lady Prestor erschien vor einigen Jahren bei Hofe und stieg rasch zu einer seiner angesehensten Persönlichkeiten auf. Die Adligen von Sturmwind buhlen um ihre Gunst, und ihr Rat prägt viele der Entscheidungen, die im Namen des jungen Königs getroffen werden, während Hochlord Bolvar Fordragon als Regent herrscht. Bittsteller, die nach Burg Sturmwind kommen, um Soldaten oder Hilfe zu erbitten, stellen oft fest, dass ihre Meinung ebenso viel Gewicht hat wie die des Regenten."}},faq={{q="Wer ist Lady Katrana Prestor?",a="Lady Katrana Prestor ist eine Adlige aus Sturmwind und eine vertraute Beraterin bei Hofe. Da König Varian verschollen ist, steht sie dem Knabenkönig Anduin und Hochlord Bolvar Fordragon in Burg Sturmwind zur Seite, und ihre Stimme hat bei den Adligen großes Gewicht.",al={"wer ist katrana prestor","wer ist lady prestor","katrana prestor geschichte"}},{q="Warum berät sie den König?",a="Das Verschwinden von König Varian ließ seinen jungen Sohn Anduin auf dem Thron zurück, während Hochlord Bolvar Fordragon als Regent regiert. Lady Prestor steht ihnen als Beraterin zur Seite. Viele Entscheidungen des Hofes, einschließlich der Frage, wie Sturmwind auf Hilfegesuche aus seinen umliegenden Gebieten reagiert, werden von ihrem Rat beeinflusst.",al={"warum ist prestor bei hofe","was tut katrana"}},{q="Wo kann ich Lady Prestor finden?",a="Sie hält sich üblicherweise im Thronsaal von Burg Sturmwind auf und steht dort in der Nähe von Hochlord Bolvar Fordragon und dem jungen König Anduin.",al={"wo ist katrana prestor","katrana prestor aufenthaltsort"}}},fp="20,232,18.402.0,28.243.0,29.296.0,30.125.0"}
P.entries["npc:kaymard-copperpinch"] = {n="Kaymard Kupferzwick",s="Kaymard Kupferzwick ist ein Goblinhändler, der während des Feast of Winter Veil Smokywood Pastures in Orgrimmar vertritt. Im Tal der Stärke preist er festliche Waren an und weist Reisende auf weihnachtliche Freuden sowie fehlende Festtagsgüter hin. Sein reges Geschäft bringt saisonale Fröhlichkeit – und goblinische Handelskunst – in die Hauptstadt der Horde.",h="Kaymard Kupferzwick ist ein Goblinhändler, der während des Feast of Winter Veil Smokywood Pastures in...",kw={"copperpinch","goblin","kaymard","metzen","orgrimmar","smokywood pastures","tal der stärke","winter veil"},ang={["faction:Horde"]="Für die Horde vertritt Kaymard die kommerzielle Seite des Feast of Winter Veil in Orgrimmar, indem er traditionelle Winterfeierlichkeiten mit goblinischem Unternehmergeist verbindet.",["profession:Cooking"]="Kaymard und seine Gefährten von Smokywood Pastures bieten saisonale Rezepte und spezielle Zutaten an, die für das Backen traditioneller Festtagsleckereien unverzichtbar sind."},sec={{t="Das Winterhauchfest eines Goblins",b="Wenn das Feast of Winter Veil beginnt, schlägt Smokywood Pastures seine Zelte direkt im belebten Tal der Stärke in Orgrimmar auf, angeführt vom geschäftstüchtigen Kaymard Kupferzwick. Während Altvater Winter ganz in der Nähe Besucher empfängt, sorgt Kaymard dafür, dass die Jahreszeit gewinnbringend bleibt. Mit dem Verkauf von erlesenen Leckereien, festlichem Geschenkpapier und unverzichtbaren Festtagsartikeln verkörpert er die goblinsche Ansicht, dass kein großes Kulturfest ohne einen lebhaften Münzwechsel vollkommen ist."},{t="Festtagskomplikationen",b="Neben dem Feilbieten festlicher Waren dient Kaymard oft als Ansprechpartner für die saisonalen Missgeschicke, die Smokywood Pastures heimsuchen. Von gestohlenen Lieferungen festlicher Süßwaren bis hin zum rätselhaften Verschwinden von Metzen the Reindeer heuert Kaymard eifrig Abenteurer der Horde an, um den Ärger im Schnee zu beseitigen und für einen reibungslosen Ablauf des Festes zu sorgen."}},faq={{q="Wer ist Kaymard Kupferzwick?",a="Kaymard Kupferzwick ist ein Goblinhändler, der Smokywood Pastures angehört. Während des Feast of Winter Veil agiert er im Tal der Stärke in Orgrimmar, verkauft erstklassige saisonale Waren und vergibt festliche Aufgaben an Vorbeireisende.",al={"wer ist kaymard","kaymard kupferzwick lore","was macht kaymard"}},{q="Was ist Smokywood Pastures?",a="Smokywood Pastures ist ein Händlerkonsortium, das auf ganz Azeroth für Speisen, Leckereien und saisonale Waren des Feast of Winter Veil zuständig ist. Sie versorgen sowohl die Horde als auch die Allianz mit Festtagsartikeln und erwirtschaften dabei einen stattlichen Gewinn.",al={"was ist smokywood pastures","für wen arbeitet er","smokywood pastures lore"}},{q="Wo kann ich Kaymard Kupferzwick finden?",a="Er steht im Tal der Stärke in Orgrimmar, nahe dem zentralen Festtagsbereich platziert, an dem Altvater Winter während des Feast of Winter Veil Hof hält.",al={"kaymard standort","wo ist kaymard kupferzwick","wo ist er in orgrimmar"}},{q="Warum bittet er Abenteurer während der Feiertage um Hilfe?",a="Smokywood Pastures erlebt während des Feast of Winter Veil regelmäßig logistische Katastrophen, darunter gestohlene Festtagssüßigkeiten und die Entführung ihres geschätzten Rentiers Metzen. Kaymard heuert willige Abenteurer an, um ihre Güter zurückzubringen und die Gewinne der Saison zu sichern.",al={"kaymard quests","winter veil leckereien quest","metzen quest horde"}}},fx={["10a0163d"]={q="Auf wessen Seite steht Kaymard Kupferzwick?",a="Kaymard arbeitet ausschließlich für Smokywood Pastures, ein gewerbliches Goblin-Unternehmen. Während er sein Urlaubsgeschäft im Herzen von Orgrimmar einrichtet, um Gönner der Horde zu bedienen und das Fest des Winterhauchs zu versorgen, liegt seine wahre Loyalität beim Unternehmen und dem Streben nach ehrlichem Gewinn, anstatt bei der Politik der Horde.",al={"kaymard kupferzwick fraktion","gehört kaymard zur horde","für wen arbeitet kaymard"}},["699a38fb"]={q="Warum ist Kaymard Kupferzwick hier?",a="Kaymard hat im Tal der Stärke in Orgrimmar ein Geschäft eröffnet, um das Fest des Winterhauchs zu feiern. Smokywood Pastures entsendet in jeder Festtagssaison Händler in die großen Hauptstädte, um Leckereien, Geschenkpapier, Rezepte und saisonale Spezialwaren an feiernde Bürger zu verkaufen.",al={"warum ist kaymard in orgrimmar","was macht kaymard hier","zweck von kaymard in orgrimmar"}}},fp="19,352,22.459.0,21.345.0,27.228.0,27.234.0,37.172.0,57.259.0"}
P.entries["npc:keeper-albagorm"] = {n="Bewahrer Albagorm",s="Bewahrer Albagorm ist ein Hüter des Hains, der in der idyllischen Zuflucht des Steinkrallengipfels stationiert ist. Zutiefst besorgt über die Verwüstung, die die südlichen Ausläufer der Berge verdirbt, wirbt er Reisende an, um bei der Heilung der versengten Wildnis des verbrannten Tals zu helfen.",h="Bewahrer Albagorm ist ein Hüter des Hains, der in der idyllischen Zuflucht des Steinkrallengipfels...",kw={"cenarius","das verbrannte tal","bewahrer albagorm","hüter des hains","steinkralle","der steinkrallengipfel"},ang={["class:Druid"]="Als Hüter des Hains hat Albagorm eine direkte Verbindung zur cenarischen Blutlinie, was seine Bemühungen zur Läuterung des verbrannten Tals für Druiden zu einer zutiefst persönlichen Angelegenheit macht.",["faction:Alliance"]="Albagorm bietet Streitkräften der Allianz, die die Zuflucht der Nachtelfen am Steinkrallengipfel durchqueren, Zuflucht und Führung."},sec={{t="Ein Wächter auf dem Gipfel",b="Inmitten der friedlichen Zweige des Steinkrallengipfels wacht Bewahrer Albagorm über eine der heiligen Zufluchten der Elfen in Kalimdor. Wie viele Söhne von Cenarius spürt er den Schmerz der natürlichen Welt überaus deutlich. Seine Aufmerksamkeit richtet sich nach Süden auf die schwelenden Ruinen des verbrannten Tals, die von einer gierigen mechanisierten Armee von Industriellen in Brand gesteckt wurden und nun von den Harpyien der Bloodfury beherrscht werden, die jedes Nachwachsen verhindern. Von seiner Zuflucht aus arbeitet Albagorm unermüdlich daran, die Ausbreitung des Verfalls aufzuhalten und das Gleichgewicht im verwundeten Wald wiederherzustellen."}},faq={{q="Wer ist Bewahrer Albagorm?",a="Er ist ein Hüter des Hains – einer der halbgöttlichen Nachkommen von Cenarius –, der am Steinkrallengipfel im Steinkrallengebirge stationiert ist. Er dient als Verbündeter der Nachtelfen und natürlichen Beschützer Kalimdors.",al={"bewahrer albagorm","wer ist albagorm","albagorm steinkrallen"}},{q="Wo finde ich Bewahrer Albagorm?",a="Er weilt am Steinkrallengipfel, einer der Allianz wohlgesinnten druidischen Zuflucht, die hoch im nordwestlichen Winkel des Steinkrallengebirges liegt.",al={"bewahrer albagorm aufenthaltsort","wo ist albagorm","albagorm koordinaten"}},{q="Wobei möchte Bewahrer Albagorm Hilfe?",a="Albagorm versucht, die Verwüstung des verbrannten Tals zu heilen. Er schickt fähige Abenteurer in das ascheerstickte Becken, um die verseuchte Landschaft zu läutern und die Harpyien der Bloodfury zu vertreiben, die das natürliche Nachwachsen verhindern.",al={"bewahrer albagorm quests","was will albagorm","die rückeroberung des verbrannten tals"}}},fx={["23205c35"]={q="Auf wessen Seite steht Bewahrer Albagorm?",a="Bewahrer Albagorm ist auf die Seite der Nachtelfen und der Cenarion-Druiden vom Steinkrallengipfel ausgerichtet und bietet Champions der Allianz seinen Rat und seine Führung an. Wie alle Söhne des Cenarius liegt seine tiefere Loyalität beim Gleichgewicht der Natur; er sucht nach Verbündeten, die bereit sind, bei der Heilung der vernarbten Landschaften Kalimdors zu helfen.",al={"bewahrer albagorm fraktion","albagorm allianz oder horde","ist albagorm freundlich"}},["28024e4a"]={q="Warum ist Bewahrer Albagorm hier am Steinkrallengipfel?",a="Bewahrer Albagorm wacht über das Heiligtum des Steinkrallengipfels, eine lebenswichtige Bastion der Natur, die hoch oben in den Bergen liegt. Von diesem Zufluchtsort aus beobachtet er die Verderbnis und Zerstörung, die sich in der Region ausbreiten, und weist vertrauenswürdige Reisende an, die Plage zurückzudrängen und die Verwüstung zu beheben, die das nahegelegene verbrannte Tal bedroht.",al={"warum ist albagorm am steinkrallengipfel","zweck von albagorm am steinkrallengipfel","rolle von bewahrer albagorm"}},["7aa8d5e1"]={q="Mit wem ist Bewahrer Albagorm verbunden?",a="Als Bewahrer des Hains ist Albagorm einer der verehrten Söhne des Cenarius, was ihn durch eine heilige Blutlinie direkt mit dem Halbgott des Mondes und der natürlichen Ordnung verbindet. Im Steinkrallengebirge steht er eng an der Seite der dortigen Nachtelfen-Schildwachen und Cenarion-Beschützer, die auf dem Gipfel des Berges stationiert sind.",al={"verbindungen von bewahrer albagorm","albagorm kontakte","wem untersteht albagorm"}}},fp="15,260,22.526.0,23.205.0,33.134.0,41.213.0"}
P.entries["npc:keeper-bel-dugur"] = {n="Bewahrer Bel'dugur",s="Bewahrer Bel'dugur ist ein gelehrter Verlassener, der tief im Apothekarium von Unterstadt residiert. Er dient seinem Volk, indem er Expeditionen zur Bergung dunkler Wälzer und magischer Artefakte aus ganz Azeroth in Auftrag gibt.",h="Bewahrer Bel'dugur ist ein gelehrter Verlassener, der tief im Apothekarium von Unterstadt residiert.",kw={"das apothekarium","bel'dugur","bewahrer beldugur","shadowfang","das buch von ur","unterstadt"},ang={["class:Warlock"]="Hexenmeister kreuzen häufig die Wege von Bel'dugurs Anfragen, da seine Interessen stark mit gefährlichen Grimoires, extraplanarer Beschwörung und dunklem Okkultismus übereinstimmen.",["race:Undead"]="Bel'dugur wirkt wie jeder andere gelehrte Verlassene, der nach verbotenem Wissen strebt, um Euer Königreich zu stärken, doch seine wahren Ambitionen liegen außerhalb der Überlebenspläne der Bansheekönigin."},sec={{t="Ein Sammler dunkler Relikte",b="Inmitten der Bottiche und Forscher des Apothekariums beauftragt Bewahrer Bel'dugur Abenteurer damit, gefährliche arkane und okkulte Relikte aus ganz Azeroth zu beschaffen. Zu seinen bedeutendsten Interessen gehört Das Buch von Ur, eine legendäre Abhandlung über extradimensionale Wesen, die in Burg Shadowfang weggeschlossen liegt. Während viele in Unterstadt nach magischem Wissen suchen, um den Zustand der Untoten zu heilen oder als Waffe einzusetzen, scheinen Bel'dugurs gezielte Beschaffungen darauf ausgerichtet zu sein, uralte, verbotene Mächte freizulegen."},{t="Verborgene Loyalitäten",b="Hinter seinem ruhigen Auftreten als Forscher von Unterstadt verbirgt sich eine geheime Loyalität zum apokalyptischen Kult des Schattenhammers. Die Quests und Forschungsaufgaben, die Bel'dugur vergibt, treiben im Stillen die esoterischen Pläne des Kults voran, indem grundlegende Grimoires der Beschwörungs- und Leerenmagie direkt vor den ahnungslosen Augen der Königlichen Apothekervereinigung und Fürstin Sylvanas beschafft werden."}},faq={{q="Wo kann ich Bewahrer Bel'dugur finden?",a="Bewahrer Bel'dugur befindet sich im Apothekarium, dem alchemistischen Viertel im südlichen unteren Ring von Unterstadt.",al={"bewahrer bel'dugur aufenthaltsort","wo ist beldugur","beldugur karte"}},{q="Warum will Bel'dugur Das Buch von Ur?",a="Das Buch von Ur enthält die grundlegenden Forschungen des Dalaran-Magiers Ur über andere Dimensionen und die wilden Worgen. Bel'dugur versucht, diese verbotenen Beschwörungsprinzipien für die finsteren Pläne seiner wahren Meister zu nutzen.",al={"warum buch von ur","was macht beldugur mit dem buch von ur"}},{q="Ist Bewahrer Bel'dugur Fürstin Sylvanas treu ergeben?",a="Nach außen hin fungiert er als Archivar und Forscher für die Verlassenen, doch subtile Hinweise in seinen Untersuchungen deuten darauf hin, dass seine Loyalität woanders liegen könnte.",al={"ist beldugur böse","beldugur fraktion","wem dient beldugur"}},{q="Welche anderen Aufgaben gibt er Abenteurern?",a="Über das Buch von Ur aus Burg Shadowfang hinaus leitet Bel'dugur Reisende zu vergessener Kunde und verbotenen Wälzern, einschließlich dunkler Abhandlungen, die mit uralten Ritualen und verbotenem Wissen verknüpft sind.",al={"beldugur quests","bewahrer beldugur quests"}}},fx={f8b2616f={q="Wer ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur ist ein Gelehrter der Verlassenen, der im Apothekarium innerhalb der Unterstadt stationiert ist. Während er sich als stiller Archivar präsentiert, der obskure Folianten und vergessenes Wissen für die Königliche Apothekergesellschaft sammelt, verfolgt er gefährliches esoterisches Wissen, das weit über das gewöhnliche Handwerk der Apotheker hinausgeht.",al={"wer ist bel'dugur","hintergrund von bewahrer beldugur","wer ist bewahrer beldugur"}},["3453eee6"]={q="Was möchte Bewahrer Bel'dugur?",a="Bel'dugur sucht nach verbotenen arkanen Texten, okkulten Geheimnissen und Relikten dunkler Macht. Er beauftragt Abenteurer mit der Bergung gefährlicher Folianten wie dem Buch von Ur aus Burg Shadowfang und anderen versteckten Sammelbänden, um gefährliche antike Magie freizuschalten.",al={"was möchte beldugur","motive von bewahrer beldugur","ziel von beldugur"}},["43763d0f"]={q="Warum ist Bewahrer Bel'dugur in der Unterstadt?",a="Bel'dugur wohnt im Apothekarium der Unterstadt, einem idealen Zufluchtsort für diejenigen, die dunkle Studien abseits neugieriger Blicke verfolgen. Von der Sicherheit der Hauptstadt der Verlassenen aus weist er Wanderer zu gefährlichen Ecken der Welt, um verlorene Schriften für seine Sammlung zu bergen.",al={"warum ist bel'dugur in der unterstadt","warum ist bewahrer beldugur hier","standort von beldugur"}},["5a26a87f"]={q="Mit wem ist Bewahrer Bel'dugur verbunden?",a="Unter seiner Rolle bei den Verlassenen im Apothekarium deuten subtile Hinweise und Dialoge zu seiner verbotenen Forschung auf Verbindungen zum geheimnisvollen Kult des Schattenhammers hin, der nach weltverändernder Macht und apokalyptischem Wissen giert.",al={"verbindungen von bewahrer bel'dugur","für wen arbeitet beldugur","beldugur und der kult des schattenhammers"}}},fp="16,211,26.501.0,16.349.2,34.129.0,39.227.1,43.155.2,42.181.0"}
P.entries["npc:keeper-bel-varil"] = {n="Bewahrer Bel'varil",s="Bewahrer Bel'varil ist ein Betreuer und Forscher der Verlassenen, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. In enger Zusammenarbeit mit Wordeen Voidglare leitet er Abenteurer der Horde an, magische Relikte und bindende Materialien aus den umliegenden Landen zu beschaffen, um ihre okkulten Studien voranzutreiben.",h="Bewahrer Bel'varil ist ein Betreuer und Forscher der Verlassenen, der in Tarrens Mühle im Vorgebirge des...",kw={"bel'varil","armschienen der bindung","vorgebirge des hügellands","bewahrer bel'varil","steinmarken","tarrens mühle","wordeen voidglare"},ang={["faction:Horde"]="Für Champions der Horde, die im Vorgebirge des Hügellands kämpfen, bietet Bel'varil praktische Belohnungen im Austausch für die Bezwingung elementarer Bedrohungen und die Bergung bindender Amulette.",["race:Undead"]="Bel'varils Arbeit spiegelt das Streben der Verlassenen nach arkaner Meisterschaft und Einfallsreichtum wider, um sich durch die sorgfältige Erforschung regionaler Relikte einen Vorteil in Lordaeron zu sichern."},sec={{t="Studien in Tarrens Mühle",b="Inmitten des belagerten Dorfes Tarrens Mühle unterstützt Bewahrer Bel'varil im Stillen die magische und alchemistische Forschung der Verlassenen. Während königliche Apotheker und Soldaten sich mit der Garnison der Allianz die Straße hinab bei Süderstade beschäftigen, konzentriert sich Bel'varil auf praktische Zauberei und entsendet Reisende, um Steinmarken und bindende Armschienen von nahen elementaren und verzauberten Bedrohungen zu bergen."}},faq={{q="Wer ist Bewahrer Bel'varil?",a="Bewahrer Bel'varil ist ein Gelehrter der Verlassenen, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Er unterstützt den Forscherkollegen Wordeen Voidglare bei der Untersuchung magischer Artefakte und Reagenzien, die im umkämpften Gebiet gefunden werden.",al={"bewahrer belvaril","wer ist belvaril","belvaril tarrens mühle"}},{q="Wo kann ich Bewahrer Bel'varil finden?",a="Er befindet sich in der Siedlung der Verlassenen in Tarrens Mühle, gelegen im nördlichen Vorgebirge des Hügellands.",al={"belvaril aufenthaltsort","wo ist bewahrer bel'varil","bewahrer bel'varil finden"}},{q="Welche Aufgaben bietet Bewahrer Bel'varil an?",a="Er heuert Abenteurer der Horde an, um magische Überreste wie Steinmarken und Armschienen der Bindung zu sammeln, was seinem Zirkel dabei hilft, elementare Mächte zu verstehen und zu manipulieren.",al={"belvaril quests","bewahrer bel'varil aufgaben"}}},fx={["07ee922c"]={q="Auf wessen Seite steht Bewahrer Bel'varil?",a="Bewahrer Bel'varil ist loyal gegenüber den Verlassenen und der größeren Horde. Er ist in Tarrens Mühle stationiert und arbeitet an der Seite seiner untoten Brüder, um das Vorgebirge des Hügellands gegen die Aggression der Allianz zu sichern und bei der strategischen Forschung zu helfen, die von seinen Mitstreitern der Verlassenen durchgeführt wird.",al={"bel'varil fraktion","gehört bel'varil zur horde","treue von bel'varil"}},["19ba277e"]={q="Was möchte Bewahrer Bel'varil?",a="Bel'varil sucht nach mystischen Komponenten und Artefakten, um bei der spezialisierten arkanen Forschung zu helfen. Um die Arbeit von Wordeen Voidglare in Tarrens Mühle zu unterstützen, rekrutiert er Reisende, um verzauberte Überreste, wie Stone Tokens und Armschienen der Bindung, von den Elementaren und Ruinen in den umliegenden Regionen zu bergen.",al={"ziel von bel'varil","was benötigt bel'varil","warum bel'varil helfen"}},["4541a85d"]={q="Warum ist Bewahrer Bel'varil hier in Tarrens Mühle?",a="Bewahrer Bel'varil bleibt in Tarrens Mühle stationiert, um die territorialen und arkanen Interessen der Verlassenen im Vorgebirge des Hügellands zu unterstützen. In Zusammenarbeit mit Forschern wie Wordeen Voidglare koordiniert er die Beschaffung magischer Vorräte, die benötigt werden, um ihren Halt gegen nahegelegene Feinde zu stärken.",al={"warum ist bel'varil in tarrens mühle","zweck von bel'varil im hügelland","warum ist bewahrer bel'varil hier"}},b0435467={q="Mit wem ist Bewahrer Bel'varil verbunden?",a="Bewahrer Bel'varil arbeitet eng mit Wordeen Voidglare zusammen, einem weiteren Gelehrten der Verlassenen, der in Tarrens Mühle stationiert ist. Bel'varil fungiert als Assistent und Koordinator, der Abenteurer organisiert, um die spezifischen Materialien und Marken zu sammeln, die Wordeen für seine laufenden Studien benötigt.",al={"verbündete von bel'varil","für wen arbeitet bel'varil","kontakte von bel'varil"}}},fp="16,289,20.386.0,24.217.0,34.109.0,39.164.0"}
P.entries["npc:keldran"] = {n="Keldran",s="Keldran ist ein orcischer Agent, der knapp nördlich des Tal der Geister in Orgrimmar stationiert ist. Er hat es sich zur Aufgabe gemacht, den Weg für eine spätere Diplomatie mit der Allianz zu ebnen, und koordiniert verdeckte Schläge gegen dämonische Überreste, um zu beweisen, dass die moderne Horde der Brennenden Legion wahrhaftig abgeschworen hat.",h="Keldran ist ein orcischer Agent, der knapp nördlich des Tal der Geister in Orgrimmar stationiert ist.",kw={"allianz-beziehungen","burning blade","desolace","keldran","maurin knochenspalter","orgrimmar","takata stahlklinge","tal der geister"},ang={["class:Warlock"]="Keldrans verdeckter Krieg gegen die Burning Blade unterstreicht, wie vehement sich die Führung der Horde von unkontrollierter dämonischer Verderbnis distanzieren möchte.",["faction:Horde"]="Keldran repräsentiert den vorausschauenden Teil der Horde, der die dringende Notwendigkeit erkennt, ihren dämonischen Ruf abzulegen, wenn jemals ein dauerhafter Frieden auf Kalimdor gesichert werden soll."},sec={{t="Ein diplomatischer Kreuzzug",b="Während Thrall vom Valley of Wisdom aus regiert, arbeitet Keldran von den roten Felsterrassen der Stadt aus daran, eine schwelende diplomatische Katastrophe zu lösen. Die Allianz betrachtet alle Orcs noch immer als blutrünstige Marionetten dämonischer Herren – ein Ruf, der sich während der ersten Kriege festigte. Keldran ist überzeugt, dass selbst Thrall des endlosen Konflikts überdrüssig ist, und glaubt, dass echte Friedensverhandlungen niemals stattfinden können, solange dämonenanbetende Kulte in Kalimdor fortbestehen. Ohne formelle Genehmigung des Kriegshäuptlings ergreift er selbst die Initiative und lenkt vertrauenswürdige Agenten gegen ferne Bedrohungen, um den dämonischen Makel ein für alle Mal zu beseitigen."},{t="Der Krieg in Desolace",b="Um sein Anliegen gegenüber der Allianz zu untermauern, nimmt Keldran die düstere Ödnis von Desolace ins Visier. Er entsandte Takata Stahlklinge und Maurin Knochenspalter, um die Operationen gegen die dortigen dämonischen Heimsuchungen anzuführen, wobei er besonderen Wert auf die Vernichtung der Kultisten der Burning Blade legte. Indem er diese dämonischen Praktiker ausmerzt und handfeste Beweise nach Orgrimmar zurückbringt, hofft Keldran unmissverständlich zu demonstrieren, dass die neue Horde ebenso ein Feind der Legion ist wie die Menschen und Nachtelfen."}},faq={{q="Wer ist Keldran?",a="Keldran ist ein Orc nördlich des Tal der Geister in Orgrimmar, der Bestrebungen organisiert, dämonischen Einfluss zu beseitigen und einen Weg zu diplomatischen Allianz-Beziehungen zu ebnen.",al={"wer ist keldran","keldran lore","keldran npc"}},{q="Warum liegen Keldran die Allianz-Beziehungen am Herzen?",a="Keldran glaubt, dass Thrall des ständigen Krieges mit der Allianz müde wird. Er weiß, dass Friedensgespräche unmöglich bleiben werden, solange die Allianz annimmt, die Horde stünde noch immer im Bunde mit der Brennenden Legion.",al={"warum allianz-beziehungen","keldrans motive","warum will er frieden"}},{q="Handelt Keldran auf Thralls offizielle Befehle hin?",a="Nein. Keldran besitzt keine offizielle Autorisierung von Kriegshäuptling Thrall für seine Operation und entscheidet sich dazu, unabhängig zu handeln, um den Namen der Horde reinzuwaschen und das Fundament für zukünftigen Frieden zu legen.",al={"hat thrall keldran geschickt","thralls befehle keldran","ist keldran autorisiert"}},{q="Was tut Keldran in Desolace?",a="Er entsandte Takata Stahlklinge und Maurin Knochenspalter nach Desolace, um die dortigen dämonischen Streitkräfte zu säubern und die Präsenz des Kults der Burning Blade entscheidend auszumerzen.",al={"desolace operation","warum desolace","keldran burning blade"}}},fx={b49902f3={q="Mit wem ist Keldran verbunden?",a="Keldran arbeitet an der Seite loyaler Horde-Agenten, die seine Vision von Frieden teilen. Um seine Strategie gegen Dämonenanbeter in Desolace auszuführen, verlässt er sich auf Takata Stahlklinge und Maurin Knochenspalter und weist sie an, die dämonische Bedrohung zu bekämpfen und die Burning Blade aus der Region zu vertreiben.",al={"keldran verbündete","mit wem arbeitet keldran zusammen","kontakte von keldran"}}},fp="7,277,20.591.0,19.487.1,15.181.0,56.212.0,49.177.0,34.166.0"}
P.entries["npc:kelm-hargunth"] = {n="Kelm Hargunth",s="Kelm Hargunth ist der primäre Nachschuboffizier und Rüstmeister der Vorhut des Kriegshymnenklans und im Mor'shan-Stützpunkt an der nördlichen Grenze des Brachlands stationiert. Er rüstet die Champions der Horde aus, die in den umkämpften Wäldern der Kriegshymnenschlucht gegen die Nachtelfen kämpfen. Durch seine Hilfspakete und Rationen stellt er sicher, dass die Kriegsanstrengungen an der Front stets voll versorgt bleiben.",h="Kelm Hargunth ist der primäre Nachschuboffizier und Rüstmeister der Vorhut des Kriegshymnenklans und im...",kw={"brachland","hilfspaket","kelm hargunth","mor'shan-stützpunkt","pvp-händler","rüstmeister","warsongschlucht","warsongvorhut"},ang={["class:Warrior"]="Frontkrieger verlassen sich in hohem Maße auf Hargunths robuste Plattenbeinlinge, schwere Klingen und Kampfrationen, um die Linie gegen die Allianz zu halten.",["faction:Horde"]="Kelm Hargunth liefert das Rüstzeug des Krieges für jeden Hordensoldaten, der bereit ist, in der Kriegshymnenschlucht die Waffen gegen die Nachtelfen zu erheben.",["race:Orc"]="Für die Orcs stellt Hargunth sicher, dass Grom Hellscreams Vermächtnis in Eschental fortbesteht, indem er den Kriegshymnenklan bewaffnet und ernährt hält."},sec={{t="Rüstmeister von Mor'shan",b="Auf den irdenen Wällen mit Blick auf Eschental überwacht Kelm Hargunth die logistischen Operationen der Vorhut des Kriegshymnenklans im Mor'shan-Stützpunkt. Während Späher und Plünderer jenseits der Palisade scharmützeln, leitet Hargunth den Fluss von Waffen, Rüstungen und Rationen, die zur Aufrechterhaltung eines langwierigen Grenzkriegs erforderlich sind. Für ihn hängt der Sieg gegen die Schildwachen der Silberschwingen ebenso sehr von beständigem Nachschub ab wie von roher Kampfwut."},{t="Nachschub für die Front",b="Hargunth verteilt spezialisierten Nachschub an Krieger, die ihren Mut in der Schlucht bewiesen haben. Von maßgeschneiderten Hilfspaketen voller Verbandszeug und eisernen Rationen bis hin zu meisterhaft gefertigter Rüstung mit dem purpurnen Wappen des Kriegshymnenklans: Seine Vorräte sind strikt jenen vorbehalten, die für die territorialen Ambitionen der Horde in den holzreichen Wäldern des Nordens bluten."}},faq={{q="Wer ist Kelm Hargunth?",a="Kelm Hargunth ist ein orkischer Nachschuboffizier, der die Vorhut des Kriegshymnenklans vertritt. Er ist im Mor'shan-Stützpunkt im nördlichen Brachland stationiert und verteilt Waffen, Rüstungen sowie Kampfproviant an die Soldaten der Horde, die in der Kriegshymnenschlucht kämpfen.",al={"kelm hargunth","wer ist kelm","mor'shan händler","warsong händler"}},{q="Wo befindet sich Kelm Hargunth?",a="Er ist im Mor'shan-Stützpunkt stationiert, der am äußersten nördlichen Rand des Brachlands direkt an der Wallgrenze liegt, die nach Eschental führt.",al={"kelm aufenthaltsort","wo ist kelm hargunth","standort nachschuboffizier mor shan"}},{q="Welcher Fraktion dient Kelm Hargunth?",a="Er dient der Vorhut des Kriegshymnenklans, der Vorhut der Horde, die sich der Sicherung von Holz und der Beanspruchung von Territorien im südlichen Eschental gegen die Nachtelfen verschrieben hat.",al={"kelm fraktion","rüstmeister der warsongvorhut","für wen arbeitet kelm"}},{q="Was sind die Hilfspakete, die Kelm anbietet?",a="Hargunth gibt einfache, gewöhnliche und hochentwickelte Hilfspakete an Frontkämpfer aus. Diese Versorgungspakete enthalten unverzichtbare Schlachtfeldutensilien, Verbände und Rationen, um die Kämpfer der Horde in der Schlucht versorgt zu halten.",al={"hilfspaket der vorhut","kelm hilfspaket","warsong hilfspaket"}},{q="Warum ist der Mor'shan-Stützpunkt für den Kriegshymnenklan so wichtig?",a="Der Mor'shan-Stützpunkt dient als befestigter Sammelplatz und Kontrollpunkt zwischen dem Brachland und Eschental, wodurch der Kriegshymnenklan Nachschub, Verstärkung und geschlagenes Holz sicher in die Gebiete der Horde transportieren kann.",al={"warum mor'shan-stützpunkt","mor'shan zweck","hintergrund stützpunkt"}},{q="Welche Art von Ausrüstung stellt Kelm Hargunth bereit?",a="Er stattet bewährte Kämpfer mit Schlachtwappenröcken des Kriegshymnenklans, Spezialwaffen wie der Klinge des Spähers und dem Schwert des Legionärs, angepassten Rüstungssets, Ringen und Schlachtfeldtränken für den Nahkampf aus.",al={"kelm pvp-ausrüstung","warsong belohnungen","was verkauft kelm"}}},fx={["1810d113"]={q="Warum ist Kelm Hargunth im Mor'shan-Stützpunkt stationiert?",a="Kelm Hargunth dient als Versorgungsoffizier für die Vorhut des Kriegshymnenklans direkt an der Grenze zum Eschental. Er ist im Mor'shan-Stützpunkt stationiert und stellt sicher, dass Champions der Horde, die in die Kriegshymnenschlucht aufbrechen, ordnungsgemäß ausgerüstet sind, um gegen die Schildwachen der Silberschwingen zu kämpfen und lebenswichtiges Holz und Territorium zu sichern.",al={"warum ist kelm hargunth hier","zweck von kelm hargunth","warum ist kelm bei morshan"}},c16a55e1={q="Was möchte Kelm Hargunth?",a="Kelm will nichts Geringeres als den totalen Sieg der Horde gegen die Nachtelfen in der Kriegshymnenschlucht. Als Quartiermeister der Vorhut verlangt er Beweise Eurer Tapferkeit auf dem Schlachtfeld und bietet denjenigen, die hart gegen die Allianz zuschlagen, Rüstungen, Vorräte und Versorgungspakete an.",al={"was möchte kelm hargunth","ziel von kelm hargunth","was möchte kelm"}},bced0f9b={q="An wen ist Kelm Hargunth gebunden?",a="Kelm untersteht direkt der Vorhut des Kriegshymnenklans, der Vorhut der Horde, die um die dichten Wälder des Eschentals kämpft. Er operiert unter dem Banner des Kriegshymnenklans sowie der Horde und arbeitet Hand in Hand mit den Fronttruppen, die den Mor'shan-Stützpunkt verteidigen.",al={"kelm hargunth zugehörigkeit","für wen arbeitet kelm hargunth","kelm hargunth fraktion"}}},fp="13,368,25.422.0,19.376.0,21.229.0,31.145.0,38.150.0,39.217.0,54.220.0,45.216.0"}
P.entries["npc:kerlonian-evershade"] = {fx={["62482562"]={q="Auf wessen Seite steht Kerlonian Schattenspiel?",a="Kerlonian ist ein Nachtelf-Druid of the Claw, der dem Zirkel des Cenarius und den Nachtelfen der Allianz aus Darnassus angehört. Seine Hingabe gilt der Natur, dem Smaragdgrünen Traum und seinen druidischen Brüdern, die die uralten Haine in ganz Kalimdor beschützen.",al={"kerlonian fraktion","ist kerlonian allianz","kerlonian schattenspiel seite"}},["9e991c8a"]={q="Was will Kerlonian Schattenspiel?",a="Da er kürzlich aus seinem langen Schlaf im Smaragdgrünen Traum erwacht ist, wünscht sich Kerlonian nichts sehnlicher als eine sichere Rückkehr zu seinen Nachtelfen-Gefährten bei Maestras Posten. Seine tiefe Trance macht ihn schläfrig, was selbst einfache Reisen durch die Dunkelküste zu einem gefährlichen Unterfangen macht.",al={"kerlonian ziel","was will kerlonian schattenspiel","kerlonian zweck"}},["4cb7152a"]={q="Warum ist Kerlonian Schattenspiel hier?",a="Kerlonian hat am Grove of the Ancients für ein kurzes Nickerchen angehalten, während er auf dem Weg war, um Liladris Moonriver bei Maestras Posten zu treffen. Er ist nach dem Erwachen aus dem Smaragdgrünen Traum immer noch schläfrig und bittet um Hilfe, um sie sicher zu erreichen.",al={"warum ist kerlonian in der dunkelküste","kerlonian grove of ancients","warum schläft kerlonian hier"}},["0418b012"]={q="An wen ist Kerlonian Schattenspiel gebunden?",a="Kerlonian gehört zu den Druid of the Claw, einem Orden innerhalb des Zirkel des Cenarius, der dem Bärengeist gewidmet ist und die Aufgabe hat, die Wildnis zu bewachen. Er ist außerdem durch Verwandtschaft und Pflicht an die Nachtelfen gebunden, die bei Maestras Posten an der Grenze zum Eschental stationiert sind.",al={"kerlonian orden","kerlonian verbindungen","wem dient kerlonian"}}}}
P.entries["npc:kernobee"] = {n="Kernobee",s="Kernobee ist ein Goblin-Ingenieur, der tief in den verfallenen Hallen von Gnomeregan gefangen ist. Nachdem er auf gefährliche Geheimnisse über die Sabotage der Dunkeleisenzwerge gestoßen war, wurde er gefangen genommen, bewusstlos geschlagen und bei den Troggs in den Schlafsälen zum Sterben zurückgelassen.",h="Kernobee ist ein Goblin-Ingenieur, der tief in den verfallenen Hallen von Gnomeregan gefangen ist.",kw={"dunkeleisenzwerge","schlafsaal","gnomeregan","kernobee","ratschet","superbohrer","tinkerwiz"},ang={["profession:Engineering"]="Ingenieure können die schiere Gefahr nachvollziehen, die das Herumschnüffeln an experimentellen Untertagemaschinen wie den Dunkeleisen-Bohrern birgt, wenn es um konkurrierende Baupläne geht.",["race:Gnome"]="Für Gnome, die um die Rückeroberung ihrer Heimat kämpfen, ist Kernobees Information ein alarmierender Beweis dafür, dass ihre Katastrophe aus dem Verborgenen durch die Einmischung der Dunkeleisenzwerge begünstigt wurde."},sec={{t="Eine tödliche Entdeckung",b="Während er in der gefallenen Gnomenhauptstadt Geschäfte abwickelte oder nach Brauchbarem suchte, deckte Kernobee ein schwerwiegendes Geheimnis auf: Die Dunkeleisenzwerge waren direkt am Bau und Betrieb der gewaltigen Superbohrer beteiligt, die sich unter der Stadt hindurchgruben. Da er den immensen Wert – und die Tödlichkeit – dieser Informationen erkannte, versuchte er sofort nach Ratschet zu fliehen, um seinem Partner Tinkerwiz Bericht zu erstatten. Unglücklicherweise schnappten ihn die Dunkeleisenzwerge, bevor ihm die Flucht gelang."},{t="Den Troggs überlassen",b="Anstatt ihn auf der Stelle zu töten, schlugen seine Entführer Kernobee bewusstlos und warfen ihn in einen kleinen Raum entlang des Schlafsalkorridors, gegenüber der Clean Zone. Gestrandet zwischen wilden Troggs und radioaktivem Niederschlag, ist der geschundene Goblin vollkommen darauf angewiesen, dass vorbeikommende Abenteurer ihn wiederbeleben und beschützen, bis er sich in Sicherheit bringen kann."}},faq={{q="Wer ist Kernobee?",a="Kernobee ist ein Goblin-Agent, der bewusstlos im Schlafsaalsektor von Gnomeregan aufgefunden wird. Er arbeitet eng mit Tinkerwiz in Ratschet zusammen und wagte sich in die Ruinen, bevor er in einen Hinterhalt geriet.",al={"wer ist dieser goblin","kernobee lore","über kernobee"}},{q="Warum wurde Kernobee in Gnomeregan gefangen gehalten?",a="Kernobee entdeckte, dass der Dunkeleisenclan heimlich beim Bau der unterirdischen Superbohrer-Maschinen in der Stadt half. Um ihre Anwesenheit und Sabotage geheim zu halten, setzten die Dunkeleisenzwerge ihn außer Gefecht und warfen ihn in den Schlafsaal, damit er dort umkommt.",al={"warum ist er hier","warum nahmen die dunkeleisenzwerge ihn gefangen","warum im schlafsaal"}},{q="Wem untersteht Kernobee?",a="Er untersteht Tinkerwiz, einem Goblin-Ingenieur, der jenseits des Meeres in der neutralen Hafenstadt Ratschet im Brachland stationiert ist.",al={"wer ist tinkerwiz","wohin geht er","verbindung nach ratschet"}},{q="Wo in Gnomeregan befindet sich Kernobee?",a="Er liegt zusammengesunken und bewusstlos in einem kleinen Nebenraum auf der unteren Ebene des Schlafsaals, auf der Westseite direkt gegenüber der Clean Zone.",al={"kernobee standort","wo ist kernobee","kernobee finden"}}},fx={["3c758521"]={q="Auf wessen Seite steht Kernobee?",a="Kernobee gehört zum Steamwheedle Cartel und untersteht Tinkerwiz im neutralen Hafen von Ratschet. Anstatt der Allianz oder der Horde zu dienen, kümmert er sich um Goblin-Geschäfte – was ihn direkt gegen die Dunkeleisenzwerge stellte, die in Gnomeregan lauerten, sobald er ihre Pläne aufdeckte.",al={"ist kernobee allianz oder horde","kernobee fraktion","für wen arbeitet kernobee"}},b63dca8d={q="Was will Kernobee?",a="Kernobee will nichts sehnlicher, als Gnomeregan lebend zu entkommen. Nachdem er entdeckt hat, dass Dunkeleisenzwerge am Bau der massiven Superbohranlage beteiligt waren, muss er dringend das Wohnheim verlassen und aus der verstrahlten Stadt fliehen, um seine Erkenntnisse Tinkerwiz in Ratschet melden zu können.",al={"was versucht kernobee zu tun","kernobee ziel","warum kernobee helfen"}}},fp="8,253,18.470.0,19.335.0,16.180.0,42.247.0,28.119.0,40.149.0"}
P.entries["npc:keryn-sylvius"] = {n="Keryn Sylvius",s="Keryn Sylvius ist eine menschliche Schurkenlehrerin, die sich im zweiten Stock des Gasthauses \"Zur Höhle des Löwen\" in Goldhain aufhält. Zurückgezogen im Lesezimmer des Gasthauses bringt sie angehenden Halunken die Grundlagen der Verstohlenheit und Klingenkunst bei und fungiert zugleich als stilles Bindeglied zum Geheimdienst von Sturmwind.",h="Keryn Sylvius ist eine menschliche Schurkenlehrerin, die sich im zweiten Stock des Gasthauses \"Zur Höhle des...",kw={"wald von elwynn","goldhain","keryn sylvius","gasthaus \"zur höhle des löwen\"","schurkenlehrer","der si:7"},ang={["class:Rogue"]="Sylvius ist die primäre Mentorin für aufstrebende Schurken, die den Wald von Elwynn durchstreifen, und weist ihnen schließlich den Weg zum Hauptquartier des SI:7 in Sturmwind.",["faction:Alliance"]="Über der Kreuzung von Goldhain stationiert, hilft sie dabei, die verborgenen Augen der Allianz entlang der Hauptverkehrswege von Elwynn offenzuhalten."},sec={{t="Eine ruhige Gestalt in Goldhain",b="Während das Erdgeschoss des Gasthauses \"Zur Höhle des Löwen\" von lauten Reisenden und erschöpften Stadtwachen wimmelt, hält sich Keryn Sylvius im ruhigen Lesezimmer im Obergeschoss auf. Äußerlich unauffällig, beobachtet sie den stetigen Strom an Gerüchten von der Straße und dient als örtliche Mentorin für Schurken, die im Wald von Elwynn ihre ersten Erfahrungen sammeln. Sobald vielversprechende Agenten den lokalen kleinen Diebereien und Gaunereien am Wegesrand entwachsen sind, schickt Sylvius sie diskret weiter nach Sturmwind, um Kontakt mit dem SI:7 aufzunehmen."}},faq={{q="Wo kann ich Keryn Sylvius finden?",a="Sie befindet sich im zweiten Stock des Gasthauses \"Zur Höhle des Löwen\" in Goldhain, abgeschieden im kleinen Lesezimmer.",al={"keryn sylvius aufenthaltsort","wo ist keryn","goldhain schurkenlehrer aufenthaltsort"}},{q="Welche Dienste bietet sie an?",a="Keryn Sylvius ist eine Schurkenlehrerin, die neue Fähigkeiten lehrt, Talentspezialisierungen zurücksetzt und aufstrebenden Schurken den Weg weist.",al={"was tut keryn","kann sie mich ausbilden","keryn sylvius rolle"}},{q="Welche Verbindung hat sie zum SI:7?",a="Sylvius dient als frühe Anlaufstelle für Sturmwinds geheimes Spionagenetzwerk und schickt fähige Agenten zu Meister Mathias Shaw und dem SI:7 in der Altstadt, sobald sie ihr Können unter Beweis gestellt haben.",al={"keryn der si:7","gehört sie zum si:7","arbeitet sie für sturmwind"}}},fx={["74741391"]={q="Wer ist Keryn Sylvius?",a="Keryn Sylvius ist eine Schurkenlehrerin, die ihr Zuhause im oberen Stockwerk des Gasthauses \"Zur Höhle des Löwen\" in Goldhain hat. Versteckt im ruhigen Leseraum beobachtet sie das Kommen und Gehen im Wald von Elwynn, während sie aufstrebenden Schurken unter dem Banner der Allianz die subtilen Künste der Verstohlenheit, des Schlösserknackens und der Täuschung vermittelt.",al={"wer ist keryn","keryn sylvius hintergrund","wer ist sylvius"}},["017a68dc"]={q="Auf wessen Seite steht Keryn Sylvius?",a="Keryn steht fest hinter dem Königreich Sturmwind und der Allianz. Ihr Handwerk dient den Interessen des Reiches, indem sie talentierte Agenten stillschweigend an das geheime Geheimdienstnetzwerk von Sturmwind verweist, damit diese das Königreich gegen interne Unruhen und äußere Bedrohungen unterstützen können.",al={"keryn sylvius allianz oder horde","keryn sylvius loyalität","wem dient keryn sylvius"}},["90e34396"]={q="Was will Keryn Sylvius?",a="Keryn zielt darauf ab, junge Talente im ruhigen Herzen von Elwynn auszukundschaften und anzuleiten, bevor sie mit dem Gesetz in Konflikt geraten oder ihre tödlichen Fähigkeiten missbrauchen. Sobald sich ein Lehrling als fähig erweist, besteht ihr Ziel darin, seine Fähigkeiten in geordnete Bahnen zu lenken, indem sie ihn an das Hauptquartier von SI:7 in der Altstadt verweist.",al={"was will keryn","keryn sylvius ziele","warum schurken ausbilden"}},f8e496c4={q="Warum ist Keryn Sylvius hier in Goldhain?",a="Das Gasthaus \"Zur Höhle des Löwen\" dient als geschäftiger Knotenpunkt im Wald von Elwynn und ist daher ein idealer Ort, um unauffällig Schurken zu identifizieren, die außerhalb des Nordhaintals ihre ersten Schritte machen. Ihr Posten im Obergeschoss bietet ihr einen diskreten Ort, um Anfänger auszubilden, ohne unnötige Aufmerksamkeit von den örtlichen Wachen oder den Stadtbewohnern unter ihr zu erregen.",al={"warum ist keryn im gasthaus zur höhle des löwen","warum ist keryn sylvius in goldhain","keryn goldhain grund"}}},fp="13,279,29.470.0,31.108.0,29.135.0,38.201.0"}
P.entries["npc:khelden-bremen"] = {n="Khelden Bremen",s="Khelden Bremen ist ein menschlicher Magier und Ausbilder, der sich im oberen Stockwerk der Abtei von Nordhain im Wald von Elwynn aufhält. Er beaufsichtigt die allererste Ausbildung von Zauberwirker-Neulingen, die im Dienste von Sturmwind die arkanen Künste erlernen.",h="Khelden Bremen ist ein menschlicher Magier und Ausbilder, der sich im oberen Stockwerk der Abtei von Nordhain...",kw={"arkan","wald von elwynn","glyphenbrief","khelden bremen","magierlehrer","abtei von nordhain"},ang={["class:Mage"]="Für menschliche Magier stellt Khelden Bremen den ersten formellen Schritt in die arkane Gelehrsamkeit dar, bevor sie ihre fortgeschrittene Ausbildung in den Türmen von Sturmwind fortsetzen."},sec={{t="Lehrer des Arkanen",b="Inmitten der ruhigen Steinmauern der Abtei von Nordhain fungiert Khelden Bremen als primärer Ausbilder für angehende menschliche Magier. Während sich die Geistlichen und Verteidiger unten den kriegerischen und spirituellen Belangen widmen, unterhält Bremen im Obergeschoss ein ruhiges Studierzimmer. Hier führt er Novizen an die Disziplin, die Konzentration und die grundlegenden Techniken heran, die erforderlich sind, um rohe magische Energie sicher zu weben, bevor sie in den Wald von Elwynn und weiter in das Magierviertel von Sturmwind hinausziehen."}},faq={{q="Wer ist Khelden Bremen?",a="Khelden Bremen ist der ansässige Magierlehrer in der Abtei von Nordhain im Wald von Elwynn. Er leitet neu erwachte Magier bei ihren ersten Zaubern und den grundlegenden arkanen Studien an.",al={"wer ist khelden","bremen","magierlehrer nordhain"}},{q="Wo finde ich Khelden Bremen?",a="Er befindet sich im zweiten Stock der Abtei von Nordhain. Betretet die Abtei und geht die Treppe im zweiten Raum auf der linken Seite hinauf.",al={"wo ist khelden","khelden bremen aufenthaltsort","nordhain magierlehrer standort"}},{q="Welche Rolle spielt er für neue Abenteurer?",a="Angehende menschliche Magier werden nach ihrer Ankunft in Nordhain an Khelden verwiesen, oft mit einem Glyphenbrief als Empfehlungsschreiben. Er lehrt wichtige Anfangszauber und hilft Novizen dabei, ihre magische Begabung zu nutzen.",al={"was macht khelden","bremen quests","empfänger von glyphen-brief"}}},fx={["7cfd66d2"]={q="Auf wessen Seite steht Khelden Bremen?",a="Khelden Bremen steht fest an der Seite des Königreichs Sturmwind und der Allianz. Er ist in der Abtei von Nordhain stationiert und dient dem Reich, indem er die nächste Generation von Zauberwirkern unterweist und sie darauf vorbereitet, die Ländereien der Menschheit gegen aufkommende Gefahren zu verteidigen.",al={"fraktion khelden bremen","wem dient khelden","ist khelden bremen bei der allianz"}},["032606f2"]={q="Was möchte Khelden Bremen?",a="Kheldens Ziel ist es, angehende Magier in den arkanen Künsten zu unterrichten. Er sucht engagierte Lehrlinge, die bereit sind, grundlegende Zauber zu erlernen, ihren wachsenden Intellekt zu meistern und ihre Macht verantwortungsbewusst für die Sicherheit des Waldes von Elwynn und Sturmwind einzusetzen.",al={"ziel von khelden bremen","was will khelden"}},["8660ec47"]={q="Warum ist Khelden Bremen hier in der Abtei von Nordhain?",a="Die Abtei von Nordhain dient als Zufluchtsort für Rekrutierung und Ausbildung junger Verteidiger, die dem Ruf Sturmwinds folgen. Bremen hält sich im oberen Stockwerk der Abtei auf, speziell um angehende menschliche Praktizierende zu empfangen und ihre ersten Schritte in der Magie zu lenken, bevor sie sich tiefer in das weitere Reich vorwagen.",al={"warum ist khelden in nordhain","warum ist khelden bremen hier"}}},fp="14,225,19.459.0,22.172.0,32.134.0,43.205.0"}
P.entries["npc:kil-hala"] = {fx={["5b372e18"]={q="Auf wessen Seite steht Kil'hala?",a="Kil'hala ist der Horde und seinem Volk, den Dunkelspeertrollen, treu. Im Herzen des Wegekreuzes dient er als Schneidereilehrer, um Reisende, Krieger und angehende Handwerker, die durch Kalimdor ziehen, auszurüsten.",al={"kil'hala horde oder allianz","kil'hala fraktion","wem dient kil'hala"}},["218c0279"]={q="Warum ist Kil'hala hier?",a="Kil'hala hat sein Zuhause am Wegekreuz, einem wichtigen Knotenpunkt, der Durotar, Mulgore und die nördliche Wildnis verbindet. Durch seine Stationierung hier kann er den stetigen Strom von Horde-Abenteurern, die das Brachland durchqueren, seine Handwerkskunst und Beratung anbieten.",al={"warum ist kil'hala am wegekreuz","warum ist kil'hala im brachland","kil'hala standort grund"}}}}
P.entries["npc:kin-weelay"] = {n="Kin'weelay",s="Kin'weelay ist ein renommierter Hexendoktor der Dunkelspeere, der im Basislager von Grom'gol im Schlingendorntal stationiert ist. Direkt aus Orgrimmar entsandt, bietet er der Vorhut der Horde im Dschungel mystischen Beistand und Rat. Seine spirituelle Expertise ist unerlässlich, um dunkles Mojo zu brechen und bei der Rettung des jungen Yenniku zu helfen.",h="Kin'weelay ist ein renommierter Hexendoktor der Dunkelspeere, der im Basislager von Grom'gol im...",kw={"dunkelspeer","grom'gol","kin'weelay","kinweelay","gedankenauge","schlingendorntal","hexendoktor","yenniku"},ang={["faction:Horde"]="Kin'weelay demonstriert den Wert des Troll-Spiritualismus für die Kriegsanstrengungen der Horde, indem er magische Gegenstrategien gegen Bedrohungen liefert, die mit reiner Stärke nicht bezwungen werden können.",["race:Troll"]="Für die Dunkelspeere verkörpert Kin'weelay eine der angesehensten spirituellen Autoritäten des Stammes, die sich der Aufhebung der grausamen Flüche ihrer Dschungelverwandten verschrieben hat."},sec={{t="Ein Meister des Dunkelspeer-Mojo",b="Unter den Dunkelspeeren als einer ihrer mächtigsten Ausüber traditioneller Hexendoktorkunst anerkannt, verfügt Kin'weelay über tiefes Wissen über Geister, Flüche und Seelenmagie. Wenn Angelegenheiten rund um Ahnengeister oder feindselige Troll-Verzauberungen auftreten, wenden sich die Späher der Horde im Schlingendorntal an ihn, um den magischen Schleier zu durchdringen."},{t="Die Mission nach Grom'gol",b="Kin'weelay wurde aus den staubigen Straßen von Orgrimmar nach Süden geschickt, um Nimboya im Basislager von Grom'gol gezielt zu unterstützen. Seine Bestimmung geht über einfache militärische Hilfe hinaus; sein Fokus liegt darauf, die unheilvollen Bande zu zerbrechen, die dem entführten Yenniku auferlegt wurden, dem Sohn aus der vertrauten Blutlinie von Häuptling Vol'jin. Um solch dunkles Handwerk rückgängig zu machen, sucht Kin'weelay nach mächtigen Reagenzien – allen voran dem Gedankenauge –, um einen Seelenedelstein anzufertigen, der gefangene Geister befreien kann."}},faq={{q="Wer ist Kin'weelay?",a="Kin'weelay ist ein hochgeschätzter Hexendoktor der Dunkelspeer, der im Basislager von Grom'gol im nördlichen Schlingendorntal stationiert ist. Bekannt für seine Meisterschaft über Geist- und Seelenmagie, wurde er von der Führung der Horde aus Orgrimmar entsandt.",al={"kinweelay lore","wer ist kin'weelay","grom'gol hexendoktor"}},{q="Warum ist Kin'weelay im Schlingendorntal?",a="Er wurde in das Basislager Grom'gol geschickt, um Nimboya und der dortigen Dunkelspeer-Expedition seine mystischen Talente zur Verfügung zu stellen, insbesondere bei der Suche und Rettung des jungen Yenniku aus den Klauen feindseliger Dschungeltrolle.",al={"warum ist kinweelay in grom'gol","kinweelay aufgabe"}},{q="Was versucht Kin'weelay herzustellen?",a="Kin'weelay versucht, ein Relikt namens Gedankenauge in seinen Besitz zu bringen. Mit seiner Hexenkunst beabsichtigt er, es zu einem Seelenedelstein zu verarbeiten, der die Seele von Yenniku einfangen und sicher bewahren kann, um die finstere Beherrschung des Jungen zu brechen.",al={"kinweelay gedankenauge","was stellt kinweelay her"}},{q="Woher stammt Kin'weelay?",a="Er reiste aus Orgrimmar an, wo der Stamm der Dunkelspeer seit seinem Beitritt zur Horde und der Besiedlung der Echoinseln eine starke Verbindung und Präsenz aufrechterhält.",al={"kinweelay hintergrund","woher kommt kinweelay"}},{q="Wie sieht er die anderen Trollstämme des Schlingendorntals?",a="Er betrachtet feindliche Dschungelstämme wie die Bloodscalp und Schädelspalter als gefährliche Rivalen, die in gewalttätigen, verderbten Ritualen versunken sind. Er setzt seine Künste aktiv ein, um ihren Bannzaubern entgegenzuwirken und die geraubte Jugend der Dunkelspeer zurückzuholen.",al={"kinweelay andere trolle","kinweelay und bloodscalp"}},{q="Welche Arten von Gegenständen erforscht Kin'weelay?",a="Kin'weelay untersucht lokale Kuriositäten mit natürlicher oder verhexter Resonanz, darunter die geheimnisvollen singenden Kristalle und Knochenhalsketten feindlicher Dschungeltrolle, und studiert deren Mojo, um Gegenmaßnahmen zu entwickeln.",al={"kinweelay gegenstände","singende kristalle kinweelay"}}},fp="10,308,26.324.0,23.444.1,18.227.0,40.201.0,36.222.0,32.146.0,57.216.0,41.219.0"}
P.entries["npc:kirge-sternhorn"] = {n="Kirge Sternhorn",s="Kirge Sternhorn ist ein Taure, der an der rauen Grenze des Brachlands stationiert ist. Als verlässlicher Ansprechpartner für Reisende, die das zentrale Kalimdor durchqueren, weist er unerfahrenen Abenteurern der Horde den Weg nach Norden zum wichtigen Außenposten Das Wegekreuz.",h="Kirge Sternhorn ist ein Taure, der an der rauen Grenze des Brachlands stationiert ist.",kw={"brachland","das wegekreuz","kirge","südliches brachland","sternhorn","taurajo","tauren"},ang={["faction:Horde"]="Für Reisende, die aus den südlichen Gebieten kommen, dient Kirge als früher Wegpunkt, der sie zur größeren Gemeinschaft der Horde im Wegekreuz leitet.",["race:Tauren"]="Kirge verkörpert den bodenständigen, gastfreundlichen Geist der Shu'halo und führt Stammesverwandte sowie Verbündete durch die raue Grenzregion ihrer Wahlheimat."},sec={{t="Ein Wanderer im Brachland",b="Die weiten, sonnenverbrannten Ebenen des Brachlands wirken auf neu eingetroffene Wanderer entmutigend, und Kirge Sternhorn steht ihnen als hilfsbereiter Wegweiser zur Seite. Südlich der zentralen Pfade postiert, wacht er über Reisende, die zwischen den südlichen Lagern und dem Herzen von Kalimdor unterwegs sind. Im Bewusstsein der Gefahren durch marodierende Borstennacken und wilde Raubtiere, welche die Savanne durchstreifen, sorgt Kirge dafür, dass junge Abenteurer Fuß fassen und die größere Hordenpräsenz aufsuchen, die sich im Norden sammelt."}},faq={{q="Wer ist Kirge Sternhorn?",a="Kirge Sternhorn ist ein taurischer Wanderer und Wegweiser, der in den südlichen Weiten des Brachlands stationiert ist und Reisenden der Horde dabei hilft, die staubigen Ebenen zu durchqueren.",al={"kirge sternhorn lore","wer ist kirge","kirge nsc"}},{q="Wohin schickt Kirge Reisende?",a="Kirge schickt Reisende nach Norden in Richtung Das Wegekreuz, dem zentralen Knotenpunkt im Brachland, an dem die Streitkräfte der Horde die Verteidigung und Erkundung der Region koordinieren.",al={"kirge quest","reise zum wegekreuz kirge","wohin schickt kirge euch"}},{q="Welcher Fraktion dient Kirge Sternhorn?",a="Kirge ist der Horde und seinen taurischen Brüdern und Schwestern treu ergeben und bietet allen Mitgliedern der Fraktion, die durch das Gebiet reisen, Führung und Hilfe an.",al={"ist kirge horde","kirge fraktion"}}},fp="15,248,25.483.0,23.150.0,32.161.0,40.146.0"}
P.entries["npc:klannoc-macleod"] = {n="Klannoc Macleod",s="Klannoc Macleod ist ein abgehärteter menschlicher Krieger, der auf Prügel-Eiland vor den östlichen Gestaden des Brachlands lebt. Bekannt als Prüfer kriegerischer Fähigkeiten, testet er aufstrebende Raufbolde sowohl der Allianz als auch der Horde, die die Kampfhaltungen meistern wollen. Jene, die sich seinen Respekt verdienen, schickt er weiter ins Landesinnere zu noch größeren Prüfungen der Stärke.",h="Klannoc Macleod ist ein abgehärteter menschlicher Krieger, der auf Prügel-Eiland vor den östlichen Gestaden...",kw={"brachland","berserker","prügel-eiland","insulaner","klannoc","macleod","der ringkampf","krieger"},ang={["class:Warrior"]="Klannoc Macleod ist eine Schlüsselfigur auf der Reise eines Kriegers; er testet Eure Ausdauer und Wildheit im Ringkampf, bevor er Euch auf den Weg zur Beherrschung der Berserkerhaltung führt.",["faction:Alliance"]="Krieger der Allianz müssen weit in Kalimdors Gewässer vor der Küste des Brachlands vordringen, um Klannoc zu finden und ihre Kampfbereitschaft auf Prügel-Eiland zu beweisen.",["faction:Horde"]="Obwohl er ein Mensch ist, schert sich Klannoc nicht um Fraktionsrivalitäten und heißt Kämpfer der Horde willkommen, die auf seiner abgelegenen Insel nach Prüfung und Ehre suchen."},sec={{t="Der Meister von Prügel-Eiland",b="Abgeschieden auf Prügel-Eiland vor der Händlerküste im Brachland überwacht Klannoc Macleod einen brutalen Richtplatz für erfahrene Kämpfer. Obwohl er ein Mensch ist, hält sich Klannoc aus den typischen politischen Streitigkeiten von Allianz und Horde heraus und beurteilt Herausforderer einzig nach ihrem Schneid, ihrer Klingenführung und ihrer Entschlossenheit im Gefecht."},{t="Der Ringkampf",b="Krieger, die nach Prügel-Eiland entsandt werden, müssen sich Macleods Prüfung stellen: dem Ringkampf. Die Anwärter betreten ein erhöhtes Eisengitter, um unbarmherzigen Wellen eifriger Raufbolde zu trotzen, während Klannoc zusieht. Jene, die dem Ansturm standhalten und seinen auserwählten Champion besiegen, verdienen sich seine Anerkennung und beweisen, dass sie das nötige Temperament für die Ausbildung zum Berserker besitzen."}},faq={{q="Wer ist Klannoc Macleod?",a="Klannoc Macleod ist ein erfahrener menschlicher Krieger, der auf Prügel-Eiland direkt vor der Küste des Brachlands haust. Er dient als Ausbilder und Prüfungsmeister für Krieger, die ihre Grenzen austesten und neue Techniken erlernen wollen.",al={"wer ist klannoc","klannoc macleod geschichte","prügel-eiland typ"}},{q="Wo finde ich Klannoc Macleod?",a="Klannoc befindet sich auf Prügel-Eiland, einer felsigen Insel vor der Ostküste des Brachlands, südöstlich der Händlerküste und von Ratschet. Ihr müsst durch das offene Wasser schwimmen, um sein Lager zu erreichen.",al={"klannoc aufenthaltsort","wo ist prügel-eiland","weg zu klannoc"}},{q="Warum spricht ein Mensch auf Prügel-Eiland mit Horde-Spielern?",a="Klannoc steht außerhalb des traditionellen Konflikts zwischen Allianz und Horde. Als unabhängiger Kampfmeister schert er sich nur um kriegerische Disziplin und den Kriegerkodex und stellt jeden Herausforderer auf die Probe, der mit einer angemessenen Empfehlung anreist.",al={"ist klannoc der horde feindlich","warum ist klannoc neutral","horde klannoc"}},{q="Was ist der Ringkampf?",a="Der Ringkampf ist eine Ausdauerprüfung, die auf Prügel-Eiland stattfindet. Ein Krieger muss auf Klannocs Kampfplattform stehen und Wellen von Herausforderern besiegen, was in einem Kampf gegen Big Will gipfelt, um zu beweisen, dass er die nötige Wildheit für fortgeschrittene Kriegertechniken besitzt.",al={"der ringkampf quest","prügel-eiland prüfung","klannoc prüfung"}},{q="Warum werden Krieger zu Klannoc Macleod geschickt?",a="Kriegerausbilder in ganz Azeroth verweisen ihre vielversprechendsten Schüler an Klannoc, damit sie sich einer Prüfung kriegerischer Standhaftigkeit unterziehen, die nötig ist, um sie auf den wilden Fokus der Berserkerhaltung vorzubereiten.",al={"kriegerquest prügel-eiland","warum zu klannoc","berserkerhaltung quest"}},{q="Zu wem schickt Klannoc einen nach dem Ringkampf?",a="Nachdem Ihr Euren Mut im Ringkampf bewiesen habt, schickt Klannoc die Krieger nach Norden ins Alteracgebirge nahe Tarrens Mühle, um Bath'rah den Windbehüter für weitere Unterweisungen aufzusuchen.",al={"nach klannoc","der windbehüter quest","wer ist der windbehüter"}}},fx={bf19a78f={q="Was will Klannoc Macleod?",a="Klannoc beaufsichtigt die Kampfprüfungen auf dem Prügel-Eiland und sucht nur nach fähigen Schlägern, die es wert sind, für The Affray in den Ring zu steigen. Er kümmert sich nicht um Fraktionspolitik oder die Herkunft der Kämpfer, sondern fordert nur, dass diejenigen, die seinen Rat suchen, ihren Mut und ihre Ausdauer in einem harten Kampf unter Beweis stellen, bevor er sie an eine weiterführende Kampfausbildung verweist.",al={"was will klannoc macleod","was will klannoc","klannoc zweck"}}},fp="15,346,25.330.0,10.352.0,23.214.0,33.185.0,54.232.0,19.252.0,37.191.0,46.174.1"}
P.entries["npc:kor-ghan"] = {n="Kor'ghan",s="Kor'ghan ist ein Dschungeltroll der Dunkelspeere, der sich in den düsteren Höhlen der Kluft der Schatten in Orgrimmar aufhält. Direkt vor Rekkul's Poisons bittet er um Unterstützung bei der Zubereitung von Heilmitteln gegen giftige Raubtiere der Wildnis.",h="Kor'ghan ist ein Dschungeltroll der Dunkelspeere, der sich in den düsteren Höhlen der Kluft der Schatten in...",kw={"gegengift","die kluft der schatten","kor'ghan","korghan","orgrimmar","rekkul's poisons","skorpiongift","sen'jin"},ang={["class:Rogue"]="Direkt vor Rekkul's Poisons in der Kluft der Schatten postiert, ist Kor'ghan ein vertrauter Anblick für Schurken, die die Schattenseiten von Orgrimmar auf der Suche nach Reagenzien und Giften aufsuchen.",["race:Troll"]="Wie viele seiner Dunkelspeer-Verwandten, die Sen'jin verlassen haben, nutzt Kor'ghan sein praktisches Wissen über die wilden Gefahren Durotars in der befestigten Hauptstadt der Horde."},sec={{t="Ein Troll in den Schatten",b="Vor Rekkul's Poisons in den höhlenartigen Tiefen der Kluft der Schatten wacht Kor'ghan sowohl über Heilmittel als auch über Toxine. Von der Hauptstadt aus entsendet er Abenteurer durch die roten Schluchten, um giftige Bestandteile von den Skorpione Durotars zu sammeln und so lebenswichtige Gegengifte herzustellen."}},faq={{q="Wer ist Kor'ghan?",a="Kor'ghan ist ein Dunkelspeer-Troll in der Kluft der Schatten in Orgrimmar, der vor Rekkuls Giftladen steht.",al={"kor'ghan","wer ist kor'ghan","korghan nsc"}},{q="Wo kann ich Kor'ghan finden?",a="Er befindet sich in der unterirdischen Kluft der Schatten unter dem Zentrum von Orgrimmar, direkt vor Rekkul's Poisons.",al={"kor'ghan aufenthaltsort","wo ist korghan","korghan finden"}},{q="Wobei benötigt Kor'ghan Hilfe?",a="Er bittet Reisende darum, Giftbeutel von den Giftschwanzskorpionen zu sammeln, die nahe dem Eingang von Orgrimmar umherstreifen, um bei der Herstellung von Gegengiften zu helfen.",al={"kor'ghan quest","suche nach dem gegengift quest","korghan gift"}},{q="War Kor'ghan jemals in Durotar anzutreffen?",a="Er selbst nicht. Kor'ghan bleibt an seinem Platz nahe den Giftlieferanten in Orgrimmar, doch er schickt Abenteurer nach Durotar hinaus, um Giftbeutel von den Giftschwanzskorpionen nahe dem Stadttor zu beschaffen.",al={"kor'ghan sen'jin","korghan alter aufenthaltsort"}}},fx={["8434b88c"]={q="Auf wessen Seite steht Kor'ghan?",a="Kor'ghan gehört zur Horde. Als Dschungeltroll der Dunkelspeere, der tief in der Kluft der Schatten in Orgrimmar lebt, gilt seine Loyalität fest seinem Volk und der neuen Heimat, die sie unter Kriegshäuptling Thrall teilen.",al={"kor'ghan fraktion","ist kor'ghan horde","kor'ghan allianz oder horde"}},["041d8a17"]={q="Warum ist Kor'ghan hier?",a="Kor'ghan hat seinen Platz direkt vor Rekkuls Gifte in den schattigen Tiefen der Kluft der Schatten. Er hält sich bei den Schurken und Alchemisten der Stadt auf und sucht bei denjenigen, die mit gefährlichen Mixturen handeln, nach spezieller Hilfe und giftigen Heilmitteln.",al={"warum ist kor'ghan in orgrimmar","warum ist kor'ghan in der kluft der schatten","was brachte kor'ghan hierher"}}},fp="8,246,22.296.0,16.113.0,26.125.0,34.138.0,35.197.0"}
P.entries["npc:korran"] = {n="Korran",s="Korran ist ein Forscher der Dunkelspeertrolle, der im Wegekreuz im Brachland stationiert ist. Im Dienste von Belgrom Rockmaul in Orgrimmar überwacht er merkwürdige Vorkommnisse im gesamten Buschland und erforscht die aufkeimende Bedrohung durch die insektoiden Silithiden.",h="Korran ist ein Forscher der Dunkelspeertrolle, der im Wegekreuz im Brachland stationiert ist.",kw={"brachland","belgrom rockmaul","das wegekreuz","eierjagd","feld der riesen","korran","silithid"},ang={["faction:Horde"]="Korran verkörpert das wachsame Auge der Horde auf die sich wandelnde Ökologie Kalimdors und stellt sicher, dass neue Bedrohungen wie die Silithiden Orgrimmar nicht unvorbereitet treffen, während es seine Grenzen sichert.",["race:Troll"]="Als Dunkelspeertroll bringt Korran scharfe Späher- und Überlebensinstinkte in das trockene Brachland ein und setzt pragmatische Schläue ein, um seltsame, fremdartige Bestien zu analysieren."},sec={{t="Ein Späher im Wegekreuz",b="Während sich die meisten im Wegekreuz mit aggressiven Borstennacken und lokalen Zentaurenklans befassen, hält Korran ein wachsames Auge auf subtilere, heimtückischere Gefahren gerichtet. Auf Befehl von Belgrom Rockmaul in Orgrimmar stationiert, beobachtet der Trollspäher das sich verändernde Land und koordiniert das Sammeln von Informationen für die Führung der Horde."},{t="Der Silithideneinfall",b="Korrans Hauptaugenmerk hat sich nach Süden zum Feld der Riesen verlagert, wo seltsame insektoide Kreaturen, bekannt als Silithiden, damit begonnen haben, sich in die Erde einzugraben. Beunruhigt über ihre aggressive Natur und ihr rasches Vordringen wirbt er vorbeiziehende Abenteurer an, um mithilfe seines Klauenwerkzeugs intakte Eier auszugraben, in dem Versuch zu entschlüsseln, woher der Schwarm stammt und welche Gefahr er für die junge Horde darstellt."}},faq={{q="Wer ist Korran?",a="Korran ist ein Dunkelspeertroll, der im Wegekreuz im Brachland stationiert ist. Er fungiert als Beobachter und Forscher, der Belgrom Rockmaul in Orgrimmar Bericht erstattet.",al={"wer ist korran","korran troll","das wegekreuz troll"}},{q="Was untersucht Korran im Brachland?",a="Er untersucht die seltsamen, aggressiven insektoiden Kreaturen, die als Silithiden bekannt sind und im Südlichen Brachland am Feld der Riesen aufgetaucht sind, sowie ähnliche Schwärme, die weiter südlich in Tausend Nadeln gemeldet wurden.",al={"was erforscht korran","korran forschung","feld der riesen insekten"}},{q="Für wen arbeitet Korran?",a="Korran dient Belgrom Rockmaul, einem erfahrenen Krieger, der im Tal der Ehre in Orgrimmar stationiert ist und für die Horde aufkommende Bedrohungen in ganz Kalimdor überwacht.",al={"wer schickte korran","korrans vorgesetzter","belgrom rockmaul"}},{q="Warum braucht Korran Silithideneier?",a="Er benötigt intakte Eier, um den Lebenszyklus und die Ursprünge des Silithidenschwarms zu untersuchen. Durch das Studium früher Exemplare hofft Korran zu verstehen, worum es sich bei diesen Kreaturen handelt, und festzustellen, wie groß die Bedrohung für das Territorium der Horde ist.",al={"warum silithideneier","eierjagd quest","korrans klaue"}}},fx={b07b8377={q="Auf wessen Seite steht Korran?",a="Korran ist ein treuer Späher der Horde, der am Wegekreuz stationiert ist. Er berichtet direkt an Belgrom Felsenhauer, einen bedeutenden Offizier in Orgrimmar, und hält das Kommando des Kriegshäuptlings über seltsame Unruhen im Brachland auf dem Laufenden.",al={"korran fraktion","ist korran horde","korran loyalität"}}},fp="6,229,25.335.0,22.389.0,14.158.0,44.220.0,25.157.0,35.226.0"}
P.entries["npc:kravel-koalbeard"] = {n="Kravel Kohlebart",s="Kravel Kohlebart ist ein intrigantes Zwergen-Schlitzohr und Gauner, der auf der Illusionenrennbahn in der schimmernden Ebene stationiert ist. Anstatt rein aus Liebe zum Sport mitzufiebern, betrachtet er die erbitterte Rennrivalität zwischen Gnomen und Goblins als goldene Gelegenheit, sich die Taschen vollzustopfen. Vom Bergen herrenloser Maschinenteile bis hin zur Manipulation von Rennergebnissen durch Erpressung und Alkohol ist Kravel stets auf der Jagd nach seinem nächsten profitablen Coup.",h="Kravel Kohlebart ist ein intrigantes Zwergen-Schlitzohr und Gauner, der auf der Illusionenrennbahn in der...",kw={"erpressung","koalbeard","kravel","illusionenrennbahn","raketenwagen","sabotage","die schimmernde ebene","tausend nadeln"},ang={["class:Rogue"]="Schurken wird Kravels Metier vertraut sein: Diebstahl, Sabotage, Erpressung und das Manipulieren gieriger Zielpersonen aus den Schatten heraus.",["race:Dwarf"]="Im Gegensatz zu den ehrlichen Bergleuten, Prospektoren und Gebirgsjägern von Eisenschmiede ist Kravel ein unverfrorener Gauner und Betrüger, der traditionelle Zwergentugenden mit Füßen tritt.",["race:Gnome"]="Gnome sollten in Kravels Nähe ihre Getränke und Baupläne gut im Auge behalten, da er ebenso erpicht darauf ist, Gnomenpiloten zu betäuben, wie ihre Maschinen zu sabotieren."},sec={{t="Ein Gauner in der Ebene",b="Während die meisten Zuschauer und Crewmitglieder auf der Illusionenrennbahn ganz von mechanischen Rivalitäten und dem Dröhnen der Raketenmotoren eingenommen sind, hat Kravel Kohlebart ein wachsames Auge auf die Geldbeutel aller Beteiligten geworfen. Er ist ein Opportunist, der in den staubigen Winkeln des Rennlagers agiert und stets bereit ist, Verträge und Gefälligkeiten anzubieten, die selten lautere Motive haben. Kravel sieht in den brisanten Spannungen zwischen gnomischen und goblinischen Ingenieuren keinen inspirierenden Wettstreit, sondern einen fruchtbaren Nährboden für Erpressung, Sabotage und Diebstahl."},{t="Manipulation an der Rennstrecke",b="Kravels Machenschaften reichen weit über das Auflesen von weggeworfenem Schrott auf den Salzebenen hinaus. Um die Quoten zu manipulieren und sicherzustellen, dass die Ergebnisse zu seinen Gunsten ausfallen, schickt Kravel bereitwillige Abenteurer auf illegale Botengänge – er streut Gerüchte, fädelt Erpressungen ein und betrinkt Boxencrews sogar kurz vor einem Showdown. Ob er nun Goblinmechaniker mit hochprozentigen Spirituosen abfüllt oder Gnomenpiloten starke Drinks unterjubelt – Kravel schreckt vor keinem hinterhältigen Trick zurück, wenn es darum geht, sich am Renntag die Taschen zu füllen."}},faq={{q="Wer ist Kravel Kohlebart?",a="Kravel Kohlebart ist ein zwergischer Ränkeschmied und Opportunist, der auf der Illusionenrennbahn in der schimmernden Ebene anzutreffen ist. Er nutzt die Rivalität zwischen Gnomen und Goblins aus, um sich durch Schrottverwertung, Rennmanipulation und Erpressung die Taschen vollzuschlagen.",al={"wer ist kravel","identität von kravel kohlebart","illusionenrennbahn zwerg"}},{q="Was tut Kravel Kohlebart auf der Illusionenrennbahn?",a="Kravel heuert Reisende an, um zwielichtige Besorgungen rund um die Rennstrecke zu erledigen. Zu seinen Plänen gehört das Sammeln geborgener Raketenwagenteile, das Aufspüren von Erpressungsmaterial und das Sabotieren von Rennteams, indem er deren Mechaniker und Piloten betrinkt, um die Rennergebnisse zu beeinflussen.",al={"kravel zweck","was will kravel","kravel pläne"}},{q="Warum versucht Kravel, die Renncrews betrunken zu machen?",a="Kravel setzt hohe Wetteinsätze auf den Ausgang der Raketenwagenrennen. Indem er entweder die Gnome oder die Goblins vor dem Rennen betrunken macht, manipuliert er den Wettbewerb zugunsten des Ergebnisses, das ihm den größten Profit einbringt.",al={"gnome betrinken quest","goblins betrinken","kravel sabotage"}},{q="Wo ist Kravel Kohlebart zu finden?",a="Er befindet sich in der schimmernden Ebene in Tausend Nadeln, wo er sich direkt bei den geschäftigen Lagern an den Boxengassen der Illusionenrennbahn herumtreibt.",al={"kravel aufenthaltsort","wo ist kravel","kravel tausend nadeln"}},{q="Hat Kravel Verbindungen außerhalb von Tausend Nadeln?",a="Ja. Seine zwielichtigen Geschäfte schließen Kontakte in den Goblinhäfen Ratschet und Beutebucht ein, darunter Abmachungen mit Werftmeister Flunkerblick aus Ratschet, Gerüchtehändlern und Händlern exotischer Gebräue aus dem Schlingendorntal.",al={"kravel beutebucht","kravel verbindungen"}},{q="Arbeitet Kravel sowohl mit der Allianz als auch mit der Horde zusammen?",a="Wie viele Persönlichkeiten an neutralen Schauplätzen wie der Illusionenrennbahn ist Kravel an Gold statt an Fraktionstreue interessiert. Er heuert mit Freuden sowohl Abenteurer der Allianz als auch der Horde an, um seine Vorhaben in die Tat umzusetzen.",al={"ist kravel nur allianz","kann horde mit kravel sprechen"}}},fx={["33aea695"]={q="Was will Kravel Kohlebart?",a="Kravel ist ausschließlich von Profit und Eigennutz getrieben. Er versucht, sich auf dem Brachland in der schimmernden Ebene durch alle verfügbaren Methoden die Taschen zu füllen, von der Beschaffung von Teilen und dem Feilbieten von Gefälligkeiten bis hin zur Organisation von Erpressungen. Sein kühnster Ehrgeiz ist die Manipulation der Illusionenrennbahn selbst, wobei er plant, die Wettbewerbe zu sabotieren und zu manipulieren, indem er die Boxencrews und Fahrer gründlich betrunken macht.",al={"was will kravel","kravel kohlebart ziele","kravel beweggründe"}},["97572808"]={q="Warum ist Kravel Kohlebart in Tausend Nadeln?",a="Die Illusionenrennbahn in der schimmernden Ebene ist ein gesetzloses Zentrum für Glücksspiele mit hohen Einsätzen, erbitterte Rivalität und rücksichtslose Ingenieurskunst, was sie zu einem erstklassigen Jagdrevier für einen Betrüger macht. Kravel hat sein Lager neben den konkurrierenden Gnomen und Goblins aufgeschlagen, weil ihre bittere Besessenheit, einander zu besiegen, sie blind für Opportunisten und leichte Opfer seiner Machenschaften macht.",al={"warum ist kravel hier","warum ist kravel an der illusionenrennbahn","kravel schimmernde ebene"}}},fp="16,424,25.509.0,17.494.1,24.220.0,52.252.0,45.208.0,36.127.0,47.201.0,46.215.0"}
P.entries["npc:kreldig-ungor"] = {n="Kreldig Ungor",s="Kreldig Ungor ist ein geschäftstüchtiger Zwergenagent, der Reclaimers Inc. vertritt und hoch oben in den Klippen der Nijelspitze in Desolace stationiert ist. Mit der Leitung von Feldeinsätzen im kargen Ödland betraut, heuert er Abenteurer der Allianz an, um verlorene Fracht zu bergen und wertvolle lokale Reagenzien zu sichern. Seine Bergungs- und Beschaffungsaufträge machen ihn zu einer zentralen Anlaufstelle für Reisende, die sich durch die feindselige Region bewegen.",h="Kreldig Ungor ist ein geschäftstüchtiger Zwergenagent, der Reclaimers Inc.",kw={"allianz","desolace","zwerg","karnitol schiffswrack","kreldig ungor","die nijelspitze","reclaimers inc","bergung"},ang={["faction:Alliance"]="Auf der Nijelspitze stationiert, ist Kreldig vollkommen auf Reisende der Allianz angewiesen, um seine Bergungsaufträge in einem ansonsten feindseligen Gebiet voranzutreiben.",["race:Dwarf"]="Kreldig verkörpert die klassische Vorliebe der Zwerge für unerschrockene Grenzlandexpeditionen und wirtschaftlichen Ehrgeiz, indem er sich fernab der heimischen Berghallen niederlässt."},sec={{t="Feldagent im Ödland",b="Die Nijelspitze bietet der Allianz eine seltene Zuflucht inmitten der verheerten Schluchten von Desolace, was sie zu einer idealen Operationsbasis für wirtschaftliche Opportunisten wie Kreldig Ungor macht. Als Vertreter von Reclaimers Inc. hat sich Kreldig weit aus der Sicherheit von Khaz Modan in eine trostlose Wildnis gewagt, die von Zentaurenklans, Dämonen und der Horde umkämpft wird. Wo andere nur Ruinen und Asche sehen, erkennt Kreldig ungenutzten Profit und verlorene Güter, die nur darauf warten, geborgen zu werden."},{t="Der Karnitol-Auftrag",b="Eines der Hauptunterfangen, die Kreldig nach Desolace führen, dreht sich um das verschollene Schiff von Karnitol, das an der tückischen Westküste zerschellte. Karnitols Ladung enthielt kostbare Waren, und Kreldig koordiniert die Bemühungen, die Trümmer aufzuspüren und das verstreute Frachtgut zu bergen, bevor Plünderer oder Meeresriesen der Küste alles an sich reißen können."},{t="Beschaffung lokaler Reagenzien",b="Neben der Bergung von Schiffsgütern überwacht Kreldig für Reclaimers Inc. die Beschaffung von Desolaces seltsamen biologischen und mineralischen Schätzen. Die raue Umgebung bringt eine einzigartige Flora und Fauna hervor, deren Bestandteile bei Alchemisten und Ingenieuren in den Östlichen Königreichen hohe Preise erzielen. Abenteurer, die bereit sind, den Raubtieren des Ödlands zu trotzen, finden in Kreldigs Auftragsbuch eine verlässliche Einnahmequelle."}},faq={{q="Wer ist Kreldig Ungor?",a="Kreldig Ungor ist ein Zwergenagent, der für Reclaimers Inc. arbeitet und seinen Stützpunkt im Außenposten der Allianz auf der Nijelspitze in Desolace hat. Er koordiniert Bergungsmissionen und das Sammeln von Proben im gesamten Gebiet.",al={"kreldig ungor geschichte","wer ist kreldig","kreldig ungor"}},{q="Was ist Reclaimers Inc.?",a="Reclaimers Inc. ist ein unternehmerisches Projekt, das darauf ausgerichtet ist, verlorene Fracht zu bergen, Wracks auszuschlachten und seltene Reagenzien in gefährlichen Grenzgebieten gewinnbringend zu sammeln.",al={"reclaimers inc","wer sind reclaimers inc","reclaimers unternehmen"}},{q="Wo ist Kreldig Ungor zu finden?",a="Er befindet sich in der Allianzsiedlung auf der Nijelspitze, hoch oben in den felsigen Bergen im Nordosten von Desolace.",al={"kreldig ungor standort","wo ist kreldig","kreldig ungor finden"}},{q="Was bezweckt Kreldig mit dem Schiffswrack von Karnitol?",a="Ein Schiff mit wertvollen Gütern von Karnitol erlitt an der Küste von Desolace Schiffbruch. Kreldig heuert Abenteurer an, um das Wrack aufzuspüren und die verlorene Fracht zu sichern, bevor sie geplündert oder zerstört wird.",al={"karnitol schiffswrack","kreldig karnitol","desolace schiffswrack"}},{q="Warum sammelt Kreldig Reagenzien in Desolace?",a="Die raue Umgebung von Desolace bringt seltene Kreaturen und einzigartige natürliche Substanzen hervor. Kreldig sammelt diese Proben, um Alchemisten, Handwerker und Käufer in den großen Städten der Allianz zu beliefern.",al={"reagenzien für reclaimers inc","desolace reagenzien","warum reagenzien sammeln"}},{q="Arbeitet Kreldig für Eisenschmiede oder ein Privatunternehmen?",a="Obwohl er von einem Allianzaußenposten aus operiert und ausschließlich Reisende der Allianz anheuert, vertritt Kreldig Reclaimers Inc. – ein kommerzielles Unternehmen, das auf Bergung und Handel setzt, statt offizielle königliche Militärziele zu verfolgen.",al={"kreldig allianz oder privat","reclaimers inc eisenschmiede"}}},fx={ad7684ca={q="Warum ist Kreldig Ungor in der Nijelspitze stationiert?",a="Kreldig Ungor hat sich hoch oben in der Nijelspitze niedergelassen, um für Reclaimers Inc. in der rauen Weite von Desolace geschäftliche Unternehmungen zu verfolgen. Von diesem befestigten Zufluchtsort der Allianz aus überwacht er Bergungs- und Beschaffungsoperationen in relativer Sicherheit und nutzt ihn als Basis, um zähe Abenteurer für Unternehmungen in die gefährlichen Einöden anzuheuern.",al={"warum ist kreldig ungor hier","kreldig ungor nijelspitze","warum ist kreldig in desolace"}}},fp="13,399,25.429.0,21.323.0,25.373.0,21.203.0,24.163.0,33.120.0,51.197.0,47.195.0,56.219.0"}
P.entries["npc:krolg"] = {fx={["4c25d8d9"]={q="Wer ist Krolg?",a="Krolg ist ein nicht korrumpierter Furbolg, der in selbstgewähltem Exil südlich des Mystralsees im Eschental lebt. Als ehemaliges Mitglied des Stammes der Foulweald gelang es ihm, der dunklen Verderbnis zu widerstehen, die seine Brüder befiel. Nun isoliert in seiner einfachen Hütte bewahrt er seinen Verstand und seine Weisheit, während er um das trauert, was aus seinem Volk geworden ist, und ist bereit, Außenstehenden zu helfen, die ihn in Furbolggestalt aufsuchen.",al={"wer ist krolg","krolg identität","wer ist der furbolg an krolgs hütte"}},["19bbdb38"]={q="Auf wessen Seite steht Krolg?",a="Krolg hat sich weder der Allianz noch der Horde verschrieben; er steht als einer der wenigen vernünftigen, nicht korrumpierten Furbolgs, die in der Region verblieben sind, allein. Er verhandelt jedoch nur mit Abenteurern der Allianz, die sich ihm mit Dartols Stab als Artgenossen getarnt nähern, und bietet ihnen im Kampf gegen die korrumpierten Foulweald Führung und rituelles Wissen an.",al={"ist krolg allianz oder horde","krolg fraktion","auf wessen seite steht krolg"}},["39fdb4f1"]={q="Was will Krolg?",a="Krolg sucht ein Ende für den Wahnsinn, der seine ehemaligen Verwandten zerstört. Er bittet transformierte Abenteurer, Ran Bloodtooth und seine Wachen zu erschlagen, da ihre Verderbnis die Nachtelfen und die anderen Kreaturen des Waldes bedroht.",al={"was will krolg","krolg beweggründe","krolg ziel"}}}}
P.entries["npc:krom-stoutarm"] = {fx={["6ca19015"]={q="Wer ist Krom Starkarm?",a="Krom Starkarm ist ein Hexenmeister der Zwerge, der in der Library der Hall of Explorers in Eisenschmiede dunkles Wissen studiert. Im Gegensatz zu vielen Praktizierenden der Teufelsmagie, die sich in schattigen Kellern und abgelegenen Zirkeln verstecken, operiert Krom offen unter den Gelehrten und Ausgräbern der Forscherliga und vertieft sich in alte Relikte, obskure Arkana und okkulte Folianten.",al={"wer ist krom","krom starkarm lore","wer ist krom starkarm"}},["23fb54c2"]={q="Auf wessen Seite steht Krom Starkarm?",a="Krom Starkarm ist Eisenschmiede und der Allianz gegenüber loyal. Obwohl er Hexenmeisterkünste praktiziert, die bei vielen seiner Verwandten Argwohn und Unbehagen hervorrufen, bleibt er ein respektierter Gelehrter in der Hall of Explorers und bietet seine esoterische Expertise und sein arkanes Wissen ausschließlich an, um Champions der Allianz bei ihren Unternehmungen zu unterstützen.",al={"krom starkarm fraktion","krom starkarm allianz oder horde","wem dient krom"}}}}
P.entries["npc:krusk"] = {fx={["86db3c10"]={q="Auf wessen Seite steht Krusk?",a="Krusk ist ein loyaler Agent der Horde. Er wurde direkt unter dem Befehl von Kriegshäuptling Thrall ausgesandt und operiert von Tarrens Mühle aus, um die strategischen Interessen von Orgrimmar im gesamten Vorgebirge des Hügellands zu wahren.",al={"krusk fraktion","ist krusk horde","wem dient krusk"}},["943a1bb4"]={q="Was will Krusk?",a="Krusk benötigt fähige Champions, um seine gefangenen Gefährten – Gol'dir, Drull und Tog'thar – aus den Händen des Syndikats in den Ruinen von Burg Durnholde zu befreien. Er versucht außerdem, die Operationen des Syndikats aufzudecken und einen Gegenstand von großer Bedeutung zu sichern, der mit der Geschichte von Durnholde verbunden ist.",al={"was braucht krusk","krusk ziele","wonach sucht krusk"}},["2e7680ba"]={q="Warum ist Krusk hier in Tarrens Mühle?",a="Kriegshäuptling Thrall schickte Krusk und seinen Trupp persönlich in das Hügelland, um die Aktivitäten des Syndikats rund um Burg Durnholde zu untersuchen. Nachdem ein Hinterhalt seine Späher gefangen genommen hatte, zog sich Krusk nach Tarrens Mühle zurück, um sich neu zu formieren und Hilfe für den Abschluss der Mission anzuwerben.",al={"warum ist krusk im hügelland","krusk tarrens mühle warum","warum hat thrall krusk geschickt"}}}}
P.entries["npc:kuray-bin"] = {fx={["65134a3b"]={q="Auf wessen Seite steht Kuray'bin?",a="Kuray'bin dient der Horde. Er ist direkt außerhalb des Splitterholzpostens stationiert, arbeitet daran, die Siedlung gegen Einfälle der Allianz zu sichern und hält Wache über die umkämpften Grenzen des Eschentals.",al={"kuraybin fraktion","wem dient kuraybin","ist kuraybin horde"}},bfddbb0e={q="Warum ist Kuray'bin hier im Eschental stationiert?",a="Kuray'bin hält an einem Außenposten direkt außerhalb des Splitterholzpostens Wache, um feindliche Bewegungen zu beobachten. Da Späher der Nachtelfen tief in das Territorium der Horde eindringen, ist es seine Aufgabe, Bedrohungen zu erkennen, bevor sie die Siedlung angreifen.",al={"warum ist kuraybin hier","kuraybin zweck eschental","warum ist kuraybin am splitterholzposten"}},["189aca6f"]={q="Mit wem ist Kuray'bin verbunden?",a="Kuray'bin ist direkt mit der Garnison der Horde am Splitterholzposten verbunden. Als Späher der Dschungeltrolle arbeitet er in Abstimmung mit den Orcs und anderen Verteidigern, die diesen unsicheren Stützpunkt im Eschental gegen die Nachtelfen halten.",al={"kuraybin verbindungen","kuraybin verbündete","mit wem arbeitet kuraybin zusammen"}}}}
P.entries["npc:kzan-thornslash"] = {fx={feb30cb2={q="Auf wessen Seite steht Kzan Dornenhieb?",a="Kzan Dornenhieb steht fest auf der Seite der Horde. Er operiert innerhalb des Tals der Prüfungen, untersteht der Autorität von Orgrimmar und Thralls neuer Nation und rüstet die jungen Orcs und Trolle aus, die ankommen, um ihre Stärke und Loyalität in Durotar unter Beweis zu stellen.",al={"kzan dornenhieb fraktion","wem dient kzan","ist kzan horde"}},["1bbcac80"]={q="Warum ist Kzan Dornenhieb im Tal der Prüfungen?",a="Kzan bleibt im Tal der Prüfungen, um aufstrebende Rekruten und Krieger auszurüsten, die sich auf ihre ersten Prüfungen begeben. In einem rauen, ariden Übungsgelände, das von Skorpionen, Ebern und Vile Familiars überrannt wird, benötigt ein unerprobter Kämpfer zuverlässigen Stahl, Keulen und Klingen, um seine Tests zu überleben.",al={"warum ist kzan dornenhieb hier","kzan tal der prüfungen rolle","was macht kzan"}},c4565150={q="Was will Kzan Dornenhieb?",a="Kzan möchte die Rekruten mit den Waffen versorgen, die sie benötigen, während er seinen Handel in Durotar aufrechterhält. Durch seine Geschäfte mit jungen Kriegern stellt er sicher, dass die jungen Verteidiger der Horde angemessen mit grundlegenden Waffen ausgestattet sind, um ihre neu besiedelten Länder zu verteidigen.",al={"was will kzan","kzan dornenhieb beweggrund","kzan dornenhieb ziel"}}}}
P.entries["npc:lady-anacondra"] = {fx={["6f9b72fe"]={q="Mit wem ist Lady Anakondra verbunden?",a="Lady Anakondra ist direkt mit Naralex verbunden, dem mächtigen Druiden, dem sie als Akolythin diente, bevor sein Albtraum ihren Verstand zerrüttete. Sie ist zudem an die anderen Fanglords gebunden – wie etwa Cobrahn und Serpentis –, die gemeinsam mit ihr den verdrehten Kult der Druiden des Giftzahns anführen.",al={"wer ist anakondras meister","verbindung anakondra naralex","wer führt anakondra an"}},["1a1ef870"]={q="Auf wessen Seite steht Lady Anakondra?",a="Lady Anakondra steht auf der Seite der Druiden des Giftzahns, nachdem sie ihre frühere Loyalität zum Zirkel des Cenarius aufgegeben hat. Korrumpiert durch den Smaragdgrünen Alptraum, der ihren Meister Naralex verschlang, stellt sie sich nun gegen ihre ehemaligen Verwandten und verteidigt den Wahnsinn, der in den Höhlen des Wehklagens schwärt.",al={"anakondra fraktion","wem dient lady anakondra","lady anakondra loyalität"}}}}
P.entries["npc:lady-sarevess"] = {n="Lady Sarevess",s="Lady Sarevess ist eine verkrüppelte Naga-Zauberin, die in den überfluteten Ruinen der Tiefschwarzen Grotte haust, wo sie sich mit dunklen Zaubern befasst.",h="Lady Sarevess ist eine verkrüppelte Naga-Zauberin, die in den überfluteten Ruinen der Tiefschwarzen Grotte...",kw={"aku'mai","tiefschwarze grotte","lady sarevess","naga","pool of ask'ar","sarevess","meerhexe","schattenhammer"},ang={["class:Mage"]="Sarevess zeigt, wie die magischen Praktiken der Hochgeborenen unter Jahrhunderten ozeanischer Verderbnis zu roher, chaotischer Blitz- und Gezeitenzauberei verfielen.",["race:NightElf"]="Die Ruinen, die Lady Sarevess bewohnt, waren einst ein heiliger Tempel von Elune. Zu sehen, wie ihre verkrüppelten Naga-Artgenossen die Gewässer von Ask'ar entweihen, ist eine bittere Erinnerung an die Zerschlagung."},sec={{t="Eine Grotte in der Tiefe",b="Im Pool of Ask'ar vollzieht Lady Sarevess ihre Rituale in einer überfluteten Grotte des zerstörten Tempels. Als zutiefst verdorbene Zauberin befasst sie sich mit dunkler Magie, während die Kultisten des Schattenhammers, die den versunkenen Tempel ebenfalls heimsuchen, tiefer in der Höhle ihren eigenen Kult praktizieren."},{t="Zauberei der Gezeiten",b="Ganz ähnlich wie eine Meerhexe der tiefen Ozeane gebietet Sarevess über elementare Strömungen und knisternde Blitze. Umgeben von loyalen Naga-Schildwachen und beschworenen Wasserelementaren verteidigt sie ihr Heiligtum erbittert gegen alle Eindringlinge, die ihr finsteres Werk bedrohen."}},faq={{q="Wer ist Lady Sarevess?",a="Lady Sarevess ist eine Naga-Zauberin, die sich im unterirdischen Pool of Ask'ar innerhalb der Tiefschwarzen Grotte niedergelassen hat. Sie ist eine zutiefst verdorbene Zauberin, die sich mit dunkler Magie befasst.",al={"wer ist sarevess","sarevess lore","lady sarevess hintergrundgeschichte"}},{q="Wo ist Lady Sarevess zu finden?",a="Sie haust im Pool of Ask'ar, einer überfluteten Kammer in den vorderen Bereichen des Tempelkomplexes der Tiefschwarzen Grotte an der Küste von Eschental.",al={"sarevess aufenthaltsort","wo ist lady sarevess","pool of askar"}},{q="Über welche Kräfte gebietet Lady Sarevess?",a="In der Tradition der Naga-Meerhexen wirkt Sarevess mächtige Wasser- und Elementarmagie, insbesondere heftige Entladungen von Gabelblitzen, um jeden niederzustrecken, der ihre Bucht betritt.",al={"sarevess magie","sarevess fähigkeiten"}}},fx={["75d3f337"]={q="Auf wessen Seite steht Lady Sarevess?",a="Lady Sarevess dient ihrem eigenen Volk, den Naga, und nicht der Allianz oder der Horde. Als überaus verdorbene Zauberwirkerin haust sie im überfluteten Pool of Ask'ar in der Tiefschwarzen Grotte und verteidigt ihre Grotte erbittert gegen jeden Eindringling.",al={"fraktion lady sarevess","wem dient sarevess","loyalität sarevess"}},["67d48548"]={q="Was will Lady Sarevess?",a="Sarevess strebt danach, ihre Meisterschaft über verdrehte magische Künste auszuweiten. Sie führt dunkle Rituale in ihrer überfluteten Grotte tief in der Tiefschwarzen Grotte durch und streckt jeden Eindringling nieder, der ihre Arbeit stört.",al={"was tut sarevess","ziel von lady sarevess","zweck von sarevess"}},["6008d570"]={q="Warum ist Lady Sarevess hier in der Tiefschwarzen Grotte?",a="Lady Sarevess hat den Pool of Ask'ar, eine überflutete Grotte im Ruinentempel der Tiefschwarzen Grotte, zu ihrem Versteck erkoren. Dort befasst sie sich mit dunkler Magie, bewacht von Naga-Wachposten und beschworenen Wasserelementaren.",al={"warum ist lady sarevess in der tiefschwarzen grotte","grund für sarevess in tiefschwarzer grotte","warum ist sarevess hier"}},d8505f38={q="Mit wem ist Lady Sarevess verbunden?",a="Sarevess ist mit den Naga verbunden, die die überfluteten Ruinen der Tiefschwarzen Grotte heimsuchen. Sie befehligt loyale Naga-Wachposten und beschworene Wasserelementare in ihrer Grotte. Die Kultisten des Schattenhammers, die ebenfalls den versunkenen Tempel heimsuchen, verfolgen tief in der Höhle ihren eigenen Kult.",al={"verbündete von sarevess","mit wem arbeitet sarevess zusammen","sarevess schattenhammer"}}},fp="13,134,21.274.0,20.262.0,21.188.0,33.156.0,39.192.0"}
P.entries["npc:laird"] = {n="Laird",s="Laird ist ein Fischverkäufer der Nachtelfen, den man im Gasthaus an der Küste von Auberdine antrifft. Bei seiner Arbeit an der nebelverhangenen Küste der Dunkelküste versorgt er Reisende und Angler, die sich an die raue Küste wagen, mit Handelsgütern und Kochrezepten.",h="Laird ist ein Fischverkäufer der Nachtelfen, den man im Gasthaus an der Küste von Auberdine antrifft.",kw={"auberdine","dunkelküste","frenzyfilet","fischverkäufer","laird","nessa schattensang"},ang={["profession:Cooking"]="Kulinarisch interessierte Reisende, die Dunkelküste besuchen, suchen Laird oft wegen seines Rezepts auf, wie man die wilden Frenzy-Fische aus den Gewässern von Kalimdor richtig filetiert und zubereitet.",["race:NightElf"]="Laird steht stellvertretend für die alltäglichen Handwerker und Händler der Nachtelfen, die sich an den Küsten des Festlands niedergelassen haben, um das wachsende Küstennetzwerk von Kalimdor zu unterstützen."},sec={{t="Ein Hafenhändler",b="Im geschäftigen Gasthaus von Auberdine verkauft Laird frischen Fisch und Vorräte an Seeleute, Einheimische und reisende Abenteurer. Die Gewässer der Dunkelküste sind im Vergleich zu den geschützten Ufern von Teldrassil berüchtigt für ihre Unruhe und voller Gefahren, doch Laird weiß genau, dass Risiken auch Belohnungen bringen. Für wagemutige Angler, die bereit sind, ihre Leinen an den nebligen Stränden auszuwerfen, verspricht der örtliche Fang einen stattlichen Gewinn."},{t="Verbindungen über das Wasser",b="Laird pflegt weiterhin enge Verbindungen zu den Fischereibetrieben jenseits des Kanals in Teldrassil. Er dient als wichtige Anlaufstelle für Kurierfahrten zwischen den Inselzweigen von Rut'theran und dem Hafen auf dem Festland, nimmt Lieferungen seiner Fischerkollegin Nessa Schattensang entgegen und sorgt dafür, dass die Küstenhandelswege offen bleiben."}},faq={{q="Wo kann ich Laird finden?",a="Laird befindet sich im Erdgeschoss des Gasthauses in Auberdine, der Hauptsiedlung der Allianz an der Küste der Dunkelküste.",al={"laird aufenthaltsort","wo ist laird","laird auberdine"}},{q="Was verkauft Laird?",a="Er verkauft verschiedene gefangene Fische und Kochzutaten sowie die kulinarische Anleitung zur Zubereitung von Frenzyfilet.",al={"laird händler","was verkauft laird","laird waren"}},{q="Welche Quests haben mit Laird zu tun?",a="Laird ist in der Quest Ein unerwartetes Geschenk der Empfänger einer Lieferung von Nessa Schattensang aus Rut'theran; anschließend bittet er Abenteurer, eine Nachricht zurück über das Meer zu bringen.",al={"laird quests","auberdine fischquest"}},{q="Warum lohnt sich das Angeln in Dunkelküste laut Laird trotz der Gefahren?",a="Laird merkt an, dass die neblige Küste der Dunkelküste zwar weit mehr Gefahren birgt als die ruhigen Gewässer von Teldrassil, die reiche und exotische Meeresfauna den Handel für geschäftstüchtige Angler jedoch weitaus profitabler macht.",al={"laird gerede","ist dunkelküste gut zum angeln"}}},fx={["47d7af55"]={q="Wer ist Laird?",a="Laird ist ein Nachtelf-Fischer und Fischhändler, der seinen Lebensunterhalt in der Dunkelküste verdient. Er hat seinen Stützpunkt im belebten Gasthaus von Auberdine und handelt mit Reisenden und Fischern, die die nebligen Gewässer entlang der Küste befahren. Er bietet Vorbeigehenden Kochrezepte und frischen Fisch an.",al={"wer ist laird","laird auberdine","identität von laird"}},f4a4a12e={q="Auf wessen Seite steht Laird?",a="Laird ist mit den Nachtelfen und der Allianz verbündet. Da er friedlich in Auberdine lebt, heißt er Abenteurer der Allianz und einheimische Fischer willkommen, damit sie sich im Gasthaus ausruhen und seine Waren durchstöbern können.",al={"fraktion von laird","ist laird allianz","wem dient laird"}},["90f5a883"]={q="Warum ist Laird hier?",a="Laird bleibt im Gasthaus von Auberdine, um Küstenfänge zu kaufen und zu verkaufen. Obwohl die Küste der Dunkelküste Gefahren birgt, die es in Teldrassil nicht gibt, erkennt er, dass wagemutige Fischer beträchtliche Gewinne aus den örtlichen Gewässern erzielen können, was den Hafen zu einem erstklassigen Ort für seinen Handel macht.",al={"warum ist laird in auberdine","zweck von laird in der dunkelküste"}},d47e4f81={q="Was will Laird?",a="Laird strebt einen florierenden Küstenfischhandel an. Er fördert lokale Fischereiunternehmen trotz der Gefahren an den Küsten der Dunkelküste und freut sich, hungrige Reisende mit Meeresfrüchten und kulinarischen Rezepten zu versorgen.",al={"was will laird","ziele von laird","motive von laird"}}},fp="5,224,17.404.0,21.323.0,23.128.0,21.123.0,26.193.0,72.215.0"}
P.entries["npc:lakota-windsong"] = {n="Lakota Windweise",s="Lakota Windweise ist eine junge Tauren, die auf den Klippen des Düsterwolkengipfels in Tausend Nadeln gefangen gehalten wird. Nachdem sie einen unerwünschten Heiratsantrag von Arnak Grimtotem abgelehnt hatte, wurde sie gewaltsam entführt und wartet nun auf Rettung aus den Klauen des Klans der Grimtotem.",h="Lakota Windweise ist eine junge Tauren, die auf den Klippen des Düsterwolkengipfels in Tausend Nadeln...",kw={"arnak grimtotem","düsterwolkengipfel","endlich frei","freiwindposten","lakota windweise","thalia bernhaut","tausend nadeln"},ang={["faction:Horde"]="Die Rettung von Lakota versetzt der Vorherrschaft der Grimtotem in Tausend Nadeln einen Schlag und sichert Reisenden, die am Freiwindposten rasten, freies Geleit.",["race:Tauren"]="Lakotas Tortur ist eine deutliche Mahnung an den Verrat, der unter den Grimtotem schwelt, deren Auflehnung gegen die Führung von Cairne Bluthuf regelmäßig in Gewalt umschlägt."},sec={{t="Ein tödliches Werben",b="Nicht lange nach dem Dritten Krieg wurde Lakota Windweise von Arnak Grimtotem umworben. Da sie weder seinem Klan beitreten noch sein Werben erwidern wollte, lehnte sie seinen Antrag ab. Arnak weigerte sich, ein Nein zu akzeptieren; er kehrte im Schutz der Nacht zurück, ermordete Lakotas Bruder, als dieser einzuschreiten versuchte, und verschleppte sie in die zerklüfteten Höhen von Tausend Nadeln. Gefangen hoch über dem Schluchtboden auf dem Düsterwolkengipfel, verbleibt sie unter strenger Bewachung, während Arnak noch immer darauf beharrt, sie zu seiner Braut zu machen."},{t="Abstieg in die Sicherheit",b="Umringt von verräterischen Banditen der Grimtotem kann sich Lakota den Weg die Klippen hinab nicht alleine freikämpfen. Nur eine mutige Eskorte kann sie über die Hängebrücken und die gewundenen Pfade hinab in den Schluchtgrund führen. Sobald sie sich vom Düsterwolkengipfel befreit hat, flieht Lakota in die Sicherheit des Freiwindpostens und überbringt Thalia Bernhaut sowie den dort stationierten Verteidigern die Nachricht von ihrer Rettung."}},faq={{q="Warum wird Lakota Windweise auf dem Düsterwolkengipfel festgehalten?",a="Sie lehnte einen Heiratsantrag von Arnak Grimtotem ab. Anstatt ihre Absage zu akzeptieren, ermordete Arnak ihren Bruder und entführte Lakota in die Festung der Grimtotem auf dem Düsterwolkengipfel, in der Hoffnung, sie zur Heirat zu zwingen.",al={"warum ist lakota gefangen","wer hat lakota entführt","warum ist lakota auf dem düsterwolkengipfel"}},{q="Wohin geht Lakota, sobald sie gerettet ist?",a="Nachdem sie den Fuß des Düsterwolkengipfels sicher erreicht hat, macht sich Lakota auf den Weg zum Freiwindposten, wo sie Zuflucht bei den Verteidigern der Horde findet und Thalia Bernhaut von ihrem Martyrium berichten kann.",al={"wohin rennt lakota","wohin geht sie nach der begleitung","lakota zielort"}},{q="Wer ist Arnak Grimtotem?",a="Arnak ist ein gewalttätiger Krieger des verräterischen Klans der Grimtotem, der Lakotas Bruder ermordete und sie entführte, als sie sich weigerte, ihn zu heiraten.",al={"wer ist arnak","wer hat sie entführt","arnak geschichte"}}},fx={e2861ac8={q="Wer ist Lakota Windweise?",a="Lakota Windweise ist eine Taurenfrau, die gefangen auf dem Düsterwolkengipfel festgehalten wird. Als Arnak Grimmtotem um ihre Hand anhielt, wies Lakota ihn ab. Außer sich vor Wut über ihre Zurückweisung ermordete Arnak ihren Bruder und verschleppte sie in die Festung der Grimmtotem in Tausend Nadeln, um die Vereinigung gegen ihren Willen zu erzwingen.",al={"wer ist lakota windweise","wer ist lakota","identität von lakota"}},["412850e2"]={q="Auf wessen Seite steht Lakota Windweise?",a="Lakota steht auf der Seite der friedlichen Tauren der Horde und hofft auf den Schutz der Recken am Freiwindposten. Sie hegt tiefen Groll gegen den Grimmtotem-Clan, der ihrem Bruder brutal das Leben nahm und sie entführte.",al={"fraktion von lakota windweise","ist lakota horde","loyalität von lakota"}},["2c16a924"]={q="Was will Lakota Windweise?",a="Lakota wünscht sich nichts sehnlicher, als vom Düsterwolkengipfel zu entkommen und in Sicherheit, fernab der Grimmtotem-Banditen, zu gelangen. Da ihr Bruder bei ihrer Verteidigung erschlagen wurde, ist sie auf jemanden angewiesen, der mutig genug ist, sich an ihren Entführern vorbeizukämpfen und sie sicher die gewundenen Pfade hinunter zum Freiwindposten zu geleiten.",al={"ziel von lakota windweise","was braucht lakota","wünsche von lakota"}},["3261173c"]={q="Mit wem ist Lakota Windweise verbunden?",a="Lakota wurde erbittert von ihrem Bruder beschützt, der sein Leben verlor, als er versuchte, sie vor Arnak Grimmtotem zu verteidigen. Sie setzt ihr Vertrauen auch in Thalia Bernhaut und die Verteidiger, die am Freiwindposten stationiert sind.",al={"familie von lakota","verbindungen von lakota","mit wem ist lakota verwandt"}}},fp="15,245,18.504.0,17.388.1,56.226.0,41.187.1,23.139.0"}
P.entries["npc:lanka-farshot"] = {n="Lanka Weitschuss",s="Lanka Weitschuss ist ein Jägerlehrer der Tauren, der im Camp Narache auf der Hochwolkenebene stationiert ist. Er leitet unerfahrene Taurenjäger an, während sie ihre ersten Schritte im Fährtenlesen, der Treffsicherheit und dem Überleben in den Ebenen von Mulgore unternehmen.",h="Lanka Weitschuss ist ein Jägerlehrer der Tauren, der im Camp Narache auf der Hochwolkenebene stationiert ist.",kw={"camp narache","jägerlehrer","lanka weitschuss","mulgore","die hochwolkenebene","taurenjäger"},ang={["class:Hunter"]="Für Taurenjäger, die ihre Ausbildung in Mulgore beginnen, ist Lanka Weitschuss der allererste Mentor, dem sie begegnen; er lehrt grundlegende Treffsicherheit und das Überleben in der Wildnis.",["race:Tauren"]="Lanka verkörpert die traditionelle Jagdphilosophie der Tauren, in der Treffsicherheit und Fährtenlesen als lebenswichtige Pflichten zum Schutz des Stammes und für ein Leben im Einklang mit den Ebenen gelten."},sec={{t="Mentor der Hochwolkenebene",b="Lanka Weitschuss wacht über Camp Narache und begrüßt neue Tauren, die zum Pfad des Jägers berufen wurden. Frische Rekruten treffen mit einer geätzten Notiz ein, die sie anweist, seinen Rat zu suchen. Unter seinem wachsamen Auge erlernen Lehrlinge die Grundlagen des Fernkampfs, das Aufspüren von Beute und den Respekt vor den wilden Tieren, die die grasbewachsenen Ebenen von Mulgore durchstreifen. Seine Lehren stellen sicher, dass jeder junge Jäger dem Stamm als fähiger Späher und Versorger dient."}},faq={{q="Wer ist Lanka Weitschuss?",a="Lanka Weitschuss ist der Jägerlehrer der Tauren, der im Camp Narache auf der Hochwolkenebene in Mulgore stationiert ist. Er bietet jungen Jägern, die ihre Reise beginnen, erste Ausbildung und Anleitung.",al={"wer ist lanka","lanka weitschuss nsc","camp narache jäger"}},{q="Welche Quests bietet Lanka Weitschuss an?",a="Lanka empfängt junge Taurenjäger, die bei ihrer Ankunft im Camp Narache über eine geätzte Notiz zu ihm geschickt werden, und führt sie auf den Weg des Jägers, während sie die Grundlagen ihres Handwerks erlernen.",al={"lanka weitschuss quests","jägerquests camp narache"}},{q="Ist Lanka Weitschuss mit Mixie Farshot verwandt?",a="Obwohl sie denselben Nachnamen tragen, gibt es keinen Hinweis darauf, dass Lanka Weitschuss mit der Goblindame Mixie Farshot verwandt ist.",al={"ist lanka mit mixie verwandt","verwandtschaft mixie farshot"}}},fx={["3509322d"]={q="Auf wessen Seite steht Lanka Weitschuss?",a="Lanka Weitschuss ist den Taurenstämmen und der Horde treu ergeben. Er ist im sicheren Zufluchtsort Camp Narache stationiert und dient seinem Volk, indem er junge Taurenjäger anleitet, während sie lernen, unter der Führung des Hochhäuptlings Cairne Bluthuf zu überleben und zu den vereinigten Stämmen beizutragen.",al={"fraktion von lanka weitschuss","wem dient lanka weitschuss","ist lanka horde"}},fd40a21a={q="Warum ist Lanka Weitschuss hier in Camp Narache?",a="Lanka wohnt in Camp Narache, um angehende Jäger zu unterweisen, die ihre Prüfungen auf der Hochwolkenebene beginnen. Die Ebenen von Mulgore erfordern scharfe Sinne und ein ruhiges Zielwasser, und Lanka steht bereit, die wesentlichen Künste des Aufspürens und der Treffsicherheit an die nächste Generation weiterzugeben.",al={"warum ist lanka hier","standort und zweck von lanka weitschuss","was führt lanka nach camp narache"}},["2df75887"]={q="Was will Lanka Weitschuss?",a="Lanka möchte sicherstellen, dass jeder aufstrebende Taurenjäger die Wege der Wildnis meistert. Er möchte, dass Ihr Eure Beute respektiert, Eure Treffsicherheit schärft und die stolzen Traditionen fortführt, die notwendig sind, um Euer Volk auf dem Grasland zu ernähren und zu verteidigen.",al={"ziel von lanka weitschuss","was versucht lanka zu tun","zweck von lanka weitschuss"}}},fp="13,220,28.441.0,21.186.0,37.182.0,42.113.0"}
P.entries["npc:lar-prowltusk"] = {n="Lar Lauerzahn",s="Lar Lauerzahn ist ein Schildwache-Troll der Dunkelspeer, der südwestlich von Sen'jin in Durotar stationiert ist. Von seinem Außenposten an der Grenze aus wacht er über herannahende Bedrohungen für die junge Trollsiedlung und weist Abenteurer an, das Vorrücken nahegelegener Feinde aufzuhalten.",h="Lar Lauerzahn ist ein Schildwache-Troll der Dunkelspeer, der südwestlich von Sen'jin in Durotar stationiert...",kw={"dunkelspeer","durotar","kolkar","lar lauerzahn","northwatch","sen'jin","troll"},ang={["faction:Horde"]="Lar Lauerzahn verkörpert den Kampf der Horde, die Grenzen von Durotar direkt vor den Toren ihrer noch jungen Hauptstadt gegen äußere Bedrohungen zu sichern.",["race:Troll"]="Für die Dunkelspeere sind Späher wie Lar Lauerzahn von entscheidender Bedeutung, um die zerbrechliche neue Heimat des Stammes in Durotar vor aggressiven Zentaurenclans und vordringenden Streitkräften der Menschen zu schützen."},sec={{t="Wächter an der Küste",b="Südwestlich von Sen'jin an der zerklüfteten Küste von Durotar gelegen, dient Lar Lauerzahn als einer der vorderen Vorpostenposten des Dunkelspeer-Stammes. Da die Trolle nach ihrer Flucht von ihrer versunkenen Inselkette immer noch daran arbeiten, sich eine dauerhafte Heimat zu sichern, ist Sen'jin ständigen Übergriffen feindlicher Nachbarn ausgesetzt. Lar koordiniert Späher und Krieger, um die Küstenbewegungen zu überwachen und die Aggression feindlicher Mächte einzudämmen – insbesondere der Kolkar-Zentauren –, damit die fragile Siedlung Raum zum Atmen hat."}},faq={{q="Wer ist Lar Lauerzahn?",a="Lar Lauerzahn ist ein Questgeber der Dunkelspeer-Trolle, der direkt südwestlich von Sen'jin in Durotar stationiert ist. Er hilft bei der Bewachung der Außenbezirke der Siedlung, indem er fähige Reisende der Horde anheuert, um regionale Bedrohungen zu bekämpfen, bevor sie das eigentliche Dorf erreichen.",al={"lar lauerzahn","wer ist lar lauerzahn","lar lauerzahn durotar"}},{q="Auf welche Bedrohungen konzentriert sich Lar Lauerzahn?",a="Lar konzentriert sich auf Grenzgefahren, die das südliche Durotar bedrohen, insbesondere auf die marodierenden Rudel der Kolkar-Zentauren, die in das Territorium der Trolle vordringen.",al={"lar lauerzahn quests","was will lar lauerzahn"}},{q="Wo ist Lar Lauerzahn zu finden?",a="Er befindet sich im südlichen Durotar und hält entlang der Pfade südwestlich von Sen'jin Wache.",al={"lar lauerzahn aufenthaltsort","wo ist lar lauerzahn"}}},fx={["7aeb1fbe"]={q="Auf wessen Seite steht Lar Lauerzahn?",a="Lar Lauerzahn ist dem Stamm der Dunkelspeere und der Horde treu ergeben. Er ist an der rauen Küste von Durotar südwestlich von Sen'jin stationiert und handelt zur Verteidigung der neuen Heimat seines Volkes. Er hält Ausschau nach vordringenden Feinden, die die Sicherheit der Dunkelspeertrolle und ihrer orkischen Verbündeten bedrohen.",al={"fraktion von lar lauerzahn","wem dient lar lauerzahn","lar lauerzahn horde oder allianz"}},ffd46d6a={q="Warum ist Lar Lauerzahn hier draußen?",a="Lar Lauerzahn hält südwestlich von Sen'jin Wache, um die Dunkelspeersiedlung vor regionalen Gefahren zu schützen. Die südlichen Ausläufer von Durotar sind ständig dem Druck aggressiver Nachbarn ausgesetzt, und Lar bleibt in der Nähe der wilden Küste stationiert, um dabei zu helfen, Verteidiger gegen diese lokalen Bedrohungen zu lenken, bevor sie das Dorf angreifen.",al={"warum ist lar lauerzahn in durotar","grund für den standort von lar lauerzahn","warum ist lar südwestlich von sen'jin"}},["9e56c7c1"]={q="Mit wem ist Lar Lauerzahn verbunden?",a="Lar Lauerzahn ist eng mit der Trollsiedlung Sen'jin verbunden und koordiniert sich mit den Dorfverteidigern und wandernden Abenteurern der Horde, um das Territorium der Trolle zu schützen.",al={"verbündete von lar lauerzahn","beziehungen von lar lauerzahn","partner von lar lauerzahn"}}},fp="13,259,20.505.0,21.249.0,41.136.0,33.94.0"}
P.entries["npc:laris-geardawdle"] = {fx={a960bc4a={q="Auf wessen Seite steht Laris Bummelritzel?",a="Laris Bummelritzel steht fest auf der Seite der Allianz und der Gnomeregangnome. Er arbeitet von der Hall of Explorers in Eisenschmiede aus, zusammen mit zwergischen Gelehrten und Forschern, und trägt seinen scharfen Verstand und seine exzentrischen biologischen Theorien dazu bei, das Wissen und Verständnis der Allianz über seltsame Phänomene in der ganzen Welt voranzubringen.",al={"fraktion von laris bummelritzel","laris bummelritzel allianz","ist laris bummelritzel freundlich"}},["114e8ed2"]={q="Warum ist Laris Bummelritzel in Eisenschmiede?",a="Nach dem Fall von Gnomeregan suchten viele Gnome Zuflucht bei ihren zwergischen Verbündeten in Eisenschmiede. Laris Bummelritzel hat sein Zuhause in der Library innerhalb der Hall of Explorers gefunden, einem idealen Zufluchtsort, wo er seine exzentrische akademische Forschung verfolgen und seine Theorien über den Ursprung von Schlämmen katalogisieren kann, mit vollem Zugang zu umfangreichen historischen und natürlichen Archiven.",al={"warum ist laris bummelritzel hier","laris bummelritzel hall of explorers","warum ist laris in eisenschmiede"}}}}
P.entries["npc:lars"] = {n="Lars",s="Lars ist ein bedrängter menschlicher Überlebender, der in der Wildnis von Dämmerwald lagert. Gemeinsam mit seinem Gefährten Sven Yorgen kämpft er am nördlichen Rand des stillen Ufers darum, sich gegen die Schrecken zu behaupten, die durch den Wald streifen.",h="Lars ist ein bedrängter menschlicher Überlebender, der in der Wildnis von Dämmerwald lagert.",kw={"lager","dämmerwald","das stille ufer","lars","sven yorgen","wölfe","wölfe sind uns auf den fersen"},ang={["faction:Alliance"]="Lars ist ein bedrängter menschlicher Zivilist, der außerhalb der Reichweite der Stadtwache überlebt und froh ist, Recken der Allianz zu finden, die bereit sind, die sein Lager umkreisenden Wölfe niederzustrecken."},sec={{t="Ein heikler Zufluchtsort",b="In einem bescheidenen Lager am nördlichen Rand des stillen Ufers fristet Lars fernab der zweifelhaften Sicherheit von Dunkelhain ein unsicheres Dasein. Dämmerwald ist selbst in den besten Zeiten tückisch, doch die umliegenden Wälder wimmeln von wilden Bestien, unerbittlichen Untoten und schleichenden Worgen. Lars weicht Sven Yorgen nicht von der Seite und versucht schlichtweg, in einer zunehmend feindseligen Wildnis am Leben zu bleiben."},{t="Gefahr aus der Wildnis",b="Das Überleben im Lager erfordert ständige Wachsamkeit gegenüber den ansässigen Raubtieren. Lars sieht sich durch die unerbittlichen Rudel hungernder Terrorwölfe, die in den Schatten um ihr Feuer lauern, schwer bedrängt. Da er seine Wachsamkeit nicht nachlassen lassen und sie nicht allein zurückdrängen kann, ist er auf fähige Reisende angewiesen, um die hungrigen Raubtiere auszudünnen, bevor sein kleines Lager vollkommen überrannt wird."}},faq={{q="Wer ist Lars?",a="Lars ist ein menschlicher Überlebender, der in der Wildnis von Dämmerwald lagert. Er lebt an der Seite seines Freundes und Gefährten Sven Yorgen an der nördlichen Grenze des stillen Ufers und tut, was er kann, um die Schrecken des Waldes zu überstehen.",al={"lars dämmerwald","wer ist lars","lars nsc"}},{q="Wo ist Lars zu finden?",a="Lars befindet sich in einem kleinen Wildnislager am nördlichen Rand des stillen Ufers im westlichen Dämmerwald.",al={"wo ist lars","lars aufenthaltsort","lars lager"}},{q="Vor welchem Problem steht Lars?",a="Lars und Sven werden ständig von den unersättlichen Wölfen und Raubtieren heimgesucht, die in den nahegelegenen Wäldern lauern. Mit der Aufgabe 'Wölfe sind uns auf den Fersen' bittet Lars vorbeikommende Abenteurer darum, die Raubtiere zu jagen, bevor sie sein Lager zerfleischen.",al={"lars quest","wölfe auf den fersen quest","warum braucht lars hilfe"}},{q="In welcher Beziehung steht Lars zu Sven Yorgen?",a="Lars und Sven Yorgen sind Gefährten, die gemeinsam in der Wildnis überleben. Sven hat in der Region seine eigene finstere Vergangenheit und eine Blutrache auszutragen, während Lars hilft, ihren rauen, abgelegenen Außenposten aufrechtzuerhalten.",al={"lars und sven","wer ist sven für lars"}}},fx={["05f5e77d"]={q="Auf wessen Seite steht Lars?",a="Lars ist ein unabhängiger menschlicher Überlebender, der mit der Allianz verbündet ist. Anstatt direkt der The Night Watch oder dem Militär von Sturmwind zu dienen, ist er einfach ein gewöhnlicher Mann, der versucht, die Gefahren des Dämmerwaldes an der Seite seines Gefährten Sven Yorgen zu überstehen.",al={"lars fraktion","ist lars bei der allianz","wem dient lars"}},["2eb2df94"]={q="Warum schlägt Lars im Dämmerwald sein Lager auf?",a="Lars hat in einem rauen Lager am nördlichen Rand des Stillen Ufers Zuflucht gesucht. Er bleibt dort und versucht, im dunklen Wald Tag für Tag in der Gesellschaft von Sven Yorgen zu überleben, während er gegen die vordringenden Raubtiere und Schrecken des Waldes ausharrt.",al={"warum ist lars hier","grund für lars im dämmerwald","warum kam lars hierher"}}},fp="4,232,18.391.0,21.358.0,12.212.0,24.118.0,28.233.0,43.188.0"}
P.entries["npc:laurna-morninglight"] = {n="Laurna Morgenglanz",s="Laurna Morgenglanz ist eine Priesterlehrerin der Nachtelfen, die in der beschaulichen Siedlung Dolanaar auf Teldrassil lebt. Sie ist der Schwesternschaft von Elune ergeben und unterweist angehende Akolythen, die aus Laubschattental kommen, in den spirituellen Riten und heilenden Gaben der Mondgöttin. Ihre Lehren bereiten junge Priester der Nachtelfen auf die wachsenden Gefahren vor, die die Äste des Weltenbaums bedrohen.",h="Laurna Morgenglanz ist eine Priesterlehrerin der Nachtelfen, die in der beschaulichen Siedlung Dolanaar auf...",kw={"dolanaar","elune","kaldorei","laurna","morninglight","priesterlehrer","schwesternschaft von elune","teldrassil"},ang={["class:Priest"]="Für Priester der Nachtelfen, die aus Laubschattental eintreffen, ist Laurna Morgenglanz Eure erste wichtige Mentorin außerhalb des Starttals; sie lehrt grundlegende Zauber und leitet Eure frühe Hingabe an Elune.",["race:NightElf"]="Laurna verkörpert die traditionelle Hingabe der Kaldorei an die Mondgöttin und erinnert Abenteurer daran, dass das Priestertum auf Teldrassil aus Elune und nicht aus dem Heiligen Licht schöpft."},sec={{t="Eine Wegweiserin in Dolanaar",b="Inmitten der Äste von Dolanaar dient Laurna Morgenglanz als eine der wichtigsten Lehrmeisterinnen für junge Priester, die ihre anfänglichen Riten in Laubschattental abgeschlossen haben. Wenn neue Initianden die weiteren Gefilde von Teldrassil betreten, leitet sie sie an, ihre Verbindung zu Elune zu vertiefen und das Licht der Heilung mit defensiven Riten in Einklang zu bringen, die für das Überleben in einer zunehmend feindseligen Wildnis unerlässlich sind."},{t="Hingabe an die Mondgöttin",b="Das Priestertum der Kaldorei ist eng mit der Verehrung Elunes verbunden und unterscheidet sich vom abstrakten Heiligen Licht, das von Menschen und Zwergen verehrt wird. Laurna überträgt ihren Schülern spirituelle Aufgaben, wie etwa den Empfang geweihter Roben und die Heilung einer verwundeten Schildwache. Durch diese Bräuche lernen die Akolythen, dass ihre Kräfte direkte Geschenke von Mutter Mond sind, die der Bewahrung und Genesung des Volkes der Kaldorei dienen."}},faq={{q="Wo finde ich Laurna Morgenglanz?",a="Laurna Morgenglanz hält sich im Dorf Dolanaar auf, das im Herzen von Teldrassil liegt, gleich die Straße hinab von Laubschattental.",al={"laurna aufenthaltsort","wo ist laurna","dolanaar priesterlehrer"}},{q="Welche Funktion erfüllt Laurna Morgenglanz?",a="Sie ist eine Priesterlehrerin für Charaktere der Nachtelfen. Sie lehrt neue Zauber, verbessert die Ränge bekannter Fähigkeiten und bietet erste Orientierung bei klassenspezifischen Riten.",al={"was macht sie","laurna rolle","laurna priesterlehrerin"}},{q="Welche Quests bietet sie an?",a="Sie leitet Klassenquests für angehende Priester ein und schickt sie aus, um verwundeten Verbündeten zu helfen und durch zeremonielle Gewänder und Gebete die göttliche Gunst Elunes zu erbitten.",al={"laurna quests","priesterquests dolanaar"}},{q="Bildet sie auch andere Völker aus?",a="Obwohl sie kulturell in der Schwesternschaft von Elune verwurzelt ist, unterweisen Priesterlehrer der Allianz jeden verbündeten Priester, der nach spiritueller Disziplin strebt.",al={"können menschen hier trainieren","priesterlehrer jedes volk"}},{q="Gehört sie zum Tempel des Mondes?",a="Ja, als Priesterin der Kaldorei sind ihre Gelübde und ihre Magie ganz der Göttin Elune und den weiteren Traditionen gewidmet, die vom Tempel des Mondes in Darnassus überwacht werden.",al={"gehört sie zur schwesterngemeinschaft von elune","laurna tempel des mondes"}},{q="Teilt sie ihren Familiennamen mit anderen Nachtelfen?",a="Unter den Kaldorei von Teldrassil sind keine Verwandten von Laurna bekannt.",al={"morninglight familie","laurna verwandte"}}},fx={["3c87933c"]={q="Wer ist Laurna Morgenglanz?",a="Laurna Morgenglanz ist eine Nachtelfenpriesterin und Mentorin, die im Dorf Dolanaar lebt. Sie widmet sich der Verehrung von Elune und leitet junge Akolythen und Initianden an, die ihre ersten Schritte in Teldrassil machen. Sie lehrt sie, die lindernde Ausstrahlung der Göttin zu kanalisieren und göttlichen Schutz zu erbitten.",al={"wer ist laurna morgenglanz","wer ist laurna","laurna morgenglanz hintergrundgeschichte"}},["5c82db11"]={q="Auf wessen Seite steht Laurna Morgenglanz?",a="Sie ist den Nachtelfen von Darnassus, der Schwesternschaft der Elune und der Allianz treu ergeben. Als Akolythin der Mondgöttin liegt ihr Herz beim Schutz ihres Volkes und der spirituellen Führung der Kaldorei auf Teldrassil.",al={"laurna morgenglanz fraktion","wem dient laurna morgenglanz","laurna morgenglanz allianz"}},["6a7a4981"]={q="Was möchte Laurna Morgenglanz?",a="Ihre hauptsächliche Hingabe gilt der Ausbildung von Priesterneulingen in den Wegen von Elune. Sie möchte, dass vielversprechende Akolythen ihre göttliche Verbindung kultivieren, Heilgebete meistern und heilige Gewänder tragen, um ihre Verwandten in den Zweigen von Teldrassil zu unterstützen.",al={"laurna morgenglanz beweggründe","was tut laurna morgenglanz"}},["65cf8731"]={q="Warum ist Laurna Morgenglanz hier in Dolanaar?",a="Dolanaar ist der wichtigste Knotenpunkt und Sammelplatz für junge Abenteurer, die die abgelegenen Lichtungen von Laubschattental verlassen. Laurna ist hier stationiert, um sicherzustellen, dass angehende Priester angemessene Führung, Unterweisung und heilige Riten erhalten, während sie größere Aufgaben in Teldrassil übernehmen.",al={"warum ist laurna in dolanaar","warum ist laurna morgenglanz hier"}}},fp="19,383,19.397.0,28.400.0,37.141.0,33.165.0,35.158.0,27.162.0,46.168.0,52.66.0"}
P.entries["npc:lelanai"] = {n="Lelanai",s="Lelanai ist eine Nachtelf-Reittierhändlerin, die in der Enklave des Cenarius in Darnassus lebt. Sie stellt den würdigen Reitern die wilden Säbler-Reittiere der Nachtelfen zur Verfügung und bietet sowohl gewöhnliche Nachtsäbler als auch schnelle Kriegsbestien für ihr Volk und vertrauenswürdige Verbündete von Darnassus an.",h="Lelanai ist eine Nachtelf-Reittierhändlerin, die in der Enklave des Cenarius in Darnassus lebt.",kw={"die enklave des cenarius","darnassus","frostsäbler","jartsam","lelanai","reittierhändler","nachtsäbler"},ang={["faction:Alliance"]="Helden der Allianz, die den Ruf ehrfürchtig bei Darnassus erlangen, können Lelanai aufsuchen, um an der Seite ihrer Kaldorei-Verbündeten auf den ikonischen Säblern in die Schlacht zu reiten.",["race:NightElf"]="Für Nachtelfen ist der Besuch bei Lelanai ein wesentlicher Initiationsritus beim Erwerb ihrer traditionellen Katzen-Reittiere."},sec={{t="Züchterin der Enklave des Cenarius",b="Stationiert neben dem Reitlehrer Jartsam inmitten der hoch aufragenden Bäume der Enklave des Cenarius, kümmert sich Lelanai um einige der feinsten Großkatzen, die in Kalimdor gezüchtet werden. Nachtelfen haben seit Langem tiefe Bindungen zu den wilden Raubtieren der nördlichen Wälder aufgebaut und trainieren Nachtsäbler und Frostsäbler, um Wächter und Späher mit raubtierhafter Anmut durch unwegsames Gelände zu tragen. Lelanai dient als Hauptanbieterin dieser verehrten Reittiere in der Hauptstadt."},{t="Bindungen über das eigene Volk hinaus",b="Während Säbler-Reittiere jedem Nachtelf mit entsprechender Fertigkeit frei angeboten werden, müssen Außenstehende eine viel strengere Hürde nehmen. Angesichts der heiligen Natur der Katzen und der natürlichen Zurückhaltung der Kaldorei wird Lelanai einem Nicht-Nachtelfen nur dann ein Tier anvertrauen, wenn dieser sich den höchsten Grad an Respekt und Ansehen bei der Stadt Darnassus verdient hat."}},faq={{q="Wo finde ich Lelanai?",a="Lelanai befindet sich in der Enklave des Cenarius in Darnassus und steht direkt neben dem Tigerreitlehrer Jartsam.",al={"lelanai standort","wo ist lelanai","lelanai karte"}},{q="Was verkauft Lelanai?",a="Sie verkauft Zügel für verschiedene Arten von Frostsäbler- und Nachtsäbler-Reittieren, einschließlich schneller, gepanzerter Varianten für erfahrene Reiter.",al={"lelanai waren","welche reittiere hat sie","nachtelfen reittiere"}},{q="Können Nicht-Nachtelfen Reittiere bei Lelanai kaufen?",a="Ja, aber nur, wenn Ihr Eure außergewöhnliche Loyalität durch den Ruf ehrfürchtig bei Darnassus bewiesen habt. Andernfalls wird sie sich weigern, ihre Bestien an Außenstehende zu verkaufen.",al={"können menschen säbler kaufen","können zwerge auf nachtsäblern reiten","benötigter ruf für säbler"}},{q="Können Spieler der Horde mit Lelanai interagieren?",a="Nein. Lelanai ist der Fraktion Darnassus der Allianz treu ergeben. Mitglieder der Horde werden von ihr und den Wachen der nahegelegenen Enklave als feindliche Eindringlinge behandelt.",al={"kann die horde säbler kaufen","ist lelanai der horde gegenüber freundlich"}}},fx={["8575cac4"]={q="Wer ist Lelanai?",a="Lelanai ist eine Nachtelfen-Reittierzüchterin und Händlerin, die in Darnassus lebt. Stationiert in der üppigen Die Enklave des Cenarius, kümmert sie sich um die majestätischen Säbler, die für die Kaldorei gezüchtet werden, und bietet sie vertrauenswürdigen Champions an, die in der Lage sind, diese wilden katzenartigen Raubtiere zu bändigen.",al={"wer ist lelanai","lelanai identität","lelanai hintergrundgeschichte"}},["4b3049f5"]={q="Auf wessen Seite steht Lelanai?",a="Lelanai ist Darnassus und der gesamten Allianz treu. Sie vertraut ihre ausgebildeten Säbler bereitwillig ihren Nachtelfen-Mitbürgern an, obwohl sie nur dann in Erwägung zieht, sie anderen Mitgliedern der Allianz anzubieten, wenn diese sich höchstes Ansehen und Vertrauen bei ihrem Volk verdient haben.",al={"lelanai fraktion","ist lelanai bei der allianz","wem dient lelanai"}},["18fb2d04"]={q="Warum ist Lelanai hier in Darnassus?",a="Sie hat ihr Zuhause in der Die Enklave des Cenarius von Darnassus, zusammen mit Jartsam, dem Reitlehrer. Dort, inmitten der friedlichen Zweige von Teldrassil, zieht sie Frostsäbler- und Nachtsäbler-Reittiere auf und pflegt sie, die für die Wächterinnen der Kaldorei und Reisende unerlässlich sind.",al={"warum ist lelanai in darnassus","lelanai zweck der die enklave des cenarius","warum ist lelanai hier"}},["14c3da8f"]={q="Was möchte Lelanai?",a="Lelanai möchte sicherstellen, dass ihre wertvollen Nachtsäbler- und Frostsäbler-Reittiere würdige Reiter finden. Sie besteht darauf, dass jeder, der eines ihrer Tiere reiten möchte, über das richtige Training verfügt und wahre Hingabe und Ehrfurcht gegenüber Darnassus zeigt.",al={"was möchte lelanai","lelanai ziel","lelanai motivation"}},ec77c23e={q="An wen ist Lelanai gebunden?",a="Lelanai arbeitet eng mit Jartsam, dem Nachtelfen-Reitlehrer in der Die Enklave des Cenarius, zusammen. Während Jartsam angehenden Reitern die heikle Kunst des Tigerreitens beibringt, stellt Lelanai die verbundenen Säbler bereit, die sie durch ganz Kalimdor tragen.",al={"lelanai verbindungen","mit wem arbeitet lelanai zusammen","lelanai jartsam"}}},fp="7,257,31.437.0,20.352.0,25.112.0,23.126.0,44.160.0,40.150.0"}
P.entries["npc:lieutenant-farren-orinelle"] = {n="Leutnant Farren Orinelle",s="Leutnant Farren Orinelle ist ein Offizier der Armee von Sturmwind, der derzeit im Gasthaus von Süderstade im Vorgebirge des Hügellands stationiert ist. Zutiefst unglücklich über seine Stationierung an der Grenze verbringt er die meiste Zeit mit Trinken, während er seine Pflichten an vorbeireisende Reisende auslagert. Sein primärer militärischer Auftrag besteht darin, sich um die vordringenden Murlocs entlang der Küste zu kümmern – eine lästige Pflicht, die er nur allzu gern delegiert, in der Hoffnung, sich eine Versetzung zurück in den Süden zu sichern.",h="Leutnant Farren Orinelle ist ein Offizier der Armee von Sturmwind, der derzeit im Gasthaus von Süderstade im...",kw={"farren","hillsbrad","marshal redpath","murloc","orinelle","versetzung","süderstade","sturmwind"},ang={["faction:Alliance"]="Für die Champions der Allianz repräsentiert Orinelle die verärgerten Truppen des Südens, die einen einsamen Außenposten im Norden halten und jedem Münzen und Belobigungen bieten, der seine Aufgaben übernimmt.",["race:Human"]="Als Soldat aus Sturmwind, der weit weg vom Wald von Elwynn festsitzt, verdeutlicht Orinelles Verachtung für den Dienst an der nördlichen Grenze die Kluft zwischen dem komfortablen Leben in der Hauptstadt und den harten Einsätzen in Übersee."},sec={{t="Exil in Süderstade",b="Leutnant Farren Orinelle hat sich Süderstade nicht ausgesucht. Weit weg von Sturmwind entsandt, empfindet der Lieutenant die feuchten, umkämpften Küsten von Hillsbrad als miserablen Abstieg gegenüber den zivilisierten Annehmlichkeiten der Hauptstadt. Anstatt die Felder zu patrouillieren oder die Verteidigung mit seinem kommandierenden Offizier, Marshal Redpath, zu koordinieren, hat Orinelle praktisch einen ständigen Wohnsitz im Gasthaus von Süderstade bezogen. Seine Tage verbringt er damit, zu schmollen, zu trinken und von einem offiziellen Versetzungsbefehl zu träumen, der ihn in den Süden zurückbringen wird."},{t="Auslagerung der Pflichten",b="Trotz seines bequemen Platzes in der Taverne untersteht Orinelle weiterhin Marshal Redpath, der den Lieutenant damit beauftragte, die Murlocs zu beseitigen, die die nahe gelegene Küste bevölkern. Nicht gewillt, sich die Stiefel im Schlamm der Küste zu beschmutzen, verlässt sich Orinelle auf umherziehende Abenteurer, um die Kreaturen zu dezimieren und Beweise für ihr Ableben zu sammeln. Er hofft, dass die Vorlage greifbarer Ergebnisse gegenüber seinen Vorgesetzten beweist, dass seine Pflicht erfüllt ist, und seine schließliche Rückberufung nach Sturmwind beschleunigt."}},faq={{q="Wer ist Leutnant Farren Orinelle?",a="Er ist ein Offizier des Militärs von Sturmwind, der in Süderstade stationiert ist, einer Stadt im Vorgebirge des Hügellands. Man findet ihn trinkend im Gasthaus von Süderstade, wo er über seinen Posten mürrt.",al={"farren orinelle","wer ist orinelle","süderstade lieutenant"}},{q="Warum ist er in Süderstade?",a="Er wurde aus Sturmwind nach Norden versetzt, um die örtliche Garnison zu verstärken und Marshal Redpath zu unterstützen. Er verabscheut diesen Auftrag zutiefst und sehnt sich danach, nach Hause zurückzukehren.",al={"warum ist farren in süderstade","orinelle versetzung"}},{q="Was ist sein offizieller Auftrag?",a="Marshal Redpath befahl ihm, sich um die feindseligen Murlocs zu kümmern, die die Küste von Hillsbrad heimsuchen, doch Orinelle zieht es vor, reisende Söldner dafür zu bezahlen, die Kämpfe für ihn auszutragen.",al={"farren pflicht","orinelle mission","farren murlocs"}},{q="Verlässt er jemals das Gasthaus von Süderstade?",a="Nein. Orinelle verbringt fast seine gesamte Zeit damit, an der Bar des Gasthauses herumzulungern, da er davor zurückschreckt, den schlammigen Stränden oder den feindseligen Elementen draußen zu trotzen.",al={"wo man farren findet","farren aufenthaltsort","orinelle gasthaus"}},{q="Was ist Farrens eigentliches Ziel?",a="Er wünscht sich nichts sehnlicher als eine offizielle Versetzung zurück nach Sturmwind, weit weg von den Gefahren und der Trostlosigkeit der Küste Lordaerons.",al={"was will farren","versetzung"}},{q="Wer ist Orinelles Kommandant?",a="Er untersteht Marshal Redpath, der die militärische Abteilung der Allianz kommandiert, die Süderstade verteidigt.",al={"farren vorgesetzter","farren boss","wer befehligt farren"}}},fx={["7d023078"]={q="Auf wessen Seite steht Leutnant Farren Orinelle?",a="Leutnant Orinelle dient der Großen Allianz und berichtet direkt an die Streitkräfte von Sturmwind. Obwohl er sein derzeitiges Kommando im Vorgebirge des Hügellands verabscheut, stellt ihn sein Posten unter Marshal Redpath direkt auf die Seite der Verteidiger von Süderstade gegen regionale Schrecken und die Aggression der Horde.",al={"orinelle fraktion","farren orinelle allianz","wem dient farren"}}},fp="26,423,19.515.0,16.458.0,34.183.0,24.167.0,32.172.0,38.136.0,31.143.0,28.98.0"}
P.entries["npc:lieutenant-haggerdin"] = {n="Leutnant Haggerdin",s="Leutnant Haggerdin ist ein Zwergenoffizier, der auf dem Headland im Alteracgebirge stationiert ist. Er hält Wache vor dem befestigten Tor zum Alteractal und fungiert als primärer Rekrutierungs- und Verbindungsoffizier für die Stormpikegarde. Er beurteilt aufstrebende Champions der Allianz und belohnt jene, die ihren Mut gegen den Frostwolfklan unter Beweis stellen.",h="Leutnant Haggerdin ist ein Zwergenoffizier, der auf dem Headland im Alteracgebirge stationiert ist.",kw={"alterac","zwerg","frostwolf","haggerdin","headland","eisenschmiede","leutnant","proving grounds","stormpike"},ang={["faction:Alliance"]="Leutnant Haggerdin ist Euer primärer Ansprechpartner außerhalb des Alteractals und bietet die Ausweise und offiziellen Ehren an, die Ihr Euch im Kampf gegen den Frostwolfklan verdient habt.",["faction:Horde"]="Als standhafter Posten, der das Portal der Allianz in das Alteractal bewacht, leitet Haggerdin die Verstärkung an, die entsandt wurde, um die Frostwolforcs zu zerschlagen.",["race:Dwarf"]="Als stolzer Offizier des Stormpike-Klans verkörpert Haggerdin Eisenschmiedes unerschütterliche Entschlossenheit, ihr titanisches Erbe in den verschneiten Klüften von Alterac aufzudecken."},sec={{t="Torwächter des Headland",b="In den verschneiten Höhen des Headland oberhalb des Vorgebirges des Hügellands gelegen, überwacht Leutnant Haggerdin den Sammelpunkt für den anhaltenden Feldzug der Allianz im Alteractal. Zwergische Banner flattern neben dem massiven Holztor, während sich Rekruten und Veteranen unter seinen wachsamen Augen versammeln und sich darauf vorbereiten, in das eisige Kriegsgebiet vorzudringen."},{t="Stimme der Stormpikegarde",b="Im Dienst der Stormpike-Expedition stellt Haggerdin sicher, dass nur erprobte Krieger Eisenschmiede und die Große Allianz im Tal vertreten. Durch Herausforderungen wie die Proving Grounds beauftragt er Rekruten mit der Bergung von Bannern und Relikten und verleiht offizielle Belobigungen, Abzeichen und Ranganerkennungen, während die Soldaten in den Rängen der Stormpikegarde aufsteigen."}},faq={{q="Wer ist Leutnant Haggerdin?",a="Leutnant Haggerdin ist ein Zwergenoffizier, der die Stormpikegarde vertritt. Am Eingang zum Alteractal auf dem Headland im Alteracgebirge stationiert, überwacht er die Rekrutierung der Allianz und verleiht Schlachtfeldehren.",al={"haggerdin","wer ist haggerdin","leutnant haggerdin alterac"}},{q="Wo finde ich Leutnant Haggerdin?",a="Er befindet sich im nördlichen Alteracgebirge auf dem Headland, direkt vor dem Portal und den Toren, die unmittelbar in das Alteractal führen.",al={"haggerdin standort","wo ist leutnant haggerdin","alteractal eingang allianz"}},{q="Welche Rolle spielt Haggerdin in der Stormpikegarde?",a="Er dient als Feldverbindungs- und Quartiermeisteroffizier, der Rekrutierungsprüfungen wie die Proving Grounds leitet und Kämpfer der Allianz mit höheren Rängen und Abzeichen belohnt, während ihr Ruf bei der Stormpikegarde wächst.",al={"was macht haggerdin","haggerdin quests","offizier der stormpikegarde"}},{q="Warum kämpft die Allianz im Alteractal?",a="Die Stormpike-Expedition reiste in das Tal, um uralte Relikte und die Geschichte der Zwerge auszugraben, doch ihre Ankunft entfachte einen erbitterten territorialen Konflikt mit den dort ansässigen Frostwolforcs und ihren Verbündeten der Horde.",al={"warum alteractal","ziel der stormpike-expedition","alterackonflikt"}},{q="Können Spieler der Horde mit Leutnant Haggerdin interagieren?",a="Nein. Leutnant Haggerdin ist ein aktiver Offizier der Allianz und wird jeden Champion der Horde angreifen, der sich in die Nähe des Tors am Headland wagt.",al={"ist haggerdin feindselig gegenüber der horde","horde haggerdin","kann horde mit haggerdin sprechen"}},{q="Was ist die Prüfung der Proving Grounds?",a="Die Proving Grounds sind ein einführender Auftrag, den Haggerdin angehenden Soldaten der Allianz erteilt, um deren Kompetenz und Entschlossenheit zu prüfen, bevor sie sich voll und ganz den Kriegsanstrengungen im Alteractal verschreiben.",al={"quest proving grounds","proving grounds alterac","haggerdin proving grounds"}}},fx={["1d45d886"]={q="Auf wessen Seite steht Leutnant Haggerdin?",a="Leutnant Haggerdin ist der Allianz absolut treu ergeben und dient speziell in der Stormpikegarde. Er operiert am nördlichen Rand des Vorgebirges nahe dem Alteractal und fungiert als Offizier und Musterungsbeauftragter für Allianzstreitkräfte, die sich gegen die Frostwolf-Orks sammeln.",al={"haggerdin fraktion","ist haggerdin bei der allianz","haggerdin zugehörigkeit"}},["5fb68a23"]={q="Was möchte Leutnant Haggerdin?",a="Haggerdin möchte fähige Allianz-Champions, um die Reihen der Stormpikegarde im Alteractal zu verstärken. Er testet neue Rekruten, um sicherzustellen, dass sie die eisige Wildnis überleben können, erkennt erfahrene Veteranen mit Rängen und Abzeichen an, wenn ihre Taten wachsen, und strebt den Untergang von Bedrohungen wie dem Winterax-Trollchampion Korrak an.",al={"was möchte haggerdin","haggerdin ziele","haggerdin zweck"}},["96f37aaa"]={q="Warum ist Leutnant Haggerdin hier im Alterac-Vorgebirge?",a="Leutnant Haggerdin ist am Headland stationiert, das das Tor zum Alteractal überblickt, um eintreffende Allianzstreitkräfte zu organisieren und zu überprüfen. Da der anhaltende Zusammenstoß zwischen der Stormpike-Expedition und dem Frostwolfklan ständige Verstärkung erfordert, hält er an den Bereitstellungsplätzen Wache, um diejenigen zu rekrutieren und zu ehren, die bereit sind, im Schnee zu kämpfen.",al={"warum ist haggerdin hier","warum ist haggerdin im alterac","haggerdin posten"}},["9b7a183a"]={q="An wen ist Leutnant Haggerdin gebunden?",a="Haggerdin ist direkt an die Stormpikegarde gebunden, den militärischen Arm der Stormpike-Expedition von Eisenschmiede unter der Führung von General Vanndar Sturmlanze. Er dient als Offizier, der Allianz-Rekruten, die durch das Alteracgebirge ankommen, mit dem Regiment verbindet, das tief im Alteractal kämpft.",al={"haggerdin verbindungen","haggerdin stormpikegarde","wem dient haggerdin"}}},fp="20,345,26.335.0,28.362.0,28.224.0,38.145.0,53.231.0,47.211.0,53.126.0,34.195.0"}
P.entries["npc:lieutenant-lisande"] = {n="Leutnant Lisande",s="Leutnant Lisande ist eine Gesandte der Argentumdämmerung, die auf den hohen Hochebenen von Donnerfels stationiert ist. Als Mensch, der sich offen in den Ländern der Tauren aufhält, dient sie als Verbindungsperson gegen die gemeinsame existenzielle Bedrohung durch die Geißel.",h="Leutnant Lisande ist eine Gesandte der Argentumdämmerung, die auf den hohen Hochebenen von Donnerfels...",kw={"argentumdämmerung","leutnant lisande","lisande","mulgore","geißel","invasion der geißel","donnerfels"},ang={["faction:Horde"]="Lisande dient als Erinnerung daran, dass der Krieg gegen die Geißel Pragmatismus und gelegentliche Zusammenarbeit mit neutralen menschlichen Orden erfordert.",["race:Tauren"]="Obwohl Lisande eine Außenstehende ist, respektieren die Tauren die Hingabe der Argentumdämmerung, das Land von der abscheulichen Verderbnis der Untoten zu reinigen."},sec={{t="Eine ungewöhnliche Gesandte",b="Während menschliche Gesichter auf den windgepeitschten Höhen von Donnerfels eine Seltenheit sind, steht die Argentumdämmerung über den traditionellen Feindseligkeiten der Fraktionen. Leutnant Lisande dient dem heiligen Orden, indem sie selbst im fernen Kalimdor nach Anzeichen für das Verderben des Lichkönigs Ausschau hält. Wenn sich untote Streitkräfte in den Ebenen darunter regen, ruft sie tapfere Champions der Horde zusammen, um auszureiten und der herannahenden Bedrohung nachzugehen, bevor sie die heilige Erde entweihen kann."}},faq={{q="Warum steht ein Mensch in Donnerfels?",a="Lisande vertritt die Argentumdämmerung, eine neutrale Organisation, die sich einzig der Vernichtung der Geißel verschrieben hat. Da die Dämmerung sowohl Völker der Allianz als auch der Horde in ihren Reihen willkommen heißt, wird ihren Verbindungspersonen diplomatischer Zutritt zu den Hauptstädten gewährt, um die Verteidigung gegen die Untoten zu koordinieren.",al={"mensch in donnerfels","warum ist lisande hier","ist sie feindselig"}},{q="Welches Interesse hat die Argentumdämmerung an Mulgore?",a="Die Reichweite des Lichkönigs bedroht jeden Winkel von Azeroth, nicht nur die Östlichen Königreiche. Lisande überwacht jegliche Anzeichen nekromantischer Aktivitäten oder einfallender Streitkräfte der Geißel, die den Frieden von Mulgore gefährden, und sorgt dafür, dass die örtlichen Verteidiger vor der Gefahr gewarnt sind.",al={"geißel in mulgore","warum donnerfels","untote im taurenland"}},{q="Welche Aufgaben vergibt Leutnant Lisande?",a="Lisande weist Abenteurer an, von den Klippen herabzusteigen, um Übergriffen der Geißel nachzugehen, die im Umland gesichtet wurden, und beauftragt sie damit, Bericht zu erstatten, damit die Dämmerung das Ausmaß der Bedrohung einschätzen kann.",al={"lisande quest","was tut lisande","untersuchungsquest"}}},fx={["0fde76ad"]={q="An wen ist Leutnant Lisande gebunden?",a="Sie ist direkt an die Argentumdämmerung gebunden, einen unabhängigen Orden aus heiligen Kriegern, Magiern und Spähern verschiedenster Völker, der gegründet wurde, um die Geißel überall dort zu bekämpfen, wo die untote Bedrohung ihr Haupt erhebt.",al={"lisande fraktion","mit wem arbeitet lisande zusammen","lisande verbindungen"}},["986453a4"]={q="Wer ist Leutnant Lisande?",a="Leutnant Lisande ist eine Offizierin, die der Argentumdämmerung dient. Obwohl sie ein Mensch im Herzen des Territoriums der Horde ist, steht sie offen in Donnerfels, um tapfere Verteidiger gegen eine Bedrohung zu versammeln, die alles Lebendige gefährdet.",al={"wer ist lisande","leutnant lisande identität","wer ist leutnant lisande"}},b5328b2a={q="Auf wessen Seite steht Leutnant Lisande?",a="Lisande ist der Argentumdämmerung treu und nicht der Allianz. Die Dämmerung ist ein neutrales Bündnis, das sich vollständig dem Kampf gegen die Geißel widmet, was es ihr ermöglicht, ohne fraktionsbedingte Feindseligkeiten direkt mit den Tauren und Champions der Horde zusammenzuarbeiten.",al={"lisande allianz oder horde","wem dient lisande","ist lisande bei der allianz"}},["9158bc2a"]={q="Was möchte Leutnant Lisande?",a="Lisande möchte wachsame Abenteurer, die die Streitkräfte der Geißel untersuchen und bekämpfen, die auf das Land außerhalb von Donnerfels übergreifen. Ihr Ziel ist es, die Bedrohung durch die Untoten einzudämmen, bevor sie die Ebenen von Mulgore überrennen kann.",al={"was möchte lisande","lisande ziele","warum braucht lisande hilfe"}}},fp="18,223,17.412.0,41.280.0,46.253.0,44.211.0"}
P.entries["npc:lieutenant-nevell"] = {n="Leutnant Nevell",s="Leutnant Nevell ist ein Offizier der Argentumdämmerung, der vor den Toren von Eisenschmiede in Dun Morogh stationiert ist. Als Bollwerk gegen die sich ausbreitende Dunkelheit der Geißel koordiniert er die örtlichen Verteidiger und warnt eintreffende Abenteurer vor untoten Bedrohungen, die die Grenzen des Zwergenreichs auskundschaften.",h="Leutnant Nevell ist ein Offizier der Argentumdämmerung, der vor den Toren von Eisenschmiede in Dun Morogh...",kw={"argentumdämmerung","dun morogh","eisenschmiede","leutnant nevell","nevell","geißel"},ang={["faction:Alliance"]="Für Champions der Allianz, die nach Eisenschmiede reisen, dient Nevell als Mahnung, dass der Krieg gegen die Geißel nicht auf den Norden beschränkt ist.",["race:Dwarf"]="Die Zwerge schätzen das wachsamen Auge der Argentumdämmerung vor ihrer bergigen Heimat wohlwissend, dass Wachsamkeit gegenüber Nekromantie selbst an den kalten Hängen von Dun Morogh geboten ist."},sec={{t="Eine Wacht im Schnee",b="Während die Argentumdämmerung vor allem dafür bekannt ist, die Stellung in den zerrütteten Pestländern von Lordaeron zu halten, reicht ihre Wachsamkeit weit in den Süden. In den eisigen Winden vor Eisenschmiede stationiert, verkörpert Leutnant Nevell die vorausschauende Verteidigung des Ordens gegen nekromantische Übergriffe. Wenn sich Geißelaktivitäten in den Bergpässen von Dun Morogh regen, weist Nevell Rekruten und fähige Abenteurer an die Frontlinien ein, um sicherzustellen, dass Eisenschmiedes schneebedeckte Schwelle sicher bleibt."}},faq={{q="Wer ist Leutnant Nevell?",a="Leutnant Nevell ist ein Offizier der Argentumdämmerung, der nahe Eisenschmiede in Dun Morogh stationiert ist. Seine Mission besteht darin, lokale Verteidiger zu sammeln und Hinweisen auf eine Präsenz der Geißel nachzugehen, die auf das Zwergenreich übergreift.",al={"nevell rolle","wer ist nevell","leutnant nevell"}},{q="Warum befindet sich die Argentumdämmerung vor Eisenschmiede?",a="Obwohl sie hauptsächlich in Lordaeron ansässig ist, überwacht die Argentumdämmerung den gesamten Kontinent auf Übergriffe der Untoten. Sollte der Lichkönig versuchen, tief in verbündete Gebiete wie Dun Morogh vorzustoßen, werden Offiziere wie Nevell entsandt, um die Stadtverteidigung zu koordinieren und feindliche Truppenbewegungen auszuspähen.",al={"argentumdämmerung in dun morogh","argentumdämmerung eisenschmiede"}},{q="Worum bittet Leutnant Nevell die Abenteurer?",a="Nevell beauftragt fähige Helden damit, hinter die Tore von Eisenschmiede vorzudringen, um nahe Streitkräfte der Geißel aufzuklären und zurückzuschlagen, wodurch die untote Bedrohung neutralisiert wird, bevor sie in den Bergpässen Fuß fassen kann.",al={"nevell quests","die geißel untersuchen"}}},fx={["4853a4a6"]={q="Auf wessen Seite steht Leutnant Nevell?",a="Leutnant Nevell dient der Argentumdämmerung, einem entschlossenen neutralen Orden, der sich dem Schutz Azeroths vor der Geißel verschrieben hat. Obwohl er ein Mensch ist, steht er als Verbündeter aller Gegner der untoten Bedrohung vor den Toren von Eisenschmiede und koordiniert die Verteidigung gemeinsam mit den Zwergen, anstatt direkt dem Militär der Allianz zu dienen.",al={"leutnant nevell fraktion","für wen kämpft leutnant nevell","ist nevell argentumdämmerung"}},["5e43a7a7"]={q="An wen ist Leutnant Nevell gebunden?",a="Nevell berichtet direkt an die Führung der Argentumdämmerung. Stationiert an den Hängen von Dun Morogh, fungiert er als Verbindungsperson zwischen dem Orden und den Verteidigern von Eisenschmiede und versammelt lokale Abenteurer und Gebirgswachen, um jede schleichende Bedrohung durch die Geißel in der Region zu bekämpfen.",al={"nevell verbindungen","leutnant nevell argentumdämmerung bindungen","wem untersteht nevell"}}},fp="17,292,19.476.0,25.208.0,41.278.0,50.205.0"}
P.entries["npc:lieutenant-orrin"] = {n="Leutnant Orrin",s="Leutnant Orrin ist ein Offizier der Argentumdämmerung, der an den Toren von Sturmwind stationiert ist. Im Tal der Helden positioniert, koordiniert er die lokale Verteidigung gegen Übergriffe der Geißel und weist neue Rekruten an, untote Bedrohungen außerhalb der Mauern der Hauptstadt zu untersuchen.",h="Leutnant Orrin ist ein Offizier der Argentumdämmerung, der an den Toren von Sturmwind stationiert ist.",kw={"argentumdämmerung","leutnant orrin","nekrotischer kristall","orrin","geißel","sturmwind","untote","das tal der helden"},ang={["class:Paladin"]="Paladine, die das Licht hochhalten, finden oft eine natürliche Gemeinsamkeit mit den Bemühungen der Argentumdämmerung, die Nekromantie überall dort auszumerzen, wo sie schwelt.",["faction:Alliance"]="Für Champions der Allianz, die in die Hauptstadt zurückkehren, dient Orrin als deutliche Mahnung, dass selbst das südliche Kernland nicht gänzlich vor der Reichweite des Lichkönigs sicher ist."},sec={{t="Ein Wächter an den Toren",b="Obwohl die Argentumdämmerung vor allem dafür bekannt ist, die Frontlinien im zerstörten Norden zu halten, reicht ihre Präsenz bis in den Süden, um lebenswichtige Festungen wie Sturmwind zu schützen. Leutnant Orrin steht nahe den hoch aufragenden Statuen im Tal der Helden und beobachtet die Straße auf Anzeichen von Verderbnis. Wenn sich außerhalb der Hauptstadt nekromantische Magie regt, obliegt es ihm, Alarm zu schlagen und Abenteurer zu sammeln, bevor finstere Mächte die Bevölkerung bedrohen können."},{t="Ein wachsames Auge auf die Untoten",b="Orrin fungiert als wichtiges Bindeglied zwischen dem unabhängigen Orden und Freiwilligen im südlichen Königreich. Wenn jenseits der Stadttore Anzeichen der Geißel auftauchen, stellt er fähige Späher zusammen und schickt sie aus, um Informationen zu sammeln und gefährliche Artefakte wie gesprungene nekrotische Kristalle zu sichern, um die Bedrohung durch die Untoten besser zu verstehen und abzuwehren."}},faq={{q="Wer ist Leutnant Orrin?",a="Leutnant Orrin ist ein menschlicher Offizier im Dienst der Argentumdämmerung. Er ist im Tal der Helden am Eingang von Sturmwind stationiert und damit beauftragt, die Verteidigung zu koordinieren und Späher anzuwerben, wann immer die Geißel das Umland bedroht.",al={"wer ist orrin","leutnant orrin lore","wer ist der offizier der argentumdämmerung"}},{q="Warum befindet sich die Argentumdämmerung in Sturmwind?",a="Obwohl die Argentumdämmerung ihren Krieg gegen die Geißel hauptsächlich in den Plaguelands führt, unterhält sie Außenposten und Verbindungsoffiziere in bedeutenden Zentren der Allianz und der Horde. An den Toren der Hauptstadt stationiert, halten Offiziere wie Orrin Ausschau nach nekromantischen Übergriffen und rekrutieren fähige Kämpfer, um die Ausbreitung der Untoten einzudämmen.",al={"warum ist die argentumdämmerung in sturmwind","argentumdämmerung sturmwind","was macht die argentumdämmerung hier"}},{q="Worum bittet Leutnant Orrin die Abenteurer?",a="Orrin weist Rekruten an, die Umgebung außerhalb von Sturmwind auszukundschaften, Anzeichen von Aktivitäten der Geißel nachzugehen und Artefakte wie gesprungene nekrotische Kristalle zu bergen, um die unheilige Magie hinter den Übergriffen zu erforschen.",al={"orrin quests","erforscht die geißel von sturmwind","was will orrin"}}},fx={["3ede5d84"]={q="Auf wessen Seite steht Leutnant Orrin?",a="Leutnant Orrin dient der Argentumdämmerung, einem entschlossenen neutralen Bündnis, das geformt wurde, um die Geißel überall dort zu bekämpfen, wo sie Azeroth bedroht. Obwohl er innerhalb des Tals der Helden von Sturmwind inmitten menschlicher Verteidiger stationiert ist, bleibt seine primäre Loyalität der heiligen Mission der Dämmerung und nicht der Politik der Allianz gewidmet.",al={"leutnant orrin fraktion","wem dient orrin","ist leutnant orrin allianz"}}},fp="16,276,23.446.0,20.352.0,24.244.0,41.313.0,49.210.0"}
P.entries["npc:loganaar"] = {n="Loganaar",s="Loganaar ist ein Nachtelf und Ausbilder der Druiden, der in der Zuflucht Nachthafen in Mondlichtung weilt. Er widmet sich der Führung von Initianden sowohl der Allianz als auch der Horde und unterweist junge Druiden, während sie sich auf die Wildnis einstimmen und sich auf den Ruf des Smaragdgrünen Traums vorbereiten.",h="Loganaar ist ein Nachtelf und Ausbilder der Druiden, der in der Zuflucht Nachthafen in Mondlichtung weilt.",kw={"zirkel des cenarius","druidenlehrer","smaragdgrüner traum","loganaar","mondlichtung","nachthafen"},ang={["class:Druid"]="Sowohl für Druiden aus Darnassus als auch aus Donnerfels ist Loganaar einer der ersten Mentoren, denen sie nach der Teleportation nach Mondlichtung begegnen, und er bietet fortgeschrittene Ausbildung sowie spirituellen Rat.",["race:NightElf"]="Loganaar spiegelt die uralten Traditionen der Druiden der Kaldorei wider, die Jahrtausende damit verbrachten, Zwiesprache mit der Natur zu halten und unter Malfurion Sturmgrimm in den Smaragdgrünen Traum einzutreten."},sec={{t="Hüter der heiligen Kunst",b="Inmitten der ruhigen Baumkronen von Nachthafen dient Loganaar als ein zentraler Mentor für frisch initiierte Druiden, die nach Mondlichtung reisen. Unabhängig davon, ob ein Novize aus Darnassus oder Donnerfels stammt, vermittelt Loganaar Weisheit über Gleichgewicht, Gestaltwandlung und die Ehrfurcht vor der Natur. Er erinnert seine Schüler daran, dass wahre Seelenruhe selbst inmitten kalter Steine und fremder Lande im eigenen Inneren gefunden werden muss. Zudem fungiert er als einladender Wegweiser für jene, die tiefer in die Belange des Zirkels des Cenarius eintauchen, und schickt vielversprechende Schüler zu Wanderern wie Torwa Pfadfinder im Krater von Un'Goro oder tiefer in uralte Waldriten."},{t="Der Ruf des Traums",b="Über die grundlegende Zauberkunst hinaus bereitet Loganaar die Schüler auf die höchste Bestimmung vor, die alle traditionellen Beschützer Kalimdors teilen: den tiefen Schlummer des Smaragdgrünen Traums. Er lehrt die Initianden über die heilige Verbindung zwischen Azeroths urzeitlicher Geisterwelt und der wachenden Welt und erinnert sie daran, dass wahre Meisterschaft eines Tages einen jahrhundertelangen Winterschlaf erfordern wird, um unter der Führung der Halbgötter inmitten der reinsten, unberührten Formen der Natur zu wandeln."}},faq={{q="Wer ist Loganaar?",a="Loganaar ist ein Nachtelf-Druidenlehrer in Nachthafen, der zentralen Siedlung von Mondlichtung. Er heißt Druiden jeder Herkunft willkommen, um sie in ihren Künsten zu unterweisen, und führt sie an die tieferen Traditionen des Zirkels des Cenarius heran.",al={"loganaar nsc","wer ist loganaar","loganaar lore"}},{q="Bildet Loganaar Horde-Druiden aus?",a="Ja. Mondlichtung ist heiliger, neutraler Boden unter der Obhut des Zirkels des Cenarius. Als Mitglied des Zirkels legt Loganaar den Konflikt zwischen der Allianz und der Horde beiseite, um Tauren- und Nachtelfen-Druiden gleichermaßen zu unterrichten.",al={"können tauren bei loganaar trainieren","loganaar horde","druidenlehrer mondlichtung horde"}},{q="Was lehrt Loganaar über den Smaragdgrünen Traum?",a="Loganaar lehrt, dass jeder wahre Druide letztlich den Ruf des Smaragdgrünen Traums spüren wird. Er erklärt, dass während eines langen, tiefen Winterschlafs inmitten seiner unberührten Formen die eigentliche, vollendete Ausbildung eines Druiden stattfindet.",al={"loganaar traum","smaragdgrüner traum zitat"}},{q="Wohin schickt Loganaar erfahrene Druiden?",a="Sobald Druiden an Erfahrung gewinnen, weist Loganaar ihnen den Weg hinaus in die Welt, um Azeroths ursprüngliche Ökosysteme zu beobachten und zu heilen. Unter anderem entsendet er erfahrene Schüler, um Naturforschern wie Torwa Pfadfinder in der ungezähmten Wildnis des Un'Goro-Kraters beizustehen.",al={"loganaar quests","torwa pfadfinder quest loganaar"}}},fp="8,261,24.626.0,21.439.0,16.225.0,33.211.0,49.225.0,41.245.0"}
P.entries["npc:lomac-gearstrip"] = {n="Lomac Ritzeldreh",s="Lomac Ritzeldreh ist ein ehrgeiziger Gnomen-Erfinder, der in Tüftlerstadt in Eisenschmiede ansässig ist. Bekannt für die Entwicklung des verheerenden NG-5-Sprengstoffs, steht er in Verbindung mit anderen Gnomenforschern, die in ganz Kalimdor tätig sind.",h="Lomac Ritzeldreh ist ein ehrgeiziger Gnomen-Erfinder, der in Tüftlerstadt in Eisenschmiede ansässig ist.",kw={"ein alter kollege","gnomen-ingenieur","stümperhaftigkeit + chemikalien = riesenspaß!","eisenschmiede","lomac ritzeldreh","ng-5 sprengstoff","steinkrallengebirge","tüftlerstadt"},ang={["faction:Alliance"]="Allianz-Agenten, die zwischen Eisenschmiede und Expeditionsaußenposten in Kalimdor reisen, transportieren im Auftrag von Lomac häufig heikle Munition und flüchtige Formeln.",["profession:Engineering"]="Lomacs NG-5-Sprengstoff repräsentiert den neuesten Stand der Gnomen-Pyrotechnik und dient Tüftlern, die sich für Sprengstoffe mit enormer Wirkung interessieren, als Vorbild.",["race:Gnome"]="Lomac verkörpert den unermüdlichen Tatendrang der Gnome von Tüftlerstadt und führt anspruchsvolle technische Forschungen selbst im Exil fernab von Gnomeregan fort."},sec={{t="Ein Funke in Tüftlerstadt",b="Inmitten der klappernden Zahnräder und zischenden Rohre von Eisenschmiedes Tüftlerstadt widmet sich Lomac Ritzeldreh den Feinheiten der Gnomen-Artillerie. Wie viele exilierte Gnom, die vor der Tragödie in Gnomeregan flohen, hat Lomac seine Tüfteleien direkt in die Zwergenhauptstadt verlegt. Seine Werkstatt konzentriert sich auf flüchtige chemische Gemische und Spezialmunition, die darauf ausgelegt sind, schwer verteidigte feindliche Festungen zu überwinden."},{t="Der NG-5-Sprengstoff",b="Lomacs stolzester Beitrag zur modernen Kampftechnik ist der NG-5-Sprengstoff. Für maximale Zerstörungskraft entwickelt, verlangt das Gemisch präzise Handhabung und seltene chemische Reagenzien. Um derart gefährliche Erfindungen im Feld zu verfeinern und einzusetzen, hält Lomac Kontakt zu alten Kollegen, die auf fernen Kriegsschauplätzen stationiert sind, und tauscht technische Aufträge und gefährliche Lieferungen über das große Meer hinweg aus."}},faq={{q="Wo kann ich Lomac Ritzeldreh finden?",a="Lomac Ritzeldreh befindet sich in Tüftlerstadt, dem Gnomenviertel im östlichen Teil der Bergstadt Eisenschmiede.",al={"lomac ritzeldreh standort","wo ist lomac","lomac ritzeldreh finden"}},{q="Wofür ist Lomac Ritzeldreh als Erfinder berühmt?",a="Lomac ist vor allem als Schöpfer des NG-5-Sprengstoffs bekannt, einer mächtigen Geschützformel, die den Unternehmungen der Gnome verheerende Feuerkraft verleihen soll.",al={"was hat lomac gebaut","lomac erfindung","ng-5 sprengstoff entwickler"}},{q="Warum hat Lomac Kontakte in Kalimdor?",a="Lomac hält Kontakt zu früheren Forscherkollegen, die in Grenzregionen wie dem Steinkrallengebirge arbeiten, koordiniert die Beschaffung gefährlicher chemischer Zutaten und testet seine Sprengstoffe mit hoher Sprengkraft in aktiven Operationen.",al={"lomac steinkrallengebirge","warum steinkrallengebirge quest","lomac kollegen"}},{q="Welche Aufgaben überträgt Lomac Abenteurern?",a="Lomac beauftragt vertrauenswürdige Kuriere der Allianz damit, Bestellungen und flüchtige chemische Reagenzien zwischen Eisenschmiede und im Ausland stationierten Forschern zu transportieren, oft im Zusammenhang mit Experimenten an seinem NG-5-Sprengstoff.",al={"lomac quests","chemikalien ungeschicklichkeit spaß","ein alter kollege quest"}},{q="Was ist die mit Lomac verbundene Purchase Order Receipt?",a="Lomac hat die Purchase Order Receipt verfasst, ein Dokument, das dazu dient, Lieferungen von Spezialausrüstung und gefährlichen, flüchtigen Reagenzien zwischen Tüftlern zu organisieren und festzuhalten.",al={"purchase order receipt","lomac beleg"}},{q="Gehört Lomac zu den Flüchtlingen aus Gnomeregan?",a="Ja. Wie die übrigen Bewohner von Tüftlerstadt gehört Lomac zur vertriebenen Gemeinschaft von Gnomeregan, die die Gastfreundschaft der Zwerge von Eisenschmiede genießt, während er seine Ingenieursarbeiten fortsetzt.",al={"stammt lomac aus gnomeregan","lomac fraktion"}}},fx={e46167fb={q="Wer ist Lomac Ritzeldreh?",a="Lomac Ritzeldreh ist ein ehrgeiziger gnomischer Erfinder und Tüftler, der in der Tüftlerstadt innerhalb der Zwergenfestung Eisenschmiede operiert. Er ist tief in unbeständige Experimente und Chemieingenieurwesen vertieft und vor allem für die Entwicklung potenter Kampfmittel wie des NG-5-Sprengsatzes bekannt. Trotz der Entfernung über das große Meer unterhält er Kontakte und geschäftliche Vereinbarungen bis hin nach Kalimdor, um seltene Materialien und Feldtests für seine Arbeit zu erhalten.",al={"wer ist lomac","wer ist ritzeldreh","lomac ritzeldreh hintergrund"}},["6618560a"]={q="Was will Lomac Ritzeldreh?",a="Lomac Ritzeldreh wird von seinen explosiven Ingenieursprojekten angetrieben, allen voran der Verfeinerung seines geschätzten NG-5-Sprengsatzes. Um seine chemischen Versuche voranzutreiben, benötigt er Kuriere, flüchtige Verbindungen und Feldtests, die mit seinen Gebräuen durchgeführt werden. Er verlässt sich auf Reisende und alte Bekannte in aller Welt, um Bestellungen auszuführen und die seltenen Reagenzien zu beschaffen, die nötig sind, um seine instabilen Erfindungen zu perfektionieren.",al={"was will lomac","lomac ritzeldreh ziele","warum braucht lomac hilfe"}},ca50cdb6={q="An wen ist Lomac Ritzeldreh gebunden?",a="Lomac unterhält Beziehungen zu weit entfernten Mitarbeitern und anderen Tüftlern, einschließlich eines alten Kollegen im Ausland, der ihn bei Bestellungen und spezialisierten Tests unterstützt. Von der Tüftlerstadt aus arbeitet er komfortabel sowohl mit den Gnomeregangnome als auch mit den ansässigen Handwerkern von Eisenschmiede zusammen und weist Kuriere und Abenteurer an, zwischen seiner Werkbank in den Östlichen Königreichen und den Testgeländen in ganz Kalimdor zu vermitteln.",al={"mit wem arbeitet lomac zusammen","lomac ritzeldreh mitarbeiter","lomac alter kollege"}}},fp="15,212,22.406.0,18.398.0,33.125.0,45.148.0,46.240.0,51.206.0,49.169.0,47.196.0"}
P.entries["npc:longbraid-the-grim"] = {n="Langzopf der Grimmige",s="Langzopf der Grimmige ist ein Zwergenkommandant aus Eisenschmiede, der direkt vor der gefallenen Festung Dun Modr im nördlichen Sumpfland stationiert ist. Er betrauert den Verlust seines Bruders sowie die Einnahme des Thandol-Übergangs und koordiniert die überlebenden Zwergentruppen gegen den eindringenden Dunkeleisenzwerge-Clan.",h="Langzopf der Grimmige ist ein Zwergenkommandant aus Eisenschmiede, der direkt vor der gefallenen Festung Dun...",kw={"dunkeleisenzwerge","dun modr","longbraid","thandol-übergang","der grimmige","sumpfland","whelgar"},ang={["faction:Alliance"]="Longbraid hält die dünne Verteidigungslinie am Nordtor von Khaz Modan und kämpft dafür, die wichtige Landverbindung über den Thandol-Übergang nach Arathi wieder zu öffnen.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede verkörpert Longbraid die erbitterte, anhaltende Blutfehde gegen ihre verräterischen Dunkeleisen-Vettern, die direkt an ihrer nördlichen Pforte zuschlugen."},sec={{t="Eine bittere Wacht",b="In Sichtweite der Brücke zum Arathihochland sammelt Langzopf der Grimmige die Reste der Zwergengarnison, nachdem der Dunkeleisenclan Dun Modr eingenommen hat. Der überraschende Angriff vernichtete die regionalen Verteidiger und forderte während der Belagerung des Thandol-Übergangs das Leben von Longbraids eigenem Bruder. Gezeichnet von Trauer und Hass weigert sich Longbraid, die nördliche Grenze aufzugeben, und leitet Reisende sowie überlebende Gebirgsjäger bei gezielten Vorstößen an, um das Vordringen der Dunkeleisenzwerge einzudämmen."},{t="Die Stellung halten",b="Über die Verteidigung des Zugangs zur Brücke hinaus beaufsichtigt Longbraid weiter reichende Zwergenoperationen im gesamten Sumpfland. Er entsandte unverzichtbare Soldaten zur Eskorte von Ausgrabungsleiter Whelgar in den Marschen und arbeitet unermüdlich daran, die verlorenen Befestigungen von Dun Modr zurückzuerobern, während er den Saboteuren der Dunkeleisenzwerge Vergeltung schwört."}},faq={{q="Wer ist Langzopf der Grimmige?",a="Langzopf der Grimmige ist ein Zwergenkommandant, der vor Dun Modr im nördlichen Sumpfland stationiert ist. Er führt den lokalen Widerstand der Allianz gegen die Dunkeleisenzwerge an, die das Gebiet überrannt haben.",al={"wer ist longbraid","identität von longbraid","dun modr zwerg"}},{q="Warum wird Longbraid 'der Grimmige' genannt?",a="Er erhielt sein grimmiges Wesen, nachdem sein Bruder während des verheerenden Angriffs der Dunkeleisenzwerge auf den Thandol-Übergang getötet wurde. Seither ist er von dem Verlangen getrieben, seinen gefallenen Verwandten zu rächen.",al={"warum ist er grimmig","longbraids bruder","longbraid hintergrundgeschichte"}},{q="Was geschah mit Dun Modr?",a="Dun Modr wurde vom Dunkeleisenclan überrannt und besetzt, der die Zwergengarnison überfiel und versuchte, den Thandol-Übergang zu zerstören, um die Hauptroute zwischen dem Sumpfland und dem Arathihochland abzuschneiden.",al={"der fall von dun modr","was geschah mit der brücke","angriff auf den thandol-übergang"}},{q="Was verbindet Longbraid mit Ausgrabungsleiter Whelgar?",a="Longbraid stellte Soldaten seiner Truppen ab, um Ausgrabungsleiter Whelgar zu begleiten und zu beschützen, als das zwergische Ausgrabungsteam tiefer in das gefährliche Sumpfland vordrang.",al={"whelgar longbraid","merrins brief"}}},fx={d54d2b61={q="Auf wessen Seite steht Langzopf der Grimmige?",a="Langzopf der Grimmige dient Eisenschmiede und der Allianz. Im nördlichen Sumpfland stationiert, befehligt er zwergische Streitkräfte, die versuchen, die Stellung gegen den Dunkeleisenclan zu halten, der Dun Modr besetzt und The Thandol Span beschädigt hat.",al={"langzopf fraktion","wem dient langzopf","langzopf allianz"}},["40b05609"]={q="Was will Langzopf der Grimmige?",a="Langzopf sucht Rache an den Dunkeleisenzwergen, die Dun Modr überrannt und seinen Bruder während des Angriffs auf The Thandol Span getötet haben. Er will ihre Streitkräfte zerschlagen und die Nordgrenze für Eisenschmiede sichern.",al={"langzopf der grimmige ziel","was will langzopf","langzopf beweggründe"}},["0c91256b"]={q="Warum ist Langzopf der Grimmige hier?",a="Langzopf lagert direkt vor Dun Modr im hohen Norden des Sumpflands, um die Ruinen zu überwachen und die Verteidigung zu koordinieren. Nach der brutalen Dunkeleisen-Invasion, die die Stadt und die Brücke zerstörte, bleibt er an der Front, um Gegenangriffe gegen den vordringenden Feind zu leiten.",al={"warum ist langzopf im sumpfland","warum ist langzopf vor dun modr","langzopf standort grund"}}},fp="18,280,14.492.0,16.312.0,26.184.0,35.189.0,26.205.0,53.161.0"}
P.entries["npc:lord-arkkoroc"] = {n="Lord Arkkoroc",s="Lord Arkkoroc ist ein uralter, gewaltiger Meeresriese, der in den Ruinen des Tempels von Arkkoran an der zerklüfteten Küste von Azshara weilt. Vom Dämonenjäger Loramus Thalipedes als niedere Gottheit beschrieben, gebietet er über die umliegenden Gewässer und befehligt niedere Meeresriesen, die als seine Söhne dienen.",h="Lord Arkkoroc ist ein uralter, gewaltiger Meeresriese, der in den Ruinen des Tempels von Arkkoran an der...",kw={"arkkoran","arkkoroc","azshara","hetaera","loramus","lord arkkoroc","meeresriese"},ang={["race:NightElf"]="Die Ruinen des Tempels von Arkkoran stehen auf einstigen Ländereien der Hochgeborenen, wo nun eine uralte Meeresentität über die gefallene Erhabenheit des alten Kalimdor herrscht."},sec={{t="Herr der Versunkenen Küste",b="Inmitten der salzverkrusteten Ruinen des Tempels von Arkkoran ruhend, ist Lord Arkkoroc weit mehr als ein gewöhnlicher Meeresriese. Für Einsiedler wie Loramus Thalipedes gilt dieses kolossale Wesen als niedere Gottheit, deren göttlicher Wille die umliegenden Gewässer formt. Seine Söhne patrouillieren durch die Klippen und Untiefen rund um das Heiligtum und setzen seine stille Herrschaft über Azsharas stürmische Küsten durch."},{t="Vergeltung gegen die Tiefe",b="Trotz seiner immensen göttlichen Macht erleidet Arkkoroc persönliche Verluste unter den Gezeiten. Eine furchterregende, vielköpfige Hydra namens Hetaera hat viele seiner Söhne entlang der Klippen gejagt und niedergemetzelt. Da er die Bestie nicht selbst jagen kann oder will, bietet Arkkoroc jedem umherziehenden Abenteurer wertvolles Wissen und okkulte Hilfe an, der stark genug ist, ihm die Köpfe des Mörders seiner Nachkommen zu bringen."}},faq={{q="Wer ist Lord Arkkoroc?",a="Lord Arkkoroc ist ein gewaltiger Meeresriese, der im Tempel von Arkkoran in Azshara residiert. Er wird als niedere Gottheit der Meere verehrt und herrscht über eine Brut von Meeresriesen, die er als seine Söhne betrachtet.",al={"wer ist arkkoroc","arkkoroc geschichte","tempel meeresriese"}},{q="Wo finde ich Lord Arkkoroc?",a="Ihr findet ihn inmitten der Ruinen des Tempels von Arkkoran an der östlichen Küste und den felsigen Riffen von Azshara.",al={"arkkoroc aufenthaltsort","wo ist arkkoroc","arkkoroc finden"}},{q="Warum schickt Loramus Thalipedes Abenteurer zu Arkkoroc?",a="Loramus Thalipedes schickt Reisende zu Arkkoroc, um arkane Erkenntnisse über einen mächtigen Dämon einzuholen. Als niedere Meeresgottheit verfügt Arkkoroc über uraltes Wissen, verlangt jedoch, dass Abenteurer die Hydra Hetaera erschlagen, bevor er seine Geheimnisse preisgibt.",al={"loramus arkkoroc quest","name der bestie"}},{q="Warum ist Arkkoroc zornig auf die Hydra Hetaera?",a="Die wilde Meeresbestie Hetaera hat mehrere von Arkkorocs Söhnen abgeschlachtet, die entlang der Küste patrouillierten. Um Rache für seine getöteten Nachkommen zu nehmen, fordert der Meeresriese ihre Köpfe.",al={"warum hetaera töten","arkkoroc hydra groll"}}},fp="13,294,24.378.0,26.398.1,21.195.0,31.129.0,57.247.0,45.170.0"}
P.entries["npc:lord-baurles-k-wishock"] = {n="Lord Baurles K. Wischock",s="Lord Baurles K. Wischock ist ein Adliger, der sich in der Petitioner's Chamber von Burg Sturmwind aufhält. Bei Barkeepern ist er für seine unbezahlten Rechnungen und seine Vorliebe für starke Getränke berüchtigt, doch in den Schatten der Stadt stieß er auf weitaus finsterere Machenschaften als bloße Trunkenheit.",h="Lord Baurles K.",kw={"baurles","house of nobles","petitioner's chamber","slaughtered lamb","burg sturmwind","wishock","zardeth"},ang={["class:Warlock"]="Wishocks neugierige Nachforschungen rund um das Gasthaus Zum Geschlachteten Lamm stellen eine unmittelbare Bedrohung für Sturmwinds Schattenzirkel dar, weshalb sein stilles Ableben für die praktizierenden Hexenmeister oberste Priorität hat.",["race:Human"]="Seine Anwesenheit in der Petitioner's Chamber spiegelt den dekadenten, eigennützigen Ruf des House of Nobles während der frühen Regentschaft des Knabenkönigs Anduin wider."},sec={{t="Die gefährliche Neugier eines Adligen",b="Inmitten der Bittsteller und Würdenträger in Burg Sturmwind hält Lord Baurles K. Wischock Hof, der ein Mitglied des einflussreichen House of Nobles ist. Trotz seines hohen Standes pflegte Wishock die Gewohnheit, die zwielichtigen Schänken des Magierviertels aufzusuchen – allen voran das Gasthaus Zum Geschlachteten Lamm –, wobei er beträchtliche unbezahlte Rechnungen hinterließ. Während er dort trank, bekam er jedoch Wind von dem Hexenmeisterzirkel, der in den Kellern unter den Dielen dunkle Künste praktizierte. Entschlossen, die Taverne schließen zu lassen, begann Wishock, bei anderen Adligen eine formelle Untersuchung zu erbitten – unwissend, dass das Aufdecken dämonischer Kulte in Sturmwind selten ungestraft bleibt."},{t="Ein vergifteter Becher",b="Wishocks Bemühungen rückten ihn direkt ins Visier der verborgenen Hexenmeister der Stadt. Anstatt eine königliche Überprüfung oder eine Untersuchung ihres unterirdischen Heiligtums zu riskieren, fädelte der Hexenmeister Zardeth der Schwarzen Klaue die heimliche Beseitigung des Adligen ein. Der Zirkel nutzte Wishocks berüchtigten Durst nach edlen Tropfen aus, braute ein tödliches Gebräu, das als feines Bier getarnt war, und arrangierte es so, dass ein angeheuerter Abenteurer das verhängnisvolle Getränk direkt vor den Augen der Wachen der Feste überbrachte."}},faq={{q="Wer ist Lord Baurles K. Wischock?",a="Lord Baurles K. Wischock ist ein dem House of Nobles angehörender Aristokrat. Er verbringt seine Tage in der Petitioner's Chamber in Burg Sturmwind, ist im Magierviertel jedoch dafür berüchtigt, hohe, unbezahlte Zechen anzuhäufen.",al={"baurles wishock","wer ist wishock","adliger bittsteller"}},{q="Wo ist Lord Wishock zu finden?",a="Er steht in der Petitioner's Chamber auf der Ostseite von Burg Sturmwind, umgeben von anderen Höflingen, Diplomaten und Bittstellern, die auf eine königliche Audienz warten.",al={"wishock aufenthaltsort","wo ist wishock","lord wishock finden"}},{q="Warum wollen die Hexenmeister unter dem Gasthaus Zum Geschlachteten Lamm seinen Tod?",a="Während seiner nächtlichen Zechtouren im Gasthaus Zum Geschlachteten Lamm erfuhr Wishock, dass ein Zirkel von Hexenmeistern unter der Taverne operierte. Er begann, beim House of Nobles für eine formelle Untersuchung und die Schließung des Etablissements zu werben, was die geheimen Aktivitäten der Hexenmeister auffliegen zu lassen drohte.",al={"warum wishock töten","zardeth wishock","warum wishock vergiften"}},{q="Wie wird er ermordet?",a="Zardeth der Schwarzen Klaue braut ein tödliches Gift und tarnt es als erlesenes Getränk. Da Wishocks Schwäche für feinen Alkohol und Freibier bekannt ist, überbringt ihm ein Agent das vergiftete Fässchen direkt in Burg Sturmwind.",al={"wie stirbt wishock","wishock gift","ein nobles bräu"}}},fx={["255656dc"]={q="Auf wessen Seite steht Lord Baurles K. Wischock?",a="Lord Wischock dient dem Königreich Sturmwind als sitzendes Mitglied des Hauses der Adligen. Er operiert strikt innerhalb der königlichen Aristokratie und nutzt seinen politischen Einfluss, um die bürgerliche und adlige Autorität gegen subversive Elemente zu verteidigen, die sich innerhalb der Stadtgrenzen verbergen.",al={"lord wischock seite","lord wischock fraktion","wem dient wischock"}},["59c1fa27"]={q="Was will Lord Baurles K. Wischock?",a="Lord Wischock ist entschlossen, den dunklen Zirkel, der im Keller unter dem The Slaughtered Lamb operiert, aufzudecken und zu zerschlagen. Nachdem er ihre abscheulichen Riten entdeckt hat, setzt er sich bei seinen Kollegen im Haus der Adligen aktiv dafür ein, eine umfassende offizielle Untersuchung der Taverne einzuleiten und die Hexenmeister aus Sturmwind zu vertreiben.",al={"wischock ziel","was will wischock","lord wischock plan"}},["3d37be28"]={q="Warum befindet sich Lord Baurles K. Wischock in Burg Sturmwind?",a="Ihr findet Lord Wischock in der Petitioner's Chamber innerhalb von Burg Sturmwind, wo er seinen adligen Pflichten nachgeht. Als Mitglied des Hauses der Adligen hält er sich häufig in der Burg auf, um sich mit anderen Lords zu beraten und Petitionen an den königlichen Hof zu richten.",al={"warum ist wischock in burg sturmwind","warum ist lord wischock hier","wischock petitioners chamber"}},["83d2fff3"]={q="Mit wem ist Lord Baurles K. Wischock verbunden?",a="Lord Wischock gehört dem Haus der Adligen an, der einflussreichen Regierungsversammlung von Sturmwinds Aristokratie. Außerhalb des Hofes war er ein regelmäßiger Gast im The Slaughtered Lamb im Magierviertel – wo er eine enorme unbezahlte Rechnung anhäufte, bevor er den Hexenmeister-Zirkel entdeckte, der in dessen verborgenen Krypten dunkle Künste praktizierte.",al={"wischock verbindungen","lord wischock beziehungen","wischock haus der adligen"}}},fp="23,241,32.635.0,14.479.1,31.233.0,32.179.0,63.276.1,23.222.1"}
P.entries["npc:lord-cobrahn"] = {fx={["3feb6d50"]={q="Auf wessen Seite steht Lord Kobrahn?",a="Lord Kobrahn dient den Druiden des Giftzahns und dem sich ausbreitenden Albtraum innerhalb der Höhlen des Wehklagens. Er hat alle Loyalität gegenüber dem Zirkel des Cenarius und dem Volk der Nachtelfen aufgegeben und steht an der Seite von Naralex' gefallenen Schülern gegen jeden, der es wagt, einzudringen, um die Verderbnis zu reinigen.",al={"kobrahn fraktion","wem dient kobrahn","lord kobrahn loyalitäten"}}}}
P.entries["npc:lord-ello-ebonlocke"] = {n="Lord Ello Schwarzhaupt",s="Lord Ello Schwarzhaupt ist der Bürgermeister von Dunkelhain und das Oberhaupt seines Stadtrates, stationiert im Rathaus von Dunkelhain. Umgeben von Dunkelheit und schleichendem Grauen kämpft er täglich darum, die Ordnung aufrechtzuerhalten und seine belagerten Bürger zu beschützen, obwohl er kaum Hilfe aus Sturmwind erhält.",h="Lord Ello Schwarzhaupt ist der Bürgermeister von Dunkelhain und das Oberhaupt seines Stadtrates, stationiert...",kw={"calvinius","althea","rat","dunkelhain","dämmerwald","ebonlocke","ello","seenhain","bürgermeister"},ang={["faction:Alliance"]="Lord Schwarzhaupt steht für die vergessenen Grenzlande der Allianz, in denen isolierte Bürgermeister ihr Volk ohne kaiserliche Unterstützung durch albtraumhafte Zustände führen müssen.",["race:Human"]="Für Menschen, die aus Sturmwind anreisen, ist das Gespräch mit Lord Schwarzhaupt eine ernüchternde Erinnerung daran, wie tief die südlichen Provinzen in Ruin und Verlassenheit gestürzt sind."},sec={{t="Ein bedrängter Bürgermeister",b="In der Düsternis des Rathauses von Dunkelhain trägt Lord Ello Schwarzhaupt die schwere Bürde, eine Siedlung am Rande des Ruins zu regieren. Einst Teil der wohlhabenden ländlichen Zuflucht namens Grand Hamlet, ist Dunkelhain nun in ewigen Schatten gehüllt und wird von unersättlichen Ghulen, untoten Monstrositäten und wilden Bestien belagert. Ello führt den Vorsitz über den Rat von Dunkelhain und müht sich gegen aussichtslose Chancen ab, die Reste der Zivilisation aufrechtzuerhalten, während Sturmwind vor ihrer Notlage die Augen verschließt."},{t="Eine geteilte Grenze",b="Da die Garnison von Sturmwind sich weigert, Soldaten für die Grenzlande abzustellen, ist Dunkelhain fast gänzlich auf einheimische Freiwilligenmilizen wie die Nachtwache angewiesen, die von seiner Verwandten Althea Schwarzhaupt befehligt wird. Wenn benachbarte Anführer wie Magistrat Solomon aus Seenhain um Verstärkung im Kampf gegen die Schwarzfelsorcs flehen, muss Lord Schwarzhaupt quälende Entscheidungen treffen. Wie er Boten aus dem Rotkammgebirge feierlich erklärt, kann Dunkelhain keine einzige Klinge entbehren: Würden die Wachen über den Waldrand hinaus entsandt, fielen die eigenen Heime augenblicklich dem umgebenden Unheil anheim."},{t="Blind für die Pläne des Einsiedlers",b="Neben dem Patrouillieren der Straßen verlässt sich Lord Schwarzhaupt häufig auf umherziehende Abenteurer, um sich um merkwürdige Vorkommnisse in den Wäldern zu kümmern. In seinem aufrichtigen Wunsch, allen Bewohnern des Dämmerwalds beizustehen, koordiniert er die Kommunikation mit einsamen Gestalten wie dem Einsiedler Calvinius. Bedauerlicherweise sorgt Schwarzhaupts Mangel an echtem Verständnis für die kryptischen Schriften des Einsiedlers dafür, dass er für den grauenhaften, zusammengenähten Albtraum blind bleibt, der sich knapp hinter den Stadtgrenzen zusammenbraut – bis es beinahe zu spät ist."}},faq={{q="Wer ist Lord Ello Schwarzhaupt?",a="Lord Ello Schwarzhaupt ist der Bürgermeister von Dunkelhain und das Oberhaupt des Rates von Dunkelhain. Von seinem Sitz im Rathaus aus wacht er über die Verteidigung, die zivilen Angelegenheiten und das Überleben der verbliebenen menschlichen Bevölkerung des Dämmerwalds.",al={"wer ist ello","bürgermeister von dunkelhain","ello ebonlocke lore"}},{q="In welcher Beziehung steht er zu Kommandantin Althea Schwarzhaupt?",a="Kommandantin Althea Schwarzhaupt, die unerschütterliche Anführerin der Nachtwache, ist eine nahe Verwandte von Lord Ello. Während er die zivilen und diplomatischen Belange von Dunkelhain lenkt, befehligt sie die Miliz, die die Siedlung aktiv beschützt.",al={"althea schwarzhaupt verwandtschaft","ist althea ellos tochter"}},{q="Warum weigert sich Lord Schwarzhaupt, Truppen nach Seenhain zu entsenden?",a="Als Magistrat Solomon um Hilfe gegen die Schwarzfelsorcs im Rotkammgebirge bittet, ist Lord Schwarzhaupt gezwungen abzulehnen. Dunkelhain wird von Untoten und Ungeheuern so stark bedrängt, dass das Abziehen von Wachen die Stadt völlig überrennen ließe, noch bevor die Miliz überhaupt die Waldgrenze erreicht hätte.",al={"warum keine hilfe für rotkamm","botschaft nach dunkelhain","magistrat solomon ello ebonlocke"}},{q="Wo ist Lord Ello Schwarzhaupt zu finden?",a="Er befindet sich im Rathaus von Dunkelhain, das im Zentrum von Dunkelhain im östlichen Dämmerwald steht.",al={"ello ebonlocke standort","wo ist bürgermeister ebonlocke"}},{q="Warum sendet Sturmwind keine Truppen, um Lord Schwarzhaupt zu helfen?",a="Sturmwind ist nach dem Verschwinden von König Varian Wrynn in interne politische Konflikte verstrickt. Angesichts der knappen Ressourcen des Königreichs hat das Adelsgeschlecht die südlichen Regionen weitgehend im Stich gelassen, was lokale Anführer wie Lord Schwarzhaupt dazu zwingt, ihre Verteidigung selbst zu organisieren.",al={"warum hilft sturmwind dämmerwald nicht","vernachlässigung durch sturmwind"}},{q="Welche Verbindung hat Lord Schwarzhaupt zu Calvinius?",a="Lord Schwarzhaupt hilft bei der Kommunikation mit dem Einsiedler Calvinius und veranlasst die Übersetzung sonderbarer Notizen.",al={"ello calvinius notiz","übersetzung von calvinius' notiz"}}},fx={["0007fc63"]={q="Auf wessen Seite steht Lord Ello Schwarzhaupt?",a="Lord Ello Schwarzhaupt ist der Große Allianz loyal ergeben und dient als Bürgermeister von Dunkelhain, wo er den Stadtrat leitet. Obwohl er dem Königreich Sturmwind verpflichtet ist, muss er das Überleben seiner eigenen verängstigten Bürger über breitere regionale Hilferufe stellen.",al={"lord schwarzhaupt fraktion","wem dient ello schwarzhaupt","ist schwarzhaupt allianz"}},["48b49947"]={q="Was will Lord Ello Schwarzhaupt?",a="Bürgermeister Schwarzhaupt will vor allem verhindern, dass die bedrängte Stadt Dunkelhain der heraufziehenden Finsternis zum Opfer fällt. Von der Krone im Stich gelassen, liegt sein einziger Fokus darauf, sein Volk zu beschützen und die örtliche Nachtwache gegen die umliegenden Schrecken einsatzbereit zu halten.",al={"was will lord ello","schwarzhaupt ziel","ello schwarzhaupt zweck"}},["26db90ba"]={q="Warum ist Lord Ello Schwarzhaupt in Dunkelhain?",a="Lord Schwarzhaupt leitet Dunkelhain vom Rathaus aus, da er das Oberhaupt des Rats von Dunkelhain ist. Als ziviler Anführer des letzten überlebenden Bollwerks der Zivilisation im Dämmerwald überwacht er die lokale Verteidigung und Verwaltung aus dem Herzen der Siedlung heraus.",al={"warum ist lord schwarzhaupt im dämmerwald","warum ist schwarzhaupt in dunkelhain","ello schwarzhaupt standort grund"}}},fp="19,289,19.500.0,18.576.0,29.465.1,27.208.0,48.218.0,59.294.0,39.106.0,57.276.0,54.125.1"}
P.entries["npc:lord-grayson-shadowbreaker"] = {fx={["2db8c97e"]={q="Auf wessen Seite steht Lord Grayson Schattenbruch?",a="Lord Grayson steht fest an der Seite der Großen Allianz, des Königreichs Sturmwind und des Ordens der Silbernen Hand. Er widmet sich voll und ganz das Heilige Licht und der Verteidigung der Lebenden gegen die Geißel und andere dunkle Bedrohungen.",al={"grayson schattenbruch fraktion","wem dient grayson","ist grayson allianz"}},["88e74201"]={q="Was will Lord Grayson Schattenbruch?",a="Lord Grayson versucht, die nächste Generation heiliger Krieger zu schmieden, um die Finsternis zurückzudrängen, die Azeroth verschlingt. Er testet Paladine durch beschwerliche geistige und kampfbezogene Prüfungen, schickt sie aus, um die Geißel in den Pestländern zu bekämpfen, und beweist ihre Würdigkeit, ein gesegnetes Streitross zu erhalten.",al={"grayson schattenbruch ziele","was will grayson","grayson motiv"}},a5a2c568={q="Warum ist Lord Grayson Schattenbruch in der Kathedrale des Lichts?",a="Er ist innerhalb der Kathedrale des Lichts von Sturmwind stationiert, um die Entwicklung der Paladine der Stadt zu beaufsichtigen. Von diesem zentralen Bollwerk des Glaubens aus koordiniert er Missionen gegen die Geißel und leitet hochrangige Champions durch die anspruchsvollen Prüfungen, die erforderlich sind, um ihre heiligen Schlachtrösser zu beschwören.",al={"warum ist grayson in sturmwind","warum ist grayson hier","grayson kathedrale des lichts"}},c41cec02={q="Mit wem ist Lord Grayson Schattenbruch verbunden?",a="Schattenbruch arbeitet eng mit Hohepriester Rohan von Eisenschmiede, dem Schmied Grimand Elmore und Befehlshabern zusammen, die im Norden gegen die Geißel kämpfen, wie zum Beispiel Ashlam Valorfist.",al={"verbündete von grayson schattenbruch","wen kennt grayson","knappen von grayson"}}}}
P.entries["npc:lord-jorach-ravenholdt"] = {n="Lord Jorach Rabenholdt",s="Lord Jorach Rabenholdt ist das Oberhaupt von Rabenholdt, einer Elitegilde von Schurken und Attentätern, die von einem abgelegenen Anwesen im Alteracgebirge aus operiert. Er leitet die geheimen Operationen des Bundes, bildet vielversprechende Agenten aus und führt einen erbitterten Krieg gegen die regionalen Banditen des Syndikats.",h="Lord Jorach Rabenholdt ist das Oberhaupt von Rabenholdt, einer Elitegilde von Schurken und Attentätern, die...",kw={"alterac","assassin's league","azurblauer schlüssel","jorach","rabenholdt","schurke","syndikat","xylem"},ang={["class:Rogue"]="Lord Rabenholdt ist der bedeutendste Schutzpatron für Meisterschurken in ganz Azeroth und bietet Eliteausbildung, Gifte und prestigeträchtige Aufträge für jene, die sein Vertrauen gewinnen."},sec={{t="Meister der Assassin's League",b="Lord Jorach Rabenholdt herrscht über die Assassin's League von seinem verborgenen Anwesen aus, das in den zerklüfteten Felsen zwischen Alterac und Hillsbrad liegt. Als Adliger von geheimnisvoller Abstammung öffnet er seine Hallen für Gesetzlose, Beutelschneider und Attentäter ungeachtet ihrer Zugehörigkeit, sofern sie außergewöhnliches Geschick an den Tag legen und seine Autorität respektieren. Unter seinem Befehl fungiert der Bund sowohl als Bruderschaft für Meisterdiebe als auch als unabhängiges Syndikat für Auftragsmorde und Spionage. Rabenholdt hegt einen tiefen Hass auf das Syndikat – die Schar in Ungnade gefallener Alterac-Adliger, die zu Gesetzlosen wurden – und beauftragt seine Untergebenen sowie reisende Freiberufler regelmäßig damit, deren Lager zu sabotieren und ihre Vorräte zu plündern."},{t="Geheimnisse in den Schatten",b="Während er scheinbar mit lokalen Scharmützeln beschäftigt ist, leitet Lord Rabenholdt weitreichende Operationen in ganz Azeroth. Schurken, die ihre Loyalität unter Beweis stellen, werden für knifflige, kontinentübergreifende Aufgaben rekrutiert, um wohlbehütete Artefakte zu beschaffen. Darunter war die Bergung einer geheimnisvollen Versiegelten azurblauen Tasche, die ihm gestohlen und zu Furbolgs nach Azshara gebracht worden war; dies erforderte die arkane Entschlüsselung durch Erzmagier Xylem und einen Azurblauen Schlüssel, der dem Versunkenen Tempel entrissen werden musste. Rabenholdt koordiniert zudem die Entwicklung tödlicher neuer Substanzen und entsendet seine Späher, um tödliches Gift von uralten Schrecken im gesamten Reich zu sammeln."}},faq={{q="Wer ist Lord Jorach Rabenholdt?",a="Er ist der aristokratische Anführer der Assassin's League, einer geheimen Vereinigung von Schurken mit Hauptsitz im Rabenholdtanwesen in den Bergen über dem Vorgebirge des Hügellands. Er bildet Meister der Tarnung aus und koordiniert diskrete Attentate sowie das Beschaffen von Informationen.",al={"wer ist jorach","rabenholdt anführer","jorach lore"}},{q="Warum hasst Rabenholdt das Syndikat?",a="Rabenholdts Anwesen liegt direkt in einem vom Syndikat beanspruchten Gebiet – einem Netzwerk ehemaliger Alterac-Adliger, die zu skrupellosen Gesetzlosen wurden. Er betrachtet ihr primitives Banditentum als Seuche im Hochland und setzt die Attentäter seiner Gilde aktiv ein, um deren Hochburgen zu säubern.",al={"warum syndikat feind","rabenholdt gegen syndikat","syndikat rivalität"}},{q="Gehört Lord Rabenholdt zur Allianz oder zur Horde?",a="Rabenholdt agiert streng als unabhängige Organisation. Lord Jorach empfängt sowohl Schurken der Allianz als auch der Horde auf seinem Anwesen; ihm geht es einzig um professionelles Können, Disziplin im Verborgenen und absolute Diskretion, nicht um Völkerpolitik.",al={"ist rabenholdt allianz","ist jorach horde","rabenholdt fraktion"}},{q="Was befindet sich in der Versiegelten azurblauen Tasche, nach der Jorach sucht?",a="Der Inhalt bleibt ein streng gehütetes Geheimnis. Als ihm der Azurblaue Schlüssel überreicht wurde, um den verzauberten Beutel endlich zu öffnen, wurde Lord Jorach von einem unheimlichen goldenen Licht umhüllt; er starrte voller Erstaunen hinein, bevor er ihn rasch verstaute.",al={"versiegelte azurblaue tasche inhalt","azurblaue tasche geheimnis","was hat jorach bekommen"}}},fp="22,302,31.670.0,22.600.1,30.264.0,39.273.0,57.249.0,49.237.1"}
P.entries["npc:lord-pythas"] = {fx={be91010a={q="Auf wessen Seite steht Lord Pythas?",a="Lord Pythas dient den Leaders of the Fang. Einst ein ergebener Beschützer und Akolyth von Naralex, hat der Alptraum Besitz von seinem Verstand ergriffen und seine Loyalität verzerrt. Nun steht er fest auf der Seite dieser abtrünnigen Sekte und setzt seine Klinge sowie Naturmagie ein, um den Alptraum zu beschützen, anstatt den Meister zu verteidigen, den er einst zu beschützen schwor.",al={"fraktion von pythas","allianz von pythas","wem dient pythas"}},a058df7c={q="Was will Lord Pythas?",a="Vom Alptraum, der Naralex' Schlaf infiziert hat, in den Wahnsinn getrieben, versucht Pythas, Die Höhlen des Wehklagens vor jedem zu verteidigen, der sie reinigen will. Seines Verstandes beraubt, wünscht er sich nur, Eindringlinge zu vernichten, die den Griff des Alptraums bedrohen, und richtet seine kriegerische Disziplin und druidische Macht vollständig darauf aus, die korrumpierte Domäne zu bewahren.",al={"ziele von pythas","was versucht pythas zu tun","motive von pythas"}},eb0bbb13={q="Warum wird Lord Pythas gefürchtet?",a="Lord Pythas gilt als der furchterregendste der Leaders of the Fang. Im Gegensatz zu vielen Akolythen, die sich nur auf Naturzauber verlassen, war Pythas ein erfahrener Krieger, bevor er Druide wurde. Seine Kombination aus tödlicher Nahkampfkraft, schierer physischer Widerstandsfähigkeit und dunkler druidischer Magie macht ihn für jede Expedition außerordentlich gefährlich.",al={"ist pythas gefährlich","warum ist pythas stark","stärke von pythas"}}}}
P.entries["npc:lord-serpentis"] = {n="Lord Serpentis",s="Lord Serpentis ist ein korrumpierter Nachtelfendruide, der als einer der vier Anführer der abtrünnigen Druiden des Giftzahns in den Höhlen des Wehklagens weilt. Einst ein Druide von großer Macht und hohem Ansehen im Orden von Naralex, verfiel er dem Wahnsinn, als Naralex' Traum in den unterirdischen Quellen zu einem Albtraum wurde. Nun befehligt er die Schlangen verehrende Sekte tief in den Höhlen, wo der korrumpierte Naralex im Schlummer liegt.",h="Lord Serpentis ist ein korrumpierter Nachtelfendruide, der als einer der vier Anführer der abtrünnigen...",kw={"druiden des giftzahns","edelstein von serpentis","anführer der giftzähne","lord serpentis","naralex","serpentis","die höhlen des wehklagens"},ang={["class:Druid"]="Serpentis verkörpert die tragische Gefahr, die im Smaragdgrünen Traum lauert, und veranschaulicht, wie selbst ein Druide von großer Macht verzerrt werden kann, wenn eine edle Vision zum Albtraum wird.",["race:NightElf"]="Für Nachtelfen sind Serpentis und seine Anhänger eine schmerzhafte Schande – Gelehrte der Kaldorei von großem Renommee, die ihre heilige Pflicht gegenüber der Natur wegwarfen, um zu monströsen Schlangenlords zu werden.",["race:Tauren"]="Tauren sehen in der Verderbnis von Serpentis eine abscheuliche Entweihung des Gleichgewichts der Erdenmutter, die das empfindliche Ökosystem des Brachlands mit unnatürlichem Wahnsinn bedroht."},sec={{t="Vom edlen Druiden zum Schlangenlord",b="Bevor die Finsternis die Quellen der Höhle einnahm, war Serpentis ein Druide von großer Macht und hohem Ansehen, Teil des edlen Ordens unter der Führung von Naralex, der hoffte, die Quellen der Höhlen und den Smaragdgrünen Traum zu nutzen, um das Brachland zu heilen. Doch als Naralex' Vision zu einem verderblichen Albtraum wurde, gehörte Serpentis zu den Druiden, deren Geist dem aufkeimenden Wahnsinn anheimfiel."},{t="Ein Lord der Giftzähne",b="Der Verderbnis, die von Naralex' verzerrten Träumen ausging, gänzlich erlegen, wurden Serpentis und seine Druidengefährten zu den Druiden des Giftzahns. Sie sagten sich vom traditionellen cenarischen Gleichgewicht und den Totemtieren vergangener Tage los und trachten nun danach, das Brachland nach ihren eigenen verzerrten Träumen umzugestalten, anstatt es zu heilen. Serpentis herrscht über die Sekte als einer ihrer vier Anführer, an der Seite von Lady Anakondra, Lord Kobrahn und Lord Pythas."},{t="Das letzte Hindernis",b="Tief in den verwinkelten Höhlen thronend, ist Lord Serpentis einer der vier Anführer der abtrünnigen Sekte, von denen jeder einen Traumedelstein bei sich trägt. Jene, die den gefangenen Meister erwecken oder die Gewässer der Oase zurückfordern wollen, müssen Serpentis niederstrecken und den Edelstein an sich bringen, den er trägt, um den Griff der Schlange über das Labyrinth zu brechen."}},faq={{q="Wer ist Lord Serpentis?",a="Lord Serpentis ist einer der vier Anführer der Druiden des Giftzahns tief in den Höhlen des Wehklagens. Einst ein Nachtelfendruide von großer Macht und hohem Ansehen in Naralex' Orden, wurde er zusammen mit seinen Druidengefährten von Naralex' Albtraum korrumpiert.",al={"wer ist serpentis","lord serpentis lore","serpentis hintergrund"}},{q="Warum wurde Serpentis böse?",a="Als Naralex' Versuch, das Brachland durch den Smaragdgrünen Traum zu heilen, in einen Albtraum umschlug, griff seine Verderbnis auf die Druiden über, die ihm folgten, und trieb Serpentis' Geist in den Wahnsinn und die Schlangenverehrung.",al={"warum serpentis böse wurde","serpentis verderbnis","warum serpentis böse ist"}},{q="Was ist seine Beziehung zu Naralex?",a="Serpentis war einst einer der edlen Druiden, die Naralex in die Höhlen folgten. Anstatt seinem Meister bei der Genesung beizustehen, wurde er zu einem Anführer der Druiden des Giftzahns, die nun versuchen, das Brachland nach ihren eigenen verzerrten Träumen umzugestalten.",al={"serpentis und naralex","ist serpentis mit naralex verwandt","naralex lehrling"}},{q="Warum müssen Spieler ihn töten?",a="Serpentis ist einer der vier Anführer der Druiden des Giftzahns. Ihn zu beseitigen ist unerlässlich, um die Herrschaft der Sekte über die Höhlen des Wehklagens zu brechen, sich seinen Edelstein für die Quest Anführer der Giftzähne zu sichern und einen Pfad zur Erweckung von Naralex freizumachen.",al={"warum serpentis töten","anführer der giftzähne serpentis","edelstein von serpentis"}},{q="Wer sind die Druiden des Giftzahns?",a="Sie sind eine abtrünnige Fraktion von Nachtelfendruiden, die Naralex in die Höhlen des Wehklagens folgten. Vom Smaragdgrünen Albtraum korrumpiert, gaben sie die traditionellen druidischen Gestalten auf, um unter dem Befehl von Serpentis und ihren anderen Giftzahnfürsten die Aspekte, Gifte und Verhaltensweisen von Schlangen anzunehmen.",al={"druiden des giftzahns lore","was sind druiden des giftzahns","giftzahndruiden"}}},fx={["1f07cf4d"]={q="Auf wessen Seite steht Lord Serpentis?",a="Lord Serpentis ist der Anführer der Druiden des Giftzahns. Korrumpiert durch den Alptraum, der seinen Mentor Naralex verzehrt, hat er den Zirkel des Cenarius und die Ideale der Nachtelfen aufgegeben und ist allen gegenüber, die die Höhlen betreten, vollkommen feindselig eingestellt.",al={"fraktion von lord serpentis","wem dient serpentis","loyalität von serpentis"}}},fp="14,426,32.350.0,18.412.0,18.316.1,22.250.0,28.208.0,36.242.0,32.234.0,31.285.0"}
P.entries["npc:lord-shalzaru"] = {n="Lord Shalzaru",s="Lord Shalzaru ist der tyrannische Anführer der Naga der Hatecrest, die von der Insel des Schreckens vor der Küste von Feralas aus operieren. Er herrscht mit absoluter Grausamkeit über seine schlangenartigen Anhänger und beaufsichtigt umfangreiche Ausgrabungen inmitten der versunkenen und verfallenen elfischen Siedlungen. Seine jüngste Entdeckung eines seltsamen, uralten Relikts hat die Aufmerksamkeit außenstehender Ermittler geweckt, die es ihm unbedingt entreißen wollen.",h="Lord Shalzaru ist der tyrannische Anführer der Naga der Hatecrest, die von der Insel des Schreckens vor der...",kw={"feralas","hatecrest","die insel des schreckens","lord shalzaru","geheimnisvolles relikt","naga","shalzaru"},ang={["faction:Alliance"]="Die Sicherung von Shalzarus Relikt und das Neutralisieren des Kriegsfürsten der Hatecrest trägt dazu bei, die abgelegenen Vorposten der Allianz an der ungezähmten Küste von Feralas zu schützen.",["faction:Horde"]="Späher der Horde haben ein wachsames Auge auf Bedrohungen an der Küste von Feralas, und das Niederschlagen des Nagafürsten beseitigt eine unberechenbare Gefahr nahe der Interessensphäre von Camp Mojache.",["race:NightElf"]="Die Naga der Hatecrest entweihen die antiken Ruinen des alten Kalimdor; das Zurückholen von Relikten von Shalzaru verhindert, dass das dunkle Erbe der Hochgeborenen seine schlangenartige Sippe stärkt."},sec={{t="Meister der Hatecrest",b="Lord Shalzaru befehligt die Naga der Hatecrest und lenkt deren Präsenz entlang der Südküste von Feralas. Aus seinem unterirdischen Unterschlupf in einer Höhle auf der Insel des Schreckens setzt er seine Herrschaft mit Grausamkeit und unbarmherziger Autorität durch. Unter seinem Befehl durchkämmen die Hatecrest die antiken Ruinen des alten Kalimdor auf der Suche nach vergessenen Schätzen und mächtigen Relikten, die von der Zerschlagung zurückgeblieben sind."},{t="Das geheimnisvolle Relikt",b="Bei Ausgrabungen südlich der primären Ruinen auf der Insel des Schreckens barg Shalzaru persönlich ein seltsames, uraltes Relikt. Zweck und Macht dieses Artefakts bleiben ein Rätsel, doch seine Bergung durch einen solch mächtigen Kriegsfürsten der Naga stellt eine eindeutige Bedrohung dar. Ermittler auf dem Festland suchen tapfere Streiter, die sich in die Schlangenhöhle wagen, Shalzarus Herrschaft beenden und das sonderbare Relikt sichern, bevor die Hatecrest es für dunklere Zwecke nutzen können."}},faq={{q="Wer ist Lord Shalzaru?",a="Lord Shalzaru ist der grausame königliche Anführer der Naga der Hatecrest. Er beaufsichtigt die Streitkräfte und Ausgrabungen der Naga auf der Insel des Schreckens vor der Küste von Feralas.",al={"lord shalzaru lore","shalzaru","wer ist shalzaru"}},{q="Wo ist Lord Shalzaru zu finden?",a="Er haust in einer Höhle südlich der elfischen Hauptruinen jenseits des Wassers auf der Insel des Schreckens, vor der südwestlichen Küste von Feralas.",al={"shalzaru standort","wo ist lord shalzaru","insel des schreckens höhle"}},{q="Wer sind die Hatecrest?",a="Die Hatecrest sind ein feindseliger Stamm von Naga, der die Küstenlinie und Inseln von Feralas besetzt und dafür bekannt ist, unter Shalzarus Befehl antike Ruinen zu durchkämmen und die Küstengewässer zu terrorisieren.",al={"hatecrest naga","hatecrest stamm"}},{q="Welches Relikt besitzt Lord Shalzaru?",a="Bei einer kürzlichen Ausgrabung auf der Insel des Schreckens legte Shalzaru ein geheimnisvolles, uraltes Relikt unbekannter Herkunft und Macht frei, was Fraktionen des Festlands dazu veranlasste, Abenteurer auszusenden, um es einzufordern.",al={"shalzaru relikt","geheimnisvolles relikt feralas"}},{q="Warum muss Lord Shalzaru bezwungen werden?",a="Die Ausschaltung von Shalzaru bricht die Führung der Hatecrest auf der Insel des Schreckens und erlaubt es Abenteurern, das geheimnisvolle Relikt zu bergen, das er kürzlich ausgegraben hat, bevor die Naga es sich zunutze machen können.",al={"gegen lord shalzaru","lord shalzaru töten"}},{q="Wonach graben die Hatecrest in Feralas?",a="Die Hatecrest graben in den zerstörten Siedlungen der Nachtelfen, die während der Großen Zerschlagung zertrümmert wurden, und suchen nach mächtigen magischen Relikten und Überresten der Geschichte der Hochgeborenen, die unter der Erde und den Wellen verborgen liegen.",al={"hatecrest ausgrabung","warum sind naga in feralas"}}},fp="13,392,23.394.0,20.439.0,21.159.0,33.135.0,22.183.0,38.189.0,35.182.0,46.194.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="Hüter des Wissens Raintotem",s="Hüter des Wissens Raintotem ist ein Ältester der Tauren, der im nördlichen Mulgore direkt südlich der Teufelsfelsen stationiert ist. Er kümmert sich um die heiligen Begräbnisstätten und bittet Abenteurer, die dort störenden Stachelborstenquillboar zu vertreiben.",h="Hüter des Wissens Raintotem ist ein Ältester der Tauren, der im nördlichen Mulgore direkt südlich der...",kw={"hüter des wissens raintotem","mulgore","raintotem","teufelsfelsen","heilige bestattung"},ang={["class:Shaman"]="Raintotems Wachsamkeit über die ruhelosen Toten an den Teufelsfelsen betrifft direkt schamanische Pflichten und stellt sicher, dass die Geister der Ahnen den gebührenden Frieden und Respekt erhalten.",["race:Tauren"]="Raintotem bei der Verteidigung der Teufelsfelsen zu helfen, ehrt die Ahnen und bewahrt die Begräbnistraditionen Eures Volkes."},sec={{t="Wächter der Teufelsfelsen",b="Nahe den heiligen Klippen der Teufelsfelsen in Mulgore stationiert, kümmert sich Hüter des Wissens Raintotem um die spirituellen Verpflichtungen seines Volkes. Er bittet Abenteurer, die Stachelborsten-Eindringlinge von der Begräbnisstätte zu vertreiben und den Frieden an der Ruhestätte der Ahnen wiederherzustellen."},{t="Verteidiger der Ahnenstätten",b="Über das Prüfen junger Helden hinaus wacht Hüter des Wissens Raintotem über die heiligen Begräbnisstätten bei den Teufelsfelsen. Wenn Stachelborstenquillboar die geweihten Ruhestätten verstorbener Taurenhäuptlinge und Schamanen stören, rekrutiert Raintotem Reisende, um die Würde wiederherzustellen und die gestörten Toten zu beruhigen."}},faq={{q="Wo finde ich Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem ist im nördlichen Mulgore stationiert, direkt südlich der Teufelsfelsen an dem Pfad gelegen, der zu den Ahnenklippen hinaufführt.",al={"standort raintotem","wo ist hüter des wissens raintotem","raintotem mulgore finden"}},{q="Warum bittet Raintotem um Hilfe bei den Begräbnisstätten?",a="Er bittet Abenteurer, die Stachelborsten-Eindringlinge von den Teufelsfelsen zu vertreiben, wo die Quillboar die heilige Begräbnisstätte der Tauren verwüsten.",al={"raintotem heilige bestattung","warum raintotem helfen","teufelsfelsen begräbnisstätten"}},{q="Warum benötigt Raintotem Hilfe bei den Teufelsfelsen?",a="Die Teufelsfelsen dienen als heilige Begräbnisstätte der Tauren, doch Stachelborsten-Eindringlinge verwüsten den Friedhof. Raintotem beauftragt fähige Abenteurer damit, die entweihten Ahnenstätten wieder in Ordnung zu bringen.",al={"problem teufelsfelsen","warum quest heilige bestattung"}}},fx={["4ada6d87"]={q="Wer ist Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem dient seiner Tauren-Gemeinschaft, bewahrt die Traditionen der Ahnen und stellt sicher, dass die Gefallenen ein heiliges Begräbnis erhalten.",al={"wer ist raintotem","infos zu hüter des wissens raintotem","über raintotem"}},["29f679b7"]={q="Auf wessen Seite steht Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem ist den Tauren-Stämmen von Mulgore und der Horde unter Hochhäuptling Cairne Bluthuf vollkommen loyal. Er dient als geehrter kultureller Ältester und unterstützt jeden Abenteurer der Horde, der Respekt vor den heiligen Riten und den Ahnen seines Volkes zeigt.",al={"fraktion von raintotem","gehört raintotem zur horde","loyalität von raintotem"}},["6a12fd3c"]={q="Warum ist Hüter des Wissens Raintotem hier?",a="Raintotem hält südlich der Teufelsfelsen Wache, da dies die heilige Ahnenbegräbnisstätte der Tauren-Stämme ist. Er bleibt in der Nähe stationiert, um das geheiligte Land zu schützen, Pilger zu führen, die den Segen der Ahnen suchen, und Bedrohungen entgegenzutreten, die die Geister stören, welche innerhalb der roten Felsenklippen ruhen.",al={"warum ist raintotem bei den teufelsfelsen","grund für raintotems aufenthaltsort","warum ist hüter des wissens raintotem in mulgore"}},["88640b34"]={q="Was will Hüter des Wissens Raintotem?",a="Er kümmert sich um die Ahnenbegräbnisstätten bei den Teufelsfelsen und bittet Abenteurer, die Borstennacken-Eindringlinge zu vertreiben, die dort stören.",al={"was will raintotem","ziele von raintotem","worum bittet raintotem"}}},fp="20,207,20.255.0,29.302.0,38.141.0,53.133.0,42.213.0"}
P.entries["npc:lorgus-jett"] = {n="Lorgus Jett",s="Lorgus Jett ist ein menschliches Mitglied des Kults des Schattenhammers, das in den überfluteten Korridoren der Tiefschwarzen Grotte operiert. Während er die Moonshrine Ruins durchstreift, dient er als skrupelloser Kommandant im Dienste des Kults für die Alten Götter. Anführer der Horde haben ihn als vorrangiges Ziel auserkoren, um die vordringende Präsenz des Kults entlang der Küste des Eschentals zu zerschlagen.",h="Lorgus Jett ist ein menschliches Mitglied des Kults des Schattenhammers, das in den überfluteten Korridoren...",kw={"allegiance to the old gods","tiefschwarze grotte","lorgus jett","moonshrine ruins","twilight's hammer"},ang={["class:Shaman"]="Jett führt die Elemente nicht in Harmonie oder Ehrerbietung, sondern durch die verderbten, gewaltsamen Methoden, die der Schattenhammer lehrt.",["faction:Horde"]="Lorgus Jett niederzustrecken erfüllt eine dringende Bitte, die Führung des Schattenhammers zu zerschlagen, die sich unter der Küste des Eschentals festsetzt.",["race:Human"]="Einen Menschen so weit westlich in Kalimdor im Dienst kosmischer Schrecken zu sehen, ist eine erschreckende Mahnung daran, wie weit die Verderbnis des Schattenhammers bereits reicht."},sec={{t="Ein Schänder in den Ruinen",b="Während viele Mitglieder des Schattenhammers, die in der Tiefschwarzen Grotte arbeiten, orkischer oder Tauren-Abstammung sind, sticht Lorgus Jett als Mensch in den tiefen Winkeln uralter Nachtelfenruinen hervor. Jett streift überall zwischen den oberen Moonshrine Ruins und den höhlenartigen Tunneln jenseits des Murloc-Schänders Gelihast umher und koordiniert die finsteren Rituale und gewaltsamen Ambitionen des Kults."}},faq={{q="Wer ist Lorgus Jett?",a="Lorgus Jett ist ein menschlicher Agent des Kults des Schattenhammers, der in der Tiefschwarzen Grotte stationiert ist. Er beaufsichtigt die Aktivitäten des Kults in den Moonshrine Ruins und dient den Alten Göttern.",al={"lorgus jett lore","wer ist lorgus","lorgus jett hintergrund"}},{q="Wo ist Lorgus Jett in der Tiefschwarzen Grotte zu finden?",a="Lorgus Jett hat ein wechselndes Patrouillengebiet innerhalb der Moonshrine Ruins. Er kann in der Nähe der ersten Gruppen von Schattenhammer-Kultisten auftauchen oder weiter hinten in den überfluteten Gängen kurz hinter Gelihasts Schrein.",al={"lorgus jett aufenthaltsort","wo ist lorgus jett","lorgus jett finden"}},{q="Warum will die Horde Lorgus Jett tot sehen?",a="Die Horde trachtet im Rahmen der Mission „Allegiance to the Old Gods“ nach seinem Tod. Seine Präsenz im Eschental bedroht die regionale Stabilität und stellt ein heimtückisches Bündnis dar, das sich der Entfesselung uralter, weltenzerstörender Wesenheiten verschrieben hat.",al={"warum lorgus töten","allegiance to the old gods quest"}},{q="Warum nutzt ein Mensch schamanistische Kräfte?",a="Der Schattenhammer kommuniziert direkt mit chaotischen Elementarkräften und Alten Göttern statt mit traditionellen Geistern der Ahnen, was es untypischen Völkern wie Menschen ermöglicht, elementare Verwüstung zu entfesseln.",al={"lorgus jett magie","mensch schamane lorgus"}},{q="Was verbindet Lorgus Jett mit Gelihast?",a="Beide hausen in den Moonshrine Ruins der Tiefschwarzen Grotte, vereint in ihrer Knechtschaft gegenüber den dunklen Mächten, die unter dem Meer schlummern, wobei Jett regelmäßig die Gänge jenseits von Gelihasts Altar patrouilliert.",al={"lorgus und gelihast","gelihast verbindung"}}},fx={["647bfdae"]={q="Auf wessen Seite steht Lorgus Jett?",a="Lorgus Jett dient dem Schattenhammer, dem apokalyptischen Kult, der sich den Alten Göttern verschrieben hat. Obwohl er ein Mensch ist, hat er seine Verwandten verlassen, um sich den dunklen Ritualisten und Elementarkräften anzuschließen, die sich in den vergessenen Tiefen des Eschentals versammeln.",al={"fraktion von lorgus jett","wem dient lorgus jett","welcher fraktion gehört lorgus jett an"}},ba0235c4={q="Warum ist Lorgus Jett in der Tiefschwarzen Grotte?",a="Er lauert zusammen mit seinen Kultistenkollegen in den unterirdischen Moonshrine Ruins und führt den Willen des Schattenhammers aus. Tief im Inneren des alten Elbentempels kümmert sich der Kult um dunkle Schrecken und verehrt die uralten Mächte, die sich unter den Wassern regen.",al={"warum ist lorgus jett in der tiefschwarzen grotte","zweck von lorgus jett in der tiefschwarzen grotte","warum ist lorgus jett hier"}}},fp="11,350,22.373.0,19.179.0,52.199.0,41.223.0,40.200.0,45.198.0"}
P.entries["npc:loslor-rudge"] = {n="Loslor Rudge",s="Loslor Rudge ist ein geschäftstüchtiger zwergischer Ingenieursbedarfshändler, der in Stahlrosts Depot in Dun Morogh stationiert ist. Er versorgt Tüftler in den verschneiten Gebirgszügen mit mechanischen Teilen, Werkzeugen und Munition und hält wichtige Verbindungen zu Büchsenmachern wie Hegnar Schlingerschuss aufrecht.",h="Loslor Rudge ist ein geschäftstüchtiger zwergischer Ingenieursbedarfshändler, der in Stahlrosts Depot in Dun...",kw={"munition","dun morogh","ingenieurskunst","der altgediente bau","hegnar schlingerschuss","loslor rudge","stahlrosts depot"},ang={["profession:Engineering"]="Loslor führt wichtige Vorräte für das frühe Handwerk – wie etwa Flussmittel, Sprengpulver, Röhren und Tüftlersätze –, was seinen Posten im Depot zu einer praktischen Anlaufstelle für jeden angehenden Ingenieur auf der Reise durch Dun Morogh macht.",["race:Dwarf"]="Wie bei vielen Handwerkern in Dun Morogh hängt Loslors Lebensunterhalt von verlässlichen Karawanenrouten zwischen den verstreuten Zwergenlagern ab, was zeigt, wie selbst einheimische Raubtiere wie Wendigos den Handel im Gebirge stören können."},sec={{t="Ein Lieferant im Schnee",b="Von seinem Stützpunkt in Stahlrosts Depot gleich die Straße hinunter von Kharanos aus führt Loslor Rudge einen stetigen Vorrat an unverzichtbarem Ingenieursbedarf – von Kupfermodulatoren und Bronzeröhren bis hin zu Sprengpulver und Schraubenschlüsseln. Das raue Wetter in Dun Morogh und die ausgedehnten Tüftelarbeiten bedeuten, dass praktische Teile ständig gefragt sind, und Loslor ist stolz darauf, die einheimischen Schrauber zu versorgen. Die Wildnis zwischen den Außenposten ist jedoch tückisch; als ein Kurier, der eine Abkürzung in der Nähe des altgedienten Baus nahm, von Wendigos verjagt wurde, blieb eine wichtige Munitionslieferung für seinen geschätzten Kunden, den Büchsenmacher Hegnar Schlingerschuss, im Schnee zurück."}},faq={{q="Wer ist Loslor Rudge?",a="Loslor Rudge ist ein zwergischer Ingenieursbedarfshändler, der sein Geschäft in Stahlrosts Depot in Dun Morogh betreibt. Er verkauft Tüftlerwerkzeuge, Teile und Munition an Abenteurer und Handwerker in der gesamten Region.",al={"loslor rudge","wer ist rudge","steelgrills depot ingenieur"}},{q="Bei welchem Problem braucht Loslor Hilfe?",a="Er hat kürzlich einen Kurier entsandt, um eine Munitionslieferung zum Büchsenmacher Hegnar Schlingerschuss zu bringen. Der Kurier nahm eine Abkürzung am altgedienten Bau vorbei, geriet an wilde Wendigos und floh, wobei er die Kiste im Schnee zurückließ. Loslor braucht jemanden, der die Lieferung birgt, bevor er seinen geschätzten Kunden verliert.",al={"munition für rumbleshot quest","was will rudge","rudge kurier"}},{q="Wo befindet sich Stahlrosts Depot?",a="Stahlrosts Depot ist ein geschäftiger zwergischer Sammelplatz und eine Maschinenwerkstatt, die direkt östlich von Kharanos an der Hauptstraße nach Loch Modan liegt.",al={"wo ist steelgrills depot","steelgrill standort"}},{q="Wer ist Hegnar Schlingerschuss?",a="Hegnar Schlingerschuss ist ein zwergischer Büchsenmacher, der von einem Lager in Dun Morogh aus arbeitet und für frische Munitionslieferungen und mechanische Bauteile auf Loslor Rudge angewiesen ist.",al={"wer ist hegnar","rumbleshot"}}},fx={["774accc1"]={q="Auf wessen Seite steht Loslor Rudge?",a="Loslor Rudge ist ein loyales Mitglied der Zwergengemeinschaft von Eisenschmiede und der Allianz. Von Stahlrosts Depot aus betreibt er Geschäfte, die zwergische Scharfschützen, Handwerker und nahegelegene Siedlungen in ganz Dun Morogh direkt unterstützen.",al={"fraktion von loslor rudge","gehört loslor rudge zur allianz","wem dient loslor rudge"}},["1a06e65e"]={q="Warum ist Loslor Rudge in Stahlrosts Depot?",a="Loslor arbeitet von Stahlrosts Depot aus als Ingenieurslieferant und Händler. Das Depot dient als geschäftiger Knotenpunkt für zwergische Maschinerie, Reparaturen und Industrie außerhalb von Eisenschmiede, was es zu einem idealen Ort für ihn macht, um Bastlerteile und Pulver zu verkaufen und Munition für regionale Büchsenmacher herzustellen.",al={"warum ist loslor rudge hier","rolle von loslor rudge in stahlrosts depot","warum ist loslor im depot"}}},fp="12,278,22.653.0,20.204.0,40.304.0,28.141.0,25.162.0"}
P.entries["npc:lotwil-veriatus"] = {n="Lotwil Veriatus",s="Lotwil Veriatus ist ein exzentrischer gnomischer Gelehrter, der in den staubigen Weiten des Ödlands gefährliche Elementarexperimente durchführt. Östlich von Kargath mit seinem sarkastischen Lehrling Lucien Tosselwrench und einem mechanischen Diener namens Servo stationiert, widmet er sich der Verschmelzung von arkaner Theorie, Alchemie und Ingenieurskunst zu einer einheitlichen Disziplin.",h="Lotwil Veriatus ist ein exzentrischer gnomischer Gelehrter, der in den staubigen Weiten des Ödlands...",kw={"ödland","elementar","fam'retor","kargath","lotwil","lucien","servo","veriatus"},ang={["profession:Engineering"]="Ingenieure werden Lotwils Bestreben wiedererkennen, mechanische Gyros und Zahnräder in arkane Eindämmungsfelder zu integrieren, ebenso wie die klassische ingenieurstechnische Tücke einer plötzlichen, gewaltsamen Fehlfunktion.",["race:Gnome"]="Lotwil ist ein Paradebeispiel für gnomischen intellektuellen Ehrgeiz, der bis ins Waghalsige getrieben wird, indem er versucht, Ingenieurskunst und das Arkane ungeachtet der katastrophalen Risiken miteinander zu verbinden."},sec={{t="Ein vereintes Feld des Chaos",b="Ursprünglich aus Kharanos in Dun Morogh stammend, träumt Lotwil von einer großen Universität für seine Erleuchtete Vereinigung für Arkanologie, Alchemie und Ingenieurswissenschaften. Er glaubt, dass diese drei Disziplinen nicht isoliert voneinander ausgeübt, sondern harmonisiert werden sollten. Um diesen Traum zu verwirklichen, wählte er das raue Ödland als sein Laboratorium, um einheimische Felselementare zu erforschen und bindende Fesseln zu konstruieren, die elementare Kräfte beherrschen können. Obwohl er ein versierter Forscher ist – der in der Vergangenheit Elementarmaschinen untersuchte und Dunkeleisenkonstrukte bezwang –, macht ihn sein unerschütterlicher Fokus oft blind für die explosiven Gefahren seiner Feldforschung."},{t="Die Elementarfesseln",b="Lotwils großes Bestreben im Ödland konzentriert sich darauf, seine Fesseln der Elementarbindung zu testen. Indem er Abenteurer damit beauftragt, Felselementarkerne, Kühlmittel und Gyrochronatome zu sammeln, bereitet er ein aufwendiges Ritual vor, das einen elementaren Diener unterwerfen soll. Doch als die Bindungsvorrichtung schließlich aktiviert wird, geht das Zusammenspiel aus unbeständiger Magie, unberechenbarer Ingenieurskunst und instabilen alchemistischen Reagenzien katastrophal schief und beschwört ein gewaltiges, rasendes Elementarmonstrum namens Fam'retor herauf, das sich gegen seinen Schöpfer wendet."}},faq={{q="Wer ist Lotwil Veriatus?",a="Lotwil Veriatus ist ein gnomischer Gelehrter, der in einem abgelegenen Lager östlich von Kargath im Ödland weilt. Er ist ein Gründungsmitglied der Erleuchteten Vereinigung für Arkanologie, Alchemie und Ingenieurswissenschaften und versucht, alle drei Gebiete zu einer einzigen akademischen Disziplin zu verschmelzen.",al={"wer ist lotwil","lotwil veriatus lore","gnom im ödland"}},{q="Warum hält sich Lotwil im Ödland auf?",a="Lotwil kam ins Ödland, um die dortige dichte Ansammlung wilder Felselementare zu erforschen. Die offene Wüste bietet sowohl rohes Elementarmaterial als auch genügend Raum, um unberechenbare Bindungsexperimente durchzuführen, ohne größere Bevölkerungszentren zu gefährden.",al={"warum ist lotwil im ödland","lotwil ödland lager","was macht lotwil"}},{q="Wer ist Lucien Tosselwrench?",a="Lucien Tosselwrench ist Lotwils leidgeprüfter gnomischer Assistent. Völlig zynisch und erschöpft von den exzentrischen Ausführungen seines Meisters, kümmert sich Lucien um die Logistik, repariert den mechanischen Diener Servo und warnt Unbeteiligte regelmäßig vor Lotwils gefährlicher Sorglosigkeit.",al={"lucien tosselwrench","lotwil assistent","lotwil lehrling"}},{q="Was geschieht, wenn Lotwil sein Experiment beendet?",a="Lotwil versucht, seine eigens angefertigten Fesseln der Elementarbindung zu nutzen, um ein Elementarkonstrukt zu versklaven. Die Hybridtechnologie scheitert spektakulär und beschwört ein riesiges, erzürntes Felselementar namens Fam'retor herauf, das getötet werden muss, bevor es sein Lager zerstört.",al={"lotwil experiment gescheitert","fesseln der elementarbindung","fam'retor"}}},fp="15,338,24.619.0,22.526.1,23.268.0,34.248.0,27.269.0,49.259.1"}
P.entries["npc:lucius"] = {n="Lucius",s="Lucius ist ein Zwergenagent, der in der Nähe der Docks von Seenhain im Rotkammgebirge zu finden ist. Er fungiert als verdeckter Feldkontakt für den Geheimdienst Der SI:7 aus Sturmwind und unterstützt Agenten mit spezialisierter Aufklärung sowie handwerklichen Fertigkeiten.",h="Lucius ist ein Zwergenagent, der in der Nähe der Docks von Seenhain im Rotkammgebirge zu finden ist.",kw={"docks","zwerg","seenhain","schlossknacken","lucius","rotkammgebirge","schurke","der si:7"},ang={["class:Rogue"]="Für Schurken, die von Sturmwind ins Feld geschickt werden, fungiert Lucius als unverzichtbarer Kontakt und Ausbilder zur Verfeinerung von Schlossknack- und Aufklärungsfertigkeiten.",["race:Dwarf"]="Lucius erinnert daran, dass zwergische Talente weit über Schmiede und Frontlinie hinausgehen und auch in den verdeckten Operationen von Sturmwind ihren Platz finden."},sec={{t="Augen im Gebirge",b="Während Lucius an der Uferpromenade von Seenhain einen unauffälligen Eindruck erweckt, ist er in Wirklichkeit ein verdeckter Agent, der direkt dem Geheimdienstapparat von Sturmwind, dem SI:7, untersteht. Von seinem Posten an den Docks aus überwacht er den Handel, ungewöhnliche Truppenbewegungen und regionale Bedrohungen, die das Rotkammgebirge gefährden. Agenten, die von Sturmwind nach Osten entsandt werden, werden an ihn verwiesen, um verdeckte Aufträge zu koordinieren und praktische Fertigkeiten der Feldarbeit wie das Schlossknacken zu verfeinern, damit die Krone ihren Einfluss weit über den Wald von Elwynn hinaus sichert."}},faq={{q="Wer ist Lucius?",a="Lucius ist ein in Seenhain stationierter Zwergenagent, der für den SI:7, den Geheimdienst des Königreichs Sturmwind, arbeitet.",al={"lucius identität","wer ist der zwerg an den docks","lucius nsc"}},{q="Was tut Lucius in Seenhain?",a="Er dient als Feldkontakt für verdeckte Agenten, erteilt vor Ort Unterweisung in Diebeskunst und Schlossknacken und behält die regionalen Bewegungen im Rotkammgebirge im Auge.",al={"was macht lucius hier","lucius zweck","warum ist lucius an den docks"}},{q="Welche Quests schließen Lucius ein?",a="Lucius ist die Ansprechperson für die SI:7-Mission „Rendezvous im Rotkammgebirge“ und schickt junge Schurken aus, um die Schlösser von Truhen bei Althers Mühle zu knacken und sich ihr Zertifikat der Diebeskunst zu verdienen.",al={"lucius quests","quest rendezvous im rotkammgebirge","althers mühle"}}},fx={f414b59e={q="Auf wessen Seite steht Lucius?",a="Lucius steht fest auf der Seite der Allianz und untersteht speziell dem SI:7, Sturmwinds Elite-Geheimdienst- und Geheimoperationsagentur. Während er ein bescheidenes Profil wahrt, während er am Pier in Seenhain arbeitet, gelten seine Loyalitäten direkt den Spionagemeistern in der Hauptstadt.",al={"fraktion von lucius","loyalität von lucius","wem dient lucius"}},db7d3191={q="Was will Lucius?",a="Lucius dient als unauffälliger Feldagent für das SI:7. Er behält die Aktivitäten rund um den Immerruhsee und die Grenze des Rotkammgebirges scharf im Auge, verbindet sich mit besuchenden Agenten und leitet vielversprechende Agenten an, die ausgesandt wurden, um sensible Aufgaben in den Bergen auszuführen.",al={"was macht lucius","was braucht lucius","ziele von lucius"}},["2f7f1e59"]={q="Mit wem ist Lucius verbunden?",a="Lucius ist direkt mit dem SI:7 verbunden, dem Geheimdienstnetzwerk mit Sitz in Sturmwind. Er fungiert als ihr ruhiger lokaler Kontakt im Rotkammgebirge und arbeitet mit anderen Agenten zusammen, die in die Region entsandt wurden, um verdeckte Aufklärung und spezialisierte Operationen durchzuführen.",al={"mit wem ist lucius verbunden","verbindungen von lucius","lucius und das si7"}}},fp="6,244,21.490.0,14.127.0,33.178.0,28.171.0"}
P.entries["npc:lyria-du-lac"] = {n="Lyria Du Lac",s="Lyria Du Lac ist eine menschliche Kriegerlehrerin, die in Goldhain im Wald von Elwynn stationiert ist. Versteckt direkt hinter der Schmiede des Dorfes drillt sie kampfunerfahrene Rekruten und weist junge Krieger an, während sie beginnen, ihre Haltungen und den Umgang mit ihren Waffen zu meistern.",h="Lyria Du Lac ist eine menschliche Kriegerlehrerin, die in Goldhain im Wald von Elwynn stationiert ist.",kw={"die ausbildung eines kriegers","schmied","wald von elwynn","goldhain","lyria du lac","kriegerlehrer"},ang={["class:Warrior"]="Für Krieger, die frisch aus der Abtei von Nordhain kommen, ist Lyria Du Lac die erste wichtige Lehrmeisterin, der Ihr im Wald von Elwynn begegnet, und sie hilft Euch dabei, die Beherrschung Eurer Haltungen und Eure Nahkampftaktiken zu schärfen.",["faction:Alliance"]="Hinter der Schmiede in Goldhain positioniert, stellt Lyria sicher, dass lokale Rekruten in der Lage sind, das Kernland von Sturmwind gegen Defias-Banditen und Gnoll-Plünderer zu verteidigen."},sec={{t="Kriegerlehrerin von Goldhain",b="Während das Gasthaus \"Zur Höhle des Löwen\" in Goldhain vor Reisenden nur so wimmelt und der Schmied fleißig an lokalen Handelswaren hämmert, hält sich Lyria Du Lac auf dem Hof hinter der Schmiede auf. Erfahren in militärischer Disziplin dient sie der Allianz, indem sie frisch aus der Abtei von Nordhain kommende, unerfahrene Krieger ausbildet. Sie bewertet deren Bereitschaft und führt sie in spezialisierte Kampftechniken ein, um sicherzustellen, dass diejenigen, die für Sturmwind zu Schild und Klinge greifen, sich gegen die drohenden Gefahren im Wald von Elwynn behaupten können."}},faq={{q="Wo kann ich Lyria Du Lac finden?",a="Lyria Du Lac steht draußen direkt hinter der Schmiede in Goldhain, gleich westlich des Gasthaus \"Zur Höhle des Löwen\" im Wald von Elwynn.",al={"lyria du lac standort","wo ist lyria","kriegerlehrer goldhain"}},{q="Welchen Dienst bietet Lyria Du Lac an?",a="Sie ist eine Kriegerlehrerin. Sie bringt unerfahrenen Kriegern grundlegende Kampfmanöver, die Grundlagen der Kampfhaltungen und Kampfdisziplinen bei, während diese ihre Fähigkeiten verbessern.",al={"was macht lyria","lyria du lac rolle","was bringt lyria bei"}},{q="Welche Quests beinhalten Lyria Du Lac?",a="Lyria gibt aufstrebenden Kriegern die Quest 'Die Ausbildung eines Kriegers' und schickt sie zu dem Veteranen Harry Burlguard in die Gaststätte Pig and Whistle in der Altstadt von Sturmwind.",al={"lyria du lac quests","kriegerquest goldhain"}}},fx={f698c0e4={q="Wer ist Lyria Du Lac?",a="Lyria Du Lac ist eine erfahrene menschliche Kriegerin, die im Wald von Elwynn als Kampfausbilderin dient. Sie ist hinter der Schmiede in Goldhain stationiert, wo sie angehende Kämpfer auf ihrem Weg in das Königreich begutachtet und unterweist. Dabei bringt sie ihnen bei, ihr kriegerisches Können zu nutzen und die Bedrohungen zu überleben, die an die Grenzen von Sturmwind drängen.",al={"wer ist lyria","lyria du lac lore","wer ist lyria du lac"}},["34434421"]={q="Auf wessen Seite steht Lyria Du Lac?",a="Lyria steht fest an der Seite des Königreichs Sturmwind und der Allianz. Indem sie frische Rekruten darauf vorbereitet, den Wald von Elwynn vor lokalen Gefahren wie Banditen und Gnollen zu verteidigen, hilft sie dabei, die militärische Bereitschaft des Königreichs zu stärken, während die regulären Garnisonstruppen überlastet sind.",al={"fraktion von lyria du lac","loyalität von lyria du lac","wem dient lyria"}},afd6a9c2={q="Warum ist Lyria Du Lac hier in Goldhain?",a="Goldhain ist der natürliche Sammelpunkt für Reisende, die das Nordhaintal verlassen, was es zum idealen Posten macht, um vielversprechende Abenteurer im Umgang mit Waffen zu schulen. Direkt hinter dem Schmied stationiert, stellt Lyria sicher, dass jeder junge Krieger, der in der Stadt ankommt, ordentlich konditioniert und diszipliniert ist, bevor er sich größeren Gefahren stellt.",al={"warum ist lyria in goldhain","zweck des standorts von lyria du lac","was brachte lyria hierher"}},["277e5774"]={q="Was will Lyria Du Lac?",a="Lyria sucht fähige Schüler, die bereit sind, die Kunst des Kampfes zu meistern. Sie möchte sehen, wie junge Krieger ihre Disziplin schärfen, die Kampfhaltungen und -techniken beherrschen und ihr Training nutzen, um das Reich vor jeglichem Chaos zu verteidigen, das seinen Frieden bedroht.",al={"was will lyria","ziel von lyria du lac","beweggrund von lyria du lac"}}},fp="12,231,28.500.0,30.129.0,39.154.0,33.164.0"}
P.entries["npc:ma-stonefield"] = {n="Mutter Steinfeld",s="Mutter Steinfeld ist eine menschliche Matriarchin, die auf dem Hof der Steinfelds im westlichen Wald von Elwynn lebt. Direkt vor dem Gehöft der Familie steht sie an der Seite von Tantchen Bernice und meistert die alltäglichen Härten des ländlichen Farmlebens inmitten von Nachbarschaftsfehden und Plagen.",h="Mutter Steinfeld ist eine menschliche Matriarchin, die auf dem Hof der Steinfelds im westlichen Wald von...",kw={"bernice stonefield","wald von elwynn","mutter steinfeld","prinzessin","prinzessin muss sterben","hof der steinfelds"},ang={["faction:Alliance"]="Für Abenteurer der Allianz, die den Wald von Elwynn erkunden, trägt die Hilfe für fleißige Siedler wie Mutter Steinfeld dazu bei, Sturmwinds landwirtschaftliches Rückgrat zu bewahren."},sec={{t="Probleme auf dem Gehöft",b="Neben ihrem Familienhäuschen im südwestlichen Wald von Elwynn wacht Mutter Steinfeld an der Seite von Tantchen Bernice Steinfeld über das Gehöft. Das Leben zwischen dem benachbarten Maclure-Hof und den nahegelegenen Kürbisfeldern ist selten friedlich. Einheimische Wildschweine bedrohen fortwährend die Ernte der Familie, und keines stellt ein größeres Ärgernis dar als Prinzessin, eine riesige Preissau, die berüchtigt dafür ist, Felder zu zertrampeln und die mühsam erarbeitete Ernte zu verschlingen."}},faq={{q="Wer ist Mutter Steinfeld?",a="Mutter Steinfeld ist eine der Ältesten der Familie Steinfeld und lebt auf deren Gehöft im südwestlichen Wald von Elwynn an der Seite von Verwandten wie Tantchen Bernice.",al={"wer ist mutter stonefield","mutter steinfeld","stonefield mutter"}},{q="Wo kann ich Mutter Steinfeld finden?",a="Sie steht im Freien direkt vor dem Haupthaus auf dem Hof der Steinfelds, westlich von Goldhain im Wald von Elwynn.",al={"mutter stonefield standort","wo ist mutter stonefield","hof der stonefields standort"}},{q="Welches Problem muss Mutter Steinfeld gelöst haben?",a="Mutter Steinfeld sucht Abenteurer, die Prinzessin ein Ende bereiten – einem riesigen Preisschwein, das wiederholt durch die umliegenden Felder tobt und die Ernte verschlingt.",al={"mutter stonefield quest","prinzessin sau quest","questgeber prinzessin muss sterben"}}},fx={["51af3003"]={q="Auf wessen Seite steht Mutter Steinfeld?",a="Mutter Steinfeld ist eine loyale Untertanin des Königreichs Sturmwind und Mitglied der Allianz. Wie die meisten Landleute, die im Herzen des Walds von Elwynn leben, konzentriert sie sich ganz auf den Hof ihrer Familie, wenngleich sie sich auf Abenteurer der Allianz verlässt, um einzugreifen, wenn örtliche Probleme für einfache Farmer zu groß werden.",al={"ist mutter steinfeld allianz","fraktion von mutter steinfeld"}},["02537c40"]={q="Warum ist Mutter Steinfeld hier?",a="Der Hof der Steinfelds ist das lebenslange Zuhause von Mutter Steinfeld. Sie lebt und bewirtschaftet das Land im Wald von Elwynn an der Seite ihrer Verwandten und kümmert sich um die täglichen Aufgaben des Landlebens direkt vor dem Gehöft der Familie nahe bei Tantchen Bernice Steinfeld.",al={"warum ist mutter steinfeld auf dem hof","was macht mutter steinfeld hier"}},ae4d5db0={q="Mit wem ist Mutter Steinfeld verbunden?",a="Mutter Steinfeld ist eine Matriarchin des Steinfeld-Clans und lebt zusammen mit Verwandten wie Tantchen Bernice Steinfeld auf ihrem Gehöft im Wald von Elwynn. Ihre Familie hat langjährige Wurzeln im Tal, obwohl sie auch eine bittere, andauernde Fehde mit ihren Nachbarn, den Maclures, verbindet.",al={"familie von mutter steinfeld","mit wem ist mutter steinfeld verwandt"}}},fp="13,264,18.438.0,21.166.0,31.138.0,44.163.0"}
P.entries["npc:mad-magus-tirth"] = {fx={f085518f={q="Auf wessen Seite steht Magus Tirth?",a="Magus Tirth bleibt strikt neutral. Er verdient seinen Lebensunterhalt auf den Salzebenen der schimmernden Ebene an der Seite von Goblin- und Gnom-Ingenieuren und bietet Reisenden der Allianz wie auch der Horde bereitwillig seine Waren und magischen Ratschläge an, ohne an ihrem größeren Krieg teilzunehmen.",al={"ist magus tirth allianz oder horde","fraktion von tirth","ist magus tirth neutral"}}}}
P.entries["npc:madame-eva"] = {fx={b3bc0c21={q="Auf wessen Seite steht Madame Eva?",a="Madame Eva steht fest auf der Seite der Bewohner von Dunkelhain und der Allianz. Obwohl sie sich mit Kartenlegen und den obskuren ‚alten Künsten‘ befasst, bleiben ihre Loyalitäten bei ihren bedrängten Nachbarn und ihrer Familie; sie nutzt ihre Weissagungen und Rituale, um die Stadt vor den dunklen Gefahren zu schützen, die durch den Dämmerwald kriechen.",al={"loyalität von madame eva","wem dient eva","ist madame eva allianz"}},d6f73346={q="Was will Madame Eva?",a="Madame Eva versucht, ihre Gemeinschaft und Verwandten vor den dunklen Mächten zu schützen, die im Dämmerwald umgehen. Mithilfe ihrer Kartenlegetechnik sieht sie verborgene Bedrohungen voraus – etwa das lauernde Unheil, das das Geheimnis um Stalvan Dunstmantel umgibt – und weist Reisende an, rituelle Reagenzien zu sammeln, um das Böse abzuwehren und ihre Familie zu beschützen.",al={"was versucht eva zu tun","ziele von eva","warum braucht madame eva hilfe"}},["6bf59259"]={q="Warum ist Madame Eva hier in Dunkelhain?",a="Dunkelhain ist das angestammte Zuhause von Madame Eva. Sie lebt in ihrem Häuschen als Matriarchin für ihre Enkelkinder Alyssa und Lohgan Eva und bietet den verängstigten Leuten, die versuchen, das Leben inmitten der schattenhaften Wälder zu ertragen, Führung, Wahrsagerei und mystischen Beistand.",al={"warum lebt eva im dämmerwald","warum ist madame eva in dunkelhain","zuhause von madame eva"}}}}
P.entries["npc:magatha-grimtotem"] = {n="Magatha Grimmtotem",s="Magatha Grimmtotem ist die Matriarchin des Stammes der Grimmtotem und die Ältestengreisin von Donnerfels. Als furchterregende Schamanin und politische Ränkeschmiedin residiert sie auf der Anhöhe der Ältesten, während sie Cairne Bluthufs Vision für das Volk der Tauren unablässig herausfordert.",h="Magatha Grimmtotem ist die Matriarchin des Stammes der Grimmtotem und die Ältestengreisin von Donnerfels.",kw={"arikara","bloodhoof","cairne","die ältestengreisin","die anhöhe der ältesten","grimmtotem","magatha","ragefire","donnerfels","zamah"},ang={["class:Shaman"]="Magatha ist unbestreitbar eine der mächtigsten Schamaninnen auf Kalimdor und befehligt die Urgewalten der Elemente mit einer Autorität, die nur wenige lebende Tauren erreichen können.",["faction:Horde"]="Obwohl Magatha wertvolle Hilfe und Ratschläge gegen regionale Bedrohungen bietet, machen ihre erbitterte Loyalität zu ihrem Clan und ihre offene Verachtung für andere Völker sie zu einer unzuverlässigen Gefährtin.",["race:Tauren"]="Jeder Taure kennt den finsteren Ruf der Grimmtotem, wodurch Magathas Anwesenheit auf der Anhöhe der Ältesten eine beunruhigende Erinnerung an die ideologische Kluft darstellt, die ihre vereinten Stämme bedroht.",["race:Undead"]="Reisende der Verlassenen werden von der Ältestengreisin überraschend herzlich empfangen, die sich regelmäßig mit der Königlichen Apothekervereinigung in den Teichen der Visionen berät."},sec={{t="Die Matriarchin der Anhöhe der Ältesten",b="Magatha erlangte die absolute Herrschaft über die Grimmtotem durch eine arrangierte Verbindung, auf die der plötzliche, tödliche Kletterunfall ihres Gefährten folgte. Von der Anhöhe der Ältesten aus agiert sie mit ihrem persönlichen Gefolge und Leibwächtern als unangefochtene politische und spirituelle Anführerin ihres zurückgezogenen Stammes. Im Gegensatz zu Cairne Bluthuf predigt Magatha die Vorherrschaft der Tauren und betrachtet andere sterbliche Völker als Eindringlinge auf Kalimdor, die vernichtet oder beiseitegefegt werden sollten."},{t="Ein sonderbares Bündnis",b="Trotz ihrer offenen Verachtung für Nicht-Tauren gehörte Magatha zu den frühesten Fürsprechern für die Aufnahme der Verlassenen in die Horde. Sie behauptet, die Tauren könnten den Untoten spirituelles Gleichgewicht lehren und sie dabei anleiten, ihre Menschlichkeit wiederzuerlangen. In der Praxis arbeitet Magatha jedoch direkt mit der Königlichen Apothekervereinigung unter Donnerfels zusammen und berät sich mit Persönlichkeiten wie Apothekerin Zamah über angewandte Alchemie und das Studium arkaner Relikte."},{t="Politische Machenschaften",b="Hinter einer Fassade weisen Rats arbeitet Magatha aktiv daran, Cairnes Autorität zu schwächen, während sie die Verteidigung potenzieller Bedrohungen auf die Probe stellt. Sie entsendet Abenteurer in große Gefahren – von der Erkundung der Trogg-Streitkräfte im Flammenschlund bis hin zur Jagd auf den rachsüchtigen Geist Arikara. Jede von ihr gestellte Aufgabe dient entweder dazu, den Einfluss der Grimmtotem zu festigen, oder bereitet den Tag vor, an dem sie die Bluthuf-Dynastie vollständig verdrängen kann."}},faq={{q="Wer ist Magatha Grimmtotem?",a="Magatha ist die Ältestengreisin und Matriarchin des Stammes der Grimmtotem. Seit ihrer Kindheit eine begabte Schamanin, übernahm sie die uneingeschränkte Herrschaft über ihren Clan, nachdem ihr Gefährte bei einem Kletterunfall ums Leben kam. Sie residiert auf der Anhöhe der Ältesten in Donnerfels, wo sie als Cairne Bluthufs größte politische Rivalin fungiert.",al={"magatha hintergrundgeschichte","wer ist die ältestengreisin","ältestengreisin donnerfels"}},{q="Warum unterstützt Magatha die Verlassenen?",a="Vordergründig glaubt Magatha, dass die Traditionen der Tauren und schamanisches Verständnis die Verlassenen zurück zur Menschlichkeit führen können. Viele vermuten jedoch, dass ihre Freundschaft mit der Königlichen Apothekervereinigung vom Wunsch nach esoterischen alchemistischen Geheimnissen und politischen Verbündeten außerhalb von Cairnes loyalem engsten Kreis angetrieben wird.",al={"magatha und untote","warum magatha verlassene mag","magatha apothekerin zamah"}},{q="Wie ist Magathas Beziehung zu Cairne Bluthuf?",a="Magatha hält Cairne für weich, naiv und unfähig, die vereinten Tauren anzuführen. Während Cairne für die Koexistenz innerhalb der Horde und Frieden auf ganz Kalimdor eintritt, glaubt Magatha, dass die Grimmtotem das Land ihrer Ahnen mit Gewalt zurückfordern und fremde Eindringlinge beseitigen sollten.",al={"magatha gegen cairne","hasst magatha cairne","cairne und magatha"}},{q="Was war der Auftrag im Flammenschlund?",a="Magatha schickte einen Abgesandten namens Maur in den Flammenschlund unter Orgrimmar, um mit den dort ansässigen Troggs zu verhandeln. Stattdessen töteten die Troggs Maur, was Magatha dazu veranlasste, Abenteurer der Horde in die Höhle zu schicken, um Maurs Ranzen zu bergen und die Troggs zur Vergeltung abzuschlachten.",al={"magatha ragefire quest","warum schickte magatha maur","verlorener ranzen magatha"}},{q="Wer ist Arikara?",a="Arikara ist der Geist einer rachsüchtigen Windnatter, von dem es heißt, er suche Vergeltung am Volk der Tauren. Magatha behauptet, Arikara trachte direkt nach Rache an Cairne Bluthuf, und beauftragt fähige Recken damit, das Biest mithilfe verzauberter Agaven zu beschwören und zu erschlagen.",al={"schlange der vergeltung","arikara quest","magatha arikara"}},{q="Wo ist Magatha Grimmtotem zu finden?",a="Magatha residiert im großen Hauptzelt auf der Anhöhe der Ältesten in Donnerfels, begleitet von ihrem Diener Rahauro und zwei stoischen Grimmtotem-Wachen.",al={"magatha aufenthaltsort","wo ist magatha","magatha anhöhe der ältesten"}}},fx={ebac2d3c={q="Auf wessen Seite steht Magatha Grimmtotem?",a="Magatha dient vor allem sich selbst und dem Grimmtotem-Stamm. Während sie einen ehrenvollen Sitz auf der Anhöhe der Ältesten in Donnerfels innehat und offiziell zur Horde gehört, ist ihre Loyalität rein geschäftsmäßig. Sie fordert offen die Vision von Hochhäuptling Cairne Bluthuf für ihr Volk heraus, bevorzugt rücksichtslose Vorherrschaft der Tauren gegenüber Frieden und verfolgt private Bündnisse – vor allem mit den Verlassenen –, um den Einfluss ihrer eigenen Fraktion auszubauen.",al={"loyalitäten von magatha","wem dient magatha","ist magatha der horde gegenüber loyal"}},b26ae613={q="Was will Magatha Grimmtotem?",a="Magatha glaubt, dass nur sie dazu geeignet ist, die Tauren anzuführen. Sie versucht, Cairne Bluthuf die Autorität zu entziehen, alle niederen Rassen aus Kalimdor zu vertreiben und die angestammten Gebiete ihres Volkes zurückzufordern. Um die Macht zu sammeln, die sie dafür benötigt, sammelt sie ständig uralte Relikte, testet potenzielle Feinde und pflegt kontroverse Beziehungen, die Cairne und die anderen Ältesten niemals billigen würden.",al={"ziele von magatha","was plant magatha","motivationen von magatha"}},["0cc6173c"]={q="Warum ist Magatha Grimmtotem hier?",a="Als The Elder Crone und Matriarchin der Grimmtotem residiert Magatha auf der Anhöhe der Ältesten, um ihren grimmigen Stamm innerhalb der vereinten Taurennation zu vertreten. Von diesem erhabenen Standpunkt aus berät sie Reisende, gibt der Stadt Rat und behält die Herrschaft von Cairne Bluthuf im Auge, um sicherzustellen, dass ihr Clan eine mächtige Stimme in der Regierung von Donnerfels behält.",al={"warum ist magatha in donnerfels","warum ist magatha hier"}},["4e6ef5c4"]={q="Mit wem ist Magatha Grimmtotem verbunden?",a="Magatha befehligt die grimmigen Krieger des Grimmtotem-Stamms, die ständig von ihren persönlichen Wachen und Dienern flankiert werden. Außerhalb ihres Clans unterhält sie eine ungewöhnlich enge, aktive Partnerschaft mit den Verlassenen – sie arbeitet an der Seite von Figuren der Königlichen Apothekervereinigung wie Apothecary Zamah – und unterhält private Verbindungen zu Sehern und Agenten in ganz Kalimdor, die außerhalb von Cairnes engem Kreis operieren.",al={"verbündete von magatha","mit wem verkehrt magatha","verbindungen von magatha"}},["92d0808b"]={q="Warum ist Magatha Grimmtotem berühmt oder gefürchtet?",a="Magatha war von Kindheit an mit immensem schamanischen Talent gesegnet und hat ein Leben lang damit verbracht, diese Macht in absolute Autorität über die Grimmtotem umzusetzen. Viele in Donnerfels fürchten ihre rücksichtslose Ambition und tuscheln, dass sie ihre eigene Heirat arrangiert habe, um die Führung ihres Clans zu gewinnen. Ihre Bereitschaft, dunkle Heilmittel einzusetzen, sich mit rachsüchtigen Geistern einzulassen und sich Cairne zu widersetzen, macht sie zu einer der einschüchterndsten Figuren in Mulgore.",al={"warum wird magatha gefürchtet","ist magatha mächtig","ruf von magatha"}}},fp="17,243,27.449.0,18.431.0,22.412.1,25.284.0,38.301.0,53.256.0,39.270.0,15.251.0,37.140.0"}
P.entries["npc:magga"] = {n="Magga",s="Magga ist eine Orc-Bewohnerin, die in der staubigen Siedlung Klingenhügel in Durotar lebt. Sie hält sich in der Nähe des belebten Gasthauses der Stadt auf und ist ein freundliches Gesicht für frisch angekommene Abenteurer der Horde, die gerade das Tal der Prüfungen verlassen haben.",h="Magga ist eine Orc-Bewohnerin, die in der staubigen Siedlung Klingenhügel in Durotar lebt.",kw={"durotar","horde","gastwirt grosk","magga","orc","klingenhügel","willkommen"},ang={["faction:Horde"]="Für frische Rekruten, die die harten Prüfungen des Tals der Prüfungen hinter sich gelassen haben, bietet Magga einen beruhigenden Empfang in der ersten richtigen Siedlung in Durotar."},sec={{t="Ein freundliches Gesicht in Klingenhügel",b="Klingenhügel ist für junge Orcs und Dunkelspeere, die aus dem Tal der Prüfungen kommen, der erste echte Vorgeschmack auf die Welt da draußen. Magga hat ihren Platz direkt neben dem örtlichen Gasthaus und begrüßt Neuankömmlinge im Außenposten. Obwohl sie sich unter den geschäftigen Soldaten und Handwerkern des Außenpostens eher im Hintergrund hält, trägt sie dazu bei, die kleine Siedlung zusammenzuhalten."}},faq={{q="Wer ist Magga?",a="Magga ist eine zivile Orc, die in Klingenhügel in Durotar stationiert ist. Sie steht in der Nähe des Gasthauses, heißt neue Reisende der Horde willkommen und weist ihnen den Weg zu Unterkunft und Rast.",al={"magga durotar","magga klingenhügel","wer ist magga"}},{q="Welche Verbindung hat Magga zu Gastwirt Grosk?",a="Es ist keine besondere Verbindung zwischen ihnen verzeichnet. Magga hält sich in der Nähe des Gasthauses von Klingenhügel auf, wo Gastwirt Grosk Reisenden Speis, Trank und einen Ort bietet, an den sie ihren Ruhestein binden können.",al={"magga und grosk","magga gastwirt"}},{q="Bietet Magga Quests an?",a="Magga ist für die Besorgung 'Willkommen!' zuständig: Abenteurer, die einen Gutschein für Klingenhügel bei sich tragen, überreichen ihn ihr, woraufhin sie sie mit einem kleinen Begleiter als Geschenk in Azeroth willkommen heißt.",al={"magga quests","willkommensquest"}}},fx={["65fbd604"]={q="Auf wessen Seite steht Magga?",a="Magga ist ein loyales Mitglied der Horde und lebt an der Seite ihrer orcischen Mitstreiter in der Siedlung Klingenhügel. Sie heißt Reisende willkommen, die durch das Wegekreuz kommen, und unterstützt stolz das Volk und die Verteidigung von Durotar unter Thralls Führung.",al={"fraktion von magga","ist magga horde","loyalität von magga"}}},fp="5,239,30.339.0,13.156.0,46.168.0,28.168.0"}
P.entries["npc:maggran-earthbinder"] = {n="Maggran Erdbinder",s="Maggran Erdbinder ist ein ergrauter Taurenveteran, der von Oberhäuptling Cairne Bluthuf ernannt wurde, um das Lager der Horde in Sonnenfels anzuführen. Abgehärtet durch ein Leben voller brutaler Konflikte überwacht er die Verteidigung der schroffen Täler des Steinkrallengebirges gegen unersättliche Bestien und aggressive Harpyienzirkel. Obwohl er von zahllosen Schlachten gezeichnet ist, bleibt er ein unerschütterlicher Wächter der Siedlung.",h="Maggran Erdbinder ist ein ergrauter Taurenveteran, der von Oberhäuptling Cairne Bluthuf ernannt wurde, um das...",kw={"besseleth","bloodfury","cairne bluthuf","earthbinder","harpyien","maggran","steinkrallengebirge","sonnenfels"},ang={["faction:Horde"]="Für Reisende, die die steilen Anstiege des Steinkrallengebirges durchqueren, ist Maggran die zentrale Autorität, die lokale Patrouillen der Horde koordiniert und Versorgungsrouten frei von Bestien und Harpyien hält.",["race:Tauren"]="Maggran verkörpert den schweren Tribut, den der Krieg vom Geist der Shu'halo fordert, und dient als Mahnung dafür, wie Konflikte selbst die bodenständigsten Kinder der Erdenmutter verhärten können."},sec={{t="Die Zuflucht eines Veteranen",b="Maggran Erdbinder wurde von Oberhäuptling Cairne Bluthuf persönlich in das Steinkrallengebirge entsandt. Als Veteran zahlloser Scharmützel und blutiger Feldzüge gibt Maggran zu, dass Alter und Gewalt sein Herz verhärtet und ihm die für sein Volk typische Sanftmut genommen haben. Sonnenfels sollte sowohl ein Außenposten unter seinem besonnenen Kommando als auch ein Ort der Erholung sein, an dem warme Winde und der Sonnenschein der Berge seinen kampfesmüden Geist besänftigen könnten."},{t="Gefahren in den Klippen",b="Selbst im Steinkrallengebirge findet Maggran wenig Ruhe. Als Aufseher von Sonnenfels koordiniert er die Verteidigungsbemühungen gegen die Bloodfury-Harpyien, die in den Gipfeln nisten, und stellt Krieger auf, um den Gefahren durch Raubtiere in den schroffen Felsen zu begegnen. Da er einst selbst einen Hinterhalt der riesigen Spinne Besseleth überlebte, gibt sich Maggran keinen Illusionen über die tödliche Wildnis um sie herum hin und rekrutiert regelmäßig Reisende, um gefährliche Raubtiere der Region zu beseitigen, bevor sie den Außenposten überrennen."}},faq={{q="Wer ist Maggran Erdbinder?",a="Maggran Erdbinder ist der befehligende Taurenältester in Sonnenfels im Steinkrallengebirge. Gehärtet durch unzählige Schlachten wurde er von Cairne Bluthuf hierher beordert, um über die Siedlung zu wachen und ihre Versorgungswege sowie Grenzen zu sichern.",al={"maggran","wer ist maggran","anführer von sonnenfels"}},{q="Warum wurde Maggran nach Sonnenfels geschickt?",a="Cairne Bluthuf ernannte ihn teils wegen seiner erfahrenen militärischen Führung und teils als Rückzugsort zum Leiter von Sonnenfels. Maggrans Körper und Geist wurden durch ein Leben voller Kämpfe schwer gezeichnet, und die ruhige Bergsonne schenkt ihm ein gewisses Maß an Genesung.",al={"warum ist maggran hier","maggran hintergrund","cairne und maggran"}},{q="Mit welchen Bedrohungen bittet Maggran Abenteurer fertigzuwerden?",a="Maggran leitet Verteidigungsmaßnahmen gegen die wilden Bloodfury-Harpyien, die die Berge heimsuchen, und entsendet Krieger, um die riesige Spinnenmatriarchin Besseleth zu eliminieren – ein furchterregendes Raubtier, dem er früher auf seinen Reisen nur knapp entkam.",al={"maggran quests","was will maggran","harpyien steinkrallengebirge"}},{q="Was geschah zwischen Maggran und Besseleth?",a="Maggran wurde einst von der kolossalen Spinne Besseleth gebissen. Obwohl es ihm gelang, sie abzuwehren und mit dem Leben davonzukommen, schickt er fähige Abenteurer aus, um die Bestie zu erschlagen, damit niemand sonst ihrem Netz zum Opfer fällt.",al={"maggran besseleth","spinnenquest maggran","arachnophobie hintergrund"}},{q="Hat Maggran eine Rolle in Donnerfels?",a="Maggran dient direkt auf Geheiß von Donnerfels' Oberhäuptling Cairne Bluthuf. Während er draußen im Feld in Sonnenfels stationiert ist, stammen seine Autorität und seine Befehle direkt aus der Hauptstadt.",al={"maggran donnerfels","maggran cairne"}},{q="Ist Maggran Erdbinder Spielern der Allianz freundlich gesinnt?",a="Nein. Maggran ist ein loyaler Anführer der Horde und verhält sich allen Allianz-Abenteurern gegenüber, die nach Sonnenfels stolpern, vollkommen feindselig.",al={"kann allianz mit maggran sprechen","maggran feindselig"}}},fp="19,387,17.455.0,20.472.0,27.247.0,41.256.0,55.228.0,44.210.0,42.201.0,52.133.0"}
P.entries["npc:magis-sparkmantle"] = {n="Magis Funkelmantel",s="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in der Brauerei Donnerbräu in Kharanos stationiert ist. Er bietet jungen Zauberwirkern Anleitung und Ausbildung, wenn sie sich aus dem Coldridgetal in das Herz von Dun Morogh wagen.",h="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in der Brauerei Donnerbräu in Kharanos stationiert ist.",kw={"dun morogh","gnomenmagier","kharanos","magierlehrer","magis","magis funkelmantel","sparkmantle","brauerei donnerbräu"},ang={["class:Mage"]="Für Magier der Allianz, die Dun Morogh durchqueren, ist Sparkmantle ein unverzichtbarer örtlicher Ansprechpartner für die Zauberausbildung und die Weitervermittlung an größere arkane Netzwerke.",["race:Gnome"]="Aus Gnomeregan vertriebene Gnome verlassen sich oft auf Mentoren wie Sparkmantle, um ihre gelehrten und arkanen Traditionen während des Lebens unter den Zwergen aufrechtzuerhalten."},sec={{t="Ein Zauberwirker in der Brauerei",b="Während sich die Zwerge in der Brauerei Donnerbräu für deftiges Bier versammeln, sorgt Magis Funkelmantel zwischen den Fässern und Fässchen von Kharanos für eine arkane Präsenz. Gnomische Magier leben überall in Dun Morogh oft eng mit ihren zwergischen Verbündeten zusammen, und Sparkmantle dient als wichtiger Mentor für angehende Zauberwirker, die bereit sind, ihr theoretisches und praktisches Verständnis der arkanen Künste zu erweitern."},{t="Wegweisung für junge Arkanisten",b="Neben der Unterweisung von Neulingen in grundlegenden Beschwörungsformeln sorgt Magis dafür, dass vielversprechende Schüler Anschluss an größere magische Zirkel finden. Sobald Magier der anfänglichen lokalen Ausbildung entwachsen sind oder spezialisierte Anleitung benötigen, weist Sparkmantle ihnen den weiteren Weg und schickt sie zu befreundeten Praktizierenden wie Bink oder zu Mentoren, die in den Hauptzentren der Allianz stationiert sind."}},faq={{q="Wer ist Magis Funkelmantel?",a="Magis Funkelmantel ist ein Gnom-Magierlehrer, der in Kharanos in Dun Morogh weilt. Er unterweist angehende Zauberwirker in den arkanen Grundlagen.",al={"magis funkelmantel","wer ist magis","kharanos magierlehrer"}},{q="Wo ist Magis Funkelmantel zu finden?",a="Er befindet sich im Inneren der Brauerei Donnerbräu, dem Hauptgasthaus und Versammlungsort des Ortes Kharanos.",al={"magis aufenthaltsort","wo ist magis","sparkmantle finden"}},{q="Warum hält sich ein Gnom-Magierlehrer in einer Zwergenbrauerei auf?",a="Nach dem Fall von Gnomeregan ließen sich viele Gnome bei ihren zwergischen Vettern in Dun Morogh nieder. Die Brauerei Donnerbräu dient als zentraler Knotenpunkt von Kharanos und ist damit ein idealer Posten, um umherreisende Zauberwirker anzuleiten.",al={"warum in brauerei","gnom in brauerei","warum brauerei donnerbräu"}},{q="Bietet Magis Funkelmantel Quests an?",a="Magis weist heranwachsenden Magiern im Laufe ihres Fortschritts den Weg zu anderen arkanen Mentoren, unter anderem schickt er Praktizierende zum Gespräch mit Bink oder weist sie an, sich bei Ausbildern in den Gebieten der Menschen zu melden.",al={"sparkmantle quests","magis quests"}}},fx={["1189c3a2"]={q="Auf wessen Seite steht Magis Funkelmantel?",a="Magis Funkelmantel steht fest auf der Seite von Gnomeregan und der Großen Allianz. Wie viele Exilgnome, die vor der Katastrophe in ihrer Heimatstadt geflohen sind, lebt und arbeitet er an der Seite der Zwerge von Eisenschmiede und bietet den Verteidigern der Allianz sein arkanes Wissen an.",al={"fraktion von magis funkelmantel","ist magis allianz","wem dient funkelmantel"}},e3e37731={q="Was will Magis Funkelmantel?",a="Magis widmet sich der Ausbildung aufstrebender Magier in den arkanen Künsten. Während er in der Destillerie untergebracht ist, bereitet er unerfahrene Zauberwirker auf den vor ihnen liegenden Weg vor, unterweist sie in grundlegender Magie, bevor er sie an erfahrene Meister wie Jennea Haubitz in Sturmwind verweist.",al={"was will magis","ziele von magis funkelmantel","warum bildet magis magier aus"}},["318a77dd"]={q="Mit wem ist Magis Funkelmantel verbunden?",a="Als Teil des weiteren Netzwerks der Magier der Allianz unterhält Magis Verbindungen zu anderen Ausbildern im gesamten Reich, darunter Bink in den Zwergenlanden und Jennea Haubitz im Mage Quarter von Sturmwind, um sicherzustellen, dass vielversprechende Schüler fortgeschrittenen Unterricht finden.",al={"verbündete von magis funkelmantel","mit wem ist funkelmantel verbunden","verbindungen von funkelmantel"}}},fp="17,224,31.369.0,25.350.0,25.132.0,37.107.0,60.222.0,40.173.0"}
P.entries["npc:magistrate-henry-maleb"] = {n="Magistrat Henry Maleb",s="Magistrat Henry Maleb beaufsichtigt die zivile Verwaltung in der Hafenstadt Süderstade, der wichtigsten Küstenbastion der Allianz im Vorgebirge des Hügellands. Mit der Aufgabe betraut, inmitten ständiger Bedrohungen die Ordnung aufrechtzuerhalten, richtet er einen Großteil seiner Autorität darauf, die Verschwörer des Syndikats zur Strecke zu bringen, die es auf die Führung der Stadt abgesehen haben.",h="Magistrat Henry Maleb beaufsichtigt die zivile Verwaltung in der Hafenstadt Süderstade, der wichtigsten...",kw={"alterac","attentäter","henry maleb","hillsbrad","magistrat maleb","süderstade","syndikat"},ang={["class:Rogue"]="Schurken werden feststellen, dass Maleb die Künste der Täuschung und des Meuchelmords mit großer Sorge betrachtet und auf scharfsinnige Agenten setzt, um die verborgenen Mörder des Syndikats auszumanövrieren.",["faction:Alliance"]="Für Recken der Allianz, die in Hillsbrad eintreffen, verkörpert Magistrat Maleb die rechtmäßige weltliche Autorität in einem gesetzlosen Grenzland und setzt Kopfgelder auf die Halsabschneider des Syndikats aus, welche die Stadt destabilisieren."},sec={{t="Hüter der Ordnung von Süderstade",b="Vom Rathaus in Süderstade aus leitet Magistrat Henry Maleb die zivile Verwaltung einer der letzten wahren Siedlungen der Allianz in Lordaeron. Die Stadt steht unter ständiger Bedrängnis durch die Verlassenen im Norden und Westen, während skrupellose Wegelagerer das Vorgebirge unsicher machen. Maleb trat sein derzeitiges Amt nach der rätselhaften Ermordung des vorherigen Magistrats an – eine Tat, die er direkt dem Syndikat zuschreibt. Entschlossen, nicht dasselbe Schicksal zu erleiden, koordiniert er aktive Ermittlungen, um verborgene Attentäter aufzuspüren, die Versorgungsnetzwerke des Syndikats zu zerschlagen und die abtrünnigen Adligen zu entlarven, die aus den Ruinen von Alterac die Fäden ziehen."},{t="Ein Netz adligen Verrats",b="Malebs Nachforschungen über das Syndikat offenbaren einen erbitterten regionalen Konflikt. Bei den Attentätern, die durch die Obstgärten vor Süderstade schleichen, handelt es sich nicht um bloße Banditen, sondern um bezahlte Handlanger im Auftrag gefallener alteracischer Aristokraten. Maleb weist vertrauenswürdige Späher der Allianz an, ihre verschlüsselten Pläne abzufangen und ihre Anführer auszuschalten, wobei er unermüdlich daran arbeitet, den Einfluss des Syndikats zu brechen, bevor dessen Komplotte die Verteidigung der Stadt gänzlich lahmlegen können."}},faq={{q="Wer ist Magistrat Henry Maleb?",a="Er ist der oberste zivile Magistrat von Süderstade im Vorgebirge des Hügellands und dafür verantwortlich, die bürgerliche Ordnung aufrechtzuerhalten und die Zuflucht der Allianz an der Küste vor Gefahren aus dem Inneren zu schützen.",al={"henry maleb","süderstade magistrat","wer ist maleb"}},{q="Warum ermittelt Maleb gegen das Syndikat?",a="Maleb übernahm sein Amt nach der Ermordung des vorherigen Magistrats von Süderstade. Seine Nachforschungen weisen auf gedungene Attentäter des Syndikats hin, die von gefallenen Adligen aus Alterac entsandt wurden, und er beauftragt aktiv Abenteurer der Allianz, um einem weiteren Mordanschlag auf sein Leben zuvorzukommen.",al={"warum syndikat","maleb syndikat","süderstade attentäter"}},{q="Wo ist Magistrat Maleb zu finden?",a="Er hält sich im Rathaus von Süderstade auf, das im südlichen Teil des Vorgebirges des Hügellands liegt.",al={"maleb standort","wo ist henry maleb","magistrat maleb finden"}},{q="Welchen Bedrohungen sieht sich Maleb in Hillsbrad gegenüber?",a="Neben der allgegenwärtigen Gefahr einer Expansion der Verlassenen aus dem Norden und Westen wird Maleb insbesondere von finsteren Mördern des Syndikats bedroht, die die Grenzen der Stadt belauern und den Untergang der Führung von Süderstade planen.",al={"süderstade bedrohungen","maleb feinde"}}},fx={a611609c={q="Warum ist Magistrat Henry Maleb in Süderstade?",a="Maleb wurde kürzlich nach der Ermordung des früheren Anführers der Stadt zum Magistrat von Süderstade ernannt. Er residiert im Rathaus von Süderstade, um die Siedlung zu verwalten, die Verteidigung der Stadt zu überwachen und die Untersuchungen der Allianz zu den Bedrohungen im Vorgebirge des Hügellands zu koordinieren.",al={"warum ist maleb in süderstade","grund für maleb in süderstade","magistrat maleb rathaus"}},["078ca783"]={q="Auf wessen Seite steht Magistrat Henry Maleb?",a="Magistrat Henry Maleb ist voll und ganz der Allianz ergeben. Als ziviler Magistrat von Süderstade dient er der örtlichen Gemeinde und ist den Behörden der Allianz verantwortlich; er arbeitet daran, die verbliebenen freien Menschen von Hillsbrad vereint und sicher vor den umliegenden Feinden zu halten.",al={"fraktion von magistrat maleb","maleb allianz oder horde","ist henry maleb allianz"}},b9806b6f={q="Was will Magistrat Henry Maleb?",a="Maleb will Süderstade vor der Zerstörung bewahren und den Raubzügen des Syndikats ein Ende setzen. Nachdem er sein Amt angetreten hat, nachdem sein Vorgänger ermordet wurde, ist er entschlossen, die Verschwörer zu identifizieren, ihre schattenhaften Attentäter aufzuspüren und die Alteraci-Adligen zu bestrafen, die die Komplotte gegen die Stadt leiten.",al={"ziele von henry maleb","was braucht maleb","ziel von magistrat maleb"}}},fp="22,313,30.640.0,24.434.1,30.175.0,41.278.0,36.121.0,42.222.0"}
P.entries["npc:magistrate-sevren"] = {n="Magistrat Sevren",s="Magistrat Sevren ist der oberste Verwaltungsbeamte, der die Siedlung Brill in Tirisfal leitet. Er steht im Rathaus, organisiert die frühe Verteidigung der Verlassenen und weist eintreffende Champions an, das Gebiet rund um Unterstadt zu stabilisieren.",h="Magistrat Sevren ist der oberste Verwaltungsbeamte, der die Siedlung Brill in Tirisfal leitet.",kw={"agamand","brill","verlassene","magistrat","sevren","tirisfal","rathaus","unterstadt"},ang={["faction:Horde"]="Verbündete der Horde, die in Tirisfal eintreffen, werden Sevren dabei antreffen, wie er die Befriedung an vorderster Front in Tirisfal gegen Banditen, Überreste der Geißel und Rebellengruppierungen koordiniert.",["race:Undead"]="Für neu befreite Verlassene, die Todesend verlassen, stellt Magistrat Sevren das bürgerliche Gesicht von Sylvanas' Reich dar und erteilt Euch Eure ersten großen Aufgaben zum Schutz Eurer Heimat."},sec={{t="Stadtmagistrat von Brill",b="Aus dem Rathaus in Brill heraus koordiniert Magistrat Sevren die Zivilbehörde und strategische Bemühungen in den Ländereien unmittelbar nördlich von Unterstadt. Wenn neue Verlassene nach Tirisfal heraustreten, beurteilt Sevren örtliche Krisen und entsendet Abenteurer, um die Ordnung wiederherzustellen, ruinierte Infrastruktur zu sichern und anhaltende Bedrohungen zu unterdrücken, die in den umliegenden Hügeln lauern."},{t="Sicherung der Gräber",b="Sevrens Hauptaugenmerk liegt auf der Bewahrung und Bergung der Toten von Tirisfal. Lokale Graverobbers, Rotfelle und abtrünnige Untote stören die Grabstätten und bedrohen die entstehende Herrschaft von Sylvanas Windläufer. Sevren stellt sicher, dass uralte Gräber – wie die Gruft der Familie Agamand – zurückgefordert werden und dass Deserteure oder unkooperative Kräfte die Autorität der Verlassenen in der Region nicht untergraben."}},faq={{q="Wer ist Magistrat Sevren?",a="Magistrat Sevren ist das Verwaltungsoberhaupt von Brill und im Rathaus stationiert. Er dient als Aufseher für die Gebietsverwaltung der Verlassenen und vergibt Aufgaben an Abenteurer, die aus Todesend eintreffen, um dem jungen Reich beizustehen.",al={"magistrat sevren","wer ist sevren","magistrat von brill"}},{q="Wo ist Magistrat Sevren zu finden?",a="Er befindet sich im Rathaus im Zentrum von Brill in Tirisfal.",al={"sevren aufenthaltsort","wo ist magistrat sevren","sevren finden"}},{q="Mit welchen Bedrohungen befasst sich Magistrat Sevren?",a="Sevren kämpft gegen lokale Bedrohungen für Tirisfal an, darunter mit der Geißel verbündete Rotfellgnolle, die Gräber plündern, Überreste der Geißel, die örtliche Grüfte entweihen, und abtrünnige untote Gestalten, die Fürstin Sylvanas die Gefolgschaft verweigern.",al={"sevren quests","was will sevren","probleme in brill"}},{q="Wem gilt Magistrat Sevrens Loyalität?",a="Er ist den Verlassenen treu ergeben und regiert Brill im Namen von Fürstin Sylvanas Windläufer und Unterstadt.",al={"sevren fraktion","wem dient sevren"}},{q="Warum schickt Sevren Abenteurer zur Familiengruft?",a="Die Grüfte der alten Agamand-Dynastie werden von Untoten und plündernden Bedrohungen überrannt. Sevren verlangt von Abenteurern, die Ruhestätten der Ahnen zu sichern, um zu verhindern, dass Feinde sie ausnutzen.",al={"agamand-gruft","sevren gruft-quest"}},{q="Hat Sevren Verbindungen zur Führung von Unterstadt?",a="Ja. Als örtlicher Magistrat steht er regelmäßig in Verbindung mit Agenten und Beamten aus Unterstadt, entsendet Boten und schickt Abenteurer tiefer in die Hauptstadt, sobald sie ihre Fähigkeiten in Brill unter Beweis gestellt haben.",al={"sevren unterstadt","sevren raleigh"}}},fx={["54ff886a"]={q="Was will Magistrat Sevren?",a="Als oberste zivile Autorität von Brill will Sevren das Tirisfal für die Verlassenen sichern. Er koordiniert die Bemühungen, die verbliebene Geißel auszurotten, Grabräuber zu stoppen, die die Ruhestätten der Verlassenen entweihen, und klare Befehls- und Versorgungslinien tiefer in das Königreich aufrechtzuerhalten.",al={"ziele von magistrat sevren","motive von sevren","was will sevren"}},["2465c638"]={q="Warum ist Magistrat Sevren in Brill?",a="Sevren leitet das Rathaus von Brill, um die lokale Verwaltung und Rechtsprechung direkt vor den Toren der Unterstadt zu beaufsichtigen. Er dient als primäre kommunale Autorität, die frisch erwachte und ankommende Verlassene in den Dienst leitet, um das Reich zu schützen und zu organisieren.",al={"warum ist sevren in brill","magistrat sevren rathaus","zweck von sevrens aufenthaltsort"}}},fp="17,260,24.369.0,19.396.0,25.236.0,37.78.0,46.220.0,39.102.0,53.204.0,50.212.0"}
P.entries["npc:magistrate-solomon"] = {fx={["85afa026"]={q="Auf wessen Seite steht Magistrat Solomon?",a="Solomon ist dem Königreich Sturmwind und der Großen Allianz loyal ergeben. Als zivile Autorität in Seenhain ist er dem königlichen Hof in Sturmwind unterstellt und bittet Hochlord Bolvar Fordragon um militärische Unterstützung, um sein Volk zu schützen.",al={"fraktion von magistrat solomon","wem dient solomon","loyalität von solomon"}},c7aa651d={q="Was will Magistrat Solomon?",a="Solomon sucht verzweifelt nach militärischer Hilfe und Ressourcen, um Seenhain vor der drohenden Vernichtung zu verteidigen. Eingekesselt von aggressiven Gnollrudeln und den vordringenden Schwarzfelsorks wünscht er sich Verstärkung aus Sturmwind und den benachbarten Siedlungen – oder fähige Abenteurer, die bereit sind, den Kampf zum Feind zu tragen.",al={"ziel von solomon","was braucht solomon","motivation von magistrat solomon"}}}}
P.entries["npc:magus-rimtori"] = {n="Magus Rimtori",s="Magus Rimtori ist eine abtrünnige Blutelfen-Zauberin, die eine Expedition durch die uralten Ruinen von Azshara anführt. Bekannt für ihre skrupellose Täuschung, manipulierte sie die Horde, um ihre Reise durch Kalimdor abzusichern, bevor sie ihre orkische Eskorte niedermetzelte.",h="Magus Rimtori ist eine abtrünnige Blutelfen-Zauberin, die eine Expedition durch die uralten Ruinen von...",kw={"azshara","belgrom","blutelf","hawkhelm","kim'jael","magus rimtori","rimtori","thalassischer stützpunkt"},ang={["class:Mage"]="Rimtori zeigt, wie weit thalassische Magi bei ihrer verzweifelten Suche nach arkaner Macht gehen, indem sie die Ruinen und dämonischen Relikte Kalimdors durchkämmen.",["faction:Horde"]="Rimtori manipulierte Belgrom und schlachtete die zu ihrem Schutz abkommandierte Orkwache ab, wodurch ihre Beseitigung zu einer obersten Priorität für Krieger der Horde wurde, die ihre gefallenen Brüder rächen wollen."},sec={{t="Eine tödliche Täuschung",b="Magus Rimtori führte eine Expedition adliger Blutelfen über das Meer an die uralten Küsten von Azshara. Um das Überleben ihrer Gruppe in den Gefahren Kalimdors zu sichern, manipulierte sie den Ork Belgrom, betörte und hinterging ihn, bis er einwilligte, eine bewaffnete Eskorte bereitzustellen. Sobald die Soldaten sie sicher an ihr Ziel geleitet hatten, zeigte Rimtori ihr wahres Gesicht, wandte sich gegen ihre Beschützer und massakrierte die gesamte Garnison. Nachdem sie ihre Streitkräfte im Thalassischen Stützpunkt eingerichtet hatte, brach sie in die Wildnis der Küste auf, begleitet von Eliteleibwächtern, um nach vergessenen magischen Artefakten zu suchen."},{t="Geheimnisse der Ruinen",b="Das wahre Motiv hinter Rimtoris Expedition bleibt im Dunkeln, doch ihre skrupellosen Methoden haben ihr zahllose Feinde eingebracht. Neben dem Verrat an der Horde hinterging sie auch einheimische Mietlinge, darunter den Goblin-Landvermesser Kim'jael, der behauptet, sie sei von der Entdeckung einer uralten Rune besessen gewesen. Umgeben von Relikten wie einem Folianten der Dämonenbeschwörung, der in ihrem Lager zurückgelassen wurde, hat Rimtoris Jagd nach Macht die erbitterte Vergeltung der Horde heraufbeschworen, die sie so kaltblütig hintergangen hat."}},faq={{q="Warum will die Horde Rimtori tot sehen?",a="Rimtori betörte und manipulierte den Ork Belgrom, damit er ihrer Expedition eine militärische Eskorte durch Kalimdor zur Verfügung stellte. Sobald sie sicher in Azshara angekommen waren, verriet und schlachtete sie jeden einzelnen orkischen Soldaten unter Belgroms Befehl ab.",al={"warum rimtori töten","belgrom rimtori lore","was tat rimtori der horde an"}},{q="Wo ist Magus Rimtori zu finden?",a="Während ihre Expedition den Thalassischen Stützpunkt errichtete, durchstreift Rimtori selbst in Begleitung ihrer persönlichen Blutelfen-Leibwächter die Wildnis von Azshara auf der Suche nach uralten Relikten.",al={"rimtori aufenthaltsort","wo ist magus rimtori","rimtori azshara aufenthaltsort"}},{q="Wonach suchte Rimtori in Azshara?",a="Dem Goblin Kim'jael zufolge, den sie anheuerte und daraufhin verriet, jagte Rimtori wie besessen nach einer geheimnisvollen uralten Rune, neben anderen mächtigen Relikten wie einem kaldoreischen Folianten der Beschwörung.",al={"was will rimtori","rimtoris ziel azshara","rimtori rune"}},{q="Wer ist Magister Hawkhelm?",a="Magister Hawkhelm ist ein Blutelfenoffizier, dem von Magus Rimtori die Leitung und Aufsicht über den Thalassischen Stützpunkt anvertraut wurde, während sie die umliegenden Ruinen untersucht.",al={"hawkhelm","thalassischer stützpunkt anführer","magister hawkhelm rimtori"}}},fp="13,241,18.585.0,20.485.1,37.236.0,33.191.0,42.198.0,25.163.0"}
P.entries["npc:mai-ah"] = {n="Mai'ah",s="Mai'ah ist eine Dschungeltroll-Magierausbilderin, die im sonnenverbrannten Becken des Tal der Prüfungen in Durotar stationiert ist. Sie unterweist angehende Zauberwirker unter den Dunkelspeer, die in die roten Schluchten treten, um ihre Beherrschung der arkanen Künste zu schulen. Jungen Trollen, die den Pfad der Zauberei beginnen, bietet sie frühe Anleitung und Unterweisung in den grundlegenden Künsten der Magie.",h="Mai'ah ist eine Dschungeltroll-Magierausbilderin, die im sonnenverbrannten Becken des Tal der Prüfungen in...",kw={"dunkelspeer","durotar","magierausbilder","mai'ah","maiah","troll","das tal der prüfungen"},ang={["class:Mage"]="Für Dunkelspeer-Zauberwirker repräsentiert Mai'ah den Beginn ihrer magischen Reise und lehrt die Disziplin, die nötig ist, um unter der harten Sonne von Durotar Feuer, Frost und arkane Energie zu weben.",["race:Troll"]="Mai'ah bietet Dunkelspeer-Jugendlichen im Tal der Prüfungen kulturelle Mentorenschaft in einer Kunst, die von ihren orcischen Verbündeten selten praktiziert wird."},sec={{t="Arkanmentorin des Höhlenbaus",b="Während Orcs überwiegend dem urtümlichen Ruf der Elemente oder der physischen Dominanz des Kriegers den Vorzug geben, besitzen Dunkelspeer eine seltene Affinität für das arkane Studium. Mai'ah steht im Tal der Prüfungen und dient als Ausbilderin für junge Trollmagier, die eintreffen, um ihre Riten des Erwachsenwerdens zu vollziehen. Sie nimmt Kandidaten entgegen, die Glyphic Parchment mit sich führen, und beginnt damit, ihre chaotische rohe Macht in disziplinierte Zauber zu formen, wobei sie sicherstellt, dass sie die Kontrolle erlernen, die zum Überleben der Gefahren in Durotar erforderlich ist."}},faq={{q="Wer ist Mai'ah?",a="Mai'ah ist eine Dunkelspeer-Trollmagierausbilderin, die sich im Tal der Prüfungen in Durotar befindet. Sie bietet neu eingetroffenen Trollzauberwirkern erste Anleitung, Training und grundlegende Zauber, bevor diese in die weiteren Länder der Horde aufbrechen.",al={"wer ist maiah","maiah lore","trollmagierausbilderin"}},{q="Warum gibt es eine Trollmagierausbilderin in einem Orc-Startgebiet?",a="Nachdem die Dunkelspeer ihre sinkende Inselheimat flohen und sich an der Seite von Thralls Orcs in Durotar neu ansiedelten, vollziehen junge Dunkelspeer ihre Prüfungen des Erwachsenwerdens zusammen mit Orc-Jugendlichen. Da die Orc-Kultur aufgrund früherer Dämonenkorruption arkane Magie weitgehend meidet, springen Trollmagier wie Mai'ah ein, um ihre eigene Art anzuleiten.",al={"warum trollmagier hier","trollausbilder tal der prüfungen","trollmagier durotar"}},{q="Welche Rolle spielt sie bei der Ausbildung neuer Magier?",a="Mai'ah heißt neue Trollmagier willkommen, die schriftliche Anweisungen wie Glyphic Parchment mit sich führen. Sie initiiert ihre formale Ausbildung und lehrt die Grundlagen des Zauberwirkens, damit sie das Tal der Prüfungen vor heimischen Bestien und abtrünnigen Infiltratoren der Burning Blade verteidigen können.",al={"was macht maiah","glyphic parchment maiah","maiah quests"}}},fx={["4a36b72a"]={q="Auf wessen Seite steht Mai'ah?",a="Mai'ah ist dem Stamm der Dunkelspeere und der Horde loyal ergeben. Stationiert im Tal der Prüfungen arbeitet sie unter dem neuen Regime von Thrall, um die zukünftigen Zauberkundigen der Horde zu fördern, und widmet ihr arkanes Wissen der Stärkung junger Trolle und verbündeter Magier.",al={"loyalität von mai'ah","wem dient mai'ah","ist mai'ah bei der horde"}},["648de549"]={q="Was will Mai'ah?",a="Mai'ah möchte angehende Praktizierende in den Grundlagen der arkanen Magie ausbilden. Sie versucht, junge Novizen durch ihre einleitenden Zauber und Glyphen zu führen und sicherzustellen, dass sie über die Disziplin und die magische Kraft verfügen, die nötig sind, um in Durotar zu überleben und der Horde zu dienen.",al={"was braucht mai'ah","ziele von mai'ah","warum unterrichtet mai'ah"}}},fp="6,368,24.501.0,14.245.0,58.314.0,46.263.0"}
P.entries["npc:major-mattingly"] = {n="Major Mattingly",s="Major Mattingly ist ein erfahrener Offizier der Armee von Sturmwind, der an den großen Toren im Tal der Helden stationiert ist. Unter dem Befehl von General Marcus Jonathan hilft er dabei, den Haupteingang der Hauptstadt zu sichern und fähige Handwerker dabei zu beraten, wie sie Helden vor drakonischen Gefahren schützen können.",h="Major Mattingly ist ein erfahrener Offizier der Armee von Sturmwind, der an den großen Toren im Tal der...",kw={"drachenschuppenumhang","marcus jonathan","major mattingly","mattingly","armee von sturmwind","das tal der helden"},ang={["class:Warrior"]="Als disziplinierter Veteran, der an den Stadttoren sein Langschwert führt, verkörpert Mattingly die standhafte Entschlossenheit der Infanterieoffiziere der Armee von Sturmwind.",["faction:Alliance"]="Für Champions der Allianz, die es wagen, mächtige Drachen wie Onyxia herauszufordern, liefert Major Mattingly die entscheidende Anleitung zur Herstellung von schützenden Umhängen aus Drachenschuppen."},sec={{t="Schildwache der Tore der Hauptstadt",b="Major Mattingly hält Wache im Tal der Helden und ist einer der hochrangigen Offiziere, die direkt für Sturmwinds wichtigste landseitige Verteidigung verantwortlich sind. Als ergrauter Veteran, dessen Gesicht die Züge hart erkämpfter Erfahrung trägt, dient er an der Seite der ständigen Garnison der Stadt unter General Marcus Jonathan. Neben seinen täglichen Pflichten bei der Überwachung der Torpatrouillen und ankommenden Reisenden verfügt Mattingly über spezielles taktisches Wissen über die tödliche Natur von Drachen. Erfahrenen Abenteurern gilt er als unverzichtbarer Ansprechpartner, wenn es darum geht, schützende Drachenschuppenausrüstung herzustellen, die für das Betreten der gefährlichsten Horte des Reiches erforderlich ist."}},faq={{q="Wo ist Major Mattingly zu finden?",a="Major Mattingly ist nahe dem Eingang von Sturmwind im Tal der Helden stationiert, wo er direkt hinter den Haupttoren an der Seite anderer Truppen der Garnison Wache hält.",al={"mattingly standort","wo ist major mattingly","major mattingly finden"}},{q="Welchen Rang und welche Rolle hat Major Mattingly in Sturmwind?",a="Er ist ein Offizier der Armee von Sturmwind, der unter General Marcus Jonathan dient. Er hilft bei der Überwachung der Verteidigung der Stadttore und steht Abenteurern mit militärischem Rat zur Seite.",al={"wer ist mattingly","mattingly beruf","was macht mattingly"}},{q="Warum suchen Lederverarbeiter Major Mattingly auf?",a="Mattingly besitzt Anleitungen zur Behandlung und Herstellung von Schuppenumhängen aus der Haut schwarzer Drachen und leitet erfahrene Handwerker an, die ihre Verbündeten vor drakonischen Flammen schützen wollen.",al={"onyxiaschuppenumhang mattingly","mattingly quest","die reise beginnt erst mattingly"}},{q="Ist Major Mattingly in größere Konflikte verwickelt?",a="Er ist ein kampferprobter Veteran des Königreichs Sturmwind, der sich der Verteidigung des Reiches verschrieben hat, während König Varian Wrynn weiterhin vermisst wird und das Königreich mit anhaltenden Bedrohungen ringt.",al={"mattingly hintergrund","mattingly lore"}}},fx={["3133ea98"]={q="Auf wessen Seite steht Major Mattingly?",a="Major Mattingly ist dem Königreich Sturmwind und der Allianz vollkommen ergeben. Als Offizier der Armee von Sturmwind ist er General Marcus Jonathan unterstellt und hält Wache am Haupteingang der Hauptstadt, loyal zum Thron und der Verteidigung des Reiches.",al={"fraktion von mattingly","wem dient mattingly","loyalität von major mattingly"}},["3a90c3f3"]={q="Warum ist Major Mattingly im Tal der Helden stationiert?",a="Er ist an den Toren im Tal der Helden stationiert, um die vorderste Verteidigungslinie der Hauptstadt zu überwachen. Unter den hoch aufragenden Monumenten für die Helden des Zweiten Krieges hilft Mattingly, die Wache am Torhaus zu befehligen und sicherzustellen, dass keine feindlichen Kräfte ungehindert durch die Tore marschieren.",al={"warum ist mattingly hier","warum ist mattingly im tal der helden","was macht mattingly in sturmwind"}},["728996ed"]={q="Mit wem ist Major Mattingly verbunden?",a="Major Mattingly dient direkt unter General Marcus Jonathan innerhalb der Befehlskette der Armee von Sturmwind. Er teilt zudem den Nachnamen mit Janice Mattingly, einer Bewohnerin der Stadt, obwohl seine täglichen Pflichten strikt an seinen militärischen Posten und seinen kommandierenden Offizier gebunden bleiben.",al={"kommandant von mattingly","wem untersteht mattingly","verbindungen von major mattingly"}}},fp="15,284,29.642.0,35.165.0,53.173.0,47.173.0,53.187.0"}
P.entries["npc:major-samuelson"] = {n="Major Samuelson",s="Major Samuelson ist ein hochrangiger Offizier der Stadtwache von Sturmwind, der im Thronsaal von Burg Sturmwind stationiert ist. Als erfahrener militärischer Kommandant beaufsichtigt er wichtige Personalangelegenheiten und diente zuvor jüngeren Offizieren wie Leutnant Farren Orinelle als Mentor.",h="Major Samuelson ist ein hochrangiger Offizier der Stadtwache von Sturmwind, der im Thronsaal von Burg...",kw={"farren orinelle","major samuelson","versetzung","samuelson","süderstade","wache von sturmwind","burg sturmwind"},ang={["faction:Alliance"]="Im königlichen Thronsaal dient Major Samuelson als administratives Rückgrat des Militärs von Sturmwind und koordiniert das Personal in umkämpften Gebieten wie Hillsbrad."},sec={{t="Eine Stütze der Wache von Sturmwind",b="Major Samuelson steht in Burg Sturmwind vor dem königlichen Hof und repräsentiert die Führung der Stadtwache von Sturmwind. Er überwacht Offiziersposten und administrative Militärbefehle im gesamten Reich. Insbesondere war er der Mentor von Leutnant Farren Orinelle, einem Offizier, der weit im Norden in Süderstade im Vorgebirge des Hügellands stationiert ist. Wenn jüngere Befehlshaber überfordert sind oder eine Versetzung aus fernen Grenzgarnisonen anstreben, gelangen ihre Gesuche und offiziellen Berichte quer durch das Königreich direkt auf den Schreibtisch von Major Samuelson in der Hauptstadt."}},faq={{q="Wer ist Major Samuelson?",a="Major Samuelson ist ein Offizier der Stadtwache von Sturmwind, der im Thronsaal von Burg Sturmwind stationiert ist. Er dient als administrativer Kommandant, der sich um Truppenstationierungen und Personalfragen von Offizieren kümmert.",al={"samuelson","major samuelson identität","wer ist der major in der feste"}},{q="Wo ist Major Samuelson zu finden?",a="Er befindet sich in Burg Sturmwind in Sturmwind und steht im Thronsaal in der Nähe des Kindkönigs Anduin Wrynn und von Hochlord Bolvar Fordragon.",al={"samuelson aufenthaltsort","wo ist major samuelson","samuelson finden"}},{q="Was verbindet ihn mit Süderstade?",a="Major Samuelson diente als Mentor von Leutnant Farren Orinelle, einem in Süderstade im Vorgebirge des Hügellands stationierten Offizier. Orinelle versucht über Samuelson, eine Versetzung von dem anstrengenden nördlichen Posten zu erwirken.",al={"samuelson süderstade","leutnant farren orinelle mentor","samuelson hillsbrad"}},{q="Warum suchen Abenteurer ihn auf?",a="Abenteurer, die von der nördlichen Front in Hillsbrad anreisen, überbringen Leutnant Farren Orinelles offizielles Versetzungsgesuch an Major Samuelson in Burg Sturmwind.",al={"sturmwind hq questabgabe","versetzungsquest","warum mit samuelson sprechen"}}},fx={["75428c69"]={q="Auf wessen Seite steht Major Samuelson?",a="Major Samuelson dient dem Königreich Sturmwind und der Allianz. Als Offizier innerhalb der Stadtwache von Sturmwind, der direkt in der Burg Sturmwind stationiert ist, besteht seine Pflicht darin, die Hauptstadt zu verteidigen, die militärische Ordnung aufrechtzuerhalten und die Befehle der Führung der Stadt auszuführen.",al={"fraktion von samuelson","wem dient major samuelson","ist samuelson bei der allianz"}}},fp="15,271,29.546.0,23.190.0,35.148.0,37.215.0,32.165.0"}
P.entries["npc:makaba-flathoof"] = {fx={["586aa360"]={q="Auf wessen Seite steht Makaba Flachhuf?",a="Makaba Flachhuf ist ein loyales Mitglied der Horde und des Taurenvolkes. Nachdem er vor der Gewalt geflohen ist, die seine Heimat traf, sucht er ausschließlich Unterstützung bei Reisenden und Champions der Horde, um seine Sippe zu schützen und gegen ihre Angreifer zurückzuschlagen.",al={"fraktion von makaba flachhuf","ist makaba bei der horde","wem dient makaba"}},["6e0e5223"]={q="Warum ist Makaba Flachhuf hier?",a="Makaba hat im Steinkrallengebirge Zuflucht gesucht, nachdem ihn im Camp Aparaje eine Tragödie heimgesucht hat. Von gewalttätigen Plünderern aus seiner Siedlung vertrieben, hält er sich nun hier auf und sucht Hilfe, um seine gefallenen Verwandten zu rächen und die Sicherheit von Überlebenden wie Kaya zu gewährleisten.",al={"warum ist makaba flachhuf hier","warum ist makaba im steinkrallengebirge","zweck von makaba flachhuf"}}}}
P.entries["npc:malfurion-stormrage"] = {n="Malfurion Sturmgrimm",s="Malfurion Sturmgrimm ist der erste sterbliche Druide und an der Seite von Hohepriesterin Tyrande Wisperwind der verehrte Anführer der Nachtelfen. Berühmt für den Sieg über die Brennende Legion sowohl im Krieg der Ahnen als auch im Dritten Krieg, wird er als Shan'do oder geehrter Lehrer verehrt. Derzeit liegt er in einem komatösen Schlummer im Smaragdgrünen Traum gefangen, sodass die Kaldorei ohne seine wache Führung auskommen müssen.",h="Malfurion Sturmgrimm ist der erste sterbliche Druide und an der Seite von Hohepriesterin Tyrande Wisperwind...",kw={"erzdruide","cenarius","smaragdgrüner traum","furion","hyjal","illidan","malfurion","shan'do","stormrage","tyrande"},ang={["class:Druid"]="Jeder Druide führt seine Lehren auf Malfurion zurück, der direkt von Cenarius lernte. Seine Abwesenheit im Smaragdgrünen Traum wirft einen schweren Schatten auf den Zirkel des Cenarius.",["class:Priest"]="Malfurion ist der geliebte Gefährte von Hohepriesterin Tyrande Wisperwind und vereint die spirituelle Hingabe an Elune mit der heiligen Wacht über die Natur.",["race:NightElf"]="Malfurion wird als uralter Beschützer und Retter Eures Volkes verehrt, wenngleich sein anhaltender Schlummer die Führung gänzlich Tyrande und Erz Druide Fandral Hirschhaupt überlässt."},sec={{t="Der erste Druide",b="Vor zehntausend Jahren, bevor die Große Zerschlagung das uralte Kalimdor zerbrach, lernte Malfurion unter dem Halbgott Cenarius. Während Königin Azshara und ihre Kaste der Hochgeborenen sich gefährlich tief in die arkanen Energien des Brunnens der Ewigkeit vertieften, wandte sich Malfurion den Urkräften der Natur zu und wurde Azeroths erster sterblicher Druide. Sein Misstrauen gegenüber den Hochgeborenen erwies sich auf tragische Weise als begründet, als Azsharas rücksichtslose Zauberei den Schleier durchstieß und Sargeras sowie die Brennende Legion nach Azeroth beschwor, was den verheerenden Krieg der Ahnen entfesselte."},{t="Retter von Kalimdor",b="Gemeinsam mit Cenarius, Tyrande Wisperwind und seinem Zwillingsbruder Illidan führte Malfurion den Widerstand an, der den Ansturm der Dämonen aufhielt und das Portal über dem Brunnen der Ewigkeit schloss. Nach der Zerschlagung der Welt verpflichtete Malfurion die Druiden dem Smaragdgrünen Traum, um Azeroths lebendiges Gefüge wieder aufzubauen und zu beschützen. Zehntausend Jahre später erweckte ihn Tyrande während des Dritten Krieges aus seinem langen Hügelgrab-Schlaf, um Archimonde die Stirn zu bieten, wo er am Hyjal die Waldgeister versammelte, um die Brennende Legion erneut zu zerschlagen."},{t="Im Traum verloren",b="Nach dem Dritten Krieg kehrte Malfurion in seinen Schlummer in der Mondlichtung zurück, um mit dem Smaragdgrünen Traum zu kommunizieren und seine erschöpfte Macht wieder aufzufüllen. Sein Geist konnte jedoch nicht in seinen physischen Körper zurückkehren, was ihn in einen unnatürlichen, komatösen Zustand stürzte. In Darnassus hat Erz Druide Fandral Hirschhaupt die weltlichen Führungsaufgaben im Zirkel des Cenarius übernommen, während Tyrande und die Schwesternschaft bangend auf Zeichen des Erwachens ihres großen Shan'do warten."}},faq={{q="Wo befindet sich Malfurion Sturmgrimm derzeit?",a="Malfurions Körper schläft in den Hügelgräbern der Mondlichtung, während sein Bewusstsein tief im Geistreich des Smaragdgrünen Traums gefangen bleibt. Er kann in Darnassus nicht als aktiver NSC besucht werden, da sein Körper komatös und für die meisten Abenteurer unzugänglich ist.",al={"wo ist malfurion","wo findet man malfurion","malfurion aufenthaltsort","ist malfurion im spiel"}},{q="Warum schläft Malfurion?",a="Druiden begeben sich regelmäßig in einen Winterschlaf im Smaragdgrünen Traum, um mit der Natur zu kommunizieren, die Flora und Fauna der Welt zu erhalten und ihre spirituellen Kräfte zu regenerieren. Nach der gewaltigen magischen Anstrengung beim Sieg über Archimonde am Hyjal trat Malfurion in den Traum ein, um sich zu erholen, doch ein unnatürliches Leiden hat seinen Geist von seinem Körper getrennt.",al={"warum schläft malfurion","warum ist er im koma","was geschah mit malfurion"}},{q="Wer regiert die Nachtelfen, während Malfurion schläft?",a="Hohepriesterin Tyrande Wisperwind regiert das Volk der Kaldorei vom Tempel des Mondes in Darnassus aus und führt die Schildwachen sowie die Schwesternschaft von Elune an. Unterdessen werden der Zirkel des Cenarius und die druidischen Angelegenheiten von Erz Druide Fandral Hirschhaupt beaufsichtigt.",al={"wer führt nachtelfen an","wer ist der nachtelfenanführer","nachtelfenherrscher"}},{q="Was bedeutet „Shan'do“?",a="Im Darnassischen bedeutet „Shan'do“ übersetzt „geehrter Lehrer“. Es ist ein Titel höchster Ehrfurcht, der Meisterdruiden vorbehalten ist – allen voran Malfurion Sturmgrimm, der den sterblichen Völkern unter der Führung von Cenarius erstmals das Druidentum brachte.",al={"bedeutung shando","was ist shando","shan'do"}},{q="Wer ist Malfurions Bruder?",a="Malfurions Zwillingsbruder ist Illidan Stormrage. Trotz ihrer gemeinsamen Jugend in Suramar sorgten Illidans Besessenheit von arkaner Magie und sein rücksichtsloses Streben nach dämonischer Macht während des Kriegs der Ahnen für ein bitteres Zerwürfnis zwischen ihnen, was Malfurion dazu veranlasste, ihn für Jahrtausende einzusperren.",al={"malfurions bruder","wer ist illidan für malfurion","stormrage brüder"}},{q="Was tat Malfurion in der Schlacht um den Hyjal?",a="Auf dem Höhepunkt des Dritten Krieges stieß Malfurion am Weltenbaum Nordrassil in das Horn des Cenarius und rief Tausende uralter Waldgeister (Irrlichter) herbei. Diese Geister umschwärmten den Dämonenlord Archimonde und detonierten, wodurch der Dämon vernichtet und der Weltenbaum verzehrt wurde, um Kalimdor zu retten.",al={"malfurion hyjal","schlacht um den hyjal malfurion","wie besiegte malfurion archimonde"}}},fx={["65d9a7b2"]={q="Wer ist Malfurion Sturmgrimm?",a="Malfurion Sturmgrimm ist der erste sterbliche Druide auf Azeroth und der oberste Erzdruide der Nachtelfen. Vor zehntausend Jahren vom Halbgott Cenarius ausgebildet, führte er sein Volk durch den kataklysmischen Krieg der Ahnen gegen Königin Azshara und die Brennende Legion. An der Seite seiner Geliebten, der Hohepriesterin Tyrande Wisperwind, führt er die Kaldorei seit Jahrtausenden und dient ihnen sowohl als geistiger Führer als auch als größter Verteidiger der natürlichen Welt.",al={"wer ist malfurion","wer ist furion","geschichte von malfurion sturmgrimm"}},af86ea6f={q="Auf wessen Seite steht Malfurion Sturmgrimm?",a="Malfurion steht an vorderster Front für sein Volk, die Kaldorei, und den Zirkel des Cenarius, der sich dem Erhalt der natürlichen Ordnung Azeroths verschrieben hat. Durch die jüngsten Pakte der Nachtelfen ist sein Volk mit der Großen Allianz verbündet, obwohl Malfurions ultimative Hingabe über kleinliche politische Streitigkeiten hinausgeht – seine lebenslange Pflicht ist es, das Gleichgewicht der Natur zu schützen und den Smaragdgrünen Traum vor Verderbnis zu bewahren.",al={"fraktion von malfurion","ist malfurion bei der allianz","welcher fraktion gehört malfurion an"}},["1592db0d"]={q="Was will Malfurion Sturmgrimm?",a="Über alles andere stellt Malfurion das Streben, das empfindliche natürliche Gleichgewicht Azeroths zu schützen und den Smaragdgrünen Traum vor dunklen Mächten sicher zu halten. Da er zehntausend Jahre lang so viel geopfert hat, um die vernarbte Erde zu heilen und dämonische Einfälle zu besiegen, ist sein Leben an den Schutz der Wildnis, die Pflege des Weltenbaums und das Leiten der Nachtelfen auf einem Pfad im Einklang mit der Natur gebunden.",al={"ziel von malfurion","was sind malfurions ziele","zweck von malfurion"}}},fp="19,403,15.549.0,18.530.0,17.461.0,39.270.0,24.330.0,49.248.0,25.229.0,27.276.0,51.294.0"}
P.entries["npc:mangletooth"] = {n="Quetschzahn",s="Quetschzahn ist ein gefangener Stacheleber der Razormane, der von der Horde in Camp Taurajo festgehalten wird. Vor seiner Hinrichtung stehend, tauscht er strategische Informationen über seine Rivalen und das uralte Wissen über Agamaggan mit Abenteurern aus, die bereit sind, seine Befehle auszuführen.",h="Quetschzahn ist ein gefangener Stacheleber der Razormane, der von der Horde in Camp Taurajo festgehalten wird.",kw={"agamaggan","brachland","blutscherben","bristleback","camp taurajo","quetschzahn","stacheleber","razormane"},ang={["faction:Horde"]="Die Wachen von Camp Taurajo halten Quetschzahn unter strenger Bewachung eingesperrt, doch die Horde ist bereit, den bitteren Groll des Gefangenen zu nutzen, um die Hochburgen der Stacheleber im gesamten Brachland zu zerschlagen.",["race:Tauren"]="Taurenjäger geraten in den Ebenen ständig mit den Stachelebern aneinander, weshalb Quetschzahns Bereitschaft, sich gegen seine eigene Art zu wenden, ein wertvoller, wenn auch beunruhigender militärischer Vorteil ist."},sec={{t="Eine Geisel in Ketten",b="In einem Käfig in Camp Taurajo von Taurenjägern und Orc-Schildwachen bewacht, wartet der gefangene Razormane-Stacheleber Quetschzahn auf seine Hinrichtung. Anstatt sich in den Tod zu fügen, versucht er, seine Wärter und durchreisende Horde-Abenteurer dazu zu manipulieren, die Feinde seines Stammes niederzustrecken, in der Hoffnung, dass seine Schläue seinen Wert beweist oder seine Rettung sichert."},{t="Verräter in den eigenen Reihen",b="Quetschzahn plant zunächst, sich die Dankbarkeit seines Clans zu verdienen, indem er die Muskelkraft der Horde auf den verfeindeten Stamm der Bristleback lenkt. Bald muss er jedoch erkennen, dass seine Mit-Anführer der Razormane – Nak, Kuz und Lok Orcbane – ihn völlig im Stich gelassen haben. Wütend über diesen Verrat wendet der gefangene Stacheleber seine Rache gegen das eigene Volk und beauftragt Abenteurer damit, seine ehemaligen Verbündeten hinzurichten."},{t="Die Macht der Blutscherben",b="Quetschzahn ist bestens mit der religiösen Geschichte seines Volkes vertraut und weiß, dass die riesigen Dornen im Brachland einst aus dem vergossenen Blut von Agamaggan während des uralten Kriegs der Ahnen emporwuchsen. Indem er rote, kristalline Blutscherben von gefallenen Bristleback sammelt, kanalisiert Quetschzahn die verbliebene göttliche Energie des gefallenen Ebergottes und verleiht jenen, die ihm beistehen, gewaltige uralte Segen."}},faq={{q="Wer ist Quetschzahn?",a="Quetschzahn ist ein gefangener Stacheleber der Razormane, der in einem Käfig in Camp Taurajo festgehalten wird. Angesichts seiner bevorstehenden Hinrichtung durch die Horde feilscht er mit Abenteurern und bietet Führung sowie uralte Segen im Austausch für die Beseitigung seiner Rivalen.",al={"quetschzahn","wer ist quetschzahn","eingesperrter stacheleber taurajo"}},{q="Warum sitzt Quetschzahn in einem Käfig?",a="Er wurde während der Zusammenstöße zwischen der Horde und den Stachelebern im Südlichen Brachland gefangen genommen. Die Tauren und Orcs in Camp Taurajo halten ihn bis zu seiner Hinrichtung gefangen.",al={"warum ist quetschzahn gefangen","warum im käfig","warum taurajo gefangener"}},{q="Warum verlangt Quetschzahn den Angriff auf andere Razormane-Stacheleber?",a="Quetschzahn hat erkannt, dass seine Clangefährten Nak, Kuz und Lok Orcbane ihn dem Tod überließen, anstatt eine Rettung zu wagen. Erzürnt über ihren Verrat beauftragt er Reisende aus reiner Rachsucht mit ihrer Hinrichtung.",al={"warum razormane angreifen","verräter in den eigenen reihen lore","warum nak kuz töten"}},{q="Was sind Blutscherben?",a="Blutscherben sind kristalline Mineralien, die dort entstanden sind, wo das Blut des Großen Halbgottes Agamaggan in die Erde sickerte, als er während des Kriegs der Ahnen fiel. Bristleback-Stacheleber tragen sie oft bei sich.",al={"blutscherben","blutscherben lore","agamaggan blut"}},{q="Was kann man mit Blutscherben bei Quetschzahn tun?",a="Bringt Ihr Quetschzahn Blutscherben, kanalisiert er Agamaggans heilige Macht in temporäre Segen, die erhöhte Stärke, Beweglichkeit, Ausdauer, Willenskraft oder Schnelligkeit gewähren.",al={"blutscherben buffs","blutscherben abgeben","was gibt quetschzahn"}},{q="Wo starb Agamaggan laut Quetschzahn?",a="Quetschzahn berichtet, dass Agamaggan in der Schlacht während des Kriegs der Ahnen fiel. Sein vergossenes Blut ließ die gewaltigen Dornenranken sprießen, und sein kolossaler Schädel überwölbt eine Höhle im Süden.",al={"agamaggan lore","wo fiel agamaggan","ebergott schädel"}}},fx={d88e6e26={q="Auf wessen Seite steht Quetschzahn?",a="Quetschzahn dient nur sich selbst. Obwohl er von den Stachelmähnen-Ebermenschen abstammt, hegt er keine wahre Liebe für die Horde, die ihn gefangen nahm, noch anhaltende Loyalität gegenüber seinem eigenen Stamm, als er erkennt, dass seine Stammesgenossen ihn im Stich gelassen haben. Er kooperiert nur als verzweifeltes Mittel zum Überleben mit den Abenteurern der Horde, um zu überleben und gegen seine Rivalen zurückzuschlagen.",al={"seite von quetschzahn","wem gegenüber ist quetschzahn loyal","ist quetschzahn bei der horde"}},["7791b01e"]={q="Was will Quetschzahn?",a="Da ihm im Camp Taurajo die Hinrichtung droht, zielt Quetschzahn zunächst darauf ab, zu überleben und die Vorherrschaft seines Stammes über seine Borstennacken-Rivalen zu beweisen, in der Hoffnung, dass sein Volk ihn retten wird. Als er erkennt, dass seine Anführer der Stachelmähnen – Nak, Kuz und Lok Orcbane – ihn im Stich gelassen haben, wandeln sich seine Wünsche in bittere Rache und das Sammeln der heiligen Macht von Blutsplittern.",al={"was will quetschzahn","ziel von quetschzahn","was versucht quetschzahn zu tun"}},["1234667b"]={q="Mit wem ist Quetschzahn verbunden?",a="Quetschzahn gehört zu den Stachelmähnen-Ebermenschen des Südlichen Brachlands. Sein Schicksal ist mit seinen Stammesrivalen Nak, Kuz und Lok Orcbane verflochten, deren Verrat seinen Zorn antreibt. Er verehrt zudem den uralten Eber-Gott Agamaggan, dessen verstreute Essenz es Quetschzahn erlaubt, denjenigen Segnungen zu verleihen, die ihm Relikte des Blutes des gefallenen Gottes bringen.",al={"verbindungen von quetschzahn","wen kennt quetschzahn","stamm von quetschzahn"}}},fp="11,237,19.339.0,20.389.1,25.399.0,19.213.0,29.171.0,64.201.1,22.209.0,49.182.0,42.201.0"}
P.entries["npc:mankrik"] = {n="Mankrik",s="Mankrik ist ein von Trauer überwältigter Orc-Krieger, der im Wegekreuz im Brachland stationiert ist. Nachdem ihn ein heimtückischer Hinterhalt der Quilboar von seiner Frau Olgra getrennt hatte, widmete er sein Leben der Rache und der Vernichtung jeder borstigen Bestie, die er finden kann.",h="Mankrik ist ein von Trauer überwältigter Orc-Krieger, der im Wegekreuz im Brachland stationiert ist.",kw={"brachland","das wegekreuz","goldstraße","mankrik","olgra","quilboar","thork"},ang={["faction:Horde"]="Für Reisende, die im Wegekreuz ankommen, dient Mankriks Not als eindringliche Warnung vor der unerbittlichen Bedrohung durch die borstigen Quilboar-Rudel im gesamten Brachland.",["race:Orc"]="Mankrik verkörpert den verheerenden Preis für die Besiedlung der wilden Grenzlande von Kalimdor, wo Familie und Ehre ständig gegen brutale einheimische Gefahren auf die Probe gestellt werden."},sec={{t="Hinterhalt im Staub",b="Auf ihrer Reise durch das Buschland des Brachlands wurden Mankrik und seine Frau Olgra während eines Scharmützels in einer kleinen Taurensiedlung von Scharen von Quilboar überrannt. Im Chaos und den erbitterten Kämpfen getrennt, sah Mankrik mit an, wie Olgra unter einer Flut von Hauern und dornenbewehrten Waffen verschwand. Von Wut übermannt, kämpfte er rücksichtslos, bis er bewusstlos niedergeschlagen wurde. Er überlebte nur, weil ein vorbeiziehender Tauren-Druide ihn verblutend an der Goldstraße fand und seine Wunden verband."},{t="Von Rache zerfressen",b="Während er sich im Wegekreuz erholte, war Mankrik gelähmt von Trauer und einer alles verzehrenden Blutgier. Obwohl örtliche Anführer wie Thork warnen, dass sein blinder Hass sein Urteilsvermögen trübt, und sich weigern, offizielle Kriegstrupps aufzustellen, lässt Mankrik nicht von seinem Vorhaben ab. Geplagt von der Ungewissheit über Olgras Schicksal, heuert er jeden hilfsbereiten Reisenden der Horde an, das Brachland nach Spuren seiner verlorenen Gefährtin abzusuchen und jeden Quilboar abzuschlachten, der ihren Weg kreuzt."}},faq={{q="Wer ist Mankrik?",a="Mankrik ist ein Orc-Krieger, der sich im Wegekreuz im Brachland aufhält. Er überlebte einen brutalen Hinterhalt der Quilboar, der ihn von seiner Frau trennte, und ist seither von Zorn zerfressen und auf Rache für sie aus.",al={"mankrik lore","wer ist mankrik","mankrik geschichte"}},{q="Was geschah mit Mankriks Frau?",a="Während eines Gefechts in einer Taurensiedlung wurden Mankrik und Olgra durch eine Übermacht an Quilboar voneinander abgeschnitten. Mankrik wurde im Chaos niedergestreckt, und Olgra ging in den Wirren der Kämpfe verloren.",al={"mankriks frau","wo ist mankriks frau","was geschah mit olgra","olgras schicksal"}},{q="Wie überlebte Mankrik den Kampf?",a="Nachdem er unter Scharen von Quilboar das Bewusstsein verloren hatte, wurde Mankrik von einem umherziehenden Tauren-Druiden zusammengebrochen auf der Goldstraße gefunden, der seine schweren Wunden versorgte und ihn in Sicherheit brachte.",al={"wie überlebte mankrik","wer rettete mankrik"}},{q="Warum weigert sich Thork, Mankrik zu helfen?",a="Thork, der Anführer im Wegekreuz, glaubt, dass Mankriks maßlose Wut und sein Rachedurst sein Urteilsvermögen vollkommen vernebelt haben und ihn daran hindern, vernünftig zu handeln.",al={"warum hilft thork nicht","thork und mankrik"}}},fx={["63979fed"]={q="Auf wessen Seite steht Mankrik?",a="Mankrik ist der Horde gegenüber loyal. Von Das Wegekreuz im Brachland aus operierend, verlässt er sich auf Reisende und Abenteurer der Horde, die ihm bei seiner verzweifelten Suche helfen und gegen die Stacheleber zurückschlagen, die ihr Land bedrohen.",al={"mankrik fraktion","ist mankrik horde","mankrik allianz oder horde"}},["20b8339c"]={q="Was will Mankrik?",a="Mankrik möchte das Schicksal seiner verschollenen Frau Olgra erfahren und so viele Stacheleber wie möglich töten. Nachdem er bei einem Hinterhalt von ihr getrennt wurde, ist er von Trauer, Wut und einem Bedürfnis nach Rache gegen die borstigen Plünderer erfüllt.",al={"wonach sucht mankrik","mankrik ziel","was braucht mankrik"}},["5eb75604"]={q="Warum ist Mankrik hier am Wegekreuz?",a="Nach einem Angriff der Stacheleber, bei dem er schwer verwundet wurde, zog ein vorbeikommender Taurendruide Mankrik die Goldstraße entlang in Sicherheit. Mankrik bleibt nun am Wegekreuz, da ihn seine Verletzungen und die anhaltende Ungewissheit in der Nähe des Ortes halten, an dem er seine Frau zuletzt gesehen hat.",al={"warum ist mankrik am wegekreuz","grund für mankriks aufenthaltsort","warum ist mankrik im brachland"}},d34d6f35={q="Mit wem ist Mankrik verbunden?",a="Mankrik ist durch Liebe und Trauer mit seiner Frau Olgra verbunden, an deren Seite er kämpfte, bevor sie von Stachelebern überrannt wurden. Er verdankt sein Leben zudem dem umherwandernden Taurendruiden, der seine Wunden auf der Goldstraße versorgte.",al={"mankriks beziehungen","mit wem ist mankrik verbunden","mankriks familie"}}},fp="7,244,18.488.0,21.432.0,15.194.0,32.198.0,35.186.0,38.175.0"}
P.entries["npc:marcus-redpath"] = {fx={["0aeeadbf"]={q="Auf wessen Seite steht Marcus Redpath?",a="Marschall Marcus Redpath dient der Allianz und den Überlebenden von Lordaeron, die sich unter dem Banner von Süderstade versammelt haben. Als Stadtmarschall von Süderstade steht er fest an der Seite der menschlichen Verteidiger, die die Hillsbrad-Front gegen feindliche Bedrohungen in den Ausläufern halten.",al={"marcus redpath fraktion","welcher fraktion gehört marcus redpath an","wem dient redpath"}},["43107ef7"]={q="Was will Marcus Redpath?",a="Redpath möchte Süderstade und das umliegende Land vor eindringenden Gefahren schützen. Er leitet aktiv Soldaten und Abenteurer an, regionale Bedrohungen zu beseitigen, die Ogerstämme der Crushridge aus den nördlichen Bergen zurückzudrängen und die Murloc- und Naga-Plagen auszurotten, die die Küste heimsuchen.",al={"marcus redpaths ziele","was braucht redpath","marcus redpaths aufgabe"}}}}
P.entries["npc:mardant-strongoak"] = {n="Mardant Starkeiche",s="Mardant Starkeiche ist ein Druidenlehrer der Nachtelfen, der in Aldrassil im Herzen von Teldrassil weilt. Er leitet angehende Druiden bei der Zwiesprache mit den Geistern der Natur an und weiht sie in die Geheimnisse des Smaragdgrünen Traums ein.",h="Mardant Starkeiche ist ein Druidenlehrer der Nachtelfen, der in Aldrassil im Herzen von Teldrassil weilt.",kw={"aldrassil","druide","smaragdgrüner traum","mardant","laubschattental","strongoak","teldrassil","lehrer"},ang={["class:Druid"]="Für junge Nachtelfen-Druiden ist Mardant Starkeiche die erste Brücke zwischen dem weltlichen Dasein und den heiligen Pflichten des Zirkels des Cenarius.",["race:NightElf"]="Im Herzen von Aldrassil stationiert, verkörpert Mardant die Hingabe der Kaldorei, mit Teldrassils aufblühendem Ökosystem in Einklang zu leben."},sec={{t="Ausbilder der Wildnis",b="In den Ästen von Aldrassil wenden sich junge Nachtelfen, die den Ruf der Wildnis vernehmen, an Mardant Starkeiche. Seine Hauptaufgabe besteht darin, Novizen beizubringen, ihre Sinne für die Naturgeister zu öffnen, deren Flüstern zu deuten und verjüngende Magie zu wirken. Für jene, die ihre ersten Schritte als Beschützer der Wildnis wagen, ist er oft der erste Meister, der die gewaltigen Tiefen und uralten Gefahren des Smaragdgrünen Traums enthüllt."}},faq={{q="Wer ist Mardant Starkeiche?",a="Mardant Starkeiche ist ein Druidenlehrer der Nachtelfen, der in Laubschattental in Aldrassil stationiert ist. Er unterweist neu erwachte Druiden auf Teldrassil in den grundlegenden Künsten der Zwiesprache und des Zauberwirkens.",al={"mardant starkeiche lore","wer ist mardant","mardant aldrassil"}},{q="Was lehrt er neue Druiden?",a="Er lehrt Novizen, wie sie die Botschaften der wilden Geister entschlüsseln, grundlegende Zauber wie Mondfeuer und Heilkünste wirken und das Wesen des Smaragdgrünen Traums erfassen.",al={"was lehrt mardant","mardant fähigkeiten","druidenlehrer laubschattental"}},{q="Wo kann ich Mardant Starkeiche finden?",a="Er befindet sich innerhalb oder nahe Aldrassil in Laubschattental, dem Starttal für Nachtelfen-Abenteurer auf Teldrassil.",al={"mardant aufenthaltsort","wo ist mardant starkeiche"}},{q="Was ist das Tiefgrüne Siegelzeichen?",a="Das Tiefgrüne Siegelzeichen ist ein Lehrabzeichen, das angehenden Nachtelfen-Druiden in Laubschattental überreicht wird und sie anweist, Mardant Starkeiche für ihre frühe Ausbildung aufzusuchen.",al={"quest tiefgrünes siegelzeichen","siegelzeichen für mardant"}}},fx={a3bbc1b2={q="Auf wessen Seite steht Mardant Starkeiche?",a="Mardant Starkeiche ist den Nachtelfen, der Allianz und den heiligen Grundsätzen des Zirkels des Cenarius ergeben. Er steht fest im Laubschattental, um den jungen Weltenbaum zu schützen und sicherzustellen, dass die Traditionen der Kaldorei-Druiden in diesen unsicheren Zeiten fortbestehen.",al={"mardant starkeiche fraktion","wem dient mardant","ist mardant allianz"}},ff8559f4={q="Was will Mardant Starkeiche?",a="Mardant möchte, dass junge Nachtelfen-Initianden ihre Verbindung zur Natur vertiefen. Er versucht, neue Druiden durch ihre ersten Prüfungen zu führen und ihnen dabei zu helfen, das Flüstern der Geister zu entschlüsseln sowie die tiefgreifenden Geheimnisse und Gefahren des Smaragdgrünen Traums zu meistern.",al={"was will mardant","mardant starkeiches ziele","was ist mardants ziel"}},b78651d9={q="Warum ist Mardant Starkeiche hier?",a="Stationiert in den hohlen Ästen von Aldrassil, dient Mardant als Mentor für neu erwachte Druiden, die ihre ersten Schritte in Teldrassil machen. Er bleibt im Laubschattental, um über die Novizen zu wachen, sie in ihren angeborenen Kräften zu unterweisen und sie zu denjenigen zu schicken, die Hilfe benötigen.",al={"warum ist mardant in aldrassil","warum ist mardant starkeiche hier","grund für mardant starkeiches aufenthaltsort"}},dec3bef7={q="Mit wem ist Mardant Starkeiche verbunden?",a="Mardant ist eng mit dem Zirkel des Cenarius und seinen Mitlehrenden in Aldrassil verbunden, wie etwa den Priesterinnen der Elune und den Wächterinnen, die das Sanktuarium beschützen. Gemeinsam leiten und fördern sie die jungen Verteidiger der Nachtelfen.",al={"mardant starkeiches verbündete","mit wem ist mardant verbunden","mardants verbindungen"}}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marek-ironheart"] = {n="Marek Eisenherz",s="Marek Eisenherz ist ein erfahrener zwergischer Jäger, der in der Weitschreiter-Lodge im südöstlichen Loch Modan stationiert ist. Er ist den Traditionen der Wildnis verpflichtet und prüft sowohl wandernde Reisende als auch Schützen, bevor er sie in die Reihen der angesehenen Jäger der Lodge aufnimmt.",h="Marek Eisenherz ist ein erfahrener zwergischer Jäger, der in der Weitschreiter-Lodge im südöstlichen Loch...",kw={"krokiliskenjagd","die weitschreiter-lodge","jäger","jagd","ironheart","loch modan","marek eisenherz"},ang={["class:Hunter"]="Für Waldläufer und Bestienjäger repräsentiert Marek Eisenherz die rauen Traditionen der Weitschreiter-Lodge und fordert Jäger dazu auf, ihre Treffsicherheit und ihre Fähigkeiten als Fährtenleser an der lokalen Tierwelt unter Beweis zu stellen.",["race:Dwarf"]="Marek verkörpert die Kultur der Naturfreunde, die von vielen Zwergen in Khaz Modan geschätzt wird, indem er die stille Wache in den Bergen dem lärmenden Schmiedefeuer von Eisenschmiede vorzieht."},sec={{t="Meister der Jagd",b="Die auf dem malerischen Grat mit Blick auf den See gelegene Weitschreiter-Lodge dient als Außenposten für die besten Schützen und Fährtenleser in den Zwergenlanden. Marek Eisenherz verkörpert diesen Pioniergeist. Marek ist von Titeln oder Gerede unbeeindruckt und verlangt von jedem, der den Respekt der Lodge sucht, dass er sein praktisches Können an den verschiedenen Bestien beweist, die Loch Modan durchstreifen, um zu beweisen, dass er die Geduld und die Nerven besitzt, die von einem wahren Jäger der Wildnis gefordert werden."}},faq={{q="Wer ist Marek Eisenherz?",a="Marek Eisenherz ist ein zwergischer Jäger, der in der Weitschreiter-Lodge in Loch Modan lebt. Er prüft Besucher, die Anerkennung in der Gemeinschaft der Fährtenleser und Naturfreunde der Lodge suchen.",al={"marek eisenherz","wer ist marek"}},{q="Wo finde ich Marek Eisenherz?",a="Er befindet sich in der Weitschreiter-Lodge, die in den Hügeln am südöstlichen Ufer von Loch Modan liegt.",al={"standort marek eisenherz","wo ist marek"}},{q="Welche Art von Aufgaben bietet Marek an?",a="Marek weist Jäger an, verschiedene lokale Wildtiere rund um den Loch aufzuspüren und zu dezimieren, wobei er ihre Überlebensfähigkeiten gegen gefährliche Krokolisken testet.",al={"marek eisenherz quests","marek quests"}},{q="Ist Marek mit anderen bekannten Zwergen verwandt?",a="Da er einen bekannten zwergischen Nachnamen trägt, könnte er mit dem Archäologen Adamant Ironheart und Imme Ironheart verwandt sein, obwohl Marek sein Leben der Jagd widmet und nicht der Ausgrabung von Relikten.",al={"familie ironheart","marek verwandte"}}},fx={ac3880c9={q="Auf wessen Seite steht Marek Eisenherz?",a="Marek steht an der Seite der Allianz und der Zwergenklans von Eisenschmiede. Von der Die Weitschreiter-Lodge in der südöstlichen Wildnis von Loch Modan aus operierend, heißt er andere Abenteurer der Allianz willkommen, damit sie ihr Können beweisen, indem sie die umliegende Wildnis meistern.",al={"marek eisenherz fraktion","marek eisenherz allianz","ist marek eisenherz allianz"}},["2928b65a"]={q="Was will Marek Eisenherz?",a="Marek arbeitet von der Die Weitschreiter-Lodge in Loch Modan aus, wo er Jäger dazu einlädt, Jagd auf die Krokoliske rund um den Loch zu machen.",al={"was will marek","marek eisenherz ziele","warum sollte man mit marek eisenherz sprechen"}},ddec60fb={q="Warum ist Marek Eisenherz bei der Die Weitschreiter-Lodge?",a="Marek hat sein Zuhause in der Die Weitschreiter-Lodge, um Waldläufer in den ungezähmten Hügeln von Loch Modan zu prüfen und auszubilden. Von diesem abgelegenen Außenposten aus wacht er über die lokale Tierwelt und führt Jäger, die ihre Fähigkeiten in der Wildnis der Hochlande verfeinern wollen.",al={"warum ist marek in loch modan","marek eisenherz zweck der die weitschreiter-lodge","warum ist marek hier"}}},fp="15,264,18.444.0,23.177.0,33.104.0,36.144.0,44.176.0"}
P.entries["npc:marisa-du-paige"] = {n="Marisa du'Paige",s="Marisa du'Paige ist eine seltene abtrünnige menschliche Zauberin, die im weitläufigen Höhlennetzwerk vor dem Eingang zu den Todesminen im südwestlichen Westfall lauert. Verbündet mit den Gesetzlosen, die unter Mondbruch operieren, wirkt sie arkane Magie an der Seite der Arbeiter und Wegelagerer, die die Tunnel bewachen.",h="Marisa du'Paige ist eine seltene abtrünnige menschliche Zauberin, die im weitläufigen Höhlennetzwerk vor dem...",kw={"die todesminen","mensch","magier","marisa du'paige","marisa dupaige","mondbruch","selten","westfall"},ang={["class:Mage"]="Marisa du'Paige ist eine Erinnerung daran, dass arkane Ausbildung im Königreich nicht auf die Türme der Kirin Tor oder das Magiersanktum von Sturmwind beschränkt ist; abtrünnige Zauberwirker verkaufen ihre Talente bereitwillig an kriminelle Netzwerke.",["faction:Alliance"]="Abenteurer der Allianz, die die Tunnel unter Mondbruch auskundschaften, müssen vor du'Paige auf der Hut sein, da eine unerwartete Zauberin inmitten von Horden von Beutelschneidern ein Scharmützel schnell tödlich enden lassen kann."},sec={{t="Arkanes Talent in den Tunneln",b="Tief in den verwinkelten Höhlen, die zu den Todesminen unter Mondbruch führen, sind die meisten Verteidiger raubeinige Beutelschneider, abtrünnige Minenarbeiter und Schläger. Marisa du'Paige sticht unter ihnen als geschickte menschliche Magierin hervor. Während die meisten Zauberwirker des Königreichs in den sanktionierten Hallen von Sturmwinds Magierviertel trainieren oder den Kirin Tor dienen, hat sich du'Paige den Gesetzlosen und Banditen angeschlossen, die sich in den unterirdischen Tiefen von Westfall verstecken."}},faq={{q="Wer ist Marisa du'Paige?",a="Marisa du'Paige ist eine seltene menschliche Magierin, die im äußeren Höhlensystem lauert, das in die Todesminen führt. Im Gegensatz zu den typischen gewöhnlichen Dieben und Arbeitern, die diese Gänge patrouillieren, setzt sie arkane Zauber zur Verteidigung des unterirdischen Netzwerks ein.",al={"marisa dupaige","wer ist marisa","selten in todesminen-höhle"}},{q="Wo ist sie zu finden?",a="Sie erscheint unregelmäßig im öffentlichen Höhlensystem unter Mondbruch in Westfall, in den Tunneln kurz vor der Portalschwelle der Instanz Die Todesminen.",al={"marisa du'paige aufenthaltsort","wo ist marisa dupaige","marisa spawn"}},{q="Warum versteckt sich eine menschliche Magierin in den Höhlen der Todesminen?",a="Nicht jeder arkan Kundige bleibt den hohen Türmen von Sturmwind treu. Deserteure, Abtrünnige und sympathisierende Bürgerliche haben sich überall in Westfall der Sache der Gesetzlosen angeschlossen und stellen ihren Befestigungen unter Mondbruch sowohl Stahl als auch Zauberei zur Verfügung.",al={"warum ist sie hier","marisa lore","marisa dupaige fraktion"}}},fx={["5e8e0d23"]={q="Auf welcher Seite steht Marisa du'Paige?",a="Marisa du'Paige trägt die Gewänder der The Defias Brotherhood und wandelt durch die unterirdischen Hallen der Organisation. Sie lauert tief in den Höhlen von Mondbruch, die zu den Todesminen führen, und unterstützt die aufrührerische Bruderschaft von Edwin van Cleef, indem sie ihre arkanen Zauber gegen jeden Eindringling einsetzt, der ihre Festung bedroht.",al={"marisa dupaige fraktion","ist marisa dupaige defias","für wen arbeitet marisa dupaige"}}},fp="15,299,28.436.0,23.241.0,23.162.0,50.248.0"}
P.entries["npc:marleth-barleybrew"] = {n="Marleth Gerstenbräu",s="Marleth Gerstenbräu ist eine ehrgeizige Zwergenbrauerin, die in Bräuhall stationiert ist. Frustriert über die Dominanz des Donnerbräu-Klans auf dem lokalen Biermarkt schmiedet sie ständig Pläne, um zu beweisen, dass das Gebräu ihrer Familie Kharanos' berühmtem Donnerbier überlegen ist.",h="Marleth Gerstenbräu ist eine ehrgeizige Zwergenbrauerin, die in Bräuhall stationiert ist.",kw={"bittere rivalen","brewnall","zwergenbrauer","kharanos","marleth gerstenbräu","donnerbier","donnerbräu"},ang={["race:Dwarf"]="Für Zwerge ist das Brauen eine Kunstform, die eng mit dem Prestige des Klans verknüpft ist, was Marleths Fehde mit den Donnerbräus zu einer Frage heftigen Familienstolzes macht."},sec={{t="Die Brau-Rivalität",b="In Dun Morogh nimmt man Alkohol so ernst wie Stahl, und die Rivalität zwischen den Familien Gerstenbräu und Donnerbräu ist legendär. Marleth Gerstenbräu ärgert sich über das Beinahe-Monopol, das Ragnar Donnerbräu und seine Sippe von der Brauerei Donnerbräu in Kharanos aus aufrechterhalten. Überzeugt davon, dass ihr eigenes Handwerk genauso robust ist, sucht sie nach cleveren Wegen, den Tavernenbesuchern Fässer der Gerstenbräus unterzuschieben. Anstatt sich auf einen offenen Konflikt einzulassen, entscheidet sie sich für kleine Sabotageakte und heuert durchreisende Abenteurer an, um die geschätzten Bierfässer von Kharanos heimlich gegen ihre eigenen auszutauschen."}},faq={{q="Wer ist Marleth Gerstenbräu?",a="Marleth ist eine Zwergenbraumeisterin, die in Bräuhall im westlichen Dun Morogh lebt. Sie vertritt die Familie Gerstenbräu und arbeitet aktiv daran, den Würgegriff der rivalisierenden Familie Donnerbräu auf die lokale Trinkerszene zu brechen.",al={"wer ist marleth","marleth lore","marleth gerstenbräu"}},{q="Wo finde Ich Marleth Gerstenbräu?",a="Sie befindet sich in Bräuhall, gelegen in den westlichen Gefilden von Dun Morogh nahe dem Eiswellensee.",al={"marleth standort","wo ist marleth","marleth finden"}},{q="Warum möchte Marleth das Bier von Donnerbräu austauschen?",a="Marleth glaubt, dass das Bier ihrer Familie genauso gut, wenn nicht sogar besser als Donnerbier ist. Da die Donnerbräus den Handel in Kharanos dominieren, heuert sie Abenteurer an, um heimlich die Fässer der Taverne durch Gerstenbräu-Vorräte zu ersetzen, damit die Zecher ihr Produkt kosten, und ihr zugleich eine Probe des Donnerbiers zur Analyse mitzubringen.",al={"warum das bier austauschen","bittere rivalen quest grund","warum hass auf donnerbräus"}},{q="Wer sind die anderen Mitglieder der Gerstenbräu-Familie?",a="Zu ihrem erweiterten Klan gehören weitere bekannte Brauer und Handwerker wie Malgin, Rejold, Wellart und Yorus Gerstenbräu, die sich alle der traditionellen Zwergenbraukunst verschrieben haben.",al={"familie gerstenbräu","marleth verwandte"}}},fx={c401045b={q="Auf wessen Seite steht Marleth Gerstenbräu?",a="Marleth ist eine stolze Zwergin aus Eisenschmiede und der Allianz gegenüber loyal, obwohl sich ihr unmittelbarer täglicher Fokus rein auf das Geschäftliche richtet. Sie gehört zur Brauerfamilie Gerstenbräu und setzt sich vehement für ihr Handwerk gegen ihre lokalen Konkurrenten ein.",al={"marleth gerstenbräu zugehörigkeit","wem dient marleth gerstenbräu","marleth fraktion"}},["716c9dd7"]={q="Warum ist Marleth Gerstenbräu in Bräuhall?",a="Bräuhall dient als regionaler Brauaußenposten in den verschneiten Hügeln von Dun Morogh. Marleth operiert von hier aus, um ihr Handwerksbier zu produzieren und Pläne zu schmieden, wie sie in die größeren Märkte vordringen kann, die von den Thunderbrews monopolisiert werden.",al={"warum ist marleth hier","marleth gerstenbräu bräuhall","warum ist marleth gerstenbräu in dun morogh"}}},fp="18,255,19.559.0,26.223.0,36.101.0,49.325.0,51.174.0"}
P.entries["npc:marryk-nurribit"] = {n="Marryk Nurribit",s="Marryk Nurribit ist der ansässige Gnom-Magierlehrer in Ambossar im Coldridgetal. Er schätzt die lokalen Gebräue etwas mehr als disziplinierte Pädagogik und führt angehende gnomische Arkanisten in ihr Handwerk ein, während er sie häufig um ein paar Münzen für ein Getränk anhaut.",h="Marryk Nurribit ist der ansässige Gnom-Magierlehrer in Ambossar im Coldridgetal.",kw={"ambossar","bier","coldridge","gnom","magier","marryk","nurribit","lehrer"},ang={["class:Mage"]="Für angehende Gnom-Magier, die ihre Reise im Coldridgetal beginnen, ist Marryk der erste Lehrer, an den Ihr Euch für grundlegende Zauber und Euer Glyphenmemorandum wendet.",["race:Gnome"]="Flüchtlinge, die in Dun Morogh Zuflucht suchen, kennen Marryk als ein Beispiel für einen gnomischen Gelehrten, der sich ein wenig zu gut an die zwergische Gastfreundschaft in Tavernen gewöhnt hat."},sec={{t="Arkanstudien und Bier",b="Eingekuschelt am warmen Herd von Ambossar bietet Marryk Nurribit jungen Gnomen, die ihre allerersten Schritte in die Magie wagen, arkane Führung. Obwohl er in den arkanen Künsten bewandert ist, wirkt sein Auftreten ausgesprochen lässig – oft scheint er weit mehr daran interessiert zu sein, einen Humpen Zwergenbier zu leeren und seinen neuen Schülern etwas Kleingeld abzuluchsen, als sie in komplexen Theoremen zu unterrichten. Trotz seiner Laster ist sich Marryk der Gefahren außerhalb des Coldridgetals vollkommen bewusst und warnt angehende Zauberwirker regelmäßig vor den anhaltenden radioaktiven und von Troggs heimgesuchten Schrecken des gefallenen Gnomeregan."}},faq={{q="Wer ist Marryk Nurribit?",a="Marryk Nurribit ist ein Gnom-Magierlehrer in Ambossar im Coldridgetal von Dun Morogh. Er unterweist neu angekommene Gnom-Magier in den Grundlagen der Arkanmagie.",al={"marryk nurribit","wer ist marryk","ambossar magierlehrer"}},{q="Warum fragt Marryk ständig nach Geld für Bier?",a="Marryk ist dafür bekannt, die lokalen Spirituosen weit mehr zu genießen als strikte professionelle Zurückhaltung zu wahren. Er bedrängt seine Schüler regelmäßig um Kleingeld, um seine Trinkgewohnheiten in der Taverne zu finanzieren.",al={"marryk trinken","marryk bier","warum fragt er nach münzen"}},{q="Was sagt Marryk über Gnomeregan?",a="Trotz seiner entspannten Haltung gegenüber der Ausbildung erkennt Marryk echte Gefahren und warnt frische Magier wiederholt davor, die Gefahren zu unterschätzen, die in den verstrahlten Ruinen von Gnomeregan lauern.",al={"marryk gnomeregan","gnomeregan warnung"}}},fx={["42f80152"]={q="Auf wessen Seite steht Marryk Nurribit?",a="Marryk ist loyal gegenüber den Gnomeregangnomen und steht voll und ganz an der Seite der Allianz. Er sucht Schutz bei seinen zwergischen Gastgebern in Dun Morogh und bietet den jungen Gnomen, die das Das Coldridgetal betreten, seine arkanen Unterweisungen an.",al={"marryk nurribit fraktion","wem dient marryk","marryk zugehörigkeit"}},["241b0acf"]={q="Warum ist Marryk Nurribit in Ambossar?",a="Nach dem tragischen Fall von Gnomeregan durch die Trogg-Invasion und den giftigen radioaktiven Niederschlag flohen Marryk und seine überlebenden Verwandten nach Dun Morogh. Er hält sich nun in Ambossar im Das Coldridgetal auf und hat nominell die Aufgabe, angehende Gnom-Magier in den arkanen Künsten zu unterrichten.",al={"warum ist marryk hier","marryk nurribit ambossar","marryks zweck in dun morogh"}}},fp="15,261,22.589.0,23.175.0,47.191.0,38.197.0"}
P.entries["npc:marshal-dughan"] = {fx={["72888056"]={q="Auf wessen Seite steht Marschall Dughan?",a="Marschall Dughan dient dem Königreich Sturmwind und der Allianz. Als Offizier in der Armee von Sturmwind untersteht er direkt der militärischen Hierarchie des Reiches und führt die Befehle der Krone aus, um die Ordnung aufrechtzuerhalten und das Kernland trotz schwindender königlicher Verstärkung zu schützen.",al={"dughan fraktion","wem dient dughan","marschall dughan zugehörigkeit"}},["9141816c"]={q="Was will Marschall Dughan?",a="Dughan zielt darauf ab, den Wald von Elwynn zu sichern und Goldhain vor zunehmenden Bedrohungen zu bewahren. Da seine Garnison überstrapaziert ist, sucht er nach fähigen Abenteurern, die die befallenen Fargodeep- und Jasperlode-Minen auskundschaften, die Defias-Banditen und Gnolle im Westen eindämmen und die wachsende Gefahr entlang der Flussufer einschätzen können.",al={"dughan ziel","was braucht dughan","dughan ziele"}},["8808e7de"]={q="Warum ist Marschall Dughan in Goldhain stationiert?",a="Dughan ist als Befehlshaber des örtlichen Abkommandos der Armee von Sturmwind in Goldhain stationiert. Er ist mit der Verteidigung des zentralen Wald von Elwynn betraut und beaufsichtigt die Friedenssicherung der Stadt, koordiniert Außenposten wie die Weststromgarnison und leitet die Verteidigung gegen eindringende Bestien, Kobolde und Kriminelle, die die Kornkammer der Hauptstadt bedrohen.",al={"warum ist dughan in goldhain","marschall dughan zweck hier","dughan posten"}},["156c33b1"]={q="Mit wem ist Marschall Dughan verbunden?",a="Dughan arbeitet eng mit örtlichen Außenpostenkommandanten im gesamten Wald von Elwynn zusammen, wie beispielsweise Stellvertreter Rainer in der Weststromgarnison und Wache Thomas entlang der östlichen Brücken. Außerhalb von Elwynn pflegt er die Kommunikation mit militärischen Kollegen wie Gryan Starkmantel in Westfall, um Informationen über kriminelle Aktivitäten in der Region auszutauschen.",al={"dughan verbindungen","mit wem arbeitet dughan zusammen","dughan verbündete"}}}}
P.entries["npc:marshal-marris"] = {n="Marschall Marris",s="Marschall Marris ist der schwer bedrängte Militäroffizier, der die Stadtwache von Seenhain befehligt. Er ist nahe der Stadtbrücke stationiert und koordiniert die Verteidigungsoperationen gegen die gewaltige Invasion der Schwarzfelsorcs, die von den Höhen des Rotkammgebirges herabdrängen. Da Sturmwinds Armee abwesend ist, verlässt er sich auf durchreisende Abenteurer, um den Vormarsch der Horde abzuwehren.",h="Marschall Marris ist der schwer bedrängte Militäroffizier, der die Stadtwache von Seenhain befehligt.",kw={"schwarzfels","brücke","seenhain","marris","marschall marris","rotkammgebirge","steinwacht","tharil'zun"},ang={["class:Warrior"]="Marris schätzt geradlinige soldatische Disziplin und schickt fähige Frontkämpfer direkt in den Schlund von Steinwacht, um sich mit gestählten Schwarzfelsveteranen zu messen.",["faction:Alliance"]="Marschall Marris verkörpert die Notlage der ländlichen Gebiete der Allianz, die durch Sturmwinds politische Lähmung verwundbar zurückgelassen wurden und gezwungen sind, auf sich allein gestellt ums Überleben zu kämpfen.",["race:Human"]="Für die Menschen des Königreichs repräsentiert Marris die stoische, bedrängte Grenzwache, die gegen die Überreste der Alten Horde die Stellung hält."},sec={{t="Eine Stadt unter Belagerung",b="Seenhain steht am Rande des Zusammenbruchs, eingeklemmt zwischen den Gnollen im Westen und der furchterregenden militärischen Macht des Schwarzfelsklans im Osten. Marschall Marris überwacht die Verteidigungslinie an der Hauptbrücke der Stadt, doch seine Ressourcen sind erschöpft und seine Soldaten hoffnungslos überdehnt. Da das Königreich Sturmwind königliche Verstärkung zurückhält, trägt Marris die schwere Bürde, die Ortschaft davor zu bewahren, von schierer Gewalt überrannt zu werden."},{t="Die Vorhut des Schwarzfels brechen",b="In der Erkenntnis, dass Verteidigung allein das Rotkammgebirge nicht retten wird, plant Marris entschlossene offensive Schläge gegen die Lager der Orcs. Er beauftragt Söldner damit, die Krieger des Schwarzfelsklans auszudünnen, ihre Schattenzauberer auszuschalten und letztlich Tharil'zun zur Strecke zu bringen, den bedrohlichen Kommandanten, der sich in den Ruinen von Burg Steinwacht verschanzt hat. Seine Befehle zielen darauf ab, die Kommandostruktur der Orcs zu zerschlagen, bevor ein Großangriff Seenhain vollständig vernichtet."}},faq={{q="Wer ist Marschall Marris?",a="Marschall Marris ist der ranghöchste militärische Befehlshaber, der mit der Verteidigung von Seenhain betraut ist. Man findet ihn Wache haltend nahe dem westlichen Ende der Stadtbrücke, wo er versucht, die Siedlung gegen feindliche Übergriffe zu befestigen.",al={"marris","marschall marris lore","wer ist die wache an der brücke von seenhain"}},{q="Warum heuert Marschall Marris unabhängige Abenteurer an?",a="Das Königreich Sturmwind hat es versäumt, adäquate Garnisonsverstärkung in das Rotkammgebirge zu entsenden, wodurch die örtliche Wache von Seenhain hoffnungslos in der Unterzahl ist. Angesichts von Gnoll-Kriegstrupps und einer verschanzten Invasion von Schwarzfelsorcs ist Marris gezwungen, heldenhafte Söldner für entscheidende Angriffe anzuheuern.",al={"warum braucht marris hilfe","warum keine armee aus sturmwind"}},{q="Gegen welche Bedrohungen kämpft Marschall Marris?",a="Während Gnolle die Außenbezirke heimsuchen, konzentriert sich Marris in erster Linie auf die Schwarzfelsorcs, die Burg Steinwacht eingenommen haben. Diese Orcs, befehligt von Tharil'zun und durch Schattenmagie gestärkt, stellen eine unmittelbare existenzielle Bedrohung für Seenhain und das gesamte Königreich dar.",al={"marris feinde","wer greift seenhain an"}},{q="Ist Marschall Marris mit Nathanos Marris verwandt?",a="Sie teilen einen in den Menschenkönigreichen Lordaeron und Sturmwind verbreiteten Nachnamen, aber es gibt keine offiziellen Aufzeichnungen, die eine direkte familiäre Verbindung zwischen Marschall Marris im Rotkammgebirge und dem berühmten Waldläufer Nathanos Marris aus dem Norden belegen.",al={"ist marris mit nathanos verwandt","marris familie"}},{q="Wie lautet Marris' Plan, um den Schwarzfelsklan zu besiegen?",a="Marris setzt auf einen Zermürbungs- und Enthauptungskrieg. Er beauftragt Kämpfer damit, die Infanterie des Schwarzfelsklans zu dezimieren, magische Komponenten von ihren Nutzern von Schattenmagie zu beschaffen und Burg Steinwacht zu stürmen, um deren Anführer Tharil'zun hinzurichten.",al={"marris plan","wie man schwarzfelsorcs besiegt"}},{q="Wo ist Marschall Marris zu finden?",a="Marris ist in Seenhain im Rotkammgebirge stationiert und steht weithin sichtbar an der Brücke nahe der Stadtmitte.",al={"marris aufenthaltsort","wo ist marschall marris"}}},fx={["4fad023e"]={q="Auf wessen Seite steht Marschall Marris?",a="Marschall Marris ist ein loyaler Offizier des Königreichs Sturmwind und der Allianz. Als stationierter Offizier an der Front in Seenhain repräsentiert er die lokale militärische Autorität, die verzweifelt versucht, das Rotkammgebirge und seine Bürger vor eindringenden Feinden zu schützen.",al={"marschall marris fraktion","wem dient marris","marris allianz oder sturmwind"}},["4230d686"]={q="Warum ist Marschall Marris hier in Seenhain?",a="Marschall Marris ist in der Nähe der Brücke von Seenhain stationiert, um die Verteidigung gegen die Schwarzfelsorks zu koordinieren, die aus den Bergen strömen. Da offizielle Verstärkungen aus Sturmwind knapp sind, hält er Wache im Rotkammgebirge, um alle fähigen Abenteurer zu sammeln, die bereit sind, den Kampf in die feindliche Festung zu tragen.",al={"warum ist marschall marris im rotkammgebirge","warum ist marris hier","marschall marris standort grund"}}},fp="14,354,18.453.0,31.438.0,22.223.0,53.302.0,48.263.0,45.228.0,51.229.0,34.128.0"}
P.entries["npc:marshal-maxwell"] = {n="Marschall Maxwell",s="Marschall Maxwell ist ein hochrangiger Offizier der Armee von Sturmwind, der in Morgans Wacht in der Brennenden Steppe stationiert ist. Mit der Aufgabe betraut, den nördlichsten befestigten Grat der Allianz oberhalb des Rotkammgebirges gegen den Schwarzfelsklan und die Dunkeleisenzwerge zu halten, leitet er Spähmissionen in die feindseligen Klippen darunter. Zudem spielt er eine entscheidende Rolle bei der Koordination von Bemühungen, das Schicksal seines gefangenen Kameraden Marshal Reginald Windsor aufzudecken.",h="Marschall Maxwell ist ein hochrangiger Offizier der Armee von Sturmwind, der in Morgans Wacht in der...",kw={"blackrocktiefen","brennende steppe","general drakkisath","marschall maxwell","maxwell","morgans wacht","reginald windsor","armee von sturmwind"},ang={["class:Warrior"]="Maxwell verkörpert die Disziplin des Frontmilitärs von Sturmwind, trotzt aufrecht der vulkanischen Asche und koordiniert gezielte Vorstöße tief hinter den feindlichen Linien.",["faction:Alliance"]="Für Recken der Allianz, die der sengenden Hitze der Brennenden Steppe trotzen, verkörpert Marschall Maxwell die Autorität von Sturmwind und die Speerspitze des Feldzugs gegen den Schwarzfels."},sec={{t="Ein einsamer Posten in der Steppe",b="Morgans Wacht dient als prekärer Vorposten am Südrand der Brennenden Steppe mit Blick auf ein Ödland voller Asche, Drachkin und Schwarzfelsorcs. Marschall Maxwell befehligt das hier stationierte Militärkontingent aus Sturmwind und bietet Reisenden, die den feurigen Klippen trotzen, einen seltenen vertrauten Anblick. Von dieser felsigen Bastion aus überwacht er defensive Manöver, um die feindlichen Streitkräfte des Berges in Schach zu halten, bevor sie nach Süden in das Rotkammgebirge und nach Elwynn vordringen können."},{t="Die Wahrheit im Berg aufdecken",b="Über die reine Eindämmung hinaus dient Maxwell als primäre Verbindungsstelle im Feld für Operationen, die auf das Herz der Schwarzfelsspitze und der Schwarzfelstiefen abzielen. Als Gerüchte aufkommen, dass der gefangene Marshal Reginald Windsor möglicherweise noch in den Kerkern der Dunkeleisenzwerge lebt, ist es Maxwell, der Berichte sichtet und vertrauenswürdige Recken mit einer Rettung betraut. Sein Vorposten bildet die entscheidende Brücke zwischen der Aufklärung an vorderster Front und den politischen Unruhen, die sich hinter den Toren von Sturmwind zusammenbrauen."}},faq={{q="Wer ist Marschall Maxwell?",a="Marschall Maxwell ist ein Kommandant in der Armee von Sturmwind, der in Morgans Wacht in der Brennenden Steppe stationiert ist. Er führt die örtlichen Allianzstreitkräfte an, die die Schwarzfelsorcs, die schwarzen Drachen und die Dunkeleisenzwerge im Auge behalten.",al={"marschall maxwell geschichte","wer ist maxwell"}},{q="Warum ist Marschall Maxwell in Morgans Wacht stationiert?",a="Morgans Wacht ist das Frontlager der Allianz an der Grenze zur Brennenden Steppe. Maxwell ist hier stationiert, um den Gebirgspass zu sichern, der hinab in das Rotkammgebirge führt, und Bedrohungen zu überwachen, die aus dem Schwarzfels strömen.",al={"warum ist maxwell in brennende steppe","morgans wacht kommandant"}},{q="Welche Verbindung hat Maxwell zu Marshal Windsor?",a="Maxwell ist der wichtigste Kommandant, der bei der Suche nach Marshal Reginald Windsor hilft, welcher gefangen genommen und in die Schwarzfelstiefen verschleppt wurde. Maxwell koordiniert die Rettungsbemühungen und leitet entscheidende Informationen über Windsor zurück nach Sturmwind.",al={"maxwell und windsor","abandoned hope quest geschichte"}},{q="Hilft Marschall Maxwell bei der Organisation von Angriffen auf die Schwarzfelsspitze?",a="Ja. Maxwell weist erfahrene Recken der Allianz an, die Führungsriege des Schwarzfelsklans zu zerschlagen, und erteilt Direktiven, die auf General Drakkisath und seine Truppen auf den Höhen der Schwarzfelsspitze abzielen.",al={"maxwell drakkisath","maxwells mission"}}},fp="15,446,28.475.0,36.518.1,23.216.0,51.231.0,48.243.0,67.205.0"}
P.entries["npc:marshal-mcbride"] = {n="Marschall McBride",s="Marshal Douglas McBride ist der Kommandant der Garnison von Sturmwind, die in der Abtei von Nordhain stationiert ist. Betraut mit der Verteidigung des Nordhaintals, befehligt er frisch eingetroffene Rekruten gegen die zunehmende Koboldplage, die die örtlichen Höfe und Minen bedroht. Er fungiert als wichtigste militärische Autorität für Neuankömmlinge, die ihren Dienst für das Königreich Sturmwind antreten.",h="Marshal Douglas McBride ist der Kommandant der Garnison von Sturmwind, die in der Abtei von Nordhain...",kw={"douglas mcbride","echokamm","elwynn","kobold","marschall mcbride","nordhain","abtei von nordhain"},ang={["class:Warrior"]="McBride sucht aktiv nach robusten Kämpfern für den Dienst am Königreich und verlässt sich auf Krieger an vorderster Front, um die Stollen von Echokamm zu säubern.",["faction:Alliance"]="McBride repräsentiert den anfänglichen Grenzposten der Großen Allianz im Kernland der Menschheit und nimmt Rekruten in den Dienst der Krone auf.",["race:Human"]="Für Menschen, die ihre Abenteuer in Nordhain beginnen, ist Marschall McBride der erste Vertreter der königlichen Autorität von Sturmwind, dem sie begegnen."},sec={{t="Kommandant von Nordhain",b="Direkt vor der Abtei von Nordhain stationiert, repräsentiert Marshal Douglas McBride die unmittelbare Autorität der Armee von Sturmwind in diesem ruhigen Tal. Während die Abtei selbst eine Enklave des Glaubens und der Gelehrsamkeit ist, haben die wachsenden Unruhen im gesamten Königreich die militärischen Garnisonen stark ausgedünnt. McBride muss den Frieden wahren und die Nahrungs- sowie Ressourcenversorgung des Tals mit nur einer Handvoll vereidigter Wachen und einem stetigen Zustrom unerfahrener Rekruten sichern, die eine Ausbildung unter den Meistern der Abtei suchen."},{t="Der Überfall der Kobolde",b="McBrides größtes Problem ist die plötzliche Aggressivität des örtlichen Ungeziefers. Kobolde, einst nur ein Ärgernis, haben die umliegenden Wälder überrannt und die Echokammmine besetzt – eine wichtige örtliche Ressource. Da ihm die regulären Soldaten fehlen, um sie zu vertreiben, zieht McBride Paladine, Krieger und andere Neulinge heran, um die grabenden Plagegeister zurückzuschlagen und das Ausmaß des Befalls aufzudecken, bevor das Tal vollständig abgeschnitten wird."}},faq={{q="Wer ist Marschall McBride?",a="Marshal Douglas McBride ist ein Offizier der Armee von Sturmwind, der als Garnisonskommandant in der Abtei von Nordhain stationiert ist. Er ist für die Verteidigung des Nordhaintals und die Einteilung neuer Rekruten in den Dienst zuständig.",al={"marschall mcbride","wer ist mcbride","kommandant von nordhain"}},{q="Warum lässt McBride Rekruten gegen Kobolde kämpfen?",a="Kobolde haben die Wälder rund um Nordhain heimgesucht und die Kontrolle über die Echokammmine übernommen. Da das Militär von Sturmwind stark überlastet ist, verlässt sich McBride auf neu eingetroffene Abenteurer, um das Ungeziefer zu beseitigen und das Gebiet zu sichern.",al={"warum kobolde töten","koboldproblem","echokamm problem"}},{q="Wohin schickt McBride Rekruten als Nächstes?",a="Sobald ein Rekrut seine Fähigkeiten unter Beweis gestellt hat, indem er die Bedrohungen im Nordhaintal beseitigt hat, schickt McBride ihn über die südliche Straße nach Goldhain, um Marschall Dughan zu unterstützen.",al={"wohin nach mcbride","nach nordhain","nächste stadt"}},{q="Was ist die Echokammmine?",a="Die Echokammmine ist eine mineralienreiche Höhle am nördlichen Rand des Nordhaintals. Sie wurde vor Kurzem von grabenden Kobolden überrannt, was McBride dazu veranlasste, mehrere Einsätze zu ihrer Rückeroberung anzuordnen.",al={"echokamm","die mine in nordhain"}},{q="Befehligt McBride die Abtei selbst?",a="Nein. Die Abtei von Nordhain wird von den heiligen Orden und den Priestern des Lichts geführt. McBride beaufsichtigt die Militärgarnison, die mit der Verteidigung der Abtei und des umliegenden Tals beauftragt ist.",al={"leitet mcbride die abtei von nordhain","wer leitet die abtei"}},{q="Sorgt sich McBride um Bedrohungen abseits der Kobolde?",a="Während Kobolde das unmittelbarste Ärgernis darstellen, hält McBride Ausschau nach tiefergehender Instabilität. Banditen und Gesetzlose treiben sich an den Rändern des Tals herum, was auf weiterreichende Unruhen hindeutet, die sich im Wald von Elwynn zusammenbrauen.",al={"defias in nordhain","ist nordhain sicher"}}},fx={["05ea779e"]={q="Auf wessen Seite steht Marschall McBride?",a="Marschall McBride ist ein loyaler Offizier der Armee von Sturmwind und der Großen Allianz. Er untersteht der Krone von Sturmwind und hält Wache über das Nordhaintal, um die Sicherheit der Bürger des Königreichs zu gewährleisten und Rekruten auszubilden.",al={"wem dient mcbride","mcbride loyalität","welcher fraktion gehört mcbride an"}},b6028054={q="Was will Marschall McBride?",a="McBride will das Nordhaintal gegen wachsende lokale Bedrohungen sichern. Da die Armee von Sturmwind nur dünn gesät ist, versucht er, neue Rekruten, Paladine und Freiwillige zu mobilisieren, um die aggressiven Kobolde, die das Tal befallen, zu vertreiben und die Echokammmine zurückzuerobern.",al={"mcbride ziel","was versucht mcbride zu tun","mcbride pläne"}},cc66b2df={q="Warum ist Marschall McBride hier?",a="McBride ist als Befehlshaber der militärischen Garnison des Tals außerhalb der Abtei von Nordhain stationiert. Sturmwind hat ihn damit beauftragt, die Ordnung aufrechtzuerhalten, die Verteidigung zu organisieren und Neuankömmlinge auszubilden, bevor er bewährte Soldaten in den Wald von Elwynn und darüber hinaus entsendet.",al={"warum ist mcbride in nordhain","mcbride posten","warum ist marschall mcbride an der abtei"}},["307fdf7d"]={q="Mit wem ist Marschall McBride verbunden?",a="McBride ist an das Oberkommando der Armee von Sturmwind gebunden und koordiniert sich mit den örtlichen Behörden im gesamten Wald von Elwynn; schließlich leitet er fähige Kämpfer an Marschall Dughan in Goldhain weiter. Er arbeitet mit dem Klerus und den Ausbildern der Abtei zusammen, um neue Verteidiger auf das Königreich vorzubereiten.",al={"mcbride verbindungen","wem untersteht mcbride","mcbride armee von sturmwind"}}},fp="15,363,23.465.0,20.415.0,23.204.0,45.217.0,38.181.0,24.203.0,38.178.0,50.197.0"}
P.entries["npc:martie-jainrose"] = {fx={["4d2b4277"]={q="Auf wessen Seite steht Martie Jainrose?",a="Martie ist eine loyale Bürgerin der Allianz, die friedlich in Seenhain lebt. Obwohl sie nicht an der Front kämpft oder Waffen trägt, unterstützt sie die Stadt und ihre Verteidiger durch ihren Beruf als Kräuterkundige.",al={"martie jainrose fraktion","ist martie allianz"}},e745a8a7={q="Was will Martie Jainrose?",a="Martie möchte ihren Garten in Frieden pflegen und ihr Kräuterhandwerk ohne Einmischung ausüben. Ihr unmittelbares Ärgernis ist ein riesiger Eber namens Bellygrub, der ständig ihre wertvolle Ernte zertrampelt, und sie begrüßt gerne jeden Reisenden, der bereit ist, das Biest zu vertreiben.",al={"martie jainrose ziel","was braucht martie"}},["6d429f48"]={q="Warum ist Martie Jainrose in Seenhain?",a="Seenhain ist Marties Zuhause, wo sie ihren Lebensunterhalt damit verdient, Kräuter anzubauen und ihren Garten entlang der ruhigen Ufer des Immerruhsees zu pflegen, trotz der wachsenden Probleme, die das umliegende Rotkammgebirge heimsuchen.",al={"warum ist martie im rotkammgebirge","warum ist martie jainrose hier"}}}}
P.entries["npc:marukai"] = {n="Marukai",s="Marukai ist eine Dschungeltrollin der Dunkelspeer, die im Außenposten von Zoram'gar an der nebligen Küste des nordwestlichen Eschental stationiert ist. Sie widmet sich dem Halten dieses abgelegenen Brückenkopfs für die Horde und koordiniert die Bemühungen, die vordringenden Wrathtail-Naga auszudünnen, welche den Außenposten bedrohen.",h="Marukai ist eine Dschungeltrollin der Dunkelspeer, die im Außenposten von Zoram'gar an der nebligen Küste des...",kw={"eschental","dunkelspeer","dschungeltroll","marukai","naga","wrathtail","der zoramstrand","außenposten von zoram'gar"},ang={["faction:Horde"]="Marukai stützt eines der heikelsten Küstenlager der Horde im Gebiet der Nachtelfen und verlässt sich auf verbündete Champions, um zu verhindern, dass die einheimischen Naga ihre Stellung überrennen.",["race:Troll"]="Fernab der warmen Klänge von Sen'jin verkörpert Marukai die Unbeugsamkeit des Dunkelspeer-Stammes, während sie auf ganz Kalimdor befestigte Stützpunkte für die Horde errichten."},sec={{t="Den Strand halten",b="Der Außenposten von Zoram'gar liegt isoliert am nördlichen Rand des Zoramstrands, umgeben von uralten Ruinen, feindseligem Nachtelfengebiet und dem unruhigen Meer. Während die Wrathtail-Naga in großer Zahl aus den Gewässern und alten Elfenruinen emportauchen, um die Küste für sich zu beanspruchen, setzt Marukai alles daran, das Lager vor dem Überranntwerden zu bewahren. Sie weist Streiter der Horde an, das Schlangenvolk zurück in die Fluten zu treiben und ihre Köpfe zu sammeln, um sicherzustellen, dass der Außenposten eine überlebensfähige Küstenfestung bleibt."}},faq={{q="Wer ist Marukai?",a="Marukai ist eine Dschungeltroll-Questgeberin, die den Außenposten von Zoram'gar verteidigt, das isolierte Küstenlager der Horde an den nordwestlichen Ufern von Eschental.",al={"marukai lore","wer ist marukai","marukai nsc"}},{q="Warum bekämpft Marukai die Naga?",a="Die Wrathtail-Naga haben den nahe gelegenen Zoramstrand und die umliegenden Ruinen heimgesucht. Um die Grenzen des Außenpostens zu sichern und das Überleben der Horde an der Küste zu gewährleisten, heuert Marukai Abenteurer an, um ihre Reihen durch direkte Jagd zu lichten.",al={"warum naga töten","marukai naga quest","zoramstrand naga"}},{q="Wo befindet sich Marukai?",a="Sie ist an der Seite ihrer Sippe im Außenposten von Zoram'gar anzutreffen, der an der Mündung des Zoramstrands im nordwestlichen Eschental liegt, direkt südlich der versunkenen Ruinen der Tiefschwarzen Grotte.",al={"wo ist marukai","marukai aufenthaltsort","marukai finden"}}},fx={["53dc13db"]={q="Auf wessen Seite steht Marukai?",a="Marukai ist der Horde treu. Von ihrem Stützpunkt im Außenposten von Zoram'gar an der Küste des Eschentals aus hält sie Wache über die Interessen der Horde und verlässt sich auf Reisende der Horde, um die Siedlung gegen örtliche Gefahren zu verteidigen.",al={"marukai fraktion","ist marukai horde","wem dient marukai"}},["1bf5ddde"]={q="Warum ist Marukai hier im Außenposten von Zoram'gar?",a="Marukai ist im Außenposten von Zoram'gar stationiert, um den Stützpunkt der Horde am The Zoram Strand zu verteidigen. Da die aggressiven Wrathtail-Naga an die Strände zurückkehren und die Grenzen des Lagers bedrohen, koordiniert sie Bemühungen, den Umkreis zu sichern und den Außenposten sicher zu halten.",al={"warum ist marukai im eschental","marukai zweck","was bringt marukai hierher"}}},fp="7,259,18.471.0,15.146.0,33.230.0,25.190.0"}
P.entries["npc:master-apothecary-faranell"] = {n="Apothekermeister Faranell",s="Apothekermeister Faranell ist das Oberhaupt der Königlichen Apothekervereinigung und hat seinen Sitz in den Tiefen des Apothekariums in Unterstadt. Zu Lebzeiten ein angesehener Gelehrter aus Dalaran, leitet er im Untod die Suche der Verlassenen nach einer verheerenden Neuen Seuche, um sowohl die Geißel als auch die Lebenden zu vernichten.",h="Apothekermeister Faranell ist das Oberhaupt der Königlichen Apothekervereinigung und hat seinen Sitz in den...",kw={"monstrosität","das apothekarium","seuche","faranell","apothekermeister faranell","neue seuche","renferrel","königliche apothekervereinigung","sylvanas","unterstadt"},ang={["faction:Horde"]="Obwohl Verbündete der Orcs, Trolle und Tauren durch den grünen Schleim und die eingesperrten Versuchsobjekte des Apothekariums beunruhigt sein mögen, werden Faranells Forschungen als unverzichtbare Kriegsführung gegen die gemeinsame Bedrohung durch die Geißel geduldet.",["profession:Herbalism"]="Faranells Bottiche verschlingen endlose Mengen seltener Flora, Moose und Pilzextrakte – ein düsteres Zeugnis botanischer Studien, die zur Zerstörung militarisiert wurden.",["race:Undead"]="Für die Verlassenen verkörpert Faranell die Vorhut biologischer Souveränität, die im Verborgenen schuftet, um sicherzustellen, dass ihr Volk über Waffen verfügt, die den Lichkönig zerschmettern können."},sec={{t="Ein vom Tode zerrütteter Geist",b="Vor dem Dritten Krieg war Faranell ein geschätzter Alchemist, der jahrzehntelang an der Seite der gelehrten Magier von Dalaran forschte. Er verbrachte seine sterblichen Tage damit, Heilmittel, Kuren und Tränke zu erforschen, um die Gesundheit der Sterblichen zu verbessern. Als die Seuche der Geißel sein Leben forderte und er als Verlassener mit freiem Willen auferstand, schlug seine einstige wissenschaftliche Neugierde in Grausamkeit um. Mit seinem enzyklopädischen Verstand tauschte er Heilsalben gegen verheerende Reagenzien ein und stieg in den Tiefen von Lordaerons gefallener Hauptstadt rasch zu einem der geschätztesten Forscher von Königin Sylvanas Windläufer auf."},{t="Der Meister des Apothekariums",b="Von den giftigen Laboratorien des Apothekariums aus koordiniert Faranell die weitverzweigten Forschungen der Königlichen Apothekervereinigung. Er beaufsichtigt den Bau schwerfälliger Monstrositäten und leitet die untergeordneten Apotheker an, die in ganz Lordaeron und darüber hinaus stationiert sind. Jede Ladung seltsamer Gifte, verdorbenen Blutes und verfluchter Flora, die von Feldforschern auf den Kontinenten gesammelt wird, landet schließlich in seinen Bottichen zur Destillation und Verfeinerung."},{t="Erschaffung der Neuen Seuche",b="Faranells einzige treibende Obsession ist die Erfüllung des Auftrags der Dunklen Fürstin: die Entdeckung der Neuen Seuche. Um eine Seuche zu brauen, die in der Lage ist, Arthas und seine willenlosen Legionen der Geißel zu vernichten, koordiniert Faranell eine umfassende Beschaffung von Reagenzien. Er entsendet Abenteurer, um die Forschungsaufzeichnungen seines gefallenen Kollegen Apotheker Berard aus Lohenscheit zu bergen, beschafft Fledermausguano aus den tiefen Höhlen im Kral der Klingenhauer und testet ätzende Kolloide an den Organen von Eiferern aus dem Scharlachroten Kloster."}},faq={{q="Wer ist Apothekermeister Faranell?",a="Faranell ist das Oberhaupt der Königlichen Apothekervereinigung, der alchemistischen Gilde im Dienste von Fürstin Sylvanas Windläufer in Unterstadt. Er überwacht sämtliche Forschungen bezüglich Toxinen, zusammengenähten Monstrositäten und der Entwicklung der Neuen Seuche.",al={"wer ist faranell","faranell lore","anführer der apotheker"}},{q="Wo ist Faranell zu finden?",a="Er hält sich im Apothekarium auf, dem alchemistischen Viertel im westlichen Teil von Unterstadt, umgeben von brodelnden Kesseln, Testkäfigen und seinen untergeordneten Apothekern.",al={"faranell aufenthaltsort","wo ist apothekermeister faranell","faranell finden"}},{q="Was war Faranells Hintergrund, bevor er starb?",a="Zu Lebzeiten war Faranell ein anerkannter Alchemist und Arzt, der bei den Zauberern von Dalaran lernte. Er verbrachte seine lebenden Jahre damit, Heilmittel gegen Krankheiten zu erfinden, bis die Seuche ihn tötete und seine Neugierde auf tödliche Gifte lenkte.",al={"faranell geschichte","war faranell in dalaran","faranell sterbliches leben"}},{q="Was versucht die Königliche Apothekervereinigung zu erschaffen?",a="Auf Befehl von Königin Sylvanas stellt die Vereinigung Eine neue Seuche her. Ihr Ziel ist es, eine Waffe zu erschaffen, die virulent genug ist, um die Geißel zu vernichten und Rache am Lichkönig zu nehmen, während sie die Verlassenen gleichzeitig vor sterblichen Feinden schützt.",al={"was ist die neue seuche","was stellen apotheker her","ziele der apotheker"}},{q="Warum schickt Faranell Abenteurer nach Lohenscheit?",a="Er sucht nach dem Forschungstagebuch seines ehemaligen Kollegen, Apotheker Berard, der in Pyrewood dem Wahnsinn und dem Worgenfluch verfiel. Berards Feldaufzeichnungen enthalten entscheidende Daten über giftige Stoffe, die zur Verfeinerung ihrer Seuchenexperimente benötigt werden.",al={"rezept für den tod quest faranell","warum pyrewood","apotheker berard tagebuch"}},{q="Warum benötigt er Reagenzien aus dem Kral der Klingenhauer und dem Scharlachroten Kloster?",a="Faranell testet, wie gegensätzliche, flüchtige Verbindungen miteinander interagieren. Er verwendet Kralguano aus den Höhlen der Borstennacken von Razorfen zusammen mit den frisch entnommenen Herzen von Eiferern des Scharlachroten Kreuzzugs, um ätzende Kolloide und biologische Kontamination zu untersuchen.",al={"kralguano faranell","herzen des eifers","scharlachrotes kloster herzen"}}},fx={["90cc21c1"]={q="Auf wessen Seite steht Apothekermeister Faranell?",a="Faranell ist voll und ganz Fürstin Sylvanas Windläufer und den Verlassenen ergeben. Als Meister der Königlichen Apothekergesellschaft richtet er seine Forschung direkt an den Ambitionen der Dunklen Fürstin aus und mobilisiert seine Alchemisten, um ihre Feinde auszurotten und das Überleben der untoten Nation zu sichern, ungeachtet der moralischen Kosten.",al={"faranell loyalität","wem dient faranell","ist faranell loyal zu sylvanas"}},b168fd3d={q="Warum ist Apothekermeister Faranell in der Unterstadt?",a="Faranell beaufsichtigt Das Apothekarium, das alchemistische Herz der Unterstadt. Von diesem weitläufigen Labor aus, erfüllt von blubbernden Bottichen und giftigen Dämpfen, leitet er die Forschung der Königlichen Apothekergesellschaft, testet gefährliche Gebräue und koordiniert die Synthese mächtiger neuer Seuchen und Monstrositäten für die Verlassenen.",al={"warum ist faranell hier","faranell apothekarium","warum ist faranell in unterstadt"}},["79d7ca05"]={q="Mit wem ist Apothekermeister Faranell verbunden?",a="Faranell dient direkt Königin Sylvanas Windläufer und leitet die Königliche Apothekergesellschaft, wobei er untergeordnete Forscher wie Apotheker Renferrel im Silberwald und Apotheker Lydon im Vorgebirge des Hügellands anleitet. Er pflegt auch Verbindungen zu anderen Forschern und setzt die Arbeiten ehemaliger Kollegen wie Apotheker Berard zusammen.",al={"faranell verbindungen","wer arbeitet mit faranell","faranell verbündete"}},d3e005f3={q="Warum wird Apothekermeister Faranell gefürchtet?",a="Einst ein angesehener Gelehrter in Dalaran, wandelte sich Faranells intellektuelle Brillanz nach seinem Aufstieg im Untod in tiefgründigen Sadismus. Er ist berüchtigt als der dunkle Architekt hinter den tödlichsten Giften und Seuchen der Verlassenen und testet schreckliche neue Gebräue an Lebenden wie Toten gleichermaßen, ohne einen Funken Reue.",al={"warum ist faranell berühmt","faranell ruf","ist faranell gefährlich"}}},fp="26,293,24.557.0,30.456.0,23.496.1,34.230.0,28.184.0,46.234.0,54.242.0,55.235.0,72.238.0"}
P.entries["npc:master-apothecary-lydon"] = {fx={["4ad88718"]={q="Auf wessen Seite steht Apotheker Lydon?",a="Apotheker Lydon ist Fürstin Sylvanas Windläufer, den Verlassenen und der Horde gegenüber äußerst loyal. Er ist ein leitender Forscher in der Königlichen Apothekergesellschaft und nimmt direkte Anweisungen von Apothekermeister Faranell in der Unterstadt entgegen. Alles, was er braut, dient Sylvanas' großen Plänen, das Reich für die Untoten zu sichern.",al={"lydon fraktion","wem dient lydon","ist lydon verlassener"}},["64f2c0db"]={q="Was will Apotheker Lydon?",a="Lydon ist besessen von der Erschaffung und Perfektionierung der Neuen Seuche für die Dunkle Fürstin. Er sucht nach wirksamen Toxinen, Raubtierblut und tödlichen Giften aus der gesamten Region, um seine Gebräue zu verfeinern – einschließlich des Elixier des Leidens und Elixir of Agony –, mit dem Ziel, den Lebenden Elend und Tod zu bringen.",al={"was versucht lydon zu tun","lydon ziel","warum will lydon gifte"}},["26e1a5a5"]={q="Warum ist Apotheker Lydon in Tarrens Mühle?",a="Lydon ist im Apothekenlabor von Tarrens Mühle stationiert, um regionale Reagenzien zu sammeln und tödliche alchemistische Formeln in der Nähe von feindlichem Gebiet zu testen. Das Vorgebirge des Hügellands bietet fruchtbare Testgelände gegen lokale Wildtiere, feindliche Zwergeneinfälle und die Menschenstadt Süderstade gleich die Straße hinunter.",al={"warum ist lydon im hügelland","lydon tarrens mühle zweck","warum ist apotheker lydon hier"}}}}
P.entries["npc:master-gadrin"] = {n="Meister Gadrin",s="Meister Gadrin ist ein ältlicher Dschungeltroll und ein ehrwürdiger Hexendoktor des Dunkelspeer-Stammes, der derzeit in Sen'jin lebt. Nachdem er einst an der Seite des abtrünnigen Hexendoktors Zalazane die Priester und Magier des Stammes ausgebildet hatte, koordiniert er nun die Bemühungen, seinem vertriebenen Volk beizustehen und den finsteren Fluch zu brechen, der ihre geraubte Heimat auf den Echoinseln im Griff hält.",h="Meister Gadrin ist ein ältlicher Dschungeltroll und ein ehrwürdiger Hexendoktor des Dunkelspeer-Stammes, der...",kw={"dunkelspeer","durotar","die echoinseln","gadrin","meister gadrin","minshina","sen'jin","vol'jin","hexendoktor","zalazane"},ang={["class:Mage"]="Gadrin beschritt neue Wege, indem er Dunkelspeer-Trolle nach dem Dritten Krieg in den arkanen Künsten unterwies, womit er bewies, dass trollische Magie weit über rohes Ritual-Mojo hinausreichen konnte.",["class:Priest"]="Als Ältester, der die Priester der Dunkelspeer in der Zwiesprache mit den Geistern und den Loa unterwies, verkörpert Gadrin die Schatten- und Glaubenstraditionen der Dschungeltrolle.",["faction:Horde"]="Meister Gadrin ist einer der vertrautesten Berater von Vol'jin; er behält die Küste von Durotar wachsam im Auge und warnt Klingenhügel, wenn finstere Kulte die noch junge Nation Durotar bedrohen.",["race:Troll"]="Für die Dunkelspeer ist Meister Gadrin eine lebendige Verbindung zu Eurer angestammten Heimat und den Traditionen von Sen'jin. Er hat die spirituelle Führung Eures Stammes über Generationen hinweg geprägt und empfindet väterliche Trauer über die Tragödie der Echoinseln."},sec={{t="Mentor der Dunkelspeer",b="Lange bevor die Dunkelspeer auf Kalimdor ankamen, diente Meister Gadrin seinem Stamm als Hexendoktor auf ihren angestammten Inseln in den südlichen Meeren, wo er die mystische Ausbildung ganzer Generationen von Dunkelspeer-Trollen anleitete."},{t="Der Verrat von Zalazane",b="Als sich die Dunkelspeer an der Seite der Horde auf den Echoinseln niederließen, leiteten Gadrin und der junge Hexendoktor Zalazane gemeinsam die mystische Ausbildung der Priester und Magier des Stammes. Tragischerweise verfiel Zalazane dem Wahnsinn, berauscht von den dunklen Voodoo-Kräften, die er zu beherrschen suchte. Der abtrünnige Ausübende versklavte den Geist seiner Brüder und vertrieb Vol'jin und die unberührten Dunkelspeer auf das Festland von Durotar. Nun in Sen'jin ansässig, trägt Gadrin den persönlichen Schmerz in sich, mitansehen zu müssen, wie ein einstiger Gefährte zu einem tyrannischen Ungeheuer wurde; unermüdlich arbeitet er daran, erschlagene Stammesangehörige zur Ruhe zu betten und Zalazanes Herrschaft zu beenden."},{t="Hüter uralten Wissens",b="Über die Krise auf den Echoinseln hinaus gilt Gadrin als eine der größten lebenden Autoritäten der Horde in puncto Troll-Spiritualismus und Loa-Kunde. Gelehrte, Schamanen und sogar die Königliche Apothekervereinigung suchen seinen Rat bei arkanen und alchemistischen Rätseln. Wenn seltsame Bedrohungen wie die Burning Blade an Durotar heranrücken oder weit entfernte Forscher vergessene Rituale benötigen – wie das Entziffern uralter Tafeln in Zul'Farrak zur Anrufung der Spinnen-Loa Shadra –, besitzt Gadrin das Wissen, um die notwendigen Bannsprüche zu weben."}},faq={{q="Wer ist Meister Gadrin?",a="Meister Gadrin ist ein Hexendoktor und ein älterer spiritueller Anführer der Dunkelspeer. An der Küste Durotars in Sen'jin gelegen, dient er Häuptling Vol'jin als ranghoher Berater.",al={"meister gadrin lore","wer ist gadrin","gadrin nsc"}},{q="Welche gemeinsame Geschichte verbindet Gadrin mit Zalazane?",a="Auf den Echoinseln leiteten Gadrin und der junge Hexendoktor Zalazane gemeinsam die mystische Ausbildung der Priester und Magier der Dunkelspeer, nur dass Gadrin mit Entsetzen mitansehen musste, wie Zalazane dunkler Magie verfiel, dem Wahnsinn anheimfiel und die Dunkelspeer aus ihrer Inselheimat vertrieb.",al={"gadrin und zalazane","woher kennt gadrin zalazane","zalazane mentor"}},{q="Warum hält sich Gadrin in Sen'jin auf?",a="Als Zalazanes Fluch die Dunkelspeer von den Echoinseln vertrieb, errichteten die Überlebenden an der Südküste von Durotar Sen'jin als Zuflucht. Gadrin bleibt in dem Dorf, um Flüchtlinge zu beraten, lokale Bedrohungen zu überwachen und Schläge gegen Zalazanes Streitkräfte zu lenken.",al={"warum ist gadrin hier","was macht gadrin in senjin"}},{q="Wer ist Minshina?",a="Minshina war Meister Gadrins Bruder. Er kam während der Unruhen auf den Echoinseln ums Leben, und sein unruhiger Geist begann, Gadrin in Träumen zu rufen. Gadrin bittet vertrauenswürdige Abenteurer darum, den Schädel seines Bruders zu bergen, damit dessen Seele endlich Frieden finden kann.",al={"minshina bruder","minshinas schädel quest lore","wer war minshina"}},{q="Hilft Gadrin gegen den Kult der Burning Blade?",a="Ja. Nachdem er von Zureetha Fernblick Nachricht über die Infiltration des Tals der Prüfungen durch die Burning Blade erhalten hat, überwacht Gadrin die Präsenz des Kults nahe Sen'jin. Da er die größere Gefahr für Durotar erkennt, schickt er Rekruten nach Norden, um Orgnil Narbenseele in Klingenhügel Bericht zu erstatten.",al={"burning blade durotar gadrin","orgnil narbenseele gadrin"}},{q="Was weiß Gadrin über die Loa Shadra?",a="Gadrin ist ein Meister uralter trollischer Theologie. Als der Verlassene Apotheker Lydon nach einem wirkungsvollen Gift sucht, das von den Witherbark-Trollen im Hinterland verwendet wird, identifiziert Gadrin es als Gabe der Spinnen-Loa Shadra; er schickt Abenteurer nach Zul'Farrak, um die Tafel mit ihrem wahren Namen zu entziffern, die er benötigt, um einen Beschwörungszauber zu verfassen.",al={"shadra spinnen loa gadrin","gadrin spinnengott"}}},fx={["48c543c3"]={q="Auf wessen Seite steht Meister Gadrin?",a="Meister Gadrin ist dem Stamm der Dunkelspeere und der Horde gegenüber loyal. Nachdem er von den Dunkelspeerinseln gereist war, nachdem Thrall sein Volk vor der Meerhexe gerettet hatte, dient er als hochrangiger Ältester, mystischer Lehrer und vertrauter Berater von Häuptling Vol'jin.",al={"fraktion von gadrin","ist gadrin horde","wem dient gadrin"}},d3faca51={q="Was will Meister Gadrin?",a="Meister Gadrin sucht den Tod des verräterischen Hexendoktors Zalazane und die Befreiung der Die Echoinseln. Er möchte seine verfluchten Verwandten von Zalazanes Gedankenkontrolle befreien, den Schädel seines verstorbenen Bruders Minshina zurückgewinnen, damit die Geister ruhen können, und Sen'jin vor aufkommenden Gefahren in ganz Durotar schützen.",al={"was will gadrin","ziel von gadrin","motiv von meister gadrin"}}},fp="13,354,23.211.0,24.606.0,22.522.0,21.190.0,39.259.0,41.267.0,16.245.0,45.268.0,43.327.0"}
P.entries["npc:master-vornal"] = {fx={e0bd334a={q="Auf wessen Seite steht Meister Vornal?",a="Meister Vornal ist dem Stamm der Dunkelspeere und der Horde gegenüber loyal. Er hat sein Zuhause in Sen'jin und stellt sein Handwerk und seine Erfahrung zur Verfügung, um die junge Siedlung vor Gefahren aus der Umgebung zu schützen.",al={"loyalität von vornal","wem dient meister vornal","fraktion von meister vornal"}},["27223be8"]={q="Warum ist Meister Vornal in Sen'jin?",a="Meister Vornal lebt an der Küste von Durotar, um seinen Verwandten zu helfen, während sie sich im Exil ein neues Dasein aufbauen. Von seinem Zuhause in Sen'jin aus übt er sein Handwerk aus und beauftragt Reisende damit, die starken Reagenzien zu sammeln, die er benötigt.",al={"warum ist meister vornal hier","warum ist vornal in senjin","zweck von vornal in durotar"}},faf3afd9={q="Was will Meister Vornal?",a="Obwohl er altert, arbeitet Meister Vornal lieber unabhängig und weigert sich, sich mit Lehrlingen zu belasten. Stattdessen sucht er fähige Abenteurer, die seine Besorgungen erledigen und seltene Destillate und Lösungsmittel in ganz Durotar sammeln.",al={"was will vornal","ziel von meister vornal","wonach sucht vornal"}}}}
P.entries["npc:mastok-wrilehiss"] = {n="Mastok Wutfauch",s="Mastok Wutfauch ist ein Ork-Offizier, der im Splitterholzposten im östlichen Eschental stationiert ist. Als entscheidender Verteidigungskoordinator für die Horde in dem umkämpften Wald weist er Späher und Krieger an, nahegelegene Grenzen zu sichern und gegen verderbende elementare Bedrohungen vorzugehen. Seine Anwesenheit ist unerlässlich, um den prekären Stützpunkt der Horde inmitten der ständigen Feindseligkeit der Nachtelfen zu halten.",h="Mastok Wutfauch ist ein Ork-Offizier, der im Splitterholzposten im östlichen Eschental stationiert ist.",kw={"eschental","der irdene ring","mastok","ork","splintertree","steinkralle","wrilehiss"},ang={["class:Shaman"]="Mastoks Sorge über verdorbene Elementare im Wald veranlasst Abenteurer oft dazu, Rat beim Irdenen Ring am Zoram'gar Strand zu suchen.",["faction:Alliance"]="Mastok Wutfauch repräsentiert die verschanzte militärische Präsenz der Orks in Eschental und verteidigt die befestigte Siedlung Splintertree gegen die Schildwachen der Nachtelfen.",["faction:Horde"]="Für Champions der Horde, die darum kämpfen, einen Vorposten in Eschental zu behaupten, ist Mastok ein maßgeblicher Kommandant, der Euch zu entscheidenden Aufgaben in der gesamten Region leiten kann."},sec={{t="Ein Bollwerk in den uralten Wäldern",b="Der Splitterholzposten liegt tief im Schatten des hoch aufragenden Blätterdachs von Eschental, vollständig umgeben von feindseligem Nachtelfengebiet. Mastok Wutfauch dient als einer der wichtigsten Verteidiger des Postens und überwacht Nachschubwege sowie Aktivitäten im Wald. Die Lage ist heikel; jedes Zeichen von Schwäche zieht rasche Angriffe der Schildwachen nach sich, die die Siedlung als frevelhaften Eingriff betrachten."},{t="Koordination der Front",b="Von seinem Posten innerhalb der Palisade aus betraut Mastok vorbeikommende Abenteurer aktiv mit entscheidenden strategischen Aufgaben. Er behält die Grenzen zu benachbarten Gebieten wie dem Steinkrallengebirge wachsam im Auge und entsendet Späher, um Schamanen wie Je'neu Sancrea vom Irdenen Ring am Zoram'gar Strand zu Rate zu ziehen. Seine Pflichten verbinden militärische Verteidigung mit der Beobachtung der seltsamen, verderbenden Kräfte, die den örtlichen Elementaren zusetzen."}},faq={{q="Wer ist Mastok Wutfauch?",a="Mastok Wutfauch ist ein Elite-Ork, der im Splitterholzposten in Eschental stationiert ist. Er fungiert als Offizier und Questgeber mit der Aufgabe, den Außenposten gegen Übergriffe der Nachtelfen zu verteidigen und nahegelegene regionale Bedrohungen zu untersuchen.",al={"wer ist mastok","mastok wutfauch rolle","wer ist dieser ork"}},{q="Wo ist Mastok Wutfauch zu finden?",a="Er befindet sich im Splitterholzposten, einem befestigten Außenposten der Horde im zentral-östlichen Eschental an der Hauptwaldstraße.",al={"mastok aufenthaltsort","wo ist mastok wutfauch","mastok karte"}},{q="Welche Aufgaben überträgt Mastok den Abenteurern?",a="Mastok betraut Horde-Abenteurer mit strategischen Aufgaben, darunter die Untersuchung verdorbener elementarer Bedrohungen im Wald, die Sicherung der Pässe ins Steinkrallengebirge und die Entsendung von Boten zu Je'neu Sancrea vom Irdenen Ring.",al={"mastok quests","quests von mastok"}},{q="Warum steht der Splitterholzposten unter ständigem Druck?",a="Der Außenposten dient als zentrales Holzfällerlager und als Festung der Horde in Eschental. Die einheimischen Nachtelfen betrachten die Anwesenheit der Orks und ihren Holzschlag als schwere Entweihung heiligen Landes, was zu unablässigen Scharmützeln führt.",al={"warum greifen nachtelfen splintertree an","splintertreeposten konflikt"}},{q="Warum schickt Mastok Reisende zu Je'neu Sancrea?",a="Die Schamanen des Irdenen Rings, darunter Je'neu am Zoram'gar Strand, erforschen und heilen die elementare Instabilität, die Eschental heimsucht. Mastok verbindet die Kämpfer an vorderster Front mit deren spiritueller Expertise, um gegen verdorbene Wasserelementare und seltsame Störungen vorzugehen.",al={"warum irdenen ring kontaktieren","mastok und jeneu"}},{q="Ist Mastok Wutfauch Spielern der Allianz feindlich gesinnt?",a="Ja. Mastok ist ein loyales Mitglied der Horde und ein Elite-Verteidiger des Splitterholzpostens, was bedeutet, dass er Spieler der Allianz sofort angreift, sobald sie sich dem Lager nähern.",al={"kann allianz mit mastok sprechen","kann man mastok töten"}}},fx={["414a3ea9"]={q="Warum ist Mastok Wutfauch im Eschental?",a="Mastok Wutfauch ist im Splitterholzposten stationiert, um dabei zu helfen, den Stützpunkt der Horde in den umkämpften Wäldern des Eschentals zu sichern. Als erfahrener Verteidiger unter den Streitkräften des Kriegshymnenklans überwacht er lokale Verteidigungsbemühungen, verfolgt Störungen, die die umliegende Wildnis betreffen, und rekrutiert fähige Reisende, um mit verderblichen Elementarbedrohungen und den Feindseligkeiten der benachbarten Nachtelfen umzugehen.",al={"warum ist mastok hier","mastok wutfauch splitterholzposten","warum ist mastok am splitterholzposten"}}},fp="16,381,30.377.0,22.436.0,24.219.0,36.129.0,45.216.0,49.238.0,49.251.0,48.172.0"}
P.entries["npc:mathias-shaw"] = {fx={ad27d291={q="Auf wessen Seite steht Mathias Shaw?",a="Meister Mathias Shaw dient der Allianz, dem Haus Wrynn und dem Königreich Sturmwind mit unerschütterlicher Loyalität. Als Anführer des Geheimdienstbüros des Reiches ist jede verdeckte Mission, die er beaufsichtigt, und jeder Spion, den er leitet, der Sicherung Sturmwinds vor innerer Unterwanderung und ausländischen Bedrohungen gewidmet.",al={"fraktion von mathias shaw","wem dient shaw","ist mathias shaw loyal"}},["14719004"]={q="Was will Mathias Shaw?",a="Shaws Hauptanliegen ist es, existenzielle Bedrohungen für Sturmwind zu beseitigen, bevor sie zuschlagen. Er leitet das verdeckte Netzwerk von SI:7, um die Pläne der The Defias Brotherhood zu vereiteln, gefährliche Bewegungen der Verlassenen im Norden zu überwachen und die Informationen zu sammeln, die notwendig sind, um die Sicherheit des Königreichs in einer Ära tiefgreifender politischer Verwundbarkeit zu bewahren.",al={"ziel von mathias shaw","was will shaw","motive von shaw"}},a0b783f7={q="Warum ist Mathias Shaw berühmt oder gefürchtet?",a="Shaw ist im gesamten Königreich als der Meister der Spione und der Meister der Assassinen bekannt. Berühmt für seine überragenden Fähigkeiten in Verstohlenheit, Infiltration und lautloser Tödlichkeit, bedeutet sein weitreichendes Spionagenetzwerk, dass nur sehr wenig im Königreich ohne sein Wissen geschieht – oder ohne das Eingreifen seiner Klingen.",al={"warum ist mathias shaw berühmt","warum ist shaw gefürchtet","meister der assassinen"}}}}
P.entries["npc:mathredis-firestar"] = {n="Mathredis Feuerstern",s="Mathredis Feuerstern ist ein exzentrischer Blutelfenmagier, der auf dem Flammenkamm in der Brennenden Steppe residiert. Er fertigt mächtige Verzauberungen an, die als geringe Arkanums bekannt sind, und stützt sich dabei auf die Arkanforschungen seines verstorbenen Meisters. Dabei nährt er sich von den Restenergien, die während des Bindungsprozesses freigesetzt werden, um seine Magiesucht zu stillen.",h="Mathredis Feuerstern ist ein exzentrischer Blutelfenmagier, der auf dem Flammenkamm in der Brennenden Steppe...",kw={"arkanum","brennende steppe","dreamseeker","firestar","flammenkamm","buchband","mathredis","telmius"},ang={["class:Mage"]="Magier werden Mathredis' Arkanumsynthese als eine verzweifelte, unberechenbare Methode erkennen, rohe magische Nahrung aus dem Prozess der Gegenstandsbindung zu ziehen."},sec={{t="Das Erbe eines Meisters und Magiesucht",b="Mathredis Feuerstern erlernte das Handwerk der Herstellung von Arkanums – konzentrierten Edelsteinen arkaner Ermächtigung – von seinem Mentor Telmius Dreamseeker. Telmius fand in den uralten Ruinen von Düsterbruch ein grausiges Ende, als er versuchte, den Shen'dralar magische Geheimnisse zu entreißen. Obwohl Telmius diese magischen Bindungen erfand, fehlt Mathredis die Meisterschaft, um die mächtigsten von ihnen herzustellen. Stattdessen spezialisiert er sich auf geringe Arkanums. Für Mathredis ist diese Arbeit weit mehr als eine akademische Übung: Wie alle Blutelfen nach dem Fall des Sonnenbrunnens leidet er unter einem nagenden Hunger nach arkaner Macht. Das Binden von Materialien an uralte Buchbände setzt heftige Entladungen magischer Energie frei, die Mathredis absaugt, um sich selbst zu erhalten."},{t="Die Kunst des Arkanums",b="Abenteurer, die Mathredis die richtigen Wälzer – wie die Buchbände der Konstitution, der Zähigkeit, des Nachsinnens, der Beharrlichkeit oder der Gier – zusammen mit seltenen Reagenzien bringen, werden feststellen, dass er sein Handwerk nur zu gern anbietet. Der Vorgang bindet flüchtige magische Reagenzien direkt an den Text und konzentriert deren Essenz in einem Arkanum, das Kopfbedeckungen oder Beinrüstungen dauerhaft verzaubern kann. Solange Abenteurer die Komponenten liefern, erhält Mathredis sowohl eine Bezahlung als auch die flüchtige arkane Nahrung, nach der er sich so verzweifelt sehnt."}},faq={{q="Wer ist Mathredis Feuerstern?",a="Mathredis Feuerstern ist ein Blutelfenmagier, der am neutralen Außenposten Flammenkamm in der Brennenden Steppe stationiert ist. Er ist ein Arkanist, der in der Lage ist, geringe Arkanums zur Verzauberung von Rüstung zu schmieden.",al={"mathredis lore","wer ist mathredis feuerstern","firestar blutelf"}},{q="Warum erschafft Mathredis Arkanums?",a="Nach der Zerstörung des Sonnenbrunnens leiden Blutelfen unter schweren magischen Entzugserscheinungen. Mathredis ernährt sich von den rohen, verbleibenden magischen Energien, die bei der Erschaffung und Bindung von Arkanums freigesetzt werden, um seine völkische Sucht zu lindern.",al={"warum arkanums herstellen","mathredis motivation","warum buchbände"}},{q="Wer war Telmius Dreamseeker?",a="Telmius Dreamseeker war Mathredis' verstorbener Meister und der ursprüngliche Erfinder der Arkanums. Telmius wagte sich in die Ruinen von Düsterbruch, um Wissen von den Shen'dralar zu erlangen, wurde dort jedoch ermordet, bevor er sein gesamtes Wissen vollständig weitergeben konnte.",al={"telmius","mathredis meister","wer war sein meister"}},{q="Welche Arten von Arkanums kann Mathredis herstellen?",a="Mathredis kann geringe Arkanums der Konstitution, der Zähigkeit, des Nachsinnens, der Beharrlichkeit und der Gier schmieden. Die mächtigsten Arkanums waren nur seinem Meister Telmius bekannt und bleiben außerhalb von Mathredis' Reichweite.",al={"welche arkanums","geringe arkanums","buchband liste"}}},fp="18,330,37.709.0,22.497.0,26.181.0,35.233.0,28.245.0,42.200.0"}
P.entries["npc:mathrengyl-bearwalker"] = {fx={d00fa4f6={q="Auf wessen Seite steht Mathrengyl Bärenfährte?",a="Mathrengyl ist dem Zirkel des Cenarius und den Nachtelfen von Darnassus gegenüber loyal. Als prominenter Druid of the Claw, der in der Die Enklave des Cenarius residiert, dient er sowohl den Kaldorei als auch dem breiteren druidischen Orden und strebt danach, das Gleichgewicht der Natur in ganz Kalimdor aufrechtzuerhalten.",al={"fraktion von mathrengyl","wem dient mathrengyl","ist mathrengyl allianz"}},["88f66b3d"]={q="Warum ist Mathrengyl Bärenfährte in Darnassus?",a="Mathrengyl lebt in der Die Enklave des Cenarius, um junge Nachtelfdruiden bei ihren heiligen Pflichten anzuleiten und zu unterrichten. Im Herzen der Kaldorei-Gesellschaft auf Teldrassil stehend, hilft er Initianden, Tierformen zu erlernen, sich mit den Geistern der Wildnis zu verbinden und natürliche Krisen anzugehen, die das Reich bedrohen.",al={"warum ist mathrengyl hier","grund für mathrengyl in darnassus","was bringt mathrengyl nach darnassus"}}}}
P.entries["npc:maur-grimtotem"] = {n="Maur Grimmtotem",s="Maur Grimmtotem war ein Abgesandter, der von The Elder Crone Magatha Grimmtotem in die Tiefen des Flammenschlunds entsandt wurde. Er wurde auf eine zum Scheitern verurteilte diplomatische Mission zu den Troggs geschickt, die die unterirdischen Tunnel unter Orgrimmar bevölkern, und fand durch ihre Hände ein grausames Ende. Heute zeugen nur noch seine Überreste und seine persönliche Tasche in der Dunkelheit von diesem törichten Unterfangen.",h="Maur Grimmtotem war ein Abgesandter, der von The Elder Crone Magatha Grimmtotem in die Tiefen des...",kw={"grimmtotem","magatha","maur","flintauge","orgrimmar","flammenschlund","tasche","trogg"},ang={["faction:Horde"]="Ein tödliches unterirdisches Höhlensystem direkt unter Orgrimmar zu haben ist schon schlimm genug; einzelne Abgesandte loszuschicken, um mit Troggs zu verhandeln, erwies sich als absolut verhängnisvoll für die Sicherheit der Horde.",["race:Tauren"]="Der Grimmtotem-Clan unterhält ein schwieriges Verhältnis zu den anderen Stämmen in Donnerfels, und Maurs bizarres, tödliches Unterfangen in den Trogg-Tunneln verstärkt nur den Argwohn gegenüber Magathas wahren Absichten."},sec={{t="Eine verhängnisvolle Diplomatie",b="Während die meisten in der Horde Troggs als gedankenlose, wilde Bestien betrachten, die unter ihrer Würde stehen, um mit ihnen zu verhandeln, sah The Elder Crone Magatha Grimmtotem dies anders – oder behauptete es zumindest. Sie entsandte Maur Grimmtotem tief in die verschlungenen Höhlen des Flammenschlunds unter Orgrimmar, um einen Friedensversuch mit den unterirdischen Bestien zu wagen. Wie zu erwarten war, scheiterte die Diplomatie. Maur wurde schnell getötet und seine Leiche unter den wachsamen Augen des Trogg-Häuptlings Flintauge in den Höhlen zurückgelassen."},{t="Die Interessen von The Elder Crone",b="Nach Maurs Ableben suchte Magatha Abenteurer, nicht nur um ihn zu rächen, sondern auch, um die persönliche Tasche zu bergen, die er in die Tiefen mitgenommen hatte. Ob Maur wirklich glaubte, dass Frieden mit den Troggs möglich sei, oder ob er nur ein entbehrlicher Spielball in den zwielichtigen Plänen der Grimmtotem-Matriarchin war, bleibt eine offene Frage für diejenigen, die seine Habseligkeiten bergen."}},faq={{q="Wer war Maur Grimmtotem?",a="Maur war ein Taure, der dem Grimmtotem-Clan angehörte. Auf Befehl von Magatha Grimmtotem wagte er sich als Abgesandter zu den Troggs in die Höhlen des Flammenschlunds unter Orgrimmar, wo er getötet wurde.",al={"wer ist maur","maur grimmtotem hintergrundgeschichte","was tat maur"}},{q="Warum versuchte er, mit Troggs zu verhandeln?",a="The Elder Crone Magatha behauptete, sie habe ihn geschickt, um Frieden zu suchen und die Stärke dieser unterirdischen Feinde zu testen. Angesichts der wilden Natur der Troggs vermuten viele, dass Magatha Hintergedanken hatte oder Maur einfach benutzte, um die Tiefen des Flammenschlunds zu erkunden.",al={"warum frieden mit troggs","trogg-diplomatie","warum mit troggs sprechen"}},{q="Wer tötete Maur Grimmtotem?",a="Maur wurde von dem Trogg-Stamm getötet, der im Flammenschlund lebt. Seine Leiche wurde streng bewacht von Flintauge gefunden, dem Häuptling der Troggs im Flammenschlund.",al={"wie starb maur","wer tötete ihn","maurs tod"}},{q="Was geschah mit seinem Körper und seinen Habseligkeiten?",a="Maurs Körper wurde im Flammenschlund in der Nähe von Flintauge zurückgelassen. Abenteurer werden von Rahauro in Donnerfels beauftragt, Maurs verlorene Tasche zu bergen und sie ihm auf der Anhöhe der Ältesten für Magatha Grimmtotem zurückzubringen.",al={"maurs leiche","verlorene tasche","maurs tasche"}}},fx={c7d44e51={q="Auf wessen Seite stand Maur Grimmtotem?",a="Maur antwortete direkt der Ältestenmatrone Magatha Grimmtotem und diente den Interessen des Grimmtotem-Clans. Während die Grimmtotem technisch gesehen zur Horde zählen, aufgrund ihrer unbehaglichen Präsenz auf der Die Anhöhe der Ältesten in Donnerfels, gehörten Maurs Loyalitäten und seine geheime Mission ausschließlich seinem Clan.",al={"fraktion von maur grimmtotem","wem dient maur grimmtotem","maur grimmtotem allianz horde"}},["565aa8ac"]={q="Was wollte Maur Grimmtotem?",a="Maur versuchte, ein Bündnis oder ein friedliches Abkommen mit den Troggs zu schließen, die die Schluchten unter Orgrimmar befallen. Den Anweisungen von Magatha Grimmtotem folgend, wagte er sich in den Der Flammenschlund in der Hoffnung, mit den Kreaturen zu verhandeln, ohne zu wissen, dass ihre wilde und gewalttätige Natur jegliche diplomatische Einigung unmöglich machte.",al={"was hat maur grimmtotem getan","mission von maur grimmtotem","ziel von maur grimmtotem"}},bfc0472b={q="Mit wem war Maur Grimmtotem verbunden?",a="Maur war ein Abgesandter, der von Magatha Grimmtotem entsandt wurde, der Matriarchin des Grimmtotem-Clans, die derzeit auf der Die Anhöhe der Ältesten in Donnerfels residiert. Er führte ihre privaten Pläne unter Orgrimmar aus und hielt seine Mission von der regulären Führung der Horde getrennt.",al={"wer hat maur grimmtotem entsandt","verbindungen von maur grimmtotem","maur grimmtotem magatha"}}},fp="14,352,18.458.0,27.345.1,23.209.0,40.232.0,26.149.0,41.208.0"}
P.entries["npc:maur-raincaller"] = {n="Maur Regenrufer",s="Maur Regenrufer ist ein Tauren, der im Dorf der Bluthufe in Mulgore ansässig ist. Verbunden mit dem natürlichen und spirituellen Leben der Ebenen unterstützt er die Dorfältesten und wacht über lokale Belange, die die Herden und wilden Bestien betreffen.",h="Maur Regenrufer ist ein Tauren, der im Dorf der Bluthufe in Mulgore ansässig ist.",kw={"bloodhoof","maur regenrufer","mazzranache","mulgore","ebenenschreiter","tauren"},ang={["class:Hunter"]="Maur stellt Euch vor eine frühe Jagdprüfung und schickt Euch los, um von den Wölfen, Pumas, Eitsträußen und Sturzfliegern der offenen Ebenen die Teile zu beschaffen, die er zur Heilung von Mazzranaches giftigem Biss benötigt.",["race:Tauren"]="Jungen Tauren, die aus Camp Narache aufbrechen, bietet Maur eine Gelegenheit, das angestammte Land Eures Volkes vor umherstreifenden Raubtieren und unruhigen Bestien zu schützen."},sec={{t="Ein Bewohner des Dorfes der Bluthufe",b="Nahe dem Herzen des Dorfes der Bluthufe an den Ufern des Lake Stonebull gelegen, dient Maur Regenrufer seiner Gemeinschaft, indem er sich um regionale ökologische Belange und Tierangelegenheiten kümmert. Wie viele, die den Namen Raincaller tragen, achtet er aufmerksam auf das Gleichgewicht der Elemente und der Tierwelt in den fruchtbaren Ebenen von Mulgore. Nachdem die Wunde durch den Biss des furchterregenden Schreiters Mazzranach sich entzündet hat, wendet sich Maur an fähige junge Reisende, um die Tierbestandteile zu sammeln, die er für ein Heilmittel benötigt."}},faq={{q="Wer ist Maur Regenrufer?",a="Maur Regenrufer ist ein Taure, der im Dorf der Bluthufe in den saftigen Graslanden von Mulgore lebt. Er fungiert als lokaler Questgeber und beauftragt Abenteurer damit, die unbändige Tierwelt im Umland in Schach zu halten.",al={"maur regenrufer rolle","wer ist maur","maur regenrufer lore"}},{q="Wo kann ich Maur Regenrufer finden?",a="Er steht unter freiem Himmel zwischen den Tipi-Zelten und Herdfeuern des Dorfes der Bluthufe, südlich von Donnerfels am Ostufer des Lake Stonebull gelegen.",al={"maur regenrufer aufenthaltsort","wo ist maur","maur koordinaten"}},{q="Mit welchen Problemen schlägt sich Maur herum?",a="Maur wurde von Mazzranach gebissen, einem furchterregenden Schreiter aus den Geschichten seines Großvaters, und die Wunde hat sich entzündet. Er bittet Abenteurer darum, ihm Teile von den Wölfen, Pumas, Eitsträußen und Sturzfliegern von Mulgore zu bringen, damit er ein Heilmittel herstellen kann.",al={"maur regenrufer quest","mazzranache problem","was will maur"}}},fx={fd24c378={q="Auf wessen Seite steht Maur Regenrufer?",a="Maur Regenrufer ist ein loyaler Tauren des Stammes der Bluthufe und ein Anhänger der Horde. Da er im Dorf der Bluthufe lebt, liegt seine Loyalität fest bei Häuptling Cairne Bluthuf und der Sicherheit der Ebenen von Mulgore.",al={"fraktion von maur regenrufer","ist maur regenrufer horde","wem dient maur"}}},fp="15,241,31.493.0,23.204.0,33.168.0,34.243.0"}
P.entries["npc:maxan-anvol"] = {fx={["32034ea0"]={q="Wer ist Maxan Anvol?",a="Maxan Anvol ist ein Zwergenpriester des Heiligen Lichts, der in Kharanos stationiert ist. Er dient als Ausbilder für angehende Anhänger in Dun Morogh und testet junge Akolythen auf ihre Disziplin und Gemeinschaft mit dem Licht, bevor er ihnen Gewänder gewährt, die ihrem Stand in der Kirche entsprechen.",al={"wer ist maxan","geschichte von maxan anvol","priesterausbilder kharanos"}},["310c3ecc"]={q="Auf wessen Seite steht Maxan Anvol?",a="Er steht loyal zum Königreich Eisenschmiede, dem Heiligen Licht und der Großen Allianz. Er widmet seinen Dienst dem Schutz der lokalen Bevölkerung von Dun Morogh und der Vorbereitung neuer Priester darauf, den Glauben in den Ländern der Allianz aufrechtzuerhalten.",al={"fraktion von maxan","ist maxan allianz","loyalität von maxan anvol"}},["1141108e"]={q="Was will Maxan Anvol?",a="Maxan versucht, die Hingabe an das Heilige Licht zu fördern und sicherzustellen, dass unerfahrene Priester gründlich auf die Prüfungen der Welt vorbereitet sind. Er testet aufstrebende Schüler, um sicherzustellen, dass sie ihrer heiligen Gewänder würdig sind, während er alle Passanten daran erinnert, niemals die Gnade des Lichts aufzugeben.",al={"ziel von maxan anvol","was will maxan","motiv von maxan anvol"}}}}
P.entries["npc:maybell-maclure"] = {n="Maybell Maclure",s="Maybell Maclure ist eine junge Frau, die in den Weinbergen der Maclures im Wald von Elwynn lebt. Trotz einer erbitterten, langjährigen Fehde zwischen ihrer Familie und den benachbarten Steinfelds hat sie sich heimlich in Tommy Joe Steinfeld verliebt.",h="Maybell Maclure ist eine junge Frau, die in den Weinbergen der Maclures im Wald von Elwynn lebt.",kw={"liebende","maclure","maybell","steinfeld","tommy joe","weinberge"},ang={["faction:Alliance"]="Für Abenteurer der Allianz, die durch den Wald von Elwynn reisen, ist Maybells Romanze eine Erinnerung daran, dass persönliche Sorgen und uralter Groll selbst in den Kernlanden des Königreichs fortbestehen."},sec={{t="Unglücklich verliebt in den Weinbergen",b="Das Leben in den Weinbergen der Maclures ist von endloser Arbeit und einem anhaltenden Groll gegen die benachbarte Familie Steinfeld geprägt. Mittendrin steht Maybell Maclure, die sich unsterblich in Tommy Joe Steinfeld verliebt hat, den jungen Erben des rivalisierenden Hofes. Getrennt durch wachsame Verwandte und alte familiäre Ressentiments sehnt sich Maybell nach jeder Gelegenheit, abseits der neugierigen Blicke ihrer Sippe mit Tommy Joe in Kontakt zu treten."},{t="Ein Gebräu für die wahre Liebe",b="Da Maybell die Grenze zwischen den Höfen nicht offen überqueren kann, ist sie auf mitfühlende Reisende und die Führung von Oma Steinfeld angewiesen. Mit der Hilfe des örtlichen Alchemisten von Goldhain, William Pestle, wird ein Unsichtbarkeitsschnaps gebraut. Durch das Trinken dieses verbotenen Tranks kann Maybell unbemerkt vom Gehöft der Maclures entkommen und unten am Flussufer kostbare Momente mit Tommy Joe verbringen."}},faq={{q="Warum können Maybell und Tommy Joe einander nicht sehen?",a="Die Familien Maclure und Steinfeld hegen seit Jahren eine erbitterte Rivalität. Da beide Haushalte jeglichen Kontakt zwischen den Sippen verbieten, müssen Maybell und Tommy Joe ihre Romanze absolut geheim halten, um nicht den Zorn ihrer Verwandten auf sich zu ziehen.",al={"warum familienfehde","maclure steinfeld fehde","warum können sie nicht zusammen sein"}},{q="Was hindert Maybell daran, das Weingut zu verlassen?",a="Ihre Familie bewacht sie wegen der Fehde mit den Steinfelds streng. Sie braucht Hilfe, um einen Weg zu finden, Tommy Joe zu treffen, ohne deren Aufmerksamkeit zu erregen.",al={"wie schleicht maybell sich heraus","unsichtbarkeitstrank elwynn","wie trifft sie tommy"}},{q="Wo trifft Maybell Tommy Joe?",a="Tommy Joe wartet am Flussufer an der Grenze zwischen den Weinbergen der Maclures und dem Hof der Steinfelds, verborgen vor dem direkten Blick beider Gehöfte.",al={"treffpunkt","wo treffen sie sich","wo ist tommy joe"}},{q="Wer hilft Maybell bei ihrer Romanze?",a="Oma Steinfeld erweist sich als verständnisvoll gegenüber der Not der Liebenden und schickt hilfsbereite Abenteurer zu William Pestle, dem Alchemisten in Goldhain, der die Mittel für ihr heimliches Stelldichein bereitstellt.",al={"wer hilft maybell","steinfeld helfer"}}},fx={c4338ded={q="Wer ist Maybell Maclure?",a="Maybell Maclure ist eine junge menschliche Frau, die in den Weinbergen der Maclures im Wald von Elwynn lebt. Sie steckt inmitten einer erbitterten, langjährigen Fehde zwischen ihrer Familie und deren Nachbarn, den Steinfelds, nachdem sie sich unsterblich in Tommy Joe Steinfeld verliebt hat.",al={"wer ist maybell","wer ist maybell maclure","maybell maclure hintergrundgeschichte"}},["9f94442c"]={q="Auf wessen Seite steht Maybell Maclure?",a="Sie ist eine loyale Untertanin der Allianz und eine Tochter des Hauses Maclure. Wenn es jedoch um die kleinliche, bittere Rivalität zwischen den Maclures und den Steinfelds geht, lehnt sie diesen Hass völlig ab und stellt ihre Liebe zu Tommy Joe über den Groll ihrer Familie.",al={"ist maybell allianz","auf wessen seite steht maybell","maybell fraktion"}},cbd5fa72={q="Was möchte Maybell Maclure?",a="Maybell möchte nichts sehnlicher, als mit Tommy Joe Steinfeld zusammen zu sein. Da ihre Familien einen intensiven gegenseitigen Hass hegen, sucht sie die Hilfe von verständnisvollen Reisenden und vertrauten Verbündeten, um Wege zu finden, ihn heimlich zu treffen, ohne dabei erwischt zu werden.",al={"was möchte maybell","maybell maclure ziel","warum braucht maybell hilfe"}},b079e731={q="Warum ist Maybell Maclure hier?",a="Maybell wohnt in den Weinbergen der Maclures, dem Anwesen ihrer Familie im südlichen Wald von Elwynn. Sie bleibt unter den wachsamen Augen ihrer Verwandten auf dem Gelände des Weinguts beschränkt und hofft auf eine Gelegenheit, sich davonzuschleichen und ihren Geliebten zu sehen.",al={"warum ist maybell maclure hier","warum ist maybell in den weinbergen"}},["26be6d7a"]={q="Mit wem ist Maybell Maclure verbunden?",a="Maybell ist Teil der Winzerfamilie Maclure. Sie ist romantisch mit Tommy Joe Steinfeld verbunden, dem Erben der rivalisierenden Farm der Steinfelds, und pflegt geheime Verbindungen zu Oma Steinfeld, die die heimliche Romanze des jungen Paares unterstützt.",al={"beziehungen von maybell maclure","mit wem ist maybell verwandt","maybell verbindungen"}}},fp="15,230,29.425.0,26.383.1,47.236.0,48.155.1,34.152.0,35.189.1"}
P.entries["npc:mebok-mizzyrix"] = {n="Mebok Mizzyrix",s="Mebok Mizzyrix ist ein geschäftstüchtiger Goblin-Unternehmer, der in der Hafenstadt Ratschet ansässig ist. Stets darauf bedacht, bizarre Reagenzien aus der Wildnis zu Geld zu machen, heuert er durchreisende Abenteurer an, um ungewöhnliche Flora und Fauna aus dem gesamten Brachland und darüber hinaus zu sammeln. Sein berüchtigtstes Projekt besteht darin, aus Raptorhörnern ein kommerzielles, intelligenzsteigerndes Getränk zu brauen.",h="Mebok Mizzyrix ist ein geschäftstüchtiger Goblin-Unternehmer, der in der Hafenstadt Ratschet ansässig ist.",kw={"brachland","blaulaubknollen","mebok","mizzyrix","raptorhörner","ratschet","klugheitstränke","steamwheedle"},ang={["faction:Alliance"]="Wer das Schiff von Beutebucht ins neutrale Ratschet verlässt, erhält als Entdecker der Allianz Zugang zu Meboks Aufgaben, ohne feindselige Wachen fürchten zu müssen.",["faction:Horde"]="Bei der Durchreise durch Ratschet auf dem Weg durch das Brachland bietet sich Hordereisenden eine einfache Einnahmequelle durch die Beseitigung gefährlicher Bestien in der Nähe.",["profession:Cooking"]="Kulinarisch interessierte Abenteurer dürften Meboks Essens- und Getränkerezepturen bestenfalls fragwürdig finden, angesichts seines Beharrens darauf, gemahlenes Raptorhorn zu brauen.",["profession:Herbalism"]="Meboks Faszination für sonderbare Exemplare wie Blaulaubknollen veranschaulicht die wildere, kommerzielle Seite beim Sammeln der einzigartigen Flora Kalimdors."},sec={{t="Ein geschäftstüchtiger Alchemist",b="Von der geschäftigen, neutralen Hafenstadt Ratschet aus agierend, verkörpert Mebok Mizzyrix den klassischen Geist des rastlosen Opportunismus des Steamwheedle-Kartells. Während Ratschet Seefahrer, Piraten und Händler jeder Couleur bedient, richtet Mebok seinen scharfen Blick auf die Wildnis Kalimdors. Statt gewöhnliches Erz abzubauen oder alltägliche Stoffe zu handeln, sucht er nach seltenen biologischen Kuriositäten, von denen er glaubt, dass sie sich zu äußerst lukrativen Gebräuen und Handelsgütern verarbeiten lassen."},{t="Das Streben nach Klugheitstränken",b="Meboks wichtigstes kommerzielles Vorhaben ist ein firmeneigener 'Klugheitstrank', der den Intellekt jedes Konsumenten künstlich steigern soll. Überzeugt davon, dass die natürliche List und Wildheit der einheimischen Raptoren von den Hörnern herrührt, die ihre Schnauzen krönen, beauftragt Mebok Jäger damit, im gesamten Brachland intakte Hörner zu erbeuten. Für ihn stehen Ethik und Geschmack hinter dem reinen Marktpotenzial zurück – solange zahlende Kunden glauben, dass das Gebräu Wirkung zeigt."},{t="Exotische Reagenzien und Flora",b="Neben Elixieren aus Raptorenteilen besteht bei Mebok eine ständige Nachfrage nach weiteren bizarren Exemplaren. Von der Beschaffung flüchtiger Eier der Kluftmoosspinnen bis hin zum Auftrag, seltene, tief im Dornengestrüpp vom Kral der Klingenhauer vergrabene Blaulaubknollen zu bergen, führen seine Unternehmungen unerschrockene Söldner immer wieder in gefährliche Gefilde. Wenn ein Organismus seltsame Eigenschaften besitzt, ist sich Mebok sicher, dass es einen Weg gibt, ihn in Flaschen abzufüllen und zu verkaufen."}},faq={{q="Wer ist Mebok Mizzyrix?",a="Mebok Mizzyrix ist ein Goblinhändler und alchemistischer Ränkeschmied in der neutralen Hafenstadt Ratschet im Brachland. Er heuert Abenteurer an, um seltsame Wildtiere und Pflanzenteile zu beschaffen, um seine kommerziellen Projekte voranzutreiben.",al={"wer ist mebok","mebok mizzyrix lore","ratschet goblin mebok"}},{q="Was sind Klugheitstränke?",a="Klugheitstränke sind experimentelle, intelligenzsteigernde Stärkungsmittel, die Mebok Mizzyrix brauen und verkaufen möchte. Er glaubt, dass das Zermahlen der Hörner kluger Raptoren aus dem Brachland deren scharfe Instinkte und List auf den Trinker überträgt.",al={"klugheitstrank","klugheitstränke quest","raptorhorn trank"}},{q="Wo ist Mebok Mizzyrix zu finden?",a="Er steht zwischen den Gebäuden in der Hafenstadt Ratschet an der Ostküste des Brachlands und ist sowohl für Reisende der Horde als auch der Allianz zugänglich.",al={"mebok standort","wo ist mebok","mebok mizzyrix finden"}},{q="Warum will Mebok Raptorhörner haben?",a="Mebok stellt die Hypothese auf, dass die schlaue Intelligenz der im Brachland umherstreifenden Raptoren in ihren Hörnern konzentriert ist. Er plant, sie zu pulverisieren und als primären Wirkstoff in seinen intelligenzsteigernden Getränken einzusetzen.",al={"warum raptorhörner","raptorhorn zweck","was macht mebok mit hörnern"}},{q="Warum schickt Mebok Leute in den Kral der Klingenhauer?",a="Er wirbt Abenteurer an, um in den Kral der Klingenhauer vorzudringen und mithilfe eines ausgebildeten Schnüfflers Blaulaubknollen auszugraben, da er die seltene Pflanze wegen ihrer wertvollen und ungewöhnlichen botanischen Eigenschaften begehrt.",al={"warum der kral von razorfen","mebok kral quest","blaulaubknollen kral"}},{q="Arbeitet Mebok für die Horde oder die Allianz?",a="Mebok ist ein unabhängiges Mitglied des Steamwheedle-Kartells im neutralen Ratschet. Er ist allein dem Profit verpflichtet und handelt sowie verhandelt gerne mit Mitgliedern beider Fraktionen.",al={"ist mebok horde","ist mebok allianz","mebok fraktion"}}},fx={["55f078f0"]={q="Was möchte Mebok Mizzyrix?",a="Mebok ist davon angetrieben, seltsame neue alchemistische Kreationen zu brauen – vor allem sein experimentelles \"schlaues Getränk\". Um seine bizarren Rezepte zu perfektionieren, schickt er Abenteurer auf die Suche nach eigenartigen Zutaten durch das Brachland und seine gefährlichen Tiefen, von intakten Raptor Horns bis hin zu seltenen Wurzelproben und Spinneneiern.",al={"mebok möchte","was braucht mebok","mebok mizzyrix ziel"}},c521482b={q="Warum ist Mebok Mizzyrix in Ratschet?",a="Ratschet ist die wichtigste Hafenstadt für ehrgeizige Goblins, die schnellen Zugang zu den wilden Ressourcen von Kalimdor benötigen. Von seiner Basis aus kann Mebok leicht ankommende Söldner beider Fraktionen anheuern, um sich in die gefährliche Savanne zu wagen und die wilden Exemplare zu ernten, die er für seine Experimente benötigt.",al={"warum ist mebok hier","mebok ratschet grund","mebok mizzyrix brachland"}}},fp="14,360,25.445.0,26.443.0,25.422.0,22.219.0,22.218.0,34.159.0,33.217.0,45.176.0,46.165.0"}
P.entries["npc:melithar-staghelm"] = {fx={de95e555={q="Auf wessen Seite steht Melithar Hirschhaupt?",a="Melithar steht an der Seite der Nachtelfen von Darnassus und der Allianz. Stationiert im Laubschattental direkt vor Aldrassil, unterstützt er junge Nachtelfen-Verteidiger und Rekruten bei ihren ersten Schritten, um den Weltenbaum zu beschützen.",al={"melithar fraktion","wem dient melithar","melithar loyalität"}},f95cde78={q="Warum ist Melithar Hirschhaupt hier?",a="Melithar ist direkt außerhalb von Aldrassil im Laubschattental stationiert, um über den Ast zu wachen und angehende Nachtelfen-Abenteurer anzuleiten. Er bietet erste Führung und beauftragt neue Verteidiger damit, die örtliche Verderbnis einzudämmen und die Harmonie in Teldrassils heiliger Gärtnerei zu bewahren.",al={"warum ist melithar im laubschattental","melithar standortgrund"}}}}
P.entries["npc:melor-stonehoof"] = {fx={c4d46d44={q="Wer ist Melor Steinhuf?",a="Melor Steinhuf ist ein angesehener Tauren-Jäger, der auf der Anhöhe der Jäger in Donnerfels stationiert ist. Er widmet sich den Traditionen der Jagd und der Bewahrung des Gleichgewichts und leitet vielversprechende Spurensucher durch ganz Kalimdor, wobei er ihre Stärke und Gerissenheit gegen die wildesten Raubtiere des Landes auf die Probe stellt.",al={"wer ist melor steinhuf","melor steinhuf hintergrundgeschichte","wer ist melor"}},d59647ad={q="Auf wessen Seite steht Melor Steinhuf?",a="Melor ist den Tauren-Stämmen und der Horde treu. Von seinem Platz hoch oben in Donnerfels dient er seinem Volk, indem er Jäger der Horde betreut und Maßnahmen gegen gefährliche Bestien koordiniert, die Reisende und Siedlungen im Brachland und darüber hinaus bedrohen.",al={"melor steinhuf fraktion","ist melor horde","melor steinhuf loyalität"}},["2962cc83"]={q="Was möchte Melor Steinhuf?",a="Melor versucht, Jäger in den alten Wegen des Anschleichens, Spurenlesens und des Ehren ihrer Beute zu unterweisen. Er möchte, dass sich geschickte Spurensucher beweisen, indem sie berüchtigte Bestien wie Steelsnap, Deadmire und Frostmaw jagen, und er arbeitet mit Verbündeten wie Sergra Darkthorn zusammen, um ihren Mut auf die Probe zu stellen.",al={"melor steinhuf ziel","was möchte melor","melor steinhuf zweck"}},["6e964c49"]={q="Warum ist Melor Steinhuf hier in Donnerfels?",a="Melor hat sein Zuhause auf der Anhöhe der Jäger, dem natürlichen Versammlungsort für die Scharfschützen, Fallensteller und Spurensucher der Tauren. Von diesem Aussichtspunkt aus kann er ankommende Jäger beobachten, Rat anbieten und erprobte Krieger in die Wildnis entsenden, um das Land zu beschützen.",al={"warum ist melor auf der anhöhe der jäger","warum ist melor in donnerfels","melor steinhuf standortzweck"}}}}
P.entries["npc:menara-voidrender"] = {n="Menara Leerbringer",s="Menara Leerbringer ist eine menschliche Hexenmeisterin, die in der Goblin-Hafenstadt Ratschet lebt. Sie fungiert als Mentorin für ehrgeizige Ausübende der dunklen Künste sowohl der Allianz als auch der Horde und teilt ihr tiefes Wissen über dämonenbindende Artefakte und arkanes Handwerk. Ihre abgelegene Position auf Kalimdor hält sie fern von den wachsamen Augen orthodoxer Autoritäten.",h="Menara Leerbringer ist eine menschliche Hexenmeisterin, die in der Goblin-Hafenstadt Ratschet lebt.",kw={"brachland","blutrobe","dämonologie","menara","orahil","ratschet","tabetha","voidrender","hexenmeister"},ang={["class:Warlock"]="Menara ist eine wichtige Mentorin auf Kalimdor, die Praktizierende beider Fraktionen lehrt, wie sie ihre charakteristischen verzauberten Roben weben und Dämonen in Fokuskugeln binden.",["profession:Tailoring"]="Menara verbindet fortschrittliche Schneidereimaterialien mit Teufelsreagenzien, um haltbare, zauberumwobene Gewänder zu weben, die dämonische Macht kanalisieren können.",["race:Human"]="Weit entfernt von den Katakomben Sturmwinds repräsentiert Menara jene menschlichen Hexenmeister, die königstreue Loyalitäten ablegten, um dunklen Künsten ungehindert in neutralen Gebieten nachzugehen."},sec={{t="Eine Zuflucht in Ratschet",b="Während die meisten Hexenmeister in den Östlichen Königreichen in feuchten Kellern oder abgelegenen Schlachthöfen unter ihren Heimatstädten praktizieren, wählte Menara Leerbringer den neutralen Goblinhafen Ratschet im Brachland. Weit entfernt von der Aufsicht der Kirin Tor, der Wachen von Sturmwind oder den Aufsehern von Orgrimmar steht es ihr frei, ihren okkulten Studien offen nachzugehen. Ihre Bereitschaft, mit jedem fähigen Lehrling unabhängig von der Fraktionszugehörigkeit zu verhandeln, macht sie zu einem seltenen Berührungspunkt unter den Praktizierenden der dunklen Künste."},{t="Meisterin der Bindung",b="Menara ist unter erfahrenen Beschwörern als Koryphäe für die Erschaffung von Kugeln bekannt, die dämonische Geister einsperren und nutzbar machen. Sie arbeitet eng mit komplexen Reagenzien und leitet Lehrlinge durch anspruchsvolle Rituale, um verzauberte Gewänder und Bindungswerkzeuge zu schmieden. Die Kunde von ihrer Expertise reicht bis nach Eisenschmiede und Unterstadt, was hochrangige Hexenmeister in ganz Azeroth dazu veranlasst, ihre vielversprechendsten Schüler über das Meer zu schicken, um ihren Rat zu suchen."},{t="Bande zu den Marschen",b="Zu Menaras entfernten Bekannten gehört die Einsiedlermagierin Tabetha, die in tiefer Isolation in den Sümpfen der Düstermarschen lebt. Obwohl Tabetha dem Arkanen nachgeht und Menara sich in Teufelsbindungen und Dämonologie vertieft, teilen die beiden Frauen eine lange Vorgeschichte. Wenn mächtige Relikte wie der Orb of Orahil Wiederherstellung oder Fachwissen erfordern, wird ihre gemeinsame Vergangenheit zu einer unerwarteten Brücke über die Wildnis Kalimdors."}},faq={{q="Wer ist Menara Leerbringer?",a="Menara Leerbringer ist eine menschliche Hexenmeisterin, die in der neutralen Hafenstadt Ratschet im Brachland stationiert ist. Sie dient als Ausbilderin und Arkanhandwerkerin für heranwachsende Hexenmeister und leitet sie durch Herstellungsrituale und dämonenbindende Zauberei.",al={"wer ist menara","menara leerbringer lore","wer ist der hexenmeister in ratschet"}},{q="Warum lebt eine menschliche Hexenmeisterin im Brachland?",a="Ratschet bietet Neutralität und Distanz zu den wachsamen Augen großer Regierungen. Indem sie sich in einem von Goblins geführten Hafen niederlässt, kann Menara verbotene Künste ausüben und Schüler sowohl der Allianz als auch der Horde unterrichten, ohne dass Paladine, Magier oder Stadtwachen eingreifen.",al={"warum ist menara in ratschet","warum ist sie im brachland","warum ratschet hexenmeister"}},{q="Auf welche Art von Magie ist Menara spezialisiert?",a="Menara ist auf Dämonologie spezialisiert, auf das Verzaubern dunkler Stoffe und auf das Formen von Gefäßen, die zum Fangen dämonischer Wesenheiten bestimmt sind. Sie ist besonders für ihre Meisterschaft bei der Erschaffung und Wiederherstellung von Kugeln bekannt, die Dämonen binden, wie etwa der Orb of Orahil.",al={"was lehrt menara","menara leerbringer kräfte","worin ist menara gut"}},{q="Was ist Menaras Verbindung zu Tabetha?",a="Menara und die zurückgezogen lebende Zauberin Tabetha teilen eine gemeinsame Vergangenheit. Obwohl Tabetha abgeschieden in den Düstermarschen lebt und traditionelle Zauberei praktiziert, stellen Hexenmeister auf der Suche nach Wissen über den Orb of Orahil fest, dass die beiden Frauen mit den Talenten der jeweils anderen vertraut sind.",al={"menara und tabetha","woher kennt sie tabetha","tabetha verbindung"}},{q="Bevorzugt Menara die Allianz oder die Horde?",a="Menara agiert neutral von Ratschet aus. Sie bietet ihre Unterweisung und Handwerksaufgaben jedem Hexenmeister an, der sich als fähig und ehrgeizig genug erweist, um mit Teufelsenergien umzugehen, und heißt sowohl Praktizierende der Allianz als auch der Horde willkommen.",al={"ist menara allianz oder horde","menara fraktion","für wen arbeitet menara"}},{q="Welche bedeutenden Artefakte hilft sie zu erschaffen?",a="Menara leitet Lehrlinge beim Weben der Verzauberten Goldblutrobe an, einem Gewand voller dämonischer Macht, und unterstützt fortgeschrittene Praktizierende bei der Bergung und dem Zusammenbau von Komponenten für den Orb of Orahil.",al={"menara quests","was stellt sie her","verzauberte goldblutrobe menara"}}},fx={["63c53201"]={q="Was möchte Menara Leerbringer?",a="Menara möchte angehende Hexenmeister unterrichten, die genug Potenzial und Ehrgeiz zeigen, um sie aufzusuchen. Sie widmet sich der Herstellung und Perfektionierung spezialisierter dunkler Artefakte, wie Bindungskugeln und verzauberte Roben, und verlässt sich auf fähige Praktizierende, um die seltenen, gefährlichen Reagenzien zu sammeln, die benötigt werden, um sie zu vervollständigen.",al={"menara leerbringer ziele","was möchte menara","menara leerbringer zweck"}}},fp="17,347,19.503.0,19.441.0,17.416.1,25.230.0,45.276.0,45.232.0,39.275.0,44.214.0,42.202.0"}
P.entries["npc:merissa-stilwell"] = {n="Merissa Stillbrunn",s="Merissa Stillbrunn ist eine junge menschliche Bürgerin, die in der Abtei von Nordhain im Wald von Elwynn wohnt. Nahe der Abtei stehend, bietet sie den Neulingen, die im Nordhaintal trainieren, eine fröhliche Begrüßung und eine helfende Hand.",h="Merissa Stillbrunn ist eine junge menschliche Bürgerin, die in der Abtei von Nordhain im Wald von Elwynn...",kw={"elwynn","merissa","nordhain","stilwell"},ang={["faction:Alliance"]="Für Rekruten der Allianz, die das behütete Kloster von Nordhain verlassen, verkörpert Merissa die herzliche Gastfreundschaft von Elwynn, bevor die harten Realitäten der Bedrohung durch die Defias einsetzen."},sec={{t="Ein einladendes Gesicht in Nordhain",b="An der Abtei von Nordhain stehend, begrüßt Merissa Stillbrunn die neuen Rekruten, die im Nordhaintal eintreffen. Den umherstreifenden Neulingen bietet sie einfache Gastfreundschaft und praktische Ratschläge zum Ausruhen und zur Orientierung. Sie teilt ihren Nachnamen mit bemerkenswerten Handwerkern und Siedlern im ganzen Königreich – wie etwa dem Schmied Jordan Stillbrunn und der Verteidigerin Daphne Stillbrunn aus Westfall –, bleibt jedoch inmitten der wachsenden Spannungen des Königreichs ein friedliches Gesicht vor Ort."}},faq={{q="Wer ist Merissa Stillbrunn?",a="Merissa ist eine freundliche menschliche Bewohnerin der Abtei von Nordhain im Wald von Elwynn, die den dort ankommenden Reisenden Ratschläge und ein herzliches Willkommen bietet.",al={"merissa stillbrunn","wer ist merissa","stilwell mädchen nordhain"}},{q="Wo finde ich Merissa Stillbrunn?",a="Sie befindet sich bei der Abtei von Nordhain im Nordhaintal, im Wald von Elwynn.",al={"merissa stillbrunn aufenthaltsort","wo ist merissa","merissa finden"}},{q="Ist Merissa mit den anderen Stilwells im Königreich verwandt?",a="Obwohl sie ihren Nachnamen mit prominenten Persönlichkeiten wie dem Schmied Jordan Stillbrunn und Daphne Stillbrunn in Westfall teilt, lebt sie ruhig in der Abtei von Nordhain und heißt Reisende willkommen, anstatt gegen Banditen zu kämpfen oder Klingen zu schmieden.",al={"familie stilwell","daphne stillbrunn verwandte","jordan stillbrunn verwandter"}},{q="Bietet Merissa Stillbrunn irgendwelche Quests an?",a="Nein. Sie hat keine eigene Aufgabe für Reisende; sie begrüßt lediglich die Neulinge, die durch Nordhain ziehen.",al={"merissa quests","merissa stillbrunn quest"}}},fx={a071eba0={q="Auf wessen Seite steht Merissa Stillbrunn?",a="Merissa Stillbrunn ist eine loyale Untertanin der Großen Allianz und des Königreichs Sturmwind. Sie lebt friedlich in der Abtei von Nordhain und heißt die Reisenden und Rekruten willkommen, die im Tal ankommen.",al={"merissa stillbrunn fraktion","ist merissa stillbrunn allianz"}},["57a6fac4"]={q="Warum ist Merissa Stillbrunn in Nordhain?",a="Merissa verbringt ihre Tage rund um die Abtei von Nordhain. Wie viele einfache Leute des Königreichs lebt sie im Wald von Elwynn und heißt die Neuankömmlinge willkommen, die im Tal eintreffen.",al={"warum ist merissa stillbrunn hier","was macht merissa in nordhain"}}},fp="16,219,30.449.0,24.144.0,34.74.0,57.222.0,39.106.0"}
P.entries["npc:merrin-rockweaver"] = {n="Merrin Felsweber",s="Merrin Felsweber ist eine Zwergenforscherin, die die Forscherliga im Sumpfland vertritt. Nach einem heftigen Raptorenbefall, der Whelgars Ausgrabungsstätte überrannte, flüchtete sie an der Seite von Ausgrabungsleiter Whelgar auf einen Felsvorsprung mit Blick auf die Stätte.",h="Merrin Felsweber ist eine Zwergenforscherin, die die Forscherliga im Sumpfland vertritt.",kw={"forscherliga","merrin felsweber","raptoren","herumwerkeln","sumpfland","whelgars ausgrabungsstätte","whelgars zuflucht"},ang={["faction:Alliance"]="Merrin verkörpert die akademische Präsenz von Eisenschmiede im Sumpfland, und die Sicherung ihrer Forschungen trägt dazu bei, den unsicheren Stützpunkt der Allianz in den wilden Marschen aufrechtzuerhalten.",["race:Dwarf"]="Für zwergische Abenteurer ist die Unterstützung von Merrin eine Frage des nationalen Erbes, um die kostbaren Titanenrelikte und historischen Aufzeichnungen zu schützen, für deren Freilegung die Forscherliga ihr Leben aufs Spiel setzte."},sec={{t="Vertrieben von der Ausgrabung",b="Merrin Felsweber reiste im Auftrag der Forscherliga von Eisenschmiede ins Sumpfland, um uralte Geheimnisse der Titanen zu lüften, die unter dem Morast begraben lagen. Die Expedition endete in einer Katastrophe, als die großen Knochen, die sie freigelegt hatten, Raptoren zur Ausgrabung lockten. Bösartige prähistorische Bestien schwärmten durch die Gräben und zwangen Merrin und die überlebende Mannschaft, ihre Ausrüstung, Notizen und Fortschritte zurückzulassen. Sie sitzt nun mit den wenigen Überlebenden auf einer Klippe über den überrannten Ruinen fest."},{t="Rettung des Unternehmens",b="Auf der Klippe gefangen weigern sich die Überlebenden, die Expedition zu einem völligen Fehlschlag werden zu lassen. Während Ormer Eisenzopf auf Rache an den Bestien sinnt und Ausgrabungsleiter Whelgar nach den in den raptorenverseuchten Gräben zurückgelassenen Tafelfragmenten sucht, wandern Merrins Gedanken zu ihrem Ehemann Tarrel, der seit Wochen nichts von ihr gehört hat. Sie verlässt sich auf den Späher, den Longbraid ausgesandt hat, um das Team zu finden, damit er die Kunde von ihrer misslichen Lage zu ihm bringt."}},faq={{q="Wer ist Merrin Felsweber?",a="Merrin Felsweber ist eine Zwergenarchäologin, die der Forscherliga von Eisenschmiede angehört. Sie war an Whelgars Ausgrabungsstätte im Sumpfland stationiert, bevor Raptoren das Unternehmen überrannten.",al={"merrin felsweber lore","wer ist merrin","sumpfland zwerg merrin"}},{q="Warum sitzt sie oberhalb der Ausgrabungsstätte fest?",a="Buntflügelraptoren, angelockt von den großen Knochen, die das Team freigelegt hatte, überrannten die Ausgrabungsstätte unten, und viele Leben gingen verloren. Ormer Eisenzopf verteidigte Merrin und Ausgrabungsleiter Whelgar bei ihrer Flucht auf die nahegelegene Klippe, wo sie noch immer festsitzen.",al={"warum ist merrin am zufluchtsort","whelgars zuflucht merrin","was geschah mit ihrem lager"}},{q="Wobei benötigt Merrin Hilfe?",a="Merrin braucht jemanden, der einen Brief, in dem die Katastrophe geschildert wird, zu ihrem Ehemann Tarrel bringt, der sich vor Sorge verzehrt, seit keine Briefe mehr von ihr eintreffen.",al={"merrin quests","merrin felsweber aufgaben","herumwerkeln lore"}},{q="Was versuchte die Expedition zu finden?",a="Wie die meisten Unterfangen der Forscherliga sollte die Ausgrabung im Sumpfland uralte Artefakte im Zusammenhang mit der Abstammung der Zwerge und den geheimnisvollen Titanenrelikten ans Licht bringen, die überall in Khaz Modan verborgen liegen.",al={"wonach graben sie","zweck der ausgrabungsstätte"}}},fx={["86a5e24a"]={q="Auf wessen Seite steht Merrin Felsweber?",a="Merrin Felsweber ist fest den Zwergen von Eisenschmiede und der Allianz verbunden. Als aktive Landvermesserin und Mitglied der Forscherliga liegen ihre Loyalitäten bei den Gelehrten und Ausgräbern, die von Eisenschmiede ausgesandt wurden, um die uralten Ursprünge ihres Volkes in ganz Khaz Modan aufzudecken.",al={"merrin felsweber fraktion","merrin felsweber loyalität","wem dient merrin"}},f33c6ea8={q="Mit wem ist Merrin Felsweber verbunden?",a="Merrin begleitet die Expedition von Ausgrabungsleiter Whelgar an der Ausgrabungsstätte im Sumpfland. Ormer Eisenzopf hilft, ihr Lager gegen die es umzingelnden Raptoren zu verteidigen.",al={"merrin felsweber verbindungen","merrin felsweber verbündete","mit wem arbeitet merrin"}}},fp="17,250,20.459.0,23.426.0,25.195.0,38.234.0,32.152.0,39.192.0"}
P.entries["npc:miles-welsh"] = {fx={["9239b409"]={q="Was möchte Miles Welsch?",a="Miles Welsch dient als Ausbilder für andere Priester, die Donnerfels besuchen. Unten in den abgelegenen Teichen der Visionen teilt er seine Disziplin und dunklen Künste mit all jenen, die den Pfad der Schatten und des Glaubens beschreiten, und stellt sicher, dass die Jünger der Horde selbst weit weg von Lordaeron Führung erhalten.",al={"was tut miles welsch","miles welsch absicht","miles welsch ziele"}},["03472250"]={q="Wem ist Miles Welsch verbunden?",a="Miles Welsch ist den Verlassenen der Unterstadt verbunden. Seine Anwesenheit in Donnerfels bringt ihn an die Seite der Abgesandten und Reisenden der Verlassenen, die durch den jungen Pakt zwischen Cairne Bluthufs Volk und den Anhängern von Fürstin Sylvanas Windläufer in der Hauptstadt der Tauren willkommen sind.",al={"miles welsch verbündete","für wen arbeitet miles welsch","miles welsch verbindungen"}},c3aae6f3={q="Auf wessen Seite steht Miles Welsch?",a="Miles Welsch steht an der Seite der Verlassenen und der größeren Horde. Obwohl die Tauren einem völlig anderen spirituellen Pfad folgen, der in der Erdenmutter verwurzelt ist, residiert Miles unterhalb ihres Plateaus bei ihren Verbündeten, um Horde-Reisenden, die es suchen, sein Wissen über das Priestertum anzubieten.",al={"miles welsch fraktion","miles welsch horde oder allianz","wem dient miles welsch"}}}}
P.entries["npc:milli-featherwhistle"] = {n="Milli Federpfiff",s="Milli Federpfiff ist eine meisterhafte Mechanoschreiter-Ingenieurin der Gnom, die in Stahlrosts Depot in Dun Morogh stationiert ist. Nach dem Fall von Gnomeregan fertigt und wartet sie akribisch die von ihrem Volk bevorzugten Uhrwerk-Reittiere von Hand. Sie verkauft ihre geschätzten mechanischen Schöpfungen an Mitgnome und vertrauenswürdige Verbündete der exilierten Überlebenden von Gnomeregan.",h="Milli Federpfiff ist eine meisterhafte Mechanoschreiter-Ingenieurin der Gnom, die in Stahlrosts Depot in Dun...",kw={"dun morogh","gnomeregan","kharanos","mechanoschreiter","mekkatorque","milli federpfiff","reittierhändler","stahlrosts depot"},ang={["faction:Alliance"]="Helden der Allianz, die sich den größten Respekt der Gnomeregangnome verdienen, können Milli aufsuchen, um eines der schnellsten mechanischen Reittiere auf Azeroth zu führen.",["profession:Engineering"]="Millis Mechanoschreiter stellen den Höhepunkt der großformatigen gnomischen Fortbewegung dar und kombinieren gyroskopische Ausgleichseinheiten mit drehmomentstarken mechanischen Gliedmaßen.",["race:Gnome"]="Milli Federpfiff ist die führende Reittieringenieurin Eures Volkes, die das technologische Genie von Hochtüftler Mekkatorque auch im Exil fern Eurer unterirdischen Heimat weiterträgt."},sec={{t="Meisterin der Mechanoschreiter",b="Unter freiem Himmel in der klirrenden Kälte von Stahlrosts Depot östlich von Kharanos überwacht Milli Federpfiff den Nachschub an Uhrwerk-Rössern für die vertriebene Bevölkerung von Gnomeregan. Im Gegensatz zu den biologischen Bestien, die von Zwergen und Nachtelfen bevorzugt werden, baut Milli ihr gesamtes Sortiment selbst und kalibriert Zahnräder, Kolben und Ausgleichskreisel eigenhändig, um sicherzustellen, dass jeder mechanische Vogel mit maximaler Effizienz über die verschneiten Klippen von Dun Morogh rennt."},{t="Das Erbe von Mekkatorque",b="Jeder Rahmen und jede Feder in Millis Werkstatt geht auf Blaupausen zurück, die ursprünglich von Hochtüftler Gelbin Mekkadrill entworfen wurden. Obwohl Milli im Laufe der Jahre moderne Leistungsverbesserungen integriert hat – etwa durch das Optimieren von Fahrgestellgewichten und das Verfeinern von Auspufföffnungen –, hält sie sich treu an die grundlegenden Schaltpläne des Hochtüftlers. Ihre mechanischen Wunderwerke beweisen, dass der technologische Ehrgeiz der Gnom selbst im Exil völlig ungebrochen bleibt."}},faq={{q="Wer ist Milli Federpfiff?",a="Milli Federpfiff ist die oberste Mechanoschreiter-Züchterin und Ingenieurin für die Gnom von Gnomeregan. In Stahlrosts Depot in Dun Morogh stationiert, baut sie Uhrwerk-Mechanoschreiter von Hand und verkauft sie an berechtigte Reiter.",al={"milli federpfiff","wer ist milli","mechanoschreiterhändler"}},{q="Wo kann ich Milli Federpfiff finden?",a="Sie befindet sich in Stahlrosts Depot, einem Ingenieursaußenposten, der nur einen kurzen Fußmarsch östlich der Straße von der Stadt Kharanos in Dun Morogh entfernt liegt.",al={"milli standort","wo ist milli federpfiff","milli finden"}},{q="Wer darf Reittiere von ihr kaufen?",a="Standardmäßig verfügen nur gnomische Abenteurer über die unmittelbare Freigabe und Eignung, ihre Schöpfungen zu erwerben. Mitglieder anderer Völker der Allianz müssen sich erst das größte Vertrauen und einen ehrfürchtigen Ruf bei den Gnomeregangnomen verdienen, bevor sie ihnen einen Mechanoschreiter anvertraut.",al={"kann ich einen mechanoschreiter kaufen","mechanoschreiter voraussetzungen","wer kann mechanoschreiter reiten"}},{q="Wie werden Mechanoschreiter hergestellt?",a="Milli Federpfiff fertigt jeden Mechanoschreiter selbst an, wobei sie ihre Konstruktionen auf die ikonischen Blaupausen von Hochtüftler Gelbin Mekkadrill stützt und dabei eigene Verbesserungen an Motor und Balance vornimmt.",al={"wie mechanoschreiter gebaut werden","wer stellt mechanoschreiter her","mechanoschreiter ursprung"}},{q="Welche Reittier-Varianten bietet sie an?",a="Sie bietet verschiedene kalibrierte Modelle an, von standardmäßigen unlackierten, blauen, grünen und roten Gestellen bis hin zu fein abgestimmten schnellen Varianten mit weißer, grüner und gelber Lackierung.",al={"milli reittierfarben","mechanoschreiter modelle","welche reittiere verkauft milli"}},{q="Warum arbeitet sie draußen im Schnee bei Stahlrosts Depot?",a="Nachdem die radioaktive Katastrophe und die Trogg-Invasion die Gnom aus Gnomeregan vertrieben hatten, sammelten sich die Flüchtlinge, wo immer sie konnten. Stahlrosts Depot dient außerhalb von Kharanos als natürlicher Stützpunkt für Fahrzeugtests und mechanische Wartung an der Seite von Zwergeningenieuren.",al={"warum ist milli in dun morogh","warum steelgrills depot"}}},fx={["2267a2b3"]={q="Auf wessen Seite steht Milli Federpfiff?",a="Milli Federpfiff ist Gnomeregan und der Großen Allianz ergeben. Sie arbeitet in Stahlrosts Depot zusammen mit Zwergenhandwerkern und stellt mechanische Schreiter direkt für ihre Mitgnome und vertrauenswürdige Champions der Allianz bereit, die sich den vollen Respekt der Gnomeregangnome verdient haben.",al={"fraktion milli federpfiff","wem dient milli federpfiff","ist milli bei der allianz"}},f07f7c95={q="Was möchte Milli Federpfiff?",a="Milli möchte die besten mechanischen Schreiter in Dun Morogh bauen und warten. Basierend auf den ursprünglichen Bauplänen von Tüftlerobermeister Mekkatorque verfeinert sie deren Technik kontinuierlich, damit zuverlässige mechanische Reittiere für reisende Gnome und bewährte Verbündete stets verfügbar sind.",al={"was macht milli federpfiff","ziel von milli federpfiff","was versucht milli zu tun"}}},fp="20,342,25.441.0,21.432.0,28.220.0,38.147.0,43.262.0,29.206.0,36.178.0,57.271.0"}
P.entries["npc:milton-sheaf"] = {n="Milton Garbenbund",s="Milton Garbenbund ist der leitende Bibliothekar der Royal Library in Burg Sturmwind. Er widmet sich der Bewahrung der Geschichte des Königreichs und beaufsichtigt die Sammlung alter Wälzer und historischer Chroniken des Reiches. Häufig heuert er Reisende der Allianz an, um verloren gegangene Bände zu bergen, verstreute Aufzeichnungen aufzuspüren und vernachlässigte Manuskripte zu restaurieren.",h="Milton Garbenbund ist der leitende Bibliothekar der Royal Library in Burg Sturmwind.",kw={"bücher","geschichte","bibliothekar","milton garbenbund","royal library","burg sturmwind","wälzer"},ang={["faction:Alliance"]="Als führender Bibliothekar des Königreichs trägt Milton Garbenbund dazu bei, das niedergeschriebene Erbe der Menschenkönigreiche und der gesamten Allianz zu bewahren.",["race:Human"]="Milton hütet Jahrhunderte menschlicher Geschichte und schützt Chroniken, die den Fall und den Wiederaufbau von Sturmwind überstanden haben."},sec={{t="Der Hüter der Geschichte Sturmwinds",b="Zurückgezogen in den ruhigen Hallen der Royal Library in Burg Sturmwind pflegt Milton Garbenbund das kollektive Gedächtnis des Königreichs. Während der Hof oben von Politik, streitenden Adligen und militärischen Belangen beherrscht wird, konzentriert sich Sheaf auf die Bewahrung des geschriebenen Wortes. Er betrachtet die Pflege präziser Geschichtswerke über die Allianz und die Östlichen Königreiche als heilige Pflicht – besonders in einer Ära, die von Krieg, Verlust und Instabilität geprägt ist."},{t="Die Bergung verlorener Wälzer",b="Die Pflege der Bibliothekssammlung erfordert ständige Mühe. Bücher nutzen sich ab, und wertvolle Aufzeichnungen liegen oft verstreut im ganzen Reich in klösterlichen Archiven, fernen Außenposten oder vergessenen Ruinen. Milton entsendet regelmäßig Abenteurer durch das Land – von der Abtei von Nordhain bis zur fernen nördlichen Siedlung Süderstade –, um verlegte Bände zu beschaffen, alte Texte zu untersuchen und sicherzustellen, dass seltene Manuskripte unversehrt in die Regale der Feste zurückkehren."}},faq={{q="Wer ist Milton Garbenbund?",a="Milton Garbenbund ist ein menschlicher Gelehrter und der oberste Verwalter der Royal Library, die sich in Burg Sturmwind in Sturmwind befindet. Er verwaltet die Buchsammlungen und Chroniken des Königreichs.",al={"wer ist milton garbenbund","rolle von milton garbenbund","bibliothekar von sturmwind"}},{q="Wo kann ich Milton Garbenbund finden?",a="Ihr findet Milton Garbenbund im Flügel der Royal Library in Burg Sturmwind, gleich neben den Hauptkorridoren des Palastes.",al={"aufenthaltsort von milton garbenbund","wo ist milton garbenbund","standort der bibliothek von sturmwind"}},{q="Warum braucht Milton Garbenbund Abenteurer?",a="Milton verlässt sich oft auf reisende Abenteurer der Allianz, um historische Manuskripte aufzuspüren, beschädigte Bücher zu ersetzen und sich mit Gelehrten sowie Priestern im ganzen Königreich abzustimmen, um die Archive der Royal Library zu erweitern.",al={"quests von milton garbenbund","was will milton","warum quests vergeben"}},{q="Steht Milton Garbenbund mit anderen Gelehrten des Königreichs in Kontakt?",a="Ja. Er unterhält Verbindungen zu klösterlichen Archivaren und religiösen Gelehrten, darunter Bruder Paxton im Nordhaintal, um heilige Lehren und historische Aufzeichnungen zu bewahren.",al={"milton nordhain","milton bruder paxton","miltons verbindungen"}}},fx={["440d1fb9"]={q="Auf wessen Seite steht Milton Garbenbund?",a="Milton Garbenbund dient dem Königreich Sturmwind und der Allianz. Er ist direkt in Burg Sturmwind stationiert und arbeitet im Auftrag der königlichen Archive, wo er Geschichte katalogisiert und Wissen für die Gelehrten und die Führung des Königreichs bewahrt.",al={"fraktion milton garbenbund","wem dient milton garbenbund","milton garbenbund allianz"}},["1fad6188"]={q="Warum ist Milton Garbenbund hier in Burg Sturmwind?",a="Milton ist mit der Verwaltung und Instandhaltung der Royal Library betraut. Er kümmert sich um die riesige Sammlung an Schriftrollen, Folianten und historischen Aufzeichnungen des Königreichs und stellt sicher, dass wichtige Zeugnisse der Vergangenheit von Azeroth geschützt und dem Hof zugänglich bleiben.",al={"warum ist milton garbenbund in der royal library","absicht von milton garbenbund hier","warum ist milton in sturmwind"}}},fp="12,335,36.437.0,21.461.0,20.184.0,30.119.0,39.214.0,62.171.0"}
P.entries["npc:miner-johnson"] = {n="Minenarbeiter Johnson",s="Minenarbeiter Johnson ist ein schwer fassbarer, erfahrener Bergmann, der mit der Bruderschaft der Defias tief im Inneren der Todesminen verbündet ist. Dieser gefährliche Goldsucher, der zusammen mit gewöhnlichen Arbeitern in einer seitlichen Nische haust, beaufsichtigt die Ausgrabungsarbeiten vor den schweren Maschinen, die sich tiefer unter der Erde befinden. Da er unberechenbar durch die unterirdischen Tunnel streift, kreuzen Abenteurer seinen Weg nur gelegentlich.",h="Minenarbeiter Johnson ist ein schwer fassbarer, erfahrener Bergmann, der mit der Bruderschaft der Defias tief...",kw={"nische","die todesminen","defias","elite","minenarbeiter johnson","mondbruch","selten","schredder","westfall"},ang={["faction:Alliance"]="Das Erschlagen von Johnson unterbricht den stetigen Fluss an schmelzbarem Erz, das in die unter Mondbruch verborgene Kriegsmaschinerie der Defias fließt.",["profession:Mining"]="Für Schürfer verkörpert Johnson die raue, gesetzlose Seite der unterirdischen Arbeit und bewacht mit Blut und Spitzhacke reiche Mineralvorkommen tief unter Westfall."},sec={{t="Ein seltenes Gesicht in der Tiefe",b="Während Hunderte von Arbeitern an den unterirdischen Adern der Todesminen schuften, um Edwin van Cleefs verborgene Festung zu versorgen, sticht Minenarbeiter Johnson als ungewöhnlich furchterregende Gestalt unter ihnen hervor. Er lauert in einer schattigen Nische auf der linken Seite vor den schwerfälligen Schreddern des Mast Room und ist weitaus zäher und aggressiver als die reguläre Belegschaft. Seine unvorhersehbare Anwesenheit macht ihn zu einem legendären Ziel für Entdecker, welche die Tunnel der Defias durchqueren."},{t="Treibstoff für die Kriegsmaschinerie der Defias",b="Die geheime Operation der Bruderschaft der Defias unter Mondbruch benötigt gewaltige Mengen an Roherz, um Waffen zu schmieden, Schächte zu verstärken und mechanische Vorrichtungen zusammenzubauen. Bergleute wie Johnson liefern die Muskelkraft hinter dem Metall und schlagen auf die reichen Mineraladern unter Westfall ein. Jeder, der zufällig in Johnsons Arbeitsbereich stolpert, wird schnell feststellen, dass er seine Ausgrabungsstätte mit tödlichem Eifer verteidigt."}},faq={{q="Wer ist Minenarbeiter Johnson?",a="Minenarbeiter Johnson ist ein seltener Elite-Bergmann (Mensch), der mit der Bruderschaft der Defias verbündet ist. Er arbeitet tief in den Todesminen, untergebracht in einer seitlichen Nische mit anderen Arbeitern kurz vor dem Goblinsäbler.",al={"minenarbeiter johnson lore","wer ist minenarbeiter johnson","die todesminen minenarbeiter johnson"}},{q="Wo genau befindet sich Minenarbeiter Johnson?",a="Er ist in den oberen Schächten der Todesminen zu finden, bevor Ihr den Raum erreicht, in dem Sneed und sein Schredder untergebracht sind. Haltet Ausschau nach einer kleinen Ausgrabungsnische auf der linken Seite, in der eine Gruppe von Bergleuten aktiv den Fels bearbeitet.",al={"minenarbeiter johnson aufenthaltsort","wo ist minenarbeiter johnson","wie man minenarbeiter johnson findet"}},{q="Warum ist Minenarbeiter Johnson nicht immer da?",a="Minenarbeiter Johnson ist ein seltener Spawn, was bedeutet, dass er nur gelegentlich erscheint, wenn eine Expedition Die Todesminen betritt. Die meisten Gruppen, die durch die Minenschächte ziehen, werden stattdessen einen gewöhnlichen Bergmann an seiner Stelle vorfinden.",al={"minenarbeiter johnson spawnt nicht","ist minenarbeiter johnson selten","minenarbeiter johnson spawnrate"}},{q="Ist Minenarbeiter Johnson Teil einer Quest?",a="Minenarbeiter Johnson ist mit keinem formellen Quest-Kopfgeld verbunden. Er ist einfach eine günstige Gelegenheit für Dungeon-Gruppen, die das Glück haben, ihn beim Abbau der Ader anzutreffen.",al={"minenarbeiter johnson quest","hat minenarbeiter johnson eine quest"}},{q="Welche Rolle spielt Minenarbeiter Johnson in den Todesminen?",a="Er ist ein erfahrener Vorarbeiter oder Meistergräber, der der Bruderschaft der Defias hilft, wertvolles Metall, Gestein und Ressourcen abzubauen, die für den Bau ihrer gewaltigen unterirdischen Basis und des verborgenen Molochs notwendig sind.",al={"was macht minenarbeiter johnson","minenarbeiter johnson rolle"}},{q="Ist Minenarbeiter Johnson gefährlich im Vergleich zu anderen Bergleuten?",a="Ja. Während die Standardgräber in den Todesminen relativ schwach sind, ist Minenarbeiter Johnson ein Elite-Kämpfer mit deutlich mehr Lebenskraft und Schlagkraft, der eine koordinierte Gruppe erfordert, um ihn sicher zur Strecke zu bringen.",al={"wie schwer ist minenarbeiter johnson","ist minenarbeiter johnson elite"}}},fx={["3a6e6cc9"]={q="Auf wessen Seite steht Minenarbeiter Johnson?",a="Er steht auf der Seite der The Defias Brotherhood und ihrer Arbeiterschaft. Tief in den Todesminen schuftet Minenarbeiter Johnson zusammen mit den anderen Arbeitern und teilt ihre Loyalität zum Aufstand von Edwin van Cleef, wobei er seine Spitzhacke gegen jeden Eindringling einsetzt, der ihre unterirdische Festung durchbricht.",al={"fraktion minenarbeiter johnson","für wen arbeitet minenarbeiter johnson","ist minenarbeiter johnson defias"}}},fp="13,379,23.446.0,30.398.0,21.192.0,39.225.0,37.202.0,35.170.0,46.198.0,52.221.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="Schwache Erdmanifestation",s="Eine Schwache Erdmanifestation ist ein örtlich gebundener Elementargeist, der an heilige Steine in Mulgore und Durotar gebunden ist. Für das gewöhnliche Auge unsichtbar, offenbart er sich nur angehenden Schamanen, die das heilige Erdsapta trinken, und liefert den Rohquarz, der zum Schnitzen ihres allerersten Erdtotems benötigt wird.",h="Eine Schwache Erdmanifestation ist ein örtlich gebundener Elementargeist, der an heilige Steine in Mulgore...",kw={"ruf der erde","erdsapta","erdtotem","kodofels","schwache erdmanifestation","rohquarz","geisterfelsen"},ang={["class:Shaman"]="Jeder junge Schamane der Horde muss unter dem Einfluss des Erdsaptas mit einer Schwachen Erdmanifestation Zwiesprache halten, um sich sein allererstes Totem zu verdienen.",["race:Tauren"]="Die Jugend der Tauren reist ostwärts durch Mulgore zum Kodofelsen, um im Rahmen ihrer uralten spirituellen Prüfungen Zwiesprache mit dieser Manifestation zu suchen."},sec={{t="Stimme des Steins",b="Die Geister der Erde verweilen überall unter Schmutz und Stein, doch die Kommunikation mit ihnen erfordert ein bewusstes Ritual. An heiligen Wahrzeichen wie dem Kodofelsen in Mulgore und dem Geisterfelsen in Durotar verweilen Schwache Erdmanifestationen im Reich des Verborgenen, umgeben von noch kleineren Elementarpräsenzen. Nur Initianden, die das Erdsapta getrunken haben – einen rituellen Trunk, der von schamanischen Mentoren gebraut wird –, können den Schleier zwischen der physischen Welt und den Elementen lüften. Sobald der Geist anerkannt wird, gewährt er die Segnungen der Erde zusammen mit einem Stück Rohquarz und verleiht dem Neuling damit den spirituellen Fokus, der zum Anfertigen eines Erdtotems nötig ist."}},faq={{q="Warum kann ich die Schwache Erdmanifestation nicht sehen?",a="Die Manifestation existiert auf der Elementarebene und bleibt für das bloße Auge unsichtbar. Ihr müsst ein Erdsapta trinken, das Euch von Eurem Schamanenlehrer bereitgestellt wird, um den veränderten Wahrnehmungszustand zu erreichen, der erforderlich ist, um Elementargeister zu sehen und mit ihnen zu sprechen.",al={"manifestation nicht sichtbar","wo ist der erdgeist","erdmanifestation unsichtbar"}},{q="Wo sind diese Erdgeister zu finden?",a="Sie erscheinen am Kodofelsen in den wogenden Ebenen von Mulgore und am Geisterfelsen in den ariden Canyons von Durotar. Beide Stätten dienen als traditionelle Prüfungsstätten für junge Schamanen der Tauren, Orcs und Trolle.",al={"schwache erdmanifestation standort","erdmanifestation finden"}},{q="Welchen Zweck erfüllt der Geist während des Ritus?",a="Die Manifestation prüft und bestätigt formell die Verbindung des Initianden zum Element der Erde. Nach dem Gespräch mit dem Schamanen gewährt sie ein Stück Rohquarz, das zu einem Schamanenlehrer zurückgebracht wird, um das Erdtotem herzustellen.",al={"was macht manifestation","manifestation quest zweck"}},{q="Was sind die kleineren Kreaturen, die sie umgeben?",a="Den zentralen Geist umgeben geringere Erdmanifestationen. Sie sind schwache Echos des Elements, die von den heiligen Stätten angezogen wurden, existieren rein als Teil der natürlichen Zwiesprache und können nicht direkt interagiert werden.",al={"geringere manifestationen","kleine erdelementare drumherum"}}},fx={["40387732"]={q="Wer ist die Schwache Erdmanifestation?",a="Die Schwache Erdmanifestation ist ein elementarer Erdgeist, der an heiligen Orten wie dem Kodofels in Mulgore und dem Geisterfelsen in Durotar beschworen und verehrt wird. Für normale Augen unsichtbar, offenbart sie sich nur Schamanen, die ihr geistiges Bewusstsein durch zeremonielle Tränke wie Earth Sapta erweitert haben.",al={"was ist die schwache erdmanifestation","wer ist die erdmanifestation","schwache erdmanifestation hintergrund"}},f34b34da={q="Auf wessen Seite steht die Schwache Erdmanifestation?",a="Sie dient weder der Horde noch der Allianz. Als Verkörperung der Elemente steht sie im Einklang mit dem Gleichgewicht der natürlichen Welt und erhört die Bitten von Initianden, die den Respekt und die spirituelle Klarheit zeigen, die erforderlich sind, um mit der Erde in Verbindung zu treten.",al={"fraktion schwache erdmanifestation","ist die schwache erdmanifestation freundlich","auf welcher seite steht die erdmanifestation"}},["95a7d1ef"]={q="Was möchte die Schwache Erdmanifestation?",a="Sie begehrt die Verbindung mit all jenen, die den Pfad des Schamanen beschreiten. Wenn sich ein Initiand nähert, der den Earth Sapta zu sich genommen hat, versucht sie, dessen Entschlossenheit zu prüfen und ein Stück Rohquarz zu verleihen, um das Fundament für dessen ersten Totem zu bilden.",al={"was will die erdmanifestation","begehren der erdmanifestation","was sucht die schwache manifestation"}},["17161102"]={q="Warum ist die Schwache Erdmanifestation hier?",a="Sie weilt an heiligen Orten elementarer Macht, wie dem Kodofels in Mulgore und dem Geisterfelsen in Durotar, um als Brücke zwischen dem lebendigen Land und angehenden Schamanen zu dienen, die den Call of Earth durchlaufen.",al={"warum ist die schwache erdmanifestation am kodofels","warum ist die erdmanifestation hier","warum ist der erdgeist hier"}}},fp="28,291,18.638.0,49.247.0,39.198.0,45.234.0,46.221.0"}
P.entries["npc:minor-manifestation-of-water"] = {n="Schwache Wassermanifestation",s="Die Schwache Wassermanifestation ist ein Elementargeist, der an Nördlicher Gezeitenstrom an der Küste von Silberwald zu finden ist. Sie dient als entscheidende Prüfung für Hordeschamanen, die danach streben, mit dem Element des Wassers in Einklang zu treten und es zu meistern. Bevor dieser friedliche Geist konsultiert werden kann, müssen Initianden zunächst sein verderbtes Gegenstück reinigen.",h="Die Schwache Wassermanifestation ist ein Elementargeist, der an Nördlicher Gezeitenstrom an der Küste von...",kw={"ruf des wassers","elementar","schwache wassermanifestation","nördlicher gezeitenstrom","schamanenquest","silberwald","wassertotem"},ang={["class:Shaman"]="Die Verderbnis von diesem Elementar zu waschen und seinen Segen zu empfangen, ist der letzte Meilenstein auf dem Weg zum Einklang mit den Gezeiten und zum Schmieden Eures Wassertotems.",["faction:Horde"]="Schamanen der Trolle, Orcs und Tauren reisen den ganzen Weg von Kalimdor zu den Gestaden von Lordaeron, um mit diesem Geist zu kommunizieren."},sec={{t="Ein Geist der westlichen Gezeiten",b="An den nebelverhangenen Küsten von Nördlicher Gezeitenstrom, westlich vom Grabmal im Silberwald, stellt die Schwache Wassermanifestation einen wesentlichen Übergangsritus für heranreifende Schamanen dar. Wasserelementare verkörpern das Leben, die Erneuerung und den Fluss der Dinge, können jedoch leicht bösartiger Fäulnis zum Opfer fallen. Ein Initiand muss sich einer verderbten Manifestation dieses Elementars stellen und sie besiegen, bevor sich die reine Schwache Wassermanifestation offenbaren kann. Einmal gereinigt, bietet der Geist Schamanen Führung, die ihre heilige Reise zur Erschaffung eines Wassertotems vollenden."}},faq={{q="Wo kann ich die Schwache Wassermanifestation finden?",a="Die Schwache Wassermanifestation erscheint entlang von Nördlicher Gezeitenstrom, an der Westküste von Silberwald direkt westlich vom Grabmal.",al={"schwache wassermanifestation aufenthaltsort","wo ist die wassermanifestation","north tides run elementar"}},{q="Warum ist das Elementar feindselig, wenn ich mich ihm zuerst nähere?",a="Ein Schamane muss zuerst die Verderbte Schwache Wassermanifestation beschwören und vernichten. Erst nachdem Ihr die verderbte Präsenz besiegt habt, erscheint die friedliche Manifestation, um mit Euch zu sprechen.",al={"verderbte schwache manifestation","warum ist die wassermanifestation wütend","manifestation greift mich an"}},{q="Welche Quest beinhaltet dieses Elementar?",a="Dieser Geist ist ein entscheidender Kontakt in der Schamanenquestreihe „Ruf des Wassers“, durch die Schamanen letztlich die Fähigkeit erlangen, ihr Wassertotem zu stellen.",al={"ruf des wassers quest","wassertotem quest silberwald","für welche quest ist das"}},{q="Können Nicht-Schamanen mit diesem Geist interagieren?",a="Die Schwache Wassermanifestation existiert speziell dafür, Schamanen bei der Vollendung ihrer spirituellen Prüfungen anzuleiten. Andere Abenteurer werden kaum einen Grund finden, mit ihr zu interagieren.",al={"nur für schamanen","kann jeder mit manifestation sprechen","wer spricht mit schwacher manifestation"}}},fx={["8e58f5e5"]={q="Wer ist die Schwache Wassermanifestation?",a="Die Schwache Wassermanifestation ist ein Geist der elementaren Gewässer, der herbeigerufen wird, um aufstrebende Schamanen zu prüfen und zu leiten. Sobald sie von Verderbnis gereinigt wurde, dient dieses Elementar als Kanal für den natürlichen Fluss und die Weisheit des Wassers und unterstützt diejenigen, die lernen, den Ruf der Elemente zu beachten.",al={"wer ist die schwache wassermanifestation","was ist die schwache wassermanifestation","wer ist dieses elementar"}},c7703042={q="Auf wessen Seite steht die Schwache Wassermanifestation?",a="Die Manifestation gehört weder der Horde noch der Allianz. Sie dient dem Gleichgewicht der Elemente selbst, erhört die Beschwörungen von Schamanen, die nach einer Verbindung mit dem Wasser suchen, und zeigt, ob ein Bittsteller die Stärke und Reinheit des Geistes besitzt, um ihre Kräfte zu nutzen.",al={"fraktion schwache wassermanifestation","wem dient die wassermanifestation","ist die schwache wassermanifestation horde"}},["9e575f56"]={q="Was möchte die Schwache Wassermanifestation?",a="Dieser Geist versucht, jeden Schamanen zu prüfen, der die Meisterschaft über das Wasser anstrebt. Er verlangt, dass Ihr beweist, dass Ihr in der Lage seid, verderbende Mächte zu überwinden, bevor er seine reine Essenz teilt und seinen Segen gewährt.",al={"ziel der schwachen wassermanifestation","was begehrt die wassermanifestation","absicht der wassermanifestation"}},["05f89621"]={q="Warum ist die Schwache Wassermanifestation hier?",a="Die Manifestation wird von Orten angezogen, an denen sich die Macht des Wassers sammelt, und wartet auf die Rituale der Schamanen, die dem Call of Water folgen. Sie manifestiert sich speziell, um mit jenen in Verbindung zu treten, die von ihren elementaren Mentoren an ihren Ort geleitet wurden.",al={"warum ist die wassermanifestation hier","grund für den standort der wassermanifestation"}}},fp="28,323,29.559.0,50.134.0,51.182.0,35.152.0,42.167.0"}
P.entries["npc:misha-tor-kren"] = {n="Misha Tor'kren",s="Misha Tor'kren ist eine Ork-Mutter, die auf Tor'krens Hof im westlichen Durotar lebt, südöstlich des Donnergrats. Geplagt von der Sorge um ihren vermissten Sohn Kron, bittet sie vorbeiziehende Reisende um Hilfe, um sein Schicksal zu ergründen.",h="Misha Tor'kren ist eine Ork-Mutter, die auf Tor'krens Hof im westlichen Durotar lebt, südöstlich des...",kw={"krokolisken","kron","verloren, aber nicht vergessen","misha","misha tor'kren","der südstrom","donnergrat","tor'krens hof"},ang={["class:Hunter"]="Das Schicksal von Mishas Sohn zeigt die Gefahr, Flussraubtiere zu unterschätzen, bevor ein Jäger die Wildnis wirklich gemeistert hat.",["race:Orc"]="Krons leichtsinniger Wunsch, sein kriegerisches Können gegen die Tierwelt von Durotar zu beweisen, dient als düstere Erinnerung an den hohen Preis jugendlichen Stolzes."},sec={{t="Die Wache einer Mutter",b="Versteckt am Rande des Donnergrats bewirtschaftet Misha Tor'kren ihren abgelegenen Hof, während sie die schlimmste Angst eines Elternteils erträgt. Ihr Sohn Kron wagte sich nach Westen in Richtung des Südstroms, um Krokolisken zu jagen und seinen Mut zu beweisen, doch er kehrte nie zurück. Da die Gefahren an der Grenze von Durotar die orkischen Wachtürme bis an ihre Grenzen beanspruchen, bleibt Misha allein und hofft auf Nachrichten über seinen Verbleib, verzweifelt auf der Suche nach jemandem, der bereit ist, die Flussufer nach Anzeichen für ihren Jungen abzusuchen."},{t="Ein düsteres Andenken",b="Der Südstrom ist unerbittlich gegenüber jungen Jägern. Wer die schlammigen Ufer durchkämmt, stellt unweigerlich fest, dass Kron den bösartigen Krokolisken des Flusses zum Opfer fiel. Die Rückgabe seines geborgenen Amuletts ist die einzige Gewissheit, die Misha erhalten kann – eine bittere Erinnerung an die brutalen Prüfungen, denen sich junge Orks stellen müssen, um ihre Stärke in der rauen Wildnis von Kalimdor zu beweisen."}},faq={{q="Wer ist Misha Tor'kren?",a="Misha Tor'kren ist eine orkische Siedlerin, die auf Tor'krens Hof im westlichen Durotar lebt, nur südöstlich des Donnergrats.",al={"misha torkren","wer ist misha","besitzerin von torkrens hof"}},{q="Wohin ist ihr Sohn Kron gegangen?",a="Kron reiste nach Westen in Richtung des Südstroms, um Flusskrokolisken zu jagen, begierig darauf, sich als fähiger Jäger zu beweisen, kehrte jedoch nicht nach Hause zurück.",al={"wo ist kron","was passierte mit kron","mishas sohn"}},{q="Was passiert, wenn man nach Kron sucht?",a="Misha schickt Abenteurer aus, um entlang des Flusses nach Kron zu suchen. Sein Verschwinden lastet schwer auf ihr, und sie braucht jemanden, der das Gebiet untersucht.",al={"ist kron tot","finde kron","verloren, aber nicht vergessen"}},{q="Ist sie mit Rexxars Bärin Misha verwandt?",a="Nein. Obwohl sie den Namen Misha teilen, ist sie eine orkische Bäuerin, die in Durotar lebt und in keiner Weise mit Rexxars treuer Bärengefährtin verwandt ist.",al={"misha bär","rexxars bärin misha","ist sie die bärin"}}},fx={["971252e3"]={q="Auf wessen Seite steht Misha Tor'kren?",a="Misha Tor'kren ist ein loyales Mitglied der Horde und lebt als einfache Orc-Siedlerin in Durotar. Sie hat ihr Zuhause auf Tor'krens Hof, bearbeitet den harten, roten Boden und ist darauf angewiesen, dass Reisende der Horde und örtliche Helden ihrer Familie in Krisenzeiten beistehen.",al={"fraktion misha tor'kren","wem dient misha tor'kren","misha torkren horde"}},b9e15925={q="Was möchte Misha Tor'kren?",a="Misha möchte verzweifelt ihren verlorenen Sohn Kron finden. Der junge Orc verschwand, während er an den gefährlichen Ufern des Südstroms auf der Jagd war, und sie fleht vorbeikommende Abenteurer an, die Gewässer zu durchsuchen, herauszufinden, was aus ihm geworden ist, und jedes Zeichen seines Schicksals zurückzubringen.",al={"was möchte misha","ziel von misha tor'kren","warum braucht misha hilfe"}},["8e838196"]={q="Wem ist Misha Tor'kren verbunden?",a="Misha ist zutiefst mit ihrer Familie verbunden, allen voran ihrem vermissten Sohn Kron. Sie verwaltet das Gehöft Tor'kren südöstlich des Donnergrats, wo ihr Lebensunterhalt davon abhängt, die Gefahren der Wildnis von Durotar zu überleben.",al={"familie misha tor'kren","mit wem ist misha verwandt","misha torkren sohn"}}},fp="14,221,16.444.0,12.345.1,22.124.0,26.140.0,36.147.1,38.130.0"}
P.entries["npc:mitsuwa"] = {n="Mitsuwa",s="Mitsuwa ist ein Troll der Dunkelspeer, der am Außenposten von Zoram'gar an der nebligen Küste von Eschental stationiert ist. Zutiefst erschüttert über den Hinterhalt auf seine reisenden Verwandten, heuert er Recken der Horde an, um die Gefallenen zu rächen und gestohlene spirituelle Talismane zurückzuholen.",h="Mitsuwa ist ein Troll der Dunkelspeer, der am Außenposten von Zoram'gar an der nebligen Küste von Eschental...",kw={"eschental","dunkelspeer","furbolg","marukai","mitsuwa","distelfelle","troll","trollglücksbringer","zoram'gar"},ang={["faction:Horde"]="Der Außenposten von Zoram'gar ist eine isolierte und belagerte Garnison; Mitsuwa beizustehen stärkt die gefährdete Präsenz der Horde gegen wilde Bestien und Späher der Allianz an den westlichen Gestaden von Kalimdor.",["race:Troll"]="Mitsuwas Ruf zu den Waffen berührt Abenteurer der Dunkelspeere zutiefst auf persönlicher Ebene, da die Rückholung der heiligen Glücksbringer der Ahnen von den primitiven marodierenden Furbolgs ihren ermordeten Brüdern und Schwestern ihren Frieden zurückgibt."},sec={{t="Rache für die gefallenen Verwandten",b="Am abgelegenen Außenposten von Zoram'gar an der Küste des Zoramstrands dient Mitsuwa der Horde an der Seite seines Gefährten Marukai. Als eine Gruppe reisender Trolle auf dem Weg zum Lager von den aggressiven Furbolgs der Distelfelle aus dem nördlichen Eschental überfallen und niedergemetzelt wurde, empfand Mitsuwa diesen Verlust als schwere Beleidigung. Angetrieben von Pflichtgefühl und Zorn schickt er fähige Krieger zu den Höhlen der Distelfelle, um die gestohlenen Troll-Glücksbringer zurückzuholen. So stellt er sicher, dass die Geister seiner Verwandten geehrt und ihre heiligen Besitztümer den Bestien wieder entrissen werden."}},faq={{q="Wer ist Mitsuwa?",a="Mitsuwa ist ein Dschungeltroll der Dunkelspeer, der am Außenposten von Zoram'gar im nordwestlichen Eschental weilt. Gemeinsam mit seinem Gefährten Marukai bewacht er den Grenzposten und koordiniert Vergeltungsmaßnahmen gegen feindselige Bedrohungen in der Region.",al={"mitsuwa","wer ist mitsuwa","mitsuwa lore"}},{q="Was geschah mit den Trollen, die nach Zoram'gar reisten?",a="Eine Gruppe von Trollen, die durch Eschental reiste, um den Außenposten von Zoram'gar zu verstärken oder zu besuchen, wurde von den einheimischen Furbolgs der Distelfelle überfallen und niedergemetzelt, die den gefallenen Reisenden ihre persönlichen Besitztümer raubten.",al={"tote trolle eschental","distelfelle greifen trolle an"}},{q="Warum sind die Troll-Glücksbringer für Mitsuwa so wichtig?",a="Die Glücksbringer besitzen für den Stamm der Dunkelspeere eine spirituelle und kulturelle Bedeutung. Die heiligen Relikte nach einem brutalen Massaker in den Händen der Furbolgs der Distelfelle zu belassen, bedeutet eine tiefe Entehrung für die Geister der Erschlagenen.",al={"warum troll-glücksbringer","troll-glücksbringer quest grund"}},{q="Wo befinden sich die Glücksbringer?",a="Die Glücksbringer wurden von den Furbolgs der Distelfelle in ihr Lager der Distelfelle und ihren üblen Bau verschleppt, der im nördlichen Eschental östlich des Zoramstrands liegt.",al={"wo sind troll-glücksbringer","lager der distelfelle ort"}}},fx={["24ae2c07"]={q="Auf wessen Seite steht Mitsuwa?",a="Mitsuwa ist der Horde gegenüber loyal und lebt unter seinesgleichen im Außenposten von Zoram'gar an der Küste des Eschentals. Er arbeitet eng mit anderen Reisenden der Horde zusammen und zählt auf Abenteurer der Horde, um gefallene Kameraden zu rächen.",al={"fraktion mitsuwa","ist mitsuwa horde","wem dient mitsuwa"}},ec72a5f0={q="Was möchte Mitsuwa?",a="Mitsuwa sucht Gerechtigkeit für eine Gruppe anderer Trolle, die auf dem Weg zum Außenposten von Zoram'gar abgeschlachtet wurden. Die aggressiven Distelpelzfurbolgs haben die Reisenden überfallen und ihre heiligen Trollfetische gestohlen, und Mitsuwa möchte, dass diese gestohlenen Erbstücke den Bestien wieder entrissen werden.",al={"mitsuwas ziel","was braucht mitsuwa","mitsuwa quest"}},b936450a={q="Warum ist Mitsuwa hier am Außenposten von Zoram'gar?",a="Mitsuwa ist am Außenposten von Zoram'gar stationiert, einem abgelegenen Lager der Horde an der Westküste des Eschentals. Von hier aus überwacht er die umliegende Wildnis und kümmert sich um Reisende, die sich auf die tückischen Straßen durch das Gebiet der Furbolgs und Nachtelfen wagen.",al={"warum ist mitsuwa in zoram'gar","mitsuwas aufgabe im eschental","warum ist mitsuwa hier"}}},fp="7,235,23.547.0,15.220.0,51.214.0,49.215.0,29.141.0"}
P.entries["npc:monte-gazlowe"] = {fx={cabfa558={q="Warum ist Gazlowe in Ratschet?",a="Nachdem Gazlowe ein Vermögen damit verdient hatte, Thrall beim Aufbau von Orgrimmar zu helfen, investierte er seine Gewinne in die Gründung von Ratschet. Gelegen an der Mündung des Südstroms an der Küste des Brachlands, dient es als wichtigster neutraler Handelshafen in Kalimdor für das Steamwheedle Cartel, was ihm erlaubt, den Seehandel, regionale Ingenieurprojekte und lukrative Verträge auf dem gesamten Kontinent zu beaufsichtigen.",al={"warum kam gazlowe nach ratschet","warum ist gazlowe hier","gazlowes aufgabe in ratschet"}}}}
P.entries["npc:moon-priestess-amara"] = {n="Mondpriesterin Amara",s="Mondpriesterin Amara ist eine Nachtelfenpriesterin, die an der Hauptstraße westlich von Dolanaar in Teldrassil stationiert ist. Flankiert von treuen Jägerinnenwachen wacht sie über die Waldpfade, die das Herz des Astes mit der Hauptstadt Darnassus verbinden.",h="Mondpriesterin Amara ist eine Nachtelfenpriesterin, die an der Hauptstraße westlich von Dolanaar in...",kw={"amara nightwalker","dolanaar","elanaria","mondpriesterin amara","nhemai","teldrassil","die straße nach darnassus","yaeliura"},ang={["class:Priest"]="Als Mitglied der Schwesternschaft von Elune verkörpert Priesterin Amara die Hingabe der Nachtelfen an die Mondgöttin und dient jungen Akolythen, die aus Laubschattental aufbrechen, als seelsorgerische und spirituelle Führerin.",["race:NightElf"]="Amara markiert einen wichtigen Meilenstein auf Eurer Reise weg von Dolanaar und bietet Führung sowie Aufgaben, die in die große Stadt Darnassus führen."},sec={{t="Wächterin der Astwege",b="Stationiert an einem ruhigen Wegesposten westlich von Dolanaar, verkörpert Mondpriesterin Amara sowohl die spirituelle Autorität der Schwesternschaft von Elune als auch die praktische Wachsamkeit, die zur Sicherung der Straßen von Teldrassil erforderlich ist. Sie reist und wacht an der Seite zweier Jägerinnenbegleiterinnen, Nhemai und Yaeliura. Reisenden, die nach Westen ziehen, dient Amara als helfende Hand; sie leitet Abenteurer entlang der Straße nach Darnassus und beauftragt jene mit beschwertem Geist, Pfade der Erlösung zu suchen."}},faq={{q="Wer ist Mondpriesterin Amara?",a="Mondpriesterin Amara, im Dienst der Schildwachen auch als Amara Nightwalker bekannt, ist eine Priesterin der Schwesternschaft von Elune, die an der Straße zwischen Dolanaar und Darnassus in Teldrassil stationiert ist. Sie wacht über die Sicherheit und das spirituelle Wohl der Reisenden, die durch den Ast ziehen.",al={"wer ist amara","priesterin amara","schildwache amara nightwalker"}},{q="Wo kann ich Mondpriesterin Amara finden?",a="Sie befindet sich an der befestigten Straße direkt westlich von Dolanaar in Teldrassil und hält dort an der Seite zweier Jägerinnen der Schildwachen Wache.",al={"wo ist amara","amara standort","priesterin amara karte"}},{q="Wer sind die Jägerinnen, die bei ihr stehen?",a="Sie wird von Jägerin Nhemai und Jägerin Yaeliura bewacht und begleitet, zwei Nachtelfenschildwachen, die dabei helfen, die Durchgangsstraße vor Bestien und feindseliger Verderbnis zu schützen.",al={"amara begleiter","nhemai und yaeliura","amara wachen"}}},fx={["3d569ab2"]={q="Auf wessen Seite steht Mondpriesterin Amara?",a="Mondpriesterin Amara dient dem Priestertum von Elune und der Allianz und wacht über die heiligen Äste von Teldrassil. An der Seite ihrer Gefährtinnen der Sentinel widmet sie sich dem Schutz der Reisenden und der Verteidigung des Herzlandes der Kaldorei vor der Verderbnis, die dessen friedliche Wälder bedroht.",al={"amaras fraktion","amaras loyalität","wem dient amara"}},["75dde252"]={q="Warum ist Mondpriesterin Amara hier stationiert?",a="Amara ist entlang der Hauptstraße westlich von Dolanaar stationiert, um Reisende auf ihrem Weg nach Darnassus zu schützen. Die Pfade von Teldrassil werden zunehmend von verdorbenen Bestien und lauernden Holzlingen belagert, weshalb ihre Anwesenheit entscheidend dafür ist, die Waldwege sicher zu halten.",al={"warum ist amara hier","amaras zweck am standort","warum ist mondpriesterin amara auf der straße"}},["74974fcb"]={q="Was möchte Mondpriesterin Amara?",a="Sie sucht fähige Abenteurer, die dabei helfen, den Weg zur Hauptstadt Darnassus zu sichern. Amara beauftragt Reisende damit, die abscheulichen Gnarlpinefurbolgs und bösartigen Waldkreaturen zu beseitigen, die diejenigen belästigen, die unter den Ästen des Weltenbaums nach Westen reisen.",al={"was braucht amara","amaras questmotiv","warum schickt amara einen auf quests"}}},fp="20,252,25.480.0,28.270.0,38.122.0,41.174.0"}
P.entries["npc:mor-rogal"] = {n="Mor'rogal",s="Mor'rogal ist ein Tauren, der in Sonnenfels im Steinkrallengebirge lebt. Er dient als Ratgeber und Führer für Reisende, die auf der Suche nach Ruhm und Gefahr in den zerklüfteten unterirdischen Bereichen der Felsen sind.",h="Mor'rogal ist ein Tauren, der in Sonnenfels im Steinkrallengebirge lebt.",kw={"steinschlagklamm","der irdene erhebt sich","mor'rogal","morrogal","steinkrallengebirge","sonnenfels","tauren"},ang={["faction:Horde"]="Für Reisende, die den Zufluchtsort Sonnenfels erreichen, liefert Mor'rogal wichtige Informationen über die Bedrohungen, die in den Felsen jenseits der Grenzen der Siedlung lauern.",["race:Tauren"]="Mor'rogal verkörpert den Respekt der Tauren vor körperlichen und geistigen Prüfungen und betrachtet die tiefen Felshöhlen von Kalimdor als heiligen Boden, um den eigenen Wert zu beweisen."},sec={{t="Wächter in den Felsen",b="In der Zuflucht von Sonnenfels hockend, interessiert sich Mor'rogal brennend für die tiefen Felsspalten und Höhlen, die das Steinkrallengebirge durchziehen. Da er erkennt, dass die verschlungenen unterirdischen Pfade der Region sowohl großen Reichtum als auch tödliche Gefahr bieten, weist er tapfere Wanderer der Horde an, unruhige Gebiete wie die Steinschlagklamm zu untersuchen. Für Mor'rogal ist das Vordringen in diese tückischen Tiefen nicht nur eine Frage des Überlebens, sondern eine Prüfung des Geistes für all jene, die ihrem Herzen und ihrer Seele auf der Suche nach Ruhm folgen."}},faq={{q="Wer ist Mor'rogal?",a="Mor'rogal ist ein Tauren-Questgeber, der in Sonnenfels im Steinkrallengebirge lebt. Er agiert als ortskundiger Führer und drängt Abenteurer der Horde dazu, ihren Mut in den gefährlichen Höhlen und Schluchten zu beweisen, die über das zerklüftete Gebirge verstreut sind.",al={"morrogal","wer ist mor'rogal","mor rogal hintergrundgeschichte"}},{q="Wo kann ich Mor'rogal finden?",a="Er ist in Sonnenfels anzutreffen, dem wichtigsten Außenposten der Horde, der inmitten der Gipfel des zentralen Steinkrallengebirges versteckt liegt.",al={"mor'rogal standort","wo ist mor'rogal","morrogal punkt"}},{q="Welche Aufgaben bietet Mor'rogal an?",a="Mor'rogal rekrutiert fähige Champions, die sich in die Höhle der Steinschlagklamm wagen sollen, wo Kobolde fieberhaft Resonitkristalle abbauen, und danach Goggeroc zu erschlagen, einen schlummernden Irdenen, den die Kobolde ausgegraben haben.",al={"mor'rogal quests","was will mor'rogal"}},{q="Warum konzentriert sich Mor'rogal auf Höhlen und Schluchten?",a="Mor'rogal glaubt, dass die gefährlichen unterirdischen Höhlen des Steinkrallengebirges wahre Abenteuer und Prüfungen der geistigen Entschlossenheit bereithalten und denjenigen, die bereit sind, ihr Leben zu riskieren, Ruhm und Reichtum bieten.",al={"warum höhlen","mor'rogal höhlen"}}},fx={["9b06cf83"]={q="Auf wessen Seite steht Mor'rogal?",a="Mor'rogal steht auf der Seite der Horde und seiner Taurenbrüder. Stationiert im Sonnenfels, einem abgelegenen Außenposten der Horde hoch im Steinkrallengebirge, bietet er Abenteurern, die den Interessen der Horde in der Region dienen, Führung und Aufgaben an.",al={"mor'rogals fraktion","ist mor'rogal horde oder allianz","mor'rogals loyalität"}},["27de9984"]={q="Was möchte Mor'rogal?",a="Mor'rogal sucht tapfere Abenteurer, die bereit sind, sich in die gefährlichen Höhlen und Schluchten des Steinkrallengebirges zu wagen. Er schickt Kundschafter an feindselige Orte wie die Steinschlagklamm und drängt kühne Geister dazu, sich für Ehre und Reichtum den unterirdisch lauernden Gefahren aus Erde zu stellen.",al={"mor'rogals ziele","was macht mor'rogal","zweck von mor'rogals quests"}}},fp="9,204,20.521.0,17.246.0,27.130.0,32.208.0,46.188.0"}
P.entries["npc:morgan-pestle"] = {fx={["2e5b0856"]={q="Wer ist Morgan Pestle?",a="Morgan Pestle ist ein menschlicher Alchemist und Ladenbesitzer, der vom Handelsdistrikt in Sturmwind aus arbeitet. Er besitzt und betreibt Pestles Apotheke und handelt mit Reagenzien, Heilmitteln und verschiedenen alchemistischen Mischungen für die Einwohner der Stadt.",al={"wer ist morgan pestle","morgan pestle hintergrundgeschichte","wer ist pestle"}},ae642a6d={q="Auf wessen Seite steht Morgan Pestle?",a="Morgan Pestle ist ein loyaler Bürger der Allianz. Sein Handel, der im Herzen des Handelsdistrikts von Sturmwind ansässig ist, unterstützt die lokale Bevölkerung und das gesamte Königreich.",al={"morgan pestles fraktion","ist morgan pestle allianz","morgan pestles loyalität"}}}}
P.entries["npc:morgan-the-collector"] = {fx={["8321821e"]={q="Auf wessen Seite steht Morgan der Sammler?",a="Morgan der Sammler ist ein engagierter Handlanger der The Defias Brotherhood. Er ist kein gewöhnlicher Wegelagerer, sondern dient als Offizier innerhalb der kriminellen Organisation, arbeitet direkt gegen das Königreich Sturmwind und orchestriert die Aktivitäten der Bruderschaft im gesamten Herzen des Waldes von Elwynn.",al={"morgan der sammler fraktion","welcher fraktion gehört morgan an","ist morgan defias"}},["5f1d52ce"]={q="Was möchte Morgan der Sammler?",a="Morgan fungiert als Rädelsführer, der die Operationen der Defias im gesamten Wald von Elwynn überwacht. Unter dem Spitznamen \"der Sammler\" ist es sein Ziel, Reichtum, Ressourcen und Einfluss für den Aufstand der Bruderschaft zu sammeln und direkt unter den Nasen der Wachen von Sturmwind einen befestigten Stützpunkt im Kürbisbeet zu errichten.",al={"was versucht morgan zu tun","morgan der sammler ziel","morgan der sammler motiv"}},["2a29f808"]={q="Warum ist Morgan der Sammler im Wald von Elwynn?",a="Morgan hat sich in Brackwells Kürbisbeet niedergelassen, um die lokalen Operationen der The Defias Brotherhood persönlich zu leiten. Indem er zusammen mit den Leutnants Surena Caledon und Erlan Drudgemoor Zuflucht in dem Bauernhaus sucht, koordiniert er die Banditen, die sich in der gesamten Region ausbreiten, engmaschig.",al={"warum ist morgan in brackwells kürbisbeet","was brachte morgan hierher"}},ceb85f69={q="Mit wem ist Morgan der Sammler verbunden?",a="Sein Siegelring wird zu einem Beweisstück bei der Untersuchung der Gesetzlosen, die den Wald von Elwynn beunruhigen, und deren Verbindungen.",al={"mit wem arbeitet morgan zusammen","morgan der sammler verbündete","morgan steinmetze"}}}}
P.entries["npc:morin-cloudstalker"] = {n="Morin Wolkenpirscher",s="Morin Wolkenpirscher ist ein Taurenspäher, der entlang der Straße Wache hält, die östlich des Dorfes der Bluthufe in Richtung Brachland in Mulgore führt. Er wacht über die Ebenen, überwacht die lokalen Handelsrouten und untersucht die drohenden Gefahren, die Tauren-Reisende gefährden.",h="Morin Wolkenpirscher ist ein Taurenspäher, der entlang der Straße Wache hält, die östlich des Dorfes der...",kw={"bloodhoof","großes tor","morin wolkenpirscher","mulgore","überfallene karawane","vorsteher zischelspross","venture company"},ang={["faction:Horde"]="Morin bietet Champions der Horde eine frühe Gelegenheit, die Vorräte und heiligen Ländereien ihrer neuen Tauren-Verbündeten zu schützen.",["race:Tauren"]="Für Tauren, die vom Dorf der Bluthufe aus aufbrechen, repräsentiert Morin die wachsame Verteidigung Eurer Heimat gegen opportunistische Banditen und unternehmerische Schänder."},sec={{t="Wächter des südlichen Pfades",b="Positioniert neben dem Feldweg, der sich nach Osten in Richtung Brachland schlängelt, agiert Morin Wolkenpirscher sowohl als Späher als auch als Beschützer für Reisende durch Mulgore. Die grasbewachsenen Ebenen sind hier normalerweise friedlich, doch die Eröffnung von Handelsrouten und sich verschiebende Gebiete haben Opportunisten und Banditen gefährlich nah an das Herz der Heimat der Tauren gelockt."},{t="Untersuchung der Karawane",b="Morins Späher haben kürzlich eine Karawane der Venture Company am nördlichen Ufer des Stonebullsee angegriffen und niedergebrannt. Als Goblin-Plünderer in der Nähe der verbrannten Wagen gesichtet wurden, schickte er Abenteurer aus, um die überlebenden Vorratskisten zu untersuchen und herauszufinden, was die Venture Company transportierte."},{t="Verteidigung gegen die Venture Company",b="Neben gewöhnlichen Wegelagerern ist Morin zutiefst besorgt über die industrielle Präsenz der Venture Company, die Operationen innerhalb von Mulgore aufbaut. Er weist vorbeiziehende Horde-Abenteurer an, ihre Holzfäller- und Bergbauaußenposten anzugreifen und gezielt wichtige Anführer wie Vorsteher Fizsprocket auszuschalten, um die Umweltzerstörung zu stoppen, die die heiligen Ebenen bedroht."}},faq={{q="Wo kann ich Morin Wolkenpirscher finden?",a="Morin Wolkenpirscher steht am Feldweg östlich des Dorfes der Bluthufe in Mulgore, entlang der Straße, die in Richtung Brachland führt.",al={"morin standort","wo ist morin","morin wolkenpirscher karte"}},{q="Was ist Morins Rolle in Mulgore?",a="Er ist ein wachsamer Taurenspäher, der dafür verantwortlich ist, das Reisen durch das südliche Mulgore zu überwachen und die Verteidigung gegen Banditen und unternehmerische Eindringlinge zu organisieren.",al={"wer ist morin wolkenpirscher","morin rolle"}},{q="Warum untersucht Morin die zerstörte Karawane?",a="Morins Späher haben eine Karawane der Venture Company in der Nähe des Stonebullsee angegriffen und niedergebrannt. Als Goblin-Plünderer um das Wrack herum gesehen wurden, bat er Abenteurer, die überlebenden Vorratskisten zu untersuchen, um herauszufinden, was die Venture Company transportierte.",al={"quest überfallene karawane","karawanenangriff mulgore"}},{q="Warum möchte Morin, dass die Venture Company gestoppt wird?",a="Die Venture Company entzieht Mulgore die natürlichen Ressourcen mit Maschinen und durch Abholzung. Morin versucht, ihr zerstörerisches Unternehmen zu stören, indem er ihre Aufseher, einschließlich Vorsteher Fizsprocket, eliminiert.",al={"venture company mulgore","warum fizsprocket töten"}},{q="Wem untersteht Morin?",a="Morin handelt im Namen der Ältesten und Häuptlinge des Dorfes der Bluthufe und der breiteren Führung der Tauren in ganz Mulgore.",al={"morin loyalität","wer schickte morin"}},{q="Bietet Morin Allianzinspielern Quests an?",a="Nein. Morin ist ein NSC, der ausschließlich der Horde loyal ist und nur mit Horde-Abenteurern interagiert.",al={"kann die allianz mit morin sprechen","morin fraktion"}}},fx={["2ee6eb23"]={q="Wer ist Morin Wolkenpirscher?",a="Morin Wolkenpirscher ist ein Kundschafter und Beschützer der Tauren, der über Mulgore wacht. Er ist entlang der Straße postiert, die östlich des Dorfes der Bluthufe in Richtung Brachland führt, hält Ausschau nach Bedrohungen, die in das angestammte Land der Tauren kriechen, und entsendet fähige Abenteurer der Horde, um die Ebenen vor Plünderern und Ausbeutern zu schützen.",al={"wer ist morin wolkenpirscher","wer ist morin","morin hintergrundgeschichte"}},b362fb80={q="Auf wessen Seite steht Morin Wolkenpirscher?",a="Morin ist fest loyal gegenüber To Thunder Bluff und der Horde. Er bewacht das Herzland des Taurenvolkes und bietet seine Führung und Aufgaben nur anderen Reisenden der Horde an, die bereit sind, den zerbrechlichen Frieden von Mulgore zu verteidigen.",al={"morin wolkenpirscher fraktion","ist morin horde oder allianz","ist morin horde"}},["7047ff15"]={q="Was möchte Morin Wolkenpirscher?",a="Morin versucht, die Straßen und natürlichen Ressourcen von Mulgore zu schützen. Er schickt Abenteurer aus, um die Karawane der Venture Company zu untersuchen, die seine Kundschafter niedergebrannt haben, und die destruktiven Operationen der Venture Company zu stoppen; insbesondere fordert er ein Ende von Supervisor Fizsprockets ausbeuterischem Bergbau in den Hügeln.",al={"was möchte morin","morins ziele","morins aufgaben"}},["9ad7af70"]={q="Warum ist Morin Wolkenpirscher hier stationiert?",a="Morin ist entlang der Straße östlich des Dorfes der Bluthufe stationiert, um über Reisen durch Mulgore zu wachen. Diese kritische Kreuzung ermöglicht es ihm, vorbeiziehende Karawanen zu überwachen und eindringende Gefahren – wie die Schänder der Venture Company – abzufangen, bevor sie das Dorf der Bluthufe erreichen.",al={"warum ist morin hier","warum ist morin auf der straße","grund für morins standort"}}},fp="18,266,29.343.0,25.268.0,29.346.1,36.128.0,32.152.0,46.232.0,48.212.0,25.124.0,44.94.0"}
P.entries["npc:motega-firemane"] = {fx={ca68f68f={q="Auf wessen Seite steht Motega Feuermähne?",a="Motega Feuermähne ist den Tauren und der Horde treu ergeben. Stationiert am Weißgipfelposten an der Seite von Kanati Grauwolke, arbeitet er eng mit Reisenden der Horde zusammen und wahrt die Interessen von Cairne Bluthuf und den Stämmen unter dem Banner von Donnerfels.",al={"fraktion von motega feuermähne","ist motega feuermähne horde oder allianz","gehört motega zur horde"}},["8b7dc2d8"]={q="Was will Motega Feuermähne?",a="Motega konzentriert sich hauptsächlich auf das Studium der einzigartigen Tierwelt der Tausend Nadeln, während er seinen jungen Begleiter Pao'ka Bergrausch im Auge behält. Bedrohungen für Donnerfels haben jedoch schnell Vorrang. Wenn er vor der rachsüchtigen Windschlange Arikara gewarnt wird, versucht er, das Biest zu beschwören und zu vernichten, bevor es Cairne Bluthuf gefährden kann.",al={"was will motega","ziele von motega feuermähne","was versucht motega zu tun"}},["12cba981"]={q="Warum ist Motega Feuermähne hier?",a="Motega reiste in die Tausend Nadeln hinab, um die exotischen Tiere zu beobachten und zu studieren, die auf dem Grund des Canyons und den umliegenden Mesas heimisch sind. Der Weißgipfelposten dient als Basislager für seine Forschung, obwohl lokale Probleme – von verlorenen Gefährten bis hin zu bedrohlichen mythischen Schlangen – ihn oft von seinen wissenschaftlichen Bestrebungen ablenken.",al={"warum ist motega in den tausend nadeln","warum ist motega am weißgipfelposten","zweck von motega feuermähne"}}}}
P.entries["npc:mountaineer-barleybrew"] = {n="Gebirgsjäger Gerstenbräu",s="Gebirgsjäger Gerstenbräu ist ein Gebirgsjäger aus Eisenschmiede, der am Südtoraußenposten in Dun Morogh stationiert ist. Er bewacht den Pass, der nach Osten in Richtung Loch Modan führt, und verlässt sich auf herzhafte Zwergengebräue, um die Wachen in der schneidenden Kälte wachsam zu halten.",h="Gebirgsjäger Gerstenbräu ist ein Gebirgsjäger aus Eisenschmiede, der am Südtoraußenposten in Dun Morogh...",kw={"gerstenbräu","dun morogh","gebirgsjäger","schimmerstarkbier","südtoraußenposten","wellart"},ang={["race:Dwarf"]="Für Zwerge verkörpert Gerstenbräu die grundlegende Ausgewogenheit von Grenzdienst und hochprozentiger Erfrischung, die Khaz Modan sicher hält."},sec={{t="Wache am Ostpass",b="Am Südtoraußenposten postiert, um die verschneite Straße nach Loch Modan zu bewachen, steht Gebirgsjäger Wellart Gerstenbräu als Teil der Grenzwache von Eisenschmiede. Wie viele Gebirgsjäger, die in den eisigen Winden von Dun Morogh dienen, schätzt er die stärkenden Eigenschaften feiner Zwergengetränke. Als Träger des Namens des berühmten Gerstenbräu-Klans sorgt er mit dafür, dass Lieferungen des wirksamen Schimmerstarkbiers ihren Weg zu Kameraden finden, die während langer Wachen an den Bergpässen Wärme und Durchhaltevermögen benötigen."}},faq={{q="Wo kann ich Gebirgsjäger Gerstenbräu finden?",a="Gebirgsjäger Gerstenbräu ist am Südtoraußenposten stationiert, der Zwergenbefestigung, die den östlichen Pass zwischen Dun Morogh und Loch Modan bewacht.",al={"gerstenbräu standort","wo ist gebirgsjäger gerstenbräu","gerstenbräu nsc"}},{q="Was ist seine Aufgabe am Südtoraußenposten?",a="Er dient als Gebirgsposten zum Schutz der Straße und hilft bei der Koordination von Vorräten, einschließlich Schimmerstarkbier für befreundete Gebirgsjäger, die in den Pässen stationiert sind.",al={"gerstenbräu zweck","was macht gerstenbräu"}},{q="Ist er mit den anderen Gerstenbräus verwandt?",a="Ja. Sein Bruder ist der Brauer Rejold Gerstenbräu, und er ist möglicherweise auch mit Marleth, Malgin und Yorus Gerstenbräu verwandt.",al={"gerstenbräu familie","yorus gerstenbräu verwandter"}}},fx={["583559ff"]={q="Wer ist Gebirgsjäger Gerstenbräu?",a="Gebirgsjäger Wellart Gerstenbräu ist ein zwergischer Wachposten, der zur Verteidigung der östlichen Grenzen von Dun Morogh stationiert ist. Wie alle Gebirgsjäger der Eisenschmiede wacht er wachsam gegen die Bestien, Troggs und Frosttroll-Plünderer, die die Bergstraßen bedrohen, und gleicht seinen strengen Grenzdienst mit einer ausgeprägten zwergischen Vorliebe für gutes Bier aus.",al={"wer ist gebirgsjäger gerstenbräu","wer ist gerstenbräu","lore von gebirgsjäger gerstenbräu"}},["399d0350"]={q="Auf wessen Seite steht Gebirgsjäger Gerstenbräu?",a="Er ist ein standhafter Soldat der Eisenschmiede und der Allianz treu ergeben. Er befolgt die Befehle des Bronzebart-Clans und König Magni Bronzebarts und gewährleistet die Sicherheit von Reisenden und wichtigen Bergpässen im gesamten Reich.",al={"fraktion von gebirgsjäger gerstenbräu","wem dient gerstenbräu","ist gerstenbräu allianz"}},fc186c57={q="Was will Gebirgsjäger Gerstenbräu?",a="Neben der Sicherung der Straße vor Eindringlingen schätzt Gebirgsjäger Gerstenbräu ein kräftiges Gebräu, um der eisigen Bergluft zu trotzen. Er ist darauf angewiesen, dass Reisende Nachrichten und Vorräte – einschließlich eines Schlucks starkem Shimmer Stout – zwischen seinem Posten und Verbündeten in der Nähe überbringen.",al={"was will gerstenbräu","was braucht wellart gerstenbräu","wonach sucht gerstenbräu"}},b2269341={q="Warum ist Gebirgsjäger Gerstenbräu hier?",a="Er ist am Pass des Südtoraußenpostens stationiert, um die wichtige Durchgangsstraße zu bewachen, die Dun Morogh mit Loch Modan verbindet. Die hohen Pässe sind ständiger Gefahr durch umherstreifende Wildtiere und aggressive Trogg-Kriegstrupps ausgesetzt, was disziplinierte Gebirgsjäger erfordert, um die Tore befestigt und sicher zu halten.",al={"warum ist gerstenbräu am südtor","warum ist gebirgsjäger gerstenbräu hier stationiert","grund für den standort von gerstenbräu"}}},fp="22,232,27.499.0,40.145.0,39.165.0,39.118.0"}
P.entries["npc:mountaineer-kadrell"] = {n="Gebirgsjäger Kadrell",s="Gebirgsjäger Kadrell ist ein standhafter Zwergenposten, der gegenüber dem Gasthof Zum Starkbier-Lager in Thelsamar stationiert ist. Als entscheidendes Bindeglied innerhalb der Gebirgsjäger von Loch Modan koordiniert er die Aufklärung, Nachschublieferungen und die Grenzverteidigung in der gesamten Region.",h="Gebirgsjäger Kadrell ist ein standhafter Zwergenposten, der gegenüber dem Gasthof Zum Starkbier-Lager in...",kw={"kadrell","loch modan","gebirgsjäger","rockgar","stormpike","gasthof zum starkbier-lager","thelsamar"},ang={["faction:Alliance"]="Kadrell verlässt sich auf Reisende der Allianz, die Thelsamar durchqueren, um Nachrichten zu überbringen und entfernten Gebirgsjäger-Außenposten beizustehen, die gegen regionale Gefahren ankämpfen.",["race:Dwarf"]="Als Teil des angesehenen Gebirgsjägerkorps verkörpert Kadrell die vorderste Wachtlinie, die Eisenschmiedes östliche Gebiete vor den vordringenden Gefahren der Wildnis schützt."},sec={{t="Der Wachposten von Thelsamar",b="Gebirgsjäger Kadrell hält in der geschäftigen Siedlung Thelsamar Wache und fungiert als Rückgrat der zwergischen Verteidigung in ganz Loch Modan. Während Außenposten an den Rändern des Tals unablässig von Troggs, Gnollen und einheimischen Bestien bedrängt werden, bleibt Kadrell im Zentrum des Ortes, um Verstärkung zu organisieren, Befehle weiterzugeben und eingehende Lageberichte von umherstreifenden Spähern auszuwerten."},{t="Die Verbindung aufrechterhalten",b="Zu Kadrells Aufgaben gehört häufig das Aufrechterhalten des Kontakts zwischen Thelsamar und abgelegenen Vorposten. Ob er sich nun mit Gebirgsjäger Sturmlanze abstimmt oder Abenteurer entsendet, um sich bei Wachposten wie Gebirgsjäger Rockgar zu melden – Kadrell stellt sicher, dass die isolierten Außenposten an den Gebirgspässen lebenswichtigen Nachschub, Verstärkung und defensive Aufklärungsdaten erhalten."}},faq={{q="Wo ist Gebirgsjäger Kadrell zu finden?",a="Kadrell ist direkt gegenüber dem Gasthof Zum Starkbier-Lager im Ort Thelsamar stationiert, der inmitten der sanften Hügel von Loch Modan liegt.",al={"kadrell aufenthaltsort","wo ist kadrell","kadrell finden"}},{q="Welche Rolle spielt Kadrell in Loch Modan?",a="Er ist ein Mitglied der zwergischen Gebirgsjäger und damit beauftragt, als Verbindung zwischen der örtlichen Führung von Thelsamar und den abgelegenen Wachposten der Region zu fungieren sowie Patrouillen, Vorräte und Grenzberichte zu koordinieren.",al={"was macht kadrell","kadrells aufgabe","kadrells funktion"}},{q="Warum schicken andere Gebirgsjäger Boten zu Kadrell?",a="Aufgrund seiner zentralen Lage direkt am Gasthof und der Hauptstraße von Thelsamar dient Kadrell als Knotenpunkt für Lageberichte aus dem Feld und stellt sicher, dass dringende Meldungen entfernter Späher das Verteidigungsnetzwerk der Siedlung erreichen.",al={"bei kadrell melden","warum bei kadrell melden"}},{q="Mit wem stimmt sich Kadrell ab?",a="Kadrell arbeitet regelmäßig mit anderen Gebirgsjägern im Einsatzgebiet zusammen, darunter Gebirgsjäger Sturmlanze und Gebirgsjäger Rockgar, und verwaltet Aufklärungsberichte sowie Verteidigungsaufträge gegen lokale Bedrohungen.",al={"kadrell kontakte","wen kennt kadrell"}}},fx={fc9aa592={q="Wer ist Gebirgsjäger Kadrell?",a="Gebirgsjäger Kadrell ist ein zwergischer Verteidiger, der in Thelsamar stationiert ist. Als Mitglied der Gebirgsjäger, der engagierten Territorialgarde der Eisenschmiede, beaufsichtigt er die Verteidigung der Region Loch Modan, organisiert lokale Aufklärungsbemühungen und hält Versorgungslinien und Außenposten sicher.",al={"wer ist kadrell","gebirgsjäger kadrell","identität von kadrell"}},["24c7e32d"]={q="Auf wessen Seite steht Gebirgsjäger Kadrell?",a="Kadrell steht fest zum Königreich der Eisenschmiede und zur Allianz. Seine Pflichten stellen ihn in den Dienst von König Magni Bronzebart, wo er mit anderen Gebirgsjägern, Stadtmarschällen und örtlichen Zwergen zusammenarbeitet, um die Grenzen von Khaz Modan gegen eindringende Bedrohungen zu halten.",al={"fraktion von kadrell","ist kadrell allianz","loyalität von kadrell"}},["56ea1ebe"]={q="Warum ist Gebirgsjäger Kadrell in Thelsamar?",a="Kadrell ist direkt gegenüber dem Gasthof Zum Starkbier-Lager stationiert, um als zentraler Kontaktpunkt in Thelsamar zu fungieren. Da die Stadt der Hauptknotenpunkt von Loch Modan ist, ermöglicht ihm dieser Aufenthalt, Berichte von abgelegenen Wachposten zu erhalten und Reisende dorthin zu entsenden, wo Hilfe am dringendsten benötigt wird.",al={"warum ist kadrell in thelsamar","warum ist kadrell hier","posten von kadrell"}},f9923f59={q="Mit wem ist Gebirgsjäger Kadrell verbunden?",a="Kadrell ist eng mit dem Netzwerk der Gebirgsjäger der Eisenschmiede verbunden, die das Tal patrouillieren, darunter Gebirgsjäger Sturmlanze und Gebirgsjäger Rockgar. Er koordiniert sich mit Außenposten-Spähern in ganz Loch Modan, um Informationen und Verstärkungen dorthin zu leiten, wo Grenzstationen unter Druck geraten.",al={"verbindungen von kadrell","mit wem arbeitet kadrell zusammen","beziehungen von kadrell"}}},fp="19,256,23.378.0,22.362.0,39.143.0,37.208.0,50.221.0,33.192.0"}
P.entries["npc:mountaineer-stormpike"] = {n="Gebirgsjäger Sturmlanze",s="Gebirgsjäger Sturmlanze ist ein Gebirgsjäger aus Eisenschmiede, der an der Station Algaz im nördlichen Loch Modan stationiert ist. Er bewacht den Bergpass, der in das Sumpfland führt, und arbeitet unermüdlich daran, wichtige Versorgungswege vor lauernden Troggs und Kobolden zu schützen. Als stolzes Mitglied des Stormpike-Klans gilt seine uneingeschränkte Loyalität Eisenschmiede und der Sicherheit der Zwergenlande.",h="Gebirgsjäger Sturmlanze ist ein Gebirgsjäger aus Eisenschmiede, der an der Station Algaz im nördlichen Loch...",kw={"algaz","dun","kobold","loch","modan","gebirgsjäger","station","stormpike","sumpfland"},ang={["faction:Alliance"]="Die Station Algaz bildet das zentrale Überland-Bindeglied zwischen Eisenschmiede und dem Hafen von Menethil im Sumpfland, wodurch Stormpikes Wachsamkeit für die Logistik der Allianz unverzichtbar ist.",["race:Dwarf"]="Für einen Zwerg aus Eisenschmiede ist es eine ehrenvolle Pflicht, einem Gebirgsjäger wie Stormpike beizustehen, um die Binnengrenzen von Khaz Modan vor plünderndem Ungeziefer zu schützen."},sec={{t="Wächter der Station Algaz",b="An der nördlichen Grenze von Loch Modan gelegen, dient die Station Algaz als entscheidender Kontrollpunkt vor dem gefährlichen Abstieg in das Sumpfland. Gebirgsjäger Sturmlanze ist hier inmitten felsiger Klippen und ständiger Gefahren der Wildnis stationiert. Seine Hauptaufgabe besteht darin, die Verbindungslinie aufrechtzuerhalten und die Straßen für Reisende und Versorgungskonvois offenzuhalten, die Dun Algaz durchqueren."},{t="Der Kampf gegen lokale Bedrohungen",b="Die nördlichen Ausläufer von Loch Modan werden von unerbittlichen Plagen heimgesucht – von Kobolden, die nahegelegene Grabungsstätten befallen, bis hin zu unterirdischen Troggs. Stormpike rekrutiert regelmäßig vorbeiziehende Abenteurer, um diesen Bedrohungen Einhalt zu gebieten. Sein Hauptaugenmerk liegt dabei auf den Kobolden, die in die Silberbachmine eingedrungen sind und ihre schmutzigen Pfoten an die gelagerten Zwergenwerkzeuge der Liga der Forscher gelegt haben."}},faq={{q="Wo finde ich Gebirgsjäger Sturmlanze?",a="Er ist an der Station Algaz stationiert, die im nördlichen Loch Modan an der Bergstraße liegt, die nach Norden in den Pass von Dun Algaz in Richtung des Sumpflands führt.",al={"stormpike standort","wo ist stormpike","gebirgsjäger stormpike ort"}},{q="Wer ist Gebirgsjäger Sturmlanze?",a="Er ist ein Gebirgsjäger aus Eisenschmiede und gehört dem renommierten Stormpike-Klan an. Er dient als Vorpostenwache und Späher mit der Aufgabe, den nördlichen Pass von Loch Modan gegen Gefahren der umliegenden Wildnis zu sichern.",al={"wer ist stormpike","gebirgsjäger stormpike lore","wer ist gebirgsjäger stormpike"}},{q="Mit welchen Bedrohungen hat er an der Station Algaz zu tun?",a="Der Vorposten sieht sich häufigen Übergriffen durch Troggs und Kobolde gegenüber, welche die Hänge und Steinbrüche heimsuchen. Stormpike setzt sich dafür ein, diese Gefahren zu beseitigen, damit Kuriere und Karawanen sicher passieren können.",al={"station algaz gefahren","was greift station algaz an","loch modan norden bedrohungen"}},{q="Was ist der Zweck der Station Algaz?",a="Die Station Algaz dient als Vorposten von Eisenschmiede zur Überwachung der Grenze zwischen Loch Modan und den unwegsamen Tunneln von Dun Algaz. Sie fungiert als Zwischenstation für Gebirgsjäger, die an der Grenze patrouillieren und die Handelsstraße freihalten.",al={"was ist station algaz","station algaz lore","zweck von station algaz"}},{q="Ist er mit der Stormpikegarde im Alteractal verwandt?",a="Er trägt den Namen des angesehenen Stormpike-Klans, eines Zwergengeschlechts, das in ganz Eisenschmiede für seine kühnen Krieger und Prospektoren bekannt ist, auch wenn seine aktuellen Befehle ihn an den Pässen von Loch Modan binden.",al={"alterac stormpike","stormpike klan verbindung","gehört er zur stormpikegarde"}},{q="Welche Aufgaben überträgt Gebirgsjäger Sturmlanze Abenteurern?",a="Er weist Abenteurer an, die Ausrüstung der Liga der Forscher aus der von Kobolden befallenen Silberbachmine zu bergen und seine Bestellung für einen neuen Schild bis zum Zwergenrüstschmied Furen Langbart in Sturmwind zu überbringen.",al={"stormpike quests","gebirgsjäger stormpike aufgaben","schmutzige pfoten quest"}}},fx={["21d9c7b3"]={q="Auf wessen Seite steht Gebirgsjäger Sturmlanze?",a="Gebirgsjäger Sturmlanze ist der Eisenschmiede und dem Bronzebart-Clan zutiefst treu und ein stolzes Mitglied der zwergischen Gebirgsjäger. Er bewacht den Gebirgspass im Namen von König Magni Bronzebart und steht fest zur Allianz, wobei er tiefes Misstrauen gegenüber dem Dunkeleisenclan hegt.",al={"fraktion von gebirgsjäger sturmlanze","wem dient gebirgsjäger sturmlanze","loyalität von sturmlanze"}},["1b65a761"]={q="Was will Gebirgsjäger Sturmlanze?",a="Stationiert entlang der rauen nördlichen Straße, möchte Sturmlanze den Pass vor Troggs, Kobolden und anderen Bedrohungen schützen, die von den Hügeln herabsteigen. Er sucht zuverlässige Kuriere und fähige Kämpfer, um Lieferungen auszuführen, eindringendes Ungeziefer zu beseitigen und die Kommunikation zwischen Station Algaz und dem Rest von Loch Modan aufrechtzuerhalten.",al={"was will sturmlanze","ziel von sturmlanze","zweck von gebirgsjäger sturmlanze"}},["60d9a34d"]={q="Warum ist Gebirgsjäger Sturmlanze hier an Station Algaz?",a="Station Algaz bewacht die wichtige nördliche Route, die Loch Modan in Richtung Sumpfland verbindet. Sturmlanze ist hier stationiert, um den Pass zu beobachten, Patrouillen zu koordinieren und sicherzustellen, dass Vorräte und Berichte sicher zwischen den verstreuten Außenposten in den Bergen und dem umfassenderen Verteidigungsnetzwerk der Eisenschmiede transportiert werden.",al={"warum ist gebirgsjäger sturmlanze hier","warum ist sturmlanze an station algaz","grund für den standort von sturmlanze"}}},fp="21,362,25.379.0,29.350.0,39.151.0,29.207.0,48.204.0,32.221.0,55.217.0,58.211.0"}
P.entries["npc:mountaineer-thalos"] = {n="Gebirgsjäger Thalos",s="Gebirgsjäger Thalos ist ein zwergischer Wachposten, der am Eingang der Eisklamm aufseiten des Coldridgetals stationiert ist. Mit der Bewachung des Weges betraut, warnt er Reisende vor der plötzlichen Troggplage, die den Tunnel verstopft. Abenteurer, die dringende Berichte aus dem Tal überbringen, verlassen sich auf ihn, um den sicheren Weg nach Kharanos gewiesen zu bekommen.",h="Gebirgsjäger Thalos ist ein zwergischer Wachposten, der am Eingang der Eisklamm aufseiten des Coldridgetals...",kw={"coldridgepass","das coldridgetal","dun morogh","gebirgsjäger von eisenschmiede","kharanos","gebirgsjäger thalos","senir weißbart","troggs"},ang={["faction:Alliance"]="Thalos hält die Verbindung entlang dieser lebenswichtigen Gebirgsader aufrecht, die die Verteidigungskräfte des Tals mit dem Oberkommando in Eisenschmiede verbindet.",["race:Dwarf"]="Für junge Zwerge, die die Wiege ihrer Heimat verlassen, ist Thalos die ernste Mahnung, dass die Bedrohung durch die Troggs keine bloße Übung ist, sondern eine Belagerung, die schwer auf den Schwellen von Eisenschmiede lastet.",["race:Gnome"]="Gnome, die aus den Zufluchtsstätten Gnomeregans weiterziehen, treffen auf Thalos, der an der Überlandhauptroute hinab nach Kharanos und Eisenschmiede Wache hält."},sec={{t="Wächter der Eisklamm",b="An der verschneiten Grenze postiert, an der das Coldridgetal in die tieferen Klüfte von Dun Morogh übergeht, dient Gebirgsjäger Thalos als erste Verteidigungslinie für Reisende, die die Ausbildungsstätten der Zwerge verlassen. Die Eisklamm ist zu einem tückischen Engpass geworden, der von feindseligen Troggs überrannt wurde, die sich aus den Tiefen der Erde emporgewühlt haben. Thalos hält in der Kälte Wache, warnt Unvorbereitete zur Umkehr und prüft, ob abgehärtete Boten den Mut aufbringen, sich den Weg in das weitere Königreich freizukämpfen."},{t="Ein Kontrollpunkt für Boten",b="Sobald Grelin Weißbart seinen Bericht über die Bewegungen der Frostmanetrolle im abgelegenen Tal vollendet hat, wird dem Boten, der ihn zu seinem Bruder Senir in Kharanos bringen soll, aufgetragen, vor dem Betreten des Tunnels mit Gebirgsjäger Thalos zu sprechen. Nachdem er sich vergewissert hat, dass ein Abenteurer der befallenen Passage gewachsen ist, weist Thalos den Weg weiter nach Kharanos, wo regionale Befehlshaber die Verteidigung von Dun Morogh koordinieren. Seine wachsame Anwesenheit stellt sicher, dass entscheidende Informationen die militärischen Anführer von Eisenschmiede erreichen, anstatt im Schnee verloren zu gehen."}},faq={{q="Wer ist Gebirgsjäger Thalos?",a="Gebirgsjäger Thalos ist ein Gebirgsjäger von Eisenschmiede, der an der südlichen Öffnung der Eisklamm stationiert ist. Sein Posten bewacht die Schwelle zwischen dem Coldridgetal und den weiteren Weiten von Dun Morogh.",al={"thalos lore","wer ist thalos","gebirgsjäger thalos"}},{q="Warum warnt Gebirgsjäger Thalos Reisende vor dem Weitergehen?",a="Ein verheerender Befall durch Felsenkippentroggs hat die Eisklamm überrannt. Thalos warnt Zivilisten und unerfahrene Kämpfer vor dem Versuch der Durchquerung und lässt nur fähige Boten und gestählte Kämpfer hinein.",al={"warum ist der pass gesperrt","troggs im pass","coldridgepass gefahr"}},{q="Wohin schickt Gebirgsjäger Thalos Abenteurer?",a="Nach Prüfung der dringenden Lageberichte aus dem Coldridgetal weist Thalos Reisende durch den Pass in Richtung Kharanos, der nächstgelegenen Siedlung auf der Straße nach Eisenschmiede.",al={"wohin nach thalos","thalos zielort","nächste stadt"}},{q="Welchen Bericht erhält Thalos von Senir Weißbart?",a="Keinen von Senir selbst. Der Bericht, der Thalos passiert, ist Grelin Weißbarts Bericht über die Bedrohung durch die Frostmanetrolle im Coldridgetal, getragen von einem Boten auf dem Weg zu Grelins Bruder Senir in Kharanos. Thalos warnt den Boten vor den Troggs und schickt ihn weiter durch den Tunnel.",al={"senirs beobachtungen","senirs depesche","was thalos liest"}},{q="Welcher Fraktion gehört Gebirgsjäger Thalos an?",a="Thalos ist ein geschworenes Mitglied der Gebirgsjäger von Eisenschmiede, den abgehärteten Grenzläufern, die im Dienst der Allianz über Dun Moroghs Grenzen, Tunnel und schneeverwehte Gebirgspfade wachen.",al={"thalos fraktion","gehört thalos zu eisenschmiede","gebirgsjäger allianz"}},{q="Ist die Eisklamm unpassierbar, ohne mit Thalos zu sprechen?",a="Der Pass steht jedem offen, der wagemutig genug ist, ihn zu betreten; doch das Gespräch mit Thalos stellt sicher, dass ein Abenteurer entscheidende Aufklärungsberichte nach Kharanos bringt und von den bevorstehenden Gefahren erfährt.",al={"muss man mit thalos sprechen","thalos umgehen"}}},fx={["37207617"]={q="Was will Gebirgsjäger Thalos?",a="Gebirgsjäger Thalos möchte Reisende schützen, indem er sie vor der tückischen Eisklamm warnt. Der Tunnel wurde von feindlichen Troggs überrannt, was den Durchgang für jeden, der nicht vorbereitet ist, gefährlich macht. Wenn er auf Abenteurer mit dringenden Angelegenheiten trifft, drängt er sie dazu, vorsichtig durch den Tunnel zu gehen und den Bericht von Grelin Weißbart sicher zu seinem Bruder Senir in die Zwergenstadt Kharanos zu bringen.",al={"was will thalos","ziel von thalos","zweck von gebirgsjäger thalos"}},ae07b8df={q="Mit wem ist Gebirgsjäger Thalos verbunden?",a="Thalos dient als Wachposten für die Gebirgsjäger der Eisenschmiede und bewacht den Weg, der aus dem Coldridgetal führt. Kuriere, die Grelin Weißbarts Bericht über die Frostmähnen-Trolle zu Grelins Bruder Senir Weißbart in Kharanos bringen, werden zu Thalos geschickt, bevor sie den von Troggs verseuchten Tunnel betreten.",al={"verbündete von thalos","mit wem arbeitet thalos zusammen","thalos und senir weißbart"}}},fp="18,308,26.499.0,22.529.0,26.194.0,49.215.0,47.175.0,54.285.0,47.186.0,56.191.0"}
P.entries["npc:mr-smite"] = {fx={ecfcf591={q="Wer ist Handlanger Pein?",a="Handlanger Pein ist ein furchterregender Tauren-Waffenmeister, der als Erster Offizier an Bord des Juggernauts dient, das tief in den Todesminen versteckt ist. Er arbeitet direkt unter Kapitän Grünhaut, befehligt die Dock-Verteidigung der Bruderschaft der Defias und hält ihre Schurken mit eiserner Faust und einem Arsenal tödlicher Waffen in Schach.",al={"wer ist handlanger pein","identität von handlanger pein","was ist handlanger pein"}},["8cad5068"]={q="Auf wessen Seite steht Handlanger Pein?",a="Obwohl er ein Tauren ist, schuldet Handlanger Pein der Horde oder seiner Verwandtschaft in Kalimdor keine Treue. Er ist fest auf die Bruderschaft der Defias von Edwin van Cleef ausgerichtet und dient als Zweiter Befehlshaber unter ihrem goblinischen Marinekommandanten Kapitän Grünhaut.",al={"fraktion von handlanger pein","für wen arbeitet handlanger pein","ist handlanger pein horde oder defias"}},["1c026e95"]={q="Warum ist Handlanger Pein berühmt oder gefürchtet?",a="Pein wird wegen seiner schieren körperlichen Brutalität und seiner unberechenbaren Kampfbeherrschung gefürchtet. Er ist dafür berüchtigt, mit seinen Opfern zu spielen und sie glauben zu lassen, sie hätten die Oberhand gewonnen, bevor er sie mit einem erschütternden Stampfen betäubt und immer tödlichere Waffen aus seiner Brust zieht, um sie zu erledigen.",al={"warum wird handlanger pein gefürchtet","ruf von handlanger pein","warum ist handlanger pein berühmt"}}}}
P.entries["npc:mull-thunderhorn"] = {fx={["7b9ffdeb"]={q="Auf wessen Seite steht Mull Donnerhorn?",a="Mull steht loyal zu seinem Volk und der Horde und widmet sich den Stämmen, die in Mulgore leben. Als respektiertes Mitglied des Dorfes der Bluthufe wacht er über die Ebenen der Ahnen und folgt dem spirituellen Ruf, seine Verwandten und ihr heiliges Land vor der Verderbnis von außen zu schützen.",al={"mull donnerhorn fraktion","gehört mull zur horde","wem dient mull"}},be00c091={q="Was möchte Mull Donnerhorn?",a="Mull möchte die heiligen Wasserquellen von Mulgore wiederherstellen und reinigen, einschließlich der Quellen von Winterhoof, Donnerhorn und Wildmane. Er sucht vertrauenswürdige Tauren, die traditionelle Totems anfertigen und die lebensnotwendigen Reinigungsriten durchführen, die erforderlich sind, um die üble Verseuchung, die das Lebenselixier des Landes bedroht, aufzuheben.",al={"was möchte mull","mull donnerhorn ziel","warum braucht mull hilfe"}}}}
P.entries["npc:mupsi-shacklefridd"] = {n="Mupsi Kettelfridd",s="Mupsi Kettelfridd ist eine Goblindame, die kurz vor der Hafenstadt Ratschet im Brachland stationiert ist. Sie dient als örtliche Kontaktperson für Reisende, die zerrüttete Beziehungen zum Steamwheedle-Kartell glätten möchten.",h="Mupsi Kettelfridd ist eine Goblindame, die kurz vor der Hafenstadt Ratschet im Brachland stationiert ist.",kw={"brachland","goblin","mupsi","ratschet","ruf","shacklefridd","steamwheedle"},sec={{t="Vor den Toren von Ratschet",b="Mupsi Kettelfridd arbeitet unmittelbar vor Ratschet an den staubigen Küstenstraßen des Brachlands. Das Leben nahe der Hafenstadt ist immer rege, während Wachen des Steamwheedle-Kartells die Umgebung patrouillieren und Händler ein- und ausgehen. Für jene, die bei den Goblins in Ungnade gefallen sind, bietet Mupsi einen Weg zur Versöhnung – vorausgesetzt, Reisende sind bereit, die vom Kartell geforderten Vorräte und Dienste zu erbringen."}},faq={{q="Wer ist Mupsi Kettelfridd?",a="Sie ist ein Goblin, der kurz vor der Siedlung Ratschet im Brachland stationiert ist und Reisenden hilft, die ihren Ruf beim Steamwheedle-Kartell wiederherstellen möchten.",al={"mupsi","wer ist mupsi","ratschet mupsi"}},{q="Wo kann ich sie finden?",a="Mupsi befindet sich direkt vor Ratschet im Brachland, nahe genug an der Hauptsiedlung, dass umherstreifende Hafenwachen und Patrouillen gelegentlich ihren Weg kreuzen.",al={"mupsi standort","wo ist mupsi kettelfridd","mupsi finden"}},{q="Warum sollte man mit Mupsi Kettelfridd sprechen?",a="Reisende, die den Zorn des Steamwheedle-Kartells auf sich gezogen haben – oft durch Zusammenstöße mit Goblins oder das Paktieren mit Piraten –, können mit Mupsi über Vorratsspenden zusammenarbeiten, um ihren Ruf wiederherzustellen.",al={"heilen alter wunden ratschet","ratschet ruf abgabe","mupsi quest"}}},fx={["8798c45f"]={q="Auf wessen Seite steht Mupsi Kettelfridd?",a="Mupsi Kettelfridd gehört zum Steamwheedle Cartel und arbeitet unter der Hafenbehörde von Ratschet. Wie die meisten Goblins in der Siedlung verhält sie sich geschäftlich neutral gegenüber der Allianz und der Horde und stellt Handel, Materialien und Gold über politische Kriegsführung.",al={"mupsi kettelfridd fraktion","für wen arbeitet mupsi","ist mupsi kettelfridd neutral"}},["8b7e7b21"]={q="Warum ist Mupsi Kettelfridd außerhalb von Ratschet stationiert?",a="Sie ist am Rande von Ratschet stationiert, um die Öffentlichkeitsarbeit und Logistik für Reisende zu übernehmen, die sich dem geschäftigen Hafen nähern. Da sie direkt außerhalb der zentralen Docks arbeitet, kann sie Händler, Ausgestoßene und Abenteurer abfangen, die Waren tauschen oder ihre Beziehungen zum Kartell verbessern müssen.",al={"warum ist mupsi hier","mupsi kettelfridd standort grund","warum ist mupsi außerhalb von ratschet"}}},fp="18,219,27.406.0,26.165.0,21.158.0,45.185.0"}
P.entries["npc:mutanus-the-devourer"] = {fx={["1d17d2ec"]={q="Auf wessen Seite steht Mutanus der Verschlinger?",a="Mutanus dient der dunklen, verderbenden Macht, die den Smaragdgrünen Traum infiziert und Naralex in seinem Albtraum gefangen hält. Anstatt seinen eigenen Launen zu folgen oder der einheimischen Tierwelt im Brachland zu dienen, gehorcht er dem Willen des Albtraums selbst. Er wurde in die wache Welt entsandt, einzig um sicherzustellen, dass der Druide schläft und verderbt bleibt.",al={"wer kontrolliert mutanus","mutanus fraktion","mutanus loyalität"}},["93f250d8"]={q="Was möchte Mutanus der Verschlinger?",a="Mutanus existiert, um jeden Versuch zu vereiteln, Naralex aus seinem verdrehten Schlummer zu wecken. Er versucht, jeden zu verschlingen, der versucht, den schlafenden Druiden aus den Klauen des Albtraums zu befreien, um sicherzustellen, dass Naralex hilflos bleibt, während die dunkle Verderbnis in den Höhlen des Wehklagens weiter schwärt.",al={"mutanus ziel","warum kämpft mutanus","was versucht mutanus zu tun"}},c0fe9c52={q="Mit wem ist Mutanus der Verschlinger verbunden?",a="Mutanus ist direkt mit dem Nachtelf-Druiden Naralex verbunden. Er ist kein natürliches Biest aus dem Brachland, sondern eine physische Manifestation, die aus den dunkelsten Ecken von Naralex' eigenem verderbten Geist stammt und die unterbewussten Ängste des Druiden als verdrehter Albtraum in der physischen Welt verkörpert.",al={"mutanus verbindung naralex","mutanus beziehung naralex","mit wem ist mutanus verknüpft"}}}}
P.entries["npc:mux-manascrambler"] = {n="Mux Manamix",s="Mux Manamix ist ein exzentrischer Goblin-Ingenieur, der im Wüstenaußenposten Gadgetzan lebt. Im Gegensatz zu vielen seiner Artgenossen, die sich ausschließlich auf Sprengstoffe oder Bergbauausrüstung konzentrieren, hegt Mux eine sonderbare Faszination für das Übernatürliche und okkulte Energien.",h="Mux Manamix ist ein exzentrischer Goblin-Ingenieur, der im Wüstenaußenposten Gadgetzan lebt.",kw={"ektoplasma","gadgetzan","geist","goblin-ingenieur","manascrambler","mux","tanaris"},ang={["profession:Engineering"]="Mux ist eine Kuriosität unter den Goblin-Tüftlern; er setzt mechanische Zahnräder und Energiezellen ein, um unsichtbare übernatürliche Kräfte einzufangen und zu destillieren, anstatt einfach nur Dinge in die Luft zu jagen."},sec={{t="Ein Tüftler des Unsichtbaren",b="Versteckt in einem Gebäude im Zentrum von Gadgetzan, hinter Driz Plunkbow und seinen ratternden Butcherbots, sitzt Mux Manamix. Während das Steamwheedle-Kartell regen Handel mit Öl, Waffen und Bergungsgut treibt, richtet Mux seinen Erfindergeist auf esoterischere Bestrebungen: das Reich der Geister und übernatürlichen Anomalien. Er nutzt seinen technischen Scharfsinn, um bizarre Apparaturen zu entwerfen, die in der Lage sind, spektrale Überreste aufzuspüren, zu destillieren und mit ihnen zu interagieren, wodurch er grobe Goblin-Handwerkskunst mit den unsichtbaren Welten der Toten verbindet."}},faq={{q="Wo kann ich Mux Manamix finden?",a="Mux hat sein Zuhause in Gadgetzan im nördlichen Tanaris. Ihr findet ihn versteckt in einem Gebäude nahe dem Zentrum des Wüstenhandelsknotenpunkts, direkt hinter Driz Plunkbow und den fleischzerteilenden Butcherbots.",al={"mux standort","wo ist mux","mux manamix karte"}},{q="Welcher Art von Arbeit geht Mux nach?",a="Mux ist ein Ingenieur, der von spektralen und unsichtbaren Kräften besessen ist. Statt gewöhnlicher Sprengungen oder Transportmittel baut er spezialisierte Gerätschaften, die Geister enthüllen, Ektoplasma destillieren und arkane, übernatürliche Kräfte nutzbar machen können.",al={"mux beruf","was verkauft mux","mux forschung"}},{q="Gehört Mux einer Fraktion an?",a="Mux gehört zum Steamwheedle-Kartell, das von Gadgetzan aus operiert. Als unabhängiger Goblin-Handwerker wahrt er strikte geschäftliche Neutralität und ist bereit, Abenteurern sowohl der Horde als auch der Allianz zu helfen.",al={"ist mux horde","ist mux neutral","mux allianz"}}},fp="17,249,24.504.0,35.208.0,30.236.0,29.215.0"}
P.entries["npc:mydrannul"] = {n="Mydrannul",s="Mydrannul ist ein Händler für Gemischtwaren der Nachtelfen, der auf der Terrasse der Krieger in Darnassus stationiert ist. Er versorgt die Schildwachen, Soldaten und Besucher der Hauptstadt, indem er Grundbedarfsgüter, Munition und Verpflegung bereithält.",h="Mydrannul ist ein Händler für Gemischtwaren der Nachtelfen, der auf der Terrasse der Krieger in Darnassus...",kw={"munition","darnassus","gemischtwaren","mydrannul","teldrassil","händler","die terrasse der krieger"},ang={["faction:Alliance"]="Reisende der Allianz, die auf Teldrassil eintreffen, können sich bei Händlern wie Mydrannul auf der Terrasse der Krieger mit einfachen Taschen, Munition und Feldrationen eindecken.",["race:NightElf"]="Für Nachtelfen, die in Darnassus trainieren, bietet Mydrannul grundlegende Alltagsausrüstung und Pfeile, damit die Schildwachen stets gut versorgt sind."},sec={{t="Vorräte der Terrasse der Krieger",b="Inmitten der Militärpavillons und Übungsplätze auf der Terrasse der Krieger versorgt Mydrannul sowohl die Verteidiger von Darnassus als auch reisende Abenteurer mit lebenswichtiger Ausrüstung. Zu seinen Waren gehören die praktischen Alltagsgegenstände, die für das Leben im Feld benötigt werden: Munition für Bogenschützen und Schützen, Wurfwaffen, Feuerstein, Beutel und einfache Rationen. Mit seinem Stand im kriegerischen Viertel der Stadt stellt er sicher, dass es den Schildwachen und Rekruten, die sich auf ihren Dienst auf Teldrassil vorbereiten, nicht an grundlegendem Bedarf mangelt."}},faq={{q="Wo ist Mydrannul zu finden?",a="Mydrannul befindet sich auf der Terrasse der Krieger, dem südöstlichen kriegerischen Viertel von Darnassus auf der Krone von Teldrassil.",al={"mydrannul aufenthaltsort","wo ist mydrannul","mydrannul karte"}},{q="Welche Waren verkauft Mydrannul?",a="Er fungiert als Gemischtwarenhändler und führt Behälter, einfache Rationen, Getränke und Lagerbedarf wie Feuerstein und Zunder sowie Wurfwaffen und Munition wie Pfeile und Kugeln.",al={"mydrannul waren","was verkauft mydrannul","mydrannul händlergegenstände"}},{q="Bietet Mydrannul Quests an?",a="Ja. Neben dem Verkauf von Vorräten schickt Mydrannul Abenteurer zu seiner Freundin Nessa Schattensang, einer Angelbedarfshändlerin in Rut'theran, die ein Paket an die Dunkelküste bringen lassen muss.",al={"mydrannul quest","quests von mydrannul"}}},fx={cca0dfd1={q="Wer ist Mydrannul?",a="Mydrannul ist ein Nachtelf-Händler, der in Darnassus wohnt und auf Die Terrasse der Krieger arbeitet. Er fungiert als Händler für allgemeine Waren in der Hauptstadt der Nachtelfen und versorgt Reisende, Einheimische und Soldaten gleichermaßen mit wichtigen alltäglichen Waren, Proviant und Munition.",al={"wer ist mydrannul","mydrannul identität","mydrannul darnassus"}},["34e3a734"]={q="Auf wessen Seite steht Mydrannul?",a="Mydrannul ist Darnassus und der Allianz fest loyal verbunden. Als Nachtelf, der im Herzen ihres heiligen Weltenbaums lebt, dient er gerne seinem Volk und jedem Abenteurer der Allianz, der durch die Stadt reist.",al={"mydrannul fraktion","mydrannul loyalität","ist mydrannul allianz"}},["6cf1b6fe"]={q="Warum ist Mydrannul hier?",a="Mydrannul ist auf Die Terrasse der Krieger in Darnassus stationiert und unterhält dort einen Laden, um diejenigen auszurüsten, die sich auf Patrouille oder eine weite Reise vorbereiten. Seine Anwesenheit stellt sicher, dass Verteidiger und Wanderer direkten Zugang zu notwendigen Vorräten in der Nähe der Trainingsgelände der Stadt haben.",al={"warum ist mydrannul hier","mydrannul zweck darnassus","was macht mydrannul hier"}},a5485425={q="Was möchte Mydrannul?",a="Mydrannul strebt nach ehrlichem Handel und bietet jedem in Darnassus, der mit ihm handeln möchte, zuverlässige Dinge des täglichen Bedarfs, Nahrung und Munition an.",al={"was möchte mydrannul","mydrannul ziele","mydrannul beweggrund"}}},fp="9,224,33.502.0,29.134.0,31.190.0,32.172.0"}
P.entries["npc:nalpak"] = {fx={a6c930b7={q="Auf wessen Seite steht Nalpak?",a="Nalpak ist ein Schüler von Naralex und dient den Druiden, die versuchen, das Brachland zu heilen. Obwohl er als Taure diejenigen willkommen heißt, die die Höhlen betreten, um ihre Sache zu unterstützen, gilt seine höchste Loyalität der Vision von Naralex und der Wiederherstellung der verderbten unterirdischen Quellen.",al={"nalpak fraktion","wem dient nalpak","gehört nalpak zur horde"}}}}
P.entries["npc:nara-meideros"] = {n="Nara Meideros",s="Nara Meideros ist eine Nachtelfenpriesterin, die im ruhigen Grün des Parks in Sturmwind stationiert ist. Als Mentorin für Akolythen vertritt sie die Lehren von Elune inmitten der Menschenhauptstadt.",h="Nara Meideros ist eine Nachtelfenpriesterin, die im ruhigen Grün des Parks in Sturmwind stationiert ist.",kw={"elune","nara meideros","nachtelfenpriester","priesterlehrer","sturmwind","der park"},ang={["class:Priest"]="Nachtelfenpriestern, die die Östlichen Königreiche durchqueren, bietet Nara Führung und Unterweisung in grundlegenden volksspezifischen Andachten, ohne dass eine beschwerliche Reise zurück nach Kalimdor nötig wäre.",["race:NightElf"]="Fern der Wälder von Eschental und Teldrassil bieten Nara Meideros und der Park ein tröstliches Stück Heimat innerhalb der geschäftigen Steinmauern der Menschenhauptstadt."},sec={{t="Eine Priesterin in Sturmwind",b="Während die meisten Priesterinnen von Elune in Kalimdor unter den Ästen von Teldrassil verweilen, lebt Nara Meideros weit über das Große Meer hinweg in Sturmwind. Sie befindet sich im Park – einer Zuflucht, die von durchreisenden Druiden und Priestern der Nachtelfen gepflegt wird – und leitet junge spirituelle Sucher auf den Pfaden göttlicher Hingabe an. Neben den menschlichen Anhängern des Heiligen Lichts auf dem Kathedralenplatz bietet Nara jenen Nachtelfen, die die Östlichen Königreiche bereisen oder dort leben, eine vertraute Verbindung zur Gnade der Mondgöttin."}},faq={{q="Wo kann ich Nara Meideros finden?",a="Nara Meideros befindet sich im Parkviertel von Sturmwind, umgeben von Mondbrunnen und hoch aufragenden Bäumen, die reisende Nachtelfen an ihre Heimat erinnern.",al={"nara meideros aufenthaltsort","wo ist nara meideros","park priesterlehrer"}},{q="Welche Rolle erfüllt Nara Meideros?",a="Sie ist eine Priesterlehrerin, die Novizen und heranwachsenden Priestern zur Seite steht, und sie schickt menschliche Priester zur Kathedrale des Lichts, um Andachtszauber wie Verzweifeltes Gebet zu erlernen.",al={"was tut nara","nara meideros funktion","wer ist nara meideros"}},{q="Warum hält sich eine Nachtelfenpriesterin in Sturmwind auf?",a="Da die Bande zwischen den Nachtelfen von Darnassus und der Großen Allianz enger werden, pflegen Gesandte, Druiden und Priester der Nachtelfen eine aktive Präsenz im Park, um ihren Artverwandten zu helfen und ihre spirituellen Traditionen zu vertreten.",al={"warum ist sie in sturmwind","nachtelf in sturmwind"}}},fx={["07f550b7"]={q="Wer ist Nara Meideros?",a="Nara Meideros ist eine Nachtelf-Priesterin des Mondes, die der Schwesternschaft von Elune dient. Sie ist bei den sterblichen Verbündeten der Allianz stationiert und leitet hingebungsvolle Akolythen in den spirituellen Traditionen und heiligen Disziplinen ihres Volkes an.",al={"wer ist nara meideros","wer ist nara","nara meideros lore"}},["6f64ae70"]={q="Auf wessen Seite steht Nara Meideros?",a="Sie ist den Kaldorei und der Allianz vollkommen loyal, fungiert als Botschafterin des Glaubens der Nachtelfen und bietet Priestern Führung, die nach Gemeinschaft mit dem göttlichen Licht und den Lehren von Elune suchen.",al={"nara meideros fraktion","wem dient nara meideros","nara meideros allianz"}}},fp="13,205,24.491.0,31.148.0,35.176.0,51.220.0"}
P.entries["npc:narain-soothfancy"] = {n="Narain Pfauentraum",s="Narain Pfauentraum ist ein exzentrischer Gnom, der in einer abgelegenen Strandhütte unmittelbar nördlich des Dampfdruckpiers in Tanaris haust. Während er sich selbst lautstark als Meister-Wahrsager anpreist, der die Zukunft weissagen kann, halten diejenigen, die ihn kennen, seine übersinnlichen Talente im Vergleich zu seinem wahrhaftigen Ingenieursgenie für eine reine Farce.",h="Narain Pfauentraum ist ein exzentrischer Gnom, der in einer abgelegenen Strandhütte unmittelbar nördlich des...",kw={"azuregos","ingenieur","narain","pfauentraum","wahrsager","dampfdruckpier","tanaris"},ang={["profession:Engineering"]="Ingenieure werden Narains wilde Erfindungen faszinierend finden, selbst wenn er lieber so tut, als seien seine mechanischen Triumphe in Wahrheit mystische Visionen.",["race:Gnome"]="Narain verkörpert das exzentrische Extrem gnomischen Erfindergeists, indem er brillante technologische Problemlösungen mit bizarren, obsessiven Hobbys verbindet."},sec={{t="Übersinnliche Visionen und praktische Ingenieurskunst",b="An der Ostküste von Tanaris direkt nördlich der Goblindocks lebt Narain Pfauentraum als pensionierter Ingenieur, der zum selbsternannten Meister-Wahrsager geworden ist. Er begrüßt Besucher routinemäßig, indem er ungeöffnete Umschläge an seine Stirn presst oder völlig abwegige Vermutungen über ihr Anliegen anstellt – wie etwa die Frage, ob sie auf der Suche nach dem legendären Aschenbringer eingetroffen seien. Trotz seines theatralischen Schwindels verfügt Narain über tiefes technisches Wissen. Selbst uralte Wesen wie der blaue Drache Azuregos bemerken, dass Narain zwar ein furchtbares Medium ist, seine Ingenieursbegabung jedoch unbestreitbar brillant ist. Ein Handbuch mit dem Titel „Soothsaying for Dummies“ liegt in der Nähe."},{t="Ein Absturz an der Küste",b="Bevor er sich beim Dampfdruckpier niederließ, erlitt Narain weit im Süden entlang des Landendestrands einen katastrophalen Absturz mit einer Flugmaschine. Er überlebte das Wrack dank einer unerwarteten Rettung, doch seine exzentrische Persönlichkeit und seine sonderbaren Obsessionen haben ihn an den Wüstengestaden isoliert gehalten, wo er an arkan-naher Technologie tüftelt und dubiose Prophezeiungen an jeden Vorbeigehenden feilbietet."}},faq={{q="Wer ist Narain Pfauentraum?",a="Narain Pfauentraum ist ein pensionierter Gnomeningenieur, der in Tanaris nördlich des Dampfdruckpiers wohnt. Er preist sich selbst als Meister-Wahrsager an, wenngleich seine Weissagungen bekanntermaßen ungenau sind.",al={"narain pfauentraum lore","wer ist narain","hellseherischer gnom tanaris"}},{q="Ist Narain tatsächlich ein Hellseher?",a="Nein. Mächtige Bekannte wie der Drache Azuregos beschreiben ihn offen als schreckliches Medium. Sein wahres Talent liegt ungeachtet seiner theatralischen Versuche des Gedankenlesens in meisterhafter Ingenieurskunst und Tüftelei.",al={"kann narain die zukunft sehen","ist narain hellseherisch","pfauentraum wahrsager"}},{q="Was ist das Buch „Soothsaying for Dummies“ neben ihm?",a="Es ist ein Handbuch, das in Narains Hütte aufbewahrt wird und mit spezialisierten Handwerken verknüpft ist. Narain verweist Reisende, die solches Wissen suchen, auf das Buch.",al={"soothsaying for dummies","narain berufsbuch"}},{q="Woher kennt Narain Azuregos?",a="Narain ist ein alter Bekannter des blauen Drachen Azuregos, der durch Azshara streift. Trotz Narains bizarren Gehabes respektiert der Drache seine unübertroffenen Fähigkeiten im Ingenieurswesen und Handwerk.",al={"narain und azuregos","blauer drache narain"}}},fp="17,315,37.654.0,17.384.0,25.187.0,29.209.0,54.138.0,30.187.0"}
P.entries["npc:naralex"] = {fx={ec55d9d1={q="Auf wessen Seite steht Naralex?",a="Naralex gehört zum Zirkel des Cenarius, was ihn gegenüber der Allianz und der Horde neutral macht. Seine Loyalität gilt dem Gleichgewicht der Natur und nicht den politischen Streitigkeiten von Kalimdor. Leider hat sein gefangener Geist völlig die Kontrolle verloren, sodass sein schlafender Körper von verdrehten ehemaligen Akolythen bewacht wird, die jeden angreifen, der eintritt.",al={"ist naralex allianz oder horde","naralex fraktion","wem dient naralex"}}}}
P.entries["npc:natalia-mar-alith"] = {n="Natalia Mar'alith",s="Herrin Natalia Mar'alith ist eine Nachtelfenpriesterin und Forscherin des Zirkels des Cenarius, die tief in den Silithidenbauten vom Bau des Regalschwarms verschollen ist. Sie wagte sich an der Seite ihres Mannes, Kommandant Mar'alith, in die Ödnis von Silithus, bevor sie zu einer Expedition in die Bauten aufbrach.",h="Herrin Natalia Mar'alith ist eine Nachtelfenpriesterin und Forscherin des Zirkels des Cenarius, die tief in...",kw={"brann bronzebeard","burg cenarius","bau des regalschwarms","in den schlund des wahnsinns","mar'alith","maralith","natalia","silithus"},ang={["faction:Alliance"]="Rutgar Glyphenschnitzer und Frankal Stonebridge in Bronzebeards Lager teilen die finsteren Einzelheiten ihres Falls mit Forschern der Allianz, die Branns Expedition nachreisen.",["race:NightElf"]="Natalias tragischer Fall ist eine düstere Mahnung an die Kaldorei, dass selbst ihre hingebungsvollsten Priesterinnen den uralten Schrecken wehrlos gegenüberstehen, die unter dem Sand von Silithus begraben liegen."},sec={{t="Ein tragischer Abstieg",b="Als der Zirkel des Cenarius seinen Außenposten auf Burg Cenarius errichtete, um das Erwachen des Sandes zu überwachen, begleitete Natalia ihren Ehemann, Kommandant Mar'alith, in die Einöde. Begierig darauf, das Geheimnis hinter dem Wiedererstarken der Silithiden und den uralten Ruinen der Qiraji zu lüften, schloss sie sich einer Erkundungsgruppe unter der Leitung des berühmten Forschers Brann Bronzebeard an, die von den Zwergenforschern Rutgar Glyphenschnitzer und Frankal Stonebridge begleitet wurde."},{t="Der Kristall im Bau des Regalschwarms",b="Die Expedition verfolgte merkwürdige Ausstrahlungen bis in die südlichen Bereiche vom Bau des Regalschwarms. Tief im Herzen des Baus entdeckten sie einen kolossalen Kristall, der mit uralten Qiraji-Glyphen versehen war. Angezogen von seiner flüsternden Resonanz beugte sich Natalia vor, um die Zeichen genauer zu untersuchen. Die dunkle Magie in seinem Inneren überwältigte ihren Geist innerhalb von Augenblicken, raubte ihr den Verstand und unterwarf ihren Willen C'Thun. Ihre Zwergenbegleiter brachten sie hinaus zu Burg Cenarius, wo die Druiden sie aufweckten, doch Wochen später stürmte sie besessen zurück in ihr Lager, verlangte eine Rückkehr in den Bau und musste vertrieben werden. Heute ist sie eine fanatische Beschützerin des schrecklichen Meisters des Baus."},{t="Die Verzweiflung des Kommandanten",b="Zurück auf Burg Cenarius klammert sich Kommandant Mar'alith verzweifelt an die Hoffnung, dass seine Frau gerettet werden kann, und weigert sich zu akzeptieren, dass ihr Geist unwiderruflich zerstört ist. Doch jeder, der den Bau des Regalschwarms betritt, findet keine Gefangene vor, die gerettet werden muss, sondern eine skrupellose Dienerin des Wahnsinns, die geweihte Priestermagie führt, welche von der Bosheit des Alten Gottes verzerrt wurde."}},faq={{q="Wer ist Natalia Mar'alith?",a="Natalia Mar'alith ist eine Nachtelfenpriesterin des Zirkels des Cenarius und die Frau von Kommandant Mar'alith. Sie schloss sich Brann Bronzebeards Erkundungsexpedition in den Bau des Regalschwarms an, um das Wiedererstarken der Silithiden zu erforschen, wo sie dunkler, uralter Magie zum Opfer fiel.",al={"natalia maralith","wer ist natalia","kommandant maraliths frau"}},{q="Wo kann ich Natalia Mar'alith finden?",a="Sie befindet sich tief in den insektoiden Tunneln vom Bau des Regalschwarms im südlichen Silithus, wo sie vor einem leuchtenden, mit Glyphen bedeckten Kristall Wache hält.",al={"natalia standort","wo ist natalia","bau des regalschwarms priesterin"}},{q="Warum ist Natalia Abenteurern gegenüber feindselig gestimmt?",a="Während sie einen Qiraji-Kristall untersuchte, wurde Natalia von den Einflüsterungen des Alten Gottes C'Thun vollkommen verdorben und geistig gebrochen. Sie verteidigt den Kristall nun fanatisch gegen jeden, der den Bau betritt.",al={"warum greift natalia an","warum ist natalia verrückt","natalia manipuliert"}},{q="Wer war bei Natalia, als sie verschwand?",a="Sie wagte sich mit Brann Bronzebeard, Rutgar Glyphenschnitzer und Frankal Stonebridge in den Bau des Regalschwarms. Rutgar und Frankal überlebten die Tortur und zogen sich nach Bronzebeards Lager im südlichen Silithus zurück, um von den Geschehnissen zu berichten.",al={"natalia expedition","wer begleitete natalia","brann und natalia"}},{q="Warum ist sie im Kampf so gefährlich?",a="Natalia verfügt nach wie vor über ihre gewaltigen Priesterkräfte, zerstreut Angreifer unentwegt mit Psychischem Schrei und stellt ihre Kraft durch nahezu kostenlose Große Heilungen wieder her, was es sehr schwer macht, sie ohne ständige Unterbrechungen zu bezwingen.",al={"natalia kampf","natalia besiegen","natalia heilung"}}},fp="17,280,16.427.0,25.634.1,23.333.1,25.255.1,35.139.0,38.198.1,43.219.0,34.232.0"}
P.entries["npc:nathanos-blightcaller"] = {n="Nathanos Pestrufer",s="Nathanos Pestrufer, einst Nathanos Marris, steht auf seinem ruinierten Gehöft in den Östlichen Pestländern als tödlicher Champion von Königin Sylvanas Windläufer. Zu Lebzeiten war er der erste und einzige menschliche Waldläuferlord von Quel'Thalas, und im Untod bildet er Jäger der Verlassenen aus, während er die östliche Grenze mit beißender Verachtung für jeden bewacht, der sich nähert.",h="Nathanos Pestrufer, einst Nathanos Marris, steht auf seinem ruinierten Gehöft in den Östlichen Pestländern...",kw={"blightcaller","weltenwanderer","jägerlehrer","marris","marris' siedlung","nathanos","pestländer","sylvanas"},ang={["class:Hunter"]="Nathanos ist der ranghöchste Jägerlehrer der Verlassenen und bringt die anspruchsvollen, legendären Scharfschützentechniken der Weltenwanderer von Quel'Thalas zu den Untoten von Lordaeron.",["faction:Alliance"]="Einen hochdekorierten Helden von Lordaeron und gefeierten Weltenwanderer unter dem Banner der Verlassenen kämpfen zu sehen, ist für Sturmwind eine schallende Beleidigung und ein tödliches taktisches Problem.",["faction:Horde"]="Nathanos liefert der Horde in den Pestländern entscheidende taktische Anleitung und Jägerausbildung, auch wenn er Besucher mit beißender Geringschätzung behandelt.",["race:Undead"]="Als Champion der Dunklen Fürstin verkörpert Nathanos die bittere Widerstandskraft der Verlassenen, wenngleich er wenig Geduld für Inkompetenz unter Seinesgleichen aufbringt."},sec={{t="Der einzige menschliche Weltenwanderer",b="Vor dem Dritten Krieg war Nathanos Marris ein außergewöhnlicher Scharfschütze und taktisches Genie aus den ländlichen Randgebieten Lordaerons. Von den Hochelfen von Quel'Thalas ausgebildet und Sylvanas Windläufer nahestehend, wurde er der einzige Mensch, der je den prestigeträchtigen Rang eines Waldläuferlords erlangte. Seine Heimat blieb das Familienanwesen in Lordaeron, Marris' Siedlung."},{t="Der Fall und die Wiedergeburt",b="Als Prinz Arthas und die Geißel nach dem Ausmisten von Stratholme durch Lordaeron fegten, verschlang die Seuche das Königreich. Nathanos leistete auf seinem Anwesen verzweifelten Widerstand, fiel jedoch der monströsen Monstrosität Ramstein der Verschlinger zum Opfer. Als geistloser untoter Knecht auferweckt, zog er durch die verseuchten Felder und tötete im Namen des Lichkönigs. Nachdem Sylvanas den mentalen Griff der Geißel gebrochen und die Verlassenen in Unterstadt gegründet hatte, holte sie ihn – so wie er irgendwie gewusst hatte, dass sie es tun würde – und riss sein Bewusstsein aus dem Willen des Lichkönigs frei, womit seine taktische Brillanz und feurige Loyalität an ihre Seite zurückkehrten."},{t="Champion der Bansheekönigin",b="Nathanos nahm den Beinamen Blightcaller an und schlug seinen dauerhaften Wohnsitz auf der verfallenen Marris' Siedlung auf. Er dient als Sylvanas' Champion, Jägerlehrer und regionaler Spionagemeister in den umkämpften Östlichen Pestländern, beschützt von fauligen Pesthunden. Der Geheimdienst der Allianz hat sein Überleben mit tiefer Beunruhigung festgestellt; Hochlord Bolvar Fordragon betrachtet ein Meistertaktiker von Nathanos' Kaliber an der Spitze untoter Streitkräfte als unerträgliche Bedrohung für das Überleben der Menschen und entsendet Stoßtrupps, um den gefallenen Waldläuferlord zu ermorden."}},faq={{q="Wer ist Nathanos Pestrufer?",a="Nathanos Pestrufer war Nathanos Marris, ein renommierter menschlicher Scharfschütze und der einzige Nichtelf, der je zum Waldläuferlord von Quel'Thalas ernannt wurde. Nach seinem Tod und seiner Wiederauferstehung während des Dritten Krieges befreite Sylvanas seinen Geist von der Geißel. Er dient nun als ihr Champion und Jägerlehrer auf seinem angestammten Anwesen in den Östlichen Pestländern.",al={"wer ist nathanos","nathanos lore","wer ist der typ bei marris siedlung"}},{q="Warum befindet sich Nathanos in Marris' Siedlung?",a="Marris' Siedlung war zu Lebzeiten Nathanos' Heimat, und dort fiel er bei der Verteidigung Lordaerons. Im Untod beschloss er, auf sein ruiniertes Anwesen zurückzukehren und es in einen Außenposten zu verwandeln, um Jäger der Verlassenen auszubilden und die Bewegungen der Allianz sowie der Geißel zu überwachen.",al={"wo ist nathanos","warum ist nathanos in den pestländern","marris siedlung nathanos"}},{q="Wie wurde Nathanos untot?",a="Nathanos wurde während des Dritten Krieges auf seinem Gehöft von der Monstrosität der Geißel, Ramstein der Verschlinger, getötet. Er erhob sich als gehorsamer, geistloser Knecht des Lichkönigs, bis Sylvanas ihn holte und seinen Geist befreite, damit er sich den Verlassenen anschließen konnte.",al={"wie starb nathanos","wer tötete nathanos","nathanos tod"}},{q="Warum will die Allianz ihn töten?",a="Die Führung der Allianz in Sturmwind fand heraus, dass Nathanos Marris – einer der größten militärischen Köpfe und taktischen Genies der Allianz – nicht endgültig umkam, sondern sich stattdessen den Verlassenen anschloss. Da Hochlord Bolvar Fordragon seine taktische Brillanz als immense Gefahr ansieht, befiehlt er seine Beseitigung.",al={"warum nathanos töten","allianz quest nathanos","ordnung muss wiederhergestellt werden"}},{q="In welcher Beziehung steht er zu Sylvanas?",a="Nathanos stand Sylvanas bereits im Leben nahe, als die Elfen von Quel'Thalas ihn zu ihrem einzigen menschlichen Waldläuferlord machten, und er ist nun ihr Champion. Im Untod bleibt seine Loyalität zur Bansheekönigin absolut und unerschütterlich.",al={"sylvanas und nathanos","liebte sylvanas nathanos","nathanos sylvanas romanze"}},{q="Wer sind die Hunde, die neben ihm stehen?",a="Es sind bösartige Pesthunde, die Nathanos selbst abgerichtet hat. An seiner Seite gehalten, um die Ruinen von Marris' Siedlung zu bewachen, greifen sie jeden Eindringling an, der töricht genug ist, sein Territorium zu betreten.",al={"nathanos hunde","marris siedlung hunde","blightcaller begleiter"}}},fp="21,344,25.354.0,20.606.0,29.515.1,29.329.0,36.251.0,34.244.0,39.301.0,39.214.0,37.188.0"}
P.entries["npc:nida"] = {n="Nida",s="Nida ist ein junges Menschenmädchen, das in der am See gelegenen Stadt Seenhain im Rotkammgebirge lebt. Verzweifelt, nachdem ihr ein geschätztes Geschenk ihres Vaters in den See gefallen ist, verbringt sie ihre Zeit weinend an den Docks der Stadt.",h="Nida ist ein junges Menschenmädchen, das in der am See gelegenen Stadt Seenhain im Rotkammgebirge lebt.",kw={"kind","hilary","der immerruhsee","seenhain","halskette","nida","rotkammgebirge","shawn"},ang={["faction:Alliance"]="Selbst während das Rotkammgebirge mit größeren regionalen Krisen ringt, bringt die Hilfe für Nida den geplagten Bewohnern von Seenhain ein kleines Stück Wärme und Unschuld zurück."},sec={{t="Das verlorene Andenken eines Kindes",b="Inmitten der wachsenden Bedrohung durch Gnollinvasionen und Kriegstrupps der Schwarzfelsorcs, die Seenhain bedrängen, stehen die Kinder der Stadt dennoch vor alltäglichen Kindheitssorgen. Nida ließ versehentlich eine Halskette, die ihr Vater ihr geschenkt hatte, in die trüben Gewässer des Immerruhsees fallen. Voller Angst, ihr Vater könnte wütend auf sie sein, wartet das verzweifelte Mädchen unter Tränen am Pier der Stadt und hofft, dass jemand mutig genug ist, in den See abzutauchen, um sie wiederzubeschaffen."}},faq={{q="Wer ist Nida?",a="Nida ist ein junges Menschenkind, das in Seenhain im Rotkammgebirge wohnt und oft weinend in der Nähe der Docks anzutreffen ist.",al={"wer ist nida","nida seenhain","weinendes mädchen seenhain"}},{q="Warum weint Nida?",a="Nida hat eine wertvolle Halskette verloren, die ihr Vater für sie gekauft hatte. Sie glitt in die Gewässer des Immerruhsees, und sie fürchtet den Zorn ihres Vaters, sobald er bemerkt, dass sie fehlt.",al={"warum weint sie","warum ist nida traurig","nida weinen geräusch"}},{q="Wer versucht, ihr beim Finden der Halskette zu helfen?",a="Ihr Spielkamerad Shawn bemerkt ihren Kummer und bittet vorbeikommende Abenteurer, in den Immerruhsee zu tauchen, um die versunkene Halskette für sie zu bergen.",al={"wer hilft nida","nida freund","wer gibt nida quest"}},{q="Wo befindet sich die verlorene Halskette?",a="Die Halskette liegt unter der Oberfläche des Immerruhsees, versunken nahe den Docks der Stadt, wo Nida sie fallen ließ.",al={"wo ist nidas halskette","fundort halskette der immerruhsee"}}},fx={["7ae322dc"]={q="Auf wessen Seite steht Nida?",a="Nida ist ein junges Menschenkind, das friedlich unter dem Schutz der Allianz in Seenhain lebt. Sie beteiligt sich nicht an Politik oder Soldatenleben, sondern lebt einfach ihre Kindheit unter den Einheimischen am Der Immerruhsee.",al={"nida fraktion","ist nida allianz","auf wessen seite steht nida"}},["3c3e0c86"]={q="Warum ist Nida in Seenhain?",a="Seenhain ist Nidas Zuhause. Sie lebt in der Siedlung am See bei ihrer Familie und verbringt ihre Tage damit, zusammen mit ihrem Jugendfreund Shawn an den Docks und am Ufer zu spielen.",al={"warum ist nida hier","warum ist nida in seenhain","was macht nida hier"}}},fp="6,221,23.444.0,14.126.0,21.185.0,44.137.0,35.114.0"}
P.entries["npc:nikova-raskol"] = {fx={dc3813b4={q="Auf wessen Seite steht Nikova Raskol?",a="Nikova Raskol steht fest zu Sturmwind und der Allianz. Als ältere Bewohnerin, die im Herzen der Hauptstadt lebt, richtet sich ihr Hass gänzlich gegen The Defias Brotherhood, die sie für den Mord an ihrer Familie verantwortlich macht.",al={"ist nikova allianz","nikova raskol fraktion","auf wessen seite steht nikova"}},cb2616e5={q="Warum ist Nikova Raskol in Die Altstadt?",a="Nikova durchstreift die steinernen Straßen von Die Altstadt, weil Sturmwind ihr Zuhause ist. Verzehrt von Kummer und einem Durst nach Gerechtigkeit, schreitet sie durch die Stadt auf der Suche nach fähigen Helden, die gegen die kriminellen Verschwörer zurückschlagen, die unter den Straßen gefangen gehalten werden.",al={"warum ist nikova hier","warum ist nikova raskol in sturmwind","nikova raskol altstadt grund"}}}}
P.entries["npc:nissa-firestone"] = {n="Nissa Feuerstein",s="Nissa Feuerstein ist eine Zwergenärztin, die über dem geschäftigen Treiben der Großen Schmiede in Eisenschmiede stationiert ist. Sie dient als Ausbilderin in Feldmedizin und bringt Reisenden sowie Soldaten bei, wie man Wunden versorgt und Traumata verbindet.",h="Nissa Feuerstein ist eine Zwergenärztin, die über dem geschäftigen Treiben der Großen Schmiede in...",kw={"traumachirurg der allianz","verbände","erste hilfe","die große schmiede","heiler","heiler von eisenschmiede","nissa feuerstein"},ang={["faction:Alliance"]="Jeder Abenteurer der Allianz, der Khaz Modan durchquert, verlässt sich auf Ausbilder wie Nissa, um grundlegende Überlebensfähigkeiten zu erlernen, ohne auf göttliche oder arkane Magie angewiesen zu sein.",["race:Dwarf"]="Für Zwerge, die von Scharmützeln mit Troggs oder Frosttrollen zurückkehren, verkörpert Nissa den praktischen, sachlichen Ansatz der medizinischen Tradition von Eisenschmiede."},sec={{t="Eine Heilerin über den Ambossen",b="Inmitten des klirrenden Metalls und der glühenden Hitze der Großen Schmiede praktiziert Nissa Feuerstein im oberen Stockwerk des Ladens Heiler von Eisenschmiede. Während Zwergenkrieger für ihre Zähigkeit berühmt sind, reißt selbst steinhartes Fleisch vor Klinge und Klaue auf. Nissa sorgt dafür, dass diejenigen, die in den Schnee von Dun Morogh oder darüber hinaus aufbrechen, wissen, wie sie sich selbst und ihre Verbündeten mit einfachen Verbänden und Feldkompressen am Leben halten."},{t="Triage und fortgeschrittene Traumata",b="Bei Feldsanitätern, die die Grundlagen von Stoff und Verbandsmull gemeistert haben, erkennt Nissa, wenn ein Schüler ihrer Klinik entwachsen ist. Wenn Anwender die Grenzen dessen erreichen, was sie lehren kann, verweist sie sie an spezialisierte Triage-Offiziere in entlegenen Vorposten und schickt fähige Heiler dorthin, wo die Verluste der Allianz am schwersten sind."}},faq={{q="Wer ist Nissa Feuerstein?",a="Nissa Feuerstein ist eine Zwergen-Lehrerin für Erste Hilfe, die im Laden Heiler von Eisenschmiede am südlichen Rand der Großen Schmiede arbeitet.",al={"wer ist nissa feuerstein","nissa feuerstein rolle","eisenschmiede erste hilfe lehrer"}},{q="Wo kann ich Nissa Feuerstein finden?",a="Sie befindet sich im oberen Stockwerk des Ladens Heiler von Eisenschmiede, der am südlichen Rand des Rings der Großen Schmiede in Eisenschmiede liegt.",al={"nissa feuerstein standort","wo ist nissa","heiler von eisenschmiede standort"}},{q="Was bringt Nissa Feuerstein einem bei?",a="Sie unterweist Allianz-Abenteurer in der Kunst der Ersten Hilfe und lehrt das Handwerk, Verbände und Gegengifte herzustellen, um im Feld erlittene Verletzungen zu behandeln.",al={"was lehrt nissa","erste hilfe eisenschmiede","verbände lernen eisenschmiede"}},{q="Kann Nissa Triage auf Meisterniveau lehren?",a="Nein. Sobald ein Sanitäter eine fortgeschrittene Fertigkeit erreicht hat, verweist Nissa ihn über den Auftrag Traumachirurg der Allianz an andere Stellen und schickt ihn zu erfahrenen Feldchirurgen, die nahe aktiven Kriegsgebieten stationiert sind.",al={"traumachirurg der allianz quest","meister erste hilfe eisenschmiede","erste hilfe über 225"}}},fx={f16b91f7={q="Auf wessen Seite steht Nissa Feuerstein?",a="Nissa Feuerstein steht fest zu Eisenschmiede und der Allianz. Hoch in der Hauptstadt stationiert, widmet sie ihr medizinisches Wissen dazu, die Verteidiger von Eisenschmiede und Reisende der Allianz durch Verbände und Notfallversorgung am Leben zu erhalten.",al={"nissa feuerstein fraktion","ist nissa allianz","wem dient nissa"}},bc93403c={q="Warum ist Nissa Feuerstein in Eisenschmiede?",a="Nissa arbeitet im Geschäft Heiler von Eisenschmiede oberhalb von Die Große Schmiede. Von dieser zentralen Position innerhalb der Zwergenhauptstadt aus kann sie die Kranken und Verletzten der Stadt versorgen, während sie abenteuerlustige Feldsanitäter darin ausbildet, Wunden zu verbinden und Blutungen zu stillen, bevor sie in die Schlacht ziehen.",al={"warum ist nissa hier","nissa feuerstein standort grund","was brachte nissa nach eisenschmiede"}},["2ef2db38"]={q="Was möchte Nissa Feuerstein?",a="Als Heilerin und Ausbilderin ist es Nissas vorrangiges Ziel, sicherzustellen, dass Kämpfer der Allianz wissen, wie sie sich im Feld selbst versorgen können. Wenn vielversprechende Sanitäter ihrer Ausbildung entwachsen, verweist sie sie an fortgeschrittene Feldchirurgen, die Triage in Kriegszeiten lehren können.",al={"was möchte nissa","nissa feuerstein ziele","nissa feuerstein motiv"}}},fp="15,214,25.427.0,26.329.0,23.148.0,33.138.0,32.156.0,36.184.0"}
P.entries["npc:nogg"] = {fx={["81166680"]={q="Wer ist Nogg?",a="Nogg ist ein unternehmungslustiger Goblin-Ingenieur, der Nogg's Machine Shop im Tal der Ehre in Orgrimmar betreibt. Wie viele Goblins, die in der Hauptstadt der Horde leben, bietet er seine mechanischen Dienste Tüftlern und Abenteurern gleichermaßen an und behält dabei einen geschäftstüchtigen und praktischen Blick für faszinierende Apparaturen und technologische Fundstücke.",al={"wer ist nogg","nogg hintergrundgeschichte","nogg identität"}},c0d235dc={q="Was möchte Nogg?",a="Nogg möchte innovative Ingenieurteile, kuriose mechanische Artefakte und lukrative Gelegenheiten. Zu seinen Interessen gehört es, komplizierte Ringe zu untersuchen, die von Abenteurern geborgen wurden, und das technologische Chaos von Konflikten wie den Rig-Kriegen in Gnomeregan im Auge zu behalten, um die Geschäfte seines Ladens anzukurbeln.",al={"was möchte nogg","nogg ziele","nogg quests zweck"}},["0ba8fca5"]={q="Warum ist Nogg in Orgrimmar?",a="Nogg arbeitet vom Tal der Ehre in Orgrimmar aus, wo die geschäftige Hauptstadt einen stetigen Strom an Kundschaft, Rohmaterialien und abenteuerlustigen Mercenaries bietet, die bereit sind, gefährliche Besorgungen zu erledigen. Sein Maschinenladen floriert dank der ständigen Nachfrage nach ingenieurtechnischer Expertise innerhalb der Horde.",al={"warum ist nogg hier","warum ist nogg in orgrimmar","nogg standort grund"}}}}
P.entries["npc:nori-pridedrift"] = {n="Nori Stolzmut",s="Nori Stolzmut ist ein geschäftstüchtiger Zwerg, der sein kochend heißes Scalding Mornbrew im verschneiten Coldridgetal feilbietet. Er verdient seinen Lebensunterhalt damit, der Kälte zu trotzen und frierende Gebirgsjäger mit ihrem morgendlichen Wachmacher zu versorgen, wobei er oft flinke Rekruten anheuert, um Lieferungen auszuführen, solange das Getränk noch dampft.",h="Nori Stolzmut ist ein geschäftstüchtiger Zwerg, der sein kochend heißes Scalding Mornbrew im verschneiten...",kw={"gebräu","das coldridgetal","dun morogh","zwerg","mornbrew-becher","nori stolzmut","scalding mornbrew"},ang={["profession:Cooking"]="Kulinarische Abenteurer in Dun Morogh schätzen Noris Hingabe, sein Spezialgetränk trotz der eisigen Umgebungsluft kochend heiß zu servieren.",["race:Dwarf"]="Jeder Zwerg versteht den lebenswichtigen Trost eines kräftigen Getränks bei eiskaltem Wetter, was Noris dampfendes Mornbrew zu einem willkommenen Anblick auf den Gebirgswachposten macht."},sec={{t="Ein dampfender Becher im Schnee",b="Das Leben im Coldridgetal ist hart und bitterkalt, und nichts vertreibt die Kälte so gut wie ein Schluck Scalding Mornbrew. Nori Stolzmut hat sich eine Existenz aufgebaut, indem er dieses heiße, kaffeeähnliche Morgengebräu braut und über die gefrorenen Schneeverwehungen verteilt. Da das Gebräu noch brühend heiß getrunken werden muss, um es vollends genießen zu können, ist die Auslieferung ein Wettlauf gegen die Elemente. Nori rekrutiert regelmäßig flinke Kuriere, die frische Portionen zu den frierenden Wachposten bringen, bevor die Bergluft dem Gebräu die Wärme raubt. Genauso wichtig wie das Getränk selbst ist sein begrenzter Vorrat an robusten Bechern, von denen er erwartet, dass seine Boten sie unverzüglich zurückbringen."}},faq={{q="Wer ist Nori Stolzmut?",a="Nori Stolzmut ist ein geschäftstüchtiger Zwergenhändler, der im Coldridgetal ansässig ist. Er braut und verkauft Scalding Mornbrew, ein heißes, kaffeeähnliches Getränk, das die örtlichen Wachen und Minenarbeiter warmhält.",al={"wer ist nori","nori stolzmut lore","scalding mornbrew händler"}},{q="Was ist Scalding Mornbrew?",a="Scalding Mornbrew ist ein spezielles Heißgetränk, das von Nori Stolzmut gebraut wird. Ähnlich wie kochend heißer Kaffee oder gewürztes Morgen-Ale wird es von den Einheimischen des Tals sehr geschätzt, um der bitteren Kälte von Dun Morogh zu trotzen.",al={"scalding mornbrew","welches getränk verkauft nori","mornbrew"}},{q="Warum sind die Lieferungen so dringend?",a="Der gesamte Reiz des Getränks beruht darauf, dass es kochend heiß ist. In den eisigen Bergwinden des Coldridgetals verliert ein Becher rasch seine Wärme, was Noris Lieferboten dazu zwingt, zu ihren durstigen Kunden zu sprinten.",al={"warum eilt die lieferung","mornbrew lieferung eilt","warum wird das getränk kalt"}},{q="Warum legt Nori so viel Wert auf die Rückgabe der Becher?",a="Nori verfügt im Tal nur über einen begrenzten Vorrat an Trinkgefäßen. Wenn Kunden mit seinen Bechern verschwinden oder sie in den Schneewehen zerbrechen, kommt sein morgendliches Geschäft schnell zum Erliegen.",al={"warum den becher zurückbringen","noris becher","becherrückgabe"}}},fx={ddac60d5={q="Auf wessen Seite steht Nori Stolzmut?",a="Nori steht voll und ganz zu den Zwergen von Eisenschmiede und der Allianz. Er ist ein unabhängiger lokaler Händler, der von Das Coldridgetal aus operiert und die Bergsteiger, Auszubildenden und Bewohner bedient, die das Tal verteidigen und dort leben.",al={"nori stolzmut fraktion","für wen arbeitet nori","nori stolzmut allianz"}},["26ccfe8e"]={q="Was möchte Nori Stolzmut?",a="Nori möchte ein profitables Brauereigeschäft in Das Coldridgetal führen. Sein Hauptanliegen ist es, sicherzustellen, dass sein charakteristisches Scalding Mornbrew seine durstigen Kunden erreicht, solange es noch kochend heiß ist, und sicherzugehen, dass jeder leere Humpen seinen Weg zurück in sein Inventar findet.",al={"nori stolzmut ziel","was möchte nori","nori motivationen"}},["10ad6fd1"]={q="Warum ist Nori Stolzmut hier?",a="Nori durchstreift Das Coldridgetal, weil sich dort seine durstigen Stammkunden befinden. Das raue, eiskalte Gebirgsklima macht sein kochend heißes Morgengebräu besonders beliebt bei den lokalen Wachen und Auszubildenden, was ihm ein beständiges Geschäft einbringt.",al={"warum ist nori im coldridgetal","warum ist nori hier","nori stolzmut standort"}}},fp="15,301,26.649.0,23.186.0,26.211.0,29.207.0,48.181.0"}
P.entries["npc:novice-elreth"] = {n="Novize Elreth",s="Novize Elreth ist eine untote Angehörige der Verlassenen, die in der Kapelle in Todesend stationiert ist. Wenn neu auferstandene Untote in ihr zweites Leben erwachen, weist sie sie an, sich der hirnlosen Geißel zu stellen, die die nahegelegenen Gräber heimsucht, und sich um die tragischen Folgen der Seuche zu kümmern.",h="Novize Elreth ist eine untote Angehörige der Verlassenen, die in der Kapelle in Todesend stationiert ist.",kw={"kapelle","kirche","todesend","verlassene","marla's last wish","novize elreth","the damned","tirisfal"},ang={["class:Priest"]="Indem sie auf dem ehemaligen heiligen Boden von Lordaeron steht, verkörpert Elreth den krassen, pragmatischen Wandel von der heiligen Verehrung hin zur düsteren Notwendigkeit der Untoten.",["race:Undead"]="Für frische Verlassene, die aus dem Grab kriechen, bietet Novize Elreth einige der ersten praktischen Schritte zum Überleben an, indem sie kalten Hass gegen die hirnlose Geißel fokussiert."},sec={{t="Eine Führerin in der Kirche der Verdammten",b="In der geschändeten Kapelle in Todesend unterstützt Novize Elreth die neu erwachten Untoten, während diese versuchen, ihr schreckliches Erwachen zu begreifen. Anstatt der Verzweiflung oder dem hirnlosen Hunger der Geißel zu erliegen, müssen sich die Verlassenen schnell organisieren, um ihr Gebiet zu sichern. Elreth gibt den neu befreiten Seelen erste Aufgaben und weist sie an, Tatzen und Flügel von den Wölfen und Fledermäusen im Süden zu sammeln und sich mit den verbliebenen Resten von Lordaerons tragischem Untergang zu befassen, einschließlich des Kummers ihrer Freundin Marla Fipps, die von ihrem eigenen Ehemann Samuel erschlagen wurde, nachdem er sich der hirnlosen Geißel angeschlossen hatte."}},faq={{q="Wo befindet sich Novize Elreth?",a="Novize Elreth steht in der Kapelle in Todesend, dem zerstörten Dorf in Tirisfal, wo neu erschaffene Verlassene erwachen.",al={"standort elreth","wo ist elreth","novize elreth kirche"}},{q="Welche Rolle spielt Novize Elreth in Todesend?",a="Sie fungiert als lokale Führerin und Aufgabenverteilerin für neu auferstandene Verlassene. Sie gibt wichtige erste Anweisungen und lehrt die frischen Untoten, gegen die hirnlose Geißel vorzugehen, die auf dem Dorffriedhof umherstreift.",al={"was tut elreth","rolle elreth","zweck novize elreth"}},{q="Welche Quests bietet Novize Elreth an?",a="Sie vergibt Missionen wie The Damned, bei der Abenteurer um Aasfressertatzen und Dämmerfledermausflügel gebeten werden, sowie Marla's Last Wish, bei der sie darum bittet, den hirnlosen Samuel Fipps zu besiegen und seine Überreste neben dem Grab seiner Frau Marla zu bestatten.",al={"quests novize elreth","aufgaben elreth"}},{q="Warum trägt sie den Titel 'Novize'?",a="Aufgrund ihres Standortes in der Kapelle und ihres Titels ist Elreth eine Novizin in den religiösen oder zivilen Rängen der Verlassenen und lernt die düsteren Praktiken der Verwaltung der frisch auferstandenen Untoten in Tirisfal unter dem Schatten der Ordnung der Verlassenen.",al={"warum novize","bedeutung novize elreth","ist elreth ein priester"}}},fx={["04e44638"]={q="Wer ist Novize Elreth?",a="Novize Elreth ist eine untote Betreuerin, die in der geschändeten Kirche von Todesend stationiert ist. Als eine der ersten Betreuerinnen, die den frisch erwachten Verlassenen zur Seite stehen, hilft sie dabei, neu auferstandene Seelen durch die raue Realität ihres Untodes zu führen und sie in den Dienst unter der Dunklen Fürstin zu integrieren.",al={"wer ist novize elreth","novize elreth hintergrundgeschichte","über novize elreth"}},["36f54bd8"]={q="Auf wessen Seite steht Novize Elreth?",a="Sie ist vollkommen loyal gegenüber den Verlassenen und Königin Sylvanas Windläufer. Von Todesend aus unterstützt ihre Arbeit direkt die Bemühungen der Unterstadt, Tirisfal durch die Bewertung und Anleitung der neu Auferstandenen zu sichern.",al={"novize elreth fraktion","wem dient novize elreth","novize elreth loyalität"}},d753a6ea={q="Was möchte Novize Elreth?",a="Elreth möchte sicherstellen, dass neu befreite Untote ihren Zustand verstehen, sich der Wahrheit ihrer Gräber stellen und ihren Zweck innerhalb der Verlassenen finden. Sie prüft die Entschlossenheit der neu Auferstandenen und weist fähige Hände der lokalen Führung zu, um die Kriegsanstrengungen zu unterstützen.",al={"was möchte elreth","novize elreth ziel","warum gibt elreth quests"}},a4872bf3={q="Warum ist Novize Elreth hier in Todesend?",a="Todesend ist der Ort, an dem die Verlassenen neue Leichen entdecken und erwecken, damit sie sich ihren Reihen anschließen können. Elreth bleibt in der Kapelle, um sich unmittelbar nach ihrem Erwachen um diese desorientierten Seelen zu kümmern und sicherzustellen, dass sie nicht der Verzweiflung erliegen oder sich gegen ihre neue Verwandtschaft wenden.",al={"warum ist elreth in todesend","warum ist novize elreth in der kirche"}}},fp="13,270,35.594.0,31.128.0,43.193.0,37.220.0,27.234.0"}
P.entries["npc:oben-rageclaw"] = {n="Oben Zornklaue",s="Oben Zornklaue ist der rastlose Geist eines nachtelfischen Druiden, der die verderbten Tiefen der Grabhügel von Ban'ethil in Teldrassil heimsucht. Während sein Geist gefangen im Grabhügel umherwandert, ist seine schlummernde physische Gestalt unter den Einfluss übler Furbolgmagie geraten.",h="Oben Zornklaue ist der rastlose Geist eines nachtelfischen Druiden, der die verderbten Tiefen der Grabhügel...",kw={"grabhügel von ban'ethil","druide der klaue","smaragdgrüner traum","gnarlpine","oben zornklaue","teldrassil","der schlafende druide"},ang={["class:Druid"]="Obens Schicksal ist eine erschütternde Mahnung an die Verwundbarkeit der Druiden während ihrer tranceartigen Zwiesprache mit dem Smaragdgrünen Traum, wenn heilige Grabhügel unverteidigt zurückgelassen werden.",["race:NightElf"]="Die Schändung von Oben Zornklaue durch die Gnarlpine-Furbolgs verdeutlicht, wie tief die Verderbnis bereits Teldrassils einheimische Bewohner und heilige Zufluchten heimgesucht hat."},sec={{t="Ein geschändeter Schlummer",b="Wie viele Druiden der Klaue zog sich Oben Zornklaue in das unterirdische Refugium der Grabhügel von Ban'ethil zurück, um Zwiesprache mit der Natur zu halten und im Smaragdgrünen Traum zu wandeln. Als die einheimischen Gnarlpine-Furbolgs jedoch der Verderbnis anheimfielen und die Grabhügel überrannten, wurde Oben in seiner Trance völlig wehrlos überrascht. Anstatt ihn einfach zu töten, nutzten die verderbten Schamanen der Gnarlpine dunkle Rituale, um die Kontrolle über seine komatöse sterbliche Hülle zu ergreifen, wodurch sein vertriebener Geist als gequälter Schemen zurückblieb, unfähig weiterzuziehen oder zu erwachen."},{t="Durchtrennung der Hülle",b="Unfähig, sein eigenes Fleisch aus der Knechtschaft der Schamanen zurückzufordern, ist Oben auf Reisende angewiesen, die die gefährlichen Tunnel durchqueren, um seine Qualen zu beenden. Nur indem sein als Marionette missbrauchter physischer Körper aufgespürt und vernichtet wird, können seine irdischen Bande durchtrennt werden. Sobald seine entführte Hülle getötet ist, wird Obens gequälter Geist endlich aus der unterirdischen Düsternis befreit, um ewige Ruhe im Smaragdgrünen Traum zu finden."}},faq={{q="Wer ist Oben Zornklaue?",a="Oben Zornklaue ist ein Nachtelf und Druide der Klaue, dessen Geist die Grabhügel von Ban'ethil in Teldrassil heimsucht, nachdem er von verderbten Furbolgs von seinem physischen Körper getrennt wurde.",al={"wer ist oben","oben zornklaue geschichte","geist im grabhügel"}},{q="Warum ist Oben Zornklaue ein Geist?",a="Während Oben in einer tiefen druidischen Trance schlief und im Smaragdgrünen Traum verweilte, drangen Schamanen der Gnarlpine-Furbolgs in den Höhlenbau ein und belegten seinen Körper mit übler Magie, wodurch sie die Kontrolle über ihn übernahmen und seinen Geist als Erscheinung draußen gefangen hielten.",al={"warum ist oben tot","wie starb oben","warum ist oben ein geist"}},{q="Wo befindet sich Obens physischer Körper?",a="Sein physischer Körper liegt tiefer in den gewundenen Gängen der Grabhügel von Ban'ethil, bewacht und manipuliert von den Gnarlpine-Schamanen, die den Höhlenbau verdorben haben.",al={"obens körper finden","wo ist obens körper","schlafender druide standort"}},{q="Was geschieht, nachdem Obens Körper vernichtet wurde?",a="Die Zerstörung seines manipulierten Körpers bricht die dunkle Macht der Gnarlpine-Schamanen über ihn und ermöglicht es seinem Geist, friedlich aus Teldrassil zu scheiden und für immer im Smaragdgrünen Traum zu ruhen.",al={"obens schicksal","was geschieht mit obens geist","oben retten"}}},fx={["9c749c17"]={q="Auf wessen Seite steht Oben Zornklaue?",a="Oben Zornklaue ist den Nachtelfen und dem Zirkel des Cenarius verbunden. Obwohl ein verdorbener Gnarlpine-Schamane derzeit seine schlummernde physische Gestalt tief in den Hügelgräbern manipuliert, bleibt Obens wahrer Geist seinem Volk treu und sucht Hilfe bei vorbeiziehenden Abenteurern, um seine Qualen zu beenden.",al={"ist oben zornklaue freundlich","oben zornklaue fraktion","wem dient oben"}},["98315864"]={q="Was möchte Oben Zornklaue?",a="Oben wünscht sich die Befreiung von der unnatürlichen Macht, die seinen Geist an den Grabhügel von Ban'ethil bindet. Weil abscheuliche Gnarlpine-Magie die Kontrolle über seinen physischen Körper ergriffen hat, bittet er Euch, seine verdorbene Gestalt zu zerstören, damit sein ruheloser Geist endlich Frieden im Der Smaragdgrüne Traum finden kann.",al={"was möchte oben","oben zornklaue ziel","oben zornklaue motiv"}}},fp="13,260,20.516.0,19.384.1,21.166.0,29.225.0,30.155.0,44.169.1"}
P.entries["npc:ogtinc"] = {n="Ogtinc",s="Ogtinc ist ein unabhängiger Furbolgjäger, der auf einem hohen Bergrücken mit Blick auf die Ruinen von Eldarath in Azshara haust. Nachdem er sich von seinem Stamm trennte, um dem Gleichgewicht der Natur zu dienen, fungiert er als verlässlicher Verbündeter und Mentor für den Zirkel des Cenarius. Erfahrene Jäger, die ihr Können an den wildesten Bestien Kalimdors erproben wollen, suchen oft seinen Rat.",h="Ogtinc ist ein unabhängiger Furbolgjäger, der auf einem hohen Bergrücken mit Blick auf die Ruinen von...",kw={"azshara","cenarius","eldarath","furbolg","jäger","ogtinc","holzschlund"},ang={["class:Druid"]="Als standhafter Partner des Zirkels des Cenarius stellt Ogtinc ein seltenes Bindeglied zwischen der wilden Weisheit unverdorbener Furbolgs und der Behüterrolle der Druiden dar.",["class:Hunter"]="Ogtinc bietet erfahrenen Jägern tiefgründige spirituelle und praktische Prüfungen, die ihre Treffsicherheit und ihr Überlebensgeschick an den tödlichsten Kreaturen Kalimdors messen."},sec={{t="Ein Furbolg eigener Art",b="Während die meisten Furbolgs in Kalimdor ihren Stämmen treu ergeben bleiben – oder nach dem Dritten Krieg der Verderbnis anheimgefallen sind –, wählte Ogtinc einen anderen Weg. Er verließ sein Volk und widmete seinen Bogen sowie sein Überlebenswissen der Unterstützung des Zirkels des Cenarius. Sein Lager liegt hoch auf einer Klippe südöstlich der Holzschlundfeste, von wo aus er wachsam über die uralten, zerrissenen Lande von Azshara blickt."},{t="Meister der Jagd",b="Ogtinc ist unter erfahrenen Fährtenlesern für sein tiefes Verständnis der Wildnis Kalimdors bekannt. Er stellt Jäger auf die Probe, die ihr Handwerk über die Kontinente hinweg verfeinert haben, und schickt sie aus, um seltene Trophäen zu beschaffen – wie das Geweih von Pirscherbestien, die Schuppen wellenumtoster Seeschlangen und Teile von grünen Drachenbruten. Durch diese Prüfungen lehrt er, dass wahre Jagd die Natur ehrt und das Gleichgewicht bewahrt, statt blindlings Leben zu rauben."}},faq={{q="Wer ist Ogtinc?",a="Ogtinc ist ein meisterhafter Furbolgjäger, der auf den Klippen von Azshara wacht. Anders als die meisten seiner zurückgezogen lebenden oder verdorbenen Artgenossen verließ er seinen angestammten Stamm, um den Druiden des Zirkels des Cenarius sein Fährtensucherwissen und seine Weisheit zur Verfügung zu stellen.",al={"wer ist ogtinc","ogtinc lore","furbolg in azshara"}},{q="Wo ist Ogtinc zu finden?",a="Er befindet sich in Azshara auf einem Lagerplatz an den Klippen mit Blick auf die Ruinen von Eldarath, direkt südöstlich der Holzschlundfeste.",al={"wo ist ogtinc","ogtinc aufenthaltsort","ogtinc finden"}},{q="Warum hat Ogtinc seinen Stamm verlassen?",a="Ogtinc verließ sein Volk gezielt, um den Zirkel des Cenarius bei dessen Bemühungen zur Bewahrung der Natur zu unterstützen. Seine genaue Stammesherkunft bleibt zwar unbestimmt, doch sein klarer Verstand und sein friedfertiges Wesen heben sich deutlich von den verdorbenen Stämmen im übrigen nördlichen Kalimdor ab.",al={"warum ging ogtinc","ogtinc stamm","gehört ogtinc zur holzschlundfeste"}},{q="Welche Rolle spielt Ogtinc für Jäger?",a="Ogtinc dient als meisterhafter Mentor für erfahrene Jäger, die den Höhepunkt ihrer Ausbildung erreichen. Er gibt ihnen auf, furchterregende Bestien in ganz Kalimdor aufzuspüren – von schnellen Pirschern bis hin zur Brut des grünen Drachenschwarms –, um ihre Beherrschung der Wildnis zu beweisen.",al={"ogtinc jägerquests","jägerlehrer ogtinc","warum zu ogtinc reisen"}},{q="Ist Ogtinc mit der Holzschlundfeste verbündet?",a="Obwohl er nahe der Holzschlundfeste lagert, agiert Ogtinc unabhängig und in direkter Partnerschaft mit dem Zirkel des Cenarius. Reisenden, die sich friedlich nähern, begegnet er von Natur aus freundlich, ungeachtet ihres Rufs beim Stamm der Holzschlundfurbolgs.",al={"ogtinc holzschlund","holzschlund ruf ogtinc","ist ogtinc freundlich"}},{q="Warum wacht Ogtinc über die Ruinen von Eldarath?",a="Sein erhöhter Ausguck über den Ruinen ermöglicht ihm einen ungetrübten Blick auf die unruhige Wildnis tief unten, wo Naga, Elementare und verbliebene magische Echos das empfindliche Gleichgewicht des Küstenwaldes bedrohen.",al={"warum ogtinc in azshara ist","eldarath ogtinc","ogtinc klippe"}}},fp="6,350,15.381.0,18.456.0,14.243.0,26.137.0,31.267.0,39.257.0,41.231.0,49.209.0"}
P.entries["npc:ogunaro-wolfrunner"] = {n="Ogunaro Wolfsläufer",s="Ogunaro Wolfsläufer ist der führende Wolfszüchter und Zwingerwart der Horde in Orgrimmar, stationiert an der Jägerhalle im Tal der Ehre. Er kümmert sich um die wilden Wölfe, die auserwählt wurden, um Orc-Champions und ihre treuen Verbündeten in die Schlacht zu tragen. Für erfahrene Reiter, die eine Bindung zu Durotars Spitzenprädatoren suchen, ist Ogunaro der Meister, an den man sich wenden muss.",h="Ogunaro Wolfsläufer ist der führende Wolfszüchter und Zwingerwart der Horde in Orgrimmar, stationiert an der...",kw={"terrorwolf","ogunaro wolfsläufer","orgrimmar reittiere","waldwolf","tal der ehre","wolf reittier"},ang={["faction:Horde"]="Trolle, Tauren und Verlassene müssen ihre Hingabe und Ehre gegenüber Orgrimmar beweisen, bevor Ogunaro ihnen ein Wolfsreittier anvertraut.",["race:Orc"]="Für Orcs ist das Reiten eines Wolfs eine uralte Tradition, die bis zu den Clans von Draenor zurückreicht; Ogunaro fungiert als Hüter dieser heiligen kriegerischen Verbindung."},sec={{t="Meister des Rudels",b="In der Nähe der Jägerhalle im Tal der Ehre überwacht Ogunaro Wolfsläufer die Zucht und Ausbildung von Orgrimmars Kampfwölfen. Die Bindung zwischen Orc und Wolf reicht über Generationen hinweg über die Ebenen von Draenor und die raue Wildnis von Durotar zurück und stellt eine Partnerschaft gegenseitigen Respekts dar und nicht bloße Domestizierung. Ogunaro stellt sicher, dass nur die widerstandsfähigsten und wildesten Bestien – von Terrorwölfen bis hin zu agilen Waldläufern – Kriegern anvertraut werden, die ihre Stärke und ihren Wert für den Kriegshäuptling bewiesen haben."}},faq={{q="Wer ist Ogunaro Wolfsläufer?",a="Ogunaro Wolfsläufer ist der primäre Wolfszüchter und Reittierhändler der Horde, zu finden vor der Jägerhalle in Orgrimmars Tal der Ehre.",al={"ogunaro","wolfshändler orgrimmar","orc reittierhändler"}},{q="Kann jeder einen Wolf von ihm kaufen?",a="Ihrem Erbe nach können Orcs Wölfe uneingeschränkt erwerben, sobald sie entsprechend ausgebildet sind. Nicht-Orc-Mitglieder der Horde müssen sich ehrfürchtigen Ruf und das größte Vertrauen von Orgrimmar verdienen, bevor Ogunaro sich von einer seiner geschätzten Bestien trennt.",al={"können nicht-orcs wölfe kaufen","wolf reittier rufanforderungen"}},{q="Welche Arten von Wölfen bietet er an?",a="Ogunaro führt einen vielfältigen Zwinger kampferprobter Reittiere, darunter Schwarz-, Braun-, Terror- und Waldwölfe sowie schnelle, gepanzerte Rassen, die für Kriegsveteranen geeignet sind.",al={"arten von wolfsreittieren","welche wölfe verkauft ogunaro"}}},fx={["37d9a7a8"]={q="Auf wessen Seite steht Ogunaro Wolfsläufer?",a="Ogunaro Wolfsläufer ist der Horde und der Stadt Orgrimmar gegenüber vollkommen loyal. Er kümmert sich im Tal der Ehre um die wertvollen Reitwölfe der Horde und stellt seinen orkischen Brüdern und Schwestern sowie denjenigen, die sich das tiefe Vertrauen und den höchsten Respekt von Orgrimmar verdient haben, direkt Reittiere zur Verfügung.",al={"ogunaro wolfsläufer fraktion","wem dient ogunaro","ogunaro horde allianz"}},c9c48f43={q="Warum ist Ogunaro Wolfsläufer hier im Tal der Ehre?",a="Ogunaro hat sein Zuhause im Tal der Ehre von Orgrimmar, direkt vor der Jägerhalle. Dieses Viertel dient als Ausbildungs- und Sammelplatz für die wildesten Krieger und Jäger der Horde, was es zum natürlichen Ort macht, um robuste Kriegswölfe unterzubringen, zu züchten und erfahrenen Champions anzubieten.",al={"warum ist ogunaro in orgrimmar","ogunaro wolfsläufer standort","warum ist ogunaro hier"}},c3908665={q="Was will Ogunaro Wolfsläufer?",a="Ogunaro widmet sein Handwerk der Zucht und Bereitstellung starker, verlässlicher Wölfe für die Champions der Horde. Er möchte lediglich sicherstellen, dass die ikonischen Reittiere des orkischen Volkes fähige Reiter finden, die wissen, wie man sie behandelt und im Kampf befehligt.",al={"was will ogunaro","ogunaro ziele","ogunaro wolfsläufer beweggrund"}}},fp="18,331,18.525.0,26.142.0,36.212.0,37.167.0"}
P.entries["npc:old-murk-eye"] = {n="Trübauge der Alte",s="Trübauge der Alte ist ein berüchtigter, kampferprobter Murloc, der an der südlichen Küstenlinie von Westfall sein Unwesen treibt. Von seiner eigenen Art verehrt und von Seefahrern an der Küste gefürchtet, stellt er eine tödliche Bedrohung für jeden dar, der sich in die Nähe des Leuchtturms von Westfall wagt.",h="Trübauge der Alte ist ein berüchtigter, kampferprobter Murloc, der an der südlichen Küstenlinie von Westfall...",kw={"kapitän grausohn","bedrohung der küste","murk-eye","murloc","trübauge der alte","westfall","der leuchtturm von westfall"},ang={["faction:Alliance"]="Für Abenteurer der Allianz, die Westfall säubern, beseitigt die Vernichtung von Trübauge der Alte ein berüchtigtes Raubtier, das gestrandeten Reisenden und Schiffsmannschaften auflauert."},sec={{t="Schrecken der Küste",b="Während Murlocs an den Küsten von Westfall eine gewöhnliche Plage darstellen, hebt sich Trübauge der Alte deutlich von den niederen Aasfressern ab. Beträchtlich zäher und weitaus aggressiver als seine Artgenossen, durchstreift diese ergraute Bestie die Brandung rund um den Leuchtturm von Westfall. Seine anhaltende Präsenz hat den örtlichen Seeleuten so viel Leid eingebracht, dass der geisterhafte Kapitän Grausohn seinen Tod verlangt und ein Kopfgeld für die makellosen Schuppen der Kreatur aussetzt, um seine Herrschaft über die Untiefen zu brechen."}},faq={{q="Wo treibt sich Trübauge der Alte herum?",a="Er patrouilliert an den Sandstränden und in den seichten Gewässern des südwestlichen Westfall, direkt an der Küste nahe dem Leuchtturm von Westfall.",al={"trübauge der alte aufenthaltsort","wo man trübauge der alte findet","wo ist murk-eye"}},{q="Warum will Kapitän Grausohn den Tod von Trübauge der Alte?",a="Kapitän Grausohn betrachtet Trübauge der Alte als eine ständige Bedrohung für die Küstengewässer. Um der Gewalt am Strand Einhalt zu gebieten, setzt er ein Kopfgeld auf den legendären Murloc aus und verlangt eine Schuppe als Beweis für die Tat.",al={"grayson murk-eye","warum trübauge der alte töten"}},{q="Unterscheidet sich Trübauge der Alte von gewöhnlichen Murlocs?",a="Ja. Er ist merklich stärker, widerstandsfähiger und aggressiver als die ihn umgebenden Handlanger der Coastrunner und Tidehunter und fungiert als Stammeschampion unter den hiesigen Küstenrudeln.",al={"wie stark ist murk-eye","ist murk-eye elite"}}},fx={["295d9e5f"]={q="Auf wessen Seite steht Trübauge der Alte?",a="Trübauge der Alte kämpft nur für sich selbst und seine Murloc-Artgenossen an der Küste. Er ist keinem Königreich, keiner Gilde und keiner Fraktion verpflichtet und betrachtet Luft- und Landbewohner als Eindringlinge in seinem Gebiet, die vertrieben oder getötet werden müssen.",al={"trübauge fraktion","für wen arbeitet trübauge","ist trübauge allianz"}},["48ac0465"]={q="Warum ist Trübauge der Alte in Westfall?",a="Trübauge der Alte beansprucht die Küstengewässer und Felsstrände rund um den Leuchtturm von Westfall als sein Jagdrevier. Die abgelegene Küste bietet reichlich Fischfang und eine Basis, um ahnungslose Reisende oder an der zerklüfteten Küste schiffbrüchige Seeleute zu überfallen.",al={"warum ist trübauge hier","warum ist trübauge der alte in westfall","trübauge standort lore"}},["5afdb8dc"]={q="Warum ist Trübauge der Alte berühmt oder gefürchtet?",a="Trübauge der Alte hat sich bei Seeleuten und Einheimischen einen Ruf als berüchtigte Bedrohung entlang der Brandung von Westfall erworben. Er ist stärker und aggressiver als gewöhnliche Küstenmurlocs, hat unzählige Scharmützel überlebt und terrorisiert jeden, der sich der Leuchtturmküste nähert, bis Geister wie Kapitän Grausohn ein Kopfgeld auf ihn aussetzen.",al={"warum ist trübauge gefürchtet","warum ist trübauge der alte berüchtigt","legende von trübauge"}},["0038f035"]={q="Wer ist Trübauge der Alte?",a="Trübauge der Alte ist ein berüchtigter und zäher Murloc, der die Küste von Westfall in der Nähe von Der Leuchtturm von Westfall patrouilliert. Von Einheimischen und Seeleuten gleichermaßen als Küstenplage anerkannt, sticht er unter seinesgleichen als außergewöhnlich widerstandskräftiges und gerissenes Geschöpf hervor, dessen Anwesenheit eine ständige Gefahr für jeden darstellt, der die westlichen Ufer entlangwandert.",al={"wer ist trübauge","wer ist trübauge der alte","trübauge der alte hintergrundgeschichte"}}},fp="12,229,23.451.0,31.127.0,48.203.0,48.184.0"}
P.entries["npc:onyxia"] = {fx={fd0ec0c3={q="Auf wessen Seite steht Onyxia?",a="Onyxia gehört einzig und allein dem Schwarzen Drachenschwarm an und dient den dunklen Plänen ihrer Familie. In enger Allianz mit ihrem Bruder Nefarian arbeitet sie daran, ihren korrumpierten Drachenschwarm wiederaufzubauen und die sterblichen Völker zu unterwerfen. Sie schuldet weder der Allianz noch der Horde Treue; die Reiche der Sterblichen existieren nur, um manipuliert, geschwächt und gebrochen zu werden, um die Vorherrschaft des schwarzen Drachenschwarms zu sichern.",al={"onyxia seite","wem dient onyxia","onyxia fraktion","onyxia allianz oder horde"}},ba62a202={q="Warum ist Onyxia so gefürchtet?",a="Als Tochter von Deathwing und Brutmutter des schwarzen Drachenschwarms ist Onyxia sowohl in ihrer physischen Macht als auch in ihrer List tödlich. Obwohl sie für einen ausgewachsenen Drachen vergleichsweise klein ist, sind ihre Schläge blitzschnell und ihr feuriger Atem kann Eisen innerhalb von Augenblicken schmelzen. In Kombination mit ihrem hinterhältigen Talent, unter den Sterblichen Täuschungen zu weben, stellt sie eine existenzielle Bedrohung für Azeroth dar.",al={"warum ist onyxia gefürchtet","ist onyxia mächtig","onyxia ruf"}}}}
P.entries["npc:orendil-broadleaf"] = {n="Orendil Rundblatt",s="Orendil Rundblatt ist ein erfahrener Nachtelfen-Kräuterkundiger und Heiler, der auf Maestras Posten im westlichen Eschental stationiert ist. Bekannt für sein tiefes Wissen über die Flora des Waldes, braut er lebenswichtige Heilmittel zusammen, um junge Leben in den unruhigen Wäldern zu retten.",h="Orendil Rundblatt ist ein erfahrener Nachtelfen-Kräuterkundiger und Heiler, der auf Maestras Posten im...",kw={"eschental","astranaar","bathranshaar","maestras posten","orendil rundblatt","orendils heilmittel","relara whitemoon"},ang={["profession:Herbalism"]="Orendil demonstriert die lebensrettende Bedeutung regionaler Pflanzen und verlässt sich auf seltene Gewächse wie Bathranshaar, um vor Ort wirksame Gegenmittel zu brauen.",["race:NightElf"]="Für die Nachtelfen, die Eschental verteidigen, ist Orendil ein unverzichtbarer Hüter des Lebens, dessen sanfte Heilmittel selbst ein todkrankes Kind retten können."},sec={{t="Heiler der Waldgrenze",b="Auf Maestras Posten an der westlichen Schwelle von Eschental kümmert sich Orendil Rundblatt als geschickter Heiler um die Kranken. Orendil, der für sein meisterhaftes Wissen über einheimische Kräuter und die Kunst der Wiederherstellung bekannt ist, verlässt sich auf durchreisende Reisende, um seltene natürliche Reagenzien zu sammeln. Selbst wenn Spannungen und Konflikte den Wald bedrängen, gilt sein unermüdlicher Einsatz dem Schutz seines Volkes und der Linderung ihrer Leiden."},{t="Ein Wettlauf gegen die Krankheit",b="Vor allem spielt Orendil eine zentrale Rolle bei dem verzweifelten Versuch, Relara Whitemoon zu heilen, ein leidendes Kind in Astranaar. Durch das sorgfältige Studium der Pflanzenwelt des Waldes – darunter Bathranshaar – entwickelt er wirksame Elixiere, die tödliche Krankheiten abwehren können, und beweist damit, dass kräuterkundliche Meisterschaft ein entscheidender Schild gegen die Gefahren bleibt, die Eschental heimsuchen."}},faq={{q="Wer ist Orendil Rundblatt?",a="Orendil Rundblatt ist ein Nachtelfen-Kräuterkundiger und Heiler, der auf Maestras Posten im westlichen Eschental weilt. Sein Geschick im Umgang mit Kräutern und Heilung ist weithin bekannt.",al={"orendil rundblatt","wer ist orendil","orendil eschental"}},{q="Wo ist Orendil Rundblatt zu finden?",a="Er befindet sich auf Maestras Posten, einem Außenposten der Nachtelfen am Hauptweg im westlichen Eschental, nahe der Grenze zur Dunkelküste.",al={"orendil rundblatt aufenthaltsort","orendil finden","wo ist orendil"}},{q="Was versucht Orendil zu heilen?",a="Orendil braut einen heilenden Trank zusammen, um Relara Whitemoon zu retten, ein kränkelndes Nachtelfenkind in Astranaar, wobei er seltene Kräuter verwendet, die in den wilden Weiten von Eschental gesammelt wurden.",al={"orendil heilung","wen heilt orendil","relara whitemoon heilung"}}},fx={c4fe2e8b={q="Auf wessen Seite steht Orendil Rundblatt?",a="Orendil Rundblatt steht fest an der Seite der Allianz und der Nachtelfen von Darnassus. Stationiert in Maestras Posten, arbeitet er mit den Wächterinnen zusammen, um das Eschental gegen die Aggression der Horde zu verteidigen, und kümmert sich um die Verletzungen und Leiden seines Volkes.",al={"orendil rundblatt fraktion","ist orendil rundblatt allianz","orendil rundblatt zugehörigkeit"}},["5dbbc739"]={q="Was will Orendil Rundblatt?",a="Orendil Rundblatt möchte Kranke und Verwundete heilen und gleichzeitig den Wald schützen. Sein Hauptanliegen ist es, ein lebenswichtiges Heilmittel für Relara Weißmond, ein krankes Nachtelfenkind in Astranaar, zu brauen, und er ist auf auswärtige Reisende angewiesen, um die seltenen Kräuter zu sammeln, die benötigt werden, um sie zu retten.",al={"was will orendil","orendil rundblatt ziele","orendil rundblatt motiv"}},["9af45c4c"]={q="Warum ist Orendil Rundblatt hier?",a="Orendil bleibt als engagierter Kräuterkundiger und Heiler an der westlichen Grenze des Eschentals in Maestras Posten. Dort kümmert er sich um die Leiden seines Volkes und ist auf vorbeiziehende Reisende angewiesen, um die seltenen Kräuter zu sammeln, die seine Heilmittel erfordern.",al={"warum ist orendil rundblatt in maestras posten","warum ist orendil im eschental","was macht orendil rundblatt hier"}},["7beb4a99"]={q="Mit wem ist Orendil Rundblatt verbunden?",a="Orendil Rundblatt arbeitet mit den Wächterinnen zusammen, die Maestras Posten verteidigen, und stimmt sich eng mit Pelturas Weißmond in Astranaar ab, um Pelturas' junge Tochter Relara zu beschützen.",al={"orendil rundblatt verbindungen","mit wem arbeitet orendil rundblatt","orendil lehrlinge"}}},fp="17,235,27.408.0,23.358.1,25.148.0,37.135.0,31.174.0"}
P.entries["npc:orenthil-whisperwind"] = {n="Orenthil Wisperwind",s="Orenthil Wisperwind ist ein Nachtelf und Bewohner von Teldrassil, den man unter den Ästen des Laubschattentals antrifft.",h="Orenthil Wisperwind ist ein Nachtelf und Bewohner von Teldrassil, den man unter den Ästen des...",kw={"orenthil","laubschattental","teldrassil","wisperwind"},sec={{t="Ein freundliches Gesicht in Teldrassil",b="Orenthil Wisperwind weilt unter den Nachtelfen des Laubschattentals unter dem Blätterdach von Teldrassil. Über seine persönliche Geschichte ist wenig überliefert."}},faq={{q="Wer ist Orenthil Wisperwind?",a="Er ist ein Nachtelf, der im Laubschattental auf Teldrassil zu finden ist. Er dient als freundliche Gestalt, die Abenteurer willkommen heißt, die in die Äste des Weltenbaums aufbrechen.",al={"orenthil","orenthil wisperwind info","wer ist dieser elf"}},{q="Wo kann ich Orenthil Wisperwind finden?",a="Orenthil weilt im Laubschattental, der Startansiedlung der Nachtelfen auf Teldrassil.",al={"orenthil aufenthaltsort","wo ist orenthil","orenthil karte"}}},fx={["38b36176"]={q="Auf wessen Seite steht Orenthil Wisperwind?",a="Orenthil steht fest an der Seite der Nachtelfen von Darnassus und der größeren Allianz. Er lebt unter seinesgleichen in den Zweigen von Teldrassil und begrüßt neue Reisende, die eintreffen, um seinem Volk zu helfen.",al={"orenthil wisperwind fraktion","ist orenthil allianz","wem dient orenthil"}},["71428597"]={q="Warum ist Orenthil Wisperwind hier?",a="Orenthil lebt im Laubschattental auf Teldrassil. Seine persönlichen Gründe für seine Niederlassung dort sind nicht verzeichnet.",al={"orenthil wisperwind zweck","warum ist orenthil in dolanaar","was macht orenthil"}}},fp="20,105,29.146.0,28.147.0,38.84.0"}
P.entries["npc:orgnil-soulscar"] = {n="Orgnil Narbenseele",s="Orgnil Narbenseele ist ein orcischer Ermittler, der in Klingenhügel im zentralen Durotar stationiert ist. Er fungiert als informeller Friedensoffizier und koordiniert die Verteidigung sowie die Aufklärung gegen innere Bedrohungen der jungen Nation. Sein Hauptaugenmerk gilt dem Schatten, den der Kult der Burning Blade über die Schluchten Durotars wirft.",h="Orgnil Narbenseele ist ein orcischer Ermittler, der in Klingenhügel im zentralen Durotar stationiert ist.",kw={"burning blade","durotar","margoz","orgnil narbenseele","klingenhügel","schattenrat","die knochenhöhle"},ang={["class:Warlock"]="Hexenmeister müssen in Orgnils Nähe vorsichtig sein, da sein gesamtes Augenmerk darauf liegt, unkontrollierte dämonische Verderbnis innerhalb der Grenzen von Durotar aufzuspüren und auszumerzen.",["faction:Horde"]="Orgnil sorgt dafür, dass das Herzland der Horde nicht von Kultisten von innen heraus ausgehöhlt wird, während sie nach außen blickt, um eine neue Nation aufzubauen.",["race:Orc"]="Für junge Orcs verkörpert Orgnil die vorderste Front gegen den dämonischen Makel, der einst die Clans versklavte, und erinnert neue Rekruten an die Wachsamkeit, die nötig ist, um ihre neue Heimat rein zu halten."},sec={{t="Wächter von Klingenhügel",b="In Klingenhügel übernimmt Orgnil Narbenseele die finstere Verantwortung, Umsturzversuche und heimtückische Bedrohungen in ganz Durotar aufzuspüren. Während die Patrouillen der Grunzer nach außen auf Stützpunkte der Allianz und Überfallkommandos der Zentauren achten, konzentriert sich Orgnil auf die Fäulnis, die im Inneren schwelt. Er sammelt Berichte von Spähern aus der gesamten Region und fügt Beweise für rituelle Verderbnis und verbotene Zusammenkünfte zusammen."},{t="Die Jagd nach den Überresten des Schattenrats",b="Orgnils Hauptaugenmerk liegt auf dem heimlichen Wiedererstarken des Kults der Burning Blade, dessen Hexenmeister sich in Höhlen wie der Knochenhöhle verbergen. Wohl wissend, welche Verheerung die Teufelsmagie in vergangenen Generationen über das orcische Volk gebracht hat, weigert sich Orgnil zuzulassen, dass Dämonenanbetung in der Nähe von Orgrimmar erneut Fuß fasst. Er beauftragt vertrauenswürdige Rekruten damit, Kultisten niederzustrecken, rituelle Talismane zu sammeln und sich mit einheimischen Einsiedlern und Schamanen wie Margoz zu beraten, um die finstere Magie zu verstehen, die dort am Werk ist."}},faq={{q="Wer ist Orgnil Narbenseele?",a="Orgnil Narbenseele ist ein orcischer Amtsträger in Klingenhügel, der als Ermittler und Koordinator für die Verteidigung von Durotar fungiert. Er lenkt Krieger und Späher gegen verdeckte Gefahren, die die neu besiedelten Lande der Orcs bedrohen.",al={"wer ist orgnil","orgnil narbenseele lore","klingenhügel questgeber"}},{q="Welche Bedrohung bereitet Orgnil die größte Sorge?",a="Orgnil widmet sich der Ausrottung des Kults der Burning Blade. Er betrachtet deren Präsenz in den verborgenen Höhlen Durotars und ihre verderbende Teufelsmagie als tödliche Gefahr für den Neuanfang, den Thrall für die Horde vorsieht.",al={"was will orgnil","orgnil feinde","gegen wen kämpft orgnil"}},{q="Warum schickt Orgnil Reisende zu Margoz?",a="Margoz ist ein kundiger Einsiedler, der nördlich von Klingenhügel lebt und die finsteren Zeichen und Rituale der Burning Blade versteht. Orgnil schickt Späher zu Margoz, um die Bewegungen des Kults zu entschlüsseln und die heraufziehende magische Verderbnis aufzudecken.",al={"warum margoz","orgnil und margoz","wer ist margoz für orgnil"}},{q="Wo ist Orgnil Narbenseele zu finden?",a="Orgnil ist unter freiem Himmel in der Siedlung Klingenhügel stationiert, nahe der zentralen Kreuzung von Durotar.",al={"orgnil standort","wo ist orgnil","orgnil narbenseele finden"}},{q="Was ist die Burning Blade in Durotar?",a="Die Burning Blade ist ein unheilvoller Kult, der dämonischen Meistern und dem Schattenrat dient. Sie verstecken sich in Schluchten wie der Knochenhöhle und der Staubwindhöhle, um Durotars Tierwelt zu vergiften und junge Orcs wieder in dämonische Unterwerfung zu locken.",al={"burning blade durotar","burning blade kult","wer ist die burning blade"}},{q="Arbeitet Orgnil direkt für Thrall?",a="Orgnil agiert als Teil des regionalen Verteidigungsapparats in Klingenhügel und führt den Auftrag des Kriegshäuptlings aus, Durotar vor Aufruhr und dämonischem Einfluss zu schützen.",al={"orgnil thrall","ist orgnil wache des kriegshäuptlings"}}},fx={["68dd86eb"]={q="Auf wessen Seite steht Orgnil Narbenseele?",a="Orgnil ist der Horde und der Verteidigung von Durotar gegenüber völlig loyal. Er ist in Klingenhügel stationiert, fungiert als Vollstrecker für die lokale Ordnung und Sicherheit und widmet seine Bemühungen dem Schutz junger orkischer Siedlungen vor hinterhältigen internen Bedrohungen wie den Kultisten der Burning Blade, die in den Schatten der Schluchten lauern.",al={"orgnil narbenseele fraktion","wem dient orgnil","orgnil zugehörigkeit"}},["07ede484"]={q="Was will Orgnil Narbenseele?",a="Orgnil möchte den Schatten der Burning Blade innerhalb von Durotar ausrotten. Er sucht nach zuverlässigen Informationen über die Aktivitäten der Kultisten und beauftragt fähige Abenteurer damit, ihre Hexenmeister niederzustrecken, gestohlene Talismane zurückzuerobern und einheimische Einsiedler wie Margoz zu konsultieren, um die dämonische Verderbnis zu entwirren, die sich über das Land ausbreitet.",al={"was will orgnil","orgnil ziele","orgnil zweck"}},["9d37257b"]={q="Warum ist Orgnil Narbenseele hier in Klingenhügel?",a="Klingenhügel dient außerhalb von Orgrimmar als zentraler Knotenpunkt für Verteidigung und Logistik in Durotar. Orgnil ist hier als investigative Autorität und Beschützer stationiert, perfekt positioniert, um verdächtige Regungen in den trockenen Tälern zu überwachen und Reisende gegen eindringende Kultisten und verderbte Bestien zu mobilisieren.",al={"warum ist orgnil in klingenhügel","orgnil rolle klingenhügel","warum ist orgnil hier"}},["05bd4129"]={q="Mit wem ist Orgnil Narbenseele verbunden?",a="Orgnil arbeitet mit den lokalen Verteidigern der Horde gegen die Burning Blade zusammen und weist Abenteurer an Margoz weiter, der nordöstlich von Klingenhügel lebt.",al={"orgnil verbündete","orgnil verbindungen","mit wem arbeitet orgnil"}}},fp="15,308,21.388.0,37.458.1,23.216.0,41.210.0,41.233.0,35.101.0,37.240.0,37.175.0"}
P.entries["npc:ormak-grimshot"] = {n="Ormak Grimmschlag",s="Ormak Grimmschlag ist ein erfahrener Ork-Jägerlehrer, der in der Jägerhalle im Tal der Ehre von Orgrimmar residiert. In Begleitung seines treuen Wolfs Grimfang unterweist er junge Jäger der Horde im Spurenlesen, in der Treffsicherheit und im Eingehen von Bindungen mit wilden Tieren.",h="Ormak Grimmschlag ist ein erfahrener Ork-Jägerlehrer, der in der Jägerhalle im Tal der Ehre von Orgrimmar...",kw={"tierausbildung","grimfang","jägerlehrer","die jägerhalle","orgrimmar","ormak grimmschlag","tal der ehre"},ang={["class:Hunter"]="Ormak ist ein unverzichtbarer Mentor für Jäger der Horde und führt sie durch die Pflichten des Zähmens und Pflegens eines treuen tierischen Begleiters.",["race:Orc"]="Als Verkörperung klassischer orkischer Überlebensfertigkeiten veranschaulicht Ormak, wie Orks an der Seite von Wölfen und einheimischen Raubtieren zusammenarbeiten, um Durotar zu verteidigen."},sec={{t="Meister der Jagd",b="Stationiert in der Jägerhalle im Tal der Ehre dient Ormak Grimmschlag als Grundpfeiler der kriegerischen Ausbildung für die Fährtenleser und Scharfschützen der Horde. An der Seite seines Gefährten, des Wolfs Grimfang, vermittelt Ormak die grundlegende Disziplin, die zum Überleben in der rauen Wildnis von Kalimdor erforderlich ist. Für Jäger der Orks und Trolle, die von ihren Prüfungen in Durotar eintreffen, bietet er entscheidende Führung in der heiligen Kunst des Zähmens und Befehligens wilder Tiere und stellt sicher, dass jeder Jäger eine dauerhafte Bindung zu seinem tierischen Partner aufbaut."}},faq={{q="Wer ist Ormak Grimmschlag?",a="Ormak Grimmschlag ist ein erfahrener Ork-Jägerlehrer, der im Tal der Ehre in Orgrimmar stationiert ist. Er bringt neuen Jägern der Horde fortgeschrittene Fertigkeiten im Fernkampf und in der Tierherrschaft bei.",al={"wer ist ormak","ormak grimmschlag geschichte","ormak jägerlehrer"}},{q="Wo finde ich Ormak Grimmschlag?",a="Ormak befindet sich in der Jägerhalle, gelegen im Tal der Ehre im östlichen Orgrimmar. Er steht nahe bei seinem Begleiterwolf Grimfang.",al={"ormak aufenthaltsort","wo ist grimshot","ormak finden"}},{q="Wer ist der Wolf an seiner Seite?",a="Der Wolf an seiner Seite ist Grimfang, Ormaks treuer tierischer Gefährte, der die enge Bindung zwischen einem geschickten Jäger und seinem Begleiter veranschaulicht.",al={"ormak wolf","grimfang","ormak begleiter"}},{q="Welche Rolle spielt er für neue Jäger?",a="Ormak leitet unerfahrene Jäger der Orks und Trolle darin an, wie sie ihre frisch gezähmten Tiere ausbilden, füttern und führen, sobald sie ihre grundlegenden Prüfungen in Durotar abgeschlossen haben.",al={"jäger begleiter quest orgrimmar","zähmen quest ormak","die ausbildung des tiers ormak"}}},fx={["84e77df7"]={q="Auf wessen Seite steht Ormak Grimmschlag?",a="Ormak ist der Horde und der Verteidigung von Durotar vollkommen ergeben. Als einer der Ausbilder im Tal der Ehre gilt seine Loyalität der neuen Nation von Kriegshäuptling Thrall und den Jägern, die ihre Grenzen schützen.",al={"ormak fraktion","ormak horde oder allianz","wem dient ormak"}},dac02825={q="Was möchte Ormak Grimmschlag erreichen?",a="Ormak möchte sicherstellen, dass die Jäger der Horde disziplinierte, geschickte Schützen sind, die in der Wildnis überleben können. Zusammen mit seinem Wolfsbegleiter Grimfang möchte er die Talente vielversprechender Kundschafter verfeinern und ihren Einfallsreichtum durch anspruchsvolle Prüfungen auf die Probe stellen.",al={"ormak ziel","was braucht ormak","ormak grimmschlag zweck"}},["88908d62"]={q="Warum ist Ormak Grimmschlag im Tal der Ehre?",a="Ormak ist im Tal der Ehre von Orgrimmar stationiert, um Schützen in der Jägerhalle auszubilden. Er bleibt in der Nähe des militärischen Zentrums der Horde, wo erfahrene Kundschafter und junge Auszubildende gleichermaßen Rat zur Tierherrschaft und Feldkunde suchen.",al={"warum ist ormak hier","ormak grimmschlag standort grund","warum ist ormak in orgrimmar"}}},fp="14,255,18.508.0,22.169.0,32.134.0,27.133.0,39.149.0"}
P.entries["npc:ormer-ironbraid"] = {n="Ormer Eisenzopf",s="Ormer Eisenzopf ist ein zwergischer Archäologe, der an Whelgars Ausgrabungsstätte im Süden des Sumpflands stationiert ist. Die historischen Forschungen seines Teams wurden gewaltsam durch gefräßige Raptoren unterbrochen, die die Ausgrabung überrannten. Ormer sucht nach abenteuerlustigen Verbündeten, um die Bestien zu beseitigen und die von der Stätte vertriebenen Minenarbeiter zu rächen.",h="Ormer Eisenzopf ist ein zwergischer Archäologe, der an Whelgars Ausgrabungsstätte im Süden des Sumpflands...",kw={"zwerg","ausgrabung","forscherliga","ironbraid","ormer","raptoren","sumpfland","whelgar"},ang={["class:Hunter"]="Jäger werden in Ormers Bitte eine vertraute Aufgabe finden, bei der sie ihr Können im Fährtenlesen und Bestientöten gegen einige der wildesten Raptoren in Khaz Modan unter Beweis stellen können.",["faction:Alliance"]="Ormer beizustehen sichert die Straße im südlichen Sumpfland und unterstützt die überaus wichtigen archäologischen Bestrebungen von Eisenschmiede.",["race:Dwarf"]="Ormer verkörpert zwergische Beharrlichkeit – er weigert sich, uralten Boden der Ahnen an ein Rudel übergroßer Echsen abzutreten."},sec={{t="Eine entgleiste Ausgrabung",b="Ormer Eisenzopf kam als Teil der zwergischen Bemühungen ins Sumpfland, um Relikte der Titanen und alte Geschichte an Whelgars Ausgrabungsstätte aufzudecken. Unglücklicherweise förderte das Freilegen alter Steine auch Rudel wilder Sumpflandraptoren zutage – oder stachelte sie zumindest an. Statt antike Tonwaren und Steintafeln zu katalogisieren, verbringt Ormer seine Tage damit, die Bestien beim Umherstreifen in den Ruinen zu beobachten, und hegt einen grimmigen Hass auf die Kreaturen, die ihre Arbeit unterbrochen haben."},{t="Eine bittere Fehde mit Krallen",b="Ormer weigert sich, die Grabung aufzugeben, doch fehlt ihm die rohe Muskelkraft, um die Stätte im Alleingang zu säubern. Er kanalisiert seinen Frust in einen systematischen Vernichtungsfeldzug und heuert durchreisende Wanderer an, um Raptoren von zunehmender Größe und Wildheit zu erschlagen. Für Ormer geht es bei der Rückeroberung der Ausgrabung nicht nur um die Artefakte – es ist eine zutiefst persönliche Angelegenheit zwergischen Stolzes und der Rache an der einheimischen Tierwelt."}},faq={{q="Wer ist Ormer Eisenzopf?",a="Ormer Eisenzopf ist ein Zwergenforscher, der die Arbeiten an Whelgars Ausgrabungsstätte im Sumpfland beaufsichtigt. Er vertritt die Interessen der Forscherliga bei der Untersuchung der im Moor vergrabenen uralten Ruinen.",al={"wer ist ormer","ormer eisenzopf","ormer sumpfland"}},{q="Wo kann ich Ormer Eisenzopf finden?",a="Er steht auf der Anhöhe über Whelgars Ausgrabungsstätte in den südlichen Klippen des Sumpflands, direkt östlich der Hauptstraße nach Loch Modan.",al={"ormer standort","wo ist ormer","ormer eisenzopf finden"}},{q="Warum hasst Ormer Raptoren so sehr?",a="Die örtlichen Raptorenrudel überrannten die Ausgrabungsstätte, vertrieben die zwergischen Arbeiter und brachten jeden archäologischen Fortschritt zum Erliegen. Ormer fasste diese Störung als persönliche Beleidigung auf und sinnt auf völlige Vergeltung.",al={"warum raptoren","ormer raptoren","ormers rache lore"}},{q="Was ist Whelgars Ausgrabungsstätte?",a="Es handelt sich um eine archäologische Ausgrabungsstätte, die von den Zwergen aus Eisenschmiede gegründet wurde, um uralte Ruinen der Titanen und Irdenen unter dem Sumpfland freizulegen. Eine aggressive Tierwelt hat die Grabung jedoch in ein gefährliches Schlachtfeld verwandelt.",al={"whelgars ausgrabungsstätte","was ist diese ausgrabungsstätte","sumpfland ausgrabungsstätte"}},{q="Welche Quests bietet Ormer an?",a="Ormer bietet die dreiteilige Questreihe 'Ormers Rache' an, bei der Abenteurer beauftragt werden, immer größere Raptoren in der Ausgrabungsstätte auszudünnen.",al={"ormer quests","schlag die erde","ormers rache quest"}},{q="Gehört Ormer zur Forscherliga?",a="Ja. Wie viele Zwerge, die in ganz Khaz Modan antike Ruinen ausgraben, handelt Ormer im Auftrag der archäologischen Bemühungen von Eisenschmiede, die dem Aufdecken des Titanenerbes ihres Volkes gewidmet sind.",al={"ormer forscherliga","ist ormer ein archäologe"}}},fx={["97454981"]={q="Auf wessen Seite steht Ormer Eisenzopf?",a="Ormer ist ein loyaler Zwerg von Eisenschmiede, der sich der Allianz und den Expeditionen der Zwerge durch Khaz Modan verpflichtet fühlt. Während sein unmittelbarer Fokus darauf liegt, in der Wildnis des Sumpflands zu überleben und die Ausgrabungsstätte zu sichern, steht er fest an der Seite seines Volkes und der Allianz.",al={"ormer fraktion","ist ormer allianz","ormer eisenzopf zugehörigkeit"}},f4da8dc2={q="Was will Ormer Eisenzopf?",a="Ormer möchte nichts sehnlicher, als dass die bösartigen Raptoren, die Whelgars Ausgrabungsstätte befallen haben, ausgelöscht werden. Die Bestien haben die Ausgrabungen der Expedition überrannt und die Ausgräber vertrieben, und er sucht Rache und Vergeltung gegen die Kreaturen, damit die Stätte zurückerobert werden kann.",al={"ormer ziele","was will ormer","warum ormer rache"}},["60616fd2"]={q="Warum ist Ormer Eisenzopf hier im Sumpfland?",a="Ormer kam als Teil der archäologischen Expedition der Zwerge, die in Whelgars Ausgrabungsstätte stationiert ist, ins Sumpfland. Anstatt jedoch in aller Ruhe nach alten Schätzen zu graben, fand er sich in einem bitteren Kampf ums Überleben wieder, nachdem einheimische Raptoren die Ausgrabung überrannt hatten.",al={"warum ist ormer an der ausgrabungsstätte","ormer eisenzopf sumpfland zweck","warum ist ormer hier"}}},fp="15,310,14.448.0,24.396.0,23.200.0,33.175.0,36.196.0,34.205.0,29.135.0,47.184.0"}
P.entries["npc:orokk-omosh"] = {n="Orokk Omosh",s="Orokk Omosh ist ein alternder Orcschmied, der im Tal der Ehre in Orgrimmar stationiert ist. Als letzter Erbe einer traditionsreichen Schmiedelinie sucht er in der gesamten Horde nach würdigen Lehrlingen, um die Rüstungsschmiedegeheimnisse seiner Familie zu bewahren, bevor sie für immer verloren gehen.",h="Orokk Omosh ist ein alternder Orcschmied, der im Tal der Ehre in Orgrimmar stationiert ist.",kw={"barbarische waffenschmiedekunst","schmiedekunst","dance of joy","omosh","orc schmied","orgrimmar","orokk omosh","tal der ehre"},ang={["faction:Horde"]="Orokks Hingabe stellt sicher, dass traditionelle orcische Platten- und Kettenpanzertechniken erhalten bleiben, um die Krieger zu stärken, die die aufstrebende Horde verteidigen.",["profession:Blacksmithing"]="Für angehende Rüstungsschmiede der Horde ist Orokk Omosh ein unentbehrlicher Lehrmeister, der spezialisierte Muster und Unterweisungen anbietet, um das Überleben seines uralten Handwerks zu sichern."},sec={{t="Eine Linie an ihrem Ende",b="An den tosenden Schmieden im Tal der Ehre stehend, trägt Orokk Omosh eine schwere Bürde: Er ist der letzte Schmied der ehrwürdigen Omosh-Linie. Da er keine Nachkommen gezeugt hat, die sein Handwerk erben könnten, weigert sich Orokk, die mühsam erlernten Techniken seiner Familie mit sich sterben zu lassen. Stattdessen lädt er fähige Schmiede der Horde dazu ein, anspruchsvolle Prüfungen der Metallarbeit zu absolvieren, und verspricht, jenen, die ihre Hingabe beweisen, die geschätzten Geheimnisse der Omosh-Rüstungsschmiedekunst weiterzugeben."},{t="Der Geist der Schmiede",b="Trotz der ernsten Realität seiner schwindenden Blutlinie ist Orokk unter Handwerkskollegen für seine unbändige Begeisterung bekannt, sobald wahre Meisterschaft gezeigt wird. Wer seine Prüfungen der Handwerkskunst besteht, erlangt mehr als nur spezialisierte Rüstungsmuster – oft löst dies den berühmten „Omosh Dance of Joy“ aus, einen ausgelassenen Jubeltanz zu Ehren der traditionellen Schmiedekunst, der durch die Hallen von Orgrimmar hallt."}},faq={{q="Wer ist Orokk Omosh?",a="Orokk Omosh ist ein meisterhafter Orcschmied, der im Tal der Ehre in Orgrimmar ansässig ist. Er ist das letzte überlebende Mitglied der Schmiedelinie der Omosh und verbringt seine Tage mit der Suche nach vielversprechenden Lehrlingen, die das metallurgische Wissen seiner Familie erben.",al={"wer ist orokk","orokk omosh geschichte","orc schmied orgrimmar"}},{q="Wo ist Orokk Omosh zu finden?",a="Ihr könnt Orokk Omosh nahe den Schmiedefeuern und Ambossen im Tal der Ehre finden, gelegen im nordöstlichen Teil von Orgrimmar.",al={"orokk omosh aufenthaltsort","wo ist orokk","orokk omosh finden"}},{q="Warum lehrt Orokk Omosh Außenstehende seine Familiengeheimnisse?",a="Orokk hat keine eigenen Kinder, die das Handwerk seiner Familie erben könnten. Anstatt zuzulassen, dass Generationen orcischer Rüstungsschmiedetechniken aussterben, hat er sich entschieden, jeden geschickten Schmied der Horde zu unterrichten, der sich seinen hohen Standards gewachsen zeigt.",al={"warum gibt orokk quests","omosh vermächtnis","warum schmiede unterrichten"}},{q="Was ist der „Omosh Dance of Joy“?",a="Es ist ein ausgelassener Freudentanz, den Orokk vollführt, wenn ein Handwerker erfolgreich seinen Wert unter Beweis stellt und die Schmiedetechniken seiner Linie meistert. Er dient sowohl als sein persönliches Gütesiegel als auch als feurige Hommage an das Handwerk.",al={"dance of joy","omosh tanz","freude der omoshs"}}},fx={df415c30={q="Auf wessen Seite steht Orokk Omosh?",a="Orokk Omosh ist Thralls Horde treu. Er arbeitet aus dem geschäftigen Herzen von Orgrimmar heraus und teilt bereitwillig die hart erarbeiteten Fertigkeiten und alten metallurgischen Traditionen seiner Blutlinie ausschließlich mit vielversprechenden Schmieden der Horde.",al={"orokk omosh fraktion","wem dient orokk omosh","ist orokk omosh horde"}},["1085ff21"]={q="Was möchte Orokk Omosh?",a="Als letztes lebendes Mitglied einer ehrwürdigen Linie von Orc-Schmieden und ohne eigene Kinder möchte Orokk vor allem das Vermächtnis seiner Familie bewahren. Er sucht fähige Schmiede, die würdig sind, die Waffenkammertechniken der Familie Omosh zu meistern und fortzuführen, bevor sie für immer verloren gehen.",al={"was möchte orokk omosh","orokk omosh ziel","warum sucht orokk schmiede"}},["5e3af98e"]={q="Warum ist Orokk Omosh hier in Orgrimmar?",a="Orokk hat sich im Tal der Ehre in Orgrimmar niedergelassen, wo sich die besten Krieger, Raufbolde und Handwerker der Horde versammeln. Es ist der natürliche Treffpunkt für die mächtigen Kunsthandwerker und engagierten Rüstungsschmiede, von denen er hofft, dass sie sein angestammtes Handwerk fortführen werden.",al={"warum ist orokk omosh in orgrimmar","orokk omosh standort grund"}}},fp="11,246,20.450.0,23.384.0,19.252.0,31.134.0,57.237.0,33.233.0"}
P.entries["npc:orphan-matron-battlewail"] = {n="Waisenmatrone Schlachterbe",s="Waisenmatrone Schlachterbe leitet das Waisenhaus der Horde im Tal der Ehre in Orgrimmar. Gemeinsam mit ihrer Mitbetreuerin Tosamina nimmt sie junge Ork-Kinder auf und zieht sie groß, die ihre Familien durch die anhaltenden Kriege verloren haben.",h="Waisenmatrone Schlachterbe leitet das Waisenhaus der Horde im Tal der Ehre in Orgrimmar.",kw={"battlewail","kinderwoche","orgrimmar","waisenmatrone schlachterbe","waisenhaus","tosamina","tal der ehre","hüterin der horde"},ang={["faction:Horde"]="Battlewail sichert die Zukunft der Horde, indem sie Kindern, die von den harten Realitäten des Krieges zurückgelassen wurden, Orientierung und Zuflucht bietet.",["race:Orc"]="Für die Orks, die danach streben, eine dauerhafte Heimat in Durotar zu errichten, bleibt Battlewails Waisenhaus eine ernüchternde Erinnerung an die Opfer, die ihr Volk erbringen muss."},sec={{t="Hüterin der Jugend der Horde",b="Der Krieg fordert in ganz Azeroth ständig seinen Tribut, und die junge Hauptstadt Orgrimmar ist Zeuge dieser Kosten. Waisenmatrone Schlachterbe kümmert sich um die Kleinen, die ihre Angehörigen durch Gewalt verloren haben, und sorgt dafür, dass die nächste Generation der Horde beschützt, beherbergt und umsorgt wird. Gemeinsam mit Tosamina im Tal der Ehre öffnet Battlewail vorbeiziehenden Abenteurern die Türen des Waisenhauses – insbesondere während festlicher Bräuche wie der Kinderwoche, wenn Reisende dazu aufgerufen sind, die Patenschaft für diese Jugendlichen zu übernehmen."}},faq={{q="Wer ist Waisenmatrone Schlachterbe?",a="Sie ist eine Orkin, die das Waisenhaus in Orgrimmar beaufsichtigt und ihr Leben der Beherbergung und Erziehung von Kindern widmet, deren Eltern in der Schlacht gefallen sind.",al={"battlewail rolle","wer ist battlewail","waisenmatrone battlewail"}},{q="Wo ist sie in Orgrimmar zu finden?",a="Battlewail und ihre Gefährtin Tosamina kümmern sich im Tal der Ehre um die Kinder, das im östlichen Teil von Orgrimmar liegt.",al={"battlewail standort","wo ist das waisenhaus","battlewail finden"}},{q="Was ist ihre Rolle während der Kinderwoche?",a="Während des Feiertags der Kinderwoche organisiert Battlewail Patenschaften und schickt hilfsbereite Champions mit einem Waisenkind in die Welt hinaus, um ihnen die Wunder und das Erbe der Horde zu zeigen.",al={"kinderwoche battlewail","hüterin der horde","waisenquest"}},{q="Wer unterstützt Battlewail im Waisenhaus?",a="Tosamina lebt und arbeitet an Battlewails Seite und hilft dabei, über die Kinder zu wachen und jene zu beschützen, die ihrer Fürsorge anvertraut wurden.",al={"tosamina","helferin der waisenmatrone"}}},fx={["5bd84e8a"]={q="Auf wessen Seite steht Waisenmatrone Schlachterbe?",a="Waisenmatrone Schlachterbe steht hingebungsvoll auf der Seite der Horde. Sie ist in Orgrimmar ansässig und widmet ihr Leben der Erziehung der Kinder gefallener Krieger der Horde, um sicherzustellen, dass sie stark, beschützt und stolz auf das Vermächtnis ihres Volkes aufwachsen.",al={"schlachterbe fraktion","ist schlachterbe horde"}},c46a64f6={q="Was möchte Waisenmatrone Schlachterbe?",a="Ihr vorrangiges Ziel ist die Sicherheit, das Wohlergehen und die Erziehung der Waisen in ihrer Obhut. Insbesondere während der Kinderwoche sucht sie nach verlässlichen Abenteurern, die die Kinder mit in die Welt hinausnehmen, um ihnen das Leben jenseits der Mauern von Orgrimmar zu zeigen.",al={"schlachterbe ziel","was möchte die waisenmatrone"}},["8b214374"]={q="Warum ist Waisenmatrone Schlachterbe hier?",a="Schlachterbe leitet das Waisenhaus von Orgrimmar im Tal der Ehre gemeinsam mit ihrer Gefährtin Tosamina. Ständige Konflikte in ganz Kalimdor lassen viele junge Orcs ohne Eltern zurück, was ihre mitfühlende und zugleich standhafte Fürsorge für die Stadt unverzichtbar macht.",al={"warum ist schlachterbe in orgrimmar","warum ist schlachterbe hier"}}},fp="24,224,30.498.0,32.145.0,36.133.0,40.191.0,40.115.0"}
P.entries["npc:orphan-matron-nightingale"] = {n="Waisenmatrone Nachtigall",s="Waisenmatrone Nachtigall leitet das Waisenhaus von Sturmwind auf dem Kathedralenplatz. Zusammen mit Matron Shellene kümmert sie sich um Kinder, die ihre Familien durch die unerbittlichen Konflikte verloren haben, die das Königreich plagen. Zudem wirbt sie während der Kinderwoche vertrauenswürdige Abenteurer der Allianz an, um ihren jungen Schützlingen als Mentoren und Vorbilder zur Seite zu stehen.",h="Waisenmatrone Nachtigall leitet das Waisenhaus von Sturmwind auf dem Kathedralenplatz.",kw={"kathedralenplatz","kinderwoche","matron shellene","nightingale","waisenmatrone nachtigall","sturmwind","sturmwind waisenhaus"},ang={["class:Priest"]="Direkt vor der Kathedrale des Lichts stationiert, verkörpert Nightingales Mission die Tugenden des Mitgefühls und des Dienstes am Nächsten, die die Priester des Heiligen Lichts aufrechtzuerhalten suchen.",["faction:Alliance"]="Für Streiter der Allianz dient Nightingale als Mahnung an den stillen, alltäglichen Preis des Krieges und die Pflicht, die zukünftigen Generationen des Reiches zu beschützen."},sec={{t="Hüterin der Heimatlosen",b="Direkt vor dem Waisenhaus südöstlich der Kathedrale des Lichts hält Waisenmatrone Nachtigall Wache und kümmert sich um Sturmwinds verletzlichste Überlebende. Jüngste Kriege, Gnollüberfälle und der Aufstieg der Bruderschaft der Defias haben viele Kinder ohne Heim oder Eltern zurückgelassen. Nightingale und ihre Mitbetreuerin Matron Shellene bieten diesen Kleinen unter dem wachsamen Auge der Kirche des Heiligen Lichts Schutz, grundlegende Pflege und Führung."},{t="Schirmherrin der Kinderwoche",b="Aus der Überzeugung heraus, dass Hoffnung ebenso lebenswichtig ist wie Nahrung und Obdach, organisiert Matrone Nightingale Sturmwinds Feierlichkeiten zur Kinderwoche. In dieser Zeit wendet sie sich direkt an die Helden der Allianz, damit diese als Begleiter eines Waisenkindes auf Reisen durch Azeroth fungieren. Indem sie diese Kinder an gefeierte Streiter vermittelt, hofft sie, ihr Selbstvertrauen zu stärken, ihnen einen weiteren Blick auf die Welt außerhalb der Stadtmauern zu gewähren und sie daran zu erinnern, dass sie niemals wirklich vergessen sind."}},faq={{q="Wo ist Waisenmatrone Nachtigall zu finden?",a="Sie steht direkt vor dem Eingang zum Waisenhaus von Sturmwind, das sich auf dem Kathedralenplatz südöstlich der Kathedrale des Lichts befindet.",al={"matrone nightingale standort","sturmwind waisenhaus standort","wo ist nightingale"}},{q="Warum gibt es in Sturmwind so viele Waisen?",a="Das Königreich hat verheerende Kriege durchlitten, darunter den Dritten Krieg und anhaltende Scharmützel mit der Bruderschaft der Defias, Überresten der Orcs und feindseligen Bestien in den umliegenden Gebieten. Viele Stadtbewohner und Bauern der Grenzländereien kamen ums Leben und hinterließen Kinder, die nirgendwo sonst Zuflucht finden konnten.",al={"warum gibt es waisen","sturmwind waisen herkunft","wer sind diese kinder"}},{q="Was ist die Kinderwoche?",a="Die Kinderwoche ist ein jährliches Ereignis in Sturmwind, das von Matrone Nightingale organisiert wird. Abenteurer der Allianz sind eingeladen, als Vormund und Begleiter für ein Waisenkind aufzutreten und es auf Reisen mitzunehmen, um die Wunder und Helden der weiteren Welt kennenzulernen.",al={"kinderwoche sturmwind","was ist die kinderwoche","waisen-event"}},{q="Wer hilft Matrone Nightingale bei der Leitung des Waisenhauses?",a="Matron Shellene arbeitet an der Seite von Nightingale im und um das Waisenhaus herum und hilft dabei, die Kinder in ihrer Obhut aufzuziehen, zu ernähren und zu beherbergen.",al={"andere waisenmatrone","wer leitet das waisenhaus","matron shellene"}}},fx={["9dba66e4"]={q="Wer ist Waisenmatrone Nachtigall?",a="Waisenmatrone Nachtigall ist die mitfühlende Betreuerin, die gemeinsam mit Matron Shellene das Waisenhaus von Sturmwind beaufsichtigt. Sie hat ihren Sitz im Herzen des Kathedralenplatzes und widmet ihre Tage dem Schutz und der Pflege von Kindern, die ihre Familien an die unerbittlichen Kriege und Nöte verloren haben, die das Königreich bedrohen.",al={"wer ist matrone nachtigall","waisenmatrone nachtigall hintergrund","wer leitet das waisenhaus in sturmwind"}},e8925ab2={q="Auf wessen Seite steht Waisenmatrone Nachtigall?",a="Sie ist der Großen Allianz und dem Volk von Sturmwind voll und ganz treu. Ihre Pflichten führen sie in den schützenden Schatten der Kathedrale des Lichts, wo sie unermüdlich daran arbeitet, die verletzlichsten jungen Bürger des Königreichs zu unterstützen, und sich auf die Helden der Allianz verlässt, um das Leben der Kinder zu bereichern.",al={"nachtigall fraktion","ist nachtigall allianz","matrone nachtigall loyalität"}},["1cac5069"]={q="Was möchte Waisenmatrone Nachtigall?",a="Ihr Hauptanliegen ist das Wohlergehen, das Glück und die Erziehung der Waisen in ihrer Obhut. Sie versucht, ihnen in unruhigen Zeiten einen sicheren Zufluchtsort zu bieten, und bittet während der Kinderwoche sogar erfahrene Reisende um Hilfe, um den jungen Leuten Hoffnung und einen Einblick in die weitere Welt außerhalb der Stadtmauern zu geben.",al={"matrone nachtigall ziel","was möchte nachtigall","nachtigall absicht"}},e192fa2f={q="Warum ist Waisenmatrone Nachtigall hier?",a="Sie bleibt direkt vor den Stufen des Waisenhauses am Kathedralenplatz, um sich um die Kinder in ihrer Obhut zu kümmern und Besucher zu begrüßen. Von dieser geschäftigen, heiligen Ecke der Stadt aus koordiniert sie die täglichen Abläufe des Waisenhauses und sucht Kontakt zu wohlwollenden Abenteurern, die bereit sind, ihren jungen Schützlingen zu helfen.",al={"warum ist matrone nachtigall am kathedralenplatz","warum ist nachtigall vor dem waisenhaus","nachtigall standort grund"}}},fp="25,325,25.443.0,22.433.0,45.142.0,43.280.0,24.241.0,47.143.0"}
P.entries["npc:osric-strang"] = {fx={a4d8c3b8={q="Wer ist Osric Strang?",a="Osric Strang ist ein Rüstungshändler, der in Limited Immunity arbeitet, einem Geschäft, das in der geschäftigen Altstadt von Sturmwind liegt. Er verdient seinen Lebensunterhalt damit, Abenteurer und Stadtwachen mit schweren Ketten- und Plattenrüstungen sowie stabilen Schilden auszustatten.",al={"wer ist osric","osric strang hintergrund","osric strang herkunft"}},["66b236b5"]={q="Auf wessen Seite steht Osric Strang?",a="Osric Strang ist ein loyaler Bürger des Königreichs Sturmwind und steht fest an der Seite der Allianz; er versorgt diejenigen, die das Reich verteidigen, voller Stolz mit schützender Kriegsausrüstung.",al={"osric strang fraktion","osric strang loyalität","ist osric allianz"}},["9aee9a9e"]={q="Warum ist Osric Strang in Sturmwind?",a="Osric Strang betreibt Limited Immunity im Herzen der Altstadt, einem Viertel, das für seine erfahrenen Krieger, Handwerker und Waffenkammern bekannt ist. Sturmwind bietet ihm einen stetigen Strom an Rekruten, Reisenden und Verteidigern, die auf der Suche nach zuverlässigen schweren Rüstungen sind.",al={"warum ist osric strang hier","osric strang laden","osric strang limited immunity"}}}}
P.entries["npc:overlord-mok-morokk"] = {n="Oberanführer Mok'Morokk",s="Oberanführer Mok'Morokk ist der brutale Häuptling der Stonemaul-Oger, der über Brackenwall in den Düstermarschen herrscht. Ursprünglich von Rexxar wegen seiner Stärke ernannt, hat er sich zu einem tyrannischen und feigen Herrscher entwickelt, der sich weigert, seinen Clan gegen den Schwarzen Drachenschwarm zu verteidigen.",h="Oberanführer Mok'Morokk ist der brutale Häuptling der Stonemaul-Oger, der über Brackenwall in den...",kw={"brackenwall","draz'zilb","düstermarschen","mok'morokk","oger","oberanführer","rexxar","stonemaul"},ang={["class:Warrior"]="Mok'Morokk ist ein Paradebeispiel für rohe kriegerische Stärke ohne Ehre oder Mut und zeigt, wie leicht rohe Gewalt in Feigheit und Tyrannei umschlägt.",["faction:Horde"]="Die Stonemaul-Oger sind wertvolle Verbündete, die der Horde seit Rexxars Feldzug die Treue geschworen haben, doch Mok'Morokks wirkungslose und feige Führung droht Brackenwall völlig schutzlos zurückzulassen."},sec={{t="Ein Tyrann in den Marschen",b="Als Rexxar den vorherigen Häuptling Kor'gall besiegte und den Stonemaul-Clan zur Verteidigung von Durotar anführte, übertrug er Mok'Morokk das Kommando, da er Potenzial in dessen schierer kriegerischer Stärke sah. Dieses Vertrauen erwies sich als Fehlgriff. Mok'Morokk erlag schnell dem verderblichen Einfluss absoluter Autorität und herrschte eher durch Einschüchterung und Zügellosigkeit als durch Fürsorge. Anstatt sich um seine Sippe zu kümmern, fordert er unverdienten Tribut, faulenzt in Brackenwall herum und schikaniert jeden, der seinen Befehl infrage stellt."},{t="Der Feigling von Brackenwall",b="Mok'Morokks Führung brach vollends zusammen, als der Schwarze Drachenschwarm über das angestammte Stonemaul Village hereinbrach, viele Oger erschlug und die Überlebenden in den Schlamm von Brackenwall trieb. Anstatt einen Gegenangriff zu sammeln, um ihre Heimat zurückzufordern oder die Toten zu rächen, untersagte Mok'Morokk jegliche Aktion und kauerte voller Furcht vor dem Zorn der Drachen. Unter seinen Beratern, wie etwa dem Oger-Magier Draz'Zilb, gärt der Unmut, und sie suchen im Stillen nach Champions von außerhalb, die bereit sind, die schändliche Herrschaft des Oberanführers herauszufordern."}},faq={{q="Wer ist Oberanführer Mok'Morokk?",a="Mok'Morokk ist der Häuptling der Stonemaul-Oger, der derzeit in Brackenwall in den Düstermarschen residiert. Er wurde von Rexxar zum Anführer ernannt, verkam jedoch rasch zu einem egoistischen und fordernden Despoten.",al={"wer ist mok'morokk","anführer von brackenwall","stonemaul-ogerboss"}},{q="Wie wurde Mok'Morokk zum Anführer des Stonemaul-Clans?",a="Während der Gründung von Durotar besiegte der Champion der Horde, Rexxar, den vorherigen Anführer des Clans und übernahm das Kommando über die Stonemaul. Als Rexxar aufbrach, um durch die Wildnis zu streifen, ernannte er Mok'Morokk aufgrund seiner rohen körperlichen Stärke zum Oberanführer.",al={"wie kam mok'morokk an die macht","rexxar wählte mok'morokk","warum ist er häuptling"}},{q="Warum sind die Stonemaul-Oger in Brackenwall?",a="Die Stonemaul-Oger lebten ursprünglich in Stonemaul Village, doch schwarze Drachen griffen ihre Siedlung an und machten sie dem Erdboden gleich. Die Überlebenden flohen nach Norden in die Sümpfe, um Brackenwall als Außenposten für Flüchtlinge zu errichten.",al={"warum zogen oger nach brackenwall","was geschah mit dem dorf der stonemaul","schwarze drachen greifen oger an"}},{q="Warum will Mok'Morokk nicht gegen den Schwarzen Drachenschwarm kämpfen?",a="Trotz seiner gewaltigen Größe und seines wilden Rufs hat Mok'Morokk schreckliche Angst vor den Drachen. Anstatt einen Gegenangriff anzuführen, um das angestammte Territorium seines Clans zurückzufordern, sitzt er untätig in Brackenwall, hortet Tribut und ignoriert die Klagerufe seines Volkes.",al={"warum kämpft mok'morokk nicht gegen drachen","ist mok'morokk ein feigling","stonemaul zurückerobern"}},{q="Respektieren die anderen Stonemaul-Oger Mok'Morokk?",a="Im Clan wächst der Groll über seine Faulheit, Feigheit und Schikanen stetig an. Seine Berater sorgen sich um die Zukunft der Stonemaul unter seiner Herrschaft.",al={"mögen oger mok'morokk","draz'zilb mok'morokk","stonemaul-rebellion"}}},fp="19,280,21.497.0,25.495.1,27.205.0,55.258.0,51.209.0,50.250.0,48.148.1"}
P.entries["npc:ozzie-togglevolt"] = {fx={["86f7524c"]={q="Auf wessen Seite steht Ozzie Wechselvolt?",a="Ozzie steht voll und ganz auf der Seite der Gnomeregangnome und der Allianz. Wie viele Überlebende des verheerenden Falls von Gnomeregan hat er Zuflucht bei den Zwergen in Dun Morogh gefunden und widmet seinen Verstand und seine Fähigkeiten ganz der Unterstützung seiner vertriebenen Gnom-Kollegen.",al={"ozzie wechselvolt fraktion","ozzie wechselvolt allianz oder horde","wem dient ozzie wechselvolt"}},["3c84fab0"]={q="Warum ist Ozzie Wechselvolt hier in Dun Morogh?",a="Ozzie floh nach der tragischen Verseuchung von Gnomeregan nach Kharanos. Nachdem er der tödlichen Strahlung entkommen war, die so viele seiner Brüder korrumpierte, eröffnete er zusammen mit anderen Tüftlern ein Geschäft, um eine sichere Basis zu errichten, die nahe genug liegt, um den Fallout zu untersuchen und Überlebenden zu helfen.",al={"warum ist ozzie wechselvolt in kharanos","warum ist ozzie hier","ozzie wechselvolt standort grund"}}}}
P.entries["npc:pao-ka-swiftmountain"] = {n="Pao'ka Bergrausch",s="Pao'ka Bergrausch ist ein junger Tauren-Naturforscher, der unter den wilden Wyvern auf dem Steilhang in Tausend Nadeln gestrandet ist. Nachdem er unter der Führung von Motega Feuermähne nach Süden gereist war, übermannte ihn seine jugendliche Neugier, als er sich zu nah an eine Niststätte heranwagte und schließlich in den Klippen in die Enge getrieben wurde.",h="Pao'ka Bergrausch ist ein junger Tauren-Naturforscher, der unter den wilden Wyvern auf dem Steilhang in...",kw={"der steilhang","auf der heimreise","motega feuermähne","pao'ka bergrausch","tausend nadeln","weißgipfelposten","wyvern"},ang={["faction:Horde"]="Pao'ka repräsentiert die nächste Generation von Tauren-Gelehrten, die Kalimdor erforschen; ihn am Leben zu erhalten, bewahrt enge Bande mit den Ältesten am Weißgipfelposten.",["race:Tauren"]="Wyvern werden von den Tauren als Verbündete und treue Reittiere tief verehrt, was Pao'kas schlecht geplantes Eindringen sowohl peinlich als auch gefährlich macht."},sec={{t="Ein Naturforscher in Nöten",b="Pao'ka kam an der Seite von Motega Feuermähne in die Canyonlandschaft von Tausend Nadeln, begierig darauf, die gefährlichen Bestien der Schluchten zu katalogisieren und zu erforschen. Sein Vater hatte seinen Sohn nur widerstrebend auf eine derart gefährliche Reise gehen lassen, und Pao'kas jüngstes Missgeschick beweist, dass diese Sorgen berechtigt waren. Fasziniert von den prächtigen Wyvern, die den Steilhang bewohnen, schlich sich der junge Gelehrte hinter einem einsamen Taurentotem den Bergpfad hinauf. Wenig überraschend nahmen die territorialen Bestien Anstoß an seinem Eindringen und trieben ihn tief in die schroffen Felsen, wo er sich gefangen und verängstigt wiederfand – außerstande, an den herabstoßenden Raubtieren vorbei zum Weißgipfelposten zurückzukehren."}},faq={{q="Wer ist Pao'ka Bergrausch?",a="Pao'ka ist ein junger Tauren-Gelehrter, der Motega Feuermähne nach Tausend Nadeln begleitete, um die dortige Tierwelt zu studieren, nur um von territorialen Wyvern auf dem Steilhang in die Falle gelockt zu werden.",al={"wer ist pao'ka","paoka swiftmountain","wer ist der taure am steilhang"}},{q="Wo ist Pao'ka Bergrausch zu finden?",a="Er sitzt auf dem Steilhang in Tausend Nadeln fest. Um ihn zu erreichen, muss man ein hoch aufragendes Taurentotem nahe den Klippen finden, hinter dem ein schmaler Pfad den Berghang hinauf zu den Wyvernhorsten führt.",al={"wo ist paoka","pfad zum steilhang","wie findet man paoka"}},{q="Warum versteckt er sich auf dem Steilhang?",a="Seine Faszination für Wyvern führte ihn zu nah an eines ihrer Nester heran. Die wütenden Bestien vertrieben ihn und schnitten ihm den Rückweg ab, was ihn dazu zwang, sich mehrere Tage lang zu verstecken.",al={"warum sitzt paoka fest","warum griffen wyvern paoka an"}},{q="Was geschieht, nachdem Ihr ihm bei der Flucht helft?",a="Sobald er sicher aus den Nistgründen eskortiert wurde, flieht Pao'ka zurück zu Motega Feuermähne am Weißgipfelposten, in der verzweifelten Hoffnung, dass sein Mentor das Missgeschick nicht seinem Vater meldet.",al={"auf der heimreise ausgang","schafft es paoka zurück"}}},fx={["29fbd111"]={q="Zu wem hat Pao'ka Bergrausch Verbindungen?",a="Pao'ka steht unter der Mentorschaft von Motega Feuermähne in der Weißgipfelposten, der Pao'kas zögerlichen Vater davon überzeugte, dem Jugendlichen den Gang in die Wildnis zu erlauben, um die einheimischen Bestien zu studieren. Pao'ka fürchtet sich davor, Motega zu enttäuschen oder seinen beschützerischen Vater zu bestätigen, indem er bei seiner Expedition versagt.",al={"verbindungen paoka bergrausch","wen kennt paoka","paoka mentor"}},["3733bdd0"]={q="Auf wessen Seite steht Pao'ka Bergrausch?",a="Pao'ka gehört zur Horde. Er ist ein junger Tauren-Naturforscher, der unter der Anleitung der Ältesten seines Volkes in die Schlucht reiste und sich auf Champions der Horde verlässt, die ihm helfen, die Gefahren der Tausend Nadeln zu meistern.",al={"paoka bergrausch fraktion","ist paoka horde","paoka bergrausch seite"}},ca840f79={q="Was möchte Pao'ka Bergrausch?",a="Pao'ka möchte sicher aus Der Steilhang heraus und zurück zum Weißgipfelposten eskortiert werden, ohne den Zorn seines Mentors zu erregen. Er wagte sich in die Klippen, eifrig darauf bedacht, die wilden Wyvern zu studieren, aber nachdem er ein Nest gestört hatte und in die Flucht geschlagen wurde, besteht sein Hauptwunsch einfach darin, mit dem Leben davonzukommen und zu vermeiden, in Ungnade zu seinem Vater heimgeschickt zu werden.",al={"paoka ziel","was möchte paoka","paoka bergrausch motiv"}}},fp="20,303,23.650.0,28.172.0,40.202.0,30.169.0,39.178.1"}
P.entries["npc:parqual-fintallas"] = {fx={d8934933={q="Auf wessen Seite steht Parqual Fintallas?",a="Parqual ist mit den Verlassenen und der Horde verbündet und lebt friedlich innerhalb der Unterstadt. Im Gegensatz zu vielen seiner verbitterten Artgenossen hegt er wenig Groll gegen Reisende und teilt bereitwillig seine historischen Fachkenntnisse mit Wanderern der Horde, die nach Wissen suchen.",al={"wem dient parqual","fraktion parqual","ist parqual horde"}},["03c3b7bf"]={q="Warum ist Parqual Fintallas hier im Das Apothekarium?",a="Parqual hat sein Zuhause im Das Apothekarium der Unterstadt, umgeben von Forschern und Gelehrten. Obwohl er von dunkleren alchemistischen Arbeiten umgeben ist, nutzt er die stillen Ecken der Stadt, um historische Aufzeichnungen zu studieren und zu bewahren, und dient als Informationsquelle für diejenigen, die verlorenes Wissen suchen.",al={"warum ist parqual hier","warum ist parqual in der unterstadt","was macht parqual im apothecarium"}}}}
P.entries["npc:pelturas-whitemoon"] = {n="Pelturas Weißmond",s="Pelturas Weißmond ist ein Nachtelfenvater aus Astranaar, dessen junge Tochter Relara von einer schrecklichen, verderbenden Krankheit befallen wurde. In seiner Verzweiflung arbeitet er eng mit dem örtlichen Kräuterkundigen Orendil Rundblatt und reisenden Champions der Allianz zusammen, um heilige Heilmittel aus der umliegenden Wildnis zu sammeln. Seine Quest zur Heilung von Relara führt Abenteurer in einige der ältesten heiligen Haine und Ruinen von Eschental.",h="Pelturas Weißmond ist ein Nachtelfenvater aus Astranaar, dessen junge Tochter Relara von einer schrecklichen...",kw={"eschental","astranaar","elunes träne","fallenskysee","mondstein","orendil rundblatt","pelturas","relara","die sternenstaubruinen","whitemoon"},ang={["class:Priest"]="Die Elune geweihten Reinigungsriten und heiligen Reagenzien zeigen die heilende Macht und die tiefe Verehrung, die die Schwesternschaft von Elune in die Kultur der Nachtelfen einbringt.",["faction:Alliance"]="Pelturas bei der Rettung seiner Tochter beizustehen, unterstreicht den Einsatz der Allianz zur Verteidigung und Unterstützung der Siedlungen der Kaldorei in Kalimdor.",["profession:Herbalism"]="Die Abfolge natürlicher Tränke, Umschläge und botanischer Tinkturen, die für Relara benötigt werden, verdeutlicht die enge Verbindung zwischen der Heilkunde der Kaldorei und traditionellem Kräuterwissen.",["race:NightElf"]="Pelturas' Kampf spiegelt die Verwundbarkeit einfacher Kaldorei-Familien wider, während uralte Haine der Verderbnis und regionalen Konflikten zum Opfer fallen."},sec={{t="Die Not eines Vaters in Astranaar",b="In den friedlichen Wipfeln von Astranaar führt Pelturas Weißmond das ruhige Leben, das für die im Wald lebenden Kaldorei typisch ist. Oft unternahm er Ausflüge mit seiner jungen Tochter Relara, um schimmernde Mondsteine am Himmelssturzsee zu sammeln. Als Relara jedoch lebensgefährlich an einem mysteriösen Leiden erkrankt, bricht seine ruhige Welt in panischer Verzweiflung zusammen. Astranaar wird an vielen Fronten belagert, doch für Pelturas zählt im großen Wald nichts mehr, als das Leben seines Kindes zu retten."},{t="Uralte Heilmittel und verdorbene Haine",b="Gewöhnliche Kräuterheilmittel vermögen es nicht, Relaras Zustand zu bessern, weshalb sich Pelturas an den Kräuterkundigen Orendil Rundblatt wendet. Die Behandlung der Krankheit erfordert seltene und heilige Reagenzien, die mit dem Land und der Mondgöttin verbunden sind – darunter eine Elunes Träne und schimmernder Sternenstaub aus uralten Ruinen der Kaldorei, um ihr brennendes Fieber zu senken. Jeder Schritt hält den Tod nur knapp auf Abstand und verdeutlicht, wie tief die Verderbnis, die sich durch den Boden und die Gewässer von Eschental frisst, die Bewohner bereits heimsucht."},{t="Der Himmelssturzsee",b="Um Relaras Lebenskraft vollständig wiederherzustellen, sucht Pelturas nach einem Mondstein des Shadethicket-Orakels am Himmelssturzsee. Der See, einst ein friedlicher Ort, an dem Vater und Tochter ungestört Steine sammelten, ist durch das gewaltsame Erscheinen verdorbener Moorbestien gefährlich geworden. Indem er den geborgenen Mondstein zu einem stärkenden Tee zermahlt, gelingt es Pelturas schließlich, die anhaltende Schwäche zu brechen und Relaras Gesundheit wiederherzustellen."}},faq={{q="Wer ist Pelturas Weißmond?",a="Pelturas Weißmond ist ein Nachtelf und Bewohner von Astranaar im zentralen Eschental. Er ist vor allem dafür bekannt, vorbeireisende Abenteurer der Allianz um Hilfe beim Sammeln heiliger Zutaten zu bitten, um seine schwer kranke Tochter Relara zu retten.",al={"pelturas","wer ist pelturas weißmond","pelturas astranaar"}},{q="Was fehlt seiner Tochter Relara?",a="Relara leidet an einer plötzlichen, bösartigen Krankheit, die schweres Fieber und tiefe Schwäche verursacht. Das Leiden scheint mit der unnatürlichen Verderbnis zusammenzuhängen, die sich in der Wildnis von Eschental ausbreitet; es widersteht herkömmlicher Medizin und erfordert heilige Reagenzien zur Reinigung.",al={"relara krankheit","warum ist relara krank","relara leiden"}},{q="Wer hilft Pelturas bei der Behandlung der Krankheit?",a="Pelturas sucht Rat bei Orendil Rundblatt, einem heilkundigen Nachtelfen vor Ort, der traditionelle Heilmittel der Kaldorei verordnet, darunter reinigende Steine und Kräuterumschläge.",al={"pelturas kräuterkundiger","wer hilft relara","orendil rundblatt pelturas"}},{q="Welche Reagenzien werden benötigt, um Relara zu heilen?",a="Die Rettung von Relara erfordert eine Reihe aufeinanderfolgender Behandlungen: zunächst einen Kräutertrank von Orendil, eine reinigende Elunes Träne, pulverisierten Sternenstaub aus uralten Ruinen gegen das brennende Fieber und einen Mondstein vom Himmelssturzsee, der als Tee aufgebrüht wird, um ihre Kräfte zu erneuern.",al={"heilmittel reagenzien pelturas","relara heilungszutaten","was heilt relara"}},{q="Warum ist der Himmelssturzsee für Pelturas von Bedeutung?",a="Der Himmelssturzsee war ein Ort, an dem Pelturas und Relara früher Zeit miteinander verbrachten, um Mondsteine zu sammeln. Vor Kurzem wurde der See jedoch von feindseligen Moorbestien des Shadethickets überrannt, weshalb Pelturas Abenteurer bitten muss, den für die Genesung seiner Tochter benötigten Mondstein zu beschaffen.",al={"fallenskysee pelturas","mondstein fallenskysee"}},{q="Ist Pelturas ein Mitglied des Zirkels des Cenarius oder der Schildwachen?",a="Nein. Pelturas ist ein ziviler Einwohner von Astranaar und repräsentiert die einfachen Kaldorei-Familien, die in Eschental leben und unter den vordringenden Gefahren des Waldes leiden.",al={"ist pelturas eine schildwache","pelturas fraktionsrolle"}}},fx={["6580d64d"]={q="Auf wessen Seite steht Pelturas Weißmond?",a="Pelturas ist den Nachtelfen von Darnassus treu ergeben und steht fest zur Allianz. Da er in Astranaar lebt, verlässt er sich auf den Schutz seiner kaldoreiischen Mitbürger und heißt jeden Reisenden der Allianz willkommen, der bereit ist, seiner Familie in ihrer Stunde der Not zu helfen.",al={"fraktion pelturas weißmond","ist pelturas allianz","pelturas loyalität"}},["806ac345"]={q="Was will Pelturas Weißmond?",a="Mehr als alles andere will Pelturas seine geliebte Tochter Relara vor der mysteriösen Krankheit retten, die sie befallen hat. Er ist verzweifelt auf der Suche nach wirkungsvollen, wiederherstellenden Reagenzien – von heiligen Tränen bis hin zu altem Sternenstaub – in der Hoffnung, ein Heilmittel zu brauen, das endlich ihr Fieber bricht und ihre Vitalität wiederherstellt.",al={"was will pelturas","ziel pelturas weißmond","was versucht pelturas zu tun"}},["8d08bbb7"]={q="Warum ist Pelturas Weißmond in Astranaar?",a="Pelturas hat sein Zuhause in Astranaar, dem Herzen der Nachtelfensiedlung im Eschental. Während er früher mit seiner Tochter durch die nahegelegenen Wälder und Küsten wie den Himmelssturzsee streifte, bleibt er nun in der Sicherheit der Stadt, um ihren sich verschlechternden Zustand zu pflegen.",al={"warum ist pelturas in astranaar","warum ist pelturas hier","wo lebt pelturas"}},["3f413488"]={q="Zu wem hat Pelturas Weißmond Verbindungen?",a="Pelturas' Leben dreht sich um seine kleine Tochter Relara, für deren Schutz er unermüdlich kämpft. Bei seinen Bemühungen, sie zu heilen, arbeitet er eng mit Orendil Rundblatt zusammen, einem lokalen Nachtelfen, der in medizinischen Heilmitteln bewandert ist und ihn zu möglichen Heilungen führt.",al={"familie pelturas weißmond","mit wem ist pelturas verwandt","pelturas tochter"}}},fp="18,409,30.472.0,34.481.1,15.414.1,26.217.0,40.252.0,38.173.0,40.257.0,47.274.0,61.174.0"}
P.entries["npc:pilot-bellowfiz"] = {fx={["8ff6759c"]={q="Auf wessen Seite steht Pilot Bellfiz?",a="Bellfiz dient dem Königreich Eisenschmiede und der Großen Allianz als aktiver Fahrer in der Belagerungsbrigade von Eisenschmiede. Seine Loyalität gilt fest König Magni Bronzebart und den Zwergen-Verteidigungstruppen, die Dun Morogh beschützen.",al={"fraktion pilot bellfiz","wem dient bellfiz","ist bellfiz allianz"}},["53346562"]={q="Warum ist Pilot Bellfiz hier bei Stahlrosts Depot?",a="Stahlrosts Depot dient als Bereitstellungsraum und Testgelände für die schweren Panzerfahrzeuge von Eisenschmiede. Bellfiz ist hier stationiert, um seine Belagerungsmaschine gemeinsam mit anderen Mechanikern und Fahrern zu tunen, zu testen und zu bestücken, bevor er in den Schnee ausrückt.",al={"warum ist bellfiz bei stahlrosts depot","warum ist pilot bellfiz in dun morogh","bellfiz zweck dun morogh"}}}}
